  "description": "Sistema de conferência e ajustes de vendas para consolidar dados de comissão, DRE e histórico mensal através da importação de planilhas oficiais."
}

export interface Pedido {
  id: string; // Nº Pedido MU
  data: string;
  canal: string;
  vendedor: string;
  total: number;
  margemOriginal: number;
  credito: number;
  debito: number;
  margemAjustada: number;
  confirmado: boolean;
}

export interface MesConferencia {
  mesReferencia: string;
  pedidos: Pedido[];
}

export type SortDirection = 'asc' | 'desc' | null;

export interface SortConfig {
  key: keyof Pedido;
  direction: SortDirection;
}

import { MesConferencia } from '../types';

const STORAGE_KEY = 'abc_gestao_vendas_data';

export const storageService = {
  saveData: (data: MesConferencia) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  },
  getData: (): MesConferencia | null => {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : null;
  },
  clearData: () => {
    localStorage.removeItem(STORAGE_KEY);
  }
};

