export interface Pedido {
  id: string; // Nº Pedido MU
  data: string;
  canal: string;
  vendedor: string;
  mkt: number;
  cac: number;
  total: number;
  margemOriginal: number;
  credito: number;
  debito: number;
  margemAjustada: number;
  confirmado: boolean;
}

export interface MesConferencia {
  mesReferencia: string;
  pedidos: Pedido[];
}

export type SortDirection = 'asc' | 'desc' | null;

export interface SortConfig {
  key: keyof Pedido;
  direction: SortDirection;
}

import React, { useState } from 'react';
import * as XLSX from 'xlsx';
import { Pedido, MesConferencia } from '../types';
import { OrderTable } from '../components/OrderTable';
import { Upload, FileUp, Trash2, AlertCircle } from 'lucide-react';
import { storageService } from '../services/storageService';

export const ConferenciaPage: React.FC = () => {
  const [data, setData] = useState<MesConferencia | null>(storageService.getData());
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const toNumber = (val: any): number => {
    if (!val) return 0;
    if (typeof val === 'number') return val;
    const cleaned = String(val).replace(/\./g, '').replace(',', '.').replace(/[R$\s]/g, '');
    const n = parseFloat(cleaned);
    return isNaN(n) ? 0 : n;
  };

  const excelDateToBR = (serial: any): string => {
    if (!serial) return '';
    if (typeof serial === 'string') return serial;
    try {
      const date = new Date(Math.round((serial - 25569) * 86400 * 1000));
      return date.toLocaleDateString('pt-BR');
    } catch {
      return String(serial);
    }
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json(worksheet, { defval: "" }) as any[];

        const mapa: Record<string, Pedido> = {};

        for (let i = 0; i < rows.length; i++) {
          const r = rows[i];
          const numPedido = String(r["Nº Pedido MU"] || "").trim();
          if (!numPedido) continue;

          let canal = r["Canal Venda"];
          // Logic from legacy JS: if canal is missing, check next row
          if (!canal && rows[i + 1]) canal = rows[i + 1]["Canal Venda"] || "";

          mapa[numPedido] = {
            id: numPedido,
            data: r["Data Faturamento"] ? excelDateToBR(r["Data Faturamento"]) : "",
            canal: String(canal || ""),
            vendedor: String(r["Vendedor"] || ""),
            mkt: 0,
            cac: 0,
            total: 0,
            margemOriginal: 0,
            credito: 0,
            debito: 0,
            margemAjustada: 0,
            confirmado: false
          };

          // Aggregation logic for multi-line orders
          let j = i;
          while (rows[j] && (j === i || !rows[j]["Nº Pedido MU"])) {
            const linha = rows[j];
            mapa[numPedido].total += toNumber(linha["Total Pedido (R$)"]);
            mapa[numPedido].margemOriginal += toNumber(linha["Margem líq. c/ frete"]);

            if (!mapa[numPedido].mkt && linha["Mkt"]) {
              mapa[numPedido].mkt = toNumber(linha["Mkt"]);
            }
            if (!mapa[numPedido].cac && linha["CAC"]) {
              mapa[numPedido].cac = toNumber(linha["CAC"]);
            }
            j++;
          }
          // Initialize Margem Ajustada
          mapa[numPedido].margemAjustada = mapa[numPedido].margemOriginal;
          i = j - 1; // Skip the rows we just aggregated
        }

        const pedidos = Object.values(mapa);
        const newData: MesConferencia = {
          mesReferencia: new Date().toISOString().slice(0, 7),
          pedidos,
        };
        setData(newData);
        storageService.saveData(newData);
      } catch (err) {
        console.error(err);
        setError("Erro ao processar planilha. Verifique as colunas obrigatórias conforme o guia.");
      } finally {
        setLoading(false);
      }
    };

    reader.readAsBinaryString(file);
  };

  const updatePedido = (id: string, updates: Partial<Pedido>) => {
    if (!data) return;
    const newPedidos = data.pedidos.map((p) => {
      if (p.id === id) {
        const updated = { ...p, ...updates };
        // Rule: Margem Ajustada = Margem Original + Crédito - Débito
        updated.margemAjustada = updated.margemOriginal + (updated.credito || 0) - (updated.debito || 0);
        return updated;
      }
      return p;
    });
    const newData = { ...data, pedidos: newPedidos };
    setData(newData);
    storageService.saveData(newData);
  };

  const clearAll = () => {
    if (confirm("Tem certeza que deseja limpar todos os dados da conferência atual?")) {
      setData(null);
      storageService.clearData();
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Conferência de Vendas</h2>
          <p className="text-slate-500">Importe a planilha oficial e realize ajustes pontuais.</p>
        </div>

        <div className="flex items-center gap-2">
          {data && (
            <button
              onClick={clearAll}
              className="flex items-center gap-2 px-4 py-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors border border-red-100"
            >
              <Trash2 className="w-4 h-4" />
              Limpar Tudo
            </button>
          )}

          <label className="flex items-center gap-2 px-4 py-2 bg-orange-600 hover:bg-orange-700 text-white rounded-lg cursor-pointer transition-all shadow-sm">
            <FileUp className="w-4 h-4" />
            <span>{data ? 'Importar Nova Planilha' : 'Importar Planilha .XLSX'}</span>
            <input type="file" accept=".xlsx, .xls" className="hidden" onChange={handleFileUpload} />
          </label>
        </div>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg flex items-center gap-3">
          <AlertCircle className="w-5 h-5 flex-shrink-0" />
          <p>{error}</p>
        </div>
      )}

      {loading && (
        <div className="flex flex-col items-center justify-center py-20 text-slate-400">
          <div className="w-12 h-12 border-4 border-slate-200 border-t-orange-500 rounded-full animate-spin mb-4"></div>
          <p className="animate-pulse">Agregando dados da planilha por Pedido MU...</p>
        </div>
      )}

      {!loading && !data && (
        <div className="bg-white border-2 border-dashed border-slate-200 rounded-2xl py-24 flex flex-col items-center justify-center text-slate-400">
          <Upload className="w-16 h-16 mb-4 text-slate-200" />
          <p className="text-lg font-medium text-slate-600">Nenhuma planilha importada</p>
          <p className="text-sm">Clique no botão acima para carregar o arquivo oficial (.xlsx).</p>
        </div>
      )}

      {!loading && data && (
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
          <OrderTable data={data.pedidos} onUpdatePedido={updatePedido} />
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Pedido, SortConfig, SortDirection } from '../types';
import { ChevronUp, ChevronDown, Check } from 'lucide-react';

interface OrderTableProps {
  data: Pedido[];
  onUpdatePedido?: (id: string, updates: Partial<Pedido>) => void;
  readOnly?: boolean;
}

export const OrderTable: React.FC<OrderTableProps> = ({ data, onUpdatePedido, readOnly = false }) => {
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'id', direction: 'asc' });

  const handleSort = (key: keyof Pedido) => {
    let direction: SortDirection = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const sortedData = useMemo(() => {
    const sortableItems = [...data];
    if (sortConfig.direction !== null) {
      sortableItems.sort((a, b) => {
        const valA = a[sortConfig.key];
        const valB = b[sortConfig.key];

        if (typeof valA === 'string' && typeof valB === 'string') {
          return sortConfig.direction === 'asc' 
            ? valA.localeCompare(valB) 
            : valB.localeCompare(valA);
        }

        if (typeof valA === 'number' && typeof valB === 'number') {
          return sortConfig.direction === 'asc' ? valA - valB : valB - valA;
        }

        return 0;
      });
    }
    return sortableItems;
  }, [data, sortConfig]);

  const totals = useMemo(() => {
    return data.reduce(
      (acc, curr) => ({
        total: acc.total + curr.total,
        margemOriginal: acc.margemOriginal + curr.margemOriginal,
        margemAjustada: acc.margemAjustada + curr.margemAjustada,
      }),
      { total: 0, margemOriginal: 0, margemAjustada: 0 }
    );
  }, [data]);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  };

  const formatPercent = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'percent', minimumFractionDigits: 2 }).format(value / 100);
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full text-left text-sm border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200">
              {['id', 'data', 'canal', 'vendedor', 'total', 'margemOriginal', 'margemAjustada'].map((col) => (
                <th
                  key={col}
                  onClick={() => handleSort(col as keyof Pedido)}
                  className="px-4 py-3 font-semibold text-slate-700 cursor-pointer hover:bg-slate-100 transition-colors whitespace-nowrap"
                >
                  <div className="flex items-center gap-1">
                    {col === 'id' ? 'Pedido' : 
                     col === 'data' ? 'Data' :
                     col === 'canal' ? 'Canal' :
                     col === 'vendedor' ? 'Vendedor' :
                     col === 'total' ? 'Total Ajustado' :
                     col === 'margemOriginal' ? 'Margem Orig. (R$)' : 'Margem Ajust. (R$)'}
                    {sortConfig.key === col && (
                      sortConfig.direction === 'asc' ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />
                    )}
                  </div>
                </th>
              ))}
              {!readOnly && <th className="px-4 py-3 font-semibold text-slate-700">Crédito</th>}
              {!readOnly && <th className="px-4 py-3 font-semibold text-slate-700">Débito</th>}
              <th className="px-4 py-3 font-semibold text-slate-700 whitespace-nowrap">Margem Ajust. (%)</th>
              {!readOnly && <th className="px-4 py-3 font-semibold text-slate-700 w-10">Conf.</th>}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {sortedData.map((p) => {
              const margemPercent = p.total > 0 ? (p.margemAjustada / p.total) * 100 : 0;
              const hasAdjustments = (p.credito !== 0 && p.credito !== undefined) || (p.debito !== 0 && p.debito !== undefined);
              // Visual Rule: Yellow line if confirmed
              const rowBg = !readOnly && p.confirmado ? 'bg-yellow-50' : 'bg-white';

              return (
                <tr key={p.id} className={`${rowBg} hover:bg-slate-50 transition-colors`}>
                  <td className="px-4 py-3 font-bold text-slate-900">{p.id}</td>
                  <td className="px-4 py-3 text-slate-600 whitespace-nowrap">{p.data}</td>
                  <td className="px-4 py-3 text-slate-600">{p.canal}</td>
                  <td className="px-4 py-3 text-slate-600">{p.vendedor}</td>
                  <td className="px-4 py-3 text-slate-900 font-medium whitespace-nowrap">{formatCurrency(p.total)}</td>
                  <td className="px-4 py-3 text-slate-500 whitespace-nowrap">{formatCurrency(p.margemOriginal)}</td>
                  <td className="px-4 py-3 font-semibold text-slate-900 whitespace-nowrap">{formatCurrency(p.margemAjustada)}</td>
                  {!readOnly && (
                    <td className="px-2 py-2">
                      <input
                        type="number"
                        value={p.credito === 0 ? '' : p.credito}
                        onChange={(e) => onUpdatePedido?.(p.id, { credito: parseFloat(e.target.value) || 0 })}
                        className="w-24 px-2 py-1 border border-slate-200 rounded focus:ring-1 focus:ring-orange-500 outline-none text-right"
                        placeholder="0,00"
                      />
                    </td>
                  )}
                  {!readOnly && (
                    <td className="px-2 py-2">
                      <input
                        type="number"
                        value={p.debito === 0 ? '' : p.debito}
                        onChange={(e) => onUpdatePedido?.(p.id, { debito: parseFloat(e.target.value) || 0 })}
                        className="w-24 px-2 py-1 border border-slate-200 rounded focus:ring-1 focus:ring-orange-500 outline-none text-right"
                        placeholder="0,00"
                      />
                    </td>
                  )}
                  <td className={`px-4 py-3 font-medium ${margemPercent < 10 ? 'text-red-600' : 'text-emerald-600'}`}>
                    {formatPercent(margemPercent)}
                  </td>
                  {!readOnly && (
                    <td className="px-4 py-3 text-center">
                      {hasAdjustments && (
                        <button
                          onClick={() => onUpdatePedido?.(p.id, { confirmado: !p.confirmado })}
                          className={`p-1.5 rounded-full transition-all ${p.confirmado ? 'bg-orange-500 text-white shadow-sm' : 'bg-slate-100 text-slate-400 hover:text-slate-600'}`}
                        >
                          <Check className="w-4 h-4" />
                        </button>
                      )}
                    </td>
                  )}
                </tr>
              );
            })}
          </tbody>
          <tfoot className="bg-slate-900 text-white border-t border-slate-700">
            <tr>
              <td colSpan={4} className="px-4 py-5 font-bold text-right uppercase tracking-wider text-xs">Totalizadores do Mês:</td>
              <td className="px-4 py-5 font-bold text-lg whitespace-nowrap">{formatCurrency(totals.total)}</td>
              <td className="px-4 py-5 font-bold text-slate-400 whitespace-nowrap italic">{formatCurrency(totals.margemOriginal)}</td>
              <td className="px-4 py-5 font-bold text-xl text-orange-400 whitespace-nowrap">{formatCurrency(totals.margemAjustada)}</td>
              {!readOnly ? <td colSpan={4}></td> : <td colSpan={2}></td>}
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import * as XLSX from 'xlsx';
import { Pedido, MesConferencia } from '../types';
import { OrderTable } from '../components/OrderTable';
import { Upload, FileUp, Trash2, AlertCircle } from 'lucide-react';
import { storageService } from '../services/storageService';

export const ConferenciaPage: React.FC = () => {
  const [data, setData] = useState<MesConferencia | null>(storageService.getData());
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const toNumber = (val: any): number => {
    if (val === null || val === undefined || val === '') return 0;
    if (typeof val === 'number') return val;
    // Handle currency formats like "R$ 1.234,56" or "- R$ 10,00"
    const cleaned = String(val)
      .replace(/R\$/g, '')
      .replace(/\./g, '')
      .replace(',', '.')
      .trim();
    const n = parseFloat(cleaned);
    return isNaN(n) ? 0 : n;
  };

  const isTotalRow = (row: any): boolean => {
    return Object.values(row).some(val => 
      String(val).toUpperCase().includes('TOTAL') || 
      String(val).toUpperCase() === 'TOTAL'
    );
  };

  const excelDateToBR = (serial: any): string => {
    if (!serial) return '';
    if (typeof serial === 'string') return serial;
    try {
      // Excel date epoch
      const date = new Date(Math.round((serial - 25569) * 86400 * 1000));
      return date.toLocaleDateString('pt-BR');
    } catch {
      return String(serial);
    }
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json(worksheet, { defval: "" }) as any[];

        const mapa: Record<string, Pedido> = {};

        for (let i = 0; i < rows.length; i++) {
          const r = rows[i];
          const numPedido = String(r["Nº Pedido MU"] || r["Pedido"] || "").trim();

          if (!numPedido || isTotalRow(r)) continue;

          let canal = r["Canal Venda"] || r["Canal"] || "";
          if (!canal && rows[i + 1]) {
            canal = rows[i + 1]["Canal Venda"] || rows[i + 1]["Canal"] || "";
          }

          if (!mapa[numPedido]) {
            mapa[numPedido] = {
              id: numPedido,
              data: r["Data Faturamento"] || r["Data"] ? excelDateToBR(r["Data Faturamento"] || r["Data"]) : "",
              canal: String(canal),
              vendedor: String(r["Vendedor"] || ""),
              mkt: 0,
              cac: 0,
              total: 0,
              margemOriginal: 0,
              credito: 0,
              debito: 0,
              margemAjustada: 0,
              confirmado: false
            };
          }

          // Sum only if not a summary row to avoid double counting
          // Multi-row handling: process this row and any subsequent rows without an ID that aren't "TOTAL" rows
          let j = i;
          while (rows[j] && (j === i || (!rows[j]["Nº Pedido MU"] && !rows[j]["Pedido"]))) {
            const linha = rows[j];

            // Skip summary rows within the group
            if (!isTotalRow(linha)) {
              mapa[numPedido].total += toNumber(linha["Total Pedido (R$)"] || linha["Valor Total"] || linha["Total"]);

              // Priority for the final margin column seen in screenshots
              const margemVal = toNumber(
                linha["Margem final com frete e extras (R$)"] || 
                linha["Margem líq. c/ frete"] || 
                linha["Margem R$"] || 
                linha["Margem"]
              );
              mapa[numPedido].margemOriginal += margemVal;

              if (!mapa[numPedido].mkt && linha["Mkt"]) mapa[numPedido].mkt = toNumber(linha["Mkt"]);
              if (!mapa[numPedido].cac && linha["CAC"]) mapa[numPedido].cac = toNumber(linha["CAC"]);
            }
            j++;
          }

          mapa[numPedido].margemAjustada = mapa[numPedido].margemOriginal;
          i = j - 1;
        }

        const pedidos = Object.values(mapa);
        const newData: MesConferencia = {
          mesReferencia: new Date().toISOString().slice(0, 7),
          pedidos,
        };
        setData(newData);
        storageService.saveData(newData);
      } catch (err) {
        console.error("Spreadsheet processing error:", err);
        setError("Erro ao processar planilha. Verifique se o formato segue o padrão oficial da ABC.");
      } finally {
        setLoading(false);
      }
    };

    reader.readAsBinaryString(file);
  };

  const updatePedido = (id: string, updates: Partial<Pedido>) => {
    if (!data) return;
    const newPedidos = data.pedidos.map((p) => {
      if (p.id === id) {
        const updated = { ...p, ...updates };
        updated.margemAjustada = updated.margemOriginal + (updated.credito || 0) - (updated.debito || 0);
        return updated;
      }
      return p;
    });
    const newData = { ...data, pedidos: newPedidos };
    setData(newData);
    storageService.saveData(newData);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 tracking-tight">Conferência de Vendas</h2>
          <p className="text-slate-500 text-sm">Auditoria de margens e aplicação de ajustes financeiros.</p>
        </div>

        <div className="flex items-center gap-2">
          {data && (
            <button
              onClick={() => { if(confirm("Limpar dados?")) { setData(null); storageService.clearData(); } }}
              className="px-4 py-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors border border-red-100 text-sm font-medium"
            >
              <Trash2 className="w-4 h-4 inline mr-2" />
              Limpar
            </button>
          )}

          <label className="flex items-center gap-2 px-5 py-2.5 bg-orange-600 hover:bg-orange-700 text-white rounded-lg cursor-pointer transition-all shadow-md active:scale-95 font-semibold text-sm">
            <FileUp className="w-4 h-4" />
            <span>{data ? 'Nova Importação' : 'Importar Planilha .XLSX'}</span>
            <input type="file" accept=".xlsx, .xls" className="hidden" onChange={handleFileUpload} />
          </label>
        </div>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg flex items-center gap-3 animate-pulse">
          <AlertCircle className="w-5 h-5 flex-shrink-0" />
          <p className="font-medium">{error}</p>
        </div>
      )}

      {loading && (
        <div className="flex flex-col items-center justify-center py-32 text-slate-400">
          <div className="w-10 h-10 border-3 border-slate-200 border-t-orange-500 rounded-full animate-spin mb-4"></div>
          <p className="text-sm font-medium">Validando e agregando pedidos...</p>
        </div>
      )}

      {!loading && !data && (
        <div className="bg-white border-2 border-dashed border-slate-200 rounded-3xl py-32 flex flex-col items-center justify-center text-slate-400">
          <div className="bg-slate-50 p-6 rounded-full mb-6">
            <Upload className="w-12 h-12 text-slate-300" />
          </div>
          <p className="text-xl font-bold text-slate-700">Pronto para Auditar</p>
          <p className="text-slate-400 text-sm max-w-xs text-center mt-2">Arraste a planilha ou clique no botão de importação acima para iniciar.</p>
        </div>
      )}

      {!loading && data && (
        <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
          <OrderTable data={data.pedidos} onUpdatePedido={updatePedido} />
        </div>
      )}
    </div>
  );
};

