              {!readOnly && <th className="px-5 py-4 font-bold text-slate-300 uppercase text-[11px] tracking-wider w-12 text-center">Status</th>}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {sortedData.map((p) => {
              const margemPercent = p.total > 0 ? (p.margemAjustada / p.total) * 100 : 0;
              const hasAdjustments = (p.credito !== 0 && p.credito !== undefined) || (p.debito !== 0 && p.debito !== undefined);
              const rowBg = !readOnly && p.confirmado ? 'bg-amber-50/50' : 'bg-white';

