                  <td className="px-5 py-4 text-slate-900 font-bold whitespace-nowrap">{formatCurrency(p.total)}</td>
                  <td className="px-5 py-4 text-slate-400 whitespace-nowrap italic">{formatCurrency(p.margemOriginal)}</td>
                  <td className="px-5 py-4 font-extrabold text-slate-900 whitespace-nowrap border-l border-slate-50 bg-slate-50/10">{formatCurrency(p.margemAjustada)}</td>
                  {!readOnly && (
                    <td className="px-3 py-2">
                      <input
                        type="number"
                        value={p.credito === 0 ? '' : p.credito}
                        onChange={(e) => onUpdatePedido?.(p.id, { credito: parseFloat(e.target.value) || 0 })}
                        className="w-28 px-3 py-1.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 outline-none text-right font-medium transition-all"
                        placeholder="0,00"
