                    </td>
                  )}
                  {!readOnly && (
                    <td className="px-3 py-2">
                      <input
                        type="number"
                        value={p.debito === 0 ? '' : p.debito}
                        onChange={(e) => onUpdatePedido?.(p.id, { debito: parseFloat(e.target.value) || 0 })}
                        className="w-28 px-3 py-1.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 outline-none text-right font-medium transition-all"
                        placeholder="0,00"
                      />
                    </td>
                  )}
                  <td className={`px-5 py-4 font-black text-right whitespace-nowrap ${margemPercent < 15 ? 'text-rose-600' : 'text-emerald-600'}`}>
