                        >
                          <Check className="w-4 h-4 stroke-[3px]" />
                        </button>
                      )}
                    </td>
                  )}
                </tr>
              );
            })}
          </tbody>
          <tfoot className="bg-slate-900 text-white shadow-[0_-4px_10px_rgba(0,0,0,0.1)] sticky bottom-0">
            <tr>
              <td colSpan={4} className="px-5 py-6 font-black text-right uppercase tracking-[0.2em] text-[10px] text-slate-400">Totais Consolidados:</td>
              <td className="px-5 py-6 font-black text-xl whitespace-nowrap">{formatCurrency(totals.total)}</td>
              <td className="px-5 py-6 font-bold text-slate-500 whitespace-nowrap italic line-through decoration-slate-700">{formatCurrency(totals.margemOriginal)}</td>
              <td className="px-5 py-6 font-black text-2xl text-orange-400 whitespace-nowrap bg-slate-800/50">{formatCurrency(totals.margemAjustada)}</td>
              {!readOnly ? <td colSpan={2}></td> : null}
              <td className="px-5 py-6 font-black text-right text-lg text-emerald-400">
                {formatPercent(totals.total > 0 ? (totals.margemAjustada / totals.total) * 100 : 0)}
              </td>
              {!readOnly ? <td className="w-12"></td> : null}
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
};

