import React, { useState } from 'react';
import * as XLSX from 'xlsx';
import { Pedido, MesConferencia } from '../types';
import { OrderTable } from '../components/OrderTable';
import { Upload, FileUp, Trash2, AlertCircle } from 'lucide-react';
import { storageService } from '../services/storageService';

export const ConferenciaPage: React.FC = () => {
  const [data, setData] = useState<MesConferencia | null>(storageService.getData());
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const toNumber = (val: any): number => {
    if (val === null || val === undefined || val === '') return 0;
    if (typeof val === 'number') return val;
    const cleaned = String(val)
      .replace(/R\$/g, '')
      .replace(/\./g, '')
      .replace(',', '.')
      .replace(/\s/g, '')
      .trim();
    const n = parseFloat(cleaned);
    return isNaN(n) ? 0 : n;
  };

  const isTotalRow = (row: any): boolean => {
    return Object.values(row).some(val => {
      const s = String(val).toUpperCase();
      return s.includes('TOTAL') || s === 'TOTAL';
    });
  };

  const excelDateToBR = (serial: any): string => {
    if (!serial) return '';
    if (typeof serial === 'string') return serial;
    try {
      const date = new Date(Math.round((serial - 25569) * 86400 * 1000));
      return date.toLocaleDateString('pt-BR');
    } catch {
      return String(serial);
    }
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json(worksheet, { defval: "" }) as any[];

        const mapa: Record<string, Pedido> = {};

        for (let i = 0; i < rows.length; i++) {
          const r = rows[i];
          const numPedido = String(r["Nº Pedido MU"] || r["Pedido"] || "").trim();

          if (!numPedido || isTotalRow(r)) continue;

          // Group all rows belonging to this order
          const orderRows = [];
          let j = i;
          while (rows[j] && (j === i || (!String(rows[j]["Nº Pedido MU"] || "").trim() && !String(rows[j]["Pedido"] || "").trim()))) {
            orderRows.push(rows[j]);
            j++;
          }

          // Search for a 'TOTAL' summary row in the group to avoid double counting items + total
          const totalRow = orderRows.find(row => isTotalRow(row));

          let pedidoTotal = 0;
          let pedidoMargem = 0;
          let mkt = 0;
          let cac = 0;

          if (totalRow) {
            // Priority 1: Use the summary row values directly
            pedidoTotal = toNumber(totalRow["Total Pedido (R$)"] || totalRow["Valor Total"] || totalRow["Total"]);
            pedidoMargem = toNumber(
              totalRow["Margem final com frete e extras (R$)"] || 
              totalRow["Margem líq. c/ frete"] || 
              totalRow["Margem R$"] || 
              totalRow["Margem"]
            );
          } else {
            // Priority 2: Sum all rows if no summary row exists
            orderRows.forEach(row => {
              pedidoTotal += toNumber(row["Total Pedido (R$)"] || row["Valor Total"] || row["Total"]);
              pedidoMargem += toNumber(
                row["Margem final com frete e extras (R$)"] || 
                row["Margem líq. c/ frete"] || 
                row["Margem R$"] || 
                row["Margem"]
              );
            });
          }

          // Metadata extraction from the first row of the group
          const firstRow = orderRows[0];
          let canal = firstRow["Canal Venda"] || firstRow["Canal"] || "";
          if (!canal && orderRows[1]) canal = orderRows[1]["Canal Venda"] || orderRows[1]["Canal"] || "";

          mapa[numPedido] = {
            id: numPedido,
            data: firstRow["Data Faturamento"] || firstRow["Data"] ? excelDateToBR(firstRow["Data Faturamento"] || firstRow["Data"]) : "",
            canal: String(canal),
            vendedor: String(firstRow["Vendedor"] || ""),
            mkt: toNumber(firstRow["Mkt"]),
            cac: toNumber(firstRow["CAC"]),
            total: pedidoTotal,
            margemOriginal: pedidoMargem,
            credito: 0,
            debito: 0,
            margemAjustada: pedidoMargem,
            confirmado: false
          };

          i = j - 1;
        }

        const pedidos = Object.values(mapa);
        const newData: MesConferencia = {
          mesReferencia: new Date().toISOString().slice(0, 7),
          pedidos,
        };
        setData(newData);
        storageService.saveData(newData);
      } catch (err) {
        console.error("Spreadsheet processing error:", err);
        setError("Erro ao processar planilha. Verifique se o formato segue o padrão oficial.");
      } finally {
        setLoading(false);
      }
    };

    reader.readAsBinaryString(file);
  };

  const updatePedido = (id: string, updates: Partial<Pedido>) => {
    if (!data) return;
    const newPedidos = data.pedidos.map((p) => {
      if (p.id === id) {
        const updated = { ...p, ...updates };
        updated.margemAjustada = updated.margemOriginal + (updated.credito || 0) - (updated.debito || 0);
        return updated;
      }
      return p;
    });
    const newData = { ...data, pedidos: newPedidos };
    setData(newData);
    storageService.saveData(newData);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">Conferência de Vendas</h2>
          <p className="text-slate-500 text-sm font-medium">Auditoria financeira e ajustes manuais de produção.</p>
        </div>

        <div className="flex items-center gap-3">
          {data && (
            <button
              onClick={() => { if(confirm("Deseja apagar todos os dados atuais?")) { setData(null); storageService.clearData(); } }}
              className="px-4 py-2.5 text-red-600 hover:bg-red-50 rounded-xl transition-all border border-red-100 text-xs font-bold uppercase tracking-wider"
            >
              <Trash2 className="w-4 h-4 inline mr-2" />
              Resetar
            </button>
          )}

          <label className="flex items-center gap-2 px-6 py-3 bg-orange-600 hover:bg-orange-700 text-white rounded-xl cursor-pointer transition-all shadow-lg active:scale-95 font-bold text-sm">
            <FileUp className="w-5 h-5" />
            <span>{data ? 'Nova Planilha' : 'Carregar Planilha .XLSX'}</span>
            <input type="file" accept=".xlsx, .xls" className="hidden" onChange={handleFileUpload} />
          </label>
        </div>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 px-5 py-4 rounded-xl flex items-center gap-3 shadow-sm">
          <AlertCircle className="w-6 h-6 flex-shrink-0" />
          <p className="font-bold">{error}</p>
        </div>
      )}

      {loading && (
