export interface Pedido {
  id: string; // Nº Pedido MU
  data: string;
  canal: string;
  vendedor: string;
  mkt: number;
  cac: number;
  total: number;
  margemOriginal: number;
  margemOriginalPct: number; // New: To store percentage from spreadsheet
  credito: number;
  debito: number;
  margemAjustada: number;
  confirmado: boolean;
}

export interface MesConferencia {
  mesReferencia: string;
  pedidos: Pedido[];
}

export type SortDirection = 'asc' | 'desc' | null;

export interface SortConfig {
  key: keyof Pedido;
