import React, { useState } from 'react';
import * as XLSX from 'xlsx';
import { Pedido, MesConferencia } from '../types';
import { OrderTable } from '../components/OrderTable';
import { Upload, FileUp, Trash2, AlertCircle } from 'lucide-react';
import { storageService } from '../services/storageService';

export const ConferenciaPage: React.FC = () => {
  const [data, setData] = useState<MesConferencia | null>(storageService.getData());
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const toNumber = (val: any): number => {
    if (val === null || val === undefined || val === '' || val === '-') return 0;
    if (typeof val === 'number') return val;
    const cleaned = String(val)
      .replace(/R\$/g, '')
      .replace(/\./g, '')
      .replace(',', '.')
      .replace(/\s/g, '')
      .trim();
    const n = parseFloat(cleaned);
    return isNaN(n) ? 0 : n;
  };

  const isTotalRow = (row: any): boolean => {
    return Object.values(row).some(val => {
      const s = String(val).toUpperCase();
      return s === 'TOTAL' || s.includes('TOTAL');
    });
  };

  const excelDateToBR = (serial: any): string => {
    if (!serial) return '';
    if (typeof serial === 'string') return serial;
    try {
      const date = new Date(Math.round((serial - 25569) * 86400 * 1000));
      return date.toLocaleDateString('pt-BR');
    } catch {
      return String(serial);
    }
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json(worksheet, { defval: "" }) as any[];

        const mapa: Record<string, Pedido> = {};

        for (let i = 0; i < rows.length; i++) {
          const r = rows[i];
          const numPedido = String(r["Nº Pedido MU"] || "").trim();

          if (!numPedido || isTotalRow(r)) continue;

          // Aggregation logic: find all rows for this specific Pedido MU block
          const groupRows: any[] = [];
          let j = i;
          while (rows[j] && (j === i || !String(rows[j]["Nº Pedido MU"] || "").trim())) {
            groupRows.push(rows[j]);
            j++;
          }

          // Search for a 'TOTAL' summary row in the group to avoid double counting items + total
          const summaryRow = groupRows.find(row => isTotalRow(row));

          let finalTotal = 0;
          let finalMargem = 0;
          let originalPct = 0;

          // Headers based on user's screenshots and provided rules
          const H_TOTAL = "Total Pedido (R$)";
          const H_MARGEM_RS = "Margem final com frete e extras (R$)";
          const H_MARGEM_PCT = "Margem sobre produto + frete e extras (%)";

          if (summaryRow) {
            // Priority: Use the summary row values directly to avoid value divergence
            finalTotal = toNumber(summaryRow[H_TOTAL]);
            finalMargem = toNumber(summaryRow[H_MARGEM_RS]);
            originalPct = toNumber(summaryRow[H_MARGEM_PCT]);
          } else {
            // Sum individual rows if no summary row exists (fallback)
            groupRows.forEach(row => {
              finalTotal += toNumber(row[H_TOTAL]);
              finalMargem += toNumber(row[H_MARGEM_RS]);
              // Take percentage from the first valid row if summing
              if (originalPct === 0) originalPct = toNumber(row[H_MARGEM_PCT]);
            });
          }

          const firstRow = groupRows[0];
          let canal = firstRow["Canal Venda"] || "";
          if (!canal && groupRows[1]) canal = groupRows[1]["Canal Venda"] || "";

          mapa[numPedido] = {
            id: numPedido,
            data: firstRow["Data Faturamento"] ? excelDateToBR(firstRow["Data Faturamento"]) : "",
            canal: String(canal),
            vendedor: String(firstRow["Vendedor"] || ""),
            mkt: toNumber(firstRow["Mkt"]),
            cac: toNumber(firstRow["CAC"]),
            total: finalTotal,
            margemOriginal: finalMargem,
            margemOriginalPct: originalPct,
            credito: 0,
            debito: 0,
            margemAjustada: finalMargem,
            confirmado: false
          };

          i = j - 1; 
        }

        const pedidos = Object.values(mapa);
        const newData: MesConferencia = {
          mesReferencia: new Date().toISOString().slice(0, 7),
          pedidos,
        };
        setData(newData);
        storageService.saveData(newData);
      } catch (err) {
        console.error("Aggregation Error:", err);
        setError("Erro ao ler planilha. Use o arquivo oficial com as colunas: 'Nº Pedido MU', 'Total Pedido (R$)', 'Margem final com frete e extras (R$)' e 'Canal Venda'.");
      } finally {
        setLoading(false);
      }
    };

    reader.readAsBinaryString(file);
  };

  const updatePedido = (id: string, updates: Partial<Pedido>) => {
    if (!data) return;
    const newPedidos = data.pedidos.map((p) => {
      if (p.id === id) {
        const updated = { ...p, ...updates };
        updated.margemAjustada = updated.margemOriginal + (updated.credito || 0) - (updated.debito || 0);
        return updated;
      }
      return p;
    });
    const newData = { ...data, pedidos: newPedidos };
    setData(newData);
    storageService.saveData(newData);
  };

  return (
    <div className="space-y-8">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter">Conferência de Vendas</h2>
          <p className="text-slate-500 font-medium mt-1">Sincronização de margens e auditoria de produção.</p>
        </div>

        <div className="flex items-center gap-4">
          {data && (
            <button
              onClick={() => { if(confirm("Deseja apagar todos os dados da auditoria atual?")) { setData(null); storageService.clearData(); } }}
              className="px-5 py-3 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all text-xs font-black uppercase tracking-widest border border-slate-100"
            >
              Resetar Dados
            </button>
          )}

          <label className="flex items-center gap-3 px-8 py-4 bg-orange-600 hover:bg-orange-700 text-white rounded-2xl cursor-pointer transition-all shadow-xl shadow-orange-200 active:scale-95 font-black text-sm uppercase tracking-wider">
            <FileUp className="w-5 h-5" />
            <span>{data ? 'Trocar Planilha' : 'Carregar Relatório .XLSX'}</span>
            <input type="file" accept=".xlsx, .xls" className="hidden" onChange={handleFileUpload} />
          </label>
        </div>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 p-6 rounded-3xl flex items-center gap-4 shadow-sm">
          <AlertCircle className="w-8 h-8 flex-shrink-0 text-red-500" />
          <div>
            <p className="font-black uppercase text-xs tracking-widest mb-1">Divergência de Formato</p>
            <p className="font-medium text-sm leading-relaxed">{error}</p>
          </div>
        </div>
      )}

      {loading && (
        <div className="flex flex-col items-center justify-center py-48 text-slate-400">
          <div className="w-16 h-16 border-4 border-slate-100 border-t-orange-500 rounded-full animate-spin"></div>
          <p className="text-xs font-black tracking-[0.3em] uppercase mt-8 animate-pulse text-slate-500">Agregando Pedidos e Validando Totais...</p>
        </div>
      )}

      {!loading && !data && (
        <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-48 flex flex-col items-center justify-center text-slate-400 shadow-inner group">
          <div className="bg-slate-50 p-10 rounded-full mb-8 transition-transform group-hover:scale-110 duration-500">
            <Upload className="w-20 h-20 text-slate-200" />
          </div>
          <p className="text-3xl font-black text-slate-800 tracking-tight">Pronto para Importação</p>
          <p className="text-slate-400 text-sm mt-4 font-bold uppercase tracking-widest">Selecione o relatório oficial exportado</p>
        </div>
      )}

      {!loading && data && (
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
          <OrderTable data={data.pedidos} onUpdatePedido={updatePedido} />
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Pedido, SortConfig, SortDirection } from '../types';
import { ChevronUp, ChevronDown, Check } from 'lucide-react';

interface OrderTableProps {
  data: Pedido[];
  onUpdatePedido?: (id: string, updates: Partial<Pedido>) => void;
  readOnly?: boolean;
}

export const OrderTable: React.FC<OrderTableProps> = ({ data, onUpdatePedido, readOnly = false }) => {
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'id', direction: 'asc' });

  const handleSort = (key: keyof Pedido) => {
    let direction: SortDirection = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const sortedData = useMemo(() => {
    const sortableItems = [...data];
    if (sortConfig.direction !== null) {
      sortableItems.sort((a, b) => {
        const valA = a[sortConfig.key];
        const valB = b[sortConfig.key];

        if (typeof valA === 'string' && typeof valB === 'string') {
          return sortConfig.direction === 'asc' 
            ? valA.localeCompare(valB) 
            : valB.localeCompare(valA);
        }

        if (typeof valA === 'number' && typeof valB === 'number') {
          return sortConfig.direction === 'asc' ? valA - valB : valB - valA;
        }

        return 0;
      });
    }
    return sortableItems;
  }, [data, sortConfig]);

  const totals = useMemo(() => {
    return data.reduce(
      (acc, curr) => ({
        total: acc.total + curr.total,
        margemOriginal: acc.margemOriginal + curr.margemOriginal,
        margemAjustada: acc.margemAjustada + curr.margemAjustada,
      }),
      { total: 0, margemOriginal: 0, margemAjustada: 0 }
    );
  }, [data]);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  };

  const formatPercent = (value: number) => {
    // Spreadsheet usually has percents like 50.24, so we divide by 100 for the Intl.NumberFormat percent style
    return new Intl.NumberFormat('pt-BR', { 
      style: 'percent', 
      minimumFractionDigits: 2, 
      maximumFractionDigits: 2 
    }).format(value / 100);
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-2xl border border-slate-200 overflow-hidden w-full">
      <div className="overflow-x-auto">
        <table className="w-full text-left text-sm border-collapse table-auto min-w-[1500px]">
          <thead>
            <tr className="bg-slate-950 border-b border-slate-800">
              {['id', 'data', 'canal', 'vendedor', 'total', 'margemOriginal', 'margemAjustada'].map((col) => (
                <th
                  key={col}
                  onClick={() => handleSort(col as keyof Pedido)}
                  className="px-6 py-7 font-black text-slate-500 cursor-pointer hover:bg-slate-900 transition-colors whitespace-nowrap uppercase text-[10px] tracking-[0.25em]"
                >
                  <div className="flex items-center gap-2">
                    {col === 'id' ? 'Nº Pedido' : 
                     col === 'data' ? 'Faturamento' :
                     col === 'canal' ? 'Canal Venda' :
                     col === 'vendedor' ? 'Vendedor' :
                     col === 'total' ? 'Total Planilha' :
                     col === 'margemOriginal' ? 'Margem Orig. (R$)' : 'Margem Ajust. (R$)'}
                    {sortConfig.key === col && (
                      <div className="text-orange-500">
                        {sortConfig.direction === 'asc' ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                      </div>
                    )}
                  </div>
                </th>
              ))}
              {!readOnly && <th className="px-6 py-7 font-black text-slate-500 uppercase text-[10px] tracking-[0.25em]">Crédito</th>}
              {!readOnly && <th className="px-6 py-7 font-black text-slate-500 uppercase text-[10px] tracking-[0.25em]">Débito</th>}
              <th className="px-6 py-7 font-black text-orange-400 uppercase text-[10px] tracking-[0.25em] whitespace-nowrap text-right bg-slate-900">Margem Final (%)</th>
              {!readOnly && <th className="px-6 py-7 font-black text-slate-500 uppercase text-[10px] tracking-[0.25em] w-14 text-center">Status</th>}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {sortedData.map((p) => {
              const margemPercent = p.total > 0 ? (p.margemAjustada / p.total) * 100 : 0;
              const hasAdjustments = (p.credito !== 0 && p.credito !== undefined) || (p.debito !== 0 && p.debito !== undefined);
              const rowBg = !readOnly && p.confirmado ? 'bg-amber-50/80' : 'bg-white';

              return (
                <tr key={p.id} className={`${rowBg} hover:bg-slate-50 transition-colors group`}>
                  <td className="px-6 py-5 font-black text-slate-900">{p.id}</td>
                  <td className="px-6 py-5 text-slate-500 font-medium whitespace-nowrap">{p.data}</td>
                  <td className="px-6 py-5 text-slate-500 font-medium whitespace-nowrap truncate max-w-[150px]">{p.canal}</td>
                  <td className="px-6 py-5 text-slate-600 font-medium truncate max-w-[220px]" title={p.vendedor}>{p.vendedor}</td>
                  <td className="px-6 py-5 text-slate-900 font-bold whitespace-nowrap">{formatCurrency(p.total)}</td>
                  <td className="px-6 py-5 text-slate-400 font-medium whitespace-nowrap italic">{formatCurrency(p.margemOriginal)}</td>
                  <td className="px-6 py-5 font-black text-slate-900 whitespace-nowrap bg-slate-50/50">{formatCurrency(p.margemAjustada)}</td>
                  {!readOnly && (
                    <td className="px-3 py-3">
                      <input
                        type="number"
                        value={p.credito === 0 ? '' : p.credito}
                        onChange={(e) => onUpdatePedido?.(p.id, { credito: parseFloat(e.target.value) || 0 })}
                        className="w-32 px-4 py-3 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-orange-500/10 focus:border-orange-500 outline-none text-right font-black transition-all bg-white"
                        placeholder="0,00"
                      />
                    </td>
                  )}
                  {!readOnly && (
                    <td className="px-3 py-3">
                      <input
                        type="number"
                        value={p.debito === 0 ? '' : p.debito}
                        onChange={(e) => onUpdatePedido?.(p.id, { debito: parseFloat(e.target.value) || 0 })}
                        className="w-32 px-4 py-3 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-orange-500/10 focus:border-orange-500 outline-none text-right font-black transition-all bg-white"
                        placeholder="0,00"
                      />
                    </td>
                  )}
                  <td className={`px-6 py-5 font-black text-right whitespace-nowrap bg-slate-50 border-l border-slate-100 ${margemPercent < 15 ? 'text-red-600' : 'text-emerald-600'}`}>
                    {formatPercent(margemPercent)}
                  </td>
                  {!readOnly && (
                    <td className="px-6 py-5 text-center">
                      {hasAdjustments && (
                        <button
                          onClick={() => onUpdatePedido?.(p.id, { confirmado: !p.confirmado })}
                          className={`p-3 rounded-[1.2rem] transition-all shadow-lg active:scale-90 ${p.confirmado ? 'bg-orange-600 text-white shadow-orange-200' : 'bg-slate-100 text-slate-400 hover:bg-orange-50 hover:text-orange-600'}`}
                        >
                          <Check className="w-5 h-5 stroke-[4px]" />
                        </button>
                      )}
                    </td>
                  )}
                </tr>
              );
            })}
          </tbody>
          <tfoot className="bg-slate-950 text-white shadow-[0_-12px_30px_rgba(0,0,0,0.3)] sticky bottom-0 z-30">
            <tr>
              <td colSpan={4} className="px-6 py-10 font-black text-right uppercase tracking-[0.4em] text-[11px] text-slate-600">Consolidação de Resultados:</td>
              <td className="px-6 py-10 font-black text-3xl whitespace-nowrap border-r border-slate-900/50">{formatCurrency(totals.total)}</td>
              <td className="px-6 py-10 font-bold text-slate-700 whitespace-nowrap italic opacity-30 line-through decoration-slate-600">{formatCurrency(totals.margemOriginal)}</td>
              <td className="px-6 py-10 font-black text-3xl text-white whitespace-nowrap bg-slate-900 border-x border-slate-900/50">{formatCurrency(totals.margemAjustada)}</td>
              {!readOnly ? <td colSpan={2} className="bg-slate-950"></td> : null}
              <td className="px-6 py-10 font-black text-right text-4xl text-emerald-400 bg-slate-900 shadow-inner">
                {formatPercent(totals.total > 0 ? (totals.margemAjustada / totals.total) * 100 : 0)}
              </td>
              {!readOnly ? <td className="w-14"></td> : null}
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
};

