import React, { useState, useMemo } from 'react';
import { Pedido, SortConfig, SortDirection } from '../types';
import { ChevronUp, ChevronDown, Check } from 'lucide-react';

interface OrderTableProps {
  data: Pedido[];
  onUpdatePedido?: (id: string, updates: Partial<Pedido>) => void;
  readOnly?: boolean;
}

export const OrderTable: React.FC<OrderTableProps> = ({ data, onUpdatePedido, readOnly = false }) => {
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'id', direction: 'asc' });

  const handleSort = (key: keyof Pedido) => {
    let direction: SortDirection = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const sortedData = useMemo(() => {
    const sortableItems = [...data];
    if (sortConfig.direction !== null) {
      sortableItems.sort((a, b) => {
        const valA = a[sortConfig.key];
        const valB = b[sortConfig.key];
        if (typeof valA === 'string' && typeof valB === 'string') {
          return sortConfig.direction === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
        }
        if (typeof valA === 'number' && typeof valB === 'number') {
          return sortConfig.direction === 'asc' ? valA - valB : valB - valA;
        }
        return 0;
      });
    }
    return sortableItems;
  }, [data, sortConfig]);

  const totals = useMemo(() => {
    return data.reduce(
      (acc, curr) => ({
        total: acc.total + curr.total,
        margemOriginal: acc.margemOriginal + curr.margemOriginal,
        margemAjustada: acc.margemAjustada + curr.margemAjustada,
      }),
      { total: 0, margemOriginal: 0, margemAjustada: 0 }
    );
  }, [data]);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  };

  const formatPercent = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { 
      minimumFractionDigits: 2, 
      maximumFractionDigits: 2 
    }).format(value) + '%';
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl border border-slate-200 overflow-hidden w-full">
      <div className="overflow-x-auto">
        <table className="w-full text-left text-[11px] border-collapse table-auto min-w-[1800px]">
          <thead>
            <tr className="bg-slate-950 border-b border-slate-800">
              {[
                { key: 'id', label: 'Pedido' },
                { key: 'data', label: 'Data' },
                { key: 'canal', label: 'Canal' },
                { key: 'vendedor', label: 'Vendedor' },
                { key: 'mkt', label: 'Mkt' },
                { key: 'cac', label: 'CAC' },
                { key: 'total', label: 'Total' },
                { key: 'margemOriginal', label: 'Margem R$' },
                { key: 'margemOriginalPct', label: 'Margem %' }
              ].map((col) => (
                <th
                  key={col.key}
                  onClick={() => handleSort(col.key as keyof Pedido)}
                  className="px-4 py-5 font-black text-slate-500 cursor-pointer hover:bg-slate-900 transition-colors whitespace-nowrap uppercase tracking-wider"
                >
                  <div className="flex items-center gap-1.5">
                    {col.label}
                    {sortConfig.key === col.key && (
                      <div className="text-orange-500">
                        {sortConfig.direction === 'asc' ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
                      </div>
                    )}
                  </div>
                </th>
              ))}
              {!readOnly && <th className="px-4 py-5 font-black text-slate-500 uppercase tracking-wider">Crédito</th>}
              {!readOnly && <th className="px-4 py-5 font-black text-slate-500 uppercase tracking-wider">Débito</th>}

              <th className="px-4 py-5 font-black text-slate-400 uppercase tracking-wider">Ajuste R$</th>
              <th className="px-4 py-5 font-black text-slate-300 uppercase tracking-wider">Margem Ajust. R$</th>
              <th className="px-4 py-5 font-black text-orange-400 uppercase tracking-wider text-right bg-slate-900/50">Margem Ajust. %</th>
              {!readOnly && <th className="px-4 py-5 font-black text-slate-500 uppercase tracking-wider w-12 text-center">✔</th>}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {sortedData.map((p) => {
              const ajuste = (p.credito || 0) - (p.debito || 0);
              const margemAjustadaPct = p.total > 0 ? (p.margemAjustada / p.total) * 100 : 0;
              const hasAdjustments = (p.credito !== 0 && p.credito !== undefined) || (p.debito !== 0 && p.debito !== undefined);
              const rowBg = !readOnly && p.confirmado ? 'bg-amber-50/70' : 'bg-white';

              return (
                <tr key={p.id} className={`${rowBg} hover:bg-slate-50 transition-colors group`}>
                  <td className="px-4 py-4 font-black text-slate-900">{p.id}</td>
                  <td className="px-4 py-4 text-slate-500 font-medium whitespace-nowrap">{p.data}</td>
                  <td className="px-4 py-4 text-slate-500 font-medium whitespace-nowrap truncate max-w-[120px]">{p.canal}</td>
                  <td className="px-4 py-4 text-slate-600 font-medium truncate max-w-[180px]" title={p.vendedor}>{p.vendedor}</td>
                  <td className="px-4 py-4 text-slate-600 font-medium">{formatCurrency(p.mkt)}</td>
                  <td className="px-4 py-4 text-slate-600 font-medium">{formatCurrency(p.cac)}</td>
                  <td className="px-4 py-4 text-slate-900 font-bold whitespace-nowrap">{formatCurrency(p.total)}</td>
                  <td className="px-4 py-4 text-slate-400 font-medium italic">{formatCurrency(p.margemOriginal)}</td>
                  <td className="px-4 py-4 text-slate-500 font-medium">{formatPercent(p.margemOriginalPct)}</td>

                  {!readOnly && (
                    <td className="px-2 py-2">
                      <input
                        type="number"
                        value={p.credito === 0 ? '' : p.credito}
                        onChange={(e) => onUpdatePedido?.(p.id, { credito: parseFloat(e.target.value) || 0 })}
                        className="w-24 px-2 py-2 border border-slate-200 rounded-xl focus:ring-4 focus:ring-orange-500/10 outline-none text-right font-black text-[10px]"
                        placeholder="0,00"
                      />
                    </td>
                  )}
                  {!readOnly && (
                    <td className="px-2 py-2">
                      <input
                        type="number"
                        value={p.debito === 0 ? '' : p.debito}
                        onChange={(e) => onUpdatePedido?.(p.id, { debito: parseFloat(e.target.value) || 0 })}
                        className="w-24 px-2 py-2 border border-slate-200 rounded-xl focus:ring-4 focus:ring-orange-500/10 outline-none text-right font-black text-[10px]"
                        placeholder="0,00"
                      />
                    </td>
                  )}

                  <td className="px-4 py-4 font-bold text-slate-500">{formatCurrency(ajuste)}</td>
                  <td className="px-4 py-4 font-black text-slate-900 whitespace-nowrap bg-slate-50/30">{formatCurrency(p.margemAjustada)}</td>
                  <td className={`px-4 py-4 font-black text-right whitespace-nowrap bg-slate-50 border-l border-slate-100 ${margemAjustadaPct < 15 ? 'text-red-600' : 'text-emerald-600'}`}>
                    {formatPercent(margemAjustadaPct)}
                  </td>

                  {!readOnly && (
                    <td className="px-4 py-4 text-center">
                      <button
                        onClick={() => onUpdatePedido?.(p.id, { confirmado: !p.confirmado })}
                        style={{ display: hasAdjustments ? 'inline-block' : 'none' }}
                        className={`p-2 rounded-xl transition-all shadow-md active:scale-90 ${p.confirmado ? 'bg-orange-600 text-white' : 'bg-slate-100 text-slate-400 hover:text-orange-600'}`}
                      >
                        <Check className="w-3.5 h-3.5 stroke-[4px]" />
                      </button>
                    </td>
                  )}
                </tr>
              );
            })}
          </tbody>
          <tfoot className="bg-slate-950 text-white shadow-[0_-10px_30px_rgba(0,0,0,0.3)] sticky bottom-0 z-30">
            <tr>
              <td colSpan={6} className="px-6 py-8 font-black text-right uppercase tracking-[0.3em] text-[9px] text-slate-600">Consolidação de Resultados:</td>
              <td className="px-6 py-8 font-black text-xl whitespace-nowrap border-r border-slate-900/50">{formatCurrency(totals.total)}</td>
              <td className="px-6 py-8 font-bold text-slate-700 whitespace-nowrap italic opacity-30">{formatCurrency(totals.margemOriginal)}</td>
              <td className="px-6 py-8"></td>
              {!readOnly ? <td colSpan={2} className="bg-slate-950"></td> : null}
              <td className="px-6 py-8"></td>
              <td className="px-6 py-8 font-black text-2xl text-white whitespace-nowrap bg-slate-900 border-x border-slate-900/50">{formatCurrency(totals.margemAjustada)}</td>
              <td className="px-6 py-8 font-black text-right text-3xl text-emerald-400 bg-slate-800">
                {formatPercent(totals.total > 0 ? (totals.margemAjustada / totals.total) * 100 : 0)}
              </td>
              {!readOnly ? <td className="w-12"></td> : null}
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import * as XLSX from 'xlsx';
import { Pedido, MesConferencia } from '../types';
import { OrderTable } from '../components/OrderTable';
import { Upload, FileUp, Trash2, AlertCircle } from 'lucide-react';
import { storageService } from '../services/storageService';

export const ConferenciaPage: React.FC = () => {
  const [data, setData] = useState<MesConferencia | null>(storageService.getData());
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const toNumber = (val: any): number => {
    if (val === null || val === undefined || val === '' || val === '-') return 0;
    if (typeof val === 'number') return val;
    const cleaned = String(val).replace(/R\$/g, '').replace(/\./g, '').replace(',', '.').replace(/\s/g, '').trim();
    const n = parseFloat(cleaned);
    return isNaN(n) ? 0 : n;
  };

  const isTotalRow = (row: any): boolean => {
    return Object.values(row).some(val => {
      const s = String(val).toUpperCase();
      return s === 'TOTAL' || s.includes('TOTAL');
    });
  };

  const excelDateToBR = (serial: any): string => {
    if (!serial) return '';
    if (typeof serial === 'string') return serial;
    try {
      const date = new Date(Math.round((serial - 25569) * 86400 * 1000));
      return date.toLocaleDateString('pt-BR');
    } catch {
      return String(serial);
    }
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json(worksheet, { defval: "" }) as any[];

        const mapa: Record<string, Pedido> = {};

        for (let i = 0; i < rows.length; i++) {
          const r = rows[i];
          const numPedido = String(r["Nº Pedido MU"] || "").trim();
          if (!numPedido || isTotalRow(r)) continue;

          const groupRows: any[] = [];
          let j = i;
          while (rows[j] && (j === i || !String(rows[j]["Nº Pedido MU"] || "").trim())) {
            groupRows.push(rows[j]);
            j++;
          }

          const summaryRow = groupRows.find(row => isTotalRow(row));

          let finalTotal = 0;
          let finalMargem = 0;
          let originalPct = 0;
          let mkt = 0;
          let cac = 0;

          const H_TOTAL = "Total Pedido (R$)";
          const H_MARGEM_RS = "Margem final com frete e extras (R$)";
          const H_MARGEM_PCT = "Margem sobre produto + frete e extras (%)";

          if (summaryRow) {
            finalTotal = toNumber(summaryRow[H_TOTAL]);
            finalMargem = toNumber(summaryRow[H_MARGEM_RS]);
            originalPct = toNumber(summaryRow[H_MARGEM_PCT]);
          } else {
            groupRows.forEach(row => {
              finalTotal += toNumber(row[H_TOTAL]);
              finalMargem += toNumber(row[H_MARGEM_RS]);
              if (originalPct === 0) originalPct = toNumber(row[H_MARGEM_PCT]);
            });
          }

          const firstRow = groupRows[0];
          mkt = toNumber(firstRow["Mkt"]);
          cac = toNumber(firstRow["CAC"]);
          let canal = firstRow["Canal Venda"] || "";
          if (!canal && groupRows[1]) canal = groupRows[1]["Canal Venda"] || "";

          mapa[numPedido] = {
            id: numPedido,
            data: firstRow["Data Faturamento"] ? excelDateToBR(firstRow["Data Faturamento"]) : "",
            canal: String(canal),
            vendedor: String(firstRow["Vendedor"] || ""),
            mkt: mkt,
            cac: cac,
            total: finalTotal,
            margemOriginal: finalMargem,
            margemOriginalPct: originalPct,
            credito: 0,
            debito: 0,
            margemAjustada: finalMargem,
            confirmado: false
          };

          i = j - 1; 
        }

        const pedidos = Object.values(mapa);
        const newData: MesConferencia = { mesReferencia: new Date().toISOString().slice(0, 7), pedidos };
        setData(newData);
        storageService.saveData(newData);
      } catch (err) {
        setError("Erro ao processar a planilha. Verifique os cabeçalhos das colunas MU.");
      } finally {
        setLoading(false);
      }
    };
    reader.readAsBinaryString(file);
  };

  const updatePedido = (id: string, updates: Partial<Pedido>) => {
    if (!data) return;
    const newPedidos = data.pedidos.map((p) => {
      if (p.id === id) {
        const updated = { ...p, ...updates };
        updated.margemAjustada = updated.margemOriginal + (updated.credito || 0) - (updated.debito || 0);
        return updated;
      }
      return p;
    });
    const newData = { ...data, pedidos: newPedidos };
    setData(newData);
    storageService.saveData(newData);
  };

  return (
    <div className="space-y-8">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter">Conferência</h2>
          <p className="text-slate-500 font-medium mt-1 uppercase text-[10px] tracking-widest">Auditoria de Vendas e Margens</p>
        </div>
        <div className="flex items-center gap-4">
          {data && (
            <button onClick={() => { if(confirm("Deseja apagar?")) { setData(null); storageService.clearData(); } }} className="px-5 py-3 text-slate-400 hover:text-red-600 rounded-2xl transition-all text-xs font-black uppercase tracking-widest">
              Limpar Auditoria
            </button>
          )}
          <label className="flex items-center gap-3 px-8 py-4 bg-orange-600 hover:bg-orange-700 text-white rounded-2xl cursor-pointer transition-all shadow-xl active:scale-95 font-black text-sm uppercase">
            <FileUp className="w-5 h-5" />
            <span>{data ? 'Trocar Planilha' : 'Carregar Relatório .XLSX'}</span>
            <input type="file" accept=".xlsx, .xls" className="hidden" onChange={handleFileUpload} />
          </label>
        </div>
      </div>
      {error && <div className="bg-red-50 text-red-700 p-6 rounded-3xl font-bold">{error}</div>}
      {loading ? (
        <div className="flex flex-col items-center py-48 text-slate-400">
          <div className="w-16 h-16 border-4 border-slate-100 border-t-orange-500 rounded-full animate-spin"></div>
        </div>
      ) : !data ? (
        <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-48 flex flex-col items-center justify-center text-slate-400">
          <Upload className="w-20 h-20 text-slate-200 mb-8" />
          <p className="text-2xl font-black text-slate-800">Selecione o Relatório</p>
        </div>
      ) : (
        <OrderTable data={data.pedidos} onUpdatePedido={updatePedido} />
      )}
    </div>
  );
};

