                  <td className={`px-6 py-5 font-bold ${ajuste < 0 ? 'text-red-500' : 'text-slate-500'}`}>
                    {ajuste !== 0 ? formatCurrency(ajuste) : 'R$ 0,00'}
                  </td>
                  <td className="px-6 py-5 font-black text-slate-900 whitespace-nowrap bg-slate-50/20">{formatCurrency(p.margemAjustada)}</td>
                  <td className={`px-6 py-5 font-black text-right whitespace-nowrap bg-slate-50/50 border-l border-slate-100 ${getMargemColor(margemAjustadaPct)}`}>
