  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json(worksheet, { defval: "" }) as any[];

        const mapa: Record<string, Pedido> = {};

        // MAPEAMENTO EXATO CONFORME PRINT DA PLANILHA
        const H_PEDIDO = "Nº Pedido MU";
        const H_TOTAL = "Total Pedi"; // Conforme o print
        const H_MARGEM_RS = "Margem líq. c/ frete";
        const H_MARGEM_PCT = "Margem produto c/frete (%)";
        const H_DATA = "Data Faturamento";
        const H_VENDEDOR = "Vendedor";
        const H_CANAL = "Canal Ven";

        for (let i = 0; i < rows.length; i++) {
          const r = rows[i];
          const numPedido = String(r[H_PEDIDO] || "").trim();

          // Ignora linhas vazias ou de total da própria planilha
          if (!numPedido || isTotalRow(r)) continue;

          // Agrupamento por pedido (caso existam várias linhas para o mesmo MU)
          if (!mapa[numPedido]) {
            mapa[numPedido] = {
              id: numPedido,
              data: excelDateToBR(r[H_DATA]),
              canal: String(r[H_CANAL] || ""),
              vendedor: String(r[H_VENDEDOR] || ""),
              mkt: toNumber(r["Mkt"]),
              cac: toNumber(r["CAC"]),
              total: toNumber(r[H_TOTAL]),
              margemOriginal: toNumber(r[H_MARGEM_RS]),
              margemOriginalPct: toPercent(r[H_MARGEM_PCT]),
              credito: 0,
              debito: 0,
              margemAjustada: toNumber(r[H_MARGEM_RS]),
              confirmado: false
            };
          } else {
            // Se o pedido já existe, somamos valores se necessário (depende da estrutura da planilha)
            // Normalmente para conferência MU, a primeira linha já traz o consolidado do pedido.
          }
        }

        const pedidos = Object.values(mapa);
        const newData: MesConferencia = { mesReferencia: new Date().toISOString().slice(0, 7), pedidos };
        setData(newData);
        storageService.saveData(newData);
      } catch (err) {
        setError("Erro ao ler planilha. Verifique os nomes das colunas.");
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    reader.readAsBinaryString(file);
  };

  const updatePedido = (id: string, updates: Partial<Pedido>) => {
    if (!data) return;
    const newPedidos = data.pedidos.map((p) => {
      if (p.id === id) {
        const updated = { ...p, ...updates };
        // Margem Ajustada R$ sempre calculada sobre a base original da planilha
        updated.margemAjustada = updated.margemOriginal + (updated.credito || 0) - (updated.debito || 0);
        return updated;
      }
      return p;
    });
    const newData = { ...data, pedidos: newPedidos };
    setData(newData);
    storageService.saveData(newData);
  };

  return (
    <div className="space-y-8">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6">
