        const H_MARGEM_PCT = "Margem produto c/frete (%)";

        for (let i = 0; i < rows.length; i++) {
          const r = rows[i];
          const numPedido = String(r[H_PEDIDO] || "").trim();

          if (!numPedido || isTotalRow(r)) continue;

          // Se o pedido já existe no mapa, ignoramos (ou somamos, mas normalmente MU é chave única consolidada)
          if (!mapa[numPedido]) {
            mapa[numPedido] = {
              id: numPedido,
              data: excelDateToBR(r[H_DATA]),
              canal: String(r[H_CANAL] || ""),
              vendedor: String(r[H_VENDEDOR] || ""),
              mkt: toNumber(r[H_MKT]),
              cac: toNumber(r[H_CAC]),
              total: toNumber(r[H_TOTAL]),
              margemOriginal: toNumber(r[H_MARGEM_RS]),
              margemOriginalPct: toPercent(r[H_MARGEM_PCT]),
              credito: 0,
              debito: 0,
              margemAjustada: toNumber(r[H_MARGEM_RS]),
              confirmado: false
            };
          }
        }

        const pedidos = Object.values(mapa);
        if (pedidos.length === 0) {
          setError("Nenhum pedido encontrado. Verifique os nomes das colunas.");
          setLoading(false);
          return;
        }

