      .replace(/\./g, '')
      .replace(',', '.')
      .replace(/\s/g, '')
      .trim();
    const n = parseFloat(cleaned);
    return isNaN(n) ? 0 : n;
  };

  const toPercent = (val: any): number => {
    let n = toNumber(val);
    // Converte decimal (ex: 0,15) para percentual real (15,00)
    // Aplicamos em valores entre -1 e 1 (excluindo 0)
    if (Math.abs(n) > 0 && Math.abs(n) < 1) return n * 100;
    return n;
