import React, { useState, useEffect, useCallback } from 'react';
import { Sidebar } from './components/Sidebar';
import { ConferenciaPage } from './pages/ConferenciaPage';
import { AjustesFinaisPage } from './pages/AjustesFinaisPage';
import { PageId, MesConferencia, Pedido } from './types';
import { Construction } from 'lucide-react';
import { storageService } from './services/storageService';

const App: React.FC = () => {
  const [activePage, setActivePage] = useState<PageId>('conferencia');
  const [data, setData] = useState<MesConferencia | null>(storageService.getData());

  // Sincroniza com localStorage sempre que o dado mudar
  const refreshData = useCallback((newData: MesConferencia | null) => {
    if (newData) {
      storageService.saveData(newData);
    } else {
      storageService.clearData();
    }
    setData(newData);
  }, []);

  const handleUpdatePedido = useCallback((id: string, updates: Partial<Pedido>) => {
    setData(current => {
      if (!current) return null;
      const newPedidos = current.pedidos.map((p) => {
        if (p.id === id) {
          const updated = { ...p, ...updates };
          // Regra de Ouro: Margem Ajustada = Margem Original + Crédito - Débito
          updated.margemAjustada = updated.margemOriginal + (updated.credito || 0) - (updated.debito || 0);
          return updated;
        }
        return p;
      });
      const updatedData = { ...current, pedidos: newPedidos };
      storageService.saveData(updatedData);
      return updatedData;
    });
  }, []);

  const handleDeletePedido = useCallback((id: string) => {
    setData(current => {
      if (!current) return null;
      const newPedidos = current.pedidos.filter(p => p.id !== id);
      const updatedData = { ...current, pedidos: newPedidos };
      storageService.saveData(updatedData);
      return updatedData;
    });
  }, []);

  const handleSetData = (newData: MesConferencia | null) => {
    refreshData(newData);
  };

  const renderComingSoon = (title: string) => (
    <div className="flex flex-col items-center justify-center h-[70vh] text-center space-y-8 animate-in fade-in duration-700">
      <div className="bg-slate-100 p-12 rounded-[4rem] shadow-inner">
        <Construction className="w-24 h-24 text-slate-300 animate-bounce" />
      </div>
      <div className="space-y-2">
        <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">{title}</h2>
        <p className="text-slate-400 font-bold uppercase tracking-[0.3em] text-[10px]">Módulo em Desenvolvimento</p>
      </div>
      <p className="max-w-md text-slate-500 font-medium leading-relaxed">
        Estamos preparando uma experiência incrível para este módulo. Em breve você terá acesso completo a esta funcionalidade.
      </p>
    </div>
  );

  const renderPage = () => {
    switch (activePage) {
      case 'dashboard': return renderComingSoon('Dashboard Executivo');
      case 'conferencia': 
        return (
          <ConferenciaPage 
            data={data} 
            onSetData={handleSetData}
            onUpdatePedido={handleUpdatePedido}
            onDeletePedido={handleDeletePedido}
            onNavigateToAjustes={() => setActivePage('ajustes')} 
          />
        );
      case 'ajustes': 
        return (
          <AjustesFinaisPage 
            data={data} 
            onDeletePedido={handleDeletePedido}
          />
        );
      case 'analise-vendedor': return renderComingSoon('Análise de Vendedor');
      case 'comissao': return renderComingSoon('Cálculo de Comissões');
      case 'contas-pagar': return renderComingSoon('Contas a Pagar');
      case 'fluxo-caixa': return renderComingSoon('Fluxo de Caixa');
      case 'dre': return renderComingSoon('DRE - Demonstrativo de Resultado');
      default: 
        return (
          <ConferenciaPage 
            data={data} 
            onSetData={handleSetData}
            onUpdatePedido={handleUpdatePedido}
            onDeletePedido={handleDeletePedido}
            onNavigateToAjustes={() => setActivePage('ajustes')} 
          />
        );
    }
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex selection:bg-red-100 selection:text-red-900 antialiased">
      <Sidebar activePage={activePage} setActivePage={setActivePage} />

      <main className="flex-grow flex flex-col min-w-0">
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-40 flex items-center justify-between px-12">
          <div className="flex items-center gap-3">
            <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(16,185,129,0.5)]"></div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sistemas Itu — Online</p>
          </div>

          <div className="flex items-center gap-6">
            <div className="h-8 w-px bg-slate-200"></div>
            <div className="flex items-center gap-2 px-4 py-2 bg-slate-50 rounded-full border border-slate-100">
              <span className="w-1.5 h-1.5 bg-blue-500 rounded-full"></span>
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-tighter">Backup Local Ativo</span>
            </div>
          </div>
        </header>

        <div className="p-8 lg:p-12">
          <div className="bg-white p-10 rounded-[4rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.06)] border border-slate-200/50">
            {renderPage()}
          </div>
        </div>

        <footer className="mt-auto py-12 px-12 border-t border-slate-100 bg-white/50">
          <div className="flex flex-col md:flex-row justify-between items-center gap-6">
            <div className="flex items-center gap-4">
              <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.4em]">ABC da Construção Itu &copy; {new Date().getFullYear()}</p>
            </div>
            <div className="flex items-center gap-8 text-[9px] font-black text-slate-300 uppercase tracking-[0.5em]">
              <span>Plataforma de Auditoria V1.5</span>
            </div>
          </div>
        </footer>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Pedido, SortConfig, SortDirection } from '../types';
import { ChevronUp, ChevronDown, Check, Trash2 } from 'lucide-react';

interface OrderTableProps {
  data: Pedido[];
  onUpdatePedido?: (id: string, updates: Partial<Pedido>) => void;
  onDeletePedido?: (id: string) => void;
  readOnly?: boolean;
}

export const OrderTable: React.FC<OrderTableProps> = ({ data, onUpdatePedido, onDeletePedido, readOnly = false }) => {
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'id', direction: 'asc' });

  const handleSort = (key: keyof Pedido) => {
    let direction: SortDirection = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const sortedData = useMemo(() => {
    const sortableItems = [...data];
    if (sortConfig.direction !== null) {
      sortableItems.sort((a, b) => {
        const valA = a[sortConfig.key];
        const valB = b[sortConfig.key];
        if (typeof valA === 'string' && typeof valB === 'string') {
          return sortConfig.direction === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
        }
        if (typeof valA === 'number' && typeof valB === 'number') {
          return sortConfig.direction === 'asc' ? valA - valB : valB - valA;
        }
        return 0;
      });
    }
    return sortableItems;
  }, [data, sortConfig]);

  const totals = useMemo(() => {
    return data.reduce(
      (acc, curr) => ({
        total: acc.total + curr.total,
        margemOriginal: acc.margemOriginal + curr.margemOriginal,
        margemAjustada: acc.margemAjustada + curr.margemAjustada,
      }),
      { total: 0, margemOriginal: 0, margemAjustada: 0 }
    );
  }, [data]);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  };

  const formatPercent = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { 
      minimumFractionDigits: 2, 
      maximumFractionDigits: 2 
    }).format(value) + '%';
  };

  const getMargemColor = (pct: number) => {
    if (pct <= 8.00) return 'text-[#E30613]';
    if (pct <= 10.00) return 'text-amber-500';
    return 'text-emerald-600';
  };

  const handleDeleteClick = (id: string) => {
    if (window.confirm(`Deseja EXCLUIR o pedido MU ${id}? Esta ação alterará os totais do faturamento e não pode ser desfeita.`)) {
      onDeletePedido?.(id);
    }
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl border border-slate-200 overflow-hidden w-full">
      <div className="overflow-x-auto">
        <table className="w-full text-left text-[11px] border-collapse table-auto min-w-[1920px]">
          <thead>
            <tr className="bg-[#0A1121] border-b border-slate-800">
              {[
                { key: 'id', label: 'Nº PEDIDO MU' },
                { key: 'data', label: 'DATA FATURAMENTO' },
                { key: 'canal', label: 'CANAL VENDA' },
                { key: 'vendedor', label: 'VENDEDOR' },
                { key: 'total', label: 'TOTAL PEDIDO (R$)' },
                { key: 'margemOriginal', label: 'MARGEM LÍQ. C/ FRETE' },
                { key: 'margemOriginalPct', label: 'MARGEM PRODUTO C/FRETE (%)' }
              ].map((col) => (
                <th
                  key={col.key}
                  onClick={() => handleSort(col.key as keyof Pedido)}
                  className="px-6 py-6 font-black text-slate-400 cursor-pointer hover:bg-slate-900 transition-colors whitespace-nowrap tracking-wider"
                >
                  <div className="flex items-center gap-1.5">
                    {col.label}
                    {sortConfig.key === col.key && (
                      <div className="text-[#E30613]">
                        {sortConfig.direction === 'asc' ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
                      </div>
                    )}
                  </div>
                </th>
              ))}
              {!readOnly && <th className="px-6 py-6 font-black text-slate-400 tracking-wider">CRÉDITO</th>}
              {!readOnly && <th className="px-6 py-6 font-black text-slate-400 tracking-wider">DÉBITO</th>}

              <th className="px-6 py-6 font-black text-slate-400 tracking-wider">AJUSTE R$</th>
              <th className="px-6 py-6 font-black text-slate-200 tracking-wider">MARGEM AJUST. R$</th>
              <th className="px-6 py-6 font-black text-[#E30613] tracking-wider text-right bg-[#050B16]">MARGEM AJUST. %</th>
              <th className="px-6 py-6 font-black text-slate-400 tracking-wider w-32 text-center">AÇÕES</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {sortedData.map((p) => {
              const ajuste = (p.credito || 0) - (p.debito || 0);
              const hasAdjustments = (p.credito || 0) !== 0 || (p.debito || 0) !== 0;
              const isConfirmado = !readOnly && p.confirmado;
              const margemAjustadaPct = p.total > 0 ? (p.margemAjustada / p.total) * 100 : 0;

              return (
                <tr key={p.id} className={`${isConfirmado || hasAdjustments ? 'bg-[#FFF9EB]' : 'bg-white'} hover:bg-slate-50/80 transition-all group`}>
                  <td className="px-6 py-5 text-slate-900 font-black whitespace-nowrap">{p.id}</td>
                  <td className="px-6 py-5 text-slate-500 font-medium whitespace-nowrap">{p.data}</td>
                  <td className="px-6 py-5 text-slate-500 font-medium whitespace-nowrap">{p.canal}</td>
                  <td className="px-6 py-5 text-slate-600 font-medium truncate max-w-[200px]">{p.vendedor}</td>
                  <td className="px-6 py-5 text-slate-900 font-black whitespace-nowrap">{formatCurrency(p.total)}</td>
                  <td className="px-6 py-5 text-slate-400 font-bold italic whitespace-nowrap">{formatCurrency(p.margemOriginal)}</td>
                  <td className="px-6 py-5 text-slate-500 font-bold">{formatPercent(p.margemOriginalPct)}</td>

                  {!readOnly && (
                    <td className="px-4 py-4">
                      <input
                        type="number"
                        step="0.01"
                        value={p.credito === 0 ? '' : p.credito}
                        onChange={(e) => onUpdatePedido?.(p.id, { credito: parseFloat(e.target.value) || 0 })}
                        className="w-28 px-4 py-2 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-red-500/10 outline-none text-right font-black text-[12px] bg-white transition-all shadow-sm"
                        placeholder="0,00"
                      />
                    </td>
                  )}
                  {!readOnly && (
                    <td className="px-4 py-4">
                      <input
                        type="number"
                        step="0.01"
                        value={p.debito === 0 ? '' : p.debito}
                        onChange={(e) => onUpdatePedido?.(p.id, { debito: parseFloat(e.target.value) || 0 })}
                        className="w-28 px-4 py-2 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-red-500/10 outline-none text-right font-black text-[12px] bg-white transition-all shadow-sm"
                        placeholder="0,00"
                      />
                    </td>
                  )}

                  <td className={`px-6 py-5 font-bold ${ajuste < 0 ? 'text-[#E30613]' : ajuste > 0 ? 'text-emerald-500' : 'text-slate-500'}`}>
                    {ajuste !== 0 ? formatCurrency(ajuste) : 'R$ 0,00'}
                  </td>
                  <td className="px-6 py-5 font-black text-slate-900 whitespace-nowrap bg-slate-50/20">{formatCurrency(p.margemAjustada)}</td>
                  <td className={`px-6 py-5 font-black text-right whitespace-nowrap bg-slate-50/50 border-l border-slate-100 ${getMargemColor(margemAjustadaPct)}`}>
                    {formatPercent(margemAjustadaPct)}
                  </td>

                  <td className="px-6 py-5">
                    <div className="flex items-center justify-center gap-3">
                      {!readOnly && (
                        <button
                          onClick={() => onUpdatePedido?.(p.id, { confirmado: !p.confirmado })}
                          className={`p-2.5 rounded-xl transition-all shadow-md active:scale-90 ${isConfirmado ? 'bg-[#E30613] text-white shadow-red-200' : 'bg-slate-50 text-slate-200 hover:bg-red-50 hover:text-[#E30613]'}`}
                        >
                          <Check className="w-4 h-4 stroke-[4px]" />
                        </button>
                      )}
                      <button
                        onClick={() => handleDeleteClick(p.id)}
                        className="p-2.5 rounded-xl bg-slate-100 text-slate-400 hover:bg-red-600 hover:text-white transition-all shadow-md active:scale-90"
                        title="Remover definitivamente"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
          <tfoot className="bg-[#0A1121] text-white shadow-[0_-15px_50px_rgba(0,0,0,0.5)] sticky bottom-0 z-30">
            <tr>
              <td colSpan={4} className="px-6 py-10 font-black text-right uppercase tracking-[0.4em] text-[10px] text-slate-600">Totalizadores:</td>
              <td className="px-6 py-10 font-black text-2xl whitespace-nowrap border-r border-slate-800/20">{formatCurrency(totals.total)}</td>
              <td className="px-6 py-10 font-bold text-slate-800 whitespace-nowrap italic opacity-30">{formatCurrency(totals.margemOriginal)}</td>
              <td className="px-6 py-10"></td>
              {!readOnly ? <td colSpan={2} className="bg-[#0A1121]"></td> : null}
              <td className="px-6 py-10"></td>
              <td className="px-6 py-10 font-black text-2xl text-white whitespace-nowrap bg-[#050B16] border-x border-slate-800/50">{formatCurrency(totals.margemAjustada)}</td>
              <td className={`px-6 py-10 font-black text-right text-4xl bg-[#050B16] shadow-inner ${getMargemColor(totals.total > 0 ? (totals.margemAjustada / totals.total) * 100 : 0)}`}>
                {formatPercent(totals.total > 0 ? (totals.margemAjustada / totals.total) * 100 : 0)}
              </td>
              <td className="w-32"></td>
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Pedido, SortConfig, SortDirection } from '../types';
import { ChevronUp, ChevronDown, Check, Trash2, AlertTriangle, X } from 'lucide-react';

interface OrderTableProps {
  data: Pedido[];
  onUpdatePedido?: (id: string, updates: Partial<Pedido>) => void;
  onDeletePedido?: (id: string) => void;
  readOnly?: boolean;
}

export const OrderTable: React.FC<OrderTableProps> = ({ data, onUpdatePedido, onDeletePedido, readOnly = false }) => {
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'id', direction: 'asc' });
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

  const handleSort = (key: keyof Pedido) => {
    let direction: SortDirection = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const sortedData = useMemo(() => {
    const sortableItems = [...data];
    if (sortConfig.direction !== null) {
      sortableItems.sort((a, b) => {
        const valA = a[sortConfig.key];
        const valB = b[sortConfig.key];
        if (typeof valA === 'string' && typeof valB === 'string') {
          return sortConfig.direction === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
        }
        if (typeof valA === 'number' && typeof valB === 'number') {
          return sortConfig.direction === 'asc' ? valA - valB : valB - valA;
        }
        return 0;
      });
    }
    return sortableItems;
  }, [data, sortConfig]);

  const totals = useMemo(() => {
    return data.reduce(
      (acc, curr) => ({
        total: acc.total + curr.total,
        margemOriginal: acc.margemOriginal + curr.margemOriginal,
        margemAjustada: acc.margemAjustada + curr.margemAjustada,
      }),
      { total: 0, margemOriginal: 0, margemAjustada: 0 }
    );
  }, [data]);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  };

  const formatPercent = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { 
      minimumFractionDigits: 2, 
      maximumFractionDigits: 2 
    }).format(value) + '%';
  };

  const getMargemColor = (pct: number) => {
    if (pct <= 8.00) return 'text-[#E30613]';
    if (pct <= 10.00) return 'text-amber-500';
    return 'text-emerald-600';
  };

  const confirmDelete = () => {
    if (confirmDeleteId) {
      onDeletePedido?.(confirmDeleteId);
      setConfirmDeleteId(null);
    }
  };

  return (
    <>
      {/* Custom Delete Confirmation Modal */}
      {confirmDeleteId && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-950/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white rounded-[2.5rem] shadow-2xl max-w-md w-full p-10 space-y-8 animate-in zoom-in-95 duration-300 border border-slate-200">
            <div className="flex flex-col items-center text-center space-y-4">
              <div className="w-20 h-20 bg-red-50 rounded-full flex items-center justify-center animate-pulse">
                <AlertTriangle className="w-10 h-10 text-[#E30613]" />
              </div>
              <div className="space-y-2">
                <h3 className="text-2xl font-black text-slate-900 tracking-tighter uppercase">Excluir Pedido?</h3>
                <p className="text-slate-500 text-sm font-medium leading-relaxed">
                  Você está prestes a remover permanentemente o pedido <span className="font-black text-slate-900 underline">MU {confirmDeleteId}</span>. Esta ação recalculará todos os totais e comissões.
                </p>
              </div>
            </div>

            <div className="flex flex-col gap-3">
              <button
                onClick={confirmDelete}
                className="w-full py-4 bg-[#E30613] hover:bg-red-700 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl shadow-red-100 transition-all active:scale-95"
              >
                Sim, Excluir Definitivamente
              </button>
              <button
                onClick={() => setConfirmDeleteId(null)}
                className="w-full py-4 bg-slate-100 hover:bg-slate-200 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest transition-all active:scale-95"
              >
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="bg-white rounded-[2rem] shadow-2xl border border-slate-200 overflow-hidden w-full">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-[11px] border-collapse table-auto min-w-[1920px]">
            <thead>
              <tr className="bg-[#0A1121] border-b border-slate-800">
                {[
                  { key: 'id', label: 'Nº PEDIDO MU' },
                  { key: 'data', label: 'DATA FATURAMENTO' },
                  { key: 'canal', label: 'CANAL VENDA' },
                  { key: 'vendedor', label: 'VENDEDOR' },
                  { key: 'total', label: 'TOTAL PEDIDO (R$)' },
                  { key: 'margemOriginal', label: 'MARGEM LÍQ. C/ FRETE' },
                  { key: 'margemOriginalPct', label: 'MARGEM PRODUTO C/FRETE (%)' }
                ].map((col) => (
                  <th
                    key={col.key}
                    onClick={() => handleSort(col.key as keyof Pedido)}
                    className="px-6 py-6 font-black text-slate-400 cursor-pointer hover:bg-slate-900 transition-colors whitespace-nowrap tracking-wider"
                  >
                    <div className="flex items-center gap-1.5">
                      {col.label}
                      {sortConfig.key === col.key && (
                        <div className="text-[#E30613]">
                          {sortConfig.direction === 'asc' ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
                        </div>
                      )}
                    </div>
                  </th>
                ))}
                {!readOnly && <th className="px-6 py-6 font-black text-slate-400 tracking-wider">CRÉDITO</th>}
                {!readOnly && <th className="px-6 py-6 font-black text-slate-400 tracking-wider">DÉBITO</th>}

                <th className="px-6 py-6 font-black text-slate-400 tracking-wider">AJUSTE R$</th>
                <th className="px-6 py-6 font-black text-slate-200 tracking-wider">MARGEM AJUST. R$</th>
                <th className="px-6 py-6 font-black text-[#E30613] tracking-wider text-right bg-[#050B16]">MARGEM AJUST. %</th>
                <th className="px-6 py-6 font-black text-slate-400 tracking-wider w-32 text-center">AÇÕES</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {sortedData.map((p) => {
                const ajuste = (p.credito || 0) - (p.debito || 0);
                const hasAdjustments = (p.credito || 0) !== 0 || (p.debito || 0) !== 0;
                const isConfirmado = !readOnly && p.confirmado;
                const margemAjustadaPct = p.total > 0 ? (p.margemAjustada / p.total) * 100 : 0;

                return (
                  <tr key={p.id} className={`${isConfirmado || hasAdjustments ? 'bg-[#FFF9EB]' : 'bg-white'} hover:bg-slate-50/80 transition-all group`}>
                    <td className="px-6 py-5 text-slate-900 font-black whitespace-nowrap">{p.id}</td>
                    <td className="px-6 py-5 text-slate-500 font-medium whitespace-nowrap">{p.data}</td>
                    <td className="px-6 py-5 text-slate-500 font-medium whitespace-nowrap">{p.canal}</td>
                    <td className="px-6 py-5 text-slate-600 font-medium truncate max-w-[200px]">{p.vendedor}</td>
                    <td className="px-6 py-5 text-slate-900 font-black whitespace-nowrap">{formatCurrency(p.total)}</td>
                    <td className="px-6 py-5 text-slate-400 font-bold italic whitespace-nowrap">{formatCurrency(p.margemOriginal)}</td>
                    <td className="px-6 py-5 text-slate-500 font-bold">{formatPercent(p.margemOriginalPct)}</td>

                    {!readOnly && (
                      <td className="px-4 py-4">
                        <input
                          type="number"
                          step="0.01"
                          value={p.credito === 0 ? '' : p.credito}
                          onChange={(e) => onUpdatePedido?.(p.id, { credito: parseFloat(e.target.value) || 0 })}
                          className="w-28 px-4 py-2 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-red-500/10 outline-none text-right font-black text-[12px] bg-white transition-all shadow-sm"
                          placeholder="0,00"
                        />
                      </td>
                    )}
                    {!readOnly && (
                      <td className="px-4 py-4">
                        <input
                          type="number"
                          step="0.01"
                          value={p.debito === 0 ? '' : p.debito}
                          onChange={(e) => onUpdatePedido?.(p.id, { debito: parseFloat(e.target.value) || 0 })}
                          className="w-28 px-4 py-2 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-red-500/10 outline-none text-right font-black text-[12px] bg-white transition-all shadow-sm"
                          placeholder="0,00"
                        />
                      </td>
                    )}

                    <td className={`px-6 py-5 font-bold ${ajuste < 0 ? 'text-[#E30613]' : ajuste > 0 ? 'text-emerald-500' : 'text-slate-500'}`}>
                      {ajuste !== 0 ? formatCurrency(ajuste) : 'R$ 0,00'}
                    </td>
                    <td className="px-6 py-5 font-black text-slate-900 whitespace-nowrap bg-slate-50/20">{formatCurrency(p.margemAjustada)}</td>
                    <td className={`px-6 py-5 font-black text-right whitespace-nowrap bg-slate-50/50 border-l border-slate-100 ${getMargemColor(margemAjustadaPct)}`}>
                      {formatPercent(margemAjustadaPct)}
                    </td>

                    <td className="px-6 py-5">
                      <div className="flex items-center justify-center gap-3">
                        {!readOnly && (
                          <button
                            onClick={() => onUpdatePedido?.(p.id, { confirmado: !p.confirmado })}
                            className={`p-2.5 rounded-xl transition-all shadow-md active:scale-90 ${isConfirmado ? 'bg-[#E30613] text-white shadow-red-200' : 'bg-slate-50 text-slate-200 hover:bg-red-50 hover:text-[#E30613]'}`}
                          >
                            <Check className="w-4 h-4 stroke-[4px]" />
                          </button>
                        )}
                        <button
                          onClick={() => setConfirmDeleteId(p.id)}
                          className="p-2.5 rounded-xl bg-slate-100 text-slate-400 hover:bg-red-600 hover:text-white transition-all shadow-md active:scale-90 group/trash"
                          title="Remover definitivamente"
                        >
                          <Trash2 className="w-4 h-4 group-hover/trash:scale-110 transition-transform" />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
            <tfoot className="bg-[#0A1121] text-white shadow-[0_-15px_50px_rgba(0,0,0,0.5)] sticky bottom-0 z-30">
              <tr>
                <td colSpan={4} className="px-6 py-10 font-black text-right uppercase tracking-[0.4em] text-[10px] text-slate-600">Totalizadores:</td>
                <td className="px-6 py-10 font-black text-2xl whitespace-nowrap border-r border-slate-800/20">{formatCurrency(totals.total)}</td>
                <td className="px-6 py-10 font-bold text-slate-800 whitespace-nowrap italic opacity-30">{formatCurrency(totals.margemOriginal)}</td>
                <td className="px-6 py-10"></td>
                {!readOnly ? <td colSpan={2} className="bg-[#0A1121]"></td> : null}
                <td className="px-6 py-10"></td>
                <td className="px-6 py-10 font-black text-2xl text-white whitespace-nowrap bg-[#050B16] border-x border-slate-800/50">{formatCurrency(totals.margemAjustada)}</td>
                <td className={`px-6 py-10 font-black text-right text-4xl bg-[#050B16] shadow-inner ${getMargemColor(totals.total > 0 ? (totals.margemAjustada / totals.total) * 100 : 0)}`}>
                  {formatPercent(totals.total > 0 ? (totals.margemAjustada / totals.total) * 100 : 0)}
                </td>
                <td className="w-32"></td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
    </>
  );
};

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { Pedido, MesConferencia } from '../types';
import { OrderTable } from '../components/OrderTable';
import { FileUp, CheckCircle2, Banknote, TrendingUp, Percent } from 'lucide-react';

interface ConferenciaPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null) => void;
  onUpdatePedido: (id: string, updates: Partial<Pedido>) => void;
  onDeletePedido: (id: string) => void;
  onNavigateToAjustes: () => void;
}

export const ConferenciaPage: React.FC<ConferenciaPageProps> = ({ 
  data, 
  onSetData, 
  onUpdatePedido, 
  onDeletePedido,
  onNavigateToAjustes 
}) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const COL_MU = "Nº Pedido MU";
  const COL_DATA = "Data Faturamento";
  const COL_VENDEDOR = "Vendedor";
  const COL_TOTAL = "Total Pedido (R$)";
  const COL_CANAL = "Canal Venda";
  const COL_MARGEM_RS = "Margem líq. c/ frete";
  const COL_MARGEM_PCT = "Margem produto c/frete (%)";
  const COL_MKT = "Mkt";
  const COL_CAC = "CAC";

  const summary = useMemo(() => {
    if (!data || data.pedidos.length === 0) return { total: 0, margem: 0, pct: 0 };
    const total = data.pedidos.reduce((acc, curr) => acc + curr.total, 0);
    const margem = data.pedidos.reduce((acc, curr) => acc + curr.margemAjustada, 0);
    const pct = total > 0 ? (margem / total) * 100 : 0;
    return { total, margem, pct };
  }, [data]);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  };

  const toNumber = (val: any): number => {
    if (val === null || val === undefined || val === '' || val === '-') return 0;
    if (typeof val === 'number') return val;
    const cleaned = String(val)
      .replace(/R\$/g, '')
      .replace(/\./g, '')
      .replace(',', '.')
      .replace(/\s/g, '')
      .trim();
    const n = parseFloat(cleaned);
    return isNaN(n) ? 0 : n;
  };

  const toPercent = (val: any): number => {
    let n = toNumber(val);
    if (Math.abs(n) > 0 && Math.abs(n) < 1) return n * 100;
    return n;
  };

  const excelDateToBR = (serial: any): string => {
    if (!serial) return '';
    if (typeof serial === 'string') return serial;
    try {
      const date = new Date(Math.round((serial - 25569) * 86400 * 1000));
      return date.toLocaleDateString('pt-BR');
    } catch {
      return String(serial);
    }
  };

  const getActualKey = (firstRow: any, target: string): string => {
    const keys = Object.keys(firstRow);
    const found = keys.find(k => k.trim().toLowerCase() === target.toLowerCase());
    return found || target;
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json(worksheet, { defval: "" }) as any[];

        if (rows.length === 0) throw new Error("Planilha vazia");

        const firstRow = rows[0];
        const K = {
          MU: getActualKey(firstRow, COL_MU),
          DATA: getActualKey(firstRow, COL_DATA),
          VENDEDOR: getActualKey(firstRow, COL_VENDEDOR),
          TOTAL: getActualKey(firstRow, COL_TOTAL),
          CANAL: getActualKey(firstRow, COL_CANAL),
          MARGEM_RS: getActualKey(firstRow, COL_MARGEM_RS),
          MARGEM_PCT: getActualKey(firstRow, COL_MARGEM_PCT),
          MKT: getActualKey(firstRow, COL_MKT),
          CAC: getActualKey(firstRow, COL_CAC)
        };

        const mapa: Record<string, Pedido> = {};
        let currentMU: string | null = null;

        rows.forEach(r => {
          const rawMU = String(r[K.MU] || "").trim();

          if (rawMU && !rawMU.toUpperCase().includes("TOTAL")) {
            currentMU = rawMU;

            if (!mapa[currentMU]) {
              mapa[currentMU] = {
                id: currentMU,
                data: excelDateToBR(r[K.DATA]),
                canal: String(r[K.CANAL] || "").trim(),
                vendedor: String(r[K.VENDEDOR] || "").trim(),
                mkt: toNumber(r[K.MKT]),
                cac: toNumber(r[K.CAC]),
                total: toNumber(r[K.TOTAL]),
                margemOriginal: toNumber(r[K.MARGEM_RS]),
                margemOriginalPct: toPercent(r[K.MARGEM_PCT]),
                credito: 0,
                debito: 0,
                margemAjustada: toNumber(r[K.MARGEM_RS]),
                confirmado: false
              };
            }
          } 
          else if (!rawMU && currentMU && mapa[currentMU]) {
            const canalItem = String(r[K.CANAL] || "").trim();
            const vendedorItem = String(r[K.VENDEDOR] || "").trim();
            const dataItem = excelDateToBR(r[K.DATA]);

            if (!mapa[currentMU].canal && canalItem) mapa[currentMU].canal = canalItem;
            if (!mapa[currentMU].vendedor && vendedorItem) mapa[currentMU].vendedor = vendedorItem;
            if (!mapa[currentMU].data && dataItem) mapa[currentMU].data = dataItem;

            mapa[currentMU].mkt += toNumber(r[K.MKT]);
            mapa[currentMU].cac += toNumber(r[K.CAC]);
          }
        });

        const pedidos = Object.values(mapa);
        if (pedidos.length === 0) {
          setError(`Não encontramos a coluna "${COL_MU}" ou os dados estão inválidos.`);
        } else {
          const newData: MesConferencia = { mesReferencia: new Date().toISOString().slice(0, 7), pedidos };
          onSetData(newData);
        }
      } catch (err) {
        setError("Erro fatal ao processar arquivo. Verifique se as colunas estão corretas.");
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleReset = () => {
    if(confirm("Deseja apagar todos os dados da auditoria atual? Isso não pode ser desfeito.")) {
      onSetData(null);
      setError(null);
    }
  };

  return (
    <div className="space-y-12">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div>
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Conferência</h2>
          <p className="text-[#E30613] font-bold mt-2 uppercase text-[11px] tracking-[0.3em]">Auditoria de Entradas MU</p>
        </div>
        <div className="flex items-center gap-4">
          {error && <span className="bg-red-50 text-[#E30613] px-4 py-2 rounded-lg font-bold text-xs border border-red-100">{error}</span>}

          {data && (
            <>
              <button 
                onClick={handleReset}
                className="text-slate-400 hover:text-red-600 font-black uppercase text-[10px] tracking-widest transition-colors mr-4"
              >
                Resetar Base
              </button>
              <button 
                onClick={onNavigateToAjustes}
                className="flex items-center gap-4 px-10 py-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl shadow-xl shadow-emerald-100 transition-all active:scale-95 font-black text-sm uppercase tracking-wider"
              >
                <CheckCircle2 className="w-5 h-5" />
                VALIDAR PLANILHA
              </button>
            </>
          )}

          <label className="flex items-center gap-4 px-10 py-5 bg-[#E30613] hover:bg-red-700 text-white rounded-2xl cursor-pointer transition-all shadow-2xl shadow-red-100 active:scale-95 font-black text-sm uppercase tracking-wider">
            <FileUp className="w-5 h-5" />
            <span>{data ? 'ATUALIZAR ARQUIVO' : 'IMPORTAR .XLSX'}</span>
            <input type="file" id="fileInput" accept=".xlsx, .xls" className="hidden" onChange={handleFileUpload} />
          </label>
        </div>
      </div>

      {data && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 animate-in fade-in slide-in-from-top-4 duration-500">
          <div className="bg-[#0A1121] rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden group">
            <div className="flex items-center gap-4 mb-4">
              <div className="p-3 bg-white/10 rounded-2xl">
                <Banknote className="w-6 h-6 text-[#E30613]" />
              </div>
              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">Faturamento Atual</span>
            </div>
            <p className="text-4xl font-black tracking-tighter transition-all duration-300">{formatCurrency(summary.total)}</p>
            <p className="text-[10px] mt-2 font-bold text-slate-500 uppercase">Auditando {data.pedidos.length} pedidos</p>
          </div>

          <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100 relative overflow-hidden">
            <div className="flex items-center gap-4 mb-4">
              <div className="p-3 bg-emerald-50 rounded-2xl">
                <TrendingUp className="w-6 h-6 text-emerald-600" />
              </div>
              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Margem R$ Auditada</span>
            </div>
            <p className="text-4xl font-black tracking-tighter text-slate-900 transition-all duration-300">{formatCurrency(summary.margem)}</p>
          </div>

          <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100 relative overflow-hidden">
            <div className="flex items-center gap-4 mb-4">
              <div className="p-3 bg-red-50 rounded-2xl">
                <Percent className="w-6 h-6 text-[#E30613]" />
              </div>
              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Margem % Auditada</span>
            </div>
            <p className={`text-5xl font-black tracking-tighter transition-all duration-300 ${summary.pct < 10 ? 'text-[#E30613]' : 'text-slate-900'}`}>
              {summary.pct.toFixed(2)}%
            </p>
          </div>
        </div>
      )}

      {loading ? (
        <div className="flex flex-col items-center py-64 text-slate-400">
          <div className="w-12 h-12 border-4 border-slate-100 border-t-[#E30613] rounded-full animate-spin mb-8"></div>
          <p className="font-black uppercase tracking-[0.5em] text-[10px] animate-pulse">Processando Consolidação...</p>
        </div>
