import { MesConferencia, HistoricoConsolidado } from '../types';

const STORAGE_KEY = 'abc_gestao_vendas_data';
const HISTORY_KEY = 'abc_gestao_vendas_history';

export const storageService = {
  // Dados de trabalho atual
  saveData: (data: MesConferencia) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  },
  getData: (): MesConferencia | null => {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : null;
  },
  clearData: () => {
    localStorage.removeItem(STORAGE_KEY);
  },

  // Histórico de meses fechados
  saveToHistory: (mes: MesConferencia) => {
    const history = storageService.getHistory();
    // Evita duplicatas do mesmo mês
    const filteredHistory = history.meses.filter(m => m.mesReferencia !== mes.mesReferencia);
    const newHistory: HistoricoConsolidado = {
      meses: [...filteredHistory, mes].sort((a, b) => b.mesReferencia.localeCompare(a.mesReferencia))
    };
    localStorage.setItem(HISTORY_KEY, JSON.stringify(newHistory));
  },
  getHistory: (): HistoricoConsolidado => {
    const data = localStorage.getItem(HISTORY_KEY);
    return data ? JSON.parse(data) : { meses: [] };
  },
  clearHistory: () => {
    localStorage.removeItem(HISTORY_KEY);
  }
};

