import { Pedido, MesConferencia } from '../types';
import { OrderTable } from '../components/OrderTable';
import { FileUp, CheckCircle2, Banknote, TrendingUp, Percent, DatabaseBackup } from 'lucide-react';

interface ConferenciaPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null) => void;
  onUpdatePedido: (id: string, updates: Partial<Pedido>) => void;
  onDeletePedido: (id: string) => void;
  onNavigateToAjustes: () => void;
}

export const ConferenciaPage: React.FC<ConferenciaPageProps> = ({ 
  data, 
  onSetData, 
  onUpdatePedido, 
  onDeletePedido,
  onNavigateToAjustes 
}) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const COL_MU = "Nº Pedido MU";
  const COL_DATA = "Data Faturamento";
  const COL_VENDEDOR = "Vendedor";
  const COL_TOTAL = "Total Pedido (R$)";
  const COL_CANAL = "Canal Venda";
  const COL_MARGEM_RS = "Margem líq. c/ frete";
  const COL_MARGEM_PCT = "Margem produto c/frete (%)";
  const COL_MKT = "Mkt";
  const COL_CAC = "CAC";

  const summary = useMemo(() => {
    if (!data || data.pedidos.length === 0) return { total: 0, margem: 0, pct: 0 };
    const total = data.pedidos.reduce((acc, curr) => acc + curr.total, 0);
    const margem = data.pedidos.reduce((acc, curr) => acc + curr.margemAjustada, 0);
    const pct = total > 0 ? (margem / total) * 100 : 0;
    return { total, margem, pct };
  }, [data]);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  };

  const toNumber = (val: any): number => {
    if (val === null || val === undefined || val === '' || val === '-') return 0;
    if (typeof val === 'number') return val;
    const cleaned = String(val)
      .replace(/R\$/g, '')
      .replace(/\./g, '')
      .replace(',', '.')
      .replace(/\s/g, '')
      .trim();
    const n = parseFloat(cleaned);
    return isNaN(n) ? 0 : n;
  };

  const toPercent = (val: any): number => {
    let n = toNumber(val);
    if (Math.abs(n) > 0 && Math.abs(n) < 1) return n * 100;
    return n;
  };

  const excelDateToBR = (serial: any): string => {
    if (!serial) return '';
    if (typeof serial === 'string') return serial;
    try {
      const date = new Date(Math.round((serial - 25569) * 86400 * 1000));
      return date.toLocaleDateString('pt-BR');
    } catch {
      return String(serial);
    }
  };

  const getActualKey = (firstRow: any, target: string): string => {
    const keys = Object.keys(firstRow);
    const found = keys.find(k => k.trim().toLowerCase() === target.toLowerCase());
    return found || target;
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json(worksheet, { defval: "" }) as any[];

        if (rows.length === 0) throw new Error("Planilha vazia");

        const firstRow = rows[0];
        const K = {
          MU: getActualKey(firstRow, COL_MU),
          DATA: getActualKey(firstRow, COL_DATA),
          VENDEDOR: getActualKey(firstRow, COL_VENDEDOR),
          TOTAL: getActualKey(firstRow, COL_TOTAL),
          CANAL: getActualKey(firstRow, COL_CANAL),
          MARGEM_RS: getActualKey(firstRow, COL_MARGEM_RS),
          MARGEM_PCT: getActualKey(firstRow, COL_MARGEM_PCT),
          MKT: getActualKey(firstRow, COL_MKT),
          CAC: getActualKey(firstRow, COL_CAC)
        };

        // Criar um mapa dos pedidos atuais para fazer o merge (Nº MU é a chave única)
        const mapa: Record<string, Pedido> = {};
        if (data) {
          data.pedidos.forEach(p => {
            mapa[p.id] = { ...p };
          });
        }

        let currentMU: string | null = null;

        rows.forEach(r => {
          const rawMU = String(r[K.MU] || "").trim();

          if (rawMU && !rawMU.toUpperCase().includes("TOTAL")) {
            currentMU = rawMU;

            // Se o pedido já existe, ele será atualizado com os novos dados da planilha
            // Se for novo, será criado
            mapa[currentMU] = {
              id: currentMU,
              data: excelDateToBR(r[K.DATA]),
              canal: String(r[K.CANAL] || "").trim(),
              vendedor: String(r[K.VENDEDOR] || "").trim(),
              mkt: toNumber(r[K.MKT]),
              cac: toNumber(r[K.CAC]),
              total: toNumber(r[K.TOTAL]),
              margemOriginal: toNumber(r[K.MARGEM_RS]),
              margemOriginalPct: toPercent(r[K.MARGEM_PCT]),
              // Mantém créditos/débitos se já existiam no mapa (auditoria em andamento)
              credito: mapa[currentMU]?.credito || 0,
              debito: mapa[currentMU]?.debito || 0,
              margemAjustada: toNumber(r[K.MARGEM_RS]) + (mapa[currentMU]?.credito || 0) - (mapa[currentMU]?.debito || 0),
              confirmado: mapa[currentMU]?.confirmado || false
            };
          } 
          else if (!rawMU && currentMU && mapa[currentMU]) {
            // Lógica de sub-itens ou linhas vazias que pertencem ao pedido anterior
            mapa[currentMU].mkt += toNumber(r[K.MKT]);
            mapa[currentMU].cac += toNumber(r[K.CAC]);
          }
        });

        const pedidos = Object.values(mapa);
        if (pedidos.length === 0) {
          setError(`Não encontramos a coluna "${COL_MU}" ou os dados estão inválidos.`);
        } else {
          const mesRef = data?.mesReferencia || new Date().toISOString().slice(0, 7);
          onSetData({ mesReferencia: mesRef, pedidos });
        }
      } catch (err) {
        setError("Erro fatal ao processar arquivo. Verifique se as colunas estão corretas.");
        console.error(err);
      } finally {
        setLoading(false);
        // Limpar input para permitir re-upload do mesmo arquivo se necessário
        event.target.value = "";
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleReset = () => {
    if(confirm("Deseja apagar todos os dados da auditoria atual? Isso não pode ser desfeito.")) {
      onSetData(null);
      setError(null);
    }
  };

  return (
    <div className="space-y-12">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div>
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Conferência</h2>
          <p className="text-[#E30613] font-bold mt-2 uppercase text-[11px] tracking-[0.3em]">Auditoria e Soma de Entradas</p>
        </div>
        <div className="flex items-center gap-4">
          {error && <span className="bg-red-50 text-[#E30613] px-4 py-2 rounded-lg font-bold text-xs border border-red-100">{error}</span>}

          {data && (
            <>
              <button 
                onClick={handleReset}
                className="text-slate-400 hover:text-red-600 font-black uppercase text-[10px] tracking-widest transition-colors mr-4"
              >
                Limpar Sessão Atual
              </button>
              <button 
                onClick={onNavigateToAjustes}
                className="flex items-center gap-4 px-10 py-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl shadow-xl shadow-emerald-100 transition-all active:scale-95 font-black text-sm uppercase tracking-wider"
              >
                <CheckCircle2 className="w-5 h-5" />
                CONCLUIR AJUSTES
              </button>
            </>
          )}

          <label className="flex items-center gap-4 px-10 py-5 bg-[#E30613] hover:bg-red-700 text-white rounded-2xl cursor-pointer transition-all shadow-2xl shadow-red-100 active:scale-95 font-black text-sm uppercase tracking-wider">
            <FileUp className="w-5 h-5" />
            <span>{data ? 'SOMAR MAIS PLANILHAS' : 'IMPORTAR PLANILHA'}</span>
            <input type="file" id="fileInput" accept=".xlsx, .xls" className="hidden" onChange={handleFileUpload} />
          </label>
        </div>
      </div>

      {data && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 animate-in fade-in slide-in-from-top-4 duration-500">
          <div className="bg-[#0A1121] rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden">
             <div className="flex items-center gap-4 mb-4">
              <div className="p-2 bg-white/10 rounded-xl"><Banknote className="w-5 h-5 text-[#E30613]" /></div>
              <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">Total Vendas (Acumulado)</span>
            </div>
            <p className="text-3xl font-black tracking-tighter">{formatCurrency(summary.total)}</p>
          </div>

          <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100">
            <div className="flex items-center gap-4 mb-4">
              <div className="p-2 bg-emerald-50 rounded-xl"><TrendingUp className="w-5 h-5 text-emerald-600" /></div>
              <span className="text-[9px] font-black uppercase tracking-widest text-slate-500">Margem R$ Auditada</span>
            </div>
            <p className="text-3xl font-black tracking-tighter text-slate-900">{formatCurrency(summary.margem)}</p>
          </div>

          <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100">
            <div className="flex items-center gap-4 mb-4">
              <div className="p-2 bg-red-50 rounded-xl"><Percent className="w-5 h-5 text-[#E30613]" /></div>
              <span className="text-[9px] font-black uppercase tracking-widest text-slate-500">Margem % Atual</span>
            </div>
            <p className={`text-3xl font-black tracking-tighter ${summary.pct < 10 ? 'text-[#E30613]' : 'text-slate-900'}`}>
              {summary.pct.toFixed(2)}%
            </p>
          </div>

          <div className="bg-slate-50 border border-slate-200 rounded-[2.5rem] p-8 flex flex-col justify-center items-center text-center">
             <DatabaseBackup className="w-8 h-8 text-slate-300 mb-2" />
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Base de Dados Atual</p>
             <p className="text-lg font-black text-slate-600">{data.pedidos.length} Pedidos</p>
          </div>
        </div>
      )}

      {loading ? (
        <div className="flex flex-col items-center py-64 text-slate-400">
          <div className="w-12 h-12 border-4 border-slate-100 border-t-[#E30613] rounded-full animate-spin mb-8"></div>
          <p className="font-black uppercase tracking-[0.5em] text-[10px] animate-pulse">Mesclando dados e somando valores...</p>
        </div>
      ) : !data ? (
        <div className="bg-white border-2 border-dashed border-slate-200 rounded-[4rem] py-64 flex flex-col items-center justify-center text-slate-300">
          <FileUp className="w-24 h-24 mb-10 opacity-20" />
          <p className="text-3xl font-black text-slate-800 tracking-tight">Pronto para Somar</p>
          <p className="text-sm mt-4 font-bold uppercase tracking-widest opacity-40 text-center">Importe uma ou mais planilhas de faturamento</p>
        </div>
      ) : (
        <div className="animate-in fade-in slide-in-from-bottom-6 duration-700">
          <OrderTable 
            data={data.pedidos} 
            onUpdatePedido={onUpdatePedido} 
            onDeletePedido={onDeletePedido}
          />
        </div>
      )}
    </div>
  );
};

import React, { useMemo } from 'react';
import { HistoricoConsolidado } from '../types';
import { Banknote, TrendingUp, Percent, Calendar, ShoppingBag, ArrowUpRight } from 'lucide-react';

interface DashboardPageProps {
  history: HistoricoConsolidado;
}

export const DashboardPage: React.FC<DashboardPageProps> = ({ history }) => {
  const stats = useMemo(() => {
    let totalVendas = 0;
    let totalMargem = 0;
    let totalPedidos = 0;

    history.meses.forEach(mes => {
      mes.pedidos.forEach(p => {
        totalVendas += p.total;
        totalMargem += p.margemAjustada;
        totalPedidos++;
      });
    });

    const margemPct = totalVendas > 0 ? (totalMargem / totalVendas) * 100 : 0;

    return { totalVendas, totalMargem, totalPedidos, margemPct };
  }, [history]);

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  return (
    <div className="space-y-12">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div>
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Dashboard</h2>
          <p className="text-[#E30613] font-bold mt-2 uppercase text-[11px] tracking-[0.3em]">Visão Consolidada de Faturamento e Margens</p>
        </div>
        <div className="bg-emerald-50 px-6 py-4 rounded-3xl border border-emerald-100 flex items-center gap-4">
          <div className="p-2 bg-emerald-500 rounded-xl text-white">
            <ArrowUpRight className="w-5 h-5" />
          </div>
          <div>
            <p className="text-[9px] font-black text-emerald-800 uppercase tracking-widest">Base de Dados</p>
            <p className="text-sm font-black text-emerald-900 uppercase tracking-tighter">{history.meses.length} Meses Históricos</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-[#0A1121] rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden group">
          <div className="absolute -right-4 -bottom-4 w-32 h-32 bg-white/5 rounded-full blur-2xl group-hover:scale-125 transition-transform duration-700"></div>
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-white/10 rounded-2xl"><Banknote className="w-6 h-6 text-[#E30613]" /></div>
            <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Faturamento Global</span>
          </div>
          <p className="text-3xl font-black tracking-tighter">{formatCurrency(stats.totalVendas)}</p>
        </div>

        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-emerald-50 rounded-2xl"><TrendingUp className="w-6 h-6 text-emerald-600" /></div>
            <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">Margem Acumulada</span>
          </div>
          <p className="text-3xl font-black tracking-tighter text-slate-900">{formatCurrency(stats.totalMargem)}</p>
        </div>

        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-red-50 rounded-2xl"><Percent className="w-6 h-6 text-[#E30613]" /></div>
            <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">Performance Média</span>
          </div>
          <p className="text-3xl font-black tracking-tighter text-slate-900">{stats.margemPct.toFixed(2)}%</p>
        </div>

        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-blue-50 rounded-2xl"><ShoppingBag className="w-6 h-6 text-blue-600" /></div>
            <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">Pedidos Auditados</span>
          </div>
          <p className="text-3xl font-black tracking-tighter text-slate-900">{stats.totalPedidos}</p>
        </div>
      </div>

      <div className="space-y-6">
        <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight flex items-center gap-3">
          <Calendar className="w-6 h-6 text-[#E30613]" />
          Histórico por Mês de Referência
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {history.meses.length === 0 ? (
            <div className="col-span-full py-20 bg-slate-50 rounded-[3rem] border-2 border-dashed border-slate-200 text-center">
              <p className="text-slate-400 font-black uppercase text-[10px] tracking-widest">Nenhum mês consolidado ainda</p>
            </div>
          ) : (
            history.meses.map(mes => {
              const totalM = mes.pedidos.reduce((a, b) => a + b.total, 0);
              const margemM = mes.pedidos.reduce((a, b) => a + b.margemAjustada, 0);
              return (
                <div key={mes.mesReferencia} className="bg-white border border-slate-200 rounded-[2.5rem] p-8 hover:border-[#E30613] transition-all group shadow-sm hover:shadow-xl">
                  <div className="flex justify-between items-start mb-6">
                    <span className="px-4 py-1.5 bg-slate-100 rounded-full text-[10px] font-black text-slate-500 uppercase tracking-tighter">
                      MÊS REF: {mes.mesReferencia}
                    </span>
                    <div className="flex items-center gap-1.5">
                      <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full"></div>
                      <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">CONSOLIDADO</span>
                    </div>
                  </div>
                  <div className="space-y-4">
                    <div>
                      <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Vendas Totais</p>
                      <p className="text-xl font-black text-slate-900">{formatCurrency(totalM)}</p>
                    </div>
                    <div className="flex justify-between items-end border-t border-slate-50 pt-4">
                      <div>
                        <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Margem Líquida</p>
                        <p className="text-lg font-black text-emerald-600">{formatCurrency(margemM)}</p>
                      </div>
                      <div className="text-right">
                         <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Resultado %</p>
                         <p className="text-2xl font-black text-slate-300">{(totalM > 0 ? (margemM / totalM) * 100 : 0).toFixed(1)}%</p>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>
    </div>
  );
};

import { MesConferencia, HistoricoConsolidado, Pedido } from '../types';

const STORAGE_KEY = 'abc_gestao_vendas_data';
const HISTORY_KEY = 'abc_gestao_vendas_history';

export const storageService = {
  // Dados de trabalho atual (Staging)
  saveData: (data: MesConferencia) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  },
  getData: (): MesConferencia | null => {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : null;
  },
  clearData: () => {
    localStorage.removeItem(STORAGE_KEY);
  },

  // Histórico de meses fechados (Consolidado)
  saveToHistory: (mes: MesConferencia) => {
    const history = storageService.getHistory();

    // Busca se já existe este mês no histórico
    const existingMonthIndex = history.meses.findIndex(m => m.mesReferencia === mes.mesReferencia);

    if (existingMonthIndex > -1) {
      // MERGE de pedidos: Se o pedido já existe, atualiza. Se não, adiciona.
      const pMap = new Map<string, Pedido>();

      // Carrega pedidos existentes do histórico
      history.meses[existingMonthIndex].pedidos.forEach(p => pMap.set(p.id, p));

      // Mescla com os novos pedidos validados agora
      mes.pedidos.forEach(p => {
        pMap.set(p.id, p);
      });

      history.meses[existingMonthIndex].pedidos = Array.from(pMap.values());
    } else {
      // Mês novo, apenas adiciona
      history.meses.push(mes);
    }

    // Ordena o histórico por data (mais recente primeiro)
    history.meses.sort((a, b) => b.mesReferencia.localeCompare(a.mesReferencia));

    localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
  },

  getHistory: (): HistoricoConsolidado => {
    const data = localStorage.getItem(HISTORY_KEY);
    return data ? JSON.parse(data) : { meses: [] };
  },

  clearHistory: () => {
    localStorage.removeItem(HISTORY_KEY);
  },

  // Limpeza total
  clearAll: () => {
    localStorage.removeItem(STORAGE_KEY);
    localStorage.removeItem(HISTORY_KEY);
  }
};

import React, { useState, useMemo, useEffect } from 'react';
import * as XLSX from 'xlsx';
import { Pedido, MesConferencia } from '../types';
import { OrderTable } from '../components/OrderTable';
import { FileUp, CheckCircle2, Banknote, TrendingUp, Percent, DatabaseBackup, Calendar } from 'lucide-react';

interface ConferenciaPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null) => void;
  onUpdatePedido: (id: string, updates: Partial<Pedido>) => void;
  onDeletePedido: (id: string) => void;
  onNavigateToAjustes: () => void;
}

export const ConferenciaPage: React.FC<ConferenciaPageProps> = ({ 
  data, 
  onSetData, 
  onUpdatePedido, 
  onDeletePedido,
  onNavigateToAjustes 
}) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Estado local para o mês selecionado antes ou durante a conferência
  const [selectedMonth, setSelectedMonth] = useState(data?.mesReferencia || new Date().toISOString().slice(0, 7));

  useEffect(() => {
    if (data?.mesReferencia) {
      setSelectedMonth(data.mesReferencia);
    }
  }, [data?.mesReferencia]);

  const COL_MU = "Nº Pedido MU";
  const COL_DATA = "Data Faturamento";
  const COL_VENDEDOR = "Vendedor";
  const COL_TOTAL = "Total Pedido (R$)";
  const COL_CANAL = "Canal Venda";
  const COL_MARGEM_RS = "Margem líq. c/ frete";
  const COL_MARGEM_PCT = "Margem produto c/frete (%)";
  const COL_MKT = "Mkt";
  const COL_CAC = "CAC";

  const summary = useMemo(() => {
    if (!data || data.pedidos.length === 0) return { total: 0, margem: 0, pct: 0 };
    const total = data.pedidos.reduce((acc, curr) => acc + curr.total, 0);
    const margem = data.pedidos.reduce((acc, curr) => acc + curr.margemAjustada, 0);
    const pct = total > 0 ? (margem / total) * 100 : 0;
    return { total, margem, pct };
  }, [data]);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  };

  const toNumber = (val: any): number => {
    if (val === null || val === undefined || val === '' || val === '-') return 0;
    if (typeof val === 'number') return val;
    const cleaned = String(val)
      .replace(/R\$/g, '')
      .replace(/\./g, '')
      .replace(',', '.')
      .replace(/\s/g, '')
      .trim();
    const n = parseFloat(cleaned);
    return isNaN(n) ? 0 : n;
  };

  const toPercent = (val: any): number => {
    let n = toNumber(val);
    if (Math.abs(n) > 0 && Math.abs(n) < 1) return n * 100;
    return n;
  };

  const excelDateToBR = (serial: any): string => {
    if (!serial) return '';
    if (typeof serial === 'string') return serial;
    try {
      const date = new Date(Math.round((serial - 25569) * 86400 * 1000));
      return date.toLocaleDateString('pt-BR');
    } catch {
      return String(serial);
    }
  };

  const getActualKey = (firstRow: any, target: string): string => {
    const keys = Object.keys(firstRow);
    const found = keys.find(k => k.trim().toLowerCase() === target.toLowerCase());
    return found || target;
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json(worksheet, { defval: "" }) as any[];

        if (rows.length === 0) throw new Error("Planilha vazia");

        const firstRow = rows[0];
        const K = {
          MU: getActualKey(firstRow, COL_MU),
          DATA: getActualKey(firstRow, COL_DATA),
          VENDEDOR: getActualKey(firstRow, COL_VENDEDOR),
          TOTAL: getActualKey(firstRow, COL_TOTAL),
          CANAL: getActualKey(firstRow, COL_CANAL),
          MARGEM_RS: getActualKey(firstRow, COL_MARGEM_RS),
          MARGEM_PCT: getActualKey(firstRow, COL_MARGEM_PCT),
          MKT: getActualKey(firstRow, COL_MKT),
          CAC: getActualKey(firstRow, COL_CAC)
        };

        const mapa: Record<string, Pedido> = {};
        if (data) {
          data.pedidos.forEach(p => {
            mapa[p.id] = { ...p };
          });
        }

        let currentMU: string | null = null;

        rows.forEach(r => {
          const rawMU = String(r[K.MU] || "").trim();

          if (rawMU && !rawMU.toUpperCase().includes("TOTAL")) {
            currentMU = rawMU;
            mapa[currentMU] = {
              id: currentMU,
              data: excelDateToBR(r[K.DATA]),
              canal: String(r[K.CANAL] || "").trim(),
              vendedor: String(r[K.VENDEDOR] || "").trim(),
              mkt: toNumber(r[K.MKT]),
              cac: toNumber(r[K.CAC]),
              total: toNumber(r[K.TOTAL]),
              margemOriginal: toNumber(r[K.MARGEM_RS]),
              margemOriginalPct: toPercent(r[K.MARGEM_PCT]),
              credito: mapa[currentMU]?.credito || 0,
              debito: mapa[currentMU]?.debito || 0,
              margemAjustada: toNumber(r[K.MARGEM_RS]) + (mapa[currentMU]?.credito || 0) - (mapa[currentMU]?.debito || 0),
              confirmado: mapa[currentMU]?.confirmado || false
            };
          } 
          else if (!rawMU && currentMU && mapa[currentMU]) {
            mapa[currentMU].mkt += toNumber(r[K.MKT]);
            mapa[currentMU].cac += toNumber(r[K.CAC]);
          }
        });

        const pedidos = Object.values(mapa);
        if (pedidos.length === 0) {
          setError(`Não encontramos a coluna "${COL_MU}" ou os dados estão inválidos.`);
        } else {
          onSetData({ mesReferencia: selectedMonth, pedidos });
        }
      } catch (err) {
        setError("Erro fatal ao processar arquivo.");
        console.error(err);
      } finally {
        setLoading(false);
        event.target.value = "";
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleMonthChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newMonth = e.target.value;
    setSelectedMonth(newMonth);
    if (data) {
      onSetData({ ...data, mesReferencia: newMonth });
    }
  };

  const handleReset = () => {
    if(confirm("Deseja apagar todos os dados da auditoria atual? Isso não pode ser desfeito.")) {
      onSetData(null);
      setError(null);
    }
  };

  return (
    <div className="space-y-12">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="flex flex-col gap-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Conferência</h2>
          <div className="flex items-center gap-3">
            <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Auditoria de Entradas para:</p>
            <div className="relative group">
              <input 
                type="month" 
                value={selectedMonth}
                onChange={handleMonthChange}
                className="bg-slate-100 border border-slate-200 rounded-xl px-4 py-1.5 text-xs font-black uppercase text-slate-700 focus:ring-4 focus:ring-[#E30613]/10 outline-none transition-all cursor-pointer hover:bg-white"
              />
              <Calendar className="absolute right-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-400 pointer-events-none" />
            </div>
          </div>
        </div>
        <div className="flex items-center gap-4">
          {error && <span className="bg-red-50 text-[#E30613] px-4 py-2 rounded-lg font-bold text-xs border border-red-100">{error}</span>}

          {data && (
            <>
              <button 
                onClick={handleReset}
                className="text-slate-400 hover:text-red-600 font-black uppercase text-[10px] tracking-widest transition-colors mr-4"
              >
                Limpar Sessão
              </button>
              <button 
                onClick={onNavigateToAjustes}
                className="flex items-center gap-4 px-10 py-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl shadow-xl shadow-emerald-100 transition-all active:scale-95 font-black text-sm uppercase tracking-wider"
              >
                <CheckCircle2 className="w-5 h-5" />
                CONCLUIR AJUSTES
              </button>
            </>
          )}

          <label className="flex items-center gap-4 px-10 py-5 bg-[#E30613] hover:bg-red-700 text-white rounded-2xl cursor-pointer transition-all shadow-2xl shadow-red-100 active:scale-95 font-black text-sm uppercase tracking-wider">
            <FileUp className="w-5 h-5" />
            <span>{data ? 'SOMAR MAIS PLANILHAS' : 'IMPORTAR PLANILHA'}</span>
            <input type="file" id="fileInput" accept=".xlsx, .xls" className="hidden" onChange={handleFileUpload} />
          </label>
        </div>
      </div>

      {data && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 animate-in fade-in slide-in-from-top-4 duration-500">
          <div className="bg-[#0A1121] rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden">
             <div className="flex items-center gap-4 mb-4">
              <div className="p-2 bg-white/10 rounded-xl"><Banknote className="w-5 h-5 text-[#E30613]" /></div>
              <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">Total Vendas (Desta Sessão)</span>
            </div>
            <p className="text-3xl font-black tracking-tighter">{formatCurrency(summary.total)}</p>
          </div>

          <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100">
            <div className="flex items-center gap-4 mb-4">
              <div className="p-2 bg-emerald-50 rounded-xl"><TrendingUp className="w-5 h-5 text-emerald-600" /></div>
              <span className="text-[9px] font-black uppercase tracking-widest text-slate-500">Margem R$ Auditada</span>
            </div>
            <p className="text-3xl font-black tracking-tighter text-slate-900">{formatCurrency(summary.margem)}</p>
          </div>

          <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100">
            <div className="flex items-center gap-4 mb-4">
              <div className="p-2 bg-red-50 rounded-xl"><Percent className="w-5 h-5 text-[#E30613]" /></div>
              <span className="text-[9px] font-black uppercase tracking-widest text-slate-500">Margem % Atual</span>
            </div>
            <p className={`text-3xl font-black tracking-tighter ${summary.pct < 10 ? 'text-[#E30613]' : 'text-slate-900'}`}>
              {summary.pct.toFixed(2)}%
            </p>
          </div>

          <div className="bg-slate-50 border border-slate-200 rounded-[2.5rem] p-8 flex flex-col justify-center items-center text-center">
             <DatabaseBackup className="w-8 h-8 text-slate-300 mb-2" />
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Base de Dados Atual</p>
             <p className="text-lg font-black text-slate-600">{data.pedidos.length} Pedidos</p>
          </div>
        </div>
      )}

      {loading ? (
        <div className="flex flex-col items-center py-64 text-slate-400">
          <div className="w-12 h-12 border-4 border-slate-100 border-t-[#E30613] rounded-full animate-spin mb-8"></div>
          <p className="font-black uppercase tracking-[0.5em] text-[10px] animate-pulse">Processando faturamento...</p>
        </div>
      ) : !data ? (
        <div className="bg-white border-2 border-dashed border-slate-200 rounded-[4rem] py-64 flex flex-col items-center justify-center text-slate-300">
          <FileUp className="w-24 h-24 mb-10 opacity-20" />
          <p className="text-3xl font-black text-slate-800 tracking-tight">Pronto para Auditar</p>
          <p className="text-sm mt-4 font-bold uppercase tracking-widest opacity-40 text-center">Importe planilhas para o mês de {selectedMonth}</p>
        </div>
      ) : (
        <div className="animate-in fade-in slide-in-from-bottom-6 duration-700">
          <OrderTable 
            data={data.pedidos} 
            onUpdatePedido={onUpdatePedido} 
            onDeletePedido={onDeletePedido}
          />
        </div>
      )}
    </div>
  );
};

