                    className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-black text-slate-900 focus:ring-4 focus:ring-red-500/10 outline-none transition-all text-right"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Beneficiário / Descrição</label>
                <input 
                  type="text" 
                  required
                  placeholder="Ex: Fornecedor X, Aluguel, Pro-labore..."
                  value={newConta.beneficiario}
                  onChange={(e) => setNewConta({...newConta, beneficiario: e.target.value})}
                  className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-slate-900 focus:ring-4 focus:ring-red-500/10 outline-none transition-all"
                />
              </div>

              <div className="flex items-center gap-4 bg-slate-50 p-6 rounded-[1.5rem] border border-slate-100">
                <input 
                  type="checkbox" 
                  id="pago"
                  checked={newConta.pago}
                  onChange={(e) => setNewConta({...newConta, pago: e.target.checked})}
                  className="w-5 h-5 accent-[#E30613]"
                />
                <label htmlFor="pago" className="text-xs font-black text-slate-700 uppercase tracking-tight cursor-pointer">Marcar como JÁ PAGO</label>
              </div>

              <button
                type="submit"
                className="w-full py-6 bg-[#E30613] hover:bg-red-700 text-white rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl shadow-red-200 transition-all active:scale-95 flex items-center justify-center gap-3"
              >
                SALVAR LANÇAMENTO
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Sidebar } from './components/Sidebar';
import { ConferenciaPage } from './pages/ConferenciaPage';
import { AjustesFinaisPage } from './pages/AjustesFinaisPage';
import { DashboardPage } from './pages/DashboardPage';
import { AnaliseVendedorPage } from './pages/AnaliseVendedorPage';
import { ConfiguracaoPage } from './pages/ConfiguracaoPage';
import { ContasPagarPage } from './pages/ContasPagarPage';
import { PageId, MesConferencia, Pedido, HistoricoConsolidado } from './types';
import { Construction, Sparkles, Database } from 'lucide-react';
import { storageService } from './services/storageService';

const App: React.FC = () => {
  const [activePage, setActivePage] = useState<PageId>('dashboard');
  const [data, setData] = useState<MesConferencia | null>(storageService.getData());
  const [history, setHistory] = useState<HistoricoConsolidado>(storageService.getHistory());
  const [showToast, setShowToast] = useState<{show: boolean, msg: string, type: 'success' | 'danger'}>({show: false, msg: '', type: 'success'});

  const refreshData = useCallback((newData: MesConferencia | null) => {
    if (newData) {
      storageService.saveData(newData);
    } else {
      storageService.clearData();
    }
    setData(newData);
  }, []);

  const handleUpdatePedido = useCallback((id: string, updates: Partial<Pedido>) => {
    setData(current => {
      if (!current) return null;
      const newPedidos = current.pedidos.map((p) => {
        if (p.id === id) {
          const updated = { ...p, ...updates };
          updated.margemAjustada = updated.margemOriginal + (updated.credito || 0) - (updated.debito || 0);
          return updated;
        }
        return p;
      });
      const updatedData = { ...current, pedidos: newPedidos };
      storageService.saveData(updatedData);
      return updatedData;
    });
  }, []);

  const handleDeletePedido = useCallback((id: string) => {
    setData(current => {
      if (!current) return null;
      const newPedidos = current.pedidos.filter(p => p.id !== id);
      const updatedData = { ...current, pedidos: newPedidos };
      storageService.saveData(updatedData);
      return updatedData;
    });
  }, []);

  const handleSetData = (newData: MesConferencia | null) => {
    refreshData(newData);
  };

  const handleCloseMonth = (consolidated: MesConferencia) => {
    storageService.saveToHistory(consolidated);
    storageService.clearData();
    setData(null);
    setHistory(storageService.getHistory());
    setActivePage('dashboard');
    setShowToast({show: true, msg: 'Mês consolidado no Dashboard!', type: 'success'});
    setTimeout(() => setShowToast({show: false, msg: '', type: 'success'}), 4000);
  };

  const handleClearDatabase = () => {
    storageService.clearAll();
    setData(null);
    setHistory({ meses: [] });
    setActivePage('dashboard');
    setShowToast({show: true, msg: 'Banco de dados resetado com sucesso!', type: 'danger'});
    setTimeout(() => setShowToast({show: false, msg: '', type: 'success'}), 4000);
  };

  const renderComingSoon = (title: string) => (
    <div className="flex flex-col items-center justify-center h-[70vh] text-center space-y-8 animate-in fade-in duration-700">
      <div className="bg-slate-100 p-12 rounded-[4rem] shadow-inner">
        <Construction className="w-24 h-24 text-slate-300 animate-bounce" />
      </div>
      <div className="space-y-2">
        <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">{title}</h2>
        <p className="text-slate-400 font-bold uppercase tracking-[0.3em] text-[10px]">Módulo em Desenvolvimento</p>
      </div>
      <p className="max-w-md text-slate-500 font-medium leading-relaxed">
        Estamos preparando uma experiência incrível para este módulo. Em breve você terá acesso completo a esta funcionalidade.
      </p>
    </div>
  );

  const renderPage = () => {
    switch (activePage) {
      case 'dashboard': 
        return <DashboardPage history={history} />;
      case 'conferencia': 
        return (
          <ConferenciaPage 
            data={data} 
            onSetData={handleSetData}
            onUpdatePedido={handleUpdatePedido}
            onDeletePedido={handleDeletePedido}
            onNavigateToAjustes={() => setActivePage('ajustes')} 
          />
        );
      case 'ajustes': 
        return (
          <AjustesFinaisPage 
            data={data} 
            onDeletePedido={handleDeletePedido}
            onCloseMonth={handleCloseMonth}
          />
        );
      case 'analise-vendedor': 
        return <AnaliseVendedorPage history={history} />;
      case 'contas-pagar':
        return <ContasPagarPage />;
      case 'configuracao':
        return <ConfiguracaoPage onClearDatabase={handleClearDatabase} />;
      case 'comissao': return renderComingSoon('Cálculo de Comissões');
      case 'fluxo-caixa': return renderComingSoon('Fluxo de Caixa');
      case 'dre': return renderComingSoon('DRE - Demonstrativo de Resultado');
      default: 
        return <DashboardPage history={history} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex selection:bg-red-100 selection:text-red-900 antialiased">
      <Sidebar activePage={activePage} setActivePage={setActivePage} />

      <main className="flex-grow flex flex-col min-w-0">
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-40 flex items-center justify-between px-12">
          <div className="flex items-center gap-3">
            <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(16,185,129,0.5)]"></div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sistemas Itu — Online</p>
          </div>

          <div className="flex items-center gap-6">
            <div className="h-8 w-px bg-slate-200"></div>
            <div className="flex items-center gap-2 px-4 py-2 bg-slate-50 rounded-full border border-slate-100">
              <span className={`w-1.5 h-1.5 ${history.meses.length > 0 ? 'bg-emerald-500' : 'bg-slate-300'} rounded-full`}></span>
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-tighter">
                {history.meses.length} Meses Consolidados
              </span>
            </div>
          </div>
        </header>

        {showToast.show && (
          <div className="fixed top-24 right-12 z-[250] animate-in slide-in-from-right-8 fade-in duration-500">
            <div className={`${showToast.type === 'success' ? 'bg-emerald-600' : 'bg-[#E30613]'} text-white px-8 py-5 rounded-3xl shadow-2xl flex items-center gap-4 border-2 border-white/20`}>
              <div className="bg-white/20 p-2 rounded-xl">
                {showToast.type === 'success' ? <Sparkles className="w-5 h-5" /> : <Database className="w-5 h-5" />}
              </div>
              <div>
                <p className="font-black text-xs uppercase tracking-widest">Aviso do Sistema</p>
                <p className="text-[10px] font-bold opacity-80 uppercase">{showToast.msg}</p>
              </div>
            </div>
          </div>
        )}

        <div className="p-8 lg:p-12">
          <div className="bg-white p-10 rounded-[4rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.06)] border border-slate-200/50 min-h-[75vh]">
            {renderPage()}
          </div>
        </div>

        <footer className="mt-auto py-12 px-12 border-t border-slate-100 bg-white/50">
          <div className="flex flex-col md:flex-row justify-between items-center gap-6">
            <div className="flex items-center gap-4">
              <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.4em]">ABC da Construção Itu &copy; {new Date().getFullYear()}</p>
            </div>
            <div className="flex items-center gap-8 text-[9px] font-black text-slate-300 uppercase tracking-[0.5em]">
              <span>Plataforma de Auditoria V2.5</span>
            </div>
          </div>
        </footer>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Plus, CreditCard, Banknote, Clock, CheckCircle2, Trash2, Calendar, Search, ChevronLeft, ChevronRight } from 'lucide-react';
import { ContaPagar } from '../types';
import { storageService } from '../services/storageService';

export const ContasPagarPage: React.FC = () => {
  const [contas, setContas] = useState<ContaPagar[]>(storageService.getContasPagar());
  const [showModal, setShowModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Estado para o mês de referência (formato YYYY-MM)
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));

  // Form State
  const [newConta, setNewConta] = useState<Partial<ContaPagar>>({
    dataPagamento: new Date().toISOString().split('T')[0],
    beneficiario: '',
    valor: 0,
    pago: false
  });

  useEffect(() => {
    storageService.saveContasPagar(contas);
  }, [contas]);

  // Filtra as contas pelo mês selecionado e pelo termo de busca
  const filteredData = useMemo(() => {
    const monthContas = contas.filter(c => c.dataPagamento.startsWith(selectedMonth));

    const searchContas = monthContas.filter(c => 
      c.beneficiario.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return searchContas.sort((a, b) => a.dataPagamento.localeCompare(b.dataPagamento));
  }, [contas, selectedMonth, searchTerm]);

  // Estatísticas baseadas APENAS no mês selecionado
  const stats = useMemo(() => {
    const monthContas = contas.filter(c => c.dataPagamento.startsWith(selectedMonth));
    const total = monthContas.reduce((acc, c) => acc + c.valor, 0);
    const pago = monthContas.filter(c => c.pago).reduce((acc, c) => acc + c.valor, 0);
    const pendente = total - pago;
    return { total, pago, pendente, count: monthContas.length };
  }, [contas, selectedMonth]);

  const handleAddConta = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newConta.beneficiario || !newConta.valor) return;

    const conta: ContaPagar = {
      id: crypto.randomUUID(),
      dataCadastro: new Date().toLocaleDateString('pt-BR'),
      dataPagamento: newConta.dataPagamento || '',
      beneficiario: newConta.beneficiario || '',
      valor: newConta.valor || 0,
      pago: newConta.pago || false
    };

    setContas([...contas, conta]);
    setShowModal(false);

    // Se a data de pagamento for de outro mês, avisa ou muda o foco? 
    // Vamos apenas manter o foco no mês que o usuário está vendo para não confundir.

    setNewConta({
      dataPagamento: new Date().toISOString().split('T')[0],
      beneficiario: '',
      valor: 0,
      pago: false
    });
  };

  const toggleStatus = (id: string) => {
    setContas(contas.map(c => c.id === id ? { ...c, pago: !c.pago } : c));
  };

  const deleteConta = (id: string) => {
    if (confirm('Deseja realmente remover este lançamento?')) {
      setContas(contas.filter(c => c.id !== id));
    }
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const getMonthName = (monthStr: string) => {
    const [year, month] = monthStr.split('-');
    const date = new Date(parseInt(year), parseInt(month) - 1);
    return date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' }).toUpperCase();
  };

  const changeMonth = (offset: number) => {
    const [year, month] = selectedMonth.split('-');
    const date = new Date(parseInt(year), parseInt(month) - 1 + offset);
    setSelectedMonth(date.toISOString().slice(0, 7));
  };

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Financeiro</h2>
          <div className="flex items-center gap-4">
             <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Gestão de Contas a Pagar — </p>
             <div className="flex items-center gap-2 bg-slate-100 px-3 py-1 rounded-xl border border-slate-200">
                <button onClick={() => changeMonth(-1)} className="hover:text-[#E30613] transition-colors"><ChevronLeft className="w-4 h-4" /></button>
                <input 
                  type="month" 
                  value={selectedMonth}
                  onChange={(e) => setSelectedMonth(e.target.value)}
                  className="bg-transparent text-[10px] font-black uppercase outline-none cursor-pointer text-slate-700"
                />
                <button onClick={() => changeMonth(1)} className="hover:text-[#E30613] transition-colors"><ChevronRight className="w-4 h-4" /></button>
             </div>
          </div>
        </div>

        <button
          onClick={() => setShowModal(true)}
          className="flex items-center gap-4 px-10 py-5 bg-[#E30613] hover:bg-red-700 text-white rounded-2xl shadow-2xl shadow-red-100 transition-all active:scale-95 font-black text-sm uppercase tracking-wider"
        >
          <Plus className="w-5 h-5" />
          ADICIONAR CONTA
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="bg-[#0A1121] rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden group">
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-white/10 rounded-2xl"><Banknote className="w-6 h-6 text-[#E30613]" /></div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">Total {getMonthName(selectedMonth)}</span>
          </div>
          <p className="text-4xl font-black tracking-tighter">{formatCurrency(stats.total)}</p>
          <p className="text-[9px] mt-2 font-bold text-slate-500 uppercase tracking-widest">{stats.count} lançamentos neste período</p>
        </div>

        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100">
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-red-50 rounded-2xl"><Clock className="w-6 h-6 text-[#E30613]" /></div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Pendente no Mês</span>
          </div>
          <p className="text-4xl font-black tracking-tighter text-[#E30613]">{formatCurrency(stats.pendente)}</p>
        </div>

        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100">
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-emerald-50 rounded-2xl"><CheckCircle2 className="w-6 h-6 text-emerald-600" /></div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Total Pago</span>
          </div>
          <p className="text-4xl font-black tracking-tighter text-emerald-600">{formatCurrency(stats.pago)}</p>
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-[3rem] shadow-xl overflow-hidden">
        <div className="p-8 border-b border-slate-100 bg-slate-50/30 flex items-center justify-between">
          <div className="flex items-center gap-4">
             <div className="bg-white p-2 rounded-xl border border-slate-200">
                <Calendar className="w-4 h-4 text-slate-400" />
             </div>
             <h3 className="text-sm font-black text-slate-900 uppercase tracking-tight">Listagem de Compromissos</h3>
          </div>
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            <input 
              type="text" 
              placeholder="Buscar beneficiário..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-12 pr-6 py-3 bg-white border border-slate-200 rounded-2xl text-xs font-bold outline-none focus:ring-4 focus:ring-red-500/10 transition-all"
            />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 text-slate-400 border-b border-slate-100">
                <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest">Cadastro</th>
                <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest">Vencimento</th>
                <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest">Beneficiário</th>
                <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-right">Valor</th>
                <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-center">Status</th>
                <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-center">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredData.length === 0 ? (
                <tr>
                  <td colSpan={6} className="px-10 py-24 text-center">
                    <div className="flex flex-col items-center gap-4">
                       <CreditCard className="w-12 h-12 text-slate-200" />
                       <p className="text-slate-300 font-black uppercase tracking-[0.2em] text-xs">
                          Nenhum lançamento para {getMonthName(selectedMonth)}
                       </p>
                    </div>
                  </td>
                </tr>
              ) : (
                filteredData.map(c => (
                  <tr key={c.id} className={`hover:bg-slate-50/50 transition-all ${c.pago ? 'opacity-60' : ''}`}>
                    <td className="px-10 py-6 text-xs font-bold text-slate-400 uppercase">{c.dataCadastro}</td>
                    <td className="px-10 py-6 text-xs font-black text-slate-900 uppercase">
                      {new Date(c.dataPagamento).toLocaleDateString('pt-BR')}
                    </td>
                    <td className="px-10 py-6 font-black text-slate-900 uppercase text-sm tracking-tight">{c.beneficiario}</td>
                    <td className="px-10 py-6 text-right font-black text-slate-900">{formatCurrency(c.valor)}</td>
                    <td className="px-10 py-6 text-center">
                      <button
                        onClick={() => toggleStatus(c.id)}
                        className={`px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${
                          c.pago 
                          ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' 
                          : 'bg-red-50 text-[#E30613] border border-red-100'
                        }`}
                      >
                        {c.pago ? 'Pago' : 'Pendente'}
                      </button>
                    </td>
                    <td className="px-10 py-6 text-center">
                      <div className="flex items-center justify-center gap-2">
                        <button 
                          onClick={() => deleteConta(c.id)}
                          className="p-3 bg-slate-50 text-slate-400 hover:bg-red-50 hover:text-[#E30613] rounded-xl transition-all"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
            {filteredData.length > 0 && (
              <tfoot className="bg-slate-50/50">
                <tr>
                   <td colSpan={3} className="px-10 py-6 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">Subtotal do Período:</td>
                   <td className="px-10 py-6 text-right font-black text-lg text-slate-900">{formatCurrency(stats.total)}</td>
                   <td colSpan={2}></td>
                </tr>
              </tfoot>
            )}
          </table>
        </div>
      </div>

      {/* Modal Adicionar */}
      {showModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-white rounded-[3rem] shadow-2xl max-w-xl w-full p-12 space-y-8 animate-in zoom-in-95 duration-300 border border-slate-100">
            <div className="flex items-center justify-between border-b border-slate-100 pb-6">
              <div>
                <h3 className="text-3xl font-black text-slate-900 tracking-tighter uppercase">Novo Compromisso</h3>
                <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">Registrar saída financeira</p>
              </div>
              <button onClick={() => setShowModal(false)} className="p-3 bg-slate-100 rounded-full text-slate-400 hover:bg-red-50 hover:text-red-600 transition-all">
                <Plus className="w-6 h-6 rotate-45" />
              </button>
            </div>

            <form onSubmit={handleAddConta} className="space-y-6">
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Data de Pagamento</label>
                  <div className="relative">
                    <input 
                      type="date" 
                      required
                      value={newConta.dataPagamento}
                      onChange={(e) => setNewConta({...newConta, dataPagamento: e.target.value})}
                      className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-slate-900 focus:ring-4 focus:ring-red-500/10 outline-none transition-all"
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Valor (R$)</label>
                  <input 
                    type="number" 
                    step="0.01"
                    required
                    placeholder="0,00"
                    value={newConta.valor || ''}
                    onChange={(e) => setNewConta({...newConta, valor: parseFloat(e.target.value)})}
                    className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-black text-slate-900 focus:ring-4 focus:ring-red-500/10 outline-none transition-all text-right"
                  />
                </div>
              </div>

              <div className="space-y-2">
