export const FluxoCaixaPage: React.FC = () => {
  const [contasPagar, setContasPagar] = useState<ContaPagar[]>(storageService.getContasPagar());
  const [recebimentos, setRecebimentos] = useState<Recebimento[]>(storageService.getRecebimentos());
  const [showInModal, setShowInModal] = useState(false);
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));

  // Form State para Novo Recebimento
  const [newIn, setNewIn] = useState<Partial<Recebimento>>({
    dataRecebimento: new Date().toISOString().split('T')[0],
    origem: '',
    valor: 0,
    recebido: false
  });

  useEffect(() => {
    storageService.saveRecebimentos(recebimentos);
  }, [recebimentos]);

  useEffect(() => {
    storageService.saveContasPagar(contasPagar);
  }, [contasPagar]);

  const stats = useMemo(() => {
    const monthIn = recebimentos.filter(r => r.dataRecebimento.startsWith(selectedMonth));
    const monthOut = contasPagar.filter(c => c.dataPagamento.startsWith(selectedMonth));

    const totalIn = monthIn.reduce((acc, r) => acc + r.valor, 0);
    const totalOut = monthOut.reduce((acc, c) => acc + c.valor, 0);

    const realIn = monthIn.filter(r => r.recebido).reduce((acc, r) => acc + r.valor, 0);
    const realOut = monthOut.filter(c => c.pago).reduce((acc, c) => acc + c.valor, 0);

    return {
      previsto: totalIn - totalOut,
      realizado: realIn - realOut,
      totalIn,
      totalOut,
      realIn,
      realOut
    };
  }, [recebimentos, contasPagar, selectedMonth]);

  const handleAddIn = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newIn.origem || !newIn.valor) return;

    const entry: Recebimento = {
      id: crypto.randomUUID(),
      dataCadastro: new Date().toLocaleDateString('pt-BR'),
      dataRecebimento: newIn.dataRecebimento || '',
      origem: newIn.origem || '',
      valor: newIn.valor || 0,
      recebido: newIn.recebido || false
