import React, { useState, useMemo, useEffect } from 'react';
import { 
  TrendingUp, 
  TrendingDown, 
  Plus, 
  ArrowUpCircle, 
  ArrowDownCircle, 
  Calendar, 
  ChevronLeft, 
  ChevronRight,
  Wallet,
  Scale,
  Trash2,
  CheckCircle2,
  FileText
} from 'lucide-react';
import { ContaPagar, Recebimento } from '../types';
import { storageService } from '../services/storageService';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

// Estendendo o tipo jsPDF para incluir o plugin autotable que é injetado globalmente/via import
declare module 'jspdf' {
  interface jsPDF {
    autoTable: any;
  }
}

export const FluxoCaixaPage: React.FC = () => {
  const [contasPagar, setContasPagar] = useState<ContaPagar[]>(storageService.getContasPagar());
  const [recebimentos, setRecebimentos] = useState<Recebimento[]>(storageService.getRecebimentos());
  const [showInModal, setShowInModal] = useState(false);
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));

  // Form State para Novo Recebimento
  const [newIn, setNewIn] = useState<Partial<Recebimento>>({
    dataRecebimento: new Date().toISOString().split('T')[0],
    origem: '',
    valor: 0,
    recebido: false
  });

  useEffect(() => {
    storageService.saveRecebimentos(recebimentos);
  }, [recebimentos]);

  useEffect(() => {
    storageService.saveContasPagar(contasPagar);
  }, [contasPagar]);

  const stats = useMemo(() => {
    const monthIn = recebimentos.filter(r => r.dataRecebimento.startsWith(selectedMonth));
    const monthOut = contasPagar.filter(c => c.dataPagamento.startsWith(selectedMonth));

    const totalIn = monthIn.reduce((acc, r) => acc + r.valor, 0);
    const totalOut = monthOut.reduce((acc, c) => acc + c.valor, 0);

    const realIn = monthIn.filter(r => r.recebido).reduce((acc, r) => acc + r.valor, 0);
    const realOut = monthOut.filter(c => c.pago).reduce((acc, c) => acc + c.valor, 0);

    return {
      previsto: totalIn - totalOut,
      realizado: realIn - realOut,
      totalIn,
      totalOut,
      realIn,
      realOut
    };
  }, [recebimentos, contasPagar, selectedMonth]);

  const handleAddIn = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newIn.origem || !newIn.valor) return;

    const entry: Recebimento = {
      id: crypto.randomUUID(),
      dataCadastro: new Date().toLocaleDateString('pt-BR'),
      dataRecebimento: newIn.dataRecebimento || '',
      origem: newIn.origem || '',
      valor: newIn.valor || 0,
      recebido: newIn.recebido || false
    };

    setRecebimentos([...recebimentos, entry]);
    setShowInModal(false);
    setNewIn({
      dataRecebimento: new Date().toISOString().split('T')[0],
      origem: '',
      valor: 0,
      recebido: false
    });
  };

  const deleteIn = (id: string) => {
    if (confirm('Excluir este recebimento?')) {
      setRecebimentos(recebimentos.filter(r => r.id !== id));
    }
  };

  const toggleInStatus = (id: string) => {
    setRecebimentos(recebimentos.map(r => r.id === id ? { ...r, recebido: !r.recebido } : r));
  };

  const toggleOutStatus = (id: string) => {
    setContasPagar(contasPagar.map(c => c.id === id ? { ...c, pago: !c.pago } : c));
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const getMonthName = (monthStr: string) => {
    const [year, month] = monthStr.split('-');
    const date = new Date(parseInt(year), parseInt(month) - 1);
    return date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' }).toUpperCase();
  };

  const changeMonth = (offset: number) => {
    const [year, month] = selectedMonth.split('-');
    const date = new Date(parseInt(year), parseInt(month) - 1 + offset);
    setSelectedMonth(date.toISOString().slice(0, 7));
  };

  const currentMonthIn = recebimentos
    .filter(r => r.dataRecebimento.startsWith(selectedMonth))
    .sort((a, b) => a.dataRecebimento.localeCompare(b.dataRecebimento));

  const currentMonthOut = contasPagar
    .filter(c => c.dataPagamento.startsWith(selectedMonth))
    .sort((a, b) => a.dataPagamento.localeCompare(b.dataPagamento));

  const handleExportPDF = () => {
    const doc = new jsPDF();
    const monthName = getMonthName(selectedMonth);
    const timestamp = new Date().toLocaleString('pt-BR');

    // Cabeçalho
    doc.setFillColor(10, 17, 33); // Slate 950
    doc.rect(0, 0, 210, 40, 'F');

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.setFont('helvetica', 'bold');
    doc.text('ABC DA CONSTRUÇÃO - ITU', 15, 20);

    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    doc.text(`RELATÓRIO CONSOLIDADO DE FLUXO DE CAIXA - ${monthName}`, 15, 30);
    doc.text(`Emitido em: ${timestamp}`, 140, 30);

    // Resumo Financeiro
    doc.setTextColor(10, 17, 33);
    doc.setFontSize(14);
    doc.text('RESUMO DO PERÍODO', 15, 55);

    doc.setDrawColor(226, 232, 240);
    doc.line(15, 58, 195, 58);

    doc.setFontSize(10);
    doc.text('Total de Entradas (Realizado):', 15, 68);
    doc.setTextColor(16, 185, 129); // Emerald 600
    doc.text(formatCurrency(stats.realIn), 75, 68);

    doc.setTextColor(10, 17, 33);
    doc.text('Total de Saídas (Pago):', 15, 75);
    doc.setTextColor(227, 6, 19); // ABC Red
    doc.text(formatCurrency(stats.realOut), 75, 75);

    doc.setTextColor(10, 17, 33);
    doc.setFont('helvetica', 'bold');
    doc.text('SALDO FINAL EM CAIXA:', 15, 85);
    doc.setTextColor(stats.realizado >= 0 ? 16, 185, 129 : 227, 6, 19);
    doc.text(formatCurrency(stats.realizado), 75, 85);

    // Tabela de Entradas
    doc.setTextColor(10, 17, 33);
    doc.setFontSize(12);
    doc.text('DETALHAMENTO DE ENTRADAS', 15, 105);

    const entriesData = currentMonthIn.map(r => [
      new Date(r.dataRecebimento).toLocaleDateString('pt-BR'),
      r.origem.toUpperCase(),
      r.recebido ? 'RECEBIDO' : 'PENDENTE',
      formatCurrency(r.valor)
    ]);

    doc.autoTable({
      startY: 110,
      head: [['DATA', 'ORIGEM / DESCRIÇÃO', 'STATUS', 'VALOR']],
      body: entriesData,
      theme: 'striped',
      headStyles: { fillColor: [16, 185, 129], textColor: 255, fontStyle: 'bold' },
      columnStyles: { 3: { halign: 'right' } }
    });

    // Tabela de Saídas
    const finalY = (doc as any).lastAutoTable.cursor.y || 110;
    doc.setTextColor(10, 17, 33);
    doc.setFontSize(12);
    doc.text('DETALHAMENTO DE SAÍDAS', 15, finalY + 20);

    const outsData = currentMonthOut.map(c => [
      new Date(c.dataPagamento).toLocaleDateString('pt-BR'),
      c.beneficiario.toUpperCase(),
      c.pago ? 'PAGO' : 'PENDENTE',
      formatCurrency(c.valor)
    ]);

    doc.autoTable({
      startY: finalY + 25,
      head: [['DATA', 'BENEFICIÁRIO / DESCRIÇÃO', 'STATUS', 'VALOR']],
      body: outsData,
      theme: 'striped',
      headStyles: { fillColor: [227, 6, 19], textColor: 255, fontStyle: 'bold' },
      columnStyles: { 3: { halign: 'right' } }
    });

    // Rodapé do PDF
    const totalPages = doc.internal.pages.length - 1;
    for(let i = 1; i <= totalPages; i++) {
        doc.setPage(i);
        doc.setFontSize(8);
        doc.setTextColor(150);
        doc.text(`Página ${i} de ${totalPages} | ABC da Construção Itu - Gestão Comercial e Financeira`, 15, 285);
    }

    doc.save(`Fluxo_Caixa_ABC_ITU_${selectedMonth}.pdf`);
  };

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Fluxo de Caixa</h2>
          <div className="flex items-center gap-4">
             <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Consolidado Financeiro — </p>
             <div className="flex items-center gap-2 bg-slate-100 px-3 py-1 rounded-xl border border-slate-200">
                <button onClick={() => changeMonth(-1)} className="hover:text-[#E30613] transition-colors"><ChevronLeft className="w-4 h-4" /></button>
                <input 
                  type="month" 
                  value={selectedMonth}
                  onChange={(e) => setSelectedMonth(e.target.value)}
                  className="bg-transparent text-[10px] font-black uppercase outline-none cursor-pointer text-slate-700"
                />
                <button onClick={() => changeMonth(1)} className="hover:text-[#E30613] transition-colors"><ChevronRight className="w-4 h-4" /></button>
             </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button
            onClick={handleExportPDF}
            className="flex items-center gap-4 px-8 py-5 bg-slate-900 hover:bg-black text-white rounded-2xl shadow-xl transition-all active:scale-95 font-black text-sm uppercase tracking-wider"
          >
            <FileText className="w-5 h-5" />
            EXPORTAR PDF
          </button>

          <button
            onClick={() => setShowInModal(true)}
            className="flex items-center gap-4 px-10 py-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl shadow-2xl shadow-emerald-100 transition-all active:scale-95 font-black text-sm uppercase tracking-wider"
          >
            <Plus className="w-5 h-5" />
            REGISTRAR ENTRADA
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100 group">
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-emerald-50 rounded-2xl group-hover:scale-110 transition-transform"><ArrowUpCircle className="w-6 h-6 text-emerald-600" /></div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Entradas (Previstas)</span>
          </div>
          <p className="text-4xl font-black tracking-tighter text-emerald-600">{formatCurrency(stats.totalIn)}</p>
          <p className="text-[9px] mt-2 font-bold text-slate-400 uppercase tracking-widest">Realizado: {formatCurrency(stats.realIn)}</p>
        </div>

        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100 group">
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-red-50 rounded-2xl group-hover:scale-110 transition-transform"><ArrowDownCircle className="w-6 h-6 text-[#E30613]" /></div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Saídas (Previstas)</span>
          </div>
          <p className="text-4xl font-black tracking-tighter text-[#E30613]">{formatCurrency(stats.totalOut)}</p>
          <p className="text-[9px] mt-2 font-bold text-slate-400 uppercase tracking-widest">Pago: {formatCurrency(stats.realOut)}</p>
        </div>

        <div className={`rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden group ${stats.realizado >= 0 ? 'bg-[#0A1121]' : 'bg-red-950'}`}>
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-white/10 rounded-2xl"><Scale className="w-6 h-6 text-[#E30613]" /></div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">Saldo Realizado (Caixa)</span>
          </div>
          <p className="text-4xl font-black tracking-tighter">{formatCurrency(stats.realizado)}</p>
          <p className="text-[9px] mt-2 font-bold text-slate-500 uppercase tracking-widest">Projetado: {formatCurrency(stats.previsto)}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Lado das Entradas */}
        <div className="bg-white border border-slate-200 rounded-[3rem] shadow-xl overflow-hidden">
          <div className="p-8 border-b border-slate-100 bg-emerald-50/20 flex items-center justify-between">
            <div className="flex items-center gap-4">
               <TrendingUp className="w-5 h-5 text-emerald-600" />
               <h3 className="text-sm font-black text-slate-900 uppercase tracking-tight">Entradas / Recebimentos</h3>
            </div>
            <span className="text-[10px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full uppercase">{getMonthName(selectedMonth)}</span>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-50 text-slate-400 border-b border-slate-100">
                  <th className="px-6 py-4 text-[9px] font-black uppercase">Data</th>
                  <th className="px-6 py-4 text-[9px] font-black uppercase">Origem</th>
                  <th className="px-6 py-4 text-[9px] font-black uppercase text-right">Valor</th>
                  <th className="px-6 py-4 text-[9px] font-black uppercase text-center">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {currentMonthIn.length === 0 ? (
                  <tr><td colSpan={4} className="px-6 py-12 text-center text-slate-300 text-[10px] font-bold uppercase">Sem registros</td></tr>
                ) : (
                  currentMonthIn.map(r => (
                    <tr key={r.id} className={`hover:bg-slate-50/50 transition-all ${r.recebido ? 'opacity-60' : ''}`}>
                      <td className="px-6 py-4 text-[11px] font-black">{new Date(r.dataRecebimento).toLocaleDateString('pt-BR')}</td>
                      <td className="px-6 py-4 text-[11px] font-bold text-slate-500 uppercase">{r.origem}</td>
                      <td className="px-6 py-4 text-[11px] font-black text-right">{formatCurrency(r.valor)}</td>
                      <td className="px-6 py-4 text-center">
                        <div className="flex items-center justify-center gap-2">
                           <button onClick={() => toggleInStatus(r.id)} className={`p-1.5 rounded-lg transition-all ${r.recebido ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-300 hover:text-emerald-600'}`}>
                              <CheckCircle2 className="w-3.5 h-3.5" />
                           </button>
                           <button onClick={() => deleteIn(r.id)} className="p-1.5 bg-slate-100 text-slate-300 hover:text-red-600 rounded-lg">
                              <Trash2 className="w-3.5 h-3.5" />
                           </button>
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>

        {/* Lado das Saídas */}
        <div className="bg-white border border-slate-200 rounded-[3rem] shadow-xl overflow-hidden">
          <div className="p-8 border-b border-slate-100 bg-red-50/20 flex items-center justify-between">
            <div className="flex items-center gap-4">
               <TrendingDown className="w-5 h-5 text-[#E30613]" />
               <h3 className="text-sm font-black text-slate-900 uppercase tracking-tight">Saídas / Pagamentos</h3>
            </div>
            <span className="text-[10px] font-black text-[#E30613] bg-red-50 px-3 py-1 rounded-full uppercase">{getMonthName(selectedMonth)}</span>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-50 text-slate-400 border-b border-slate-100">
                  <th className="px-6 py-4 text-[9px] font-black uppercase">Data</th>
                  <th className="px-6 py-4 text-[9px] font-black uppercase">Beneficiário</th>
                  <th className="px-6 py-4 text-[9px] font-black uppercase text-right">Valor</th>
                  <th className="px-6 py-4 text-[9px] font-black uppercase text-center">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {currentMonthOut.length === 0 ? (
                  <tr><td colSpan={4} className="px-6 py-12 text-center text-slate-300 text-[10px] font-bold uppercase">Sem registros</td></tr>
                ) : (
                  currentMonthOut.map(c => (
                    <tr key={c.id} className={`hover:bg-slate-50/50 transition-all ${c.pago ? 'opacity-60' : ''}`}>
                      <td className="px-6 py-4 text-[11px] font-black">{new Date(c.dataPagamento).toLocaleDateString('pt-BR')}</td>
                      <td className="px-6 py-4 text-[11px] font-bold text-slate-500 uppercase">{c.beneficiario}</td>
                      <td className="px-6 py-4 text-[11px] font-black text-right">{formatCurrency(c.valor)}</td>
                      <td className="px-6 py-4 text-center">
                        <button onClick={() => toggleOutStatus(c.id)} className={`p-1.5 rounded-lg transition-all ${c.pago ? 'bg-[#E30613] text-white' : 'bg-slate-100 text-slate-300 hover:text-red-600'}`}>
                          <CheckCircle2 className="w-3.5 h-3.5" />
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Modal Entrada */}
      {showInModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-white rounded-[3rem] shadow-2xl max-w-xl w-full p-12 space-y-8 animate-in zoom-in-95 duration-300 border border-slate-100">
            <div className="flex items-center justify-between border-b border-slate-100 pb-6">
              <div>
                <h3 className="text-3xl font-black text-slate-900 tracking-tighter uppercase">Novo Recebimento</h3>
                <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">Registrar entrada de capital</p>
              </div>
              <button onClick={() => setShowInModal(false)} className="p-3 bg-slate-100 rounded-full text-slate-400 hover:bg-red-50 hover:text-red-600 transition-all">
                <Plus className="w-6 h-6 rotate-45" />
              </button>
            </div>

            <form onSubmit={handleAddIn} className="space-y-6">
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Data Prevista</label>
                  <input 
                    type="date" 
                    required
                    value={newIn.dataRecebimento}
                    onChange={(e) => setNewIn({...newIn, dataRecebimento: e.target.value})}
                    className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-slate-900 focus:ring-4 focus:ring-emerald-500/10 outline-none transition-all"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Valor (R$)</label>
                  <input 
                    type="number" 
                    step="0.01"
                    required
                    placeholder="0,00"
                    value={newIn.valor || ''}
                    onChange={(e) => setNewIn({...newIn, valor: parseFloat(e.target.value)})}
                    className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-black text-slate-900 focus:ring-4 focus:ring-emerald-500/10 outline-none transition-all text-right"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Origem / Descrição</label>
                <input 
                  type="text" 
                  required
                  placeholder="Ex: Venda de Balcão, Aporte, Reembolso..."
                  value={newIn.origem}
                  onChange={(e) => setNewIn({...newIn, origem: e.target.value})}
                  className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-slate-900 focus:ring-4 focus:ring-emerald-500/10 outline-none transition-all"
                />
              </div>

              <div className="flex items-center gap-4 bg-slate-50 p-6 rounded-[1.5rem] border border-slate-100">
                <input 
                  type="checkbox" 
                  id="recebido"
                  checked={newIn.recebido}
                  onChange={(e) => setNewIn({...newIn, recebido: e.target.checked})}
                  className="w-5 h-5 accent-emerald-600"
                />
                <label htmlFor="recebido" className="text-xs font-black text-slate-700 uppercase tracking-tight cursor-pointer">Marcar como JÁ RECEBIDO</label>
              </div>

              <button
                type="submit"
                className="w-full py-6 bg-emerald-600 hover:bg-emerald-700 text-white rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl shadow-emerald-200 transition-all active:scale-95 flex items-center justify-center gap-3"
              >
                SALVAR RECEBIMENTO
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  TrendingUp, 
  TrendingDown, 
  Plus, 
  ArrowUpCircle, 
  ArrowDownCircle, 
  Calendar, 
  ChevronLeft, 
  ChevronRight,
  Wallet,
  Scale,
  Trash2,
  CheckCircle2,
  FileText
} from 'lucide-react';
import { ContaPagar, Recebimento } from '../types';
import { storageService } from '../services/storageService';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

// Fix: Removed problematic jspdf module augmentation and switched to any casting for autoTable calls

export const FluxoCaixaPage: React.FC = () => {
  const [contasPagar, setContasPagar] = useState<ContaPagar[]>(storageService.getContasPagar());
  const [recebimentos, setRecebimentos] = useState<Recebimento[]>(storageService.getRecebimentos());
  const [showInModal, setShowInModal] = useState(false);
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));

  // Form State para Novo Recebimento
  const [newIn, setNewIn] = useState<Partial<Recebimento>>({
    dataRecebimento: new Date().toISOString().split('T')[0],
    origem: '',
    valor: 0,
    recebido: false
  });

  useEffect(() => {
    storageService.saveRecebimentos(recebimentos);
  }, [recebimentos]);

  useEffect(() => {
    storageService.saveContasPagar(contasPagar);
  }, [contasPagar]);

  const stats = useMemo(() => {
    const monthIn = recebimentos.filter(r => r.dataRecebimento.startsWith(selectedMonth));
    const monthOut = contasPagar.filter(c => c.dataPagamento.startsWith(selectedMonth));

    const totalIn = monthIn.reduce((acc, r) => acc + r.valor, 0);
    const totalOut = monthOut.reduce((acc, c) => acc + c.valor, 0);

    const realIn = monthIn.filter(r => r.recebido).reduce((acc, r) => acc + r.valor, 0);
    const realOut = monthOut.filter(c => c.pago).reduce((acc, c) => acc + c.valor, 0);

    return {
      previsto: totalIn - totalOut,
      realizado: realIn - realOut,
      totalIn,
      totalOut,
      realIn,
      realOut
    };
  }, [recebimentos, contasPagar, selectedMonth]);

  const handleAddIn = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newIn.origem || !newIn.valor) return;

    const entry: Recebimento = {
      id: crypto.randomUUID(),
      dataCadastro: new Date().toLocaleDateString('pt-BR'),
      dataRecebimento: newIn.dataRecebimento || '',
      origem: newIn.origem || '',
      valor: newIn.valor || 0,
      recebido: newIn.recebido || false
    };

    setRecebimentos([...recebimentos, entry]);
    setShowInModal(false);
    setNewIn({
      dataRecebimento: new Date().toISOString().split('T')[0],
      origem: '',
      valor: 0,
      recebido: false
    });
  };

  const deleteIn = (id: string) => {
    if (confirm('Excluir este recebimento?')) {
      setRecebimentos(recebimentos.filter(r => r.id !== id));
    }
  };

  const toggleInStatus = (id: string) => {
    setRecebimentos(recebimentos.map(r => r.id === id ? { ...r, recebido: !r.recebido } : r));
  };

  const toggleOutStatus = (id: string) => {
    setContasPagar(contasPagar.map(c => c.id === id ? { ...c, pago: !c.pago } : c));
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const getMonthName = (monthStr: string) => {
    const [year, month] = monthStr.split('-');
    const date = new Date(parseInt(year), parseInt(month) - 1);
    return date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' }).toUpperCase();
  };

  const changeMonth = (offset: number) => {
    const [year, month] = selectedMonth.split('-');
    const date = new Date(parseInt(year), parseInt(month) - 1 + offset);
    setSelectedMonth(date.toISOString().slice(0, 7));
  };

  const currentMonthIn = recebimentos
    .filter(r => r.dataRecebimento.startsWith(selectedMonth))
    .sort((a, b) => a.dataRecebimento.localeCompare(b.dataRecebimento));

  const currentMonthOut = contasPagar
    .filter(c => c.dataPagamento.startsWith(selectedMonth))
    .sort((a, b) => a.dataPagamento.localeCompare(b.dataPagamento));

  const handleExportPDF = () => {
    const doc = new jsPDF();
    const monthName = getMonthName(selectedMonth);
    const timestamp = new Date().toLocaleString('pt-BR');

    // Cabeçalho
    doc.setFillColor(10, 17, 33); // Slate 950
    doc.rect(0, 0, 210, 40, 'F');

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.setFont('helvetica', 'bold');
    doc.text('ABC DA CONSTRUÇÃO - ITU', 15, 20);

    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    doc.text(`RELATÓRIO CONSOLIDADO DE FLUXO DE CAIXA - ${monthName}`, 15, 30);
    doc.text(`Emitido em: ${timestamp}`, 140, 30);

    // Resumo Financeiro
    doc.setTextColor(10, 17, 33);
    doc.setFontSize(14);
    doc.text('RESUMO DO PERÍODO', 15, 55);

    doc.setDrawColor(226, 232, 240);
    doc.line(15, 58, 195, 58);

    doc.setFontSize(10);
    doc.text('Total de Entradas (Realizado):', 15, 68);
    doc.setTextColor(16, 185, 129); // Emerald 600
    doc.text(formatCurrency(stats.realIn), 75, 68);

    doc.setTextColor(10, 17, 33);
    doc.text('Total de Saídas (Pago):', 15, 75);
    doc.setTextColor(227, 6, 19); // ABC Red
    doc.text(formatCurrency(stats.realOut), 75, 75);

    doc.setTextColor(10, 17, 33);
    doc.setFont('helvetica', 'bold');
    doc.text('SALDO FINAL EM CAIXA:', 15, 85);
    doc.setTextColor(stats.realizado >= 0 ? 16, 185, 129 : 227, 6, 19);
    doc.text(formatCurrency(stats.realizado), 75, 85);

    // Tabela de Entradas
    doc.setTextColor(10, 17, 33);
    doc.setFontSize(12);
    doc.text('DETALHAMENTO DE ENTRADAS', 15, 105);

    const entriesData = currentMonthIn.map(r => [
      new Date(r.dataRecebimento).toLocaleDateString('pt-BR'),
      r.origem.toUpperCase(),
      r.recebido ? 'RECEBIDO' : 'PENDENTE',
      formatCurrency(r.valor)
    ]);

    // Use any casting to avoid TS error on autoTable plugin
    (doc as any).autoTable({
      startY: 110,
      head: [['DATA', 'ORIGEM / DESCRIÇÃO', 'STATUS', 'VALOR']],
      body: entriesData,
      theme: 'striped',
      headStyles: { fillColor: [16, 185, 129], textColor: 255, fontStyle: 'bold' },
      columnStyles: { 3: { halign: 'right' } }
    });

    // Tabela de Saídas
    const finalY = (doc as any).lastAutoTable.cursor.y || 110;
    doc.setTextColor(10, 17, 33);
    doc.setFontSize(12);
    doc.text('DETALHAMENTO DE SAÍDAS', 15, finalY + 20);

    const outsData = currentMonthOut.map(c => [
      new Date(c.dataPagamento).toLocaleDateString('pt-BR'),
      c.beneficiario.toUpperCase(),
      c.pago ? 'PAGO' : 'PENDENTE',
      formatCurrency(c.valor)
    ]);

    // Use any casting to avoid TS error on autoTable plugin
    (doc as any).autoTable({
      startY: finalY + 25,
      head: [['DATA', 'BENEFICIÁRIO / DESCRIÇÃO', 'STATUS', 'VALOR']],
      body: outsData,
      theme: 'striped',
      headStyles: { fillColor: [227, 6, 19], textColor: 255, fontStyle: 'bold' },
      columnStyles: { 3: { halign: 'right' } }
    });

    // Rodapé do PDF
    const totalPages = doc.internal.pages.length - 1;
    for(let i = 1; i <= totalPages; i++) {
        doc.setPage(i);
        doc.setFontSize(8);
        doc.setTextColor(150);
        doc.text(`Página ${i} de ${totalPages} | ABC da Construção Itu - Gestão Comercial e Financeira`, 15, 285);
    }

    doc.save(`Fluxo_Caixa_ABC_ITU_${selectedMonth}.pdf`);
  };

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Fluxo de Caixa</h2>
          <div className="flex items-center gap-4">
             <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Consolidado Financeiro — </p>
             <div className="flex items-center gap-2 bg-slate-100 px-3 py-1 rounded-xl border border-slate-200">
                <button onClick={() => changeMonth(-1)} className="hover:text-[#E30613] transition-colors"><ChevronLeft className="w-4 h-4" /></button>
                <input 
                  type="month" 
                  value={selectedMonth}
                  onChange={(e) => setSelectedMonth(e.target.value)}
                  className="bg-transparent text-[10px] font-black uppercase outline-none cursor-pointer text-slate-700"
                />
                <button onClick={() => changeMonth(1)} className="hover:text-[#E30613] transition-colors"><ChevronRight className="w-4 h-4" /></button>
             </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button
            onClick={handleExportPDF}
            className="flex items-center gap-4 px-8 py-5 bg-slate-900 hover:bg-black text-white rounded-2xl shadow-xl transition-all active:scale-95 font-black text-sm uppercase tracking-wider"
          >
            <FileText className="w-5 h-5" />
            EXPORTAR PDF
          </button>

          <button
            onClick={() => setShowInModal(true)}
            className="flex items-center gap-4 px-10 py-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl shadow-2xl shadow-emerald-100 transition-all active:scale-95 font-black text-sm uppercase tracking-wider"
          >
            <Plus className="w-5 h-5" />
            REGISTRAR ENTRADA
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100 group">
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-emerald-50 rounded-2xl group-hover:scale-110 transition-transform"><ArrowUpCircle className="w-6 h-6 text-emerald-600" /></div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Entradas (Previstas)</span>
          </div>
          <p className="text-4xl font-black tracking-tighter text-emerald-600">{formatCurrency(stats.totalIn)}</p>
          <p className="text-[9px] mt-2 font-bold text-slate-400 uppercase tracking-widest">Realizado: {formatCurrency(stats.realIn)}</p>
        </div>

        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100 group">
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-red-50 rounded-2xl group-hover:scale-110 transition-transform"><ArrowDownCircle className="w-6 h-6 text-[#E30613]" /></div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Saídas (Previstas)</span>
          </div>
          <p className="text-4xl font-black tracking-tighter text-[#E30613]">{formatCurrency(stats.totalOut)}</p>
          <p className="text-[9px] mt-2 font-bold text-slate-400 uppercase tracking-widest">Pago: {formatCurrency(stats.realOut)}</p>
        </div>

        <div className={`rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden group ${stats.realizado >= 0 ? 'bg-[#0A1121]' : 'bg-red-950'}`}>
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-white/10 rounded-2xl"><Scale className="w-6 h-6 text-[#E30613]" /></div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">Saldo Realizado (Caixa)</span>
          </div>
          <p className="text-4xl font-black tracking-tighter">{formatCurrency(stats.realizado)}</p>
          <p className="text-[9px] mt-2 font-bold text-slate-500 uppercase tracking-widest">Projetado: {formatCurrency(stats.previsto)}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Lado das Entradas */}
        <div className="bg-white border border-slate-200 rounded-[3rem] shadow-xl overflow-hidden">
          <div className="p-8 border-b border-slate-100 bg-emerald-50/20 flex items-center justify-between">
            <div className="flex items-center gap-4">
               <TrendingUp className="w-5 h-5 text-emerald-600" />
               <h3 className="text-sm font-black text-slate-900 uppercase tracking-tight">Entradas / Recebimentos</h3>
            </div>
            <span className="text-[10px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full uppercase">{getMonthName(selectedMonth)}</span>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-50 text-slate-400 border-b border-slate-100">
                  <th className="px-6 py-4 text-[9px] font-black uppercase">Data</th>
                  <th className="px-6 py-4 text-[9px] font-black uppercase">Origem</th>
                  <th className="px-6 py-4 text-[9px] font-black uppercase text-right">Valor</th>
                  <th className="px-6 py-4 text-[9px] font-black uppercase text-center">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {currentMonthIn.length === 0 ? (
                  <tr><td colSpan={4} className="px-6 py-12 text-center text-slate-300 text-[10px] font-bold uppercase">Sem registros</td></tr>
                ) : (
                  currentMonthIn.map(r => (
                    <tr key={r.id} className={`hover:bg-slate-50/50 transition-all ${r.recebido ? 'opacity-60' : ''}`}>
                      <td className="px-6 py-4 text-[11px] font-black">{new Date(r.dataRecebimento).toLocaleDateString('pt-BR')}</td>
                      <td className="px-6 py-4 text-[11px] font-bold text-slate-500 uppercase">{r.origem}</td>
                      <td className="px-6 py-4 text-[11px] font-black text-right">{formatCurrency(r.valor)}</td>
                      <td className="px-6 py-4 text-center">
                        <div className="flex items-center justify-center gap-2">
                           <button onClick={() => toggleInStatus(r.id)} className={`p-1.5 rounded-lg transition-all ${r.recebido ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-300 hover:text-emerald-600'}`}>
                              <CheckCircle2 className="w-3.5 h-3.5" />
                           </button>
                           <button onClick={() => deleteIn(r.id)} className="p-1.5 bg-slate-100 text-slate-300 hover:text-red-600 rounded-lg">
                              <Trash2 className="w-3.5 h-3.5" />
                           </button>
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>

        {/* Lado das Saídas */}
        <div className="bg-white border border-slate-200 rounded-[3rem] shadow-xl overflow-hidden">
          <div className="p-8 border-b border-slate-100 bg-red-50/20 flex items-center justify-between">
            <div className="flex items-center gap-4">
               <TrendingDown className="w-5 h-5 text-[#E30613]" />
               <h3 className="text-sm font-black text-slate-900 uppercase tracking-tight">Saídas / Pagamentos</h3>
            </div>
            <span className="text-[10px] font-black text-[#E30613] bg-red-50 px-3 py-1 rounded-full uppercase">{getMonthName(selectedMonth)}</span>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-50 text-slate-400 border-b border-slate-100">
                  <th className="px-6 py-4 text-[9px] font-black uppercase">Data</th>
                  <th className="px-6 py-4 text-[9px] font-black uppercase">Beneficiário</th>
                  <th className="px-6 py-4 text-[9px] font-black uppercase text-right">Valor</th>
                  <th className="px-6 py-4 text-[9px] font-black uppercase text-center">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {currentMonthOut.length === 0 ? (
                  <tr><td colSpan={4} className="px-6 py-12 text-center text-slate-300 text-[10px] font-bold uppercase">Sem registros</td></tr>
                ) : (
                  currentMonthOut.map(c => (
                    <tr key={c.id} className={`hover:bg-slate-50/50 transition-all ${c.pago ? 'opacity-60' : ''}`}>
                      <td className="px-6 py-4 text-[11px] font-black">{new Date(c.dataPagamento).toLocaleDateString('pt-BR')}</td>
                      <td className="px-6 py-4 text-[11px] font-bold text-slate-500 uppercase">{c.beneficiario}</td>
                      <td className="px-6 py-4 text-[11px] font-black text-right">{formatCurrency(c.valor)}</td>
                      <td className="px-6 py-4 text-center">
                        <button onClick={() => toggleOutStatus(c.id)} className={`p-1.5 rounded-lg transition-all ${c.pago ? 'bg-[#E30613] text-white' : 'bg-slate-100 text-slate-300 hover:text-red-600'}`}>
                          <CheckCircle2 className="w-3.5 h-3.5" />
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Modal Entrada */}
      {showInModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-white rounded-[3rem] shadow-2xl max-w-xl w-full p-12 space-y-8 animate-in zoom-in-95 duration-300 border border-slate-100">
            <div className="flex items-center justify-between border-b border-slate-100 pb-6">
              <div>
                <h3 className="text-3xl font-black text-slate-900 tracking-tighter uppercase">Novo Recebimento</h3>
                <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">Registrar entrada de capital</p>
              </div>
              <button onClick={() => setShowInModal(false)} className="p-3 bg-slate-100 rounded-full text-slate-400 hover:bg-red-50 hover:text-red-600 transition-all">
                <Plus className="w-6 h-6 rotate-45" />
              </button>
            </div>

            <form onSubmit={handleAddIn} className="space-y-6">
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Data Prevista</label>
                  <input 
                    type="date" 
                    required
                    value={newIn.dataRecebimento}
                    onChange={(e) => setNewIn({...newIn, dataRecebimento: e.target.value})}
                    className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-slate-900 focus:ring-4 focus:ring-emerald-500/10 outline-none transition-all"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Valor (R$)</label>
                  <input 
                    type="number" 
                    step="0.01"
                    required
                    placeholder="0,00"
                    value={newIn.valor || ''}
                    onChange={(e) => setNewIn({...newIn, valor: parseFloat(e.target.value)})}
                    className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-black text-slate-900 focus:ring-4 focus:ring-emerald-500/10 outline-none transition-all text-right"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Origem / Descrição</label>
                <input 
                  type="text" 
                  required
                  placeholder="Ex: Venda de Balcão, Aporte, Reembolso..."
                  value={newIn.origem}
                  onChange={(e) => setNewIn({...newIn, origem: e.target.value})}
                  className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-slate-900 focus:ring-4 focus:ring-emerald-500/10 outline-none transition-all"
                />
              </div>

              <div className="flex items-center gap-4 bg-slate-50 p-6 rounded-[1.5rem] border border-slate-100">
                <input 
                  type="checkbox" 
                  id="recebido"
                  checked={newIn.recebido}
                  onChange={(e) => setNewIn({...newIn, recebido: e.target.checked})}
                  className="w-5 h-5 accent-emerald-600"
                />
                <label htmlFor="recebido" className="text-xs font-black text-slate-700 uppercase tracking-tight cursor-pointer">Marcar como JÁ RECEBIDO</label>
              </div>

              <button
                type="submit"
                className="w-full py-6 bg-emerald-600 hover:bg-emerald-700 text-white rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl shadow-emerald-200 transition-all active:scale-95 flex items-center justify-center gap-3"
              >
                SALVAR RECEBIMENTO
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  TrendingUp, 
  TrendingDown, 
  Plus, 
  ArrowUpCircle, 
  ArrowDownCircle, 
  Calendar, 
  ChevronLeft, 
  ChevronRight,
  Wallet,
  Scale,
  Trash2,
  CheckCircle2,
  FileText
} from 'lucide-react';
import { ContaPagar, Recebimento } from '../types';
import { storageService } from '../services/storageService';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

// Fix: Removed problematic jspdf module augmentation and switched to any casting for autoTable calls

export const FluxoCaixaPage: React.FC = () => {
  const [contasPagar, setContasPagar] = useState<ContaPagar[]>(storageService.getContasPagar());
  const [recebimentos, setRecebimentos] = useState<Recebimento[]>(storageService.getRecebimentos());
  const [showInModal, setShowInModal] = useState(false);
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));

  // Form State para Novo Recebimento
  const [newIn, setNewIn] = useState<Partial<Recebimento>>({
    dataRecebimento: new Date().toISOString().split('T')[0],
    origem: '',
    valor: 0,
    recebido: false
  });

  useEffect(() => {
    storageService.saveRecebimentos(recebimentos);
  }, [recebimentos]);

  useEffect(() => {
    storageService.saveContasPagar(contasPagar);
  }, [contasPagar]);

  const stats = useMemo(() => {
    const monthIn = recebimentos.filter(r => r.dataRecebimento.startsWith(selectedMonth));
    const monthOut = contasPagar.filter(c => c.dataPagamento.startsWith(selectedMonth));

    const totalIn = monthIn.reduce((acc, r) => acc + r.valor, 0);
    const totalOut = monthOut.reduce((acc, c) => acc + c.valor, 0);

    const realIn = monthIn.filter(r => r.recebido).reduce((acc, r) => acc + r.valor, 0);
    const realOut = monthOut.filter(c => c.pago).reduce((acc, c) => acc + c.valor, 0);

    return {
      previsto: totalIn - totalOut,
      realizado: realIn - realOut,
      totalIn,
      totalOut,
      realIn,
      realOut
    };
  }, [recebimentos, contasPagar, selectedMonth]);

  const handleAddIn = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newIn.origem || !newIn.valor) return;

    const entry: Recebimento = {
      id: crypto.randomUUID(),
      dataCadastro: new Date().toLocaleDateString('pt-BR'),
      dataRecebimento: newIn.dataRecebimento || '',
      origem: newIn.origem || '',
      valor: newIn.valor || 0,
      recebido: newIn.recebido || false
    };

    setRecebimentos([...recebimentos, entry]);
    setShowInModal(false);
    setNewIn({
      dataRecebimento: new Date().toISOString().split('T')[0],
      origem: '',
      valor: 0,
      recebido: false
    });
  };

  const deleteIn = (id: string) => {
    if (confirm('Excluir este recebimento?')) {
      setRecebimentos(recebimentos.filter(r => r.id !== id));
    }
  };

  const toggleInStatus = (id: string) => {
    setRecebimentos(recebimentos.map(r => r.id === id ? { ...r, recebido: !r.recebido } : r));
  };

  const toggleOutStatus = (id: string) => {
    setContasPagar(contasPagar.map(c => c.id === id ? { ...c, pago: !c.pago } : c));
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const getMonthName = (monthStr: string) => {
    const [year, month] = monthStr.split('-');
    const date = new Date(parseInt(year), parseInt(month) - 1);
    return date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' }).toUpperCase();
  };

  const changeMonth = (offset: number) => {
    const [year, month] = selectedMonth.split('-');
    const date = new Date(parseInt(year), parseInt(month) - 1 + offset);
    setSelectedMonth(date.toISOString().slice(0, 7));
  };

  const currentMonthIn = recebimentos
    .filter(r => r.dataRecebimento.startsWith(selectedMonth))
    .sort((a, b) => a.dataRecebimento.localeCompare(b.dataRecebimento));

  const currentMonthOut = contasPagar
    .filter(c => c.dataPagamento.startsWith(selectedMonth))
    .sort((a, b) => a.dataPagamento.localeCompare(b.dataPagamento));

  const handleExportPDF = () => {
    const doc = new jsPDF();
    const monthName = getMonthName(selectedMonth);
    const timestamp = new Date().toLocaleString('pt-BR');

    // Cabeçalho
    doc.setFillColor(10, 17, 33); // Slate 950
    doc.rect(0, 0, 210, 40, 'F');

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.setFont('helvetica', 'bold');
    doc.text('ABC DA CONSTRUÇÃO - ITU', 15, 20);

    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    doc.text(`RELATÓRIO CONSOLIDADO DE FLUXO DE CAIXA - ${monthName}`, 15, 30);
    doc.text(`Emitido em: ${timestamp}`, 140, 30);

    // Resumo Financeiro
    doc.setTextColor(10, 17, 33);
    doc.setFontSize(14);
    doc.text('RESUMO DO PERÍODO', 15, 55);

    doc.setDrawColor(226, 232, 240);
    doc.line(15, 58, 195, 58);

    doc.setFontSize(10);
    doc.text('Total de Entradas (Realizado):', 15, 68);
    doc.setTextColor(16, 185, 129); // Emerald 600
    doc.text(formatCurrency(stats.realIn), 75, 68);

    doc.setTextColor(10, 17, 33);
    doc.text('Total de Saídas (Pago):', 15, 75);
    doc.setTextColor(227, 6, 19); // ABC Red
    doc.text(formatCurrency(stats.realOut), 75, 75);

    doc.setTextColor(10, 17, 33);
    doc.setFont('helvetica', 'bold');
    doc.text('SALDO FINAL EM CAIXA:', 15, 85);

    // Corrigido erro de sintaxe no operador ternário para cores
    const statusColor = stats.realizado >= 0 ? [16, 185, 129] : [227, 6, 19];
    doc.setTextColor(statusColor[0], statusColor[1], statusColor[2]);
    doc.text(formatCurrency(stats.realizado), 75, 85);

    // Tabela de Entradas
    doc.setTextColor(10, 17, 33);
    doc.setFontSize(12);
    doc.text('DETALHAMENTO DE ENTRADAS', 15, 105);

    const entriesData = currentMonthIn.map(r => [
      new Date(r.dataRecebimento).toLocaleDateString('pt-BR'),
      r.origem.toUpperCase(),
      r.recebido ? 'RECEBIDO' : 'PENDENTE',
      formatCurrency(r.valor)
    ]);

    // Use any casting to avoid TS error on autoTable plugin
    (doc as any).autoTable({
      startY: 110,
      head: [['DATA', 'ORIGEM / DESCRIÇÃO', 'STATUS', 'VALOR']],
      body: entriesData,
      theme: 'striped',
      headStyles: { fillColor: [16, 185, 129], textColor: 255, fontStyle: 'bold' },
      columnStyles: { 3: { halign: 'right' } }
    });

    // Tabela de Saídas
    const finalY = (doc as any).lastAutoTable.cursor.y || 110;
    doc.setTextColor(10, 17, 33);
    doc.setFontSize(12);
    doc.text('DETALHAMENTO DE SAÍDAS', 15, finalY + 20);

    const outsData = currentMonthOut.map(c => [
      new Date(c.dataPagamento).toLocaleDateString('pt-BR'),
      c.beneficiario.toUpperCase(),
      c.pago ? 'PAGO' : 'PENDENTE',
      formatCurrency(c.valor)
    ]);

    // Use any casting to avoid TS error on autoTable plugin
    (doc as any).autoTable({
      startY: finalY + 25,
      head: [['DATA', 'BENEFICIÁRIO / DESCRIÇÃO', 'STATUS', 'VALOR']],
      body: outsData,
      theme: 'striped',
      headStyles: { fillColor: [227, 6, 19], textColor: 255, fontStyle: 'bold' },
      columnStyles: { 3: { halign: 'right' } }
    });

    // Rodapé do PDF
    const totalPages = doc.internal.pages.length - 1;
    for(let i = 1; i <= totalPages; i++) {
        doc.setPage(i);
        doc.setFontSize(8);
        doc.setTextColor(150);
        doc.text(`Página ${i} de ${totalPages} | ABC da Construção Itu - Gestão Comercial e Financeira`, 15, 285);
    }

    doc.save(`Fluxo_Caixa_ABC_ITU_${selectedMonth}.pdf`);
  };

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Fluxo de Caixa</h2>
          <div className="flex items-center gap-4">
             <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Consolidado Financeiro — </p>
             <div className="flex items-center gap-2 bg-slate-100 px-3 py-1 rounded-xl border border-slate-200">
                <button onClick={() => changeMonth(-1)} className="hover:text-[#E30613] transition-colors"><ChevronLeft className="w-4 h-4" /></button>
                <input 
                  type="month" 
                  value={selectedMonth}
                  onChange={(e) => setSelectedMonth(e.target.value)}
                  className="bg-transparent text-[10px] font-black uppercase outline-none cursor-pointer text-slate-700"
                />
                <button onClick={() => changeMonth(1)} className="hover:text-[#E30613] transition-colors"><ChevronRight className="w-4 h-4" /></button>
             </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button
            onClick={handleExportPDF}
            className="flex items-center gap-4 px-8 py-5 bg-slate-900 hover:bg-black text-white rounded-2xl shadow-xl transition-all active:scale-95 font-black text-sm uppercase tracking-wider"
          >
            <FileText className="w-5 h-5" />
            EXPORTAR PDF
          </button>

          <button
            onClick={() => setShowInModal(true)}
            className="flex items-center gap-4 px-10 py-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl shadow-2xl shadow-emerald-100 transition-all active:scale-95 font-black text-sm uppercase tracking-wider"
          >
            <Plus className="w-5 h-5" />
            REGISTRAR ENTRADA
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100 group">
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-emerald-50 rounded-2xl group-hover:scale-110 transition-transform"><ArrowUpCircle className="w-6 h-6 text-emerald-600" /></div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Entradas (Previstas)</span>
          </div>
          <p className="text-4xl font-black tracking-tighter text-emerald-600">{formatCurrency(stats.totalIn)}</p>
          <p className="text-[9px] mt-2 font-bold text-slate-400 uppercase tracking-widest">Realizado: {formatCurrency(stats.realIn)}</p>
        </div>

        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100 group">
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-red-50 rounded-2xl group-hover:scale-110 transition-transform"><ArrowDownCircle className="w-6 h-6 text-[#E30613]" /></div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Saídas (Previstas)</span>
          </div>
          <p className="text-4xl font-black tracking-tighter text-[#E30613]">{formatCurrency(stats.totalOut)}</p>
          <p className="text-[9px] mt-2 font-bold text-slate-400 uppercase tracking-widest">Pago: {formatCurrency(stats.realOut)}</p>
        </div>

        <div className={`rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden group ${stats.realizado >= 0 ? 'bg-[#0A1121]' : 'bg-red-950'}`}>
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-white/10 rounded-2xl"><Scale className="w-6 h-6 text-[#E30613]" /></div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">Saldo Realizado (Caixa)</span>
          </div>
          <p className="text-4xl font-black tracking-tighter">{formatCurrency(stats.realizado)}</p>
