import React, { useState, useMemo } from 'react';
import { 
  BarChart3, 
  ChevronLeft, 
  ChevronRight, 
  TrendingUp, 
  TrendingDown, 
  DollarSign,
  PieChart,
  ArrowRight,
  Info
} from 'lucide-react';
import { storageService } from '../services/storageService';

export const DREPage: React.FC = () => {
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));

  const history = storageService.getHistory();
  const contasPagar = storageService.getContasPagar();

  const dreData = useMemo(() => {
    // 1. Busca dados de vendas consolidadas do histórico
    const mesVendas = history.meses.find(m => m.mesReferencia === selectedMonth);
    const pedidos = mesVendas?.pedidos || [];

    const receitaBruta = pedidos.reduce((acc, p) => acc + p.total, 0);
    const margemOriginal = pedidos.reduce((acc, p) => acc + p.margemOriginal, 0);
    const cmv = receitaBruta - margemOriginal;

    const totalCreditos = pedidos.reduce((acc, p) => acc + (p.credito || 0), 0);
    const totalDebitos = pedidos.reduce((acc, p) => acc + (p.debito || 0), 0);
    const margemAjustada = margemOriginal + totalCreditos - totalDebitos;

    // 2. Busca despesas do contas a pagar
    const despesasMes = contasPagar.filter(c => c.dataPagamento.startsWith(selectedMonth));
    const totalDespesas = despesasMes.reduce((acc, c) => acc + c.valor, 0);

    // 3. Resultado Final
    const lucroLiquido = margemAjustada - totalDespesas;

    return {
      receitaBruta,
      cmv,
      margemOriginal,
      totalCreditos,
      totalDebitos,
      margemAjustada,
      totalDespesas,
      lucroLiquido,
      hasData: pedidos.length > 0 || despesasMes.length > 0
    };
  }, [selectedMonth, history, contasPagar]);

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const formatAV = (val: number) => {
    const pct = dreData.receitaBruta > 0 ? (val / dreData.receitaBruta) * 100 : 0;
    return pct.toFixed(2) + '%';
  };

  const changeMonth = (offset: number) => {
    const [year, month] = selectedMonth.split('-');
    const date = new Date(parseInt(year), parseInt(month) - 1 + offset);
    setSelectedMonth(date.toISOString().slice(0, 7));
  };

  const DreLine = ({ label, value, isBold = false, isNegative = false, showAV = true, isSubtotal = false }: any) => (
    <div className={`flex items-center justify-between py-4 px-6 ${isSubtotal ? 'bg-slate-50 border-y border-slate-100 mt-2' : 'border-b border-slate-50'}`}>
      <div className="flex items-center gap-3">
        {isSubtotal && <ArrowRight className="w-3 h-3 text-[#E30613]" />}
        <span className={`${isBold ? 'font-black text-slate-900' : 'font-medium text-slate-500'} text-xs uppercase tracking-tight`}>
          {label}
        </span>
      </div>
      <div className="flex items-center gap-12">
        {showAV && (
          <span className="text-[10px] font-black text-slate-300 w-16 text-right">
            {formatAV(value)}
          </span>
        )}
        <span className={`text-sm font-black w-32 text-right ${isNegative ? 'text-[#E30613]' : 'text-slate-900'}`}>
          {isNegative && value !== 0 ? '-' : ''} {formatCurrency(Math.abs(value))}
        </span>
      </div>
    </div>
  );

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">DRE</h2>
          <div className="flex items-center gap-4">
             <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Demonstrativo de Resultado — </p>
             <div className="flex items-center gap-2 bg-slate-100 px-3 py-1 rounded-xl border border-slate-200">
                <button onClick={() => changeMonth(-1)} className="hover:text-[#E30613] transition-colors"><ChevronLeft className="w-4 h-4" /></button>
                <input 
                  type="month" 
                  value={selectedMonth}
                  onChange={(e) => setSelectedMonth(e.target.value)}
                  className="bg-transparent text-[10px] font-black uppercase outline-none cursor-pointer text-slate-700"
                />
                <button onClick={() => changeMonth(1)} className="hover:text-[#E30613] transition-colors"><ChevronRight className="w-4 h-4" /></button>
             </div>
          </div>
        </div>
      </div>

      {!dreData.hasData ? (
        <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-[3rem] py-40 text-center space-y-4">
           <BarChart3 className="w-16 h-16 text-slate-200 mx-auto" />
           <p className="text-slate-400 font-black uppercase text-[10px] tracking-[0.3em]">Nenhum dado consolidado para este período</p>
           <p className="text-slate-300 text-xs max-w-xs mx-auto">Certifique-se de fechar o mês na aba Ajustes Finais para gerar o DRE.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">

          <div className="lg:col-span-2 space-y-6">
            <div className="bg-white border border-slate-200 rounded-[3rem] shadow-xl overflow-hidden">
              <div className="bg-[#0A1121] px-10 py-6 flex justify-between items-center">
                 <h3 className="text-white font-black text-xs uppercase tracking-[0.2em]">Estrutura de Resultado (R$)</h3>
                 <span className="text-slate-500 font-black text-[9px] uppercase tracking-widest w-16 text-right">Análise AV</span>
              </div>

              <div className="p-4">
                <DreLine label="Receita Operacional Bruta" value={dreData.receitaBruta} isBold showAV={false} />
                <DreLine label="(-) Custo de Mercadoria (CMV)" value={dreData.cmv} isNegative />
                <DreLine label="(=) Resultado Bruto" value={dreData.margemOriginal} isBold isSubtotal />

                <div className="h-4"></div>

                <DreLine label="(+) Ajustes de Créditos" value={dreData.totalCreditos} />
                <DreLine label="(-) Ajustes de Débitos" value={dreData.totalDebitos} isNegative />
                <DreLine label="(=) Margem de Contribuição" value={dreData.margemAjustada} isBold isSubtotal />

                <div className="h-4"></div>

                <DreLine label="(-) Despesas Operacionais (Contas Pagar)" value={dreData.totalDespesas} isNegative />

                <div className="mt-8 mb-4 p-8 bg-slate-950 rounded-[2rem] flex items-center justify-between text-white shadow-2xl">
                   <div>
                      <p className="text-[10px] font-black text-[#E30613] uppercase tracking-[0.3em] mb-1">Lucro / Prejuízo Líquido</p>
                      <h4 className="text-3xl font-black tracking-tighter">{formatCurrency(dreData.lucroLiquido)}</h4>
                   </div>
                   <div className="text-right">
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mb-1">Margem Líquida</p>
                      <h4 className={`text-2xl font-black ${dreData.lucroLiquido >= 0 ? 'text-emerald-400' : 'text-[#E30613]'}`}>
                        {formatAV(dreData.lucroLiquido)}
                      </h4>
                   </div>
                </div>
              </div>
            </div>

            <div className="bg-blue-50 border border-blue-100 rounded-[2.5rem] p-8 flex gap-6 items-start">
              <div className="bg-white p-3 rounded-2xl shadow-sm">
                <Info className="w-6 h-6 text-blue-600" />
              </div>
              <div>
                <p className="font-black text-blue-900 uppercase text-[10px] tracking-widest mb-1">Como este DRE é gerado?</p>
                <p className="text-blue-800/70 text-[11px] font-medium leading-relaxed">
                  As receitas e ajustes vêm exclusivamente dos meses "Fechados" no sistema. As despesas operacionais são puxadas do módulo de Contas a Pagar referente à data de vencimento dentro deste mês.
                </p>
              </div>
            </div>
          </div>

          <div className="space-y-8">
            <div className="bg-white border border-slate-200 rounded-[3rem] p-10 shadow-xl group hover:border-[#E30613] transition-all">
              <div className="flex items-center gap-4 mb-8">
                <div className="p-3 bg-slate-50 rounded-2xl group-hover:scale-110 transition-transform"><TrendingUp className="w-6 h-6 text-emerald-600" /></div>
                <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest">Ponto de Equilíbrio</h4>
              </div>
              <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-2">Despesas Fixas Totais</p>
              <p className="text-3xl font-black tracking-tighter text-slate-900 mb-6">{formatCurrency(dreData.totalDespesas)}</p>
              <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100">
                <p className="text-[9px] font-bold text-slate-400 uppercase leading-relaxed">
                  Para cobrir apenas as despesas fixas deste mês, você precisaria de uma margem bruta de 
                  <span className="text-slate-900 font-black"> {formatCurrency(dreData.totalDespesas)}</span>.
                </p>
              </div>
            </div>

            <div className="bg-white border border-slate-200 rounded-[3rem] p-10 shadow-xl group">
               <div className="flex items-center gap-4 mb-8">
                <div className="p-3 bg-slate-50 rounded-2xl"><PieChart className="w-6 h-6 text-[#E30613]" /></div>
                <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest">Efficiency Score</h4>
              </div>
              <div className="space-y-4">
                <div className="flex justify-between items-end">
                  <span className="text-[10px] font-black text-slate-400 uppercase">Aproveitamento</span>
