                </div>
                <div className="h-3 w-full bg-slate-100 rounded-full overflow-hidden">
                  <div 
                    className={`h-full transition-all duration-1000 ${dreData.lucroLiquido >= 0 ? 'bg-emerald-500' : 'bg-[#E30613]'}`} 
                    style={{ width: `${Math.max(0, Math.min(100, (dreData.lucroLiquido / (dreData.receitaBruta || 1)) * 100 * 3))}%` }}
