import React, { useState, useMemo } from 'react';
import { 
  Truck, 
  FileUp, 
  CheckCircle2, 
  Clock, 
  AlertCircle, 
  TrendingDown, 
  TrendingUp,
  Search,
  PackageCheck,
  ArrowRight
} from 'lucide-react';
import * as XLSX from 'xlsx';
import { storageService } from '../services/storageService';
import { Pedido, HistoricoConsolidado } from '../types';

export const FretePage: React.FC = () => {
  const [history, setHistory] = useState<HistoricoConsolidado>(storageService.getHistory());
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const stats = useMemo(() => {
    let totalCobrado = 0;
    let totalCusto = 0;
    let entregues = 0;
    let pendentes = 0;
    let todosPedidos: Pedido[] = [];

    history.meses.forEach(mes => {
      mes.pedidos.forEach(p => {
        todosPedidos.push(p);
        totalCobrado += p.frete;
        totalCusto += p.custoFreteReal || 0;
        if (p.statusEntrega === 'entregue') entregues++;
        else pendentes++;
      });
    });

    const filtered = todosPedidos.filter(p => 
      p.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
      p.vendedor.toLowerCase().includes(searchTerm.toLowerCase())
    ).sort((a, b) => b.data.localeCompare(a.data));

    return { 
      totalCobrado, 
      totalCusto, 
      saldo: totalCobrado - totalCusto,
      entregues, 
      pendentes,
      pedidos: filtered
    };
  }, [history, searchTerm]);

  const handleImportCustos = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setLoading(true);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json(worksheet) as any[];

        // Esperamos colunas: "Pedido" ou "MU" e "Custo" ou "Valor Frete"
        const newHistory = { ...history };
        let countMatched = 0;

        rows.forEach(row => {
          const mu = String(row["Pedido"] || row["MU"] || row["Nº Pedido MU"] || "").trim();
          const custo = parseFloat(row["Custo"] || row["Valor Frete"] || row["Custo Real"] || "0");

          if (mu && !isNaN(custo)) {
            newHistory.meses.forEach(mes => {
              mes.pedidos.forEach(p => {
                if (p.id === mu) {
                  p.custoFreteReal = custo;
                  p.statusEntrega = 'entregue';
                  countMatched++;
                }
              });
            });
          }
        });

        localStorage.setItem('abc_gestao_vendas_history', JSON.stringify(newHistory));
        setHistory(newHistory);
        alert(`${countMatched} custos de frete associados com sucesso!`);
      } catch (err) {
        alert("Erro ao processar planilha de custos.");
        console.error(err);
      } finally {
        setLoading(false);
        event.target.value = "";
      }
    };
    reader.readAsBinaryString(file);
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Gestão de Fretes</h2>
          <div className="flex items-center gap-4">
             <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Conferência de Logística — </p>
             <div className="flex items-center gap-2 bg-slate-100 px-3 py-1 rounded-full border border-slate-200">
                <span className="text-[10px] font-black uppercase text-slate-500">Saldo Operacional:</span>
                <span className={`text-[10px] font-black ${stats.saldo >= 0 ? 'text-emerald-600' : 'text-[#E30613]'}`}>
                  {formatCurrency(stats.saldo)}
                </span>
             </div>
          </div>
        </div>

        <label className="flex items-center gap-4 px-10 py-5 bg-[#0A1121] hover:bg-black text-white rounded-2xl cursor-pointer transition-all shadow-2xl active:scale-95 font-black text-sm uppercase tracking-wider">
          <FileUp className="w-5 h-5 text-[#E30613]" />
          <span>IMPORTAR CUSTOS REAIS (CT-E)</span>
          <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleImportCustos} />
        </label>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100 group">
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-blue-50 rounded-2xl group-hover:scale-110 transition-transform"><Truck className="w-6 h-6 text-blue-600" /></div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Frete Cobrado</span>
          </div>
          <p className="text-3xl font-black tracking-tighter text-slate-900">{formatCurrency(stats.totalCobrado)}</p>
          <p className="text-[9px] mt-2 font-bold text-slate-400 uppercase tracking-widest">Total recebido dos clientes</p>
        </div>

        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100 group">
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-red-50 rounded-2xl group-hover:scale-110 transition-transform"><TrendingDown className="w-6 h-6 text-[#E30613]" /></div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Custo de Frete</span>
          </div>
          <p className="text-3xl font-black tracking-tighter text-[#E30613]">{formatCurrency(stats.totalCusto)}</p>
          <p className="text-[9px] mt-2 font-bold text-slate-400 uppercase tracking-widest">Total pago às transportadoras</p>
        </div>

        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100 group">
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-emerald-50 rounded-2xl group-hover:scale-110 transition-transform"><PackageCheck className="w-6 h-6 text-emerald-600" /></div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Entregues</span>
          </div>
          <p className="text-3xl font-black tracking-tighter text-emerald-600">{stats.entregues}</p>
          <p className="text-[9px] mt-2 font-bold text-slate-400 uppercase tracking-widest">Custos reais conciliados</p>
        </div>

        <div className="bg-slate-50 border border-slate-200 rounded-[2.5rem] p-8 group">
          <div className="flex items-center gap-4 mb-4">
            <div className="p-3 bg-white rounded-2xl border border-slate-200"><Clock className="w-6 h-6 text-slate-400" /></div>
            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">A Entregar</span>
          </div>
          <p className="text-3xl font-black tracking-tighter text-slate-400">{stats.pendentes}</p>
          <p className="text-[9px] mt-2 font-bold text-slate-400 uppercase tracking-widest">Aguardando fatura CT-e</p>
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-[3rem] shadow-xl overflow-hidden">
        <div className="p-8 border-b border-slate-100 flex flex-col md:flex-row md:items-center justify-between gap-6">
           <div className="flex items-center gap-4">
              <h3 className="text-sm font-black text-slate-900 uppercase tracking-tight">Consolidado de Pedidos e Entregas</h3>
           </div>
           <div className="relative flex-1 max-w-md">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            <input 
              type="text" 
              placeholder="Buscar Pedido MU ou Vendedor..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-12 pr-6 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-xs font-bold outline-none focus:ring-4 focus:ring-red-500/10 transition-all"
            />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-[#0A1121] text-slate-400">
                <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest">Pedido MU</th>
