import React, { useState } from 'react';
import { FileX, FileUp, CheckCircle2, AlertCircle, Info } from 'lucide-react';
import * as XLSX from 'xlsx';
import { MesConferencia, Pedido } from '../types';

interface CanceladosPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null) => void;
}

export const CanceladosPage: React.FC<CanceladosPageProps> = ({ data, onSetData }) => {
  const [loading, setLoading] = useState(false);
  const [count, setCount] = useState(0);

  const handleImportCancelados = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !data) return;

    setLoading(true);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]) as any[];

        const newPedidos = [...data.pedidos];
        let matched = 0;

        rows.forEach(row => {
          const mu = String(row["Pedido"] || row["MU"] || row["Nº Pedido MU"] || "").trim();
          if (mu) {
            const index = newPedidos.findIndex(p => p.id === mu);
            if (index !== -1) {
              newPedidos[index].isCancelado = true;
              newPedidos[index].total = 0;
              newPedidos[index].margemOriginal = 0;
              newPedidos[index].margemAjustada = 0;
              matched++;
            }
          }
        });

        onSetData({ ...data, pedidos: newPedidos });
        setCount(matched);
      } catch (err) {
        alert("Erro ao processar planilha.");
      } finally {
        setLoading(false);
      }
    };
    reader.readAsBinaryString(file);
  };

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Cancelados</h2>
          <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Exclusão de Faturamento Indevido</p>
        </div>

        <label className="flex items-center gap-4 px-10 py-5 bg-slate-900 hover:bg-black text-white rounded-2xl cursor-pointer transition-all shadow-2xl active:scale-95 font-black text-sm uppercase tracking-wider">
          <FileUp className="w-5 h-5 text-[#E30613]" />
          <span>IMPORTAR PLANILHA DE CANCELADOS</span>
          <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleImportCancelados} />
        </label>
      </div>

      {!data ? (
         <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-[3rem] py-40 text-center space-y-4">
            <Info className="w-16 h-16 text-slate-200 mx-auto" />
            <p className="text-slate-400 font-black uppercase text-[10px] tracking-[0.3em]">Importe a planilha de vendas primeiro</p>
         </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 bg-white border border-slate-200 rounded-[3rem] p-10 shadow-xl">
             <div className="flex items-center gap-4 mb-8">
                <div className="p-3 bg-red-50 rounded-2xl"><FileX className="w-6 h-6 text-[#E30613]" /></div>
                <h3 className="text-sm font-black text-slate-900 uppercase tracking-tight">Regra de Cancelamento</h3>
             </div>
             <p className="text-slate-500 text-sm leading-relaxed mb-6">
                Ao importar a planilha de cancelados, o sistema buscará o <strong>Nº Pedido MU</strong> em sua conferência atual. Se encontrado:
             </p>
             <ul className="space-y-4">
                <li className="flex items-center gap-4 text-xs font-bold text-slate-600 bg-slate-50 p-4 rounded-2xl">
                   <div className="w-2 h-2 bg-[#E30613] rounded-full"></div>
                   O Total do Pedido será zerado (R$ 0,00)
                </li>
                <li className="flex items-center gap-4 text-xs font-bold text-slate-600 bg-slate-50 p-4 rounded-2xl">
                   <div className="w-2 h-2 bg-[#E30613] rounded-full"></div>
                   A Margem será zerada (não conta para DRE nem Comissão)
                </li>
                <li className="flex items-center gap-4 text-xs font-bold text-slate-600 bg-slate-50 p-4 rounded-2xl">
                   <div className="w-2 h-2 bg-[#E30613] rounded-full"></div>
                   O pedido será marcado visualmente como "Cancelado"
                </li>
             </ul>
          </div>

          <div className="bg-[#0A1121] rounded-[3rem] p-10 text-white shadow-2xl flex flex-col justify-center items-center text-center space-y-6">
             <div className={`w-20 h-20 rounded-full flex items-center justify-center ${count > 0 ? 'bg-emerald-500' : 'bg-white/10'}`}>
                <CheckCircle2 className="w-10 h-10 text-white" />
             </div>
             <div>
                <h4 className="text-4xl font-black tracking-tighter">{count}</h4>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">Pedidos Cancelados neste Lote</p>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Plus, Minus, Trash2, Link as LinkIcon, Database, CheckCircle2, Info } from 'lucide-react';
import { MesConferencia, AjusteExtra } from '../types';

interface AjustesVariosPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null) => void;
}

export const AjustesVariosPage: React.FC<AjustesVariosPageProps> = ({ data, onSetData }) => {
  const [showForm, setShowForm] = useState(false);
  const [newAjuste, setNewAjuste] = useState<Partial<AjusteExtra>>({
    descricao: '',
    valor: 0,
    tipo: 'credito',
    pedidoMU: ''
  });

  const handleAddAjuste = (e: React.FormEvent) => {
    e.preventDefault();
    if (!data || !newAjuste.descricao || !newAjuste.valor) return;

    const ajuste: AjusteExtra = {
      id: crypto.randomUUID(),
      descricao: newAjuste.descricao,
      valor: newAjuste.valor,
      tipo: newAjuste.tipo as 'credito' | 'debito',
      pedidoMU: newAjuste.pedidoMU,
      data: new Date().toLocaleDateString('pt-BR')
    };

    // Se houver MU, já tenta aplicar diretamente no pedido se ele existir
    const newPedidos = [...data.pedidos];
    if (ajuste.pedidoMU) {
      const idx = newPedidos.findIndex(p => p.id === ajuste.pedidoMU);
      if (idx !== -1) {
        if (ajuste.tipo === 'credito') newPedidos[idx].credito += ajuste.valor;
        else newPedidos[idx].debito += ajuste.valor;
        newPedidos[idx].margemAjustada = newPedidos[idx].margemOriginal + newPedidos[idx].credito - newPedidos[idx].debito;
      }
    }

    onSetData({
      ...data,
      pedidos: newPedidos,
      ajustesExtras: [...(data.ajustesExtras || []), ajuste]
    });

    setShowForm(false);
    setNewAjuste({ descricao: '', valor: 0, tipo: 'credito', pedidoMU: '' });
  };

  const deleteAjuste = (id: string) => {
    if (!data) return;
    const a = data.ajustesExtras.find(x => x.id === id);
    const newExtras = data.ajustesExtras.filter(x => x.id !== id);

    // Reverter no pedido se houver vínculo
    const newPedidos = [...data.pedidos];
    if (a?.pedidoMU) {
      const idx = newPedidos.findIndex(p => p.id === a.pedidoMU);
      if (idx !== -1) {
        if (a.tipo === 'credito') newPedidos[idx].credito -= a.valor;
        else newPedidos[idx].debito -= a.valor;
        newPedidos[idx].margemAjustada = newPedidos[idx].margemOriginal + newPedidos[idx].credito - newPedidos[idx].debito;
      }
    }

    onSetData({ ...data, pedidos: newPedidos, ajustesExtras: newExtras });
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

