import React, { useState } from 'react';
import { PackageOpen, FileUp, CheckCircle2, Info, ArrowDownRight } from 'lucide-react';
import * as XLSX from 'xlsx';
import { MesConferencia } from '../types';

interface DevolvidosPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null) => void;
}

export const DevolvidosPage: React.FC<DevolvidosPageProps> = ({ data, onSetData }) => {
  const [loading, setLoading] = useState(false);
  const [matched, setMatched] = useState(0);

  const handleImportDevolvidos = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !data) return;

    setLoading(true);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]) as any[];

        const newPedidos = [...data.pedidos];
        let count = 0;

        rows.forEach(row => {
          const mu = String(row["Pedido"] || row["MU"] || row["Nº Pedido MU"] || "").trim();
          const valorDevolucao = parseFloat(row["Valor Devolução"] || row["Valor"] || "0");

          if (mu && !isNaN(valorDevolucao)) {
            const index = newPedidos.findIndex(p => p.id === mu);
            if (index !== -1) {
              newPedidos[index].valorDevolvido = (newPedidos[index].valorDevolvido || 0) + valorDevolucao;
              // A devolução impacta diretamente o total do pedido e a margem proporcional
              newPedidos[index].total = Math.max(0, newPedidos[index].total - valorDevolucao);
              // Recalcula margem ajustada subtraindo o valor devolvido do resultado
              newPedidos[index].margemAjustada = Math.max(0, newPedidos[index].margemAjustada - valorDevolucao);
              count++;
            }
          }
        });

        onSetData({ ...data, pedidos: newPedidos });
        setMatched(count);
      } catch (err) {
        alert("Erro ao processar planilha de devoluções.");
      } finally {
        setLoading(false);
      }
    };
    reader.readAsBinaryString(file);
  };

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Devoluções</h2>
          <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Gestão de Logística Reversa</p>
        </div>

        <label className="flex items-center gap-4 px-10 py-5 bg-amber-600 hover:bg-amber-700 text-white rounded-2xl cursor-pointer transition-all shadow-2xl active:scale-95 font-black text-sm uppercase tracking-wider">
          <FileUp className="w-5 h-5 text-white" />
          <span>IMPORTAR PLANILHA DE DEVOLUÇÕES</span>
          <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleImportDevolvidos} />
        </label>
      </div>

      {!data ? (
        <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-[3rem] py-40 text-center space-y-4">
           <Info className="w-16 h-16 text-slate-200 mx-auto" />
           <p className="text-slate-400 font-black uppercase text-[10px] tracking-[0.3em]">Importe a planilha de faturamento primeiro</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
           <div className="bg-white border border-slate-200 rounded-[3rem] p-10 shadow-xl">
             <div className="flex items-center gap-4 mb-8">
                <div className="p-3 bg-amber-50 rounded-2xl"><PackageOpen className="w-6 h-6 text-amber-600" /></div>
                <h3 className="text-sm font-black text-slate-900 uppercase tracking-tight">Impacto Financeiro</h3>
             </div>
             <div className="space-y-6">
                <div className="flex items-start gap-4 bg-slate-50 p-6 rounded-2xl border border-slate-100 group">
                   <div className="bg-white p-2 rounded-xl group-hover:scale-110 transition-transform"><ArrowDownRight className="w-5 h-5 text-[#E30613]" /></div>
                   <div>
                      <p className="text-xs font-black text-slate-900 uppercase tracking-tight mb-1">Dedução de Receita</p>
                      <p className="text-[11px] font-medium text-slate-500">O valor devolvido é subtraído do total do pedido, impactando o faturamento bruto do vendedor.</p>
                   </div>
                </div>
                <div className="flex items-start gap-4 bg-slate-50 p-6 rounded-2xl border border-slate-100 group">
                   <div className="bg-white p-2 rounded-xl group-hover:scale-110 transition-transform"><ArrowDownRight className="w-5 h-5 text-[#E30613]" /></div>
                   <div>
                      <p className="text-xs font-black text-slate-900 uppercase tracking-tight mb-1">Dedução de Margem</p>
                      <p className="text-[11px] font-medium text-slate-500">A margem do pedido é ajustada para baixo. Se o custo da mercadoria já foi pago, a devolução pode gerar margem negativa no pedido.</p>
                   </div>
                </div>
             </div>
           </div>

           <div className="bg-amber-50 border border-amber-200 rounded-[3rem] p-12 text-center flex flex-col items-center justify-center space-y-6">
              <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center shadow-lg">
                <CheckCircle2 className="w-10 h-10 text-amber-600" />
              </div>
              <div>
                <h4 className="text-4xl font-black text-amber-900 tracking-tighter">{matched}</h4>
                <p className="text-[10px] font-black text-amber-700 uppercase tracking-widest mt-2">Associações Realizadas</p>
              </div>
              <p className="text-amber-800/60 text-[11px] font-medium max-w-xs italic">
                A planilha de devolução deve conter pelo menos as colunas "MU" e "Valor Devolução".
              </p>
           </div>
        </div>
      )}
    </div>
  );
};

