import React, { useState } from 'react';
import { FileX, FileUp, CheckCircle2, AlertCircle, Info, TrendingDown, Wallet } from 'lucide-react';
import * as XLSX from 'xlsx';
import { MesConferencia, Pedido } from '../types';

interface CanceladosPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null) => void;
}

export const CanceladosPage: React.FC<CanceladosPageProps> = ({ data, onSetData }) => {
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState({ matched: 0, totalDeduzido: 0, totalCreditoCliente: 0 });

  const toNumber = (val: any): number => {
    if (val === null || val === undefined || val === '' || val === '-') return 0;
    if (typeof val === 'number') return val;
    const cleaned = String(val)
      .replace(/R\$/g, '')
      .replace(/\./g, '')
      .replace(',', '.')
      .replace(/\s/g, '')
      .trim();
    const n = parseFloat(cleaned);
    return isNaN(n) ? 0 : n;
  };

  const handleImportCancelados = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !data) return;

    setLoading(true);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { defval: "" }) as any[];

        const newPedidos = [...data.pedidos];
        let matched = 0;
        let deduzido = 0;
        let credito = 0;

        rows.forEach(row => {
          // Mapeamento exato da planilha da imagem
          const mu = String(row["Nº Pedido MU"] || "").trim();
          const valorItemCancelado = toNumber(row["Preço total"]); // Coluna L
          const margemDeduzir = toNumber(row["Margem Deduzir c/ frete"]); // Coluna N (geralmente negativa)

          if (mu) {
            const index = newPedidos.findIndex(p => p.id === mu);
            if (index !== -1) {
              newPedidos[index].isCancelado = true;
              newPedidos[index].valorCancelado = (newPedidos[index].valorCancelado || 0) + valorItemCancelado;
              newPedidos[index].margemDeduzidaCancelamento = (newPedidos[index].margemDeduzidaCancelamento || 0) + margemDeduzir;

              // Deduz do total e da margem ajustada
              newPedidos[index].total = Math.max(0, newPedidos[index].total - valorItemCancelado);
              newPedidos[index].margemAjustada = newPedidos[index].margemAjustada + margemDeduzir; // margemDeduzir já vem negativo da planilha

              matched++;
              deduzido += Math.abs(margemDeduzir);
              credito += valorItemCancelado;
            }
          }
        });

        onSetData({ ...data, pedidos: newPedidos });
        setStats({ matched, totalDeduzido: deduzido, totalCreditoCliente: credito });
      } catch (err) {
        alert("Erro ao processar planilha de cancelados.");
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    reader.readAsBinaryString(file);
