import React, { useState } from 'react';
import { FileX, FileUp, CheckCircle2, AlertCircle, Info, TrendingDown, Wallet, Search } from 'lucide-react';
import * as XLSX from 'xlsx';
import { MesConferencia, Pedido } from '../types';

interface CanceladosPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null) => void;
}

export const CanceladosPage: React.FC<CanceladosPageProps> = ({ data, onSetData }) => {
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState({ matched: 0, totalDeduzido: 0, totalCreditoCliente: 0 });
  const [processedLog, setProcessedLog] = useState<{mu: string, valor: number, margem: number}[]>([]);

  const toNumber = (val: any): number => {
    if (val === null || val === undefined || val === '' || val === '-') return 0;
    if (typeof val === 'number') return val;
    // Remove símbolos monetários, trata separador de milhar (.) e decimal (,)
    const cleaned = String(val)
      .replace(/R\$/g, '')
      .replace(/\s/g, '')
      .trim();

    // Se tiver ponto e vírgula, assume formato brasileiro 1.000,00
    if (cleaned.includes('.') && cleaned.includes(',')) {
      return parseFloat(cleaned.replace(/\./g, '').replace(',', '.'));
    }
    // Se tiver apenas vírgula, assume decimal brasileiro 1000,00
    if (cleaned.includes(',')) {
      return parseFloat(cleaned.replace(',', '.'));
    }
    return parseFloat(cleaned);
  };

  const getActualKey = (firstRow: any, targets: string[]): string => {
    const keys = Object.keys(firstRow);
    // Tenta encontrar uma chave que contenha algum dos termos alvo (case insensitive)
    for (const target of targets) {
      const found = keys.find(k => 
        k.trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "") === 
        target.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "")
      );
      if (found) return found;
    }
    return targets[0];
  };

  const handleImportCancelados = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !data) return;

    setLoading(true);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const dataArray = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(dataArray, { type: 'array' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json(worksheet, { defval: "" }) as any[];

        if (rows.length === 0) throw new Error("Planilha vazia");

        const firstRow = rows[0];
        // Mapeamento dinâmico baseado na imagem e variações comuns
        const keyMU = getActualKey(firstRow, ["Nº Pedido MU", "No Pedido MU", "Pedido MU", "MU"]);
        const keyPrecoTotal = getActualKey(firstRow, ["Preço total", "Preco total", "Valor Cancelado", "Total Cancelado"]);
        const keyMargemDeduzir = getActualKey(firstRow, ["Margem Deduzir c/ frete", "Margem Deduzir", "Deducao Margem"]);

        const newPedidos = [...data.pedidos];
        let matched = 0;
        let deduzido = 0;
        let credito = 0;
        const log: {mu: string, valor: number, margem: number}[] = [];

        rows.forEach(row => {
          const mu = String(row[keyMU] || "").trim();
          const valorItemCancelado = toNumber(row[keyPrecoTotal]);
          const margemDeduzirValor = toNumber(row[keyMargemDeduzir]);

          if (mu && mu !== "0") {
            const index = newPedidos.findIndex(p => p.id === mu);
            if (index !== -1) {
              newPedidos[index].isCancelado = true;
              newPedidos[index].valorCancelado = (newPedidos[index].valorCancelado || 0) + valorItemCancelado;
              newPedidos[index].margemDeduzidaCancelamento = (newPedidos[index].margemDeduzidaCancelamento || 0) + margemDeduzirValor;

              // Regra: Descontar do total do pedido o valor do item cancelado
              newPedidos[index].total = Math.max(0, newPedidos[index].total - valorItemCancelado);

              // Regra: A margem Deduzir c/ frete da planilha (ex: -13,46) é somada à margem atual
              newPedidos[index].margemAjustada = newPedidos[index].margemAjustada + margemDeduzirValor;

              matched++;
              deduzido += Math.abs(margemDeduzirValor);
              credito += valorItemCancelado;
              log.push({ mu, valor: valorItemCancelado, margem: margemDeduzirValor });
            }
          }
        });

        if (matched === 0) {
          alert(`Nenhuma correspondência encontrada. Verifique se a coluna de Pedido MU (${keyMU}) está correta.`);
        } else {
          onSetData({ ...data, pedidos: newPedidos });
          setStats({ matched, totalDeduzido: deduzido, totalCreditoCliente: credito });
          setProcessedLog(log);
        }
      } catch (err) {
