import React, { useState } from 'react';
import { FileX, FileUp, CheckCircle2, Info, TrendingDown, Wallet, Search, AlertCircle } from 'lucide-react';
import * as XLSX from 'xlsx';
import { MesConferencia, Pedido } from '../types';

interface CanceladosPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null) => void;
}

export const CanceladosPage: React.FC<CanceladosPageProps> = ({ data, onSetData }) => {
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState({ matched: 0, totalDeduzido: 0, totalCreditoCliente: 0 });
  const [processedLog, setProcessedLog] = useState<{mu: string, valor: number, margem: number, status: 'sucesso' | 'nao_encontrado'}[]>([]);

  const toNumber = (val: any): number => {
    if (val === null || val === undefined || val === '' || val === '-') return 0;
    if (typeof val === 'number') return val;

    let str = String(val).replace(/R\$/g, '').replace(/\s/g, '').trim();

    // Lógica para formato brasileiro: 1.234,56
    // Se tem ponto e vírgula, o ponto é milhar.
    if (str.includes('.') && str.includes(',')) {
      str = str.replace(/\./g, '').replace(',', '.');
    } else if (str.includes(',')) {
      // Se tem apenas vírgula, é o decimal.
      str = str.replace(',', '.');
    }

    const n = parseFloat(str);
    return isNaN(n) ? 0 : n;
  };

  const getActualKey = (firstRow: any, targets: string[]): string => {
    const keys = Object.keys(firstRow);
    for (const target of targets) {
      const normalizedTarget = target.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
      const found = keys.find(k => {
        const normalizedK = k.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
        return normalizedK === normalizedTarget || normalizedK.includes(normalizedTarget);
      });
      if (found) return found;
    }
    return targets[0];
  };

  const handleImportCancelados = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !data) return;

    setLoading(true);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const dataArray = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(dataArray, { type: 'array' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json(worksheet, { defval: "" }) as any[];

        if (rows.length === 0) throw new Error("Planilha vazia ou ilegível");

        const firstRow = rows[0];
        // Mapeamento exato conforme solicitado e visualizado na imagem
        const keyMU = getActualKey(firstRow, ["Nº Pedido MU", "Pedido MU", "MU", "Numero Pedido MU"]);
        const keyPrecoTotal = getActualKey(firstRow, ["Preço total", "Preco total", "Valor Total"]);
        const keyMargemDeduzir = getActualKey(firstRow, ["Margem Deduzir c/ frete", "Margem Deduzir c/frete", "Margem Deduzir"]);

        const newPedidos = [...data.pedidos];
        let matchedCount = 0;
        let deduzidoSum = 0;
        let creditoSum = 0;
        const log: typeof processedLog = [];

        rows.forEach(row => {
          const mu = String(row[keyMU] || "").trim();
          if (!mu || mu === "0" || mu.toLowerCase().includes("total")) return;

          const valorCancelado = toNumber(row[keyPrecoTotal]);
          const margemDeduzir = toNumber(row[keyMargemDeduzir]);

          const index = newPedidos.findIndex(p => p.id === mu);
          if (index !== -1) {
            // Atualiza o pedido na lista
            newPedidos[index].isCancelado = true;
            newPedidos[index].valorCancelado = (newPedidos[index].valorCancelado || 0) + valorCancelado;
            newPedidos[index].margemDeduzidaCancelamento = (newPedidos[index].margemDeduzidaCancelamento || 0) + margemDeduzir;

            // Regra de Ouro: Descontar faturamento e aplicar ajuste de margem
            newPedidos[index].total = Math.max(0, newPedidos[index].total - valorCancelado);
            // margemDeduzir costuma vir negativa (ex: -13.46), então somamos para subtrair
            newPedidos[index].margemAjustada = newPedidos[index].margemAjustada + margemDeduzir;

            matchedCount++;
            deduzidoSum += Math.abs(margemDeduzir);
            creditoSum += valorCancelado;
            log.push({ mu, valor: valorCancelado, margem: margemDeduzir, status: 'sucesso' });
          } else {
            log.push({ mu, valor: valorCancelado, margem: margemDeduzir, status: 'nao_encontrado' });
          }
        });

        onSetData({ ...data, pedidos: newPedidos });
        setStats({ matched: matchedCount, totalDeduzido: deduzidoSum, totalCreditoCliente: creditoSum });
        setProcessedLog(log);

        if (matchedCount === 0) {
          alert("Aviso: A planilha foi lida, mas nenhum Pedido MU coincidiu com os dados da conferência atual.");
        }
      } catch (err) {
        alert("Erro crítico ao ler planilha. Verifique se o arquivo está no formato .xlsx correto.");
        console.error(err);
      } finally {
        setLoading(false);
        event.target.value = "";
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Cancelados</h2>
          <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Importação de Baixas de Margem — ABC ITU</p>
        </div>

        <label className="flex items-center gap-4 px-10 py-5 bg-slate-900 hover:bg-black text-white rounded-2xl cursor-pointer transition-all shadow-2xl active:scale-95 font-black text-sm uppercase tracking-wider">
          <FileUp className="w-5 h-5 text-[#E30613]" />
          <span>CARREGAR PLANILHA DE CANCELAMENTOS</span>
          <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleImportCancelados} />
        </label>
      </div>

      {!data ? (
         <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-[3rem] py-40 text-center space-y-4">
            <Info className="w-16 h-16 text-slate-200 mx-auto" />
            <p className="text-slate-400 font-black uppercase text-[10px] tracking-[0.3em]">Importe a Planilha de Vendas Base na aba Conferência</p>
         </div>
      ) : (
        <>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
             <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100 group">
                <div className="flex items-center gap-4 mb-4">
                  <div className="p-3 bg-red-50 rounded-2xl group-hover:scale-110 transition-transform"><TrendingDown className="w-6 h-6 text-[#E30613]" /></div>
                  <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">Total Dedução Margem</span>
                </div>
                <p className="text-3xl font-black tracking-tighter text-[#E30613]">{formatCurrency(stats.totalDeduzido)}</p>
                <p className="text-[9px] mt-2 font-bold text-slate-400 uppercase tracking-widest">Coluna N: Margem Deduzir c/ frete</p>
             </div>

             <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100 group">
                <div className="flex items-center gap-4 mb-4">
                  <div className="p-3 bg-blue-50 rounded-2xl group-hover:scale-110 transition-transform"><Wallet className="w-6 h-6 text-blue-600" /></div>
                  <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">Estorno Faturamento</span>
                </div>
                <p className="text-3xl font-black tracking-tighter text-slate-900">{formatCurrency(stats.totalCreditoCliente)}</p>
                <p className="text-[9px] mt-2 font-bold text-slate-400 uppercase tracking-widest">Coluna L: Preço Total Cancelado</p>
             </div>

             <div className="bg-[#0A1121] rounded-[2.5rem] p-8 text-white shadow-2xl flex flex-col justify-center items-center text-center">
                <div className={`w-12 h-12 rounded-full flex items-center justify-center mb-3 ${stats.matched > 0 ? 'bg-emerald-500' : 'bg-white/10'}`}>
                   <CheckCircle2 className="w-6 h-6 text-white" />
                </div>
                <h4 className="text-3xl font-black tracking-tighter">{stats.matched}</h4>
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-1">Vínculos de Pedidos MU</p>
             </div>
          </div>

          <div className="bg-white border border-slate-200 rounded-[3rem] p-10 shadow-xl overflow-hidden">
             <div className="flex items-center justify-between mb-8">
                <div className="flex items-center gap-4">
                  <Search className="w-5 h-5 text-slate-400" />
                  <h3 className="text-xs font-black text-slate-900 uppercase tracking-widest">Log de Processamento (Fila)</h3>
                </div>
                <div className="flex items-center gap-2">
                   <div className="w-2 h-2 bg-emerald-500 rounded-full"></div>
                   <span className="text-[9px] font-black text-slate-400 uppercase">Auditado com Sucesso</span>
                </div>
             </div>

             <div className="overflow-x-auto">
               <table className="w-full text-left">
                  <thead>
                    <tr className="border-b border-slate-100 text-[10px] font-black uppercase text-slate-400">
                      <th className="py-4 px-4">Pedido MU</th>
                      <th className="py-4 px-4 text-right">Valor Estornado (Col L)</th>
                      <th className="py-4 px-4 text-right">Dedução Margem (Col N)</th>
                      <th className="py-4 px-4 text-center">Resultado</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {processedLog.length === 0 ? (
                      <tr><td colSpan={4} className="py-12 text-center text-[10px] font-bold text-slate-300 uppercase italic">Importe a planilha para ver o log de auditoria...</td></tr>
                    ) : (
                      processedLog.map((l, i) => (
                        <tr key={i} className={`hover:bg-slate-50 transition-colors ${l.status === 'nao_encontrado' ? 'opacity-50 grayscale' : ''}`}>
                          <td className="py-4 px-4 font-black text-slate-900 text-xs">
                             <div className="flex items-center gap-2">
                                {l.mu}
                                {l.status === 'nao_encontrado' && <AlertCircle className="w-3 h-3 text-amber-500" title="MU não encontrado na conferência" />}
                             </div>
                          </td>
                          <td className="py-4 px-4 text-right font-bold text-slate-500">{formatCurrency(l.valor)}</td>
