                             ) : (
                               <span className="px-3 py-1 bg-slate-100 text-slate-400 rounded-lg text-[9px] font-black uppercase border border-slate-200">Ignorado (MU Inexistente)</span>
                             )}
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
               </table>
             </div>
          </div>
        </>
      )}
    </div>
  );
};

