import React, { useState, useEffect, useCallback } from 'react';
import { Sidebar } from './components/Sidebar';
import { ConferenciaPage } from './pages/ConferenciaPage';
import { CanceladosPage } from './pages/CanceladosPage';
import { DevolvidosPage } from './pages/DevolvidosPage';
import { AjustesVariosPage } from './pages/AjustesVariosPage';
import { AjustesFinaisPage } from './pages/AjustesFinaisPage';
import { DashboardPage } from './pages/DashboardPage';
import { AnaliseVendedorPage } from './pages/AnaliseVendedorPage';
import { ConfiguracaoPage } from './pages/ConfiguracaoPage';
import { ContasPagarPage } from './pages/ContasPagarPage';
import { FluxoCaixaPage } from './pages/FluxoCaixaPage';
import { DREPage } from './pages/DREPage';
import { ComissaoPage } from './pages/ComissaoPage';
import { FretePage } from './pages/FretePage';
import { PageId, MesConferencia, Pedido, HistoricoConsolidado } from './types';
import { Sparkles, Database } from 'lucide-react';
import { storageService } from './services/storageService';

const App: React.FC = () => {
  const [activePage, setActivePage] = useState<PageId>('dashboard');
  const [data, setData] = useState<MesConferencia | null>(storageService.getData());
  const [history, setHistory] = useState<HistoricoConsolidado>(storageService.getHistory());
  const [showToast, setShowToast] = useState<{show: boolean, msg: string, type: 'success' | 'danger'}>({show: false, msg: '', type: 'success'});

  const calculateMargemFinal = (p: Pedido): number => {
    // REGRA DE OURO: Margem Final = Original + (Ajustes Manuais) + (Deduções de Cancelamento/Devolução)
    // Nota: margemDeduzida costuma vir negativa da planilha ABC, então somamos para subtrair.
    return p.margemOriginal + 
           (p.credito || 0) - 
           (p.debito || 0) + 
           (p.margemDeduzidaCancelamento || 0) + 
           (p.margemDeduzidaDevolucao || 0);
  };

  const handleUpdatePedido = useCallback((id: string, updates: Partial<Pedido>) => {
    setData(current => {
      if (!current) return null;
      const newPedidos = current.pedidos.map((p) => {
        if (p.id === id) {
          const updated = { ...p, ...updates };
          updated.margemAjustada = calculateMargemFinal(updated);
          return updated;
        }
        return p;
      });
      const updatedData = { ...current, pedidos: newPedidos };
      storageService.saveData(updatedData);
      return updatedData;
    });
  }, []);

  const handleSetData = (newData: MesConferencia | null) => {
    if (newData) {
      // Garante que ao setar novos dados (importações), todos os pedidos recalculem a margem final
      newData.pedidos = newData.pedidos.map(p => ({
        ...p,
        margemAjustada: calculateMargemFinal(p)
      }));
      storageService.saveData(newData);
    } else {
      storageService.clearData();
    }
    setData(newData);
  };

  const handleCloseMonth = (consolidated: MesConferencia) => {
    storageService.saveToHistory(consolidated);
    storageService.clearData();
    setData(null);
    setHistory(storageService.getHistory());
    setActivePage('dashboard');
    setShowToast({show: true, msg: 'Mês consolidado com sucesso!', type: 'success'});
    setTimeout(() => setShowToast({show: false, msg: '', type: 'success'}), 4000);
  };

  const handleDeletePedido = (id: string) => {
    setData(current => {
      if (!current) return null;
      const newPedidos = current.pedidos.filter(p => p.id !== id);
      const updatedData = { ...current, pedidos: newPedidos };
      storageService.saveData(updatedData);
      return updatedData;
    });
  };

  const handleClearDatabase = () => {
    storageService.clearAll();
    setData(null);
    setHistory({ meses: [] });
    setActivePage('dashboard');
    setShowToast({show: true, msg: 'Banco de dados resetado!', type: 'danger'});
    setTimeout(() => setShowToast({show: false, msg: '', type: 'success'}), 4000);
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex selection:bg-red-100 selection:text-red-900 antialiased">
      <Sidebar activePage={activePage} setActivePage={setActivePage} />
      <main className="flex-grow flex flex-col min-w-0">
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-40 flex items-center justify-between px-12">
          <div className="flex items-center gap-3">
            <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">ABC ITU — Sistema de Auditoria</p>
          </div>
          <div className="flex items-center gap-2 px-4 py-2 bg-slate-50 rounded-full border border-slate-100">
            <span className="text-[10px] font-black text-slate-500 uppercase">{history.meses.length} Meses Históricos</span>
          </div>
        </header>

        {showToast.show && (
          <div className="fixed top-24 right-12 z-[250] animate-in slide-in-from-right-8 fade-in duration-500">
            <div className={`${showToast.type === 'success' ? 'bg-emerald-600' : 'bg-[#E30613]'} text-white px-8 py-5 rounded-3xl shadow-2xl flex items-center gap-4`}>
               <Sparkles className="w-5 h-5" />
               <p className="text-[10px] font-black uppercase">{showToast.msg}</p>
            </div>
          </div>
        )}

        <div className="p-8 lg:p-12">
          <div className="bg-white p-10 rounded-[4rem] shadow-xl border border-slate-200/50 min-h-[75vh]">
            {activePage === 'dashboard' && <DashboardPage history={history} />}
            {activePage === 'conferencia' && <ConferenciaPage data={data} onSetData={handleSetData} onUpdatePedido={handleUpdatePedido} onDeletePedido={handleDeletePedido} onNavigateToAjustes={() => setActivePage('ajustes')} />}
            {activePage === 'cancelados' && <CanceladosPage data={data} onSetData={handleSetData} />}
            {activePage === 'devolvidos' && <DevolvidosPage data={data} onSetData={handleSetData} />}
            {activePage === 'ajustes-varios' && <AjustesVariosPage data={data} onSetData={handleSetData} />}
            {activePage === 'ajustes' && <AjustesFinaisPage data={data} onDeletePedido={handleDeletePedido} onCloseMonth={handleCloseMonth} />}
            {activePage === 'analise-vendedor' && <AnaliseVendedorPage history={history} />}
            {activePage === 'contas-pagar' && <ContasPagarPage />}
            {activePage === 'fluxo-caixa' && <FluxoCaixaPage />}
            {activePage === 'dre' && <DREPage />}
            {activePage === 'comissao' && <ComissaoPage history={history} />}
            {activePage === 'frete' && <FretePage />}
            {activePage === 'configuracao' && <ConfiguracaoPage onClearDatabase={handleClearDatabase} />}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { PackageOpen, FileUp, CheckCircle2, Info, TrendingDown, Search, AlertCircle } from 'lucide-react';
import * as XLSX from 'xlsx';
import { MesConferencia } from '../types';

interface DevolvidosPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null) => void;
}

export const DevolvidosPage: React.FC<DevolvidosPageProps> = ({ data, onSetData }) => {
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState({ matched: 0, totalDeduzido: 0 });
  const [processedLog, setProcessedLog] = useState<{mu: string, valor: number, margem: number, status: 'sucesso' | 'nao_encontrado'}[]>([]);

  const toNumber = (val: any): number => {
    if (val === null || val === undefined || val === '' || val === '-') return 0;
    if (typeof val === 'number') return val;
    let str = String(val).replace(/R\$/g, '').replace(/\s/g, '').trim();
    if (str.includes('.') && str.includes(',')) str = str.replace(/\./g, '').replace(',', '.');
    else if (str.includes(',')) str = str.replace(',', '.');
    return parseFloat(str) || 0;
  };

  const getActualKey = (firstRow: any, targets: string[]): string => {
    const keys = Object.keys(firstRow);
    for (const target of targets) {
      const normalizedTarget = target.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
      const found = keys.find(k => k.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim().includes(normalizedTarget));
      if (found) return found;
    }
    return targets[0];
  };

  const handleImportDevolvidos = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !data) return;

    setLoading(true);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const dataArray = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(dataArray, { type: 'array' });
        const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { defval: "" }) as any[];

        if (rows.length === 0) throw new Error("Vazia");

        const firstRow = rows[0];
        const keyMU = getActualKey(firstRow, ["Nº Pedido MU", "Pedido MU", "MU"]);
        const keyPrecoTotal = getActualKey(firstRow, ["Preço total", "Preco total", "Valor Total"]);
        const keyMargemDeduzir = getActualKey(firstRow, ["Margem Deduzir c/ frete", "Margem Deduzir", "Deducao Margem"]);

        const newPedidos = [...data.pedidos];
        let matchedCount = 0;
        let deduzidoSum = 0;
        const log: typeof processedLog = [];

        rows.forEach(row => {
          const mu = String(row[keyMU] || "").trim();
          if (!mu || mu === "0" || mu.toLowerCase().includes("total")) return;

          const valorDevolvido = toNumber(row[keyPrecoTotal]);
          const margemDeduzir = toNumber(row[keyMargemDeduzir]);

          const index = newPedidos.findIndex(p => p.id === mu);
          if (index !== -1) {
            newPedidos[index].isDevolvido = true;
            newPedidos[index].valorDevolvido = (newPedidos[index].valorDevolvido || 0) + valorDevolvido;
            newPedidos[index].margemDeduzidaDevolucao = (newPedidos[index].margemDeduzidaDevolucao || 0) + margemDeduzir;

            // Dedução de Faturamento e Margem
            newPedidos[index].total = Math.max(0, newPedidos[index].total - valorDevolvido);
            matchedCount++;
            deduzidoSum += Math.abs(margemDeduzir);
            log.push({ mu, valor: valorDevolvido, margem: margemDeduzir, status: 'sucesso' });
          } else {
            log.push({ mu, valor: valorDevolvido, margem: margemDeduzir, status: 'nao_encontrado' });
          }
        });

        onSetData({ ...data, pedidos: newPedidos });
        setStats({ matched: matchedCount, totalDeduzido: deduzidoSum });
        setProcessedLog(log);
      } catch (err) {
        alert("Erro ao ler planilha de devoluções.");
      } finally {
        setLoading(false);
        event.target.value = "";
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Devoluções</h2>
          <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Logística Reversa — ABC ITU</p>
        </div>
        <label className="flex items-center gap-4 px-10 py-5 bg-amber-600 hover:bg-amber-700 text-white rounded-2xl cursor-pointer transition-all shadow-xl active:scale-95 font-black text-sm uppercase tracking-wider">
          <FileUp className="w-5 h-5" />
          <span>PROCESSAR PLANILHA DE DEVOLUÇÕES</span>
          <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleImportDevolvidos} />
        </label>
      </div>

      {!data ? (
        <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-[3rem] py-40 text-center">
           <Info className="w-16 h-16 text-slate-200 mx-auto" />
           <p className="text-slate-400 font-black uppercase text-[10px] tracking-[0.3em]">Importe a Planilha Base na aba Conferência</p>
        </div>
      ) : (
        <>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
             <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl flex items-center justify-between">
                <div>
                   <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Dedução de Margem (Devoluções)</p>
                   <p className="text-3xl font-black text-[#E30613]">{formatCurrency(stats.totalDeduzido)}</p>
                </div>
                <TrendingDown className="w-10 h-10 text-[#E30613]" />
             </div>
             <div className="bg-[#0A1121] rounded-[2.5rem] p-8 text-white shadow-2xl flex items-center justify-between">
                <div>
                   <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Pedidos Conciliados</p>
                   <p className="text-3xl font-black">{stats.matched}</p>
                </div>
                <CheckCircle2 className="w-10 h-10 text-emerald-500" />
             </div>
          </div>

          <div className="bg-white border border-slate-200 rounded-[3rem] p-10 shadow-xl overflow-hidden">
             <div className="flex items-center gap-4 mb-8">
                <Search className="w-5 h-5 text-slate-400" />
                <h3 className="text-xs font-black text-slate-900 uppercase tracking-widest">Resumo do Estorno de Margem</h3>
             </div>
             <div className="overflow-x-auto">
               <table className="w-full text-left">
                  <thead>
                    <tr className="border-b border-slate-100 text-[10px] font-black uppercase text-slate-400">
                      <th className="py-4 px-4">Pedido MU</th>
                      <th className="py-4 px-4 text-right">Valor Estornado</th>
                      <th className="py-4 px-4 text-right">Impacto Margem</th>
                      <th className="py-4 px-4 text-center">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {processedLog.length === 0 ? (
                      <tr><td colSpan={4} className="py-12 text-center text-[10px] font-bold text-slate-300 uppercase italic">Aguardando planilha...</td></tr>
                    ) : (
                      processedLog.map((l, i) => (
                        <tr key={i} className={`hover:bg-slate-50 ${l.status === 'nao_encontrado' ? 'opacity-40 grayscale' : ''}`}>
                          <td className="py-4 px-4 font-black text-slate-900 text-xs">
                             <div className="flex items-center gap-2">
                                {l.mu}
                                {l.status === 'nao_encontrado' && <span title="Não encontrado"><AlertCircle className="w-3 h-3 text-amber-500" /></span>}
                             </div>
                          </td>
                          <td className="py-4 px-4 text-right font-bold text-slate-500">{formatCurrency(l.valor)}</td>
                          <td className="py-4 px-4 text-right font-black text-[#E30613]">{formatCurrency(l.margem)}</td>
                          <td className="py-4 px-4 text-center">
                             <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase ${l.status === 'sucesso' ? 'bg-emerald-50 text-emerald-600' : 'bg-slate-100 text-slate-400'}`}>
                                {l.status === 'sucesso' ? 'Devolução Aplicada' : 'Ignorado'}
                             </span>
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
               </table>
             </div>
          </div>
        </>
      )}
    </div>
  );
};

