  onCloseMonth: (consolidatedData: MesConferencia) => void;
}

export const AjustesFinaisPage: React.FC<AjustesFinaisPageProps> = ({ data, onDeletePedido, onCloseMonth }) => {
  const [showConfirmModal, setShowConfirmModal] = useState(false);

  const handleConfirm = () => {
    if (!data) return;
    onCloseMonth(data);
    setShowConfirmModal(false);
  };

  const handleExportExcel = () => {
    if (!data || data.pedidos.length === 0) return;

    const exportData = data.pedidos.map(p => ({
      "Nº Pedido MU": p.id,
      "Data Faturamento": p.data,
      "Canal Venda": p.canal,
      "Vendedor": p.vendedor,
      "Total Faturado (R$)": p.total,
      "Margem Original (R$)": p.margemOriginal,
      "Dedução Cancelados (R$)": p.margemDeduzidaCancelamento || 0,
      "Dedução Devolvidos (R$)": p.margemDeduzidaDevolucao || 0,
      "Crédito Ajuste (R$)": p.credito,
      "Débito Ajuste (R$)": p.debito,
      "Margem Final Ajustada (R$)": p.margemAjustada,
      "Margem Final Ajustada (%)": (p.total > 0 ? (p.margemAjustada / p.total) * 100 : 0).toFixed(2) + "%"
    }));

    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Resultado Auditado ABC");
    XLSX.writeFile(workbook, `ABC_Consolidado_${data.mesReferencia}.xlsx`);
  };

  const summary = useMemo(() => {
    if (!data || data.pedidos.length === 0) return { 
      total: 0, 
      margemOriginal: 0, 
      deducaoCancelados: 0, 
      deducaoDevolvidos: 0, 
      ajustesManuais: 0, 
