import React, { useState, useEffect, useCallback } from 'react';
import { Sidebar } from './components/Sidebar';
import { ConferenciaPage } from './pages/ConferenciaPage';
import { CanceladosPage } from './pages/CanceladosPage';
import { DevolvidosPage } from './pages/DevolvidosPage';
import { AjustesVariosPage } from './pages/AjustesVariosPage';
import { AjustesFinaisPage } from './pages/AjustesFinaisPage';
import { DashboardPage } from './pages/DashboardPage';
import { AnaliseVendedorPage } from './pages/AnaliseVendedorPage';
import { ConfiguracaoPage } from './pages/ConfiguracaoPage';
import { ContasPagarPage } from './pages/ContasPagarPage';
import { FluxoCaixaPage } from './pages/FluxoCaixaPage';
import { DREPage } from './pages/DREPage';
import { ComissaoPage } from './pages/ComissaoPage';
import { FretePage } from './pages/FretePage';
import { PageId, MesConferencia, Pedido, HistoricoConsolidado } from './types';
import { Sparkles } from 'lucide-react';
import { storageService } from './services/storageService';

const App: React.FC = () => {
  const [activePage, setActivePage] = useState<PageId>('dashboard');
  const [data, setData] = useState<MesConferencia | null>(storageService.getData());
  const [history, setHistory] = useState<HistoricoConsolidado>(storageService.getHistory());
  const [showToast, setShowToast] = useState<{show: boolean, msg: string, type: 'success' | 'danger'}>({show: false, msg: '', type: 'success'});

  // REGRA DE OURO DO SISTEMA: Composição da Margem Final
  const calculateMargemFinal = (p: Pedido): number => {
    return p.margemOriginal + 
           (p.credito || 0) - 
           (p.debito || 0) + 
           (p.margemDeduzidaCancelamento || 0) + 
           (p.margemDeduzidaDevolucao || 0);
  };

  const handleUpdatePedido = useCallback((id: string, updates: Partial<Pedido>) => {
    setData(current => {
      if (!current) return null;
      const newPedidos = current.pedidos.map((p) => {
        if (p.id === id) {
          const updated = { ...p, ...updates };
          updated.margemAjustada = calculateMargemFinal(updated);
          return updated;
        }
        return p;
      });
      const updatedData = { ...current, pedidos: newPedidos };
      storageService.saveData(updatedData);
      return updatedData;
    });
  }, []);

  const handleSetData = (newData: MesConferencia | null) => {
    if (newData) {
      // Recalcula margens de todos ao importar novas planilhas (Cancelados/Devolvidos)
      newData.pedidos = newData.pedidos.map(p => ({
        ...p,
        margemAjustada: calculateMargemFinal(p)
      }));
      storageService.saveData(newData);
    } else {
      storageService.clearData();
    }
    setData(newData);
  };

  const handleCloseMonth = (consolidated: MesConferencia) => {
    storageService.saveToHistory(consolidated);
    storageService.clearData();
    setData(null);
    setHistory(storageService.getHistory());
    setActivePage('dashboard');
    setShowToast({show: true, msg: 'Mês consolidado e salvo com sucesso!', type: 'success'});
    setTimeout(() => setShowToast({show: false, msg: '', type: 'success'}), 4000);
  };

  const handleDeletePedido = (id: string) => {
    setData(current => {
      if (!current) return null;
      const newPedidos = current.pedidos.filter(p => p.id !== id);
      const updatedData = { ...current, pedidos: newPedidos };
      storageService.saveData(updatedData);
      return updatedData;
    });
  };

  const handleClearDatabase = () => {
    storageService.clearAll();
    setData(null);
    setHistory({ meses: [] });
    setActivePage('dashboard');
    setShowToast({show: true, msg: 'Banco de dados resetado!', type: 'danger'});
    setTimeout(() => setShowToast({show: false, msg: '', type: 'success'}), 4000);
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex selection:bg-red-100 selection:text-red-900 antialiased">
      <Sidebar activePage={activePage} setActivePage={setActivePage} />
      <main className="flex-grow flex flex-col min-w-0">
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-40 flex items-center justify-between px-12">
          <div className="flex items-center gap-3">
            <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">ABC ITU — Gestão de Resultados</p>
          </div>
          <div className="flex items-center gap-2 px-4 py-2 bg-slate-50 rounded-full border border-slate-100">
            <span className="text-[10px] font-black text-slate-500 uppercase">{history.meses.length} Meses no Banco de Dados</span>
          </div>
        </header>

        {showToast.show && (
          <div className="fixed top-24 right-12 z-[250] animate-in slide-in-from-right-8 fade-in duration-500">
            <div className={`${showToast.type === 'success' ? 'bg-emerald-600' : 'bg-[#E30613]'} text-white px-8 py-5 rounded-3xl shadow-2xl flex items-center gap-4`}>
               <Sparkles className="w-5 h-5" />
               <p className="text-[10px] font-black uppercase">{showToast.msg}</p>
            </div>
          </div>
        )}

        <div className="p-8 lg:p-12">
          <div className="bg-white p-10 rounded-[4rem] shadow-xl border border-slate-200/50 min-h-[75vh]">
            {activePage === 'dashboard' && <DashboardPage history={history} />}
            {activePage === 'conferencia' && <ConferenciaPage data={data} onSetData={handleSetData} onUpdatePedido={handleUpdatePedido} onDeletePedido={handleDeletePedido} onNavigateToAjustes={() => setActivePage('ajustes')} />}
            {activePage === 'cancelados' && <CanceladosPage data={data} onSetData={handleSetData} />}
            {activePage === 'devolvidos' && <DevolvidosPage data={data} onSetData={handleSetData} />}
            {activePage === 'ajustes-varios' && <AjustesVariosPage data={data} onSetData={handleSetData} />}
            {activePage === 'ajustes' && <AjustesFinaisPage data={data} onDeletePedido={handleDeletePedido} onCloseMonth={handleCloseMonth} />}
            {activePage === 'analise-vendedor' && <AnaliseVendedorPage history={history} />}
            {activePage === 'contas-pagar' && <ContasPagarPage />}
            {activePage === 'fluxo-caixa' && <FluxoCaixaPage />}
            {activePage === 'dre' && <DREPage />}
            {activePage === 'comissao' && <ComissaoPage history={history} />}
            {activePage === 'frete' && <FretePage />}
            {activePage === 'configuracao' && <ConfiguracaoPage onClearDatabase={handleClearDatabase} />}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { FileX, FileUp, CheckCircle2, Info, TrendingDown, Wallet, Search, AlertCircle } from 'lucide-react';
import * as XLSX from 'xlsx';
import { MesConferencia, Pedido } from '../types';

interface CanceladosPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null) => void;
}

export const CanceladosPage: React.FC<CanceladosPageProps> = ({ data, onSetData }) => {
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState({ matched: 0, totalDeduzido: 0, totalCreditoCliente: 0 });
  const [processedLog, setProcessedLog] = useState<{mu: string, valor: number, margem: number, status: 'sucesso' | 'nao_encontrado'}[]>([]);

  const toNumber = (val: any): number => {
    if (val === null || val === undefined || val === '' || val === '-') return 0;
    if (typeof val === 'number') return val;
    let str = String(val).replace(/R\$/g, '').replace(/\s/g, '').trim();
    if (str.includes('.') && str.includes(',')) str = str.replace(/\./g, '').replace(',', '.');
    else if (str.includes(',')) str = str.replace(',', '.');
    return parseFloat(str) || 0;
  };

  const getActualKey = (firstRow: any, targets: string[]): string => {
    const keys = Object.keys(firstRow);
    for (const target of targets) {
      const normalizedTarget = target.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
      const found = keys.find(k => {
        const normalizedK = k.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
        return normalizedK === normalizedTarget || normalizedK.includes(normalizedTarget);
      });
      if (found) return found;
    }
    return targets[0];
  };

  const handleImportCancelados = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !data) return;

    setLoading(true);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const dataArray = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(dataArray, { type: 'array' });
        const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { defval: "" }) as any[];

        if (rows.length === 0) throw new Error("Planilha vazia");

        const firstRow = rows[0];
        const keyMU = getActualKey(firstRow, ["Nº Pedido MU", "Pedido MU", "MU"]);
        const keyPrecoTotal = getActualKey(firstRow, ["Preço total", "Preco total", "Valor Total"]);
        const keyMargemDeduzir = getActualKey(firstRow, ["Margem Deduzir c/ frete", "Margem Deduzir", "Deducao Margem"]);

        const newPedidos = [...data.pedidos];
        let matchedCount = 0;
        let deduzidoSum = 0;
        let creditoSum = 0;
        const log: typeof processedLog = [];

        rows.forEach(row => {
          const mu = String(row[keyMU] || "").trim();
          if (!mu || mu === "0" || mu.toLowerCase().includes("total")) return;

          const valorCancelado = toNumber(row[keyPrecoTotal]);
          const margemDeduzir = toNumber(row[keyMargemDeduzir]);

          const index = newPedidos.findIndex(p => p.id === mu);
          if (index !== -1) {
            newPedidos[index].isCancelado = true;
            newPedidos[index].valorCancelado = (newPedidos[index].valorCancelado || 0) + valorCancelado;
            newPedidos[index].margemDeduzidaCancelamento = (newPedidos[index].margemDeduzidaCancelamento || 0) + margemDeduzir;

            // Dedução automática de faturamento
            newPedidos[index].total = Math.max(0, newPedidos[index].total - valorCancelado);

            matchedCount++;
            deduzidoSum += Math.abs(margemDeduzir);
            creditoSum += valorCancelado;
            log.push({ mu, valor: valorCancelado, margem: margemDeduzir, status: 'sucesso' });
          } else {
            log.push({ mu, valor: valorCancelado, margem: margemDeduzir, status: 'nao_encontrado' });
          }
        });

        onSetData({ ...data, pedidos: newPedidos });
        setStats({ matched: matchedCount, totalDeduzido: deduzidoSum, totalCreditoCliente: creditoSum });
        setProcessedLog(log);
      } catch (err) {
        alert("Erro ao ler planilha de cancelados.");
      } finally {
        setLoading(false);
        event.target.value = "";
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Cancelados</h2>
          <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Importação de Baixas de Margem — ABC ITU</p>
        </div>

        <label className="flex items-center gap-4 px-10 py-5 bg-[#0A1121] hover:bg-black text-white rounded-2xl cursor-pointer transition-all shadow-2xl active:scale-95 font-black text-sm uppercase tracking-wider">
          <FileUp className="w-5 h-5 text-[#E30613]" />
          <span>CARREGAR PLANILHA CANCELADOS</span>
          <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleImportCancelados} />
        </label>
      </div>

      {!data ? (
         <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-[3rem] py-40 text-center space-y-4">
            <Info className="w-16 h-16 text-slate-200 mx-auto" />
