      <div className="bg-slate-900 rounded-[3rem] p-12 text-white shadow-2xl relative overflow-hidden">
         <div className="absolute right-0 top-0 opacity-5 -translate-y-1/2 translate-x-1/4">
            <TrendingUp className="w-96 h-96" />
         </div>

         <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-8 relative z-10">
            <div className="space-y-2">
               <div className="flex items-center gap-2 text-slate-500 uppercase font-black text-[9px] tracking-widest">
                  <Banknote className="w-3 h-3" /> Margem Original
               </div>
               <p className="text-xl font-black">{formatCurrency(summary.margemOriginal)}</p>
            </div>

            <div className="flex items-center justify-center opacity-30"><ArrowRight className="w-5 h-5" /></div>

            <div className="space-y-2">
               <div className="flex items-center gap-2 text-red-500 uppercase font-black text-[9px] tracking-widest">
                  <FileX className="w-3 h-3" /> Baixas/Devoluções
               </div>
