import React, { useState } from 'react';
import { FileX, FileUp, CheckCircle2, Info, TrendingDown, Wallet, Search, AlertCircle, Clock } from 'lucide-react';
import * as XLSX from 'xlsx';
import { MesConferencia, Pedido } from '../types';

interface CanceladosPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null) => void;
}

export const CanceladosPage: React.FC<CanceladosPageProps> = ({ data, onSetData }) => {
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState({ matched: 0, addedNew: 0, totalDeduzido: 0 });
  const [processedLog, setProcessedLog] = useState<{mu: string, valor: number, margem: number, status: 'sucesso' | 'novo_lancamento'}[]>([]);

  const toNumber = (val: any): number => {
    if (val === null || val === undefined || val === '' || val === '-') return 0;
    if (typeof val === 'number') return val;
    let str = String(val).replace(/R\$/g, '').replace(/\s/g, '').trim();
    if (str.includes('.') && str.includes(',')) str = str.replace(/\./g, '').replace(',', '.');
    else if (str.includes(',')) str = str.replace(',', '.');
    return parseFloat(str) || 0;
  };

  const getActualKey = (firstRow: any, targets: string[]): string => {
    const keys = Object.keys(firstRow);
    for (const target of targets) {
      const normalizedTarget = target.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
      const found = keys.find(k => k.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim().includes(normalizedTarget));
      if (found) return found;
    }
    return targets[0];
  };

  const handleImportCancelados = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !data) return;

    setLoading(true);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const dataArray = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(dataArray, { type: 'array' });
        const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { defval: "" }) as any[];

        const firstRow = rows[0];
        const keyMU = getActualKey(firstRow, ["Nº Pedido MU", "Pedido MU", "MU"]);
        const keyPrecoTotal = getActualKey(firstRow, ["Preço total", "Preco total"]);
        const keyMargemDeduzir = getActualKey(firstRow, ["Margem Deduzir c/ frete", "Margem Deduzir"]);

        const newPedidos = [...data.pedidos];
        let matchedCount = 0;
        let addedNewCount = 0;
        let deduzidoSum = 0;
        const log: typeof processedLog = [];

        rows.forEach(row => {
          const mu = String(row[keyMU] || "").trim();
          if (!mu || mu === "0" || mu.toLowerCase().includes("total")) return;

          const valorCancelado = toNumber(row[keyPrecoTotal]);
          const margemDeduzir = toNumber(row[keyMargemDeduzir]);
          deduzidoSum += Math.abs(margemDeduzir);

          const index = newPedidos.findIndex(p => p.id === mu);
          if (index !== -1) {
            newPedidos[index].isCancelado = true;
            newPedidos[index].margemDeduzidaCancelamento = (newPedidos[index].margemDeduzidaCancelamento || 0) + margemDeduzir;
            newPedidos[index].total = Math.max(0, newPedidos[index].total - valorCancelado);
            matchedCount++;
            log.push({ mu, valor: valorCancelado, margem: margemDeduzir, status: 'sucesso' });
          } else {
            // REGRA DE OURO: Pedido de outro mês. Adicionamos como um lançamento de ajuste negativo.
            const novoPedidoAjuste: Pedido = {
              id: mu,
              data: "Ref. Mês Anterior",
              canal: "AJUSTE CANCELAMENTO",
              vendedor: "SISTEMA (BACKLOG)",
              mkt: 0, cac: 0, total: 0, frete: 0,
              margemOriginal: 0,
              margemOriginalPct: 0,
              credito: 0, debito: 0,
              margemDeduzidaCancelamento: margemDeduzir,
              margemAjustada: margemDeduzir,
              confirmado: true,
              isCancelado: true
            };
            newPedidos.push(novoPedidoAjuste);
            addedNewCount++;
            log.push({ mu, valor: valorCancelado, margem: margemDeduzir, status: 'novo_lancamento' });
          }
        });

        onSetData({ ...data, pedidos: newPedidos });
        setStats({ matched: matchedCount, addedNew: addedNewCount, totalDeduzido: deduzidoSum });
        setProcessedLog(log);
      } catch (err) {
        alert("Erro na importação.");
      } finally {
        setLoading(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Cancelados</h2>
          <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Auditoria de Baixas Extemporâneas</p>
        </div>
        <label className="flex items-center gap-4 px-10 py-5 bg-[#0A1121] text-white rounded-2xl cursor-pointer hover:bg-black transition-all shadow-2xl">
          <FileUp className="w-5 h-5 text-[#E30613]" />
          <span>IMPORTAR PLANILHA ABC</span>
          <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleImportCancelados} />
        </label>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
         <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Dedução Total de Margem</p>
            <p className="text-3xl font-black text-[#E30613]">{formatCurrency(stats.totalDeduzido)}</p>
         </div>
         <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Vínculos no Mês Atual</p>
            <p className="text-3xl font-black text-slate-900">{stats.matched} Pedidos</p>
         </div>
         <div className="bg-emerald-600 rounded-[2.5rem] p-8 text-white shadow-xl">
            <p className="text-[10px] font-black text-white/60 uppercase tracking-widest mb-1">Ajustes de Meses Anteriores</p>
            <p className="text-3xl font-black">{stats.addedNew} Lançamentos</p>
         </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-[3rem] p-10 shadow-xl overflow-hidden">
         <div className="flex items-center gap-4 mb-8">
            <Search className="w-5 h-5 text-slate-400" />
            <h3 className="text-xs font-black text-slate-900 uppercase tracking-widest">Log de Processamento e Auditoria</h3>
         </div>
         <div className="overflow-x-auto">
           <table className="w-full text-left">
              <thead>
                <tr className="border-b border-slate-100 text-[10px] font-black uppercase text-slate-400">
                  <th className="py-4 px-4">MU</th>
                  <th className="py-4 px-4">Impacto</th>
                  <th className="py-4 px-4 text-center">Tipo de Auditoria</th>
                </tr>
              </thead>
              <tbody>
                {processedLog.map((l, i) => (
                  <tr key={i} className="border-b border-slate-50">
                    <td className="py-4 px-4 font-black text-xs">{l.mu}</td>
                    <td className="py-4 px-4 font-black text-[#E30613]">{formatCurrency(l.margem)}</td>
                    <td className="py-4 px-4 text-center">
                       {l.status === 'sucesso' ? (
                         <span className="px-3 py-1 bg-blue-50 text-blue-600 rounded-lg text-[9px] font-black uppercase">Venda deste Mês</span>
                       ) : (
                         <span className="px-3 py-1 bg-emerald-50 text-emerald-600 rounded-lg text-[9px] font-black uppercase">Ajuste de Retroativo</span>
                       )}
                    </td>
                  </tr>
                ))}
              </tbody>
           </table>
         </div>
      </div>
    </div>
  );
};

