export const AjustesFinaisPage: React.FC<AjustesFinaisPageProps> = ({ data, onDeletePedido, onCloseMonth }) => {
  const [showConfirmModal, setShowConfirmModal] = useState(false);

  const handleConfirm = () => {
    if (!data) return;
    onCloseMonth(data);
    setShowConfirmModal(false);
  };

  const handleExportExcel = () => {
    if (!data || data.pedidos.length === 0) return;

    const exportData = data.pedidos.map(p => ({
      "Nº Pedido MU": p.id,
      "Data Faturamento": p.data,
      "Canal Venda": p.canal,
      "Vendedor": p.vendedor,
      "Total Faturado (R$)": p.total,
      "Margem Original (R$)": p.margemOriginal,
      "Ajustes Manuais (R$)": (p.credito || 0) - (p.debito || 0),
      "Impacto Cancelamento (R$)": p.margemDeduzidaCancelamento || 0,
      "Impacto Devolução (R$)": p.margemDeduzidaDevolucao || 0,
      "Margem Final Auditada (R$)": p.margemAjustada,
      "Rentabilidade (%)": (p.total > 0 ? (p.margemAjustada / p.total) * 100 : 0).toFixed(2) + "%"
    }));

    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Resultado Auditado");
    XLSX.writeFile(workbook, `ABC_Auditoria_Final_${data.mesReferencia}.xlsx`);
  };

  const summary = useMemo(() => {
    if (!data || data.pedidos.length === 0) return { 
      total: 0, 
      margemOriginal: 0, 
      deducaoCancelados: 0, 
      deducaoDevolvidos: 0, 
      impactoRetroativo: 0,
      ajustesManuais: 0, 
      margemFinal: 0,
      pct: 0 
    };

    const total = data.pedidos.reduce((acc, curr) => acc + curr.total, 0);
    const margemOriginal = data.pedidos.reduce((acc, curr) => acc + curr.margemOriginal, 0);
    const deducaoCancelados = data.pedidos.reduce((acc, curr) => acc + (curr.margemDeduzidaCancelamento || 0), 0);
    const deducaoDevolvidos = data.pedidos.reduce((acc, curr) => acc + (curr.margemDeduzidaDevolucao || 0), 0);
    const ajustesManuais = data.pedidos.reduce((acc, curr) => acc + (curr.credito - curr.debito), 0);
    const margemFinal = data.pedidos.reduce((acc, curr) => acc + curr.margemAjustada, 0);

    // Impacto retroativo são as perdas de pedidos que não são deste mês (data === "Mês Anterior")
    const impactoRetroativo = data.pedidos
      .filter(p => p.data === "Mês Anterior")
      .reduce((acc, curr) => acc + curr.margemAjustada, 0);

    const pct = total > 0 ? (margemFinal / total) * 100 : 0;

    return { total, margemOriginal, deducaoCancelados, deducaoDevolvidos, impactoRetroativo, ajustesManuais, margemFinal, pct };
  }, [data]);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  };

  if (!data) return (
    <div className="bg-slate-50 border border-slate-200 rounded-[3rem] p-24 text-center">
      <Info className="w-16 h-16 text-slate-300 mx-auto mb-4" />
      <h3 className="text-3xl font-black text-slate-900 tracking-tighter uppercase">Auditagem Pendente</h3>
      <p className="text-slate-400 font-bold max-w-md mx-auto mt-2">Importe as planilhas de vendas e baixas para processar a validação final.</p>
    </div>
  );

  return (
    <div className="space-y-12">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-8 pb-4">
        <div>
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Validação Final</h2>
          <p className="text-[#E30613] font-bold mt-2 uppercase text-[11px] tracking-[0.3em]">Consolidação dos Resultados Auditados — {data.mesReferencia}</p>
        </div>
        <div className="flex items-center gap-4">
          <button onClick={handleExportExcel} className="flex items-center gap-4 px-8 py-5 bg-white border-2 border-slate-200 hover:border-[#E30613] text-slate-600 rounded-2xl shadow-xl transition-all font-black text-sm uppercase">
            <FileDown className="w-5 h-5" /> EXPORTAR RELATÓRIO
          </button>
          <button onClick={() => setShowConfirmModal(true)} className="flex items-center gap-4 px-12 py-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl shadow-2xl transition-all font-black text-sm uppercase">
            <CheckCircle2 className="w-5 h-5" /> FECHAR MÊS E SALVAR
          </button>
        </div>
      </div>

      <div className="bg-slate-900 rounded-[3rem] p-12 text-white shadow-2xl relative overflow-hidden">
         <div className="absolute right-0 top-0 opacity-5 -translate-y-1/2 translate-x-1/4">
            <TrendingUp className="w-96 h-96" />
         </div>

         <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-8 relative z-10">
            <div className="space-y-2">
               <div className="flex items-center gap-2 text-slate-500 uppercase font-black text-[9px] tracking-widest">
                  <Banknote className="w-3 h-3" /> Margem de Venda
               </div>
               <p className="text-xl font-black">{formatCurrency(summary.margemOriginal)}</p>
            </div>

            <div className="flex items-center justify-center opacity-30"><ArrowRight className="w-5 h-5" /></div>

            <div className="space-y-2">
               <div className="flex items-center gap-2 text-red-500 uppercase font-black text-[9px] tracking-widest">
                  <FileX className="w-3 h-3" /> Perdas Retroativas
               </div>
               <p className="text-xl font-black">{formatCurrency(summary.impactoRetroativo)}</p>
            </div>

            <div className="flex items-center justify-center opacity-30"><ArrowRight className="w-5 h-5" /></div>

            <div className="lg:col-span-1 space-y-2">
