import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, 
  FileUp, 
  UserCheck, 
  Calendar, 
  FileText, 
  Trash2, 
  CheckCircle2, 
  AlertCircle, 
  Camera, 
  Edit3,
  X,
  History,
  Users,
  Search
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, MarcacaoPonto, ControleHoras } from '../types';

export const HorasPage: React.FC = () => {
  const [data, setData] = useState<ControleHoras>(() => {
    const saved = localStorage.getItem('abc_gestao_horas');
    return saved ? JSON.parse(saved) : { funcionarios: [], pontos: {} };
  });

  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePis, setActivePis] = useState<string | null>(null);
  const [showEditModal, setShowEditModal] = useState<{pis: string, date: string} | null>(null);

  useEffect(() => {
    localStorage.setItem('abc_gestao_horas', JSON.stringify(data));
  }, [data]);

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split('\n');

      const newFuncs = [...data.funcionarios];
      const newPontos = { ...data.pontos };

      lines.forEach(line => {
        // Tipo 5: Cadastro de Funcionário
        if (line.substring(9, 10) === '5') {
          const pis = line.substring(22, 34);
          const nome = line.substring(34, 86).trim();
          if (!newFuncs.find(f => f.pis === pis)) {
            newFuncs.push({ pis, nome, ativo: false });
          }
        }
        // Tipo 3: Batimento de Ponto
        else if (line.substring(9, 10) === '3') {
          const dia = line.substring(10, 12);
          const mes = line.substring(12, 14);
          const ano = line.substring(14, 18);
          const hora = line.substring(18, 20);
          const min = line.substring(20, 22);
          const pis = line.substring(22, 34);

          const dateKey = `${ano}-${mes}-${dia}`;
          const time = `${hora}:${min}`;

          if (!newPontos[pis]) newPontos[pis] = [];

          let diaPonto = newPontos[pis].find(p => p.data === dateKey);
          if (!diaPonto) {
            diaPonto = { data: dateKey, batimentos: [], ajustes: [] };
            newPontos[pis].push(diaPonto);
          }

          if (!diaPonto.batimentos.includes(time)) {
            diaPonto.batimentos.push(time);
            diaPonto.ajustes.push(false);
            diaPonto.batimentos.sort();
          }
        }
      });

      setData({ funcionarios: newFuncs, pontos: newPontos });
    };
    reader.readAsText(file);
    event.target.value = "";
  };

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const daysInMonth = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: daysInMonth }, (_, i) => {
      const d = i + 1;
      return `${year}-${month}-${d.toString().padStart(2, '0')}`;
    });
  }, [selectedMonth]);

  const activeEmployee = useMemo(() => {
    return data.funcionarios.find(f => f.pis === activePis);
  }, [data.funcionarios, activePis]);

  const toggleFuncAtivo = (pis: string) => {
    setData(prev => ({
      ...prev,
      funcionarios: prev.funcionarios.map(f => f.pis === pis ? { ...f, ativo: !f.ativo } : f)
    }));
  };

  const handleManualAdjust = (pis: string, date: string, index: number, time: string) => {
    const newPontos = { ...data.pontos };
    const diaPonto = newPontos[pis].find(p => p.data === date);
    if (diaPonto) {
      diaPonto.batimentos[index] = time;
      diaPonto.ajustes[index] = true;
      diaPonto.isFalta = false;
      setData({ ...data, pontos: newPontos });
    }
  };

  const handleToggleFalta = (pis: string, date: string) => {
    const newPontos = { ...data.pontos };
    if (!newPontos[pis]) newPontos[pis] = [];
    let diaPonto = newPontos[pis].find(p => p.data === date);
    if (!diaPonto) {
      diaPonto = { data: date, batimentos: [], ajustes: [] };
      newPontos[pis].push(diaPonto);
    }
    diaPonto.isFalta = !diaPonto.isFalta;
    if (diaPonto.isFalta) {
      diaPonto.batimentos = [];
      diaPonto.ajustes = [];
    }
    setData({ ...data, pontos: newPontos });
  };

  const handleExportPDF = () => {
    if (!activeEmployee || !activePis) return;
    const doc = new jsPDF();
    const monthName = new Date(selectedMonth + '-01').toLocaleString('pt-BR', { month: 'long', year: 'numeric' }).toUpperCase();

    doc.setFontSize(18);
    doc.text(`ESPELHO DE PONTO - ${activeEmployee.nome}`, 15, 20);
    doc.setFontSize(10);
    doc.text(`REFERÊNCIA: ${monthName} | PIS: ${activePis}`, 15, 28);

    const rows = currentMonthDays.map(day => {
      const p = data.pontos[activePis]?.find(x => x.data === day);
      const parts = day.split('-');
      const formattedDate = `${parts[2]}/${parts[1]}`;

      if (p?.isFalta) return [formattedDate, 'FALTA', '', '', '', 'AUSÊNCIA'];

      return [
        formattedDate,
        p?.batimentos[0] || '--:--',
        p?.batimentos[1] || '--:--',
        p?.batimentos[2] || '--:--',
        p?.batimentos[3] || '--:--',
        p?.observacao || ''
      ];
    });

    (doc as any).autoTable({
      startY: 35,
      head: [['DATA', 'ENTRADA', 'ALMOÇO SAÍDA', 'ALMOÇO VOLTA', 'SAÍDA FINAL', 'OBSERVAÇÕES']],
      body: rows,
      theme: 'grid',
      headStyles: { fillColor: [10, 17, 33] }
    });

    doc.save(`Ponto_${activeEmployee.nome}_${selectedMonth}.pdf`);
  };

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Horas</h2>
          <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Auditoria de Frequência e Pontualidade</p>
        </div>
        <div className="flex gap-4">
           <label className="flex items-center gap-4 px-10 py-5 bg-[#0A1121] text-white rounded-2xl cursor-pointer hover:bg-black transition-all shadow-xl active:scale-95 font-black text-sm uppercase tracking-wider">
            <FileUp className="w-5 h-5 text-[#E30613]" />
            <span>SUBIR ARQUIVO AFD (.TXT)</span>
            <input type="file" className="hidden" accept=".txt" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-12">
        {/* Sidebar de Funcionários */}
        <div className="lg:col-span-1 space-y-6">
           <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
              <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2">
                <Users className="w-4 h-4" /> Gestão de Equipe
              </h3>
              <div className="space-y-3">
                 {data.funcionarios.length === 0 ? (
                   <p className="text-[10px] font-bold text-slate-300 italic text-center py-10">Importe o arquivo AFD para listar os funcionários</p>
                 ) : (
                   data.funcionarios.map(f => (
                     <div key={f.pis} className="flex flex-col gap-2 p-4 rounded-2xl border border-slate-50 hover:border-slate-200 transition-all bg-slate-50/30">
                        <div className="flex items-center justify-between">
                           <div className="flex items-center gap-3">
                              <input 
                                type="checkbox" 
                                checked={f.ativo} 
                                onChange={() => toggleFuncAtivo(f.pis)}
                                className="w-4 h-4 accent-[#E30613]"
                              />
                              <span className={`text-xs font-black uppercase ${f.ativo ? 'text-slate-900' : 'text-slate-400'}`}>{f.nome}</span>
                           </div>
                        </div>
                        {f.ativo && (
                          <button 
                            onClick={() => setActivePis(f.pis)}
                            className={`mt-2 py-2 px-4 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activePis === f.pis ? 'bg-emerald-600 text-white shadow-lg' : 'bg-white text-slate-400 border border-slate-200 hover:bg-slate-100'}`}
                          >
                            Visualizar Cartão
                          </button>
                        )}
                     </div>
                   ))
                 )}
              </div>
           </div>

           <div className="bg-[#0A1121] rounded-[2rem] p-6 text-white shadow-xl flex items-center gap-4">
              <Calendar className="w-8 h-8 text-[#E30613]" />
              <div>
                 <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Mês em análise</p>
                 <input 
                    type="month" 
                    value={selectedMonth} 
                    onChange={(e) => setSelectedMonth(e.target.value)}
                    className="bg-transparent text-sm font-black uppercase outline-none cursor-pointer"
                 />
              </div>
           </div>
        </div>

        {/* Cartão de Ponto */}
        <div className="lg:col-span-3 space-y-6">
           {activeEmployee ? (
             <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden animate-in fade-in duration-500">
                <div className="p-10 border-b border-slate-100 flex flex-col md:flex-row md:items-center justify-between gap-6 bg-slate-50/50">
                   <div>
                      <span className="text-[10px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full uppercase border border-emerald-100">CARTÃO DE PONTO ATIVO</span>
                      <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter mt-2">{activeEmployee.nome}</h3>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">PIS: {activeEmployee.pis}</p>
                   </div>
                   <button 
                    onClick={handleExportPDF}
                    className="flex items-center gap-4 px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-black transition-all shadow-xl"
                   >
                     <FileText className="w-4 h-4" /> GERAR RELATÓRIO PDF
                   </button>
                </div>

                <div className="overflow-x-auto">
                   <table className="w-full text-left">
                      <thead>
                        <tr className="bg-slate-950 text-slate-500 border-b border-slate-800">
                          <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest">Dia</th>
                          <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest">Entrada</th>
                          <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest">Almoço (S)</th>
                          <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest">Almoço (R)</th>
                          <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest">Saída Final</th>
                          <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest text-center">Ações</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                         {currentMonthDays.map(day => {
                            const p = data.pontos[activePis!]?.find(x => x.data === day);
                            const dayNum = day.split('-')[2];

                            return (
                               <tr key={day} className={`hover:bg-slate-50 transition-all ${p?.isFalta ? 'bg-red-50/30' : ''}`}>
                                  <td className="px-8 py-6">
                                     <div className="flex flex-col">
                                        <span className="text-lg font-black text-slate-900">{dayNum}</span>
                                        <span className="text-[9px] font-bold text-slate-400 uppercase">
                                          {new Date(day + 'T00:00:00').toLocaleDateString('pt-BR', { weekday: 'short' })}
                                        </span>
                                     </div>
                                  </td>
                                  {[0, 1, 2, 3].map(idx => (
                                     <td key={idx} className="px-8 py-6">
                                        <div className="relative group">
                                           <input 
                                              type="time" 
                                              value={p?.batimentos[idx] || ''}
                                              onChange={(e) => handleManualAdjust(activePis!, day, idx, e.target.value)}
                                              className={`bg-transparent text-sm font-black outline-none border-b-2 transition-all ${p?.ajustes[idx] ? 'border-amber-400 text-amber-600' : 'border-transparent text-slate-600 focus:border-[#E30613]'}`}
                                           />
                                           {p?.ajustes[idx] && <Edit3 className="absolute -right-4 top-1/2 -translate-y-1/2 w-3 h-3 text-amber-400" />}
                                        </div>
                                     </td>
                                  ))}
                                  <td className="px-8 py-6">
                                     <div className="flex items-center justify-center gap-2">
                                        <button 
                                          onClick={() => handleToggleFalta(activePis!, day)}
                                          className={`px-4 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${p?.isFalta ? 'bg-[#E30613] text-white shadow-lg' : 'bg-slate-100 text-slate-400 hover:bg-red-50 hover:text-[#E30613]'}`}
                                        >
                                          {p?.isFalta ? 'FALTA' : 'MARCAR FALTA'}
                                        </button>
                                     </div>
                                  </td>
                               </tr>
                            );
                         })}
                      </tbody>
                   </table>
                </div>
             </div>
           ) : (
             <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-[4rem] py-64 flex flex-col items-center justify-center text-slate-300">
               <UserCheck className="w-24 h-24 mb-10 opacity-20" />
               <p className="text-3xl font-black text-slate-800 tracking-tight">Selecione um Funcionário</p>
               <p className="text-slate-400 font-medium mt-2">Habilite o funcionário ativo na lista lateral</p>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Sidebar } from './components/Sidebar';
import { ConferenciaPage } from './pages/ConferenciaPage';
import { CanceladosPage } from './pages/CanceladosPage';
import { DevolvidosPage } from './pages/DevolvidosPage';
import { AjustesVariosPage } from './pages/AjustesVariosPage';
import { AjustesFinaisPage } from './pages/AjustesFinaisPage';
import { DashboardPage } from './pages/DashboardPage';
import { AnaliseVendedorPage } from './pages/AnaliseVendedorPage';
import { ConfiguracaoPage } from './pages/ConfiguracaoPage';
import { ContasPagarPage } from './pages/ContasPagarPage';
import { FluxoCaixaPage } from './pages/FluxoCaixaPage';
import { DREPage } from './pages/DREPage';
import { ComissaoPage } from './pages/ComissaoPage';
import { FretePage } from './pages/FretePage';
import { HorasPage } from './pages/HorasPage';
import { PageId, MesConferencia, Pedido, HistoricoConsolidado } from './types';
import { Sparkles } from 'lucide-react';
import { storageService } from './services/storageService';

const App: React.FC = () => {
  const [activePage, setActivePage] = useState<PageId>('dashboard');
  const [data, setData] = useState<MesConferencia | null>(storageService.getData());
  const [history, setHistory] = useState<HistoricoConsolidado>(storageService.getHistory());
  const [showToast, setShowToast] = useState<{show: boolean, msg: string, type: 'success' | 'danger'}>({show: false, msg: '', type: 'success'});

  // REGRA DE OURO DO SISTEMA: Composição da Margem Final
  const calculateMargemFinal = (p: Pedido): number => {
    return p.margemOriginal + 
           (p.credito || 0) - 
           (p.debito || 0) + 
           (p.margemDeduzidaCancelamento || 0) + 
           (p.margemDeduzidaDevolucao || 0);
  };

  const handleUpdatePedido = useCallback((id: string, updates: Partial<Pedido>) => {
    setData(current => {
      if (!current) return null;
      const newPedidos = current.pedidos.map((p) => {
        if (p.id === id) {
          const updated = { ...p, ...updates };
          updated.margemAjustada = calculateMargemFinal(updated);
          return updated;
        }
        return p;
      });
      const updatedData = { ...current, pedidos: newPedidos };
      storageService.saveData(updatedData);
      return updatedData;
    });
  }, []);

  const handleSetData = (newData: MesConferencia | null) => {
    if (newData) {
      // Recalcula margens de todos ao importar novas planilhas (Cancelados/Devolvidos)
      newData.pedidos = newData.pedidos.map(p => ({
        ...p,
        margemAjustada: calculateMargemFinal(p)
      }));
      storageService.saveData(newData);
    } else {
      storageService.clearData();
    }
    setData(newData);
  };

  const handleCloseMonth = (consolidated: MesConferencia) => {
    storageService.saveToHistory(consolidated);
    storageService.clearData();
    setData(null);
    setHistory(storageService.getHistory());
    setActivePage('dashboard');
    setShowToast({show: true, msg: 'Mês consolidado e salvo com sucesso!', type: 'success'});
    setTimeout(() => setShowToast({show: false, msg: '', type: 'success'}), 4000);
  };

  const handleDeletePedido = (id: string) => {
    setData(current => {
      if (!current) return null;
      const newPedidos = current.pedidos.filter(p => p.id !== id);
      const updatedData = { ...current, pedidos: newPedidos };
      storageService.saveData(updatedData);
      return updatedData;
    });
  };

  const handleClearDatabase = () => {
    storageService.clearAll();
    setData(null);
    setHistory({ meses: [] });
    setActivePage('dashboard');
    setShowToast({show: true, msg: 'Banco de dados resetado!', type: 'danger'});
    setTimeout(() => setShowToast({show: false, msg: '', type: 'success'}), 4000);
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex selection:bg-red-100 selection:text-red-900 antialiased">
      <Sidebar activePage={activePage} setActivePage={setActivePage} />
      <main className="flex-grow flex flex-col min-w-0">
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-40 flex items-center justify-between px-12">
          <div className="flex items-center gap-3">
            <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">ABC ITU — Gestão de Resultados</p>
          </div>
          <div className="flex items-center gap-2 px-4 py-2 bg-slate-50 rounded-full border border-slate-100">
            <span className="text-[10px] font-black text-slate-500 uppercase">{history.meses.length} Meses no Banco de Dados</span>
          </div>
        </header>

        {showToast.show && (
          <div className="fixed top-24 right-12 z-[250] animate-in slide-in-from-right-8 fade-in duration-500">
            <div className={`${showToast.type === 'success' ? 'bg-emerald-600' : 'bg-[#E30613]'} text-white px-8 py-5 rounded-3xl shadow-2xl flex items-center gap-4`}>
               <Sparkles className="w-5 h-5" />
               <p className="text-[10px] font-black uppercase">{showToast.msg}</p>
            </div>
          </div>
        )}

        <div className="p-8 lg:p-12">
          <div className="bg-white p-10 rounded-[4rem] shadow-xl border border-slate-200/50 min-h-[75vh]">
            {activePage === 'dashboard' && <DashboardPage history={history} />}
            {activePage === 'conferencia' && <ConferenciaPage data={data} onSetData={handleSetData} onUpdatePedido={handleUpdatePedido} onDeletePedido={handleDeletePedido} onNavigateToAjustes={() => setActivePage('ajustes')} />}
            {activePage === 'cancelados' && <CanceladosPage data={data} onSetData={handleSetData} />}
            {activePage === 'devolvidos' && <DevolvidosPage data={data} onSetData={handleSetData} />}
            {activePage === 'ajustes-varios' && <AjustesVariosPage data={data} onSetData={handleSetData} />}
            {activePage === 'ajustes' && <AjustesFinaisPage data={data} onDeletePedido={handleDeletePedido} onCloseMonth={handleCloseMonth} />}
            {activePage === 'analise-vendedor' && <AnaliseVendedorPage history={history} />}
            {activePage === 'contas-pagar' && <ContasPagarPage />}
            {activePage === 'fluxo-caixa' && <FluxoCaixaPage />}
            {activePage === 'dre' && <DREPage />}
            {activePage === 'comissao' && <ComissaoPage history={history} />}
            {activePage === 'frete' && <FretePage />}
            {activePage === 'horas' && <HorasPage />}
            {activePage === 'configuracao' && <ConfiguracaoPage onClearDatabase={handleClearDatabase} />}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

export interface AjusteExtra {
  id: string;
  descricao: string;
  valor: number;
  tipo: 'credito' | 'debito';
  pedidoMU?: string;
  data: string;
}

export interface Pedido {
  id: string;
  data: string;
  canal: string;
  vendedor: string;
  mkt: number;
  cac: number;
  total: number;
  totalOriginal?: number;
  frete: number;
  isCancelado?: boolean;
  valorCancelado?: number;
  margemDeduzidaCancelamento?: number;
  isDevolvido?: boolean;
  valorDevolvido?: number;
