import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, UserCheck, Calendar, FileText, Trash2, 
  CheckCircle2, AlertTriangle, Edit3, X, History, Users, 
  Search, LayoutDashboard, ShieldCheck, TrendingUp, AlertCircle, Save
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, MarcacaoPonto, ControleHoras, LogAuditoriaPonto } from '../types';

type TabId = 'dashboard' | 'auditoria' | 'equipe';

export const HorasPage: React.FC = () => {
  const [data, setData] = useState<ControleHoras>(() => {
    const saved = localStorage.getItem('abc_gestao_horas_v2');
    return saved ? JSON.parse(saved) : { funcionarios: [], pontos: {}, logs: [] };
  });

  const [activeTab, setActiveTab] = useState<TabId>('dashboard');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePis, setActivePis] = useState<string | null>(null);

  // Estado para modal de edição
  const [editingPoint, setEditingPoint] = useState<{pis: string, date: string, index: number, value: string} | null>(null);
  const [adjustmentReason, setAdjustmentReason] = useState('');

  useEffect(() => {
    localStorage.setItem('abc_gestao_horas_v2', JSON.stringify(data));
  }, [data]);

  // Helper para converter HH:mm para minutos
  const timeToMinutes = (time: string): number => {
    if (!time || !time.includes(':')) return 0;
    const [h, m] = time.split(':').map(Number);
    return (h * 60) + m;
  };

  const minutesToTime = (mins: number): string => {
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  const calculateDay = (batimentos: string[], jornadaNominal: number = 480) => {
    if (batimentos.length < 2) return { trabalhadas: 0, extras: 0, atraso: jornadaNominal };

    let totalMinutes = 0;
    for (let i = 0; i < batimentos.length - 1; i += 2) {
      const inMin = timeToMinutes(batimentos[i]);
      const outMin = timeToMinutes(batimentos[i+1]);
      if (outMin > inMin) totalMinutes += (outMin - inMin);
    }

    const diff = totalMinutes - jornadaNominal;
    return {
      trabalhadas: totalMinutes,
      extras: diff > 0 ? diff : 0,
      atraso: diff < 0 ? Math.abs(diff) : 0
    };
  };

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split('\n');
      const newFuncs = [...data.funcionarios];
      const newPontos = { ...data.pontos };

      lines.forEach(line => {
        if (line.substring(9, 10) === '5') {
          const pis = line.substring(22, 34);
          const nome = line.substring(34, 86).trim();
          if (!newFuncs.find(f => f.pis === pis)) {
            newFuncs.push({ pis, nome, ativo: true, jornadaDiariaMinutos: 480, setor: 'Geral' });
          }
        } else if (line.substring(9, 10) === '3') {
          const dia = line.substring(10, 12), mes = line.substring(12, 14), ano = line.substring(14, 18);
          const hora = line.substring(18, 20), min = line.substring(20, 22), pis = line.substring(22, 34);
          const dateKey = `${ano}-${mes}-${dia}`;
          const time = `${hora}:${min}`;

          if (!newPontos[pis]) newPontos[pis] = [];
          let diaPonto = newPontos[pis].find(p => p.data === dateKey);
          if (!diaPonto) {
            diaPonto = { data: dateKey, batimentosOriginais: [], batimentosAjustados: [], isFalta: false };
            newPontos[pis].push(diaPonto);
          }
          if (!diaPonto.batimentosOriginais.includes(time)) {
            diaPonto.batimentosOriginais.push(time);
            diaPonto.batimentosOriginais.sort();
            diaPonto.batimentosAjustados = [...diaPonto.batimentosOriginais];
          }
        }
      });
      setData(prev => ({ ...prev, funcionarios: newFuncs, pontos: newPontos }));
      setActiveTab('auditoria');
    };
    reader.readAsText(file);
  };

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const days = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: days }, (_, i) => `${year}-${month}-${(i + 1).toString().padStart(2, '0')}`);
  }, [selectedMonth]);

  const activeEmployee = useMemo(() => data.funcionarios.find(f => f.pis === activePis), [data.funcionarios, activePis]);

  const handleSaveAdjustment = () => {
    if (!editingPoint || !adjustmentReason) return;
    const { pis, date, index, value } = editingPoint;
    const newPontos = { ...data.pontos };
    const diaPonto = newPontos[pis].find(p => p.data === date);

    if (diaPonto) {
      const oldVal = diaPonto.batimentosAjustados[index] || '--:--';
      diaPonto.batimentosAjustados[index] = value;
      diaPonto.batimentosAjustados.sort();

      const log: LogAuditoriaPonto = {
        id: crypto.randomUUID(),
        timestamp: new Date().toISOString(),
        usuario: 'Administrador',
        pis,
        dataPonto: date,
        campo: `Batida ${index + 1}`,
        valorAntigo: oldVal,
        valorNovo: value,
        motivo: adjustmentReason
      };

      setData(prev => ({
        ...prev,
        pontos: newPontos,
        logs: [log, ...prev.logs]
      }));
    }
    setEditingPoint(null);
    setAdjustmentReason('');
  };

  const dashboardStats = useMemo(() => {
    const activeFuncs = data.funcionarios.filter(f => f.ativo);
    let totalExtras = 0;
    let totalAtrasos = 0;
    let totalFaltas = 0;

    activeFuncs.forEach(f => {
      const pontos = data.pontos[f.pis] || [];
      pontos.filter(p => p.data.startsWith(selectedMonth)).forEach(p => {
        if (p.isFalta) totalFaltas++;
        else {
          const calc = calculateDay(p.batimentosAjustados, f.jornadaDiariaMinutos);
          totalExtras += calc.extras;
          totalAtrasos += calc.atraso;
        }
      });
    });

    return { totalExtras, totalAtrasos, totalFaltas, activeCount: activeFuncs.length };
  }, [data, selectedMonth]);

  return (
    <div className="space-y-10 pb-20">
      {/* Header Profissional */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <div className="flex items-center gap-3">
             <ShieldCheck className="w-8 h-8 text-[#E30613]" />
             <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Auditoria de Ponto</h2>
          </div>
          <p className="text-slate-400 font-bold uppercase text-[10px] tracking-[0.4em] ml-11">Compliance e Gestão de Frequência</p>
        </div>
        <div className="flex gap-4">
          <label className="flex items-center gap-4 px-8 py-4 bg-[#0A1121] text-white rounded-2xl cursor-pointer hover:bg-black transition-all shadow-xl font-black text-xs uppercase tracking-widest">
            <FileUp className="w-5 h-5 text-[#E30613]" />
            IMPORTAR AFD
            <input type="file" className="hidden" accept=".txt" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex gap-2 p-1.5 bg-slate-100 rounded-3xl w-fit">
        {[
          { id: 'dashboard', label: 'Visão Geral', icon: LayoutDashboard },
          { id: 'auditoria', label: 'Cartão de Ponto', icon: History },
          { id: 'equipe', label: 'Colaboradores', icon: Users },
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as TabId)}
            className={`flex items-center gap-3 px-8 py-3.5 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === tab.id ? 'bg-white text-slate-900 shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
          </button>
        ))}
      </div>

      {/* Tab: Dashboard */}
      {activeTab === 'dashboard' && (
        <div className="space-y-10 animate-in fade-in duration-500">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
             <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
                <div className="p-3 bg-red-50 rounded-2xl w-fit mb-4"><Clock className="text-[#E30613]" /></div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Extras (Mês)</p>
                <p className="text-4xl font-black text-slate-900 tracking-tighter">{minutesToTime(dashboardStats.totalExtras)}</p>
             </div>
             <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
                <div className="p-3 bg-amber-50 rounded-2xl w-fit mb-4"><TrendingUp className="text-amber-500" /></div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Atrasos</p>
                <p className="text-4xl font-black text-slate-900 tracking-tighter">{minutesToTime(dashboardStats.totalAtrasos)}</p>
             </div>
             <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
                <div className="p-3 bg-slate-100 rounded-2xl w-fit mb-4"><AlertCircle className="text-slate-500" /></div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Faltas Brutas</p>
                <p className="text-4xl font-black text-slate-900 tracking-tighter">{dashboardStats.totalFaltas} Dias</p>
             </div>
             <div className="bg-[#0A1121] rounded-[2.5rem] p-8 shadow-xl text-white">
                <div className="p-3 bg-white/10 rounded-2xl w-fit mb-4"><Users className="text-[#E30613]" /></div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Equipe Ativa</p>
                <p className="text-4xl font-black tracking-tighter">{dashboardStats.activeCount} Colaboradores</p>
             </div>
          </div>

          <div className="bg-blue-50 border border-blue-100 rounded-[2.5rem] p-8 flex items-start gap-6">
             <AlertTriangle className="w-10 h-10 text-blue-600 shrink-0" />
             <div>
                <h4 className="text-sm font-black text-blue-900 uppercase">Alertas de Compliance</h4>
                <p className="text-blue-800/70 text-xs mt-1 leading-relaxed">
                   Existem 3 colaboradores com intervalo de almoço inferior a 1 hora. Risco de multa por infração ao Artigo 71 da CLT.
                </p>
             </div>
          </div>
        </div>
      )}

      {/* Tab: Auditoria */}
      {activeTab === 'auditoria' && (
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-12 animate-in fade-in duration-500">
           {/* Lista Lateral */}
           <div className="lg:col-span-1 space-y-6">
              <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
                 <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Colaboradores</h3>
                 <div className="space-y-2">
                    {data.funcionarios.map(f => (
                      <button 
                        key={f.pis} 
                        onClick={() => setActivePis(f.pis)}
                        className={`w-full text-left p-4 rounded-2xl transition-all border ${activePis === f.pis ? 'bg-[#E30613] text-white border-[#E30613] shadow-lg shadow-red-200' : 'bg-slate-50 border-transparent text-slate-600 hover:bg-slate-100'}`}
                      >
                         <p className="text-xs font-black uppercase truncate">{f.nome}</p>
                         <p className={`text-[9px] font-bold ${activePis === f.pis ? 'text-white/60' : 'text-slate-400'}`}>PIS: {f.pis}</p>
                      </button>
                    ))}
                 </div>
              </div>
              <div className="bg-[#0A1121] rounded-[2rem] p-6 text-white shadow-xl flex items-center gap-4">
                <Calendar className="w-8 h-8 text-[#E30613]" />
                <div>
                   <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Referência</p>
                   <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="bg-transparent text-sm font-black uppercase outline-none cursor-pointer" />
                </div>
             </div>
           </div>

           {/* Cartão de Ponto Detalhado */}
           <div className="lg:col-span-3 space-y-6">
              {activeEmployee ? (
                <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                   <div className="p-10 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
                      <div>
                         <h3 className="text-3xl font-black text-slate-900 tracking-tighter uppercase">{activeEmployee.nome}</h3>
                         <div className="flex items-center gap-4 mt-2">
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Jornada: 8h/dia</span>
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Score Pontualidade: 98/100</span>
                         </div>
                      </div>
                      <button className="flex items-center gap-4 px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-black transition-all">
                        <FileText className="w-4 h-4" /> IMPRIMIR ESPELHO
                      </button>
                   </div>

                   <div className="overflow-x-auto">
                      <table className="w-full text-left">
                        <thead>
                          <tr className="bg-slate-900 text-slate-500">
                            <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest">Data</th>
                            <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest">Batidas</th>
                            <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest text-right">Trabalhadas</th>
                            <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest text-right">Extras</th>
                            <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest text-right">Atrasos</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                          {currentMonthDays.map(day => {
                            const p = data.pontos[activePis!]?.find(x => x.data === day);
                            const calc = calculateDay(p?.batimentosAjustados || [], activeEmployee.jornadaDiariaMinutos);

                            return (
                              <tr key={day} className={`group hover:bg-slate-50 transition-all ${p?.isFalta ? 'bg-red-50/20' : ''}`}>
                                <td className="px-8 py-6">
                                   <div className="flex flex-col">
                                      <span className="text-lg font-black text-slate-900">{day.split('-')[2]}</span>
                                      <span className="text-[9px] font-black text-slate-400 uppercase">{new Date(day+'T00:00:00').toLocaleDateString('pt-BR', { weekday: 'short' })}</span>
                                   </div>
                                </td>
                                <td className="px-8 py-6">
                                   <div className="flex flex-wrap gap-2">
                                      {(p?.batimentosAjustados.length || 0) > 0 ? p?.batimentosAjustados.map((time, idx) => (
                                        <button 
                                          key={idx}
                                          onClick={() => setEditingPoint({ pis: activePis!, date: day, index: idx, value: time })}
                                          className="px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-xs font-black text-slate-700 hover:border-[#E30613] transition-all flex items-center gap-2"
                                        >
                                          {time} <Edit3 className="w-3 h-3 opacity-0 group-hover:opacity-100" />
                                        </button>
                                      )) : <span className="text-slate-300 font-bold text-xs">Sem Marcação</span>}
                                      <button className="p-1.5 rounded-lg border border-dashed border-slate-300 text-slate-300 hover:text-[#E30613] hover:border-[#E30613] transition-all">
                                        <Plus className="w-4 h-4" />
                                      </button>
                                   </div>
                                </td>
                                <td className="px-8 py-6 text-right font-black text-slate-900">{minutesToTime(calc.trabalhadas)}</td>
                                <td className="px-8 py-6 text-right font-black text-emerald-600">{calc.extras > 0 ? minutesToTime(calc.extras) : '—'}</td>
                                <td className="px-8 py-6 text-right font-black text-[#E30613]">{calc.atraso > 0 ? minutesToTime(calc.atraso) : '—'}</td>
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                   </div>
                </div>
              ) : (
                <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-[4rem] py-64 flex flex-col items-center justify-center text-slate-300">
                  <UserCheck className="w-20 h-20 mb-8 opacity-20" />
                  <p className="text-2xl font-black text-slate-800 tracking-tight uppercase">Selecione um Colaborador</p>
                </div>
              )}
           </div>
        </div>
      )}

      {/* Modal de Ajuste de Ponto */}
      {editingPoint && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-950/90 backdrop-blur-md">
           <div className="bg-white rounded-[3rem] shadow-2xl max-w-lg w-full p-12 space-y-8 animate-in zoom-in-95">
              <div className="flex items-center gap-4 border-b border-slate-100 pb-6">
                 <div className="p-3 bg-red-50 rounded-2xl"><Edit3 className="text-[#E30613]" /></div>
                 <div>
                    <h3 className="text-2xl font-black text-slate-900 tracking-tighter uppercase">Ajustar Marcação</h3>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Alteração Manual de Registro</p>
                 </div>
              </div>

              <div className="space-y-6">
                 <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Nova Hora</label>
                       <input 
                         type="time" 
                         value={editingPoint.value}
                         onChange={(e) => setEditingPoint({...editingPoint, value: e.target.value})}
                         className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-black text-slate-900 outline-none focus:ring-4 focus:ring-red-500/10"
                       />
                    </div>
                    <div className="space-y-2 text-right">
