                   <div className="overflow-x-auto">
                      <table className="w-full text-left">
                        <thead>
                          <tr className="bg-slate-900 text-slate-500">
                            <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest">Data</th>
