                            <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest text-right">Extras</th>
                            <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest text-right">Atrasos</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                          {currentMonthDays.map(day => {
                            const p = data.pontos[activePis!]?.find(x => x.data === day);
                            const calc = calculateDay(p?.batimentosAjustados || [], activeEmployee.jornadaDiariaMinutos);

                            return (
                              <tr key={day} className={`group hover:bg-slate-50 transition-all ${p?.isFalta ? 'bg-red-50/20' : ''}`}>
                                <td className="px-8 py-6">
                                   <div className="flex flex-col">
                                      <span className="text-lg font-black text-slate-900">{day.split('-')[2]}</span>
                                      <span className="text-[9px] font-black text-slate-400 uppercase">{new Date(day+'T00:00:00').toLocaleDateString('pt-BR', { weekday: 'short' })}</span>
                                   </div>
                                </td>
                                <td className="px-8 py-6">
                                   <div className="flex flex-wrap gap-2">
                                      {(p?.batimentosAjustados.length || 0) > 0 ? p?.batimentosAjustados.map((time, idx) => (
                                        <button 
                                          key={idx}
                                          onClick={() => setEditingPoint({ pis: activePis!, date: day, index: idx, value: time })}
                                          className="px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-xs font-black text-slate-700 hover:border-[#E30613] transition-all flex items-center gap-2"
                                        >
                                          {time} <Edit3 className="w-3 h-3 opacity-0 group-hover:opacity-100" />
                                        </button>
                                      )) : <span className="text-slate-300 font-bold text-xs">Sem Marcação</span>}
                                      <button className="p-1.5 rounded-lg border border-dashed border-slate-300 text-slate-300 hover:text-[#E30613] hover:border-[#E30613] transition-all">
                                        <Plus className="w-4 h-4" />
                                      </button>
                                   </div>
                                </td>
                                <td className="px-8 py-6 text-right font-black text-slate-900">{minutesToTime(calc.trabalhadas)}</td>
                                <td className="px-8 py-6 text-right font-black text-emerald-600">{calc.extras > 0 ? minutesToTime(calc.extras) : '—'}</td>
                                <td className="px-8 py-6 text-right font-black text-[#E30613]">{calc.atraso > 0 ? minutesToTime(calc.atraso) : '—'}</td>
