              </div>

              <div className="space-y-6">
                 <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Nova Hora</label>
                       <input 
                         type="time" 
                         value={editingPoint.value}
                         onChange={(e) => setEditingPoint({...editingPoint, value: e.target.value})}
                         className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-black text-slate-900 outline-none focus:ring-4 focus:ring-red-500/10"
                       />
