                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Data do Evento</label>
                       <p className="px-2 py-4 font-black text-slate-900">{editingPoint.date}</p>
                    </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Motivo do Ajuste (Obrigatório)</label>
                    <textarea 
                      required
                      placeholder="Ex: Esquecimento, Problema no relógio, Reunião externa..."
                      value={adjustmentReason}
                      onChange={(e) => setAdjustmentReason(e.target.value)}
                      className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-slate-900 min-h-[120px] outline-none focus:ring-4 focus:ring-red-500/10"
                    />
