  const timeToMinutes = (time: string): number => {
    if (!time || !time.includes(':')) return 0;
    const [h, m] = time.split(':').map(Number);
    return (h * 60) + m;
  };

  const minutesToTime = (mins: number): string => {
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  const calculateDay = (batimentos: string[], jornadaNominal: number = 480) => {
    if (!batimentos || batimentos.length < 2) return { trabalhadas: 0, extras: 0, atraso: jornadaNominal };

    let totalMinutes = 0;
    const sortedBatimentos = [...batimentos].sort();
    for (let i = 0; i < sortedBatimentos.length - 1; i += 2) {
      const inMin = timeToMinutes(sortedBatimentos[i]);
      const outMin = timeToMinutes(sortedBatimentos[i+1]);
      if (outMin > inMin) totalMinutes += (outMin - inMin);
    }

    const diff = totalMinutes - jornadaNominal;
    return {
      trabalhadas: totalMinutes,
      extras: diff > 0 ? diff : 0,
      atraso: diff < 0 ? Math.abs(diff) : 0
    };
  };

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split('\n');
      const newFuncs = [...data.funcionarios];
      const newPontos = { ...data.pontos };

      lines.forEach(line => {
        const tipo = line.substring(9, 10);

        if (tipo === '5') {
          const pis = line.substring(22, 34).trim();
          const nome = line.substring(34, 86).trim();
          if (pis && !newFuncs.find(f => f.pis === pis)) {
            newFuncs.push({ pis, nome, ativo: true, jornadaDiariaMinutos: 480 });
          }
        } else if (tipo === '3') {
          const dia = line.substring(10, 12), mes = line.substring(12, 14), ano = line.substring(14, 18);
          const hora = line.substring(18, 20), min = line.substring(20, 22), pis = line.substring(22, 34).trim();
          const dateKey = `${ano}-${mes}-${dia}`;
          const time = `${hora}:${min}`;

          if (pis) {
            if (!newPontos[pis]) newPontos[pis] = [];
            let diaPonto = newPontos[pis].find(p => p.data === dateKey);
            if (!diaPonto) {
              diaPonto = { data: dateKey, batimentosOriginais: [], batimentosAjustados: [], isFalta: false };
              newPontos[pis].push(diaPonto);
            }
            if (!diaPonto.batimentosOriginais.includes(time)) {
              diaPonto.batimentosOriginais.push(time);
              diaPonto.batimentosOriginais.sort();
              diaPonto.batimentosAjustados = [...diaPonto.batimentosOriginais];
            }
          }
        }
      });
      setData(prev => ({ ...prev, funcionarios: newFuncs, pontos: newPontos }));
    };
    reader.readAsText(file);
    event.target.value = "";
  };

  const filteredFuncionarios = useMemo(() => {
    return data.funcionarios.filter(f => {
      if (statusFilter === 'ativos') return f.ativo;
      if (statusFilter === 'inativos') return !f.ativo;
      return true;
    }).sort((a, b) => a.nome.localeCompare(b.nome));
  }, [data.funcionarios, statusFilter]);

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const daysCount = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: daysCount }, (_, i) => `${year}-${month}-${(i + 1).toString().padStart(2, '0')}`);
  }, [selectedMonth]);

  const activeEmployee = useMemo(() => data.funcionarios.find(f => f.pis === activePis), [data.funcionarios, activePis]);

  const toggleFuncStatus = (pis: string) => {
    setData(prev => ({
      ...prev,
      funcionarios: prev.funcionarios.map(f => f.pis === pis ? { ...f, ativo: !f.ativo } : f)
    }));
  };

  const handleSaveAdjustment = () => {
    if (!editingPoint || !adjustmentReason) return;
    const { pis, date, index, value } = editingPoint;
    const newPontos = { ...data.pontos };
    const diaPonto = newPontos[pis]?.find(p => p.data === date);

    if (diaPonto) {
      const oldVal = diaPonto.batimentosAjustados[index] || '--:--';
      diaPonto.batimentosAjustados[index] = value;
      diaPonto.batimentosAjustados.sort();

      const log: LogAuditoriaPonto = {
        id: crypto.randomUUID(),
        timestamp: new Date().toISOString(),
        usuario: 'Administrador',
        pis,
        dataPonto: date,
        campo: `Batida ${index + 1}`,
        valorAntigo: oldVal,
        valorNovo: value,
        motivo: adjustmentReason
      };

      setData(prev => ({ ...prev, pontos: newPontos, logs: [log, ...prev.logs] }));
    }
    setEditingPoint(null);
    setAdjustmentReason('');
  };

  const handleToggleFalta = (pis: string, date: string) => {
    const newPontos = { ...data.pontos };
    if (!newPontos[pis]) newPontos[pis] = [];
    let diaPonto = newPontos[pis].find(p => p.data === date);
    if (!diaPonto) {
      diaPonto = { data: date, batimentosOriginais: [], batimentosAjustados: [], isFalta: false };
      newPontos[pis].push(diaPonto);
    }
    diaPonto.isFalta = !diaPonto.isFalta;
    if (diaPonto.isFalta) diaPonto.batimentosAjustados = [];
    setData(prev => ({ ...prev, pontos: newPontos }));
  };

  return (
    <div className="space-y-8 pb-12 animate-in fade-in duration-500">
      {/* Header Profissional */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <div className="flex items-center gap-3">
             <ShieldCheck className="w-8 h-8 text-[#E30613]" />
             <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Gestão de Horas</h2>
          </div>
          <p className="text-slate-400 font-bold uppercase text-[10px] tracking-[0.4em] ml-11 underline decoration-[#E30613] decoration-2">Auditoria de Ponto e CLT</p>
        </div>

        <div className="flex items-center gap-4">
          <div className="bg-[#0A1121] rounded-2xl p-4 text-white flex items-center gap-4 shadow-xl border border-slate-800">
            <Calendar className="w-5 h-5 text-[#E30613]" />
            <div className="flex flex-col">
               <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Referência</span>
               <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="bg-transparent text-sm font-black uppercase outline-none cursor-pointer" />
            </div>
          </div>
          <label className="flex items-center gap-4 px-8 py-4 bg-white border-2 border-slate-200 text-slate-900 rounded-2xl cursor-pointer hover:border-[#E30613] transition-all font-black text-xs uppercase tracking-widest shadow-sm">
            <FileUp className="w-5 h-5 text-[#E30613]" />
            IMPORTAR AFD
            <input type="file" className="hidden" accept=".txt" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-10">
        {/* Sidebar de Equipe */}
        <div className="lg:col-span-1 space-y-6">
           <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
              <div className="flex items-center justify-between mb-6">
                 <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Colaboradores</h3>
                 <div className="flex gap-1 bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setStatusFilter('ativos')} className={`p-1.5 rounded-md transition-all ${statusFilter === 'ativos' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`} title="Ativos"><UserCheck className="w-3.5 h-3.5" /></button>
                    <button onClick={() => setStatusFilter('inativos')} className={`p-1.5 rounded-md transition-all ${statusFilter === 'inativos' ? 'bg-white shadow-sm text-red-600' : 'text-slate-400'}`} title="Desligados"><UserMinus className="w-3.5 h-3.5" /></button>
                    <button onClick={() => setStatusFilter('todos')} className={`p-1.5 rounded-md transition-all ${statusFilter === 'todos' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400'}`} title="Todos"><Filter className="w-3.5 h-3.5" /></button>
                 </div>
              </div>

              <div className="space-y-3 max-h-[500px] overflow-y-auto pr-2 scrollbar-hide">
                 {filteredFuncionarios.length === 0 ? (
                   <p className="text-[10px] font-bold text-slate-300 italic text-center py-10">Nenhum registro encontrado</p>
                 ) : (
                   filteredFuncionarios.map(f => (
                     <div 
                        key={f.pis} 
                        className={`group relative flex items-center justify-between p-4 rounded-2xl transition-all border ${activePis === f.pis ? 'bg-red-50 border-red-100' : 'bg-slate-50 border-transparent hover:border-slate-200'}`}
                      >
                        <div className="flex-1 min-w-0 cursor-pointer" onClick={() => setActivePis(f.pis)}>
                           <p className={`text-xs font-black uppercase truncate whitespace-nowrap overflow-hidden pr-2 ${activePis === f.pis ? 'text-red-900' : 'text-slate-700'}`}>
                              {f.nome}
                           </p>
                           <p className="text-[9px] font-bold text-slate-400">PIS: {f.pis}</p>
                        </div>
                        <button 
                          onClick={(e) => { e.stopPropagation(); toggleFuncStatus(f.pis); }}
                          className={`p-2 rounded-xl transition-all ${f.ativo ? 'text-emerald-500 hover:bg-emerald-50' : 'text-red-400 hover:bg-red-50'}`}
                        >
                           {f.ativo ? <CheckCircle2 className="w-4 h-4" /> : <Trash2 className="w-4 h-4" />}
                        </button>
                     </div>
                   ))
                 )}
              </div>
           </div>
        </div>

        {/* Detalhes do Cartão */}
        <div className="lg:col-span-3">
           {activeEmployee ? (
             <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden animate-in fade-in duration-500">
                <div className="p-10 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
                   <div>
                      <div className="flex items-center gap-3">
                         <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter">{activeEmployee.nome}</h3>
                         {!activeEmployee.ativo && <span className="bg-red-100 text-red-600 text-[9px] font-black px-2 py-1 rounded uppercase">Desligado</span>}
                      </div>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Nº PIS: {activeEmployee.pis} | Jornada: 8h/dia</p>
                   </div>
                   <button className="flex items-center gap-3 px-6 py-3 bg-[#0A1121] text-white rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-black transition-all">
                     <FileText className="w-4 h-4 text-[#E30613]" /> EXPORTAR ESPELHO PDF
                   </button>
                </div>

                <div className="overflow-x-auto">
                   <table className="w-full text-left">
                      <thead>
                        <tr className="bg-slate-900 text-slate-500">
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest">Dia</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest">Batidas de Ponto</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-right">Trabalhadas</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-right">Extras</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-right">Saldo/Atr.</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-center">Status</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                         {currentMonthDays.map(day => {
                            const p = data.pontos[activePis!]?.find(x => x.data === day);
                            const calc = calculateDay(p?.batimentosAjustados || [], activeEmployee.jornadaDiariaMinutos);
                            const dayNum = day.split('-')[2];
                            const dateObj = new Date(day + 'T00:00:00');
                            const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;

                            return (
                               <tr key={day} className={`group hover:bg-slate-50 transition-all ${p?.isFalta ? 'bg-red-50/30' : isWeekend ? 'bg-slate-50/50' : ''}`}>
                                  <td className="px-8 py-5">
                                     <div className="flex flex-col">
                                        <span className="text-xl font-black text-slate-950 leading-none">{dayNum}</span>
                                        <span className="text-[9px] font-black text-slate-400 uppercase">{dateObj.toLocaleDateString('pt-BR', { weekday: 'short' })}</span>
                                     </div>
                                  </td>
                                  <td className="px-8 py-5">
                                     <div className="flex flex-wrap gap-2 items-center">
                                        {p?.batimentosAjustados?.map((time, idx) => (
                                          <button 
                                            key={idx}
                                            onClick={() => setEditingPoint({ pis: activePis!, date: day, index: idx, value: time })}
                                            className="px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-xs font-black text-slate-700 hover:border-[#E30613] transition-all flex items-center gap-2 group/btn shadow-sm"
                                          >
                                            {time} <Edit3 className="w-3 h-3 opacity-0 group-hover/btn:opacity-100 text-slate-400" />
                                          </button>
                                        ))}
                                        <button 
                                          onClick={() => setEditingPoint({ pis: activePis!, date: day, index: (p?.batimentosAjustados.length || 0), value: '08:00' })}
                                          className="p-1.5 rounded-lg border-2 border-dashed border-slate-200 text-slate-300 hover:text-[#E30613] hover:border-[#E30613] transition-all"
                                        >
                                          <Plus className="w-4 h-4" />
                                        </button>
                                     </div>
                                  </td>
                                  <td className="px-8 py-5 text-right font-black text-slate-900">{calc.trabalhadas > 0 ? minutesToTime(calc.trabalhadas) : '—'}</td>
                                  <td className="px-8 py-5 text-right font-black text-emerald-600">{calc.extras > 0 ? minutesToTime(calc.extras) : '—'}</td>
                                  <td className="px-8 py-5 text-right font-black text-[#E30613]">{calc.atraso > 0 && calc.atraso !== activeEmployee.jornadaDiariaMinutos ? minutesToTime(calc.atraso) : '—'}</td>
                                  <td className="px-8 py-5 text-center">
                                     <button 
                                       onClick={() => handleToggleFalta(activePis!, day)}
                                       className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${p?.isFalta ? 'bg-[#E30613] text-white' : 'bg-slate-100 text-slate-400 hover:bg-red-50 hover:text-[#E30613]'}`}
                                     >
                                       {p?.isFalta ? 'FALTA' : 'LANÇAR FALTA'}
                                     </button>
                                  </td>
                               </tr>
                            );
                         })}
                      </tbody>
                   </table>
                </div>
             </div>
           ) : (
             <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-[4rem] py-64 flex flex-col items-center justify-center text-slate-300">
               <Users className="w-20 h-20 mb-8 opacity-20" />
               <p className="text-2xl font-black text-slate-800 tracking-tight uppercase">Selecione um Colaborador na Lista</p>
               <p className="text-sm font-medium text-slate-400 mt-2 italic">Importe o arquivo AFD para carregar os dados</p>
             </div>
           )}
        </div>
      </div>

      {/* Modal de Edição */}
      {editingPoint && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-md">
           <div className="bg-white rounded-[3rem] shadow-2xl max-w-lg w-full p-12 space-y-8 animate-in zoom-in-95">
              <div className="flex items-center gap-4 border-b border-slate-100 pb-6">
                 <div className="p-4 bg-red-50 rounded-2xl"><Edit3 className="text-[#E30613]" /></div>
                 <div>
                    <h3 className="text-2xl font-black text-slate-900 tracking-tighter uppercase">Ajuste Manual</h3>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Auditoria Legal de Registro</p>
                 </div>
              </div>

              <div className="space-y-6">
                 <div className="flex justify-between items-end gap-6">
                    <div className="flex-1 space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Nova Hora</label>
                       <input 
                         type="time" 
                         value={editingPoint.value}
                         onChange={(e) => setEditingPoint({...editingPoint, value: e.target.value})}
                         className="w-full px-6 py-5 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-black text-2xl text-slate-900 outline-none focus:ring-4 focus:ring-red-500/10"
                       />
                    </div>
                    <div className="text-right pb-4">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Data</p>
                       <p className="font-black text-slate-900">{new Date(editingPoint.date + 'T00:00:00').toLocaleDateString()}</p>
                    </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Motivo do Ajuste</label>
                    <textarea 
                      placeholder="Descreva o motivo (ex: Esquecimento, Problema no relógio...)"
                      value={adjustmentReason}
                      onChange={(e) => setAdjustmentReason(e.target.value)}
                      className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-slate-600 min-h-[120px] outline-none focus:ring-4 focus:ring-red-500/10 text-sm"
                    />
                 </div>

                 <div className="flex flex-col gap-3">
                    <button 
                      onClick={handleSaveAdjustment}
                      disabled={!adjustmentReason}
                      className="w-full py-5 bg-[#E30613] text-white rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-2xl disabled:opacity-30 hover:bg-red-700 transition-all"
                    >
                      GRAVAR ALTERAÇÃO AUDITADA
                    </button>
                    <button 
                      onClick={() => { setEditingPoint(null); setAdjustmentReason(''); }}
                      className="w-full py-5 bg-slate-100 text-slate-400 rounded-[2rem] font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition-all"
                    >
                      CANCELAR
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

