import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, UserCheck, Calendar, FileText, Trash2, 
  CheckCircle2, AlertTriangle, Edit3, X, History, Users, 
  Search, LayoutDashboard, ShieldCheck, TrendingUp, AlertCircle, Save,
  Plus, UserMinus, Filter, Info
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, MarcacaoPonto, ControleHoras, LogAuditoriaPonto, RegistroBatida } from '../types';

type StatusFilter = 'ativos' | 'inativos' | 'todos';

export const HorasPage: React.FC = () => {
  const [data, setData] = useState<ControleHoras>(() => {
    const saved = localStorage.getItem('abc_ponto_v4');
    return saved ? JSON.parse(saved) : { funcionarios: [], pontos: {}, logs: [] };
  });

  const [statusFilter, setStatusFilter] = useState<StatusFilter>('ativos');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePis, setActivePis] = useState<string | null>(null);

  // Modal State
  const [modalAjuste, setModalAjuste] = useState<{pis: string, date: string, hora: string, index?: number} | null>(null);
  const [motivoAjuste, setMotivoAjuste] = useState('');

  useEffect(() => {
    localStorage.setItem('abc_ponto_v4', JSON.stringify(data));
  }, [data]);

  // --- UTILS ---
  const timeToMinutes = (time: string): number => {
    if (!time || !time.includes(':')) return 0;
    const [h, m] = time.split(':').map(Number);
    return (h * 60) + m;
  };

  const minutesToTime = (mins: number): string => {
    const h = Math.floor(Math.abs(mins) / 60);
    const m = Math.abs(mins) % 60;
    const sign = mins < 0 ? '-' : '';
    return `${sign}${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  // --- PARSER AFD ---
  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    // ISO-8859-1 para garantir nomes com acentos vindos do relógio de ponto
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split('\n');
      const newFuncs = [...data.funcionarios];
      const newPontos = { ...data.pontos };

      lines.forEach(line => {
        if (line.length < 10) return;
        const tipo = line.substring(9, 10);

        // Tipo 5: Cadastro de Funcionário
        if (tipo === '5') {
          const pis = line.substring(22, 34).trim();
          const nome = line.substring(34, 86).trim();
          if (pis && !newFuncs.find(f => f.pis === pis)) {
            newFuncs.push({ pis, nome, ativo: true, jornadaDiariaMinutos: 480 });
          }
        } 
        // Tipo 3: Marcação de Ponto
        else if (tipo === '3') {
          const dia = line.substring(10, 12), mes = line.substring(12, 14), ano = line.substring(14, 18);
          const hora = line.substring(18, 20), min = line.substring(20, 22), pis = line.substring(22, 34).trim();
          const dateKey = `${ano}-${mes}-${dia}`;
          const time = `${hora}:${min}`;

          if (pis) {
            if (!newPontos[pis]) newPontos[pis] = [];
            let diaPonto = newPontos[pis].find(p => p.data === dateKey);
            if (!diaPonto) {
              diaPonto = { data: dateKey, batidas: [], isFalta: false };
              newPontos[pis].push(diaPonto);
            }
            if (!diaPonto.batidas.find(b => b.hora === time)) {
              diaPonto.batidas.push({ hora: time, origem: 'AFD' });
              diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
            }
          }
        }
      });

      setData(prev => ({ ...prev, funcionarios: newFuncs, pontos: newPontos }));
    };
    event.target.value = '';
  };

  // --- CALCULOS ---
  const calculateDay = (batidas: RegistroBatida[], jornadaNominal: number = 480) => {
    if (!batidas || batidas.length < 2) return { trabalhadas: 0, extras: 0, atraso: jornadaNominal, incompleto: batidas.length % 2 !== 0 };

    let totalMinutes = 0;
    const sorted = [...batidas].sort((a, b) => a.hora.localeCompare(b.hora));

    for (let i = 0; i < sorted.length - 1; i += 2) {
      const inMin = timeToMinutes(sorted[i].hora);
      const outMin = timeToMinutes(sorted[i+1].hora);
      if (outMin > inMin) totalMinutes += (outMin - inMin);
    }

    const diff = totalMinutes - jornadaNominal;
    return {
      trabalhadas: totalMinutes,
      extras: diff > 0 ? diff : 0,
      atraso: diff < 0 ? Math.abs(diff) : 0,
      incompleto: batidas.length % 2 !== 0
    };
  };

  // --- FILTROS ---
  const filteredFuncs = useMemo(() => {
    return data.funcionarios.filter(f => {
      const matchesStatus = statusFilter === 'todos' ? true : (statusFilter === 'ativos' ? f.ativo : !f.ativo);
      const matchesSearch = f.nome.toLowerCase().includes(searchTerm.toLowerCase()) || f.pis.includes(searchTerm);
      return matchesStatus && matchesSearch;
    }).sort((a, b) => a.nome.localeCompare(b.nome));
  }, [data.funcionarios, statusFilter, searchTerm]);

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: lastDay }, (_, i) => `${year}-${month}-${(i + 1).toString().padStart(2, '0')}`);
  }, [selectedMonth]);

  const activeEmployee = useMemo(() => data.funcionarios.find(f => f.pis === activePis), [data.funcionarios, activePis]);

  const handleSaveAjuste = () => {
    if (!modalAjuste || !motivoAjuste) return;
    const { pis, date, hora } = modalAjuste;

    const newPontos = { ...data.pontos };
    if (!newPontos[pis]) newPontos[pis] = [];
    let diaPonto = newPontos[pis].find(p => p.data === date);

    if (!diaPonto) {
      diaPonto = { data: date, batidas: [], isFalta: false };
      newPontos[pis].push(diaPonto);
    }

    // Adiciona a batida
    diaPonto.batidas.push({ hora, origem: 'AJUSTE', obs: motivoAjuste });
    diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
    diaPonto.isFalta = false;

    // Log de Auditoria
    const log: LogAuditoriaPonto = {
      id: crypto.randomUUID(),
      timestamp: new Date().toISOString(),
      usuario: 'Administrador',
      pis,
      dataPonto: date,
      tipo: 'inclusao',
      valorNovo: hora,
      motivo: motivoAjuste
    };

    setData(prev => ({ ...prev, pontos: newPontos, logs: [log, ...prev.logs] }));
    setModalAjuste(null);
    setMotivoAjuste('');
  };

  const dashboardStats = useMemo(() => {
    let extras = 0, atrasos = 0, faltas = 0;
    const active = data.funcionarios.filter(f => f.ativo);

    active.forEach(f => {
      const pontos = data.pontos[f.pis] || [];
      pontos.filter(p => p.data.startsWith(selectedMonth)).forEach(p => {
        if (p.isFalta) faltas++;
        else {
          const c = calculateDay(p.batidas, f.jornadaDiariaMinutos);
          extras += c.extras;
          atrasos += c.atraso;
        }
      });
    });

    return { extras, atrasos, faltas, count: active.length };
  }, [data, selectedMonth]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* HEADER INTEGRADO */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 pb-8 border-b border-slate-100">
        <div className="space-y-2">
          <div className="flex items-center gap-3">
             <ShieldCheck className="w-10 h-10 text-[#E30613]" />
             <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Auditoria de Ponto</h2>
          </div>
          <p className="text-slate-400 font-bold uppercase text-[10px] tracking-[0.4em] ml-14 underline decoration-[#E30613] decoration-2 underline-offset-4">Compliance e Gestão de Frequência</p>
        </div>

        <div className="flex flex-wrap items-center gap-4">
          <div className="bg-[#0A1121] rounded-2xl p-4 text-white flex items-center gap-4 shadow-xl border border-slate-800">
            <Calendar className="w-5 h-5 text-[#E30613]" />
            <div className="flex flex-col">
               <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Referência</span>
               <input 
                 type="month" 
                 value={selectedMonth} 
                 onChange={(e) => setSelectedMonth(e.target.value)} 
                 className="bg-transparent text-sm font-black uppercase outline-none cursor-pointer" 
               />
            </div>
          </div>
          <label className="flex items-center gap-4 px-8 py-4 bg-white border-2 border-slate-200 text-slate-900 rounded-2xl cursor-pointer hover:border-[#E30613] transition-all font-black text-xs uppercase tracking-widest shadow-sm">
            <FileUp className="w-5 h-5 text-[#E30613]" />
            IMPORTAR AFD (.TXT)
            <input type="file" className="hidden" accept=".txt" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      {/* STATS RÁPIDOS */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
         <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Horas Extras</p>
            <p className="text-3xl font-black text-emerald-600 tracking-tighter">{minutesToTime(dashboardStats.extras)}</p>
         </div>
         <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Atrasos Totais</p>
            <p className="text-3xl font-black text-[#E30613] tracking-tighter">{minutesToTime(dashboardStats.atrasos)}</p>
         </div>
         <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Faltas Brutas</p>
            <p className="text-3xl font-black text-slate-900 tracking-tighter">{dashboardStats.faltas} dias</p>
         </div>
         <div className="bg-slate-950 rounded-[2.5rem] p-8 text-white shadow-xl">
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Equipe Ativa</p>
            <p className="text-3xl font-black tracking-tighter">{dashboardStats.count} Colab.</p>
         </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-10 items-start">
        {/* SIDEBAR COLABORADORES */}
        <div className="lg:col-span-1 space-y-6">
           <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-2xl">
              <div className="flex items-center justify-between mb-6">
                 <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">Colaboradores</h3>
                 <div className="flex gap-1 bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setStatusFilter('ativos')} className={`p-1.5 rounded-md transition-all ${statusFilter === 'ativos' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`} title="Ativos"><UserCheck className="w-4 h-4" /></button>
                    <button onClick={() => setStatusFilter('inativos')} className={`p-1.5 rounded-md transition-all ${statusFilter === 'inativos' ? 'bg-white shadow-sm text-red-600' : 'text-slate-400'}`} title="Desligados"><UserMinus className="w-4 h-4" /></button>
                    <button onClick={() => setStatusFilter('todos')} className={`p-1.5 rounded-md transition-all ${statusFilter === 'todos' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400'}`} title="Todos"><Filter className="w-4 h-4" /></button>
                 </div>
              </div>

              <div className="relative mb-4">
                 <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                 <input 
                   type="text" 
                   placeholder="Buscar..." 
                   value={searchTerm}
                   onChange={(e) => setSearchTerm(e.target.value)}
                   className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-xl text-xs font-bold outline-none focus:ring-2 focus:ring-red-500/10"
                 />
              </div>

              <div className="space-y-2 max-h-[60vh] overflow-y-auto pr-2 scrollbar-hide">
                 {filteredFuncs.map(f => (
                   <button 
                     key={f.pis} 
                     onClick={() => setActivePis(f.pis)}
                     className={`w-full text-left p-4 rounded-2xl transition-all border flex flex-col gap-0.5 min-w-0 ${activePis === f.pis ? 'bg-[#E30613] text-white border-[#E30613] shadow-lg' : 'bg-slate-50 border-transparent text-slate-600 hover:bg-slate-100'}`}
                   >
                      <p className="text-xs font-black uppercase whitespace-nowrap overflow-hidden text-ellipsis w-full leading-tight">
                        {f.nome}
                      </p>
                      <p className={`text-[9px] font-bold ${activePis === f.pis ? 'text-white/60' : 'text-slate-400'}`}>PIS: {f.pis}</p>
                   </button>
                 ))}
              </div>
           </div>
        </div>

        {/* ÁREA DE AUDITORIA */}
        <div className="lg:col-span-3">
           {activeEmployee ? (
             <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden animate-in fade-in slide-in-from-right-4 duration-500">
                <div className="p-10 border-b border-slate-100 bg-slate-50/50 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                   <div>
                      <h3 className="text-3xl font-black text-slate-950 uppercase tracking-tighter">{activeEmployee.nome}</h3>
                      <div className="flex items-center gap-4 mt-2">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Jornada: 8h/dia</span>
                        <div className="flex items-center gap-1.5 px-3 py-1 bg-emerald-50 rounded-full border border-emerald-100">
                           <TrendingUp className="w-3 h-3 text-emerald-600" />
                           <span className="text-[9px] font-black text-emerald-600 uppercase">Score: 98%</span>
                        </div>
                      </div>
                   </div>
                   <div className="flex gap-3">
                      <button className="flex items-center gap-3 px-6 py-3 bg-[#0A1121] text-white rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-black transition-all">
                        <FileText className="w-4 h-4 text-[#E30613]" /> ESPELHO PDF
                      </button>
                   </div>
                </div>

                <div className="overflow-x-auto">
                   <table className="w-full text-left">
                      <thead>
                        <tr className="bg-slate-950 text-slate-500">
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest">Dia</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest">Batidas de Ponto</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-right">Horas</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-right">Extra/Saldo</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-center">Auditoria</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                         {currentMonthDays.map(day => {
                            const diaPonto = data.pontos[activePis!]?.find(x => x.data === day);
                            const calc = calculateDay(diaPonto?.batidas || [], activeEmployee.jornadaDiariaMinutos);
                            const dt = new Date(day + 'T00:00:00');
                            const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                            return (
                               <tr key={day} className={`group hover:bg-slate-50 transition-all ${isWeekend ? 'bg-slate-50/50' : ''} ${diaPonto?.isFalta ? 'bg-red-50/30' : ''}`}>
                                  <td className="px-8 py-5">
                                     <div className="flex flex-col">
                                        <span className="text-xl font-black text-slate-900 leading-none">{day.split('-')[2]}</span>
                                        <span className="text-[9px] font-black text-slate-400 uppercase">{dt.toLocaleDateString('pt-BR', { weekday: 'short' })}</span>
                                     </div>
                                  </td>
                                  <td className="px-8 py-5">
                                     <div className="flex flex-wrap gap-2 items-center">
                                        {diaPonto?.batidas.map((b, i) => (
                                          <div key={i} className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border text-xs font-black shadow-sm ${b.origem === 'AJUSTE' ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-white border-slate-200 text-slate-700'}`}>
                                            {b.hora}
                                            {b.origem === 'AJUSTE' && <Info className="w-3 h-3 cursor-help" title={b.obs} />}
                                          </div>
                                        ))}
                                        <button 
                                          onClick={() => setModalAjuste({ pis: activePis!, date: day, hora: '08:00' })}
                                          className="p-1.5 rounded-lg border-2 border-dashed border-slate-200 text-slate-300 hover:text-[#E30613] hover:border-[#E30613] transition-all"
                                        >
                                          <Plus className="w-4 h-4" />
                                        </button>
                                     </div>
                                  </td>
                                  <td className="px-8 py-5 text-right font-black text-slate-900">
                                    {calc.trabalhadas > 0 ? minutesToTime(calc.trabalhadas) : '—'}
                                  </td>
                                  <td className={`px-8 py-5 text-right font-black ${calc.extras > 0 ? 'text-emerald-600' : 'text-[#E30613]'}`}>
                                    {calc.extras > 0 ? `+${minutesToTime(calc.extras)}` : (calc.atraso > 0 && calc.atraso !== 480 ? `-${minutesToTime(calc.atraso)}` : '—')}
                                  </td>
                                  <td className="px-8 py-5 text-center">
                                     <button 
                                       onClick={() => {
                                         const newPts = {...data.pontos};
                                         if (!newPts[activePis!]) newPts[activePis!] = [];
                                         let dp = newPts[activePis!].find(x => x.data === day);
                                         if (!dp) {
                                           dp = { data: day, batidas: [], isFalta: false };
                                           newPts[activePis!].push(dp);
                                         }
                                         dp.isFalta = !dp.isFalta;
                                         if (dp.isFalta) dp.batidas = [];
                                         setData(prev => ({ ...prev, pontos: newPts }));
                                       }}
                                       className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${diaPonto?.isFalta ? 'bg-[#E30613] text-white shadow-lg' : 'bg-slate-100 text-slate-400 hover:bg-red-50 hover:text-[#E30613]'}`}
                                     >
                                       {diaPonto?.isFalta ? 'FALTA' : 'LANÇAR FALTA'}
                                     </button>
                                  </td>
                               </tr>
                            );
                         })}
                      </tbody>
                   </table>
                </div>
             </div>
           ) : (
             <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-[4rem] py-64 flex flex-col items-center justify-center text-slate-300">
               <Users className="w-20 h-20 mb-8 opacity-20" />
               <p className="text-2xl font-black text-slate-800 tracking-tight uppercase">Selecione um Colaborador</p>
               <p className="text-sm font-medium text-slate-400 mt-2 italic">Importe o arquivo AFD para carregar registros originais</p>
             </div>
           )}
        </div>
      </div>

      {/* MODAL DE AJUSTE */}
      {modalAjuste && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-md">
           <div className="bg-white rounded-[3rem] shadow-2xl max-w-lg w-full p-12 space-y-8 animate-in zoom-in-95">
              <div className="flex items-center gap-4 border-b border-slate-100 pb-6">
                 <div className="p-4 bg-red-50 rounded-2xl"><Edit3 className="text-[#E30613]" /></div>
                 <div>
                    <h3 className="text-2xl font-black text-slate-900 tracking-tighter uppercase">Ajuste de Ponto</h3>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Registro Administrativo Auditado</p>
                 </div>
              </div>

              <div className="space-y-6">
                 <div className="flex justify-between items-end gap-6">
                    <div className="flex-1 space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Nova Hora</label>
                       <input 
                         type="time" 
                         value={modalAjuste.hora}
                         onChange={(e) => setModalAjuste({...modalAjuste, hora: e.target.value})}
                         className="w-full px-6 py-5 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-black text-3xl text-slate-900 outline-none focus:ring-4 focus:ring-red-500/10"
                       />
                    </div>
                    <div className="text-right pb-4">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Data</p>
                       <p className="font-black text-slate-900">{modalAjuste.date.split('-').reverse().join('/')}</p>
                    </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Motivo da Alteração</label>
                    <textarea 
                      placeholder="Ex: Esquecimento do funcionário, Visita externa, Problema técnico no relógio..."
                      value={motivoAjuste}
                      onChange={(e) => setMotivoAjuste(e.target.value)}
                      className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-slate-700 min-h-[120px] outline-none focus:ring-4 focus:ring-red-500/10"
                    />
                 </div>

                 <div className="flex flex-col gap-3">
                    <button 
                      onClick={handleSaveAjuste}
                      disabled={!motivoAjuste}
                      className="w-full py-5 bg-[#E30613] text-white rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-2xl disabled:opacity-30 hover:bg-red-700 transition-all flex items-center justify-center gap-3"
                    >
                      <Save className="w-4 h-4" /> GRAVAR REGISTRO
                    </button>
                    <button 
                      onClick={() => { setModalAjuste(null); setMotivoAjuste(''); }}
                      className="w-full py-5 bg-slate-100 text-slate-400 rounded-[2rem] font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition-all"
                    >
                      CANCELAR
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, UserCheck, Calendar, FileText, Trash2, 
  CheckCircle2, AlertTriangle, Edit3, X, History, Users, 
  Search, LayoutDashboard, ShieldCheck, TrendingUp, AlertCircle, Save,
  Plus, UserMinus, Filter, Info
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, MarcacaoPonto, ControleHoras, LogAuditoriaPonto, RegistroBatida } from '../types';

type StatusFilter = 'ativos' | 'inativos' | 'todos';

export const HorasPage: React.FC = () => {
  const [data, setData] = useState<ControleHoras>(() => {
    const saved = localStorage.getItem('abc_ponto_v4');
    return saved ? JSON.parse(saved) : { funcionarios: [], pontos: {}, logs: [] };
  });

  const [statusFilter, setStatusFilter] = useState<StatusFilter>('ativos');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePis, setActivePis] = useState<string | null>(null);

  // Modal State
  const [modalAjuste, setModalAjuste] = useState<{pis: string, date: string, hora: string, index?: number} | null>(null);
  const [motivoAjuste, setMotivoAjuste] = useState('');

  useEffect(() => {
    localStorage.setItem('abc_ponto_v4', JSON.stringify(data));
  }, [data]);

  // --- UTILS ---
  const timeToMinutes = (time: string): number => {
    if (!time || !time.includes(':')) return 0;
    const [h, m] = time.split(':').map(Number);
    return (h * 60) + m;
  };

  const minutesToTime = (mins: number): string => {
    const h = Math.floor(Math.abs(mins) / 60);
    const m = Math.abs(mins) % 60;
    const sign = mins < 0 ? '-' : '';
    return `${sign}${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  // --- PARSER AFD ---
  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    // ISO-8859-1 para garantir nomes com acentos vindos do relógio de ponto
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split('\n');
      const newFuncs = [...data.funcionarios];
      const newPontos = { ...data.pontos };

      lines.forEach(line => {
        if (line.length < 10) return;
        const tipo = line.substring(9, 10);

        // Tipo 5: Cadastro de Funcionário
        if (tipo === '5') {
          const pis = line.substring(22, 34).trim();
          const nome = line.substring(34, 86).trim();
          if (pis && !newFuncs.find(f => f.pis === pis)) {
            newFuncs.push({ pis, nome, ativo: true, jornadaDiariaMinutos: 480 });
          }
        } 
        // Tipo 3: Marcação de Ponto
        else if (tipo === '3') {
          const dia = line.substring(10, 12), mes = line.substring(12, 14), ano = line.substring(14, 18);
          const hora = line.substring(18, 20), min = line.substring(20, 22), pis = line.substring(22, 34).trim();
          const dateKey = `${ano}-${mes}-${dia}`;
          const time = `${hora}:${min}`;

          if (pis) {
            if (!newPontos[pis]) newPontos[pis] = [];
            let diaPonto = newPontos[pis].find(p => p.data === dateKey);
            if (!diaPonto) {
              diaPonto = { data: dateKey, batidas: [], isFalta: false };
              newPontos[pis].push(diaPonto);
            }
            if (!diaPonto.batidas.find(b => b.hora === time)) {
              diaPonto.batidas.push({ hora: time, origem: 'AFD' });
              diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
            }
          }
        }
      });

      setData(prev => ({ ...prev, funcionarios: newFuncs, pontos: newPontos }));
    };
    event.target.value = '';
  };

  // --- CALCULOS ---
  const calculateDay = (batidas: RegistroBatida[], jornadaNominal: number = 480) => {
    if (!batidas || batidas.length < 2) return { trabalhadas: 0, extras: 0, atraso: jornadaNominal, incompleto: batidas.length % 2 !== 0 };

    let totalMinutes = 0;
    const sorted = [...batidas].sort((a, b) => a.hora.localeCompare(b.hora));

    for (let i = 0; i < sorted.length - 1; i += 2) {
      const inMin = timeToMinutes(sorted[i].hora);
      const outMin = timeToMinutes(sorted[i+1].hora);
      if (outMin > inMin) totalMinutes += (outMin - inMin);
    }

    const diff = totalMinutes - jornadaNominal;
    return {
      trabalhadas: totalMinutes,
      extras: diff > 0 ? diff : 0,
      atraso: diff < 0 ? Math.abs(diff) : 0,
      incompleto: batidas.length % 2 !== 0
    };
  };

  // --- FILTROS ---
  const filteredFuncs = useMemo(() => {
    return data.funcionarios.filter(f => {
      const matchesStatus = statusFilter === 'todos' ? true : (statusFilter === 'ativos' ? f.ativo : !f.ativo);
      const matchesSearch = f.nome.toLowerCase().includes(searchTerm.toLowerCase()) || f.pis.includes(searchTerm);
      return matchesStatus && matchesSearch;
    }).sort((a, b) => a.nome.localeCompare(b.nome));
  }, [data.funcionarios, statusFilter, searchTerm]);

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: lastDay }, (_, i) => `${year}-${month}-${(i + 1).toString().padStart(2, '0')}`);
  }, [selectedMonth]);

  const activeEmployee = useMemo(() => data.funcionarios.find(f => f.pis === activePis), [data.funcionarios, activePis]);

  const handleSaveAjuste = () => {
    if (!modalAjuste || !motivoAjuste) return;
    const { pis, date, hora } = modalAjuste;

    const newPontos = { ...data.pontos };
    if (!newPontos[pis]) newPontos[pis] = [];
    let diaPonto = newPontos[pis].find(p => p.data === date);

    if (!diaPonto) {
      diaPonto = { data: date, batidas: [], isFalta: false };
      newPontos[pis].push(diaPonto);
    }

    // Adiciona a batida
    diaPonto.batidas.push({ hora, origem: 'AJUSTE', obs: motivoAjuste });
    diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
    diaPonto.isFalta = false;

    // Log de Auditoria
    const log: LogAuditoriaPonto = {
      id: crypto.randomUUID(),
      timestamp: new Date().toISOString(),
      usuario: 'Administrador',
      pis,
      dataPonto: date,
      tipo: 'inclusao',
      valorNovo: hora,
      motivo: motivoAjuste
    };

    setData(prev => ({ ...prev, pontos: newPontos, logs: [log, ...prev.logs] }));
    setModalAjuste(null);
    setMotivoAjuste('');
  };

  const dashboardStats = useMemo(() => {
    let extras = 0, atrasos = 0, faltas = 0;
    const active = data.funcionarios.filter(f => f.ativo);

    active.forEach(f => {
      const pontos = data.pontos[f.pis] || [];
      pontos.filter(p => p.data.startsWith(selectedMonth)).forEach(p => {
        if (p.isFalta) faltas++;
        else {
          const c = calculateDay(p.batidas, f.jornadaDiariaMinutos);
          extras += c.extras;
          atrasos += c.atraso;
        }
      });
    });

    return { extras, atrasos, faltas, count: active.length };
  }, [data, selectedMonth]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* HEADER INTEGRADO */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 pb-8 border-b border-slate-100">
        <div className="space-y-2">
          <div className="flex items-center gap-3">
             <ShieldCheck className="w-10 h-10 text-[#E30613]" />
             <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Auditoria de Ponto</h2>
          </div>
          <p className="text-slate-400 font-bold uppercase text-[10px] tracking-[0.4em] ml-14 underline decoration-[#E30613] decoration-2 underline-offset-4">Compliance e Gestão de Frequência</p>
        </div>

        <div className="flex flex-wrap items-center gap-4">
          <div className="bg-[#0A1121] rounded-2xl p-4 text-white flex items-center gap-4 shadow-xl border border-slate-800">
            <Calendar className="w-5 h-5 text-[#E30613]" />
            <div className="flex flex-col">
               <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Referência</span>
               <input 
                 type="month" 
                 value={selectedMonth} 
                 onChange={(e) => setSelectedMonth(e.target.value)} 
                 className="bg-transparent text-sm font-black uppercase outline-none cursor-pointer" 
               />
            </div>
          </div>
          <label className="flex items-center gap-4 px-8 py-4 bg-white border-2 border-slate-200 text-slate-900 rounded-2xl cursor-pointer hover:border-[#E30613] transition-all font-black text-xs uppercase tracking-widest shadow-sm">
            <FileUp className="w-5 h-5 text-[#E30613]" />
            IMPORTAR AFD (.TXT)
            <input type="file" className="hidden" accept=".txt" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      {/* STATS RÁPIDOS */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
         <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Horas Extras</p>
            <p className="text-3xl font-black text-emerald-600 tracking-tighter">{minutesToTime(dashboardStats.extras)}</p>
         </div>
         <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Atrasos Totais</p>
            <p className="text-3xl font-black text-[#E30613] tracking-tighter">{minutesToTime(dashboardStats.atrasos)}</p>
         </div>
         <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Faltas Brutas</p>
            <p className="text-3xl font-black text-slate-900 tracking-tighter">{dashboardStats.faltas} dias</p>
         </div>
         <div className="bg-slate-950 rounded-[2.5rem] p-8 text-white shadow-xl">
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Equipe Ativa</p>
            <p className="text-3xl font-black tracking-tighter">{dashboardStats.count} Colab.</p>
         </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-10 items-start">
        {/* SIDEBAR COLABORADORES */}
        <div className="lg:col-span-1 space-y-6">
           <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-2xl">
              <div className="flex items-center justify-between mb-6">
                 <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">Colaboradores</h3>
                 <div className="flex gap-1 bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setStatusFilter('ativos')} className={`p-1.5 rounded-md transition-all ${statusFilter === 'ativos' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`} title="Ativos"><UserCheck className="w-4 h-4" /></button>
                    <button onClick={() => setStatusFilter('inativos')} className={`p-1.5 rounded-md transition-all ${statusFilter === 'inativos' ? 'bg-white shadow-sm text-red-600' : 'text-slate-400'}`} title="Desligados"><UserMinus className="w-4 h-4" /></button>
                    <button onClick={() => setStatusFilter('todos')} className={`p-1.5 rounded-md transition-all ${statusFilter === 'todos' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400'}`} title="Todos"><Filter className="w-4 h-4" /></button>
                 </div>
              </div>

              <div className="relative mb-4">
                 <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                 <input 
                   type="text" 
                   placeholder="Buscar..." 
                   value={searchTerm}
                   onChange={(e) => setSearchTerm(e.target.value)}
                   className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-xl text-xs font-bold outline-none focus:ring-2 focus:ring-red-500/10"
                 />
              </div>

              <div className="space-y-2 max-h-[60vh] overflow-y-auto pr-2 scrollbar-hide">
                 {filteredFuncs.map(f => (
                   <button 
                     key={f.pis} 
                     onClick={() => setActivePis(f.pis)}
                     className={`w-full text-left p-4 rounded-2xl transition-all border flex flex-col gap-0.5 min-w-0 ${activePis === f.pis ? 'bg-[#E30613] text-white border-[#E30613] shadow-lg' : 'bg-slate-50 border-transparent text-slate-600 hover:bg-slate-100'}`}
                   >
                      <p className="text-xs font-black uppercase whitespace-nowrap overflow-hidden text-ellipsis w-full leading-tight">
                        {f.nome}
                      </p>
                      <p className={`text-[9px] font-bold ${activePis === f.pis ? 'text-white/60' : 'text-slate-400'}`}>PIS: {f.pis}</p>
                   </button>
                 ))}
              </div>
           </div>
        </div>

        {/* ÁREA DE AUDITORIA */}
        <div className="lg:col-span-3">
           {activeEmployee ? (
             <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden animate-in fade-in slide-in-from-right-4 duration-500">
                <div className="p-10 border-b border-slate-100 bg-slate-50/50 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                   <div>
                      <h3 className="text-3xl font-black text-slate-950 uppercase tracking-tighter">{activeEmployee.nome}</h3>
                      <div className="flex items-center gap-4 mt-2">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Jornada: 8h/dia</span>
                        <div className="flex items-center gap-1.5 px-3 py-1 bg-emerald-50 rounded-full border border-emerald-100">
                           <TrendingUp className="w-3 h-3 text-emerald-600" />
                           <span className="text-[9px] font-black text-emerald-600 uppercase">Score: 98%</span>
                        </div>
                      </div>
                   </div>
                   <div className="flex gap-3">
                      <button className="flex items-center gap-3 px-6 py-3 bg-[#0A1121] text-white rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-black transition-all">
                        <FileText className="w-4 h-4 text-[#E30613]" /> ESPELHO PDF
                      </button>
                   </div>
                </div>

                <div className="overflow-x-auto">
                   <table className="w-full text-left">
                      <thead>
                        <tr className="bg-slate-950 text-slate-500">
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest">Dia</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest">Batidas de Ponto</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-right">Horas</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-right">Extra/Saldo</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-center">Auditoria</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                         {currentMonthDays.map(day => {
                            const diaPonto = data.pontos[activePis!]?.find(x => x.data === day);
                            const calc = calculateDay(diaPonto?.batidas || [], activeEmployee.jornadaDiariaMinutos);
                            const dt = new Date(day + 'T00:00:00');
                            const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                            return (
                               <tr key={day} className={`group hover:bg-slate-50 transition-all ${isWeekend ? 'bg-slate-50/50' : ''} ${diaPonto?.isFalta ? 'bg-red-50/30' : ''}`}>
                                  <td className="px-8 py-5">
                                     <div className="flex flex-col">
                                        <span className="text-xl font-black text-slate-900 leading-none">{day.split('-')[2]}</span>
                                        <span className="text-[9px] font-black text-slate-400 uppercase">{dt.toLocaleDateString('pt-BR', { weekday: 'short' })}</span>
                                     </div>
                                  </td>
                                  <td className="px-8 py-5">
                                     <div className="flex flex-wrap gap-2 items-center">
                                        {diaPonto?.batidas.map((b, i) => (
                                          <div key={i} className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border text-xs font-black shadow-sm ${b.origem === 'AJUSTE' ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-white border-slate-200 text-slate-700'}`}>
                                            {b.hora}
                                            {/* Fix: Wrapped Lucide icon in a span to provide a title tooltip as Lucide icons don't support the title prop directly. */}
                                            {b.origem === 'AJUSTE' && <span title={b.obs} className="cursor-help flex items-center"><Info className="w-3 h-3" /></span>}
                                          </div>
                                        ))}
                                        <button 
                                          onClick={() => setModalAjuste({ pis: activePis!, date: day, hora: '08:00' })}
                                          className="p-1.5 rounded-lg border-2 border-dashed border-slate-200 text-slate-300 hover:text-[#E30613] hover:border-[#E30613] transition-all"
                                        >
                                          <Plus className="w-4 h-4" />
                                        </button>
                                     </div>
                                  </td>
                                  <td className="px-8 py-5 text-right font-black text-slate-900">
                                    {calc.trabalhadas > 0 ? minutesToTime(calc.trabalhadas) : '—'}
                                  </td>
                                  <td className={`px-8 py-5 text-right font-black ${calc.extras > 0 ? 'text-emerald-600' : 'text-[#E30613]'}`}>
                                    {calc.extras > 0 ? `+${minutesToTime(calc.extras)}` : (calc.atraso > 0 && calc.atraso !== 480 ? `-${minutesToTime(calc.atraso)}` : '—')}
                                  </td>
                                  <td className="px-8 py-5 text-center">
                                     <button 
                                       onClick={() => {
                                         const newPts = {...data.pontos};
                                         if (!newPts[activePis!]) newPts[activePis!] = [];
                                         let dp = newPts[activePis!].find(x => x.data === day);
                                         if (!dp) {
                                           dp = { data: day, batidas: [], isFalta: false };
                                           newPts[activePis!].push(dp);
                                         }
                                         dp.isFalta = !dp.isFalta;
                                         if (dp.isFalta) dp.batidas = [];
                                         setData(prev => ({ ...prev, pontos: newPts }));
                                       }}
                                       className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${diaPonto?.isFalta ? 'bg-[#E30613] text-white shadow-lg' : 'bg-slate-100 text-slate-400 hover:bg-red-50 hover:text-[#E30613]'}`}
                                     >
                                       {diaPonto?.isFalta ? 'FALTA' : 'LANÇAR FALTA'}
                                     </button>
                                  </td>
                               </tr>
                            );
                         })}
                      </tbody>
                   </table>
                </div>
             </div>
           ) : (
             <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-[4rem] py-64 flex flex-col items-center justify-center text-slate-300">
               <Users className="w-20 h-20 mb-8 opacity-20" />
               <p className="text-2xl font-black text-slate-800 tracking-tight uppercase">Selecione um Colaborador</p>
               <p className="text-sm font-medium text-slate-400 mt-2 italic">Importe o arquivo AFD para carregar registros originais</p>
             </div>
           )}
        </div>
      </div>

      {/* MODAL DE AJUSTE */}
      {modalAjuste && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-md">
           <div className="bg-white rounded-[3rem] shadow-2xl max-w-lg w-full p-12 space-y-8 animate-in zoom-in-95">
              <div className="flex items-center gap-4 border-b border-slate-100 pb-6">
                 <div className="p-4 bg-red-50 rounded-2xl"><Edit3 className="text-[#E30613]" /></div>
                 <div>
                    <h3 className="text-2xl font-black text-slate-900 tracking-tighter uppercase">Ajuste de Ponto</h3>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Registro Administrativo Auditado</p>
                 </div>
              </div>

              <div className="space-y-6">
                 <div className="flex justify-between items-end gap-6">
                    <div className="flex-1 space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Nova Hora</label>
                       <input 
                         type="time" 
                         value={modalAjuste.hora}
                         onChange={(e) => setModalAjuste({...modalAjuste, hora: e.target.value})}
                         className="w-full px-6 py-5 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-black text-3xl text-slate-900 outline-none focus:ring-4 focus:ring-red-500/10"
                       />
                    </div>
                    <div className="text-right pb-4">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Data</p>
                       <p className="font-black text-slate-900">{modalAjuste.date.split('-').reverse().join('/')}</p>
                    </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Motivo da Alteração</label>
                    <textarea 
                      placeholder="Ex: Esquecimento do funcionário, Visita externa, Problema técnico no relógio..."
                      value={motivoAjuste}
                      onChange={(e) => setMotivoAjuste(e.target.value)}
                      className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-slate-700 min-h-[120px] outline-none focus:ring-4 focus:ring-red-500/10"
                    />
                 </div>

                 <div className="flex flex-col gap-3">
                    <button 
                      onClick={handleSaveAjuste}
                      disabled={!motivoAjuste}
                      className="w-full py-5 bg-[#E30613] text-white rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-2xl disabled:opacity-30 hover:bg-red-700 transition-all flex items-center justify-center gap-3"
                    >
                      <Save className="w-4 h-4" /> GRAVAR REGISTRO
                    </button>
                    <button 
                      onClick={() => { setModalAjuste(null); setMotivoAjuste(''); }}
                      className="w-full py-5 bg-slate-100 text-slate-400 rounded-[2rem] font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition-all"
                    >
                      CANCELAR
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, UserCheck, Calendar, FileText, Trash2, 
  CheckCircle2, AlertTriangle, Edit3, X, History, Users, 
  Search, LayoutDashboard, ShieldCheck, TrendingUp, AlertCircle, Save,
  Plus, UserMinus, Filter, Info, Eye, EyeOff
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, MarcacaoPonto, ControleHoras, LogAuditoriaPonto, RegistroBatida } from '../types';

type StatusFilter = 'ativos' | 'inativos' | 'todos';

export const HorasPage: React.FC = () => {
  // Carregar dados salvos ou iniciar vazio
  const [data, setData] = useState<ControleHoras>(() => {
    const saved = localStorage.getItem('abc_ponto_v5_final');
    return saved ? JSON.parse(saved) : { funcionarios: [], pontos: {}, logs: [] };
  });

  const [statusFilter, setStatusFilter] = useState<StatusFilter>('ativos');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePis, setActivePis] = useState<string | null>(null);

  // Modal de Ajuste
  const [modalAjuste, setModalAjuste] = useState<{pis: string, date: string, hora: string} | null>(null);
  const [motivoAjuste, setMotivoAjuste] = useState('');

  // Salvar sempre que houver mudança
  useEffect(() => {
    localStorage.setItem('abc_ponto_v5_final', JSON.stringify(data));
  }, [data]);

  // --- UTILITÁRIOS DE TEMPO ---
  const timeToMinutes = (time: string): number => {
    if (!time || !time.includes(':')) return 0;
    const [h, m] = time.split(':').map(Number);
    return (h * 60) + m;
  };

  const minutesToTime = (mins: number): string => {
    const h = Math.floor(Math.abs(mins) / 60);
    const m = Math.abs(mins) % 60;
    const sign = mins < 0 ? '-' : '';
    return `${sign}${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  // --- PARSER AFD (PORTARIA 671) ---
  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    // ISO-8859-1 trata acentuação corretamente vinda do REP
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split('\n');
      const newFuncs = [...data.funcionarios];
      const newPontos = { ...data.pontos };

      lines.forEach(line => {
        if (line.length < 34) return;
        const tipo = line.substring(9, 10);

        // Registro Tipo 5 - Cadastro/Alteração de Colaborador
        if (tipo === '5') {
          const pis = line.substring(22, 34).trim();
          const nome = line.substring(34, 86).trim();
          if (pis && !newFuncs.find(f => f.pis === pis)) {
            newFuncs.push({ pis, nome, ativo: true, jornadaDiariaMinutos: 480 });
          }
        } 
        // Registro Tipo 3 - Marcação de Ponto
        else if (tipo === '3') {
          const dia = line.substring(10, 12), mes = line.substring(12, 14), ano = line.substring(14, 18);
          const hora = line.substring(18, 20), min = line.substring(20, 22);
          const pis = line.substring(22, 34).trim();
          const dateKey = `${ano}-${mes}-${dia}`;
          const time = `${hora}:${min}`;

          if (pis) {
            if (!newPontos[pis]) newPontos[pis] = [];
            let diaPonto = newPontos[pis].find(p => p.data === dateKey);
            if (!diaPonto) {
              diaPonto = { data: dateKey, batidas: [], isFalta: false };
              newPontos[pis].push(diaPonto);
            }
            if (!diaPonto.batidas.find(b => b.hora === time)) {
              diaPonto.batidas.push({ hora: time, origem: 'AFD' });
              diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
            }
          }
        }
      });

      setData(prev => ({ ...prev, funcionarios: newFuncs, pontos: newPontos }));
    };
    event.target.value = '';
  };

  // --- LOGICA DE EXIBIÇÃO ---
  const filteredFuncs = useMemo(() => {
    return data.funcionarios.filter(f => {
      const matchesStatus = statusFilter === 'todos' ? true : (statusFilter === 'ativos' ? f.ativo : !f.ativo);
      const matchesSearch = f.nome.toLowerCase().includes(searchTerm.toLowerCase()) || f.pis.includes(searchTerm);
      return matchesStatus && matchesSearch;
    }).sort((a, b) => a.nome.localeCompare(b.nome));
  }, [data.funcionarios, statusFilter, searchTerm]);

  const toggleFuncVisibility = (pis: string) => {
    setData(prev => ({
      ...prev,
      funcionarios: prev.funcionarios.map(f => f.pis === pis ? { ...f, ativo: !f.ativo } : f)
    }));
  };

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: lastDay }, (_, i) => `${year}-${month}-${(i + 1).toString().padStart(2, '0')}`);
  }, [selectedMonth]);

  const activeEmployee = useMemo(() => data.funcionarios.find(f => f.pis === activePis), [data.funcionarios, activePis]);

  const calculateDay = (batidas: RegistroBatida[], jornadaNominal: number = 480) => {
    if (!batidas || batidas.length < 2) return { trabalhadas: 0, extras: 0, atraso: jornadaNominal };
    let totalMinutes = 0;
    const sorted = [...batidas].sort((a, b) => a.hora.localeCompare(b.hora));
    for (let i = 0; i < sorted.length - 1; i += 2) {
      const inMin = timeToMinutes(sorted[i].hora);
      const outMin = timeToMinutes(sorted[i+1].hora);
      if (outMin > inMin) totalMinutes += (outMin - inMin);
    }
    const diff = totalMinutes - jornadaNominal;
    return {
      trabalhadas: totalMinutes,
      extras: diff > 0 ? diff : 0,
      atraso: diff < 0 ? Math.abs(diff) : 0
    };
  };

  const handleSaveAjuste = () => {
    if (!modalAjuste || !motivoAjuste) return;
    const { pis, date, hora } = modalAjuste;
    const newPontos = { ...data.pontos };
    if (!newPontos[pis]) newPontos[pis] = [];
    let diaPonto = newPontos[pis].find(p => p.data === date);
    if (!diaPonto) {
      diaPonto = { data: date, batidas: [], isFalta: false };
      newPontos[pis].push(diaPonto);
    }
    diaPonto.batidas.push({ hora, origem: 'AJUSTE', obs: motivoAjuste });
    diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
    diaPonto.isFalta = false;

    const log: LogAuditoriaPonto = {
      id: crypto.randomUUID(),
      timestamp: new Date().toISOString(),
      usuario: 'Administrador',
      pis,
      dataPonto: date,
      tipo: 'inclusao',
      valorNovo: hora,
      motivo: motivoAjuste
    };
    setData(prev => ({ ...prev, pontos: newPontos, logs: [log, ...prev.logs] }));
    setModalAjuste(null);
    setMotivoAjuste('');
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* HEADER PRINCIPAL */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 pb-8 border-b border-slate-100">
        <div className="space-y-2">
          <div className="flex items-center gap-4">
             <div className="bg-[#E30613] p-3 rounded-2xl shadow-lg shadow-red-200">
                <ShieldCheck className="w-8 h-8 text-white" />
             </div>
             <div>
                <h2 className="text-5xl font-black text-slate-950 tracking-tighter uppercase">Auditoria de Ponto</h2>
                <p className="text-slate-400 font-bold uppercase text-[10px] tracking-[0.4em] mt-1">Gestão de Frequência e Horas Extras</p>
             </div>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-4">
          <div className="bg-[#0A1121] rounded-2xl p-4 text-white flex items-center gap-4 shadow-xl border border-slate-800">
            <Calendar className="w-5 h-5 text-[#E30613]" />
            <div className="flex flex-col">
               <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Mês de Referência</span>
               <input 
                 type="month" 
                 value={selectedMonth} 
                 onChange={(e) => setSelectedMonth(e.target.value)} 
                 className="bg-transparent text-sm font-black uppercase outline-none cursor-pointer" 
               />
            </div>
          </div>
          <label className="flex items-center gap-4 px-8 py-4 bg-white border-2 border-slate-200 text-slate-900 rounded-2xl cursor-pointer hover:border-[#E30613] transition-all font-black text-xs uppercase tracking-widest shadow-sm">
            <FileUp className="w-5 h-5 text-[#E30613]" />
            IMPORTAR AFD (.TXT)
            <input type="file" className="hidden" accept=".txt" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-10 items-start">
        {/* LISTA DE COLABORADORES */}
        <div className="lg:col-span-1 space-y-6">
           <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-2xl">
              <div className="flex items-center justify-between mb-6">
                 <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">Equipe</h3>
                 <div className="flex gap-1 bg-slate-100 p-1 rounded-lg">
                    <button onClick={() => setStatusFilter('ativos')} className={`p-1.5 rounded-md transition-all ${statusFilter === 'ativos' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`} title="Somente Visíveis"><UserCheck className="w-4 h-4" /></button>
                    <button onClick={() => setStatusFilter('inativos')} className={`p-1.5 rounded-md transition-all ${statusFilter === 'inativos' ? 'bg-white shadow-sm text-red-600' : 'text-slate-400'}`} title="Ocultos"><UserMinus className="w-4 h-4" /></button>
                    <button onClick={() => setStatusFilter('todos')} className={`p-1.5 rounded-md transition-all ${statusFilter === 'todos' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400'}`} title="Todos"><Filter className="w-4 h-4" /></button>
                 </div>
              </div>

              <div className="relative mb-4">
                 <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                 <input 
                   type="text" 
                   placeholder="Filtrar por nome..." 
                   value={searchTerm}
                   onChange={(e) => setSearchTerm(e.target.value)}
                   className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-xl text-xs font-bold outline-none focus:ring-2 focus:ring-red-500/10"
                 />
              </div>

              <div className="space-y-2 max-h-[60vh] overflow-y-auto pr-2 scrollbar-hide">
                 {filteredFuncs.length === 0 ? (
                   <p className="text-[10px] text-center text-slate-300 font-black py-10 uppercase">Nenhum registro</p>
                 ) : (
                   filteredFuncs.map(f => (
                     <div key={f.pis} className="flex gap-2 group">
                        <button 
                          onClick={() => setActivePis(f.pis)}
                          className={`flex-1 text-left p-4 rounded-2xl transition-all border flex flex-col gap-0.5 min-w-0 ${activePis === f.pis ? 'bg-[#E30613] text-white border-[#E30613] shadow-lg' : 'bg-slate-50 border-transparent text-slate-600 hover:bg-slate-100'}`}
                        >
                           <p className="text-[11px] font-black uppercase whitespace-nowrap overflow-hidden text-ellipsis w-full leading-tight">
                             {f.nome}
                           </p>
                           <p className={`text-[9px] font-bold ${activePis === f.pis ? 'text-white/60' : 'text-slate-400'}`}>PIS: {f.pis}</p>
                        </button>
                        <button 
                          onClick={() => toggleFuncVisibility(f.pis)}
                          className={`p-3 rounded-2xl border flex items-center justify-center transition-all ${f.ativo ? 'bg-slate-50 border-slate-100 text-slate-300 hover:text-red-500' : 'bg-red-50 border-red-100 text-red-500'}`}
                          title={f.ativo ? "Ocultar Colaborador" : "Mostrar Colaborador"}
                        >
                           {f.ativo ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                        </button>
                     </div>
                   ))
                 )}
              </div>
           </div>
        </div>

        {/* CARTÃO DE PONTO */}
        <div className="lg:col-span-3">
           {activeEmployee ? (
             <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden animate-in fade-in duration-500">
                <div className="p-10 border-b border-slate-100 bg-slate-50/50 flex flex-col md:flex-row justify-between items-center gap-6">
                   <div>
                      <h3 className="text-3xl font-black text-slate-950 uppercase tracking-tighter">{activeEmployee.nome}</h3>
                      <div className="flex items-center gap-4 mt-2">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Jornada CLT: 8h/dia</span>
                        <div className="flex items-center gap-1.5 px-3 py-1 bg-emerald-50 rounded-full border border-emerald-100">
                           <TrendingUp className="w-3 h-3 text-emerald-600" />
                           <span className="text-[9px] font-black text-emerald-600 uppercase">Score: 98%</span>
                        </div>
                      </div>
                   </div>
                   <button className="flex items-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-black transition-all">
                     <FileText className="w-4 h-4 text-[#E30613]" /> EXPORTAR ESPELHO PDF
                   </button>
                </div>

                <div className="overflow-x-auto">
                   <table className="w-full text-left">
                      <thead>
                        <tr className="bg-slate-950 text-slate-500">
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest">Dia</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest">Marcações (REP/AFD)</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-right">Trabalhadas</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-right">Saldo/Extras</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-center">Lançamentos</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                         {currentMonthDays.map(day => {
                            const diaPonto = data.pontos[activePis!]?.find(x => x.data === day);
                            const calc = calculateDay(diaPonto?.batidas || [], activeEmployee.jornadaDiariaMinutos);
                            const dt = new Date(day + 'T00:00:00');
                            const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                            return (
                               <tr key={day} className={`group hover:bg-slate-50 transition-all ${isWeekend ? 'bg-slate-50/30' : ''} ${diaPonto?.isFalta ? 'bg-red-50/30' : ''}`}>
                                  <td className="px-8 py-5">
                                     <div className="flex flex-col">
                                        <span className="text-xl font-black text-slate-900 leading-none">{day.split('-')[2]}</span>
                                        <span className="text-[9px] font-black text-slate-400 uppercase">{dt.toLocaleDateString('pt-BR', { weekday: 'short' })}</span>
                                     </div>
                                  </td>
                                  <td className="px-8 py-5">
                                     <div className="flex flex-wrap gap-2 items-center">
                                        {diaPonto?.batidas.map((b, i) => (
                                          <div key={i} className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border text-[11px] font-black shadow-sm ${b.origem === 'AJUSTE' ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-white border-slate-200 text-slate-700'}`}>
                                            {b.hora}
                                            {b.origem === 'AJUSTE' && <span title={b.obs} className="cursor-help"><Info className="w-3 h-3" /></span>}
                                          </div>
                                        ))}
                                        <button 
                                          onClick={() => setModalAjuste({ pis: activePis!, date: day, hora: '08:00' })}
                                          className="p-1.5 rounded-lg border-2 border-dashed border-slate-200 text-slate-300 hover:text-[#E30613] hover:border-[#E30613] transition-all"
                                        >
                                          <Plus className="w-4 h-4" />
                                        </button>
                                     </div>
                                  </td>
                                  <td className="px-8 py-5 text-right font-black text-slate-900">
                                    {calc.trabalhadas > 0 ? minutesToTime(calc.trabalhadas) : '—'}
                                  </td>
                                  <td className={`px-8 py-5 text-right font-black ${calc.extras > 0 ? 'text-emerald-600' : 'text-[#E30613]'}`}>
                                    {calc.extras > 0 ? `+${minutesToTime(calc.extras)}` : (calc.atraso > 0 && calc.atraso !== 480 ? `-${minutesToTime(calc.atraso)}` : '—')}
                                  </td>
                                  <td className="px-8 py-5 text-center">
                                     <button 
                                       onClick={() => {
                                          const newPts = {...data.pontos};
                                          if (!newPts[activePis!]) newPts[activePis!] = [];
                                          let dp = newPts[activePis!].find(x => x.data === day);
                                          if (!dp) {
                                            dp = { data: day, batidas: [], isFalta: false };
                                            newPts[activePis!].push(dp);
                                          }
                                          dp.isFalta = !dp.isFalta;
                                          if (dp.isFalta) dp.batidas = [];
                                          setData(prev => ({ ...prev, pontos: newPts }));
                                       }}
                                       className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${diaPonto?.isFalta ? 'bg-[#E30613] text-white' : 'bg-slate-100 text-slate-400 hover:bg-red-50 hover:text-[#E30613]'}`}
                                     >
                                       {diaPonto?.isFalta ? 'FALTA' : 'LANÇAR FALTA'}
                                     </button>
                                  </td>
                               </tr>
                            );
                         })}
                      </tbody>
                   </table>
                </div>
             </div>
           ) : (
             <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-[4rem] py-64 flex flex-col items-center justify-center text-slate-300">
               <Users className="w-20 h-20 mb-8 opacity-20" />
               <p className="text-2xl font-black text-slate-800 tracking-tight uppercase">Selecione um Colaborador na Lista</p>
               <p className="text-sm font-medium text-slate-400 mt-2 italic">Dica: Use os filtros da lateral para gerenciar quem aparece</p>
             </div>
           )}
        </div>
      </div>

      {/* MODAL DE AJUSTE AUDITADO */}
      {modalAjuste && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-md">
           <div className="bg-white rounded-[3rem] shadow-2xl max-w-lg w-full p-12 space-y-8 animate-in zoom-in-95">
              <div className="flex items-center gap-4 border-b border-slate-100 pb-6">
                 <div className="p-4 bg-red-50 rounded-2xl"><Edit3 className="text-[#E30613]" /></div>
                 <div>
                    <h3 className="text-2xl font-black text-slate-900 tracking-tighter uppercase">Ajuste de Ponto</h3>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Auditoria Portaria 671</p>
                 </div>
              </div>

              <div className="space-y-6">
                 <div className="flex justify-between items-end gap-6">
                    <div className="flex-1 space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Nova Batida</label>
                       <input 
                         type="time" 
                         value={modalAjuste.hora}
                         onChange={(e) => setModalAjuste({...modalAjuste, hora: e.target.value})}
                         className="w-full px-6 py-5 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-black text-4xl text-slate-900 outline-none focus:ring-4 focus:ring-red-500/10"
                       />
                    </div>
                    <div className="text-right pb-4">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Data do Evento</p>
                       <p className="font-black text-slate-900">{modalAjuste.date.split('-').reverse().join('/')}</p>
                    </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Motivo do Ajuste (Obrigatório)</label>
                    <textarea 
                      placeholder="Ex: Esquecimento, Viagem, Problema no relógio..."
                      value={motivoAjuste}
                      onChange={(e) => setMotivoAjuste(e.target.value)}
                      className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-slate-700 min-h-[120px] outline-none focus:ring-4 focus:ring-red-500/10"
                    />
                 </div>

                 <div className="flex flex-col gap-3">
                    <button 
                      onClick={handleSaveAjuste}
                      disabled={!motivoAjuste}
                      className="w-full py-5 bg-[#E30613] text-white rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-2xl disabled:opacity-30 hover:bg-red-700 transition-all flex items-center justify-center gap-3"
                    >
                      <Save className="w-4 h-4" /> SALVAR ALTERAÇÃO
                    </button>
                    <button 
                      onClick={() => { setModalAjuste(null); setMotivoAjuste(''); }}
                      className="w-full py-5 bg-slate-100 text-slate-400 rounded-[2rem] font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition-all"
                    >
                      CANCELAR
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, UserCheck, Calendar, FileText, Trash2, 
  CheckCircle2, AlertTriangle, Edit3, X, History, Users, 
  Search, LayoutDashboard, ShieldCheck, TrendingUp, AlertCircle, Save,
  Plus, UserMinus, Filter, Info, Eye, EyeOff
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, MarcacaoPonto, ControleHoras, LogAuditoriaPonto, RegistroBatida } from '../types';

type StatusFilter = 'ativos' | 'inativos' | 'todos';

export const HorasPage: React.FC = () => {
  // Estado principal persistente
  const [data, setData] = useState<ControleHoras>(() => {
    const saved = localStorage.getItem('abc_ponto_v6_audit');
    return saved ? JSON.parse(saved) : { funcionarios: [], pontos: {}, logs: [] };
  });

  const [statusFilter, setStatusFilter] = useState<StatusFilter>('ativos');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePis, setActivePis] = useState<string | null>(null);

  // Estado para Modais
  const [modalAjuste, setModalAjuste] = useState<{pis: string, date: string, hora: string} | null>(null);
  const [motivoAjuste, setMotivoAjuste] = useState('');

  // Salvar automaticamente no LocalStorage
  useEffect(() => {
    localStorage.setItem('abc_ponto_v6_audit', JSON.stringify(data));
  }, [data]);

  // --- FUNÇÕES DE TEMPO ---
  const timeToMinutes = (time: string): number => {
    if (!time || !time.includes(':')) return 0;
    const [h, m] = time.split(':').map(Number);
    return (h * 60) + m;
  };

  const minutesToTime = (mins: number): string => {
    const h = Math.floor(Math.abs(mins) / 60);
    const m = Math.abs(mins) % 60;
    const sign = mins < 0 ? '-' : '';
    return `${sign}${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  // --- PARSER AFD CORRIGIDO (PORTARIA 671) ---
  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    // ISO-8859-1 para acentuação brasileira do REP
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split('\n');
      const newFuncs = [...data.funcionarios];
      const newPontos = { ...data.pontos };

      lines.forEach(line => {
        if (line.length < 34) return;
        const tipo = line.substring(9, 10);

        // Tipo 5: Cadastro/Alteração (Indices exatos da Portaria 671)
        if (tipo === '5') {
          const pis = line.substring(22, 34).trim();
          const nome = line.substring(34, 86).trim().replace(/^\d+/, '').trim(); // Limpa IDs residuais no início do nome
          if (pis && !newFuncs.find(f => f.pis === pis)) {
            newFuncs.push({ pis, nome, ativo: true, jornadaDiariaMinutos: 480 });
          }
        } 
        // Tipo 3: Marcação de Ponto
        else if (tipo === '3') {
          const dia = line.substring(10, 12), mes = line.substring(12, 14), ano = line.substring(14, 18);
          const hora = line.substring(18, 20), min = line.substring(20, 22);
          const pis = line.substring(22, 34).trim();
          const dateKey = `${ano}-${mes}-${dia}`;
          const time = `${hora}:${min}`;

          if (pis) {
            if (!newPontos[pis]) newPontos[pis] = [];
            let diaPonto = newPontos[pis].find(p => p.data === dateKey);
            if (!diaPonto) {
              diaPonto = { data: dateKey, batidas: [], isFalta: false };
              newPontos[pis].push(diaPonto);
            }
            if (!diaPonto.batidas.find(b => b.hora === time)) {
              diaPonto.batidas.push({ hora: time, origem: 'AFD' });
              diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
            }
          }
        }
      });

      setData(prev => ({ ...prev, funcionarios: newFuncs, pontos: newPontos }));
    };
    event.target.value = '';
  };

  // --- FILTROS E BUSCA ---
  const filteredFuncs = useMemo(() => {
    return data.funcionarios.filter(f => {
      const matchesStatus = statusFilter === 'todos' ? true : (statusFilter === 'ativos' ? f.ativo : !f.ativo);
      const matchesSearch = f.nome.toLowerCase().includes(searchTerm.toLowerCase()) || f.pis.includes(searchTerm);
      return matchesStatus && matchesSearch;
    }).sort((a, b) => a.nome.localeCompare(b.nome));
  }, [data.funcionarios, statusFilter, searchTerm]);

  const activeEmployee = useMemo(() => data.funcionarios.find(f => f.pis === activePis), [data.funcionarios, activePis]);

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: lastDay }, (_, i) => `${year}-${month}-${(i + 1).toString().padStart(2, '0')}`);
  }, [selectedMonth]);

  const toggleVisibility = (pis: string) => {
    setData(prev => ({
      ...prev,
      funcionarios: prev.funcionarios.map(f => f.pis === pis ? { ...f, ativo: !f.ativo } : f)
    }));
  };

  const calculateDay = (batidas: RegistroBatida[], jornadaNominal: number = 480) => {
    if (!batidas || batidas.length < 2) return { trabalhadas: 0, extras: 0, atraso: jornadaNominal };
    let totalMinutes = 0;
    const sorted = [...batidas].sort((a, b) => a.hora.localeCompare(b.hora));
    for (let i = 0; i < sorted.length - 1; i += 2) {
      const inMin = timeToMinutes(sorted[i].hora);
      const outMin = timeToMinutes(sorted[i+1].hora);
      if (outMin > inMin) totalMinutes += (outMin - inMin);
    }
    const diff = totalMinutes - jornadaNominal;
    return {
      trabalhadas: totalMinutes,
      extras: diff > 0 ? diff : 0,
      atraso: diff < 0 ? Math.abs(diff) : 0
    };
  };

  const handleSaveAjuste = () => {
    if (!modalAjuste || !motivoAjuste) return;
    const { pis, date, hora } = modalAjuste;
    const newPontos = { ...data.pontos };
    if (!newPontos[pis]) newPontos[pis] = [];
    let diaPonto = newPontos[pis].find(p => p.data === date);
    if (!diaPonto) {
      diaPonto = { data: date, batidas: [], isFalta: false };
      newPontos[pis].push(diaPonto);
    }
    diaPonto.batidas.push({ hora, origem: 'AJUSTE', obs: motivoAjuste });
    diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
    diaPonto.isFalta = false;

    setData(prev => ({ ...prev, pontos: newPontos }));
    setModalAjuste(null);
    setMotivoAjuste('');
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* CABEÇALHO AUDITORIA */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 pb-8 border-b border-slate-100">
        <div className="flex items-center gap-4">
           <div className="bg-[#E30613] p-4 rounded-3xl shadow-xl shadow-red-100">
              <ShieldCheck className="w-8 h-8 text-white" />
           </div>
           <div>
              <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase">Auditoria de Ponto</h2>
              <p className="text-slate-400 font-bold uppercase text-[9px] tracking-[0.3em] mt-1">Conferência e Compliance de Equipe</p>
           </div>
        </div>

        <div className="flex items-center gap-4">
          <div className="bg-slate-900 rounded-2xl p-4 text-white flex items-center gap-4 border border-slate-800 shadow-xl">
            <Calendar className="w-5 h-5 text-[#E30613]" />
            <div className="flex flex-col">
               <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Mês de Referência</span>
               <input 
                 type="month" 
                 value={selectedMonth} 
                 onChange={(e) => setSelectedMonth(e.target.value)} 
                 className="bg-transparent text-xs font-black uppercase outline-none cursor-pointer" 
               />
            </div>
          </div>
          <label className="flex items-center gap-4 px-8 py-4 bg-white border-2 border-slate-200 text-slate-900 rounded-2xl cursor-pointer hover:border-[#E30613] transition-all font-black text-xs uppercase tracking-widest shadow-sm">
            <FileUp className="w-5 h-5 text-[#E30613]" />
            IMPORTAR AFD (.TXT)
            <input type="file" className="hidden" accept=".txt" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-10">
        {/* BARRA LATERAL - EQUIPE */}
        <div className="lg:col-span-1 bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-2xl space-y-6 h-fit">
           <div className="flex items-center justify-between">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Configuração de Equipe</h3>
              <div className="flex gap-1 bg-slate-100 p-1 rounded-lg">
                 <button onClick={() => setStatusFilter('ativos')} className={`p-1.5 rounded-md transition-all ${statusFilter === 'ativos' ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-400'}`} title="Visíveis"><UserCheck className="w-4 h-4" /></button>
                 <button onClick={() => setStatusFilter('inativos')} className={`p-1.5 rounded-md transition-all ${statusFilter === 'inativos' ? 'bg-white shadow-sm text-red-600' : 'text-slate-400'}`} title="Ocultos"><UserMinus className="w-4 h-4" /></button>
                 <button onClick={() => setStatusFilter('todos')} className={`p-1.5 rounded-md transition-all ${statusFilter === 'todos' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-400'}`} title="Todos"><Filter className="w-4 h-4" /></button>
              </div>
           </div>

           <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
              <input 
                type="text" 
                placeholder="Buscar por nome ou PIS..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-xl text-[10px] font-bold outline-none focus:ring-2 focus:ring-red-500/10"
              />
           </div>

           <div className="space-y-2 max-h-[55vh] overflow-y-auto pr-2 scrollbar-hide">
              {filteredFuncs.map(f => (
                <div key={f.pis} className="flex gap-2">
                   <button 
                     onClick={() => setActivePis(f.pis)}
                     className={`flex-1 text-left p-4 rounded-2xl transition-all border min-w-0 ${activePis === f.pis ? 'bg-[#E30613] text-white border-[#E30613] shadow-lg shadow-red-100' : 'bg-slate-50 border-transparent text-slate-600 hover:bg-slate-100'}`}
                   >
                      <p className="text-[11px] font-black uppercase whitespace-nowrap overflow-hidden text-ellipsis leading-tight">
                        {f.nome}
                      </p>
                      <p className={`text-[9px] font-bold mt-0.5 ${activePis === f.pis ? 'text-white/60' : 'text-slate-400'}`}>PIS: {f.pis}</p>
                   </button>
                   <button 
                     onClick={() => toggleVisibility(f.pis)}
                     className={`p-3 rounded-2xl border transition-all ${f.ativo ? 'bg-slate-50 border-slate-100 text-slate-300 hover:text-red-500' : 'bg-red-50 border-red-100 text-red-500'}`}
                     title={f.ativo ? "Ocultar da Auditoria" : "Reativar Colaborador"}
                   >
                      {f.ativo ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                   </button>
                </div>
              ))}
           </div>
        </div>

        {/* ÁREA PRINCIPAL - TABELA DE PONTO */}
        <div className="lg:col-span-3">
           {activeEmployee ? (
             <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden animate-in fade-in slide-in-from-right-4 duration-500">
                <div className="p-10 border-b border-slate-100 bg-slate-50/50 flex flex-col md:flex-row justify-between items-center gap-6">
                   <div className="min-w-0 flex-1">
                      <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter truncate whitespace-nowrap">{activeEmployee.nome}</h3>
                      <div className="flex items-center gap-4 mt-2">
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest bg-white px-3 py-1 rounded-full border border-slate-200">PIS: {activeEmployee.pis}</span>
                        <div className="flex items-center gap-1.5 px-3 py-1 bg-emerald-50 rounded-full border border-emerald-100">
                           <TrendingUp className="w-3 h-3 text-emerald-600" />
                           <span className="text-[9px] font-black text-emerald-600 uppercase tracking-tighter">Score: 98%</span>
                        </div>
                      </div>
                   </div>
                   <button className="flex items-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-black transition-all shrink-0 shadow-lg">
                     <FileText className="w-4 h-4 text-[#E30613]" /> GERAR ESPELHO PDF
                   </button>
                </div>

                <div className="overflow-x-auto">
                   <table className="w-full text-left">
                      <thead>
                        <tr className="bg-slate-950 text-slate-400">
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest">Dia/Semana</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest">Marcações (AFD/REP)</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-right">Trabalhadas</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-right">Saldo/Extras</th>
                          <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-center">Auditoria</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                         {currentMonthDays.map(day => {
                            const diaPonto = data.pontos[activePis!]?.find(x => x.data === day);
                            const calc = calculateDay(diaPonto?.batidas || [], activeEmployee.jornadaDiariaMinutos);
                            const dt = new Date(day + 'T00:00:00');
                            const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                            return (
                               <tr key={day} className={`group hover:bg-slate-50/80 transition-all ${isWeekend ? 'bg-slate-50/40' : ''} ${diaPonto?.isFalta ? 'bg-red-50/20' : ''}`}>
                                  <td className="px-8 py-5">
                                     <div className="flex flex-col">
                                        <span className="text-xl font-black text-slate-900 leading-none">{day.split('-')[2]}</span>
                                        <span className="text-[9px] font-black text-slate-400 uppercase">{dt.toLocaleDateString('pt-BR', { weekday: 'short' })}</span>
                                     </div>
                                  </td>
                                  <td className="px-8 py-5">
                                     <div className="flex flex-wrap gap-2 items-center">
                                        {diaPonto?.batidas.map((b, i) => (
                                          <div key={i} className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border text-[11px] font-black shadow-sm ${b.origem === 'AJUSTE' ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-white border-slate-200 text-slate-700'}`}>
                                            {b.hora}
                                            {b.origem === 'AJUSTE' && <span title={b.obs} className="cursor-help"><Info className="w-3 h-3" /></span>}
                                          </div>
                                        ))}
                                        <button 
                                          onClick={() => setModalAjuste({ pis: activePis!, date: day, hora: '08:00' })}
                                          className="p-1.5 rounded-lg border-2 border-dashed border-slate-200 text-slate-300 hover:text-[#E30613] hover:border-[#E30613] transition-all bg-slate-50/50"
                                        >
                                          <Plus className="w-4 h-4" />
                                        </button>
                                     </div>
                                  </td>
                                  <td className="px-8 py-5 text-right font-black text-slate-900">
                                    {calc.trabalhadas > 0 ? minutesToTime(calc.trabalhadas) : '—'}
                                  </td>
                                  <td className={`px-8 py-5 text-right font-black ${calc.extras > 0 ? 'text-emerald-600' : 'text-[#E30613]'}`}>
                                    {calc.extras > 0 ? `+${minutesToTime(calc.extras)}` : (calc.atraso > 0 && calc.atraso !== 480 ? `-${minutesToTime(calc.atraso)}` : '—')}
                                  </td>
                                  <td className="px-8 py-5 text-center">
                                     <button 
                                       onClick={() => {
                                          const newPts = {...data.pontos};
                                          if (!newPts[activePis!]) newPts[activePis!] = [];
                                          let dp = newPts[activePis!].find(x => x.data === day);
                                          if (!dp) {
                                            dp = { data: day, batidas: [], isFalta: false };
                                            newPts[activePis!].push(dp);
                                          }
                                          dp.isFalta = !dp.isFalta;
                                          if (dp.isFalta) dp.batidas = [];
                                          setData(prev => ({ ...prev, pontos: newPts }));
                                       }}
                                       className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${diaPonto?.isFalta ? 'bg-[#E30613] text-white shadow-lg' : 'bg-slate-100 text-slate-400 hover:bg-red-50 hover:text-[#E30613]'}`}
                                     >
                                       {diaPonto?.isFalta ? 'FALTA' : 'LANÇAR FALTA'}
                                     </button>
                                  </td>
                               </tr>
                            );
                         })}
                      </tbody>
                   </table>
                </div>
             </div>
           ) : (
             <div className="bg-white border-2 border-dashed border-slate-200 rounded-[4rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-sm">
               <div className="bg-slate-50 p-6 rounded-full mb-8">
                  <Users className="w-16 h-16 opacity-20" />
               </div>
               <p className="text-2xl font-black text-slate-800 tracking-tight uppercase">Selecione um Colaborador</p>
               <p className="text-sm font-medium text-slate-400 mt-2 italic">A auditoria exige a seleção de um funcionário ativo na lateral</p>
             </div>
           )}
        </div>
      </div>

      {/* MODAL DE AJUSTE */}
      {modalAjuste && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-md">
           <div className="bg-white rounded-[3rem] shadow-2xl max-w-lg w-full p-12 space-y-8 animate-in zoom-in-95 duration-300">
              <div className="flex items-center gap-4 border-b border-slate-100 pb-6">
                 <div className="p-4 bg-red-50 rounded-2xl"><Edit3 className="text-[#E30613]" /></div>
                 <div>
                    <h3 className="text-2xl font-black text-slate-900 tracking-tighter uppercase">Lançamento Auditado</h3>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Ajuste Manual de Registro REP</p>
                 </div>
              </div>

              <div className="space-y-6">
                 <div className="flex justify-between items-end gap-6">
                    <div className="flex-1 space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Hora do Registro</label>
                       <input 
                         type="time" 
                         value={modalAjuste.hora}
                         onChange={(e) => setModalAjuste({...modalAjuste, hora: e.target.value})}
                         className="w-full px-6 py-5 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-black text-4xl text-slate-900 outline-none focus:ring-4 focus:ring-red-500/10"
                       />
                    </div>
                    <div className="text-right pb-4">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Data</p>
                       <p className="font-black text-slate-900 text-lg">{modalAjuste.date.split('-').reverse().join('/')}</p>
                    </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Justificativa do Ajuste (Obrigatória)</label>
                    <textarea 
                      placeholder="Ex: Esquecimento do cartão, Visita externa à obra, Problema técnico no relógio..."
                      value={motivoAjuste}
                      onChange={(e) => setMotivoAjuste(e.target.value)}
                      className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-slate-700 min-h-[120px] outline-none focus:ring-4 focus:ring-red-500/10"
                    />
                 </div>

                 <div className="flex flex-col gap-3">
                    <button 
                      onClick={handleSaveAjuste}
                      disabled={!motivoAjuste}
                      className="w-full py-6 bg-[#E30613] text-white rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl shadow-red-200 disabled:opacity-30 hover:bg-red-700 transition-all flex items-center justify-center gap-3"
                    >
                      <Save className="w-4 h-4" /> GRAVAR ALTERAÇÃO
                    </button>
                    <button 
                      onClick={() => { setModalAjuste(null); setMotivoAjuste(''); }}
                      className="w-full py-5 bg-slate-100 text-slate-400 rounded-[2rem] font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition-all"
                    >
                      CANCELAR
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, UserCheck, Calendar, FileText, Trash2, 
  CheckCircle2, AlertTriangle, Edit3, X, History, Users, 
  Search, LayoutDashboard, ShieldCheck, TrendingUp, AlertCircle, Save,
  Plus, UserMinus, Filter, Info, Eye, EyeOff, Settings2
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, MarcacaoPonto, ControleHoras, LogAuditoriaPonto, RegistroBatida } from '../types';

type StatusFilter = 'ativos' | 'inativos' | 'todos';

export const HorasPage: React.FC = () => {
  const [data, setData] = useState<ControleHoras>(() => {
    const saved = localStorage.getItem('abc_ponto_v7_final');
    return saved ? JSON.parse(saved) : { funcionarios: [], pontos: {}, logs: [] };
  });

  const [statusFilter, setStatusFilter] = useState<StatusFilter>('ativos');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePis, setActivePis] = useState<string | null>(null);
  const [isConfigMode, setIsConfigMode] = useState(false);

  const [modalAjuste, setModalAjuste] = useState<{pis: string, date: string, hora: string} | null>(null);
  const [motivoAjuste, setMotivoAjuste] = useState('');

  useEffect(() => {
    localStorage.setItem('abc_ponto_v7_final', JSON.stringify(data));
  }, [data]);

  // --- UTILS ---
  const formatPIS = (pis: string) => pis.trim().padStart(12, '0');

  const timeToMinutes = (time: string): number => {
    if (!time || !time.includes(':')) return 0;
    const [h, m] = time.split(':').map(Number);
    return (h * 60) + m;
  };

  const minutesToTime = (mins: number): string => {
    const h = Math.floor(Math.abs(mins) / 60);
    const m = Math.abs(mins) % 60;
    const sign = mins < 0 ? '-' : '';
    return `${sign}${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  // --- PARSER AFD PORTARIA 671 ---
  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split('\n');
      const newFuncs = [...data.funcionarios];
      const newPontos = { ...data.pontos };

      lines.forEach(line => {
        if (line.length < 30) return;
        const tipo = line.substring(9, 10);

        // Registro 5: Cadastro (Posição 10 = '5')
        if (tipo === '5') {
          const pis = formatPIS(line.substring(22, 34));
          const nomeRaw = line.substring(34, 86).trim();
          // Remove números que podem vir no início do campo nome devido a offsets errados
          const nomeLimpo = nomeRaw.replace(/^\d+/, '').trim();

          if (pis && pis !== "000000000000" && !newFuncs.find(f => formatPIS(f.pis) === pis)) {
            newFuncs.push({ pis, nome: nomeLimpo, ativo: true, jornadaDiariaMinutos: 480 });
          }
        } 
        // Registro 3: Marcação (Posição 10 = '3')
        else if (tipo === '3') {
          const dia = line.substring(10, 12), mes = line.substring(12, 14), ano = line.substring(14, 18);
          const hora = line.substring(18, 20), min = line.substring(20, 22);
          const pis = formatPIS(line.substring(22, 34));
          const dateKey = `${ano}-${mes}-${dia}`;
          const time = `${hora}:${min}`;

          if (pis && pis !== "000000000000") {
            if (!newPontos[pis]) newPontos[pis] = [];
            let diaPonto = newPontos[pis].find(p => p.data === dateKey);
            if (!diaPonto) {
              diaPonto = { data: dateKey, batidas: [], isFalta: false };
              newPontos[pis].push(diaPonto);
            }
            if (!diaPonto.batidas.find(b => b.hora === time)) {
              diaPonto.batidas.push({ hora: time, origem: 'AFD' });
              diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
            }
          }
        }
      });

      setData(prev => ({ ...prev, funcionarios: newFuncs, pontos: newPontos }));
    };
    event.target.value = '';
  };

  const filteredFuncs = useMemo(() => {
    return data.funcionarios.filter(f => {
      const matchesStatus = statusFilter === 'todos' ? true : (statusFilter === 'ativos' ? f.ativo : !f.ativo);
      const matchesSearch = f.nome.toLowerCase().includes(searchTerm.toLowerCase()) || f.pis.includes(searchTerm);
      return matchesStatus && matchesSearch;
    }).sort((a, b) => a.nome.localeCompare(b.nome));
  }, [data.funcionarios, statusFilter, searchTerm]);

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: lastDay }, (_, i) => `${year}-${month}-${(i + 1).toString().padStart(2, '0')}`);
  }, [selectedMonth]);

  const activeEmployee = useMemo(() => data.funcionarios.find(f => f.pis === activePis), [data.funcionarios, activePis]);

  const calculateDay = (batidas: RegistroBatida[], jornadaNominal: number = 480) => {
    if (!batidas || batidas.length < 2) return { trabalhadas: 0, extras: 0, atraso: jornadaNominal };
    let totalMinutes = 0;
    const sorted = [...batidas].sort((a, b) => a.hora.localeCompare(b.hora));
    for (let i = 0; i < sorted.length - 1; i += 2) {
      const inMin = timeToMinutes(sorted[i].hora);
      const outMin = timeToMinutes(sorted[i+1].hora);
      if (outMin > inMin) totalMinutes += (outMin - inMin);
    }
    const diff = totalMinutes - jornadaNominal;
    return { trabalhadas: totalMinutes, extras: diff > 0 ? diff : 0, atraso: diff < 0 ? Math.abs(diff) : 0 };
  };

  const handleSaveAjuste = () => {
    if (!modalAjuste || !motivoAjuste) return;
    const { pis, date, hora } = modalAjuste;
    const newPontos = { ...data.pontos };
    if (!newPontos[pis]) newPontos[pis] = [];
    let diaPonto = newPontos[pis].find(p => p.data === date);
    if (!diaPonto) {
      diaPonto = { data: date, batidas: [], isFalta: false };
      newPontos[pis].push(diaPonto);
    }
    diaPonto.batidas.push({ hora, origem: 'AJUSTE', obs: motivoAjuste });
