import React, { useState, useMemo, useEffect } from 'react';
import { 
  TrendingUp, 
  TrendingDown, 
  Plus, 
  ArrowUpCircle, 
  ArrowDownCircle, 
  Calendar, 
  ChevronLeft, 
  ChevronRight,
  Wallet,
  Scale,
  Trash2,
  CheckCircle2,
  FileText
} from 'lucide-react';
import { ContaPagar, Recebimento } from '../types';
import { storageService } from '../services/storageService';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

export const FluxoCaixaPage: React.FC = () => {
  const [contasPagar, setContasPagar] = useState<ContaPagar[]>(() => storageService.getContasPagar());
  const [recebimentos, setRecebimentos] = useState<Recebimento[]>(() => storageService.getRecebimentos());
  const [showInModal, setShowInModal] = useState(false);
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));

  const [newIn, setNewIn] = useState<Partial<Recebimento>>({
    dataRecebimento: new Date().toISOString().split('T')[0],
    origem: '',
    valor: 0,
    recebido: false
  });

  // Atualiza os dados se houver mudanças em outras abas (Contas a Pagar)
  useEffect(() => {
    const handleUpdate = () => {
      setContasPagar(storageService.getContasPagar());
      setRecebimentos(storageService.getRecebimentos());
    };
    window.addEventListener('storage_financeiro_update', handleUpdate);
    return () => window.removeEventListener('storage_financeiro_update', handleUpdate);
  }, []);

  useEffect(() => {
    storageService.saveRecebimentos(recebimentos);
  }, [recebimentos]);

  const stats = useMemo(() => {
    const monthIn = recebimentos.filter(r => r.dataRecebimento.startsWith(selectedMonth));
    const monthOut = contasPagar.filter(c => c.dataPagamento.startsWith(selectedMonth));

    const totalIn = monthIn.reduce((acc, r) => acc + r.valor, 0);
    const totalOut = monthOut.reduce((acc, c) => acc + c.valor, 0);

    const realIn = monthIn.filter(r => r.recebido).reduce((acc, r) => acc + r.valor, 0);
    const realOut = monthOut.filter(c => c.pago).reduce((acc, c) => acc + c.valor, 0);

    return {
      previsto: totalIn - totalOut,
      realizado: realIn - realOut,
      totalIn, totalOut, realIn, realOut
    };
  }, [recebimentos, contasPagar, selectedMonth]);

  const handleAddIn = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newIn.origem || !newIn.valor) return;

    const entry: Recebimento = {
      id: crypto.randomUUID(),
      dataCadastro: new Date().toLocaleDateString('pt-BR'),
      dataRecebimento: newIn.dataRecebimento || '',
      origem: newIn.origem || '',
      valor: newIn.valor || 0,
      recebido: newIn.recebido || false
    };

    setRecebimentos(prev => [...prev, entry]);
    setShowInModal(false);
    setNewIn({
      dataRecebimento: new Date().toISOString().split('T')[0],
      origem: '', valor: 0, recebido: false
    });
  };

  const deleteIn = (id: string) => {
    if (confirm('Excluir este recebimento?')) {
      setRecebimentos(prev => prev.filter(r => r.id !== id));
    }
  };

  const toggleInStatus = (id: string) => {
    setRecebimentos(prev => prev.map(r => r.id === id ? { ...r, recebido: !r.recebido } : r));
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  return (
    <div className="space-y-12 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div>
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Fluxo de Caixa</h2>
          <input 
            type="month" 
            value={selectedMonth} 
            onChange={e => setSelectedMonth(e.target.value)}
            className="mt-2 bg-slate-100 px-3 py-1 rounded-lg text-[10px] font-black uppercase outline-none cursor-pointer border border-slate-200"
          />
        </div>
        <button
          onClick={() => setShowInModal(true)}
          className="flex items-center gap-4 px-10 py-5 bg-emerald-600 text-white rounded-2xl shadow-xl hover:bg-emerald-700 transition-all font-black text-xs uppercase tracking-widest"
        >
          <Plus className="w-5 h-5" /> REGISTRAR ENTRADA
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
          <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">Entradas Realizadas</span>
          <p className="text-4xl font-black tracking-tighter text-emerald-600 mt-1">{formatCurrency(stats.realIn)}</p>
        </div>
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
          <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">Saídas Pagas</span>
          <p className="text-4xl font-black tracking-tighter text-[#E30613] mt-1">{formatCurrency(stats.realOut)}</p>
        </div>
        <div className={`rounded-[2.5rem] p-8 text-white shadow-2xl ${stats.realizado >= 0 ? 'bg-[#0A1121]' : 'bg-red-950'}`}>
          <span className="text-[9px] font-black uppercase tracking-widest text-slate-500">Saldo Disponível (Caixa)</span>
          <p className="text-4xl font-black tracking-tighter mt-1">{formatCurrency(stats.realizado)}</p>
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-[3rem] shadow-xl overflow-hidden">
        <div className="p-8 border-b border-slate-100 bg-emerald-50/20">
           <h3 className="text-xs font-black text-slate-900 uppercase tracking-widest">Controle de Entradas / Recebimentos</h3>
        </div>
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[10px] font-black uppercase text-slate-400">
            <tr>
              <th className="px-8 py-4">Data</th>
              <th className="px-8 py-4">Origem</th>
              <th className="px-8 py-4 text-right">Valor</th>
              <th className="px-8 py-4 text-center">Status</th>
              <th className="px-8 py-4 text-center">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {recebimentos.filter(r => r.dataRecebimento.startsWith(selectedMonth)).map(r => (
              <tr key={r.id} className={`hover:bg-slate-50 ${r.recebido ? 'opacity-50' : ''}`}>
                <td className="px-8 py-4 text-xs font-black">{new Date(r.dataRecebimento).toLocaleDateString('pt-BR')}</td>
                <td className="px-8 py-4 text-xs font-bold text-slate-600 uppercase">{r.origem}</td>
                <td className="px-8 py-4 text-right font-black text-slate-900">{formatCurrency(r.valor)}</td>
                <td className="px-8 py-4 text-center">
                  <button 
                    onClick={() => toggleInStatus(r.id)}
                    className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border ${r.recebido ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-slate-100 text-slate-400 border-slate-200'}`}
                  >
                    {r.recebido ? 'Recebido' : 'Pendente'}
                  </button>
                </td>
                <td className="px-8 py-4 text-center">
                  <button onClick={() => deleteIn(r.id)} className="text-slate-300 hover:text-red-500">
                    <Trash2 className="w-4 h-4" />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { BarChart3, ChevronLeft, ChevronRight, TrendingUp, Info, ArrowRight } from 'lucide-react';
import { storageService } from '../services/storageService';

export const DREPage: React.FC = () => {
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [history, setHistory] = useState(() => storageService.getHistory());
  const [contasPagar, setContasPagar] = useState(() => storageService.getContasPagar());

  useEffect(() => {
    const handleUpdate = () => {
      setHistory(storageService.getHistory());
      setContasPagar(storageService.getContasPagar());
    };
    window.addEventListener('storage_financeiro_update', handleUpdate);
    return () => window.removeEventListener('storage_financeiro_update', handleUpdate);
  }, []);

  const dreData = useMemo(() => {
    const mesVendas = history.meses.find(m => m.mesReferencia === selectedMonth);
    const pedidos = mesVendas?.pedidos || [];

    const receitaBruta = pedidos.reduce((acc, p) => acc + p.total, 0);
    const margemOriginal = pedidos.reduce((acc, p) => acc + p.margemOriginal, 0);
    const totalAjustes = pedidos.reduce((acc, p) => acc + (p.credito - p.debito), 0);
    const margemAjustada = margemOriginal + totalAjustes;

    const despesasMes = contasPagar.filter(c => c.dataPagamento.startsWith(selectedMonth));
    const totalDespesas = despesasMes.reduce((acc, c) => acc + c.valor, 0);

    const lucroLiquido = margemAjustada - totalDespesas;
    const margemPct = receitaBruta > 0 ? (lucroLiquido / receitaBruta) * 100 : 0;

    return {
      receitaBruta,
      cmv: receitaBruta - margemOriginal,
      margemOriginal,
      totalAjustes,
      margemAjustada,
      totalDespesas,
      lucroLiquido,
      margemPct,
      hasData: pedidos.length > 0 || despesasMes.length > 0
    };
  }, [selectedMonth, history, contasPagar]);

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  return (
    <div className="space-y-12 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div>
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">DRE</h2>
          <input 
            type="month" 
            value={selectedMonth} 
            onChange={e => setSelectedMonth(e.target.value)}
            className="mt-2 bg-slate-100 px-3 py-1 rounded-lg text-[10px] font-black uppercase outline-none cursor-pointer border border-slate-200"
          />
        </div>
      </div>

      {!dreData.hasData ? (
        <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-[3rem] py-40 text-center text-slate-300">
           <BarChart3 className="w-16 h-16 mx-auto mb-4 opacity-20" />
           <p className="font-black uppercase text-[10px] tracking-widest">Nenhum dado consolidado para {selectedMonth}</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
           <div className="lg:col-span-2 bg-white border border-slate-200 rounded-[3rem] shadow-xl overflow-hidden p-10">
              <h3 className="text-xs font-black text-slate-950 uppercase tracking-[0.2em] mb-8 border-b border-slate-50 pb-4">Estrutura de Resultado</h3>
              <div className="space-y-4">
                 <div className="flex justify-between text-xs font-black text-slate-900 uppercase">
                    <span>Receita Bruta</span>
                    <span>{formatCurrency(dreData.receitaBruta)}</span>
                 </div>
                 <div className="flex justify-between text-xs font-bold text-slate-400 uppercase">
                    <span>(-) Custos Mercadorias (CMV)</span>
                    <span>{formatCurrency(dreData.cmv)}</span>
                 </div>
                 <div className="flex justify-between text-xs font-black text-slate-900 uppercase bg-slate-50 p-3 rounded-xl border border-slate-100">
                    <span>(=) Resultado Bruto</span>
                    <span>{formatCurrency(dreData.margemOriginal)}</span>
                 </div>
                 <div className="flex justify-between text-xs font-bold text-slate-400 uppercase">
                    <span>(+/-) Ajustes Auditoria (Créditos/Débitos)</span>
                    <span className={dreData.totalAjustes >= 0 ? 'text-emerald-600' : 'text-red-600'}>
                       {formatCurrency(dreData.totalAjustes)}
                    </span>
                 </div>
                 <div className="flex justify-between text-xs font-black text-slate-900 uppercase bg-slate-50 p-3 rounded-xl border border-slate-100">
                    <span>(=) Margem de Contribuição Auditada</span>
                    <span>{formatCurrency(dreData.margemAjustada)}</span>
                 </div>
                 <div className="flex justify-between text-xs font-bold text-red-500 uppercase">
                    <span>(-) Despesas Operacionais (Contas Pagar)</span>
                    <span>{formatCurrency(dreData.totalDespesas)}</span>
                 </div>

                 <div className="mt-8 bg-[#0A1121] p-8 rounded-[2rem] text-white flex justify-between items-center shadow-2xl">
                    <div>
                       <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Lucro / Prejuízo Líquido</p>
                       <p className="text-4xl font-black tracking-tighter">{formatCurrency(dreData.lucroLiquido)}</p>
                    </div>
                    <div className="text-right">
                       <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Rentabilidade</p>
                       <p className={`text-2xl font-black ${dreData.lucroLiquido >= 0 ? 'text-emerald-400' : 'text-[#E30613]'}`}>{dreData.margemPct.toFixed(2)}%</p>
                    </div>
                 </div>
              </div>
           </div>

           <div className="space-y-6">
              <div className="bg-blue-50 border border-blue-100 rounded-[2rem] p-8">
                 <div className="flex items-center gap-3 mb-4">
                    <Info className="w-5 h-5 text-blue-600" />
                    <h4 className="text-[10px] font-black text-blue-900 uppercase tracking-widest">Auditoria Inteligente</h4>
                 </div>
                 <p className="text-[11px] font-medium text-blue-800 leading-relaxed">
                    Este relatório cruza os dados de vendas que foram finalizados na auditoria com as despesas reais lançadas no financeiro.
                 </p>
              </div>
              <div className="bg-white border border-slate-200 rounded-[2rem] p-8 shadow-lg">
                 <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Ponto de Equilíbrio</h4>
                 <p className="text-2xl font-black text-slate-900">{formatCurrency(dreData.totalDespesas)}</p>
                 <p className="text-[9px] font-bold text-slate-400 uppercase mt-2">Margem bruta mínima necessária para cobrir despesas fixas.</p>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  TrendingUp, 
  Plus, 
  Calendar, 
  Wallet,
  Trash2,
  Save,
  X,
  ArrowUpCircle,
  ArrowDownCircle,
  FileText
} from 'lucide-react';
import { ContaPagar, Recebimento } from '../types';
import { storageService } from '../services/storageService';

export const FluxoCaixaPage: React.FC = () => {
  const [contasPagar, setContasPagar] = useState<ContaPagar[]>(() => storageService.getContasPagar());
  const [recebimentos, setRecebimentos] = useState<Recebimento[]>(() => storageService.getRecebimentos());
  const [showInModal, setShowInModal] = useState(false);
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));

  const [newIn, setNewIn] = useState<Partial<Recebimento>>({
    dataRecebimento: new Date().toISOString().split('T')[0],
    origem: '',
    valor: 0,
    recebido: true // Por padrão, entradas manuais costumam ser o que já entrou
  });

  // Sincronização entre abas e persistência
  useEffect(() => {
    const handleUpdate = () => {
      setContasPagar(storageService.getContasPagar());
      setRecebimentos(storageService.getRecebimentos());
    };
    window.addEventListener('storage_financeiro_update', handleUpdate);
    return () => window.removeEventListener('storage_financeiro_update', handleUpdate);
  }, []);

  // Sempre que recebimentos mudar, salva no banco de dados
  useEffect(() => {
    storageService.saveRecebimentos(recebimentos);
    window.dispatchEvent(new Event('storage_financeiro_update'));
  }, [recebimentos]);

  const stats = useMemo(() => {
    const monthIn = recebimentos.filter(r => r.dataRecebimento.startsWith(selectedMonth));
    const monthOut = contasPagar.filter(c => c.dataPagamento.startsWith(selectedMonth));

    const totalIn = monthIn.reduce((acc, r) => acc + r.valor, 0);
    const totalOut = monthOut.reduce((acc, c) => acc + c.valor, 0);

    const realIn = monthIn.filter(r => r.recebido).reduce((acc, r) => acc + r.valor, 0);
    const realOut = monthOut.filter(c => c.pago).reduce((acc, c) => acc + c.valor, 0);

    return {
      previsto: totalIn - totalOut,
      realizado: realIn - realOut,
      totalIn, totalOut, realIn, realOut
    };
  }, [recebimentos, contasPagar, selectedMonth]);

  const handleAddIn = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newIn.origem || !newIn.valor || newIn.valor <= 0) {
      alert("Por favor, preencha a origem e um valor válido.");
      return;
    }

    const entry: Recebimento = {
      id: crypto.randomUUID(),
      dataCadastro: new Date().toLocaleDateString('pt-BR'),
      dataRecebimento: newIn.dataRecebimento || new Date().toISOString().split('T')[0],
      origem: newIn.origem || '',
      valor: newIn.valor || 0,
      recebido: newIn.recebido ?? true
    };

    setRecebimentos(prev => [...prev, entry]);
    setShowInModal(false);

    // Reset form
    setNewIn({
      dataRecebimento: new Date().toISOString().split('T')[0],
      origem: '', 
      valor: 0, 
      recebido: true
    });
  };

  const deleteIn = (id: string) => {
    if (confirm('Deseja excluir permanentemente este registro de entrada?')) {
      setRecebimentos(prev => prev.filter(r => r.id !== id));
    }
  };

  const toggleInStatus = (id: string) => {
    setRecebimentos(prev => prev.map(r => r.id === id ? { ...r, recebido: !r.recebido } : r));
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  return (
    <div className="space-y-12 animate-in fade-in duration-500">
      {/* HEADER */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
