                    <td className="px-2 py-3">
                       <div className="flex items-center gap-1">
                          <Share2 className="w-2.5 h-2.5 text-slate-300 shrink-0" />
                          <span className="text-slate-700 uppercase font-black tracking-tighter truncate leading-none">{p.canal || "---"}</span>
                       </div>
                    </td>
                    <td className="px-3 py-3 text-slate-600 uppercase font-bold group/vend min-w-0">
                       <div className="flex items-center gap-1 overflow-hidden">
                          {editingVendedor?.id === p.id ? (
                            <div className="flex items-center gap-1 w-full">
                               <input type="text" value={editingVendedor.nome} onChange={(e) => setEditingVendedor({...editingVendedor, nome: e.target.value.toUpperCase()})} className="w-full bg-white border border-slate-300 rounded px-1.5 py-1 text-[9px] outline-none focus:ring-1 focus:ring-[#E30613]" autoFocus />
                               <button onClick={() => { onUpdatePedido?.(p.id, { vendedor: editingVendedor.nome }); setEditingVendedor(null); }} className="p-1 bg-emerald-500 text-white rounded"><Check className="w-2.5 h-2.5" /></button>
                            </div>
                          ) : (
                            <>
