                              {!readOnly && (isEcommerce || p.vendedor === "" || p.vendedor === "." || p.vendedor === "SISTEMA") && (
                                <button onClick={() => setEditingVendedor({id: p.id, nome: p.vendedor})} className="p-1 text-slate-300 hover:text-[#E30613] transition-all opacity-0 group-hover/vend:opacity-100 shrink-0">
                                  <User className="w-2.5 h-2.5" />
                                </button>
                              )}
                            </>
                          )}
                       </div>
                    </td>
                    <td className={`px-2 py-3 font-black text-right ${p.isOcorrencia ? 'text-slate-400 line-through' : 'text-slate-900'}`}>{formatCurrency(p.total || 0)}</td>
                    <td className="px-2 py-3 text-slate-400 italic text-right">{formatCurrency(p.margemOriginal || 0)}</td>
                    <td className="px-2 py-3 text-slate-500 text-center font-medium">{formatPercent(p.margemOriginalPct || 0)}</td>

                    {!readOnly && (
                      <td className="px-2 py-3 text-center">
