              })}
            </tbody>
            <tfoot className="bg-[#0A1121] text-white sticky bottom-0 z-30">
              <tr className="border-t border-slate-800">
                <td colSpan={5} className="px-3 py-4 text-right font-black text-[8px] uppercase tracking-widest text-slate-500">RESUMO AUDITORIA (LÍQUIDO):</td>
                <td className="px-2 py-4 font-black text-right">{formatCurrency(totals.total)}</td>
                <td className="px-2 py-4 font-bold text-slate-600 italic text-right">{formatCurrency(totals.margemOriginal)}</td>
