import React, { useState, useMemo } from 'react';
import { PackageOpen, FileUp, CheckCircle2, Info, TrendingDown, Search, AlertCircle, History, AlertOctagon } from 'lucide-react';
import * as XLSX from 'xlsx';
import { MesConferencia, Pedido } from '../types';

interface DevolvidosPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null) => void;
}

export const DevolvidosPage: React.FC<DevolvidosPageProps> = ({ data, onSetData }) => {
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState({ matched: 0, addedNew: 0, totalDeduzido: 0 });
  const [processedLog, setProcessedLog] = useState<{mu: string, valor: number, margem: number, status: 'sucesso' | 'novo_lancamento' | 'ocorrencia'}[]>([]);

  const toNumber = (val: any): number => {
    if (val === null || val === undefined || val === '' || val === '-') return 0;
    if (typeof val === 'number') return val;
    let str = String(val).replace(/R\$/g, '').replace(/\s/g, '').trim();
    if (str.includes('.') && str.includes(',')) str = str.replace(/\./g, '').replace(',', '.');
    else if (str.includes(',')) str = str.replace(',', '.');
    return parseFloat(str) || 0;
  };

  const getActualKey = (firstRow: any, targets: string[]): string => {
    const keys = Object.keys(firstRow);
    for (const target of targets) {
      const normalizedTarget = target.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
      const found = keys.find(k => k.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim().includes(normalizedTarget));
      if (found) return found;
    }
    return targets[0];
  };

  const ocorrenciasData = useMemo(() => {
    return data?.pedidos.filter(p => p.isOcorrencia) || [];
  }, [data]);

  const handleImportDevolvidos = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !data) return;

    setLoading(true);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const dataArray = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(dataArray, { type: 'array' });
        const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { defval: "" }) as any[];

        const firstRow = rows[0];
        const keyMU = getActualKey(firstRow, ["Nº Pedido MU", "Pedido MU", "MU"]);
        const keyPrecoTotal = getActualKey(firstRow, ["Preço total", "Preco total", "Valor Devolvido"]);
        const keyMargemDeduzir = getActualKey(firstRow, ["Margem Deduzir c/ frete", "Margem Deduzir", "Diferenca Margem"]);

        const newPedidos = [...data.pedidos];
        let matchedCount = 0;
        let addedNewCount = 0;
        let deduzidoSum = 0;
        const log: typeof processedLog = [];

        rows.forEach(row => {
          const mu = String(row[keyMU] || "").trim();
          if (!mu || mu === "0" || mu.toLowerCase().includes("total")) return;

          const valorDevolvido = toNumber(row[keyPrecoTotal]);
          const margemDeduzir = toNumber(row[keyMargemDeduzir]);
          deduzidoSum += Math.abs(margemDeduzir);

          const index = newPedidos.findIndex(p => p.id === mu);
          if (index !== -1) {
            newPedidos[index].isDevolvido = true;
            newPedidos[index].margemDeduzidaDevolucao = (newPedidos[index].margemDeduzidaDevolucao || 0) + margemDeduzir;
            newPedidos[index].total = Math.max(0, newPedidos[index].total - valorDevolvido);
            matchedCount++;
            log.push({ mu, valor: valorDevolvido, margem: margemDeduzir, status: 'sucesso' });
          } else {
            const novoPedidoAjuste: Pedido = {
              id: mu,
              data: "Mês Anterior",
              canal: "AJUSTE DEVOLUÇÃO",
              vendedor: "SISTEMA (REVERSA)",
              mkt: 0, cac: 0, total: 0, frete: 0,
              margemOriginal: 0,
              margemOriginalPct: 0,
              credito: 0, debito: 0,
              margemDeduzidaDevolucao: margemDeduzir,
              margemAjustada: margemDeduzir,
              confirmado: true,
              isDevolvido: true
            };
            newPedidos.push(novoPedidoAjuste);
            addedNewCount++;
            log.push({ mu, valor: valorDevolvido, margem: margemDeduzir, status: 'novo_lancamento' });
          }
        });

        onSetData({ ...data, pedidos: newPedidos });
        setStats({ matched: matchedCount, addedNew: addedNewCount, totalDeduzido: deduzidoSum });
        setProcessedLog(log);
      } catch (err) {
        alert("Erro no processamento de devoluções.");
      } finally {
        setLoading(false);
        event.target.value = "";
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Devoluções</h2>
          <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Logística Reversa e Ajustes de Margem</p>
        </div>
        <label className="flex items-center gap-4 px-10 py-5 bg-amber-600 text-white rounded-2xl cursor-pointer hover:bg-amber-700 transition-all shadow-xl active:scale-95 font-black text-sm uppercase tracking-wider">
          <FileUp className="w-5 h-5" />
          <span>PROCESSAR REVERSAS</span>
          <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleImportDevolvidos} />
        </label>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
         <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl flex items-center justify-between group">
            <div>
               <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Prejuízo de Margem (Estorno)</p>
               <p className="text-3xl font-black text-[#E30613]">{formatCurrency(stats.totalDeduzido)}</p>
            </div>
            <TrendingDown className="w-10 h-10 text-[#E30613]" />
         </div>
         <div className="bg-[#0A1121] rounded-[2.5rem] p-8 text-white shadow-2xl flex items-center justify-between group">
            <div>
               <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Impacto Vendas Anteriores</p>
               <p className="text-3xl font-black">{stats.addedNew} Ajustes</p>
            </div>
            <History className="w-10 h-10 text-emerald-500" />
         </div>
         <div className="bg-amber-50 border border-amber-200 rounded-[2.5rem] p-8 shadow-xl flex items-center justify-between group">
            <div>
               <p className="text-[10px] font-black text-amber-700 uppercase tracking-widest mb-1">Ocorrências Pendentes</p>
               <p className="text-3xl font-black text-amber-900">{ocorrenciasData.length} MU</p>
            </div>
            <AlertOctagon className="w-10 h-10 text-amber-600" />
         </div>
      </div>

      {ocorrenciasData.length > 0 && (
        <div className="bg-amber-50/30 border-2 border-dashed border-amber-200 rounded-[3rem] p-8 animate-in slide-in-from-top-4 duration-500">
           <div className="flex items-center gap-4 mb-6">
              <AlertOctagon className="w-6 h-6 text-amber-600" />
              <h3 className="text-sm font-black text-amber-900 uppercase tracking-widest">Pedidos Marcados na Conferência (Trocas/Devoluções)</h3>
           </div>
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {ocorrenciasData.map(p => (
                <div key={p.id} className="bg-white p-6 rounded-2xl border border-amber-100 shadow-sm flex items-center justify-between group hover:shadow-md transition-all">
                   <div>
                      <p className="text-[10px] font-black text-slate-400 uppercase mb-1">MU: {p.id}</p>
                      <p className="text-sm font-black text-slate-900">{p.vendedor}</p>
                      <p className="text-[9px] font-bold text-amber-600 uppercase mt-1">Margem Original: {formatCurrency(p.margemOriginal)}</p>
                   </div>
                   <div className="text-right">
                      <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Valor Venda</p>
                      <p className="text-sm font-black text-slate-900">{formatCurrency(p.total)}</p>
                   </div>
                </div>
              ))}
           </div>
        </div>
      )}

      <div className="bg-white border border-slate-200 rounded-[3rem] p-10 shadow-xl overflow-hidden">
         <h3 className="text-xs font-black text-slate-900 uppercase tracking-widest mb-8">Auditoria de Estornos de Margem</h3>
         <div className="overflow-x-auto">
           <table className="w-full text-left">
              <thead>
                <tr className="border-b border-slate-100 text-[10px] font-black uppercase text-slate-400">
                  <th className="py-4 px-4">Pedido MU</th>
                  <th className="py-4 px-4">Valor Deduzido</th>
                  <th className="py-4 px-4 text-center">Origem Logística</th>
                </tr>
              </thead>
              <tbody>
                {processedLog.length === 0 ? (
                  <tr><td colSpan={3} className="py-12 text-center text-[10px] font-bold text-slate-300 uppercase italic">Importe os dados para auditar os descontos de margem...</td></tr>
                ) : (
                  processedLog.map((l, i) => (
                    <tr key={i} className="border-b border-slate-50 hover:bg-slate-50 transition-colors">
                      <td className="py-4 px-4 font-black text-xs">{l.mu}</td>
                      <td className="py-4 px-4 font-black text-[#E30613]">{formatCurrency(l.margem)}</td>
                      <td className="py-4 px-4 text-center">
                         <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase ${l.status === 'sucesso' ? 'bg-blue-50 text-blue-600' : 'bg-emerald-50 text-emerald-600'}`}>
                            {l.status === 'sucesso' ? 'Desta Sessão' : 'Período Passado'}
                         </span>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
           </table>
         </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Pedido, SortConfig, SortDirection } from '../types';
import { ChevronUp, ChevronDown, Check, Trash2, AlertTriangle, FileX, History, Share2, AlertOctagon, User, Save, X } from 'lucide-react';

interface OrderTableProps {
  data: Pedido[];
  onUpdatePedido?: (id: string, updates: Partial<Pedido>) => void;
  onDeletePedido?: (id: string) => void;
  readOnly?: boolean;
}

export const OrderTable: React.FC<OrderTableProps> = ({ data, onUpdatePedido, onDeletePedido, readOnly = false }) => {
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'id', direction: 'asc' });
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [editingVendedor, setEditingVendedor] = useState<{id: string, nome: string} | null>(null);

  // Lista única de vendedores para o seletor
  const listaVendedores = useMemo(() => {
    const nomes = new Set(data.map(p => p.vendedor).filter(v => v && v !== "." && v !== "SISTEMA"));
    return Array.from(nomes).sort();
  }, [data]);

  const handleSort = (key: keyof Pedido) => {
    let direction: SortDirection = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const sortedData = useMemo(() => {
    const sortableItems = [...data];
    if (sortConfig.direction !== null) {
      sortableItems.sort((a, b) => {
        const valA = a[sortConfig.key];
        const valB = b[sortConfig.key];
        if (valA === undefined || valA === null) return 1;
        if (valB === undefined || valB === null) return -1;
        if (typeof valA === 'string' && typeof valB === 'string') {
          return sortConfig.direction === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
        }
        if (typeof valA === 'number' && typeof valB === 'number') {
          return sortConfig.direction === 'asc' ? valA - valB : valB - valA;
        }
        return 0;
      });
    }
    return sortableItems;
  }, [data, sortConfig]);

  const totals = useMemo(() => {
    return data.reduce(
      (acc, curr) => {
        const valorFaturamento = curr.isOcorrencia ? 0 : (curr.total || 0);
        return {
          total: acc.total + valorFaturamento,
          margemOriginal: acc.margemOriginal + (curr.margemOriginal || 0),
          margemAjustada: acc.margemAjustada + (curr.margemAjustada || 0),
        };
      },
      { total: 0, margemOriginal: 0, margemAjustada: 0 }
    );
  }, [data]);

  const formatCurrency = (value: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  const formatPercent = (value: number) => new Intl.NumberFormat('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(value) + '%';

  const getMargemColor = (pct: number) => {
    if (pct <= 8.00) return 'text-[#E30613]';
    if (pct <= 10.00) return 'text-amber-500';
    return 'text-emerald-600';
  };

  const SortIcon = ({ column }: { column: keyof Pedido }) => {
    if (sortConfig.key !== column) return <ChevronDown className="w-3 h-3 text-slate-300 opacity-30" />;
    return sortConfig.direction === 'asc' ? <ChevronUp className="w-3 h-3 text-[#E30613]" /> : <ChevronDown className="w-3 h-3 text-[#E30613]" />;
  };

  return (
    <>
      {confirmDeleteId && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-950/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white rounded-[2.5rem] shadow-2xl max-w-md w-full p-10 space-y-8 border border-slate-200">
            <div className="flex flex-col items-center text-center space-y-4">
              <AlertTriangle className="w-10 h-10 text-[#E30613]" />
              <h3 className="text-2xl font-black text-slate-900 uppercase">Excluir Registro?</h3>
              <p className="text-slate-500 text-sm">Remover permanentemente <span className="font-black">MU {confirmDeleteId}</span>?</p>
