              margemDeduzidaDevolucao: margemDeduzir, margemAjustada: margemDeduzir, confirmado: true, isDevolvido: true
            };
            newPedidos.push(novoPedidoAjuste);
            log.push({ mu, valor: valorDevolvido, margem: margemDeduzir, status: 'REVERSA_ANT' });
          }
        });

        onSetData({ ...data, pedidos: newPedidos });
        setProcessedLog(prev => [...prev, ...log]);
      } catch (err) {
        alert("Erro no processamento.");
      } finally {
        setLoading(false);
        event.target.value = "";
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const formatCurrency = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Devoluções</h2>
          <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Logística Reversa — Conciliação de Ocorrências</p>
        </div>
        <div className="flex gap-4">
          <button onClick={() => setProcessedLog([])} className="px-6 py-5 bg-slate-100 text-slate-400 rounded-2xl font-black text-xs uppercase hover:bg-red-50 hover:text-red-500 transition-all">LIMPAR LOG</button>
          <label className="flex items-center gap-4 px-10 py-5 bg-amber-600 text-white rounded-2xl cursor-pointer hover:bg-amber-700 transition-all shadow-xl active:scale-95 font-black text-sm uppercase tracking-wider">
