import React, { useMemo, useState } from 'react';
import { MesConferencia, Pedido } from '../types';
import { OrderTable } from '../components/OrderTable';
import { CheckCircle2, Info, Banknote, TrendingUp, FileDown, FileX, PackageOpen, PlusSquare, ArrowRight, History, Settings2 } from 'lucide-react';
import * as XLSX from 'xlsx';

interface AjustesFinaisPageProps {
  data: MesConferencia | null;
  onUpdatePedido: (id: string, updates: Partial<Pedido>) => void;
  onDeletePedido: (id: string) => void;
  onCloseMonth: (consolidatedData: MesConferencia) => void;
}

export const AjustesFinaisPage: React.FC<AjustesFinaisPageProps> = ({ data, onUpdatePedido, onDeletePedido, onCloseMonth }) => {
  const [showConfirmModal, setShowConfirmModal] = useState(false);

  const handleConfirm = () => {
    if (!data) return;
    onCloseMonth(data);
    setShowConfirmModal(false);
  };

  const handleExportExcel = () => {
    if (!data || data.pedidos.length === 0) return;
    const exportData = data.pedidos.map(p => ({
      "Nº Pedido MU": p.id,
      "Data Faturamento": p.data,
      "Canal Venda": p.canal,
      "Vendedor": p.vendedor,
      "Total Faturado (R$)": p.total,
      "Margem Original (R$)": p.margemOriginal,
      "Ajustes Manuais (R$)": (p.credito || 0) - (p.debito || 0),
      "Impacto Cancelamento (R$)": p.margemDeduzidaCancelamento || 0,
      "Impacto Devolução (R$)": p.margemDeduzidaDevolucao || 0,
      "Margem Final Auditada (R$)": p.margemAjustada,
      "Rentabilidade (%)": (p.total > 0 ? (p.margemAjustada / p.total) * 100 : 0).toFixed(2) + "%"
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Resultado Auditado");
    XLSX.writeFile(workbook, `ABC_Auditoria_Final_${data.mesReferencia}.xlsx`);
  };

  const summary = useMemo(() => {
    if (!data || data.pedidos.length === 0) return { total: 0, margemOriginal: 0, deducaoCancelados: 0, deducaoDevolvidos: 0, impactoRetroativo: 0, ajustesManuais: 0, margemFinal: 0, pct: 0 };
    const total = data.pedidos.reduce((acc, curr) => acc + (curr.isOcorrencia ? 0 : curr.total), 0);
    const margemOriginal = data.pedidos.reduce((acc, curr) => acc + curr.margemOriginal, 0);
    const deducaoCancelados = data.pedidos.reduce((acc, curr) => acc + (curr.margemDeduzidaCancelamento || 0), 0);
    const deducaoDevolvidos = data.pedidos.reduce((acc, curr) => acc + (curr.margemDeduzidaDevolucao || 0), 0);
    const ajustesManuais = data.pedidos.reduce((acc, curr) => acc + (curr.credito - curr.debito), 0);
    const margemFinal = data.pedidos.reduce((acc, curr) => acc + curr.margemAjustada, 0);
    const impactoRetroativo = data.pedidos.filter(p => p.data === "Mês Anterior").reduce((acc, curr) => acc + curr.margemAjustada, 0);
    const pct = total > 0 ? (margemFinal / total) * 100 : 0;
    return { total, margemOriginal, deducaoCancelados, deducaoDevolvidos, impactoRetroativo, ajustesManuais, margemFinal, pct };
  }, [data]);

  const formatCurrency = (value: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);

  if (!data) return (
    <div className="bg-slate-50 border border-slate-200 rounded-[3rem] p-24 text-center">
      <Info className="w-16 h-16 text-slate-300 mx-auto mb-4" />
      <h3 className="text-3xl font-black text-slate-900 tracking-tighter uppercase">Auditagem Pendente</h3>
      <p className="text-slate-400 font-bold max-w-md mx-auto mt-2">Importe as planilhas de vendas para processar a validação final.</p>
    </div>
  );

  return (
    <div className="space-y-12">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-8 pb-4">
        <div className="flex items-center gap-6">
          <div className="bg-[#E30613] p-5 rounded-3xl shadow-2xl shadow-red-100"><Settings2 className="w-8 h-8 text-white"/></div>
          <div>
            <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Validação Final</h2>
            <p className="text-[#E30613] font-bold mt-1 uppercase text-[11px] tracking-[0.3em]">Consolidação Auditada — {data.mesReferencia}</p>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <button onClick={handleExportExcel} className="flex items-center gap-4 px-8 py-5 bg-white border-2 border-slate-200 hover:border-[#E30613] text-slate-600 rounded-2xl shadow-xl transition-all font-black text-sm uppercase"><FileDown className="w-5 h-5" /> EXPORTAR EXCEL</button>
          <button onClick={() => setShowConfirmModal(true)} className="flex items-center gap-4 px-12 py-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl shadow-2xl transition-all font-black text-sm uppercase"><CheckCircle2 className="w-5 h-5" /> FECHAR MÊS</button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-5 gap-6">
         <div className="bg-[#0A1121] rounded-[2.5rem] p-8 text-white shadow-2xl col-span-2">
            <span className="text-[9px] font-black uppercase tracking-widest text-slate-500">Resultado Final Líquido</span>
            <p className="text-5xl font-black tracking-tighter mt-1">{formatCurrency(summary.margemFinal)}</p>
            <div className="flex gap-4 mt-4">
               <div className="bg-white/5 px-4 py-2 rounded-xl border border-white/10">
                  <p className="text-[8px] font-black text-slate-500 uppercase">Rentabilidade</p>
                  <p className="text-xl font-black text-emerald-400">{summary.pct.toFixed(2)}%</p>
               </div>
               <div className="bg-white/5 px-4 py-2 rounded-xl border border-white/10">
                  <p className="text-[8px] font-black text-slate-500 uppercase">Faturamento Base</p>
                  <p className="text-xl font-black text-slate-300">{formatCurrency(summary.total)}</p>
               </div>
            </div>
         </div>
         <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
            <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">Cancelamentos</span>
            <p className="text-3xl font-black text-red-600 mt-1">{formatCurrency(summary.deducaoCancelados)}</p>
         </div>
         <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
            <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">Devoluções/Trocas</span>
            <p className="text-3xl font-black text-amber-600 mt-1">{formatCurrency(summary.deducaoDevolvidos)}</p>
         </div>
         <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl">
            <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">Ajustes Manuais</span>
            <p className={`text-3xl font-black mt-1 ${summary.ajustesManuais >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>{formatCurrency(summary.ajustesManuais)}</p>
         </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-[3rem] p-2 shadow-xl overflow-hidden">
        <OrderTable data={data.pedidos} onUpdatePedido={onUpdatePedido} onDeletePedido={onDeletePedido} />
      </div>

      {showConfirmModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white rounded-[3rem] shadow-2xl max-w-md w-full p-12 space-y-8 border border-slate-100">
            <div className="text-center space-y-4">
               <div className="w-20 h-20 bg-emerald-50 rounded-full flex items-center justify-center mx-auto"><CheckCircle2 className="w-10 h-10 text-emerald-600" /></div>
               <h3 className="text-3xl font-black text-slate-900 uppercase tracking-tighter">Consolidar Mês?</h3>
               <p className="text-slate-500 text-sm font-medium">Os ajustes retroativos e seleções de vendedores serão salvos no banco de dados histórico.</p>
            </div>
            <div className="flex flex-col gap-3">
               <button onClick={handleConfirm} className="w-full py-5 bg-emerald-600 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-100">GRAVAR DADOS FINAIS</button>
               <button onClick={() => setShowConfirmModal(false)} className="w-full py-5 bg-slate-100 text-slate-400 rounded-2xl font-black uppercase tracking-widest hover:bg-slate-200 transition-all">VOLTAR</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Sidebar } from './components/Sidebar';
import { ConferenciaPage } from './pages/ConferenciaPage';
import { CanceladosPage } from './pages/CanceladosPage';
import { DevolvidosPage } from './pages/DevolvidosPage';
import { AjustesVariosPage } from './pages/AjustesVariosPage';
import { AjustesFinaisPage } from './pages/AjustesFinaisPage';
import { DashboardPage } from './pages/DashboardPage';
import { AnaliseVendedorPage } from './pages/AnaliseVendedorPage';
import { ConfiguracaoPage } from './pages/ConfiguracaoPage';
import { ContasPagarPage } from './pages/ContasPagarPage';
import { FluxoCaixaPage } from './pages/FluxoCaixaPage';
import { DREPage } from './pages/DREPage';
import { ComissaoPage } from './pages/ComissaoPage';
import { FretePage } from './pages/FretePage';
import { HorasPage } from './pages/HorasPage';
import { PageId, MesConferencia, Pedido, HistoricoConsolidado } from './types';
import { Sparkles } from 'lucide-react';
import { storageService } from './services/storageService';

const App: React.FC = () => {
  const [activePage, setActivePage] = useState<PageId>('dashboard');
  const [data, setData] = useState<MesConferencia | null>(storageService.getData());
  const [history, setHistory] = useState<HistoricoConsolidado>(storageService.getHistory());
  const [showToast, setShowToast] = useState<{show: boolean, msg: string, type: 'success' | 'danger'}>({show: false, msg: '', type: 'success'});

  const calculateMargemFinal = (p: Pedido): number => {
    return p.margemOriginal + 
           (p.credito || 0) - 
           (p.debito || 0) + 
           (p.margemDeduzidaCancelamento || 0) + 
           (p.margemDeduzidaDevolucao || 0);
  };

  const handleUpdatePedido = useCallback((id: string, updates: Partial<Pedido>) => {
    setData(current => {
      if (!current) return null;
      const newPedidos = current.pedidos.map((p) => {
        if (p.id === id) {
          const updated = { ...p, ...updates };
          updated.margemAjustada = calculateMargemFinal(updated);
          return updated;
        }
        return p;
      });
      const updatedData = { ...current, pedidos: newPedidos };
      storageService.saveData(updatedData);
      return updatedData;
    });
  }, []);

  const handleSetData = (newData: MesConferencia | null, multiMonthData?: Record<string, Pedido[]>) => {
    if (multiMonthData) {
      Object.keys(multiMonthData).forEach(mesRef => {
        const pedidosMes = multiMonthData[mesRef].map(p => ({
          ...p,
          margemAjustada: calculateMargemFinal(p)
        }));
        storageService.saveToHistory({ mesReferencia: mesRef, pedidos: pedidosMes, ajustesExtras: [] });
      });
      setHistory(storageService.getHistory());
      setShowToast({show: true, msg: 'Dados processados por competência!', type: 'success'});
      setTimeout(() => setShowToast({show: false, msg: '', type: 'success'}), 4000);
      if (newData) { setData(newData); storageService.saveData(newData); }
    } else if (newData) {
      newData.pedidos = newData.pedidos.map(p => ({ ...p, margemAjustada: calculateMargemFinal(p) }));
      storageService.saveData(newData);
      setData(newData);
    } else {
      storageService.clearData();
      setData(null);
    }
  };

  const handleCloseMonth = (consolidated: MesConferencia) => {
    storageService.saveToHistory(consolidated);
    storageService.clearData();
    localStorage.removeItem('abc_cancelados_log');
    localStorage.removeItem('abc_devolvidos_log');
    setData(null);
    setHistory(storageService.getHistory());
    setActivePage('dashboard');
    setShowToast({show: true, msg: 'Mês fechado com sucesso!', type: 'success'});
    setTimeout(() => setShowToast({show: false, msg: '', type: 'success'}), 4000);
  };

  const handleDeletePedido = (id: string) => {
    setData(current => {
      if (!current) return null;
      const newPedidos = current.pedidos.filter(p => p.id !== id);
      const updatedData = { ...current, pedidos: newPedidos };
      storageService.saveData(updatedData);
      return updatedData;
    });
  };

  const handleClearDatabase = () => {
    storageService.clearAll();
    localStorage.removeItem('abc_cancelados_log');
    localStorage.removeItem('abc_devolvidos_log');
    setData(null);
    setHistory({ meses: [] });
    setActivePage('dashboard');
    setShowToast({show: true, msg: 'Banco de dados resetado!', type: 'danger'});
    setTimeout(() => setShowToast({show: false, msg: '', type: 'success'}), 4000);
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex selection:bg-red-100 selection:text-red-900 antialiased">
      <Sidebar activePage={activePage} setActivePage={setActivePage} />
      <main className="flex-grow flex flex-col min-w-0">
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-40 flex items-center justify-between px-12">
          <div className="flex items-center gap-3">
            <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">ABC ITU — Gestão de Resultados</p>
          </div>
          <div className="flex items-center gap-2 px-4 py-2 bg-slate-50 rounded-full border border-slate-100">
            <span className="text-[10px] font-black text-slate-500 uppercase">{history.meses.length} Meses Históricos</span>
          </div>
        </header>

        {showToast.show && (
          <div className="fixed top-24 right-12 z-[250] animate-in slide-in-from-right-8 fade-in duration-500">
            <div className={`${showToast.type === 'success' ? 'bg-emerald-600' : 'bg-[#E30613]'} text-white px-8 py-5 rounded-3xl shadow-2xl flex items-center gap-4`}>
               <Sparkles className="w-5 h-5" />
               <p className="text-[10px] font-black uppercase">{showToast.msg}</p>
            </div>
          </div>
        )}

        <div className="p-8 lg:p-12">
          <div className="bg-white p-10 rounded-[4rem] shadow-xl border border-slate-200/50 min-h-[75vh]">
            {activePage === 'dashboard' && <DashboardPage history={history} />}
            {activePage === 'conferencia' && <ConferenciaPage data={data} onSetData={handleSetData} onUpdatePedido={handleUpdatePedido} onDeletePedido={handleDeletePedido} onNavigateToAjustes={() => setActivePage('ajustes')} />}
            {activePage === 'cancelados' && <CanceladosPage data={data} onSetData={handleSetData} />}
            {activePage === 'devolvidos' && <DevolvidosPage data={data} onSetData={handleSetData} />}
            {activePage === 'ajustes-varios' && <AjustesVariosPage data={data} onSetData={handleSetData} />}
            {activePage === 'ajustes' && <AjustesFinaisPage data={data} onUpdatePedido={handleUpdatePedido} onDeletePedido={handleDeletePedido} onCloseMonth={handleCloseMonth} />}
            {activePage === 'analise-vendedor' && <AnaliseVendedorPage history={history} />}
            {activePage === 'contas-pagar' && <ContasPagarPage />}
            {activePage === 'fluxo-caixa' && <FluxoCaixaPage />}
            {activePage === 'dre' && <DREPage />}
            {activePage === 'comissao' && <ComissaoPage history={history} />}
            {activePage === 'frete' && <FretePage />}
            {activePage === 'horas' && <HorasPage />}
            {activePage === 'configuracao' && <ConfiguracaoPage onClearDatabase={handleClearDatabase} />}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

