          <div>
            <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Validação Final</h2>
            <p className="text-[#E30613] font-bold mt-1 uppercase text-[11px] tracking-[0.3em]">Consolidação Auditada — {data.mesReferencia}</p>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <button onClick={handleExportExcel} className="flex items-center gap-4 px-8 py-5 bg-white border-2 border-slate-200 hover:border-[#E30613] text-slate-600 rounded-2xl shadow-xl transition-all font-black text-sm uppercase"><FileDown className="w-5 h-5" /> EXPORTAR EXCEL</button>
          <button onClick={() => setShowConfirmModal(true)} className="flex items-center gap-4 px-12 py-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl shadow-2xl transition-all font-black text-sm uppercase"><CheckCircle2 className="w-5 h-5" /> FECHAR MÊS</button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
         <div className="bg-[#0A1121] rounded-[2.5rem] p-8 text-white shadow-2xl col-span-1">
            <span className="text-[9px] font-black uppercase tracking-widest text-slate-500">Resultado Final Líquido</span>
            <p className="text-4xl font-black tracking-tighter mt-1">{formatCurrency(summary.margemFinal)}</p>
