  const calculatePedidoComissao = (p: Pedido) => {
    // Base de cálculo é apenas o produto (Total - Frete)
    const valorLiquido = Math.max(0, p.total - (p.frete || 0));

    // A margem para definir a faixa considera o frete (Margem Ajustada / Total Bruto)
    const margemPct = p.total > 0 ? (p.margemAjustada / p.total) * 100 : 0;

    let taxa = 0;

    // Novas Regras:
    // 1. Margem > 10% paga 1,5%
    if (margemPct > 10) {
      taxa = 0.015;
    } 
    // 2. Margem entre 7,99% e 9,99% paga 1,0%
    else if (margemPct >= 7.99) {
      taxa = 0.01;
    }
    // 3. Abaixo de 7,99% paga 0%
    else {
      taxa = 0;
    }

    return {
      valorLiquido,
      taxa,
      comissao: valorLiquido * taxa,
      margemPct
    };
  };

  const report = useMemo(() => {
    const mesData = history.meses.find(m => m.mesReferencia === selectedMonth);
    const pedidos = mesData?.pedidos || [];

    const vendedores: Record<string, { 
      nome: string; 
      faturamentoBruto: number; 
      faturamentoSemFrete: number;
      freteTotal: number;
      comissaoTotal: number;
      pedidosCount: number;
      pedidos: any[];
    }> = {};

    pedidos.forEach(p => {
      // Ignora pedidos marcados como ocorrência no faturamento de comissão
      if (p.isOcorrencia) return;

      if (!vendedores[p.vendedor]) {
        vendedores[p.vendedor] = { 
          nome: p.vendedor, 
          faturamentoBruto: 0, 
          faturamentoSemFrete: 0,
          freteTotal: 0,
          comissaoTotal: 0, 
          pedidosCount: 0,
          pedidos: []
        };
      }

      const calc = calculatePedidoComissao(p);

      vendedores[p.vendedor].faturamentoBruto += p.total;
      vendedores[p.vendedor].faturamentoSemFrete += calc.valorLiquido;
      vendedores[p.vendedor].freteTotal += (p.frete || 0);
      vendedores[p.vendedor].comissaoTotal += calc.comissao;
      vendedores[p.vendedor].pedidosCount++;
      vendedores[p.vendedor].pedidos.push({ ...p, ...calc });
    });

    const totalMes = Object.values(vendedores).reduce((acc, v) => acc + v.comissaoTotal, 0);

