      <div className="grid grid-cols-1 lg:grid-cols-4 gap-10">
        <div className="lg:col-span-1 space-y-4">
           <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-2xl h-fit">
              <div className="flex items-center justify-between mb-6">
                 <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Configuração de Equipe</h3>
                 <button 
                  onClick={() => setIsConfigMode(!isConfigMode)}
                  className={`p-2 rounded-lg transition-all ${isConfigMode ? 'bg-[#E30613] text-white' : 'bg-slate-100 text-slate-400 hover:text-slate-900'}`}
                  title="Gerenciar Colaboradores"
                 >
                    <Settings2 className="w-4 h-4" />
                 </button>
