                                        <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{dt.toLocaleDateString('pt-BR', { weekday: 'short' })}</span>
                                     </div>
                                  </td>
                                  <td className="px-8 py-5">
                                     <div className="flex flex-wrap gap-2 items-center">
                                        {diaPonto?.batidas.map((b, i) => (
                                          <div key={i} className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border text-[11px] font-black shadow-sm group/batida ${b.origem === 'AJUSTE' ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-white border-slate-200 text-slate-700'}`}>
                                            {b.hora}
                                            {b.origem === 'AJUSTE' && (
                                              <div className="relative">
                                                <Info className="w-3 h-3 text-amber-400 cursor-help" />
                                                <div className="absolute bottom-full mb-2 left-1/2 -translate-x-1/2 w-48 p-3 bg-slate-900 text-white text-[9px] rounded-xl opacity-0 group-hover/batida:opacity-100 pointer-events-none transition-opacity z-50 shadow-2xl">
