               <p className="text-2xl font-black text-slate-800 tracking-tight uppercase">Gestão de Auditoria REP</p>
               <p className="text-sm font-medium text-slate-400 mt-2 italic">Selecione um colaborador na lateral para iniciar a auditoria do ponto</p>
             </div>
           )}
        </div>
      </div>

      {/* MODAL DE AJUSTE AUDITADO */}
      {modalAjuste && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-md">
           <div className="bg-white rounded-[3rem] shadow-2xl max-w-lg w-full p-12 space-y-8 animate-in zoom-in-95 duration-300 border border-slate-200">
