                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Motivo / Justificativa Legal</label>
                    <textarea 
                      placeholder="Ex: Colaborador esqueceu de registrar o ponto, Trabalho externo, Falha técnica no relógio iDClass..."
                      value={motivoAjuste}
                      onChange={(e) => setMotivoAjuste(e.target.value)}
                      className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-slate-700 min-h-[120px] outline-none focus:ring-4 focus:ring-red-500/10"
