import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, UserCheck, Calendar, FileText, Trash2, 
  CheckCircle2, AlertTriangle, Edit3, X, History, Users, 
  Search, LayoutDashboard, ShieldCheck, TrendingUp, AlertCircle, Save,
  Plus, UserMinus, Filter, Info, Eye, EyeOff, Settings2, Building2, Briefcase
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, MarcacaoPonto, ControleHoras, LogAuditoriaPonto, RegistroBatida } from '../types';

type StatusFilter = 'ativos' | 'inativos' | 'todos';

export const HorasPage: React.FC = () => {
  const [data, setData] = useState<ControleHoras>(() => {
    const saved = localStorage.getItem('abc_ponto_v9_final');
    return saved ? JSON.parse(saved) : { funcionarios: [], pontos: {}, logs: [] };
  });

  const [statusFilter, setStatusFilter] = useState<StatusFilter>('ativos');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePis, setActivePis] = useState<string | null>(null);
  const [isConfigMode, setIsConfigMode] = useState(false);
  const [isEditingFunc, setIsEditingFunc] = useState(false);

  const [modalAjuste, setModalAjuste] = useState<{pis: string, date: string, hora: string} | null>(null);
  const [motivoAjuste, setMotivoAjuste] = useState('');

  useEffect(() => {
    localStorage.setItem('abc_ponto_v9_final', JSON.stringify(data));
  }, [data]);

  // --- UTILS ---
  const cleanPIS = (pis: string) => pis.replace(/\D/g, '').padStart(12, '0');

  const timeToMinutes = (time: string): number => {
    if (!time || !time.includes(':')) return 0;
    const [h, m] = time.split(':').map(Number);
    return (h * 60) + m;
  };

  const minutesToTime = (mins: number): string => {
    const h = Math.floor(Math.abs(mins) / 60);
    const m = Math.abs(mins) % 60;
    const sign = mins < 0 ? '-' : '';
    return `${sign}${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  // --- PARSER AFD iDClass com Deduplicação ---
  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split('\n');
      const newFuncs = [...data.funcionarios];
      const newPontos = { ...data.pontos };

      lines.forEach(line => {
        if (line.length < 30) return;
        const tipo = line.substring(9, 10);

        if (tipo === '5') {
          const rawPis = line.substring(22, 34);
          const pis = cleanPIS(rawPis);
          const nomeRaw = line.substring(34, 86).trim();
          const nomeLimpo = nomeRaw.replace(/^\d+/, '').trim();

          if (pis && pis !== "000000000000" && !newFuncs.find(f => cleanPIS(f.pis) === pis)) {
            newFuncs.push({ pis, nome: nomeLimpo, ativo: true, jornadaDiariaMinutos: 480, setor: 'Geral' });
          }
        } 
        else if (tipo === '3') {
          const dia = line.substring(10, 12), mes = line.substring(12, 14), ano = line.substring(14, 18);
          const hora = line.substring(18, 20), min = line.substring(20, 22);
          const rawPis = line.substring(22, 34);
          const pis = cleanPIS(rawPis);
          const dateKey = `${ano}-${mes}-${dia}`;
          const time = `${hora}:${min}`;

          if (pis && pis !== "000000000000") {
            if (!newPontos[pis]) newPontos[pis] = [];
            let diaPonto = newPontos[pis].find(p => p.data === dateKey);
            if (!diaPonto) {
              diaPonto = { data: dateKey, batidas: [], isFalta: false };
              newPontos[pis].push(diaPonto);
            }
            // Evita duplicados comparando hora
            if (!diaPonto.batidas.find(b => b.hora === time)) {
              diaPonto.batidas.push({ hora: time, origem: 'AFD' });
              diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
            }
          }
        }
      });

      setData(prev => ({ ...prev, funcionarios: newFuncs, pontos: newPontos }));
    };
    event.target.value = '';
  };

  const filteredFuncs = useMemo(() => {
    return data.funcionarios.filter(f => {
      const matchesStatus = statusFilter === 'todos' ? true : (statusFilter === 'ativos' ? f.ativo : !f.ativo);
      const matchesSearch = f.nome.toLowerCase().includes(searchTerm.toLowerCase()) || f.pis.includes(searchTerm);
      return matchesStatus && matchesSearch;
    }).sort((a, b) => a.nome.localeCompare(b.nome));
  }, [data.funcionarios, statusFilter, searchTerm]);

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: lastDay }, (_, i) => `${year}-${month}-${(i + 1).toString().padStart(2, '0')}`);
  }, [selectedMonth]);

  const activeEmployee = useMemo(() => data.funcionarios.find(f => f.pis === activePis), [data.funcionarios, activePis]);

  const calculateDay = (batidas: RegistroBatida[], jornadaNominal: number = 480) => {
    if (!batidas || batidas.length < 2) return { trabalhadas: 0, extras: 0, atraso: 0 };
    let totalMinutes = 0;
    const sorted = [...batidas].sort((a, b) => a.hora.localeCompare(b.hora));
    for (let i = 0; i < sorted.length - 1; i += 2) {
      const inMin = timeToMinutes(sorted[i].hora);
      const outMin = timeToMinutes(sorted[i+1].hora);
      if (outMin > inMin) totalMinutes += (outMin - inMin);
    }
    const diff = totalMinutes - jornadaNominal;
    return { trabalhadas: totalMinutes, extras: diff > 0 ? diff : 0, atraso: diff < 0 ? Math.abs(diff) : 0 };
  };

  const handleUpdateFuncData = (pis: string, updates: Partial<Funcionario>) => {
    setData(prev => ({
      ...prev,
      funcionarios: prev.funcionarios.map(f => f.pis === pis ? { ...f, ...updates } : f)
    }));
  };

  // --- FIX: Added handleSaveAjuste to manage manual clock-in edits ---
  const handleSaveAjuste = () => {
    if (!modalAjuste || !motivoAjuste) return;

    const { pis, date, hora } = modalAjuste;
    const newPontos = { ...data.pontos };

    if (!newPontos[pis]) newPontos[pis] = [];

    let diaPonto = newPontos[pis].find(p => p.data === date);
    if (!diaPonto) {
      diaPonto = { data: date, batidas: [], isFalta: false };
      newPontos[pis].push(diaPonto);
    }

    // Add manual entry
    diaPonto.batidas.push({
      hora,
      origem: 'AJUSTE',
      obs: motivoAjuste
    });
    diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
    diaPonto.isFalta = false;

    // Log the change
    const newLog: LogAuditoriaPonto = {
      id: crypto.randomUUID(),
      timestamp: new Date().toISOString(),
      usuario: 'Administrador',
      pis,
      dataPonto: date,
      tipo: 'inclusao',
      valorNovo: hora,
      motivo: motivoAjuste
    };

    setData(prev => ({
      ...prev,
      pontos: newPontos,
      logs: [newLog, ...prev.logs]
    }));

    setModalAjuste(null);
    setMotivoAjuste('');
  };

  const handleExportPDF = () => {
    if (!activeEmployee) return;
    const doc = new jsPDF();

    // Header Profissional
    doc.setFillColor(227, 6, 19); // Vermelho ABC
    doc.rect(0, 0, 210, 40, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.setFont("helvetica", "bold");
    doc.text("ESPELHO DE PONTO", 14, 25);
    doc.setFontSize(10);
    doc.text("ABC DA CONSTRUÇÃO ITU - ITU-SP", 14, 32);

    doc.setTextColor(0, 0, 0);
    doc.setFontSize(10);
    doc.text(`Colaborador: ${activeEmployee.nome.toUpperCase()}`, 14, 50);
    doc.text(`PIS: ${activeEmployee.pis} | Setor: ${activeEmployee.setor || 'Geral'}`, 14, 55);
    doc.text(`Período de Referência: ${selectedMonth.split('-').reverse().join('/')}`, 14, 60);
    doc.text(`Jornada Diária: ${minutesToTime(activeEmployee.jornadaDiariaMinutos)}`, 14, 65);

    const tableData = currentMonthDays.map(day => {
      const p = data.pontos[activeEmployee.pis]?.find(x => x.data === day);
      const c = calculateDay(p?.batidas || [], activeEmployee.jornadaDiariaMinutos);
      return [
        day.split('-').reverse().join('/'),
        p?.batidas.map(b => b.hora).join('  ') || (p?.isFalta ? 'FALTA' : '---'),
        c.trabalhadas > 0 ? minutesToTime(c.trabalhadas) : '00:00',
        c.extras > 0 ? minutesToTime(c.extras) : '00:00',
        c.atraso > 0 ? minutesToTime(c.atraso) : '00:00'
      ];
    });

    (doc as any).autoTable({
      head: [['DATA', 'MARCAÇÕES', 'TRABALHADO', 'EXTRAS', 'ATRASOS']],
      body: tableData,
      startY: 75,
      theme: 'striped',
      headStyles: { fillColor: [40, 40, 40], textColor: 255, fontStyle: 'bold' },
      styles: { fontSize: 8, cellPadding: 3 },
      columnStyles: { 1: { cellWidth: 80 } }
    });

    doc.save(`Ponto_ABC_${activeEmployee.nome}_${selectedMonth}.pdf`);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* HEADER PRINCIPAL */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 pb-8 border-b border-slate-100">
        <div className="flex items-center gap-4">
           <div className="bg-[#E30613] p-4 rounded-3xl shadow-2xl shadow-red-100">
              <ShieldCheck className="w-8 h-8 text-white" />
           </div>
           <div>
              <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase leading-none">Gestão de REP</h2>
              <p className="text-slate-400 font-bold uppercase text-[9px] tracking-[0.3em] mt-2">Compliance Portaria 671 — ABC Itu</p>
           </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="bg-[#0A1121] rounded-2xl p-4 text-white flex items-center gap-4 border border-slate-800 shadow-xl relative group">
            <Calendar className="w-5 h-5 text-[#E30613]" />
            <div className="flex flex-col min-w-[140px]">
               <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Referência Ativa</span>
               <input 
                 type="month" 
                 value={selectedMonth} 
                 onChange={(e) => setSelectedMonth(e.target.value)} 
                 className="bg-transparent text-[11px] font-black uppercase outline-none cursor-pointer appearance-none hover:text-[#E30613] transition-colors" 
               />
            </div>
          </div>
          <label className="flex items-center gap-4 px-8 py-4 bg-white border-2 border-slate-200 text-slate-900 rounded-2xl cursor-pointer hover:border-[#E30613] transition-all font-black text-xs uppercase tracking-widest shadow-sm">
            <FileUp className="w-5 h-5 text-[#E30613]" />
            IMPORTAR AFD
            <input type="file" className="hidden" accept=".txt" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* LISTA DE FUNCIONÁRIOS */}
        <div className="lg:col-span-1 space-y-4">
           <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-xl h-fit">
              <div className="flex items-center justify-between mb-6 px-2">
                 <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Colaboradores</h3>
