                              const dt = new Date(day + 'T00:00:00');
                              const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                              return (
                                 <tr key={day} className={`group hover:bg-slate-50 transition-all ${isWeekend ? 'bg-slate-50/40' : ''} ${diaPonto?.isFalta ? 'bg-red-50/30' : ''}`}>
                                    <td className="px-8 py-5">
                                       <div className="flex flex-col">
                                          <span className={`text-xl font-black leading-none ${isWeekend ? 'text-slate-300' : 'text-slate-900'}`}>{day.split('-')[2]}</span>
                                          <span className="text-[9px] font-black text-slate-400 uppercase">{dt.toLocaleDateString('pt-BR', { weekday: 'short' })}</span>
