                                                  <Info className="w-3 h-3 text-amber-400 cursor-help" />
                                                  <div className="absolute bottom-full mb-3 left-1/2 -translate-x-1/2 w-64 p-4 bg-slate-900 text-white text-[10px] rounded-2xl opacity-0 group-hover/obs:opacity-100 pointer-events-none transition-all z-50 shadow-2xl border border-slate-700">
