                                    </td>
                                    <td className={`px-8 py-5 text-right font-black text-xs ${calc.extras > 0 ? 'text-emerald-600' : calc.atraso > 0 ? 'text-[#E30613]' : 'text-slate-300'}`}>
                                      {calc.extras > 0 ? `+${minutesToTime(calc.extras)}` : calc.atraso > 0 ? `-${minutesToTime(calc.atraso)}` : '00:00'}
                                    </td>
                                    <td className="px-8 py-5 text-center">
                                       <button 
