                                              newPts[activePis!].push(dp);
                                            }
                                            dp.isFalta = !dp.isFalta;
                                            if (dp.isFalta) dp.batidas = [];
                                            setData(prev => ({ ...prev, pontos: newPts }));
                                         }}
                                         className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${diaPonto?.isFalta ? 'bg-[#E30613] text-white shadow-lg' : 'bg-slate-100 text-slate-400 hover:bg-red-50 hover:text-[#E30613]'}`}
                                       >
                                         {diaPonto?.isFalta ? 'FALTA LANÇADA' : 'LANÇAR FALTA'}
                                       </button>
