           ) : (
             <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-[4rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-sm">
               <div className="bg-white p-8 rounded-full mb-8 shadow-xl">
