} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, MarcacaoPonto, ControleHoras, LogAuditoriaPonto, RegistroBatida } from '../types';

type StatusFilter = 'ativos' | 'inativos' | 'todos';

// Complementando a interface de Funcionário localmente para o Espelho
interface FuncionarioCompleto extends Funcionario {
  cpf?: string;
  matricula?: string;
  admissao?: string;
  cargo?: string;
  centroCusto?: string;
  departamento?: string;
}

// FIX: Added missing calculateDay function to resolve ReferenceErrors
const calculateDay = (batidas: RegistroBatida[], jornadaMinutos: number) => {
  let trabalhadas = 0;
  // Assumes sequential pairs of punches: In-Out, In-Out
  for (let i = 0; i < batidas.length; i += 2) {
    if (batidas[i] && batidas[i + 1]) {
      const start = timeToMinutes(batidas[i].hora);
      const end = timeToMinutes(batidas[i + 1].hora);
      trabalhadas += Math.max(0, end - start);
    }
  }

  const saldo = trabalhadas - jornadaMinutos;
  return { trabalhadas, saldo };
};

const timeToMinutes = (time: string): number => {
  if (!time || !time.includes(':')) return 0;
  const [h, m] = time.split(':').map(Number);
  return (h * 60) + m;
};

const minutesToTime = (mins: number): string => {
  const h = Math.floor(Math.abs(mins) / 60);
  const m = Math.abs(mins) % 60;
  return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
};

