    localStorage.setItem('abc_ponto_v11_final', JSON.stringify(data));
  }, [data]);

  const cleanPIS = (pis: string) => {
    const numbers = pis.replace(/\D/g, '');
    return numbers.slice(-12).padStart(12, '0');
  };

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/);
      const newFuncs = [...data.funcionarios];
      const newPontos = { ...data.pontos };

      lines.forEach(line => {
        // Tipo 5: Cadastro de Funcionário
        if (line.includes('000000000') && line.length > 50 && (line.slice(9, 10) === '5' || line.includes(' 5 '))) {
          const pisMatch = line.match(/\d{11,12}/);
          if (pisMatch) {
            const pis = cleanPIS(pisMatch[0]);
            const restOfLine = line.slice(line.indexOf(pisMatch[0]) + pisMatch[0].length).trim();
            const nome = restOfLine.replace(/^\d+/, '').trim();

            if (pis && pis !== "000000000000" && !newFuncs.find(f => cleanPIS(f.pis) === pis)) {
              newFuncs.push({ 
                pis, nome: nome || "Colaborador Novo", ativo: true, 
                jornadaDiariaMinutos: 480, setor: 'Geral',
                //@ts-ignore
                matricula: (newFuncs.length + 1).toString().padStart(4, '0')
              });
            }
          }
        } 
        // Tipo 3: Marcação de Ponto
        else if (line.length > 30 && (line.slice(9, 10) === '3' || line.includes(' 3 '))) {
          // Extração robusta por regex para evitar erro de deslocamento de coluna
          const dateMatch = line.match(/(\d{2})(\d{2})(\d{4})/); // DDMMYYYY
          const timeMatch = line.match(/(\d{2})(\d{2})\d{11,12}/); // HHmm seguido de PIS
          const pisMatch = line.match(/\d{11,12}$/) || line.match(/\d{11,12}/);

          if (dateMatch && timeMatch && pisMatch) {
            const dateKey = `${dateMatch[3]}-${dateMatch[2]}-${dateMatch[1]}`;
            const time = `${timeMatch[1]}:${timeMatch[2]}`;
            const pis = cleanPIS(pisMatch[0]);

            if (pis && pis !== "000000000000") {
              if (!newPontos[pis]) newPontos[pis] = [];
              let diaPonto = newPontos[pis].find(p => p.data === dateKey);
              if (!diaPonto) {
                diaPonto = { data: dateKey, batidas: [], isFalta: false };
                newPontos[pis].push(diaPonto);
              }
              if (!diaPonto.batidas.find(b => b.hora === time)) {
                diaPonto.batidas.push({ hora: time, origem: 'AFD' });
                diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
              }
            }
          }
        }
      });

      setData(prev => ({ ...prev, funcionarios: newFuncs, pontos: newPontos }));
    };
    event.target.value = '';
  };

