                                         onClick={() => setModalAjuste({ pis: activePis!, date: day, hora: '08:00' })}
                                         className="p-1.5 text-slate-300 hover:text-[#E30613] transition-all bg-white border border-slate-100 rounded-lg shadow-sm"
                                       >
                                         <Plus className="w-3.5 h-3.5" />
                                       </button>
                                    </td>
                                 </tr>
                              )
                           })}
                        </tbody>
                     </table>
                  </div>
               </div>
             </>
           ) : (
             <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner">
               <Fingerprint className="w-16 h-16 opacity-10 mb-4 animate-pulse" />
               <p className="text-xl font-black text-slate-400 uppercase tracking-tighter">Selecione um colaborador na lateral</p>
               <p className="text-[10px] font-bold text-slate-300 uppercase mt-2">Para visualizar o espelho de ponto eletrônico</p>
             </div>
           )}
        </div>
      </div>

      {modalAjuste && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-md">
           <div className="bg-white rounded-[3rem] shadow-2xl max-w-lg w-full p-12 space-y-8 animate-in zoom-in-95 duration-300 border border-slate-200">
              <div className="flex items-center gap-4 border-b border-slate-100 pb-6">
                 <div className="p-4 bg-red-50 rounded-2xl text-[#E30613] shadow-inner"><Edit3 /></div>
                 <div>
                    <h3 className="text-2xl font-black text-slate-900 tracking-tighter uppercase leading-none">Inclusão Manual</h3>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Alteração Administrativa — Portaria 671</p>
                 </div>
              </div>

              <div className="space-y-6">
                 <div className="flex justify-between items-end gap-6">
                    <div className="flex-1 space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Horário da Batida</label>
                       <input 
                         type="time" 
                         value={modalAjuste.hora}
                         onChange={(e) => setModalAjuste({...modalAjuste, hora: e.target.value})}
                         className="w-full px-6 py-5 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-black text-4xl text-slate-900 outline-none focus:ring-4 focus:ring-[#E30613]/10"
                       />
                    </div>
                    <div className="text-right pb-4">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Data</p>
                       <p className="font-black text-slate-900 text-lg tracking-tighter">{modalAjuste.date.split('-').reverse().join('/')}</p>
                    </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Motivo do Ajuste (Obrigatório)</label>
                    <textarea 
                      placeholder="Descreva o motivo desta inclusão para fins de auditoria..."
                      value={motivoAjuste}
                      onChange={(e) => setMotivoAjuste(e.target.value)}
                      className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-slate-700 min-h-[120px] outline-none focus:ring-4 focus:ring-[#E30613]/10"
                    />
                 </div>

                 <div className="flex flex-col gap-3">
                    <button 
                      onClick={handleSaveAjuste}
                      disabled={!motivoAjuste}
                      className="w-full py-6 bg-[#E30613] text-white rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl disabled:opacity-30 hover:bg-red-700 transition-all flex items-center justify-center gap-3 active:scale-95"
                    >
                      <Save className="w-4 h-4" /> CONFIRMAR LANÇAMENTO
                    </button>
                    <button 
                      onClick={() => { setModalAjuste(null); setMotivoAjuste(''); }}
                      className="w-full py-5 bg-slate-100 text-slate-400 rounded-[2rem] font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition-all"
                    >
                      CANCELAR
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

