import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, UserCheck, Calendar, FileText, Trash2, 
  CheckCircle2, AlertTriangle, Edit3, X, History, Users, 
  Search, ShieldCheck, Save, Plus, Info, Fingerprint, 
  Paperclip, Download, ShieldAlert, BadgeCheck
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, MarcacaoPonto, ControleHoras, LogAuditoriaPonto, RegistroBatida, AnexoPonto } from '../types';

export const HorasPage: React.FC = () => {
  const [data, setData] = useState<ControleHoras>(() => {
    const saved = localStorage.getItem('abc_rh_ponto_v1');
    return saved ? JSON.parse(saved) : { funcionarios: [], pontos: {}, logs: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePis, setActivePis] = useState<string | null>(null);
  const [isEditingFunc, setIsEditingFunc] = useState(false);

  // Modais
  const [modalAjuste, setModalAjuste] = useState<{pis: string, date: string, hora: string} | null>(null);
  const [motivoAjuste, setMotivoAjuste] = useState('');
  const [showLogs, setShowLogs] = useState(false);

  useEffect(() => {
    localStorage.setItem('abc_rh_ponto_v1', JSON.stringify(data));
  }, [data]);

  // --- UTILS ---
  const cleanPIS = (pis: string) => pis.replace(/\D/g, '').slice(-12).padStart(12, '0');

  const timeToMinutes = (time: string): number => {
    if (!time || !time.includes(':')) return 0;
    const [h, m] = time.split(':').map(Number);
    return (h * 60) + m;
  };

  const minutesToTime = (mins: number): string => {
    const h = Math.floor(Math.abs(mins) / 60);
    const m = Math.abs(mins) % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  // --- PARSER AFD ROBUSTO ---
  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/);
      const newFuncs = [...data.funcionarios];
      const newPontos = { ...data.pontos };

      lines.forEach(line => {
        if (line.length < 30) return;
        const tipo = line.substring(9, 10);

        // Registro Tipo 5: Cadastro/Alteração de Empregado
        if (tipo === '5') {
          const pisMatch = line.match(/\d{11,12}/);
          if (pisMatch) {
            const pis = cleanPIS(pisMatch[0]);
            const nomeRaw = line.substring(line.indexOf(pisMatch[0]) + pisMatch[0].length).trim();
            const nome = nomeRaw.replace(/^\d+/, '').trim();

            if (pis && !newFuncs.find(f => cleanPIS(f.pis) === pis)) {
              newFuncs.push({ 
                pis, nome, ativo: true, jornadaDiariaMinutos: 480, setor: 'Geral',
                matricula: (newFuncs.length + 1).toString().padStart(4, '0')
              });
            }
          }
        } 
        // Registro Tipo 3: Marcação de Ponto
        else if (tipo === '3') {
          const dia = line.substring(10, 12), mes = line.substring(12, 14), ano = line.substring(14, 18);
          const hora = line.substring(18, 20), min = line.substring(20, 22);
          const pisMatch = line.substring(22, 34).match(/\d+/);

          if (pisMatch) {
            const pis = cleanPIS(pisMatch[0]);
            const dateKey = `${ano}-${mes}-${dia}`;
            const time = `${hora}:${min}`;

            if (!newPontos[pis]) newPontos[pis] = [];
            let diaPonto = newPontos[pis].find(p => p.data === dateKey);
            if (!diaPonto) {
              diaPonto = { data: dateKey, batidas: [], isFalta: false };
              newPontos[pis].push(diaPonto);
            }
            if (!diaPonto.batidas.find(b => b.hora === time)) {
              diaPonto.batidas.push({ hora: time, origem: 'AFD' });
              diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
            }
          }
        }
      });

      setData(prev => ({ ...prev, funcionarios: newFuncs, pontos: newPontos }));
    };
    event.target.value = '';
  };

  const filteredFuncs = useMemo(() => {
    return data.funcionarios
      .filter(f => f.nome.toLowerCase().includes(searchTerm.toLowerCase()) || f.pis.includes(searchTerm))
      .sort((a, b) => a.nome.localeCompare(b.nome));
  }, [data.funcionarios, searchTerm]);

  const activeEmployee = useMemo(() => 
    data.funcionarios.find(f => f.pis === activePis), 
    [data.funcionarios, activePis]
  );

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: lastDay }, (_, i) => `${year}-${month}-${(i + 1).toString().padStart(2, '0')}`);
  }, [selectedMonth]);

  const calculateDay = (batidas: RegistroBatida[], jornadaNominal: number = 480) => {
    if (!batidas || batidas.length < 2) return { trabalhadas: 0, saldo: -jornadaNominal };
    let totalMinutes = 0;
    const sorted = [...batidas].sort((a, b) => a.hora.localeCompare(b.hora));
    for (let i = 0; i < sorted.length - 1; i += 2) {
      const start = timeToMinutes(sorted[i].hora);
      const end = timeToMinutes(sorted[i+1].hora);
      if (end > start) totalMinutes += (end - start);
    }
    return { trabalhadas: totalMinutes, saldo: totalMinutes - jornadaNominal };
  };

  const handleUpdateFuncData = (pis: string, updates: Partial<Funcionario>) => {
    setData(prev => ({
      ...prev,
      funcionarios: prev.funcionarios.map(f => f.pis === pis ? { ...f, ...updates } : f)
    }));
  };

  const handleSaveAjuste = () => {
    if (!modalAjuste || !motivoAjuste) return;
    const { pis, date, hora } = modalAjuste;
    const newPontos = { ...data.pontos };

    if (!newPontos[pis]) newPontos[pis] = [];
    let diaPonto = newPontos[pis].find(p => p.data === date);
    if (!diaPonto) {
      diaPonto = { data: date, batidas: [], isFalta: false };
      newPontos[pis].push(diaPonto);
    }

    const auditId = crypto.randomUUID();
    diaPonto.batidas.push({ hora, origem: 'AJUSTE', obs: motivoAjuste, idAuditoria: auditId });
    diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
    diaPonto.isFalta = false;

    const log: LogAuditoriaPonto = {
      id: auditId,
      timestamp: new Date().toISOString(),
      usuario: 'Administrador (RH)',
      pis,
      dataPonto: date,
      tipo: 'inclusao',
      valorNovo: hora,
      motivo: motivoAjuste
    };

    setData(prev => ({ ...prev, pontos: newPontos, logs: [log, ...prev.logs] }));
    setModalAjuste(null);
    setMotivoAjuste('');
  };

  const handleExportPDF = () => {
    if (!activeEmployee) return;
    const doc = new jsPDF();
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();

    // Estilo Control iD
    doc.setFont("helvetica", "bold");
    doc.setFontSize(22);
    doc.text("Espelho", 14, 20);
    doc.setFont("helvetica", "normal");
    doc.text("de Ponto Eletrônico", 14, 28);

    doc.setFontSize(10);
    doc.setTextColor(150, 0, 0);
    doc.text(`DE 01/${month}/${year} ATÉ ${lastDay}/${month}/${year}`, 145, 28);

    doc.setTextColor(0);
    doc.setDrawColor(200);
    doc.line(14, 35, 196, 35);

    // Cabeçalho
    doc.setFontSize(8);
    doc.setFont("helvetica", "bold");
    const infoY = 42;
    doc.text("EMPRESA:", 14, infoY); doc.setFont("helvetica", "normal"); doc.text("ABC DA CONSTRUÇÃO ITU LTDA", 32, infoY);
    doc.setFont("helvetica", "bold"); doc.text("CNPJ:", 100, infoY); doc.setFont("helvetica", "normal"); doc.text("43.717.337/0001-27", 112, infoY);

    doc.setFont("helvetica", "bold"); doc.text("NOME:", 14, infoY+6); doc.setFont("helvetica", "normal"); doc.text(activeEmployee.nome.toUpperCase(), 32, infoY+6);
    doc.setFont("helvetica", "bold"); doc.text("PIS:", 100, infoY+6); doc.setFont("helvetica", "normal"); doc.text(activeEmployee.pis, 110, infoY+6);

    const tableData = currentMonthDays.map(day => {
      const p = data.pontos[activeEmployee.pis]?.find(x => x.data === day);
      const b = p?.batidas || [];
      const calc = calculateDay(b, activeEmployee.jornadaDiariaMinutos);
      const dt = new Date(day + 'T00:00:00');
      const weekday = dt.toLocaleDateString('pt-BR', { weekday: 'short' }).toUpperCase();

      return [
        `${day.split('-')[2]}/${month} - ${weekday}`,
        b.map(x => x.hora).join(' '),
        b[0]?.hora || '', b[1]?.hora || '', b[2]?.hora || '', b[3]?.hora || '',
        calc.trabalhadas > 0 ? minutesToTime(calc.trabalhadas) : '',
        '00008'
      ];
    });

    (doc as any).autoTable({
      head: [['DIA', 'MARCAÇÕES', 'E1', 'S1', 'E2', 'S2', 'DURAÇÃO', 'CH']],
      body: tableData,
      startY: 65,
      theme: 'plain',
      headStyles: { fontSize: 6, fontStyle: 'bold', lineWidth: 0.1 },
      styles: { fontSize: 6, cellPadding: 1, lineWidth: 0.1 }
    });

    doc.save(`Espelho_Ponto_${activeEmployee.nome}_${selectedMonth}.pdf`);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* HEADER RH */}
      <div className="flex flex-col lg:flex-row justify-between items-center gap-6 bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl">
        <div className="flex items-center gap-5">
           <div className="bg-[#E30613] p-4 rounded-3xl shadow-lg">
              <ShieldCheck className="w-8 h-8 text-white" />
           </div>
           <div>
              <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tighter leading-none">Gestão de REP</h2>
              <p className="text-slate-400 font-bold text-[10px] uppercase tracking-widest mt-2">Compliance Portaria 671 — ABC Itu</p>
           </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="bg-slate-50 rounded-2xl px-5 py-3 border border-slate-200 flex items-center gap-4">
            <Calendar className="w-5 h-5 text-[#E30613]" />
            <input 
              type="month" 
              value={selectedMonth} 
              onChange={(e) => setSelectedMonth(e.target.value)} 
              className="bg-transparent text-xs font-black uppercase outline-none cursor-pointer" 
            />
          </div>
          <label className="flex items-center gap-3 px-8 py-4 bg-[#0A1121] text-white rounded-2xl cursor-pointer hover:bg-black transition-all font-black text-xs uppercase tracking-widest shadow-xl">
            <FileUp className="w-5 h-5 text-[#E30613]" /> IMPORTAR AFD
            <input type="file" className="hidden" accept=".txt" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* LISTA DE COLABORADORES */}
        <div className="lg:col-span-1 space-y-4">
          <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm sticky top-24">
            <div className="relative mb-6">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
              <input 
                type="text" 
                placeholder="Nome ou PIS..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl text-xs font-bold outline-none"
              />
            </div>
            <div className="space-y-2 max-h-[60vh] overflow-y-auto custom-scrollbar pr-1">
              {filteredFuncs.map(f => (
                <button 
                  key={f.pis}
                  onClick={() => { setActivePis(f.pis); setIsEditingFunc(false); }}
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePis === f.pis ? 'bg-[#E30613] text-white border-[#E30613] shadow-lg scale-[1.02]' : 'bg-slate-50 border-transparent text-slate-600 hover:bg-slate-100'}`}
                >
                  <p className="text-[11px] font-black uppercase truncate leading-tight">{f.nome}</p>
                  <div className="flex items-center gap-2 mt-1">
                     <Fingerprint className={`w-3 h-3 ${activePis === f.pis ? 'text-white/40' : 'text-slate-300'}`} />
                     <p className={`text-[9px] font-bold ${activePis === f.pis ? 'text-white/60' : 'text-slate-400'}`}>{f.pis}</p>
                  </div>
                </button>
              ))}
            </div>
            <button 
              onClick={() => setShowLogs(!showLogs)}
              className="w-full mt-6 py-4 bg-slate-100 text-slate-500 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-200 transition-all flex items-center justify-center gap-2"
            >
              <History className="w-4 h-4" /> Ver Logs de Auditoria
            </button>
          </div>
        </div>

        {/* PAINEL DE PONTO */}
        <div className="lg:col-span-3 space-y-6">
           {activeEmployee ? (
             <>
               {/* FICHA CADASTRAL */}
               <div className="bg-white border border-slate-200 rounded-[2.5rem] shadow-xl overflow-hidden">
                  <div className="p-8 border-b border-slate-100 bg-slate-50/30 flex flex-col md:flex-row justify-between items-center gap-6">
                     <div className="flex items-center gap-6">
                        <div className="w-16 h-16 bg-white rounded-3xl shadow-sm flex items-center justify-center border border-slate-100">
                           <Users className="w-8 h-8 text-[#E30613]" />
                        </div>
                        <div>
                           <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter leading-none">{activeEmployee.nome}</h3>
                           <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-2">Matrícula: {activeEmployee.matricula || '---'}</p>
                        </div>
                     </div>
                     <div className="flex gap-3">
                        <button onClick={() => setIsEditingFunc(!isEditingFunc)} className="p-4 bg-white border border-slate-200 rounded-2xl text-slate-400 hover:text-slate-900 transition-all shadow-sm">
                           <Edit3 className="w-5 h-5" />
                        </button>
                        <button onClick={handleExportPDF} className="flex items-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-2xl text-xs font-black uppercase tracking-widest shadow-xl hover:bg-black transition-all">
                           <FileText className="w-5 h-5 text-[#E30613]" /> Gerar Espelho
                        </button>
                     </div>
                  </div>

                  {isEditingFunc && (
                    <div className="p-10 grid grid-cols-2 md:grid-cols-4 gap-8 bg-slate-50 border-b border-slate-100">
                        <div className="space-y-1.5">
                           <label className="text-[9px] font-black text-slate-400 uppercase px-1">CPF</label>
                           <input type="text" value={activeEmployee.cpf || ''} onChange={e => handleUpdateFuncData(activeEmployee.pis, {cpf: e.target.value})} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-xs font-bold outline-none focus:ring-2 focus:ring-[#E30613]/10" placeholder="000.000.000-00"/>
                        </div>
                        <div className="space-y-1.5">
