import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, UserCheck, Calendar, FileText, Trash2, 
  CheckCircle2, AlertTriangle, Edit3, X, History, Users, 
  Search, ShieldCheck, Save, Plus, Info, Fingerprint, 
  Paperclip, Download, ShieldAlert, BadgeCheck, IdCard
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, MarcacaoPonto, ControleHoras, LogAuditoriaPonto, RegistroBatida, AnexoPonto } from '../types';

export const HorasPage: React.FC = () => {
  const [data, setData] = useState<ControleHoras>(() => {
    const saved = localStorage.getItem('abc_rh_ponto_final_v3');
    return saved ? JSON.parse(saved) : { funcionarios: [], pontos: {}, logs: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePis, setActivePis] = useState<string | null>(null);
  const [isEditingFunc, setIsEditingFunc] = useState(false);
  const [modalAjuste, setModalAjuste] = useState<{pis: string, date: string, hora: string} | null>(null);
  const [motivoAjuste, setMotivoAjuste] = useState('');

  useEffect(() => {
    localStorage.setItem('abc_rh_ponto_final_v3', JSON.stringify(data));
  }, [data]);

  // --- HELPERS ---
  const cleanPIS = (pis: string) => pis.replace(/\D/g, '').slice(-11);

  const timeToMinutes = (time: string): number => {
    if (!time || !time.includes(':')) return 0;
    const [h, m] = time.split(':').map(Number);
    return (h * 60) + m;
  };

  const minutesToTime = (mins: number): string => {
    const h = Math.floor(Math.abs(mins) / 60);
    const m = Math.abs(mins) % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  const calculateDay = (batidas: RegistroBatida[], jornadaMinutos: number = 480) => {
    if (!batidas || batidas.length < 2) return { trabalhadas: 0, saldo: 0 };
    let total = 0;
    const sorted = [...batidas].sort((a, b) => a.hora.localeCompare(b.hora));
    for (let i = 0; i < sorted.length - 1; i += 2) {
      const start = timeToMinutes(sorted[i].hora);
      const end = timeToMinutes(sorted[i+1].hora);
      if (end > start) total += (end - start);
    }
    return { trabalhadas: total, saldo: total - jornadaMinutos };
  };

  // --- PARSER AFD ROBUSTO (Ignora prefixos como o "I" do print) ---
  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/);
      const newFuncs = [...data.funcionarios];
      const newPontos = { ...data.pontos };

      lines.forEach(line => {
        // Ignora linhas de cabeçalho (Tipo 1) ou empresa (Tipo 2)
        if (line.length < 30) return;

        // REGEX para encontrar o PIS (11 ou 12 dígitos seguidos)
        const pisMatch = line.match(/\d{11,12}/);
        if (!pisMatch) return;
        const pis = cleanPIS(pisMatch[0]);

        // Se a linha contém um PIS e o código "5" (Cadastro de Empregado)
        // Note: Em alguns AFDs, o código do registro vem após o PIS ou no início
        if (line.includes(' 5 ') || (line.indexOf(pisMatch[0]) > 10 && line.includes('5'))) {
          const rawNome = line.substring(line.indexOf(pisMatch[0]) + pisMatch[0].length).trim();
          // Remove prefixos numéricos ou caracteres estranhos no início do nome
          const nomeClean = rawNome.replace(/^[^a-zA-Z]+/, '').trim();

          if (!newFuncs.find(f => cleanPIS(f.pis) === pis)) {
            newFuncs.push({ 
              pis, nome: nomeClean || "COLABORADOR " + pis, ativo: true, 
              jornadaDiariaMinutos: 480,
              matricula: (newFuncs.length + 1).toString().padStart(4, '0'),
              cargo: 'Vendedor', departamento: 'Comercial'
            });
          }
        } 
        // Se a linha contém o código "3" (Marcação de Ponto)
        else if (line.includes(' 3 ') || line.substring(9,10) === '3') {
          // Extrai Data (DDMMAAAA) e Hora (HHMM)
          const datePart = line.match(/(\d{2})(\d{2})(\d{4})/); // DD MM AAAA
          const timePart = line.match(/\d{8}(\d{2})(\d{2})/); // Após a data vem a hora HH MM

          if (datePart && timePart) {
            const dateKey = `${datePart[3]}-${datePart[2]}-${datePart[1]}`;
            const time = `${timePart[1]}:${timePart[2]}`;

            if (!newPontos[pis]) newPontos[pis] = [];
            let diaPonto = newPontos[pis].find(p => p.data === dateKey);
            if (!diaPonto) {
              diaPonto = { data: dateKey, batidas: [], isFalta: false };
              newPontos[pis].push(diaPonto);
            }
            if (!diaPonto.batidas.find(b => b.hora === time)) {
              diaPonto.batidas.push({ hora: time, origem: 'AFD' });
              diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
            }
          }
        }
      });

      setData(prev => ({ ...prev, funcionarios: newFuncs, pontos: newPontos }));
    };
    event.target.value = '';
  };

  const filteredFuncs = useMemo(() => {
    return data.funcionarios.filter(f => 
      f.nome.toLowerCase().includes(searchTerm.toLowerCase()) || f.pis.includes(searchTerm)
    ).sort((a, b) => a.nome.localeCompare(b.nome));
  }, [data.funcionarios, searchTerm]);

  const activeEmployee = useMemo(() => 
    data.funcionarios.find(f => f.pis === activePis), 
    [data.funcionarios, activePis]
  );

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: lastDay }, (_, i) => `${year}-${month}-${(i + 1).toString().padStart(2, '0')}`);
  }, [selectedMonth]);

  const handleUpdateFuncData = (pis: string, updates: Partial<Funcionario>) => {
    setData(prev => ({
      ...prev,
      funcionarios: prev.funcionarios.map(f => f.pis === pis ? { ...f, ...updates } : f)
    }));
  };

  const handleSaveAjuste = () => {
    if (!modalAjuste || !motivoAjuste) return;
    const { pis, date, hora } = modalAjuste;
    const newPontos = { ...data.pontos };
    if (!newPontos[pis]) newPontos[pis] = [];
    let diaPonto = newPontos[pis].find(p => p.data === date);
    if (!diaPonto) {
      diaPonto = { data: date, batidas: [], isFalta: false };
      newPontos[pis].push(diaPonto);
    }
    diaPonto.batidas.push({ hora, origem: 'AJUSTE', obs: motivoAjuste });
    diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
    setData(prev => ({ ...prev, pontos: newPontos }));
    setModalAjuste(null);
    setMotivoAjuste('');
  };

  const handleExportPDF = () => {
    if (!activeEmployee) return;
    const doc = new jsPDF();
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();

    // Cabeçalho Control iD
    doc.setFontSize(22);
    doc.setFont("helvetica", "bold");
    doc.text("Espelho", 14, 20);
    doc.setFont("helvetica", "normal");
    doc.text("de Ponto Eletrônico", 14, 28);
    doc.setTextColor(150, 0, 0);
    doc.setFontSize(10);
    doc.text(`DE 01/${month}/${year} ATÉ ${lastDay}/${month}/${year}`, 145, 28);

    doc.setTextColor(0);
    doc.setDrawColor(200);
    doc.line(14, 32, 196, 32);

    // Grid de Informações
    doc.setFontSize(7);
    const infoY = 40;
    doc.setFont("helvetica", "bold"); doc.text("EMPRESA:", 14, infoY);
    doc.setFont("helvetica", "normal"); doc.text("ABC DA CONSTRUÇÃO ITU LTDA", 35, infoY);
    doc.setFont("helvetica", "bold"); doc.text("CNPJ:", 110, infoY);
    doc.setFont("helvetica", "normal"); doc.text("43.717.337/0001-27", 125, infoY);

    doc.setFont("helvetica", "bold"); doc.text("NOME:", 14, infoY + 6);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.nome.toUpperCase(), 35, infoY + 6);
    doc.setFont("helvetica", "bold"); doc.text("PIS/PASEP:", 110, infoY + 6);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.pis, 130, infoY + 6);
    doc.setFont("helvetica", "bold"); doc.text("ADMISSÃO:", 165, infoY + 6);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.admissao || "01/01/2024", 185, infoY + 6);

    doc.setFont("helvetica", "bold"); doc.text("CARGO:", 14, infoY + 12);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.cargo || "Vendedor", 35, infoY + 12);
    doc.setFont("helvetica", "bold"); doc.text("CPF:", 110, infoY + 12);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.cpf || "---", 120, infoY + 12);
    doc.setFont("helvetica", "bold"); doc.text("MATRÍCULA:", 165, infoY + 12);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.matricula || "0013", 185, infoY + 12);

    const tableData = currentMonthDays.map(day => {
      const p = data.pontos[activeEmployee.pis]?.find(x => x.data === day);
      const b = p?.batidas || [];
      const calc = calculateDay(b, activeEmployee.jornadaDiariaMinutos);
      const dt = new Date(day + 'T00:00:00');
      const weekday = dt.toLocaleDateString('pt-BR', { weekday: 'short' }).toUpperCase();

      return [
        `${day.split('-')[2]}/${month} - ${weekday}`,
        b.map(x => x.hora).join('  '),
        b[0]?.hora || '', b[1]?.hora || '', b[2]?.hora || '', b[3]?.hora || '',
        calc.trabalhadas > 0 ? minutesToTime(calc.trabalhadas) : '',
        '00008'
      ];
    });

    (doc as any).autoTable({
      head: [['DIA', 'MARCAÇÕES NO PONTO', 'E1', 'S1', 'E2', 'S2', 'DURAÇÃO', 'CH']],
      body: tableData,
      startY: 60,
      theme: 'plain',
      headStyles: { fontSize: 6, fontStyle: 'bold', lineWidth: 0.1 },
      styles: { fontSize: 6, cellPadding: 1, lineWidth: 0.1 },
      columnStyles: { 1: { cellWidth: 40 } }
    });

    doc.save(`Espelho_REP_${activeEmployee.nome}_${selectedMonth}.pdf`);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col lg:flex-row justify-between items-center gap-6 bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl">
        <div className="flex items-center gap-5">
           <div className="bg-[#E30613] p-4 rounded-3xl shadow-lg">
              <ShieldCheck className="w-8 h-8 text-white" />
           </div>
           <div>
              <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tighter leading-none">Espelho de Ponto</h2>
              <p className="text-slate-400 font-bold text-[10px] uppercase tracking-widest mt-2">Sincronização AFD — Control iD</p>
           </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="bg-slate-50 rounded-2xl px-5 py-3 border border-slate-200 flex items-center gap-4">
            <Calendar className="w-5 h-5 text-[#E30613]" />
            <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="bg-transparent text-xs font-black uppercase outline-none" />
          </div>
          <label className="flex items-center gap-3 px-8 py-4 bg-[#0A1121] text-white rounded-2xl cursor-pointer hover:bg-black transition-all font-black text-xs uppercase tracking-widest shadow-xl">
            <FileUp className="w-5 h-5 text-[#E30613]" /> IMPORTAR AFD
            <input type="file" className="hidden" accept=".txt" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="lg:col-span-1 space-y-4">
          <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm sticky top-24">
            <div className="relative mb-6">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
              <input type="text" placeholder="Buscar por Nome..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl text-xs font-bold outline-none" />
            </div>
            <div className="space-y-2 max-h-[60vh] overflow-y-auto custom-scrollbar">
              {filteredFuncs.map(f => (
                <button 
                  key={f.pis}
                  onClick={() => { setActivePis(f.pis); setIsEditingFunc(false); }}
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePis === f.pis ? 'bg-[#E30613] text-white shadow-lg' : 'bg-slate-50 border-transparent text-slate-600 hover:bg-slate-100'}`}
                >
                  <p className="text-[10px] font-black uppercase truncate">{f.nome}</p>
                  <p className={`text-[9px] font-bold ${activePis === f.pis ? 'text-white/60' : 'text-slate-400'}`}>PIS: {f.pis}</p>
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="lg:col-span-3 space-y-6">
           {activeEmployee ? (
             <>
               <div className="bg-white border border-slate-200 rounded-[2.5rem] shadow-xl overflow-hidden">
                  <div className="p-8 border-b border-slate-100 bg-slate-50/30 flex flex-col md:flex-row justify-between items-center gap-6">
                     <div className="flex items-center gap-6">
                        <div className="w-16 h-16 bg-white rounded-3xl shadow-sm flex items-center justify-center border border-slate-100">
                           <IdCard className="w-8 h-8 text-[#E30613]" />
                        </div>
                        <div>
                           <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter leading-none">{activeEmployee.nome}</h3>
                           <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-2">PIS: {activeEmployee.pis} | Matrícula: {activeEmployee.matricula || '---'}</p>
                        </div>
                     </div>
                     <div className="flex gap-3">
                        <button onClick={() => setIsEditingFunc(!isEditingFunc)} className="flex items-center gap-2 px-6 py-3 bg-white border border-slate-200 rounded-2xl text-slate-500 font-black text-[10px] uppercase shadow-sm">
                           <Edit3 className="w-4 h-4" /> Editar Perfil
                        </button>
                        <button onClick={handleExportPDF} className="flex items-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-2xl text-xs font-black uppercase tracking-widest shadow-xl hover:bg-black transition-all">
                           <FileText className="w-5 h-5 text-[#E30613]" /> Gerar PDF
                        </button>
                     </div>
                  </div>

                  {isEditingFunc && (
                    <div className="p-8 grid grid-cols-2 md:grid-cols-4 gap-6 bg-slate-50">
                        <div className="space-y-1.5">
                           <label className="text-[9px] font-black text-slate-400 uppercase px-1">CPF</label>
                           <input type="text" value={activeEmployee.cpf || ''} onChange={e => handleUpdateFuncData(activeEmployee.pis, {cpf: e.target.value})} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-xs font-bold outline-none" placeholder="000.000.000-00"/>
                        </div>
                        <div className="space-y-1.5">
                           <label className="text-[9px] font-black text-slate-400 uppercase px-1">Matrícula</label>
                           <input type="text" value={activeEmployee.matricula || ''} onChange={e => handleUpdateFuncData(activeEmployee.pis, {matricula: e.target.value})} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-xs font-bold outline-none"/>
                        </div>
                        <div className="space-y-1.5">
                           <label className="text-[9px] font-black text-slate-400 uppercase px-1">Cargo</label>
                           <input type="text" value={activeEmployee.cargo || ''} onChange={e => handleUpdateFuncData(activeEmployee.pis, {cargo: e.target.value})} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-xs font-bold outline-none" placeholder="Vendedor"/>
                        </div>
                        <div className="space-y-1.5">
                           <label className="text-[9px] font-black text-slate-400 uppercase px-1">Admissão</label>
                           <input type="date" value={activeEmployee.admissao || ''} onChange={e => handleUpdateFuncData(activeEmployee.pis, {admissao: e.target.value})} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-xs font-bold outline-none"/>
                        </div>
                    </div>
                  )}
               </div>

               <div className="bg-white border border-slate-200 rounded-[2.5rem] shadow-2xl overflow-hidden">
                  <div className="overflow-x-auto">
                     <table className="w-full text-left">
                        <thead>
                           <tr className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-widest">
                              <th className="px-8 py-5 w-40">Data / Dia</th>
                              <th className="px-8 py-5">Registros</th>
                              <th className="px-4 py-5 text-center">E1</th>
                              <th className="px-4 py-5 text-center">S1</th>
                              <th className="px-4 py-5 text-center">E2</th>
                              <th className="px-4 py-5 text-center">S2</th>
                              <th className="px-8 py-5 text-right">Duração</th>
                              <th className="px-8 py-5 text-center">Ações</th>
                           </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                           {currentMonthDays.map(day => {
                              const diaPonto = data.pontos[activePis!]?.find(x => x.data === day);
                              const b = diaPonto?.batidas || [];
                              const calc = calculateDay(b, activeEmployee.jornadaDiariaMinutos);
                              const dt = new Date(day + 'T00:00:00');
                              const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                              return (
                                 <tr key={day} className={`group hover:bg-slate-50 transition-all ${isWeekend ? 'bg-slate-50/40' : ''}`}>
                                    <td className="px-8 py-4 border-r border-slate-50">
                                       <span className="text-sm font-black text-slate-900">{day.split('-').reverse().join('/')}</span>
                                       <span className="text-[9px] font-bold text-slate-400 uppercase block">{dt.toLocaleDateString('pt-BR', { weekday: 'long' }).toUpperCase()}</span>
                                    </td>
                                    <td className="px-8 py-4">
                                       <div className="flex flex-wrap gap-2">
                                          {b.length > 0 ? b.map((bt, i) => (
                                            <span key={i} className={`text-[10px] font-black px-2 py-1 rounded-md border ${bt.origem === 'AJUSTE' ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-slate-50 border-slate-200 text-slate-700'}`}>{bt.hora}</span>
                                          )) : <span className="text-[10px] text-slate-200 font-bold uppercase italic">Sem registros</span>}
                                       </div>
                                    </td>
                                    <td className="px-4 py-4 text-center text-[11px] font-black text-slate-400">{b[0]?.hora || '--:--'}</td>
                                    <td className="px-4 py-4 text-center text-[11px] font-black text-slate-400">{b[1]?.hora || '--:--'}</td>
                                    <td className="px-4 py-4 text-center text-[11px] font-black text-slate-400">{b[2]?.hora || '--:--'}</td>
                                    <td className="px-4 py-4 text-center text-[11px] font-black text-slate-400">{b[3]?.hora || '--:--'}</td>
                                    <td className={`px-8 py-4 text-right font-black text-[11px] bg-slate-50/50 ${calc.trabalhadas > 0 ? 'text-emerald-600' : 'text-slate-300'}`}>
                                       {calc.trabalhadas > 0 ? minutesToTime(calc.trabalhadas) : '00:00'}
                                    </td>
                                    <td className="px-8 py-4 text-center">
                                       <button onClick={() => setModalAjuste({ pis: activePis!, date: day, hora: '08:00' })} className="p-2 text-slate-300 hover:text-[#E30613] transition-all bg-white border border-slate-100 rounded-xl shadow-sm opacity-0 group-hover:opacity-100">
                                          <Plus className="w-4 h-4" />
                                       </button>
                                    </td>
                                 </tr>
                              )
                           })}
                        </tbody>
                     </table>
                  </div>
               </div>
             </>
           ) : (
             <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner">
               <Fingerprint className="w-20 h-20 opacity-10 mb-6 animate-pulse" />
               <p className="text-2xl font-black text-slate-400 uppercase tracking-tighter">Selecione um colaborador</p>
               <p className="text-[11px] font-bold text-slate-300 uppercase mt-2">Para visualizar e tratar o espelho de ponto</p>
             </div>
           )}
        </div>
      </div>

      {modalAjuste && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-md">
           <div className="bg-white rounded-[3rem] shadow-2xl max-w-lg w-full p-12 space-y-8 animate-in zoom-in-95 duration-300">
              <div className="flex items-center gap-5 border-b border-slate-100 pb-8">
                 <div className="p-4 bg-red-50 rounded-3xl text-[#E30613] shadow-inner"><Edit3 /></div>
                 <div>
                    <h3 className="text-3xl font-black text-slate-900 tracking-tighter uppercase leading-none">Inclusão Manual</h3>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">Tratativa de Ocorrência — Portaria 671</p>
                 </div>
              </div>
              <div className="space-y-6">
                 <div className="flex justify-between items-end gap-6">
                    <div className="flex-1 space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Horário</label>
                       <input type="time" value={modalAjuste.hora} onChange={(e) => setModalAjuste({...modalAjuste, hora: e.target.value})} className="w-full px-8 py-6 bg-slate-50 border border-slate-200 rounded-[2rem] font-black text-5xl text-slate-900 outline-none" />
                    </div>
                    <div className="text-right pb-4">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Data</p>
                       <p className="font-black text-slate-900 text-xl">{modalAjuste.date.split('-').reverse().join('/')}</p>
                    </div>
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Motivo do Ajuste</label>
                    <textarea placeholder="Justificativa legal..." value={motivoAjuste} onChange={(e) => setMotivoAjuste(e.target.value)} className="w-full px-8 py-5 bg-slate-50 border border-slate-200 rounded-[2rem] font-bold text-slate-700 min-h-[140px] outline-none" />
                 </div>
                 <button onClick={handleSaveAjuste} disabled={!motivoAjuste} className="w-full py-7 bg-[#E30613] text-white rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl disabled:opacity-30">GRAVAR TRATATIVA</button>
                 <button onClick={() => setModalAjuste(null)} className="w-full py-2 text-slate-400 font-black text-[11px] uppercase">Cancelar</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, UserCheck, Calendar, FileText, Trash2, 
  CheckCircle2, AlertTriangle, Edit3, X, History, Users, 
  Search, ShieldCheck, Save, Plus, Info, Fingerprint, 
  IdCard
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, MarcacaoPonto, ControleHoras, LogAuditoriaPonto, RegistroBatida } from '../types';

export const HorasPage: React.FC = () => {
  const [data, setData] = useState<ControleHoras>(() => {
    const saved = localStorage.getItem('abc_rh_ponto_v5');
    return saved ? JSON.parse(saved) : { funcionarios: [], pontos: {}, logs: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePis, setActivePis] = useState<string | null>(null);
  const [isEditingFunc, setIsEditingFunc] = useState(false);
  const [modalAjuste, setModalAjuste] = useState<{pis: string, date: string, hora: string} | null>(null);
  const [motivoAjuste, setMotivoAjuste] = useState('');

  useEffect(() => {
    localStorage.setItem('abc_rh_ponto_v5', JSON.stringify(data));
  }, [data]);

  const cleanPIS = (pis: string) => pis.replace(/\D/g, '').slice(-11);

  const timeToMinutes = (time: string): number => {
    if (!time || !time.includes(':')) return 0;
    const [h, m] = time.split(':').map(Number);
    return (h * 60) + m;
  };

  const minutesToTime = (mins: number): string => {
    const h = Math.floor(Math.abs(mins) / 60);
    const m = Math.abs(mins) % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  const calculateDay = (batidas: RegistroBatida[], jornadaMinutos: number = 480) => {
    if (!batidas || batidas.length < 2) return { trabalhadas: 0, saldo: 0 };
    let total = 0;
    const sorted = [...batidas].sort((a, b) => a.hora.localeCompare(b.hora));
    for (let i = 0; i < sorted.length - 1; i += 2) {
      const start = timeToMinutes(sorted[i].hora);
      const end = timeToMinutes(sorted[i+1].hora);
      if (end > start) total += (end - start);
    }
    return { trabalhadas: total, saldo: total - jornadaMinutos };
  };

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/);
      const newFuncs = [...data.funcionarios];
      const newPontos = { ...data.pontos };

      lines.forEach(line => {
        if (line.length < 20) return;

        // BUSCA POR PIS (11 ou 12 dígitos)
        const pisMatch = line.match(/\d{11,12}/);
        if (!pisMatch) return;
        const pis = cleanPIS(pisMatch[0]);

        // LÓGICA TIPO 5 (CADASTRO): Se a linha tem PIS e muitos caracteres de texto, é provável ser o nome
        // No AFD, o registro tipo 5 tem o '5' na posição 10 (index 9)
        const isCadastro = line.charAt(9) === '5' || line.includes(' 5 ');
        if (isCadastro) {
          const partAfterPis = line.substring(line.indexOf(pisMatch[0]) + pisMatch[0].length).trim();
          // Limpa o nome de prefixos como o "I" ou números grudados que vimos no print
          const nomeClean = partAfterPis.replace(/^[^a-zA-Z]+/, '').trim();

          if (nomeClean && !newFuncs.find(f => cleanPIS(f.pis) === pis)) {
            newFuncs.push({ 
              pis, nome: nomeClean, ativo: true, jornadaDiariaMinutos: 480,
              matricula: (newFuncs.length + 1).toString().padStart(4, '0')
            });
          }
        } 

        // LÓGICA TIPO 3 (MARCAÇÃO): Se a linha tem o '3' na posição 10 (index 9)
        const isMarcacao = line.charAt(9) === '3' || line.includes(' 3 ');
        if (isMarcacao) {
          // Procura por data DDMMAAAA e hora HHMM
          const dataMatch = line.match(/(\d{2})(\d{2})(\d{4})/);
          const horaMatch = line.match(/(\d{8})(\d{2})(\d{2})/); // HHMM após a data de 8 dígitos

          if (dataMatch && horaMatch) {
            const dateKey = `${dataMatch[3]}-${dataMatch[2]}-${dataMatch[1]}`;
            const time = `${horaMatch[2]}:${horaMatch[3]}`;

            if (!newPontos[pis]) newPontos[pis] = [];
            let diaPonto = newPontos[pis].find(p => p.data === dateKey);
            if (!diaPonto) {
              diaPonto = { data: dateKey, batidas: [], isFalta: false };
              newPontos[pis].push(diaPonto);
            }
            if (!diaPonto.batidas.find(b => b.hora === time)) {
              diaPonto.batidas.push({ hora: time, origem: 'AFD' });
              diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
            }
          }
        }
      });

      setData(prev => ({ ...prev, funcionarios: newFuncs, pontos: newPontos }));
    };
    event.target.value = '';
  };

  const filteredFuncs = useMemo(() => {
    return data.funcionarios.filter(f => 
      f.nome.toLowerCase().includes(searchTerm.toLowerCase()) || f.pis.includes(searchTerm)
    ).sort((a, b) => a.nome.localeCompare(b.nome));
  }, [data.funcionarios, searchTerm]);

  const activeEmployee = useMemo(() => 
    data.funcionarios.find(f => f.pis === activePis), 
    [data.funcionarios, activePis]
  );

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: lastDay }, (_, i) => `${year}-${month}-${(i + 1).toString().padStart(2, '0')}`);
  }, [selectedMonth]);

  const handleUpdateFuncData = (pis: string, updates: Partial<Funcionario>) => {
    setData(prev => ({
      ...prev,
      funcionarios: prev.funcionarios.map(f => f.pis === pis ? { ...f, ...updates } : f)
    }));
  };

  const handleSaveAjuste = () => {
    if (!modalAjuste || !motivoAjuste) return;
    const { pis, date, hora } = modalAjuste;
    const newPontos = { ...data.pontos };
    if (!newPontos[pis]) newPontos[pis] = [];
    let diaPonto = newPontos[pis].find(p => p.data === date);
    if (!diaPonto) {
      diaPonto = { data: date, batidas: [], isFalta: false };
      newPontos[pis].push(diaPonto);
    }
    diaPonto.batidas.push({ hora, origem: 'AJUSTE', obs: motivoAjuste });
    diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
    setData(prev => ({ ...prev, pontos: newPontos }));
    setModalAjuste(null);
    setMotivoAjuste('');
  };

  const handleExportPDF = () => {
    if (!activeEmployee) return;
    const doc = new jsPDF();
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();

    doc.setFontSize(22);
    doc.setFont("helvetica", "bold");
    doc.text("Espelho", 14, 20);
    doc.setFont("helvetica", "normal");
    doc.text("de Ponto Eletrônico", 14, 28);
    doc.setTextColor(150, 0, 0);
    doc.setFontSize(10);
    doc.text(`DE 01/${month}/${year} ATÉ ${lastDay}/${month}/${year}`, 145, 28);

    doc.setTextColor(0);
    doc.setDrawColor(200);
    doc.line(14, 32, 196, 32);

    doc.setFontSize(7);
    const infoY = 40;
    doc.setFont("helvetica", "bold"); doc.text("EMPRESA:", 14, infoY);
    doc.setFont("helvetica", "normal"); doc.text("ABC DA CONSTRUÇÃO ITU LTDA", 35, infoY);
    doc.setFont("helvetica", "bold"); doc.text("CNPJ:", 110, infoY);
    doc.setFont("helvetica", "normal"); doc.text("43.717.337/0001-27", 125, infoY);

    doc.setFont("helvetica", "bold"); doc.text("NOME:", 14, infoY + 6);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.nome.toUpperCase(), 35, infoY + 6);
    doc.setFont("helvetica", "bold"); doc.text("PIS/PASEP:", 110, infoY + 6);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.pis, 130, infoY + 6);
    doc.setFont("helvetica", "bold"); doc.text("ADMISSÃO:", 165, infoY + 6);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.admissao || "01/01/2024", 185, infoY + 6);

    doc.setFont("helvetica", "bold"); doc.text("CARGO:", 14, infoY + 12);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.cargo || "Vendedor", 35, infoY + 12);
    doc.setFont("helvetica", "bold"); doc.text("CPF:", 110, infoY + 12);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.cpf || "---", 120, infoY + 12);
    doc.setFont("helvetica", "bold"); doc.text("MATRÍCULA:", 165, infoY + 12);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.matricula || "---", 185, infoY + 12);

    const tableData = currentMonthDays.map(day => {
      const p = data.pontos[activeEmployee.pis]?.find(x => x.data === day);
      const b = p?.batidas || [];
      const calc = calculateDay(b, activeEmployee.jornadaDiariaMinutos);
      const dt = new Date(day + 'T00:00:00');
      const weekday = dt.toLocaleDateString('pt-BR', { weekday: 'short' }).toUpperCase();

      return [
        `${day.split('-')[2]}/${month} - ${weekday}`,
        b.map(x => x.hora).join('  '),
        b[0]?.hora || '', b[1]?.hora || '', b[2]?.hora || '', b[3]?.hora || '',
        calc.trabalhadas > 0 ? minutesToTime(calc.trabalhadas) : '',
        '00008'
      ];
    });

    (doc as any).autoTable({
      head: [['DIA', 'MARCAÇÕES NO PONTO', 'E1', 'S1', 'E2', 'S2', 'DURAÇÃO', 'CH']],
      body: tableData,
      startY: 60,
      theme: 'plain',
      headStyles: { fontSize: 6, fontStyle: 'bold', lineWidth: 0.1 },
      styles: { fontSize: 6, cellPadding: 1, lineWidth: 0.1 },
      columnStyles: { 1: { cellWidth: 40 } }
    });

    doc.save(`Espelho_Ponto_${activeEmployee.nome}_${selectedMonth}.pdf`);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col lg:flex-row justify-between items-center gap-6 bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl">
        <div className="flex items-center gap-5">
           <div className="bg-[#E30613] p-4 rounded-3xl shadow-lg">
              <ShieldCheck className="w-8 h-8 text-white" />
           </div>
           <div>
