};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, UserCheck, Calendar, FileText, Trash2, 
  CheckCircle2, AlertTriangle, Edit3, X, History, Users, 
  Search, ShieldCheck, Save, Plus, Info, Fingerprint, 
  IdCard
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, MarcacaoPonto, ControleHoras, LogAuditoriaPonto, RegistroBatida } from '../types';

export const HorasPage: React.FC = () => {
  const [data, setData] = useState<ControleHoras>(() => {
    const saved = localStorage.getItem('abc_rh_ponto_v6_final');
    return saved ? JSON.parse(saved) : { funcionarios: [], pontos: {}, logs: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePis, setActivePis] = useState<string | null>(null);
  const [isEditingFunc, setIsEditingFunc] = useState(false);
  const [modalAjuste, setModalAjuste] = useState<{pis: string, date: string, hora: string} | null>(null);
  const [motivoAjuste, setMotivoAjuste] = useState('');

  useEffect(() => {
    localStorage.setItem('abc_rh_ponto_v6_final', JSON.stringify(data));
  }, [data]);

  // --- PARSER ESPECIALIZADO PARA STRINGS "SUJAS" ---
  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/);
      const newFuncs = [...data.funcionarios];
      const newPontos = { ...data.pontos };

      lines.forEach(line => {
        if (line.length < 15) return;

        // 1. TENTAR LOCALIZAR O PIS (sequência de 11 ou 12 dígitos, ignorando o que vem antes ou depois)
        const pisMatch = line.match(/\d{11,12}/);
        if (!pisMatch) return;

        const rawPis = pisMatch[0];
        const pis = rawPis.slice(-11); // Padrão PIS são os últimos 11 dígitos

        // 2. IDENTIFICAR SE É REGISTRO DE CADASTRO (Tipo 5)
        // No seu caso, o identificador '5' pode estar deslocado devido aos prefixos 'A' ou 'I'
        const isCadastro = line.includes(' 5 ') || line.charAt(9) === '5' || line.includes('A0') || line.includes('I0');

        if (isCadastro && line.length > 30) {
          // Extrair nome: tudo que vem após a sequência de números do PIS
          const posPis = line.indexOf(rawPis);
          const partAfterPis = line.substring(posPis + rawPis.length).trim();

          // Limpeza do nome: remove qualquer número ou símbolo que sobrou no início da string do nome
          const nomeClean = partAfterPis.replace(/^[^a-zA-ZÁ-ú]+/, '').trim();

          if (nomeClean && nomeClean.length > 3) {
             const existingIdx = newFuncs.findIndex(f => f.pis === pis);
             if (existingIdx === -1) {
                newFuncs.push({ 
                  pis, 
                  nome: nomeClean, 
                  ativo: true, 
                  jornadaDiariaMinutos: 480,
                  matricula: (newFuncs.length + 1).toString().padStart(4, '0')
                });
             } else {
                // Atualiza o nome se o anterior estiver vazio ou for apenas números
                if (!/[a-zA-Z]/.test(newFuncs[existingIdx].nome)) {
                   newFuncs[existingIdx].nome = nomeClean;
                }
             }
          }
        } 

        // 3. IDENTIFICAR SE É REGISTRO DE MARCAÇÃO (Tipo 3)
        // Procuramos o padrão de data DDMMAAAA e o '3' de marcação
        if (line.includes(' 3 ') || line.charAt(9) === '3') {
          const dataMatch = line.match(/(\d{2})(\d{2})(\d{4})/); // DD MM AAAA
          // A hora costuma vir logo após a data no padrão AFD (HHMM)
          const dataIndex = line.search(/\d{8}/);
          if (dataMatch && dataIndex !== -1) {
            const timePart = line.substring(dataIndex + 8, dataIndex + 12);
            if (timePart.length === 4) {
              const dateKey = `${dataMatch[3]}-${dataMatch[2]}-${dataMatch[1]}`;
              const time = `${timePart.substring(0,2)}:${timePart.substring(2,4)}`;

              if (!newPontos[pis]) newPontos[pis] = [];
              let diaPonto = newPontos[pis].find(p => p.data === dateKey);
              if (!diaPonto) {
                diaPonto = { data: dateKey, batidas: [], isFalta: false };
                newPontos[pis].push(diaPonto);
              }
              if (!diaPonto.batidas.find(b => b.hora === time)) {
                diaPonto.batidas.push({ hora: time, origem: 'AFD' });
                diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
              }
            }
          }
        }
      });

      setData(prev => ({ ...prev, funcionarios: newFuncs, pontos: newPontos }));
    };
    event.target.value = '';
  };

  const timeToMinutes = (time: string): number => {
    if (!time || !time.includes(':')) return 0;
    const [h, m] = time.split(':').map(Number);
    return (h * 60) + m;
  };

  const minutesToTime = (mins: number): string => {
    const h = Math.floor(Math.abs(mins) / 60);
    const m = Math.abs(mins) % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  const calculateDay = (batidas: RegistroBatida[], jornadaMinutos: number = 480) => {
    if (!batidas || batidas.length < 2) return { trabalhadas: 0, saldo: 0 };
    let total = 0;
    const sorted = [...batidas].sort((a, b) => a.hora.localeCompare(b.hora));
    for (let i = 0; i < sorted.length - 1; i += 2) {
      const start = timeToMinutes(sorted[i].hora);
      const end = timeToMinutes(sorted[i+1].hora);
      if (end > start) total += (end - start);
    }
    return { trabalhadas: total, saldo: total - jornadaMinutos };
  };

  const filteredFuncs = useMemo(() => {
    return data.funcionarios.filter(f => 
      f.nome.toLowerCase().includes(searchTerm.toLowerCase()) || f.pis.includes(searchTerm)
    ).sort((a, b) => a.nome.localeCompare(b.nome));
  }, [data.funcionarios, searchTerm]);

  const activeEmployee = useMemo(() => 
    data.funcionarios.find(f => f.pis === activePis), 
    [data.funcionarios, activePis]
  );

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: lastDay }, (_, i) => `${year}-${month}-${(i + 1).toString().padStart(2, '0')}`);
  }, [selectedMonth]);

  const handleUpdateFuncData = (pis: string, updates: Partial<Funcionario>) => {
    setData(prev => ({
      ...prev,
      funcionarios: prev.funcionarios.map(f => f.pis === pis ? { ...f, ...updates } : f)
    }));
  };

  const handleSaveAjuste = () => {
    if (!modalAjuste || !motivoAjuste) return;
    const { pis, date, hora } = modalAjuste;
    const newPontos = { ...data.pontos };
    if (!newPontos[pis]) newPontos[pis] = [];
    let diaPonto = newPontos[pis].find(p => p.data === date);
    if (!diaPonto) {
      diaPonto = { data: date, batidas: [], isFalta: false };
      newPontos[pis].push(diaPonto);
    }
    diaPonto.batidas.push({ hora, origem: 'AJUSTE', obs: motivoAjuste });
    diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
    setData(prev => ({ ...prev, pontos: newPontos }));
    setModalAjuste(null);
    setMotivoAjuste('');
  };

  const handleExportPDF = () => {
    if (!activeEmployee) return;
    const doc = new jsPDF();
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();

    doc.setFontSize(22);
    doc.setFont("helvetica", "bold");
    doc.text("Espelho", 14, 20);
    doc.setFont("helvetica", "normal");
    doc.text("de Ponto Eletrônico", 14, 28);
    doc.setTextColor(150, 0, 0);
    doc.setFontSize(10);
    doc.text(`DE 01/${month}/${year} ATÉ ${lastDay}/${month}/${year}`, 145, 28);

    doc.setTextColor(0);
    doc.setDrawColor(200);
    doc.line(14, 32, 196, 32);

    doc.setFontSize(7);
    const infoY = 40;
    doc.setFont("helvetica", "bold"); doc.text("EMPRESA:", 14, infoY);
    doc.setFont("helvetica", "normal"); doc.text("ABC DA CONSTRUÇÃO ITU LTDA", 35, infoY);
    doc.setFont("helvetica", "bold"); doc.text("CNPJ:", 110, infoY);
    doc.setFont("helvetica", "normal"); doc.text("43.717.337/0001-27", 125, infoY);

    doc.setFont("helvetica", "bold"); doc.text("NOME:", 14, infoY + 6);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.nome.toUpperCase(), 35, infoY + 6);
    doc.setFont("helvetica", "bold"); doc.text("PIS/PASEP:", 110, infoY + 6);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.pis, 130, infoY + 6);
    doc.setFont("helvetica", "bold"); doc.text("ADMISSÃO:", 165, infoY + 6);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.admissao || "01/01/2024", 185, infoY + 6);

    doc.setFont("helvetica", "bold"); doc.text("CARGO:", 14, infoY + 12);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.cargo || "Vendedor", 35, infoY + 12);
    doc.setFont("helvetica", "bold"); doc.text("CPF:", 110, infoY + 12);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.cpf || "---", 120, infoY + 12);
    doc.setFont("helvetica", "bold"); doc.text("MATRÍCULA:", 165, infoY + 12);
    doc.setFont("helvetica", "normal"); doc.text(activeEmployee.matricula || "---", 185, infoY + 12);

    const tableData = currentMonthDays.map(day => {
      const p = data.pontos[activeEmployee.pis]?.find(x => x.data === day);
      const b = p?.batidas || [];
      const calc = calculateDay(b, activeEmployee.jornadaDiariaMinutos);
      const dt = new Date(day + 'T00:00:00');
      const weekday = dt.toLocaleDateString('pt-BR', { weekday: 'short' }).toUpperCase();

      return [
        `${day.split('-')[2]}/${month} - ${weekday}`,
        b.map(x => x.hora).join('  '),
        b[0]?.hora || '', b[1]?.hora || '', b[2]?.hora || '', b[3]?.hora || '',
        calc.trabalhadas > 0 ? minutesToTime(calc.trabalhadas) : '',
        '00008'
      ];
    });

    (doc as any).autoTable({
