              <ShieldCheck className="w-8 h-8 text-white" />
           </div>
           <div>
              <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tighter leading-none">Espelho de Ponto</h2>
              <p className="text-slate-400 font-bold text-[10px] uppercase tracking-widest mt-2">Motor de Parsing V6 — ABC Itu</p>
           </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="bg-slate-50 rounded-2xl px-5 py-3 border border-slate-200 flex items-center gap-4">
            <Calendar className="w-5 h-5 text-[#E30613]" />
            <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="bg-transparent text-xs font-black uppercase outline-none cursor-pointer" />
          </div>
          <label className="flex items-center gap-3 px-8 py-4 bg-[#0A1121] text-white rounded-2xl cursor-pointer hover:bg-black transition-all font-black text-xs uppercase tracking-widest shadow-xl">
