                                    </td>
                                    <td className="px-8 py-4 text-center">
                                       <button onClick={() => setModalAjuste({ pis: activePis!, date: day, hora: '08:00' })} className="p-2 text-slate-300 hover:text-[#E30613] transition-all bg-white border border-slate-100 rounded-xl shadow-sm opacity-0 group-hover:opacity-100">
                                          <Plus className="w-4 h-4" />
                                       </button>
                                    </td>
                                 </tr>
                              )
                           })}
                        </tbody>
                     </table>
                  </div>
               </div>
             </>
           ) : (
             <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner">
