                 <div>
                    <h3 className="text-3xl font-black text-slate-900 tracking-tighter uppercase leading-none">Inclusão Manual</h3>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">Tratativa de Ocorrência — Portaria 671</p>
                 </div>
              </div>
              <div className="space-y-6">
                 <div className="flex justify-between items-end gap-6">
                    <div className="flex-1 space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Horário</label>
                       <input type="time" value={modalAjuste.hora} onChange={(e) => setModalAjuste({...modalAjuste, hora: e.target.value})} className="w-full px-8 py-6 bg-slate-50 border border-slate-200 rounded-[2rem] font-black text-5xl text-slate-900 outline-none" />
                    </div>
                    <div className="text-right pb-4">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Data</p>
                       <p className="font-black text-slate-900 text-xl">{modalAjuste.date.split('-').reverse().join('/')}</p>
                    </div>
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Motivo do Ajuste</label>
                    <textarea placeholder="Justificativa legal..." value={motivoAjuste} onChange={(e) => setMotivoAjuste(e.target.value)} className="w-full px-8 py-5 bg-slate-50 border border-slate-200 rounded-[2rem] font-bold text-slate-700 min-h-[140px] outline-none" />
                 </div>
                 <button onClick={handleSaveAjuste} disabled={!motivoAjuste} className="w-full py-7 bg-[#E30613] text-white rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl disabled:opacity-30">GRAVAR TRATATIVA</button>
                 <button onClick={() => setModalAjuste(null)} className="w-full py-2 text-slate-400 font-black text-[11px] uppercase">Cancelar</button>
