                              const b = diaPonto?.batidas || [];
                              const calc = calculateDay(b, activeEmployee.jornadaDiariaMinutos);
                              const dt = new Date(day + 'T00:00:00');
                              const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                              return (
                                 <tr key={day} className={`group hover:bg-slate-50 transition-all ${isWeekend ? 'bg-slate-50/40' : ''}`}>
                                    <td className="px-8 py-4 border-r border-slate-50">
