                                    <td className="px-8 py-4">
                                       <div className="flex flex-wrap gap-2">
                                          {b.length > 0 ? b.map((bt, i) => (
                                            <span key={i} className={`text-[10px] font-black px-2 py-1 rounded-md border ${bt.origem === 'AJUSTE' ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-slate-50 border-slate-200 text-slate-700'}`}>{bt.hora}</span>
                                          )) : <span className="text-[10px] text-slate-200 font-bold uppercase italic">Sem registros</span>}
