                       <input type="time" value={modalAjuste.hora} onChange={(e) => setModalAjuste({...modalAjuste, hora: e.target.value})} className="w-full px-8 py-6 bg-slate-50 border border-slate-200 rounded-[2rem] font-black text-5xl text-slate-900 outline-none" />
