import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Clock, FileUp, UserCheck, Calendar, FileText, Trash2, 
  CheckCircle2, AlertTriangle, Edit3, X, History, Users, 
  Search, ShieldCheck, Save, Plus, Info, Fingerprint, 
  IdCard, Paperclip, FileSearch, AlertOctagon
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, MarcacaoPonto, ControleHoras, RegistroBatida, AnexoPonto } from '../types';

export const HorasPage: React.FC = () => {
  const [data, setData] = useState<ControleHoras>(() => {
    const saved = localStorage.getItem('abc_rh_ponto_v9_final');
    return saved ? JSON.parse(saved) : { funcionarios: [], pontos: {}, logs: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePis, setActivePis] = useState<string | null>(null);
  const [isEditingFunc, setIsEditingFunc] = useState(false);
  const [modalAjuste, setModalAjuste] = useState<{pis: string, date: string, hora: string} | null>(null);
  const [motivoAjuste, setMotivoAjuste] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    localStorage.setItem('abc_rh_ponto_v9_final', JSON.stringify(data));
  }, [data]);

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.replace(/\r\n/g,"\n").replace(/\r/g,"\n").split("\n");

      const newFuncsMap = new Map<string, Funcionario>();
      data.funcionarios.forEach(f => newFuncsMap.set(f.pis, f));

      const newPontos = { ...data.pontos };

      const RX_PUNCH = /^(\d{10})(\d{8})(\d{4})(\d{12})/;
      const RX_NAME_BLOCK = /([A-ZÀ-Ü]{2,}(?:\s+[A-ZÀ-Ü]{2,}){1,})/g;

      lines.forEach(line => {
        const trimmed = line.trim();
        if (trimmed.length < 15) return;

        const punchMatch = trimmed.match(RX_PUNCH);
        if (punchMatch) {
          const ddmmyyyy = punchMatch[2];
          const hhmm = punchMatch[3];
          const id12 = punchMatch[4];
          const pis = id12.slice(-11); 

          const dateKey = `${ddmmyyyy.slice(4,8)}-${ddmmyyyy.slice(2,4)}-${ddmmyyyy.slice(0,2)}`;
          const time = `${hhmm.slice(0,2)}:${hhmm.slice(2,4)}`;

          if (!newPontos[pis]) newPontos[pis] = [];
          let diaPonto = newPontos[pis].find(p => p.data === dateKey);
          if (!diaPonto) {
            diaPonto = { data: dateKey, batidas: [], isFalta: false };
            newPontos[pis].push(diaPonto);
          }
          if (!diaPonto.batidas.find(b => b.hora === time)) {
            diaPonto.batidas.push({ hora: time, origem: 'AFD' });
            diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
          }

          if (!newFuncsMap.has(pis)) {
            newFuncsMap.set(pis, {
              pis, nome: `ID ${id12}`, ativo: true, jornadaDiariaMinutos: 480,
              matricula: (newFuncsMap.size + 1).toString().padStart(4, '0')
            });
          }
        } else {
          // Lógica robusta para cadastro ignorando prefixos como A0/I0
          const allNumbers = trimmed.match(/\d{11,12}/g);
          if (allNumbers) {
            let matchName;
            RX_NAME_BLOCK.lastIndex = 0;
            while ((matchName = RX_NAME_BLOCK.exec(trimmed)) !== null) {
              const nameCandidate = matchName[1].trim();
              if (nameCandidate.length >= 6) {
                allNumbers.forEach(rawNum => {
                  const pis = rawNum.slice(-11);
                  const existing = newFuncsMap.get(pis);
                  if (!existing) {
                    newFuncsMap.set(pis, {
                      pis, nome: nameCandidate, ativo: true, jornadaDiariaMinutos: 480,
                      matricula: (newFuncsMap.size + 1).toString().padStart(4, '0')
                    });
                  } else if (existing.nome.startsWith("ID ") || existing.nome.length < 5) {
                    existing.nome = nameCandidate;
                  }
                });
              }
            }
          }
        }
      });

      setData(prev => ({ 
        ...prev, 
        funcionarios: Array.from(newFuncsMap.values()), 
        pontos: newPontos 
      }));
    };
    event.target.value = '';
  };

  const handleFileUpload = (pis: string, date: string, event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const base64 = e.target?.result as string;
      const newAnexo: AnexoPonto = {
        id: crypto.randomUUID(),
        nome: file.name,
        tipo: file.name.toLowerCase().includes('atestado') ? 'atestado' : 'justificativa',
        url: base64,
        dataEnvio: new Date().toISOString()
      };

      setData(prev => {
        const newPontos = { ...prev.pontos };
        if (!newPontos[pis]) newPontos[pis] = [];
        let dia = newPontos[pis].find(d => d.data === date);
        if (!dia) {
          dia = { data: date, batidas: [], isFalta: true };
          newPontos[pis].push(dia);
        }
        dia.anexos = [...(dia.anexos || []), newAnexo];
        dia.isFalta = true; // Marca como falta/atestado se subir anexo
        return { ...prev, pontos: newPontos };
      });
    };
    reader.readAsDataURL(file);
  };

  const calculateDay = (batidas: RegistroBatida[], jornadaMinutos: number = 480) => {
    if (!batidas || batidas.length < 2) return { trabalhadas: 0, saldo: 0 };
    let total = 0;
    const sorted = [...batidas].sort((a, b) => a.hora.localeCompare(b.hora));
    for (let i = 0; i < sorted.length - 1; i += 2) {
      const [h1, m1] = sorted[i].hora.split(':').map(Number);
      const [h2, m2] = sorted[i+1].hora.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return { trabalhadas: total, saldo: total - jornadaMinutos };
  };

  const formatMins = (mins: number) => {
    const h = Math.floor(Math.abs(mins) / 60);
    const m = Math.abs(mins) % 60;
    return `${mins < 0 ? '-' : ''}${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  const filteredFuncs = useMemo(() => {
    return data.funcionarios.filter(f => 
      f.nome.toLowerCase().includes(searchTerm.toLowerCase()) || f.pis.includes(searchTerm)
    ).sort((a, b) => a.nome.localeCompare(b.nome));
  }, [data.funcionarios, searchTerm]);

  const activeEmployee = useMemo(() => 
    data.funcionarios.find(f => f.pis === activePis), 
    [data.funcionarios, activePis]
  );

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: lastDay }, (_, i) => `${year}-${month}-${(i + 1).toString().padStart(2, '0')}`);
  }, [selectedMonth]);

  const handleSaveAjuste = () => {
    if (!modalAjuste || !motivoAjuste) return;
    const { pis, date, hora } = modalAjuste;
    setData(prev => {
      const newPontos = { ...prev.pontos };
      if (!newPontos[pis]) newPontos[pis] = [];
      let dia = newPontos[pis].find(d => d.data === date);
      if (!dia) {
        dia = { data: date, batidas: [], isFalta: false };
        newPontos[pis].push(dia);
      }
      dia.batidas.push({ hora, origem: 'AJUSTE', obs: motivoAjuste });
      dia.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
      return { ...prev, pontos: newPontos };
    });
    setModalAjuste(null);
    setMotivoAjuste('');
  };

  const handleExportPDF = () => {
    if (!activeEmployee) return;
    const doc = new jsPDF();
    const [year, month] = selectedMonth.split('-');
