    doc.setFontSize(8); doc.setFont("helvetica", "normal");
    doc.text(`Período: 01/${month}/${year} a ${lastDay}/${month}/${year}`, 14, 28);

    doc.setDrawColor(200); doc.line(14, 32, 196, 32);

    doc.setFontSize(9);
    doc.text(`Colaborador: ${activeEmployee.nome.toUpperCase()}`, 14, 40);
    doc.text(`PIS: ${activeEmployee.pis}`, 14, 45);
    doc.text(`Matrícula: ${activeEmployee.matricula || '---'}`, 110, 45);

    const tableData = currentMonthDays.map(day => {
      const diaPonto = data.pontos[activeEmployee.pis]?.find(x => x.data === day);
      const b = diaPonto?.batidas || [];
      const calc = calculateDay(b, activeEmployee.jornadaDiariaMinutos);
      const anexosCount = diaPonto?.anexos?.length || 0;

      return [
        day.split('-').reverse().join('/'),
        b.map(x => x.hora).join('  '),
        b[0]?.hora || '', b[1]?.hora || '', b[2]?.hora || '', b[3]?.hora || '',
        calc.trabalhadas > 0 ? formatMins(calc.trabalhadas) : '',
        anexosCount > 0 ? `SIM (${anexosCount})` : ''
      ];
    });

    (doc as any).autoTable({
      head: [['DATA', 'MARCAÇÕES', 'E1', 'S1', 'E2', 'S2', 'TOTAL', 'ANEXO']],
      body: tableData,
      startY: 55,
