              <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tighter leading-none">Gestão de Horas</h2>
              <p className="text-slate-400 font-bold text-[10px] uppercase tracking-widest mt-2">Unificação por PIS — ABC Itu</p>
           </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="bg-slate-50 rounded-2xl px-5 py-3 border border-slate-200 flex items-center gap-4">
