                        </thead>
                        <tbody className="divide-y divide-slate-100">
                           {currentMonthDays.map(day => {
                              const diaPonto = data.pontos[activePis!]?.find(x => x.data === day);
                              const b = diaPonto?.batidas || [];
                              const anexos = diaPonto?.anexos || [];
                              const calc = calculateDay(b, activeEmployee.jornadaDiariaMinutos);
                              const dt = new Date(day + 'T00:00:00');

                              return (
