                                       <span className="text-[9px] font-bold text-slate-400 uppercase block">{dt.toLocaleDateString('pt-BR', { weekday: 'short' }).toUpperCase()}</span>
                                    </td>
                                    <td className="px-8 py-5">
                                       <div className="flex flex-wrap gap-2">
                                          {b.map((bt, i) => (
