                              )
                           })}
                        </tbody>
                     </table>
                  </div>
               </div>
             </>
           ) : (
             <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner">
               <Fingerprint className="w-20 h-20 opacity-10 mb-6 animate-pulse" />
               <p className="text-2xl font-black text-slate-400 uppercase tracking-tighter">RH — Unificação de Ponto</p>
               <p className="text-[11px] font-bold text-slate-300 uppercase mt-2">Arraste o AFD para ler as batidas unificadas</p>
