        </div>
      </div>

      {modalAjuste && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-md">
           <div className="bg-white rounded-[3rem] shadow-2xl max-w-lg w-full p-12 space-y-8 animate-in zoom-in-95 duration-300">
              <div className="flex items-center gap-5 border-b border-slate-100 pb-8">
                 <div className="p-4 bg-red-50 rounded-3xl text-[#E30613] shadow-inner"><AlertOctagon /></div>
                 <div>
                    <h3 className="text-3xl font-black text-slate-900 tracking-tighter uppercase leading-none">Ajuste de Horário</h3>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">Correção de Batida Esquecida</p>
                 </div>
              </div>
              <div className="space-y-6">
                 <div className="flex justify-between items-end gap-6">
                    <div className="flex-1 space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Nova Batida</label>
                       <input type="time" value={modalAjuste.hora} onChange={(e) => setModalAjuste({...modalAjuste, hora: e.target.value})} className="w-full px-8 py-6 bg-slate-50 border border-slate-200 rounded-[2rem] font-black text-5xl text-slate-900 outline-none" />
                    </div>
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Justificativa</label>
                    <textarea placeholder="Ex: Esquecimento, Problema no REP..." value={motivoAjuste} onChange={(e) => setMotivoAjuste(e.target.value)} className="w-full px-8 py-5 bg-slate-50 border border-slate-200 rounded-[2rem] font-bold text-slate-700 min-h-[140px] outline-none" />
                 </div>
                 <button onClick={handleSaveAjuste} disabled={!motivoAjuste} className="w-full py-7 bg-emerald-600 text-white rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl disabled:opacity-30">GRAVAR AJUSTE</button>
                 <button onClick={() => setModalAjuste(null)} className="w-full py-2 text-slate-400 font-black text-[11px] uppercase">Cancelar</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Clock, FileUp, UserCheck, Calendar, FileText, Trash2, 
  CheckCircle2, AlertTriangle, Edit3, X, History, Users, 
  Search, ShieldCheck, Save, Plus, Info, Fingerprint, 
  IdCard, Paperclip, FileSearch, AlertOctagon, FileCheck
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, MarcacaoPonto, ControleHoras, RegistroBatida, AnexoPonto } from '../types';

export const HorasPage: React.FC = () => {
  const [data, setData] = useState<ControleHoras>(() => {
    const saved = localStorage.getItem('abc_rh_ponto_v10_final');
    return saved ? JSON.parse(saved) : { funcionarios: [], pontos: {}, logs: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePis, setActivePis] = useState<string | null>(null);
  const [isEditingFunc, setIsEditingFunc] = useState(false);
  const [modalAjuste, setModalAjuste] = useState<{pis: string, date: string, hora: string} | null>(null);
  const [motivoAjuste, setMotivoAjuste] = useState('');

  useEffect(() => {
    localStorage.setItem('abc_rh_ponto_v10_final', JSON.stringify(data));
  }, [data]);

  // FUNÇÃO DE NORMALIZAÇÃO DE PIS (Garante unicidade)
  const normalizePis = (raw: string): string => {
    const numbers = raw.replace(/\D/g, ''); // Remove letras A, I, etc.
    return numbers.slice(-11); // Mantém apenas os 11 dígitos do PIS
  };

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.replace(/\r\n/g,"\n").replace(/\r/g,"\n").split("\n");

      const funcsMap = new Map<string, Funcionario>();
      data.funcionarios.forEach(f => funcsMap.set(normalizePis(f.pis), f));

      const newPontos = { ...data.pontos };

      // Regex para Batida: NSR(10) + Tipo(1) + Data(8) + Hora(4) + PIS(12)
      const RX_PUNCH = /^(\d{10})3(\d{8})(\d{4})(\d{12})/;
      const RX_NAME_BLOCK = /([A-ZÀ-Ü]{3,}(?:\s+[A-ZÀ-Ü]{2,}){1,})/g;

      lines.forEach(line => {
        const trimmed = line.trim();
        if (trimmed.length < 15) return;

        const punchMatch = trimmed.match(RX_PUNCH);
        if (punchMatch) {
          const ddmmyyyy = punchMatch[2];
          const hhmm = punchMatch[3];
          const pis = normalizePis(punchMatch[4]);

          const dateKey = `${ddmmyyyy.slice(4,8)}-${ddmmyyyy.slice(2,4)}-${ddmmyyyy.slice(0,2)}`;
          const time = `${hhmm.slice(0,2)}:${hhmm.slice(2,4)}`;

          if (!newPontos[pis]) newPontos[pis] = [];
          let diaPonto = newPontos[pis].find(p => p.data === dateKey);
          if (!diaPonto) {
            diaPonto = { data: dateKey, batidas: [], isFalta: false };
            newPontos[pis].push(diaPonto);
          }
          if (!diaPonto.batidas.find(b => b.hora === time)) {
            diaPonto.batidas.push({ hora: time, origem: 'AFD' });
            diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
          }

          if (!funcsMap.has(pis)) {
            funcsMap.set(pis, {
              pis, nome: `COLABORADOR ${pis}`, ativo: true, jornadaDiariaMinutos: 480,
              matricula: (funcsMap.size + 1).toString().padStart(4, '0')
            });
          }
        } else {
          // Captura de nomes em linhas de cadastro (Tipo 5 ou similar)
          const allNumbers = trimmed.match(/\d{11,12}/g);
          if (allNumbers) {
            let matchName;
            RX_NAME_BLOCK.lastIndex = 0;
            while ((matchName = RX_NAME_BLOCK.exec(trimmed)) !== null) {
              const nameCandidate = matchName[1].trim();
              if (nameCandidate.length >= 6) {
                allNumbers.forEach(rawNum => {
                  const pis = normalizePis(rawNum);
                  const existing = funcsMap.get(pis);
                  if (!existing) {
                    funcsMap.set(pis, {
                      pis, nome: nameCandidate, ativo: true, jornadaDiariaMinutos: 480,
                      matricula: (funcsMap.size + 1).toString().padStart(4, '0')
                    });
                  } else if (existing.nome.includes("COLABORADOR") || existing.nome.length < 5) {
                    existing.nome = nameCandidate;
                  }
                });
              }
            }
          }
        }
      });

      setData(prev => ({ 
        ...prev, 
        funcionarios: Array.from(funcsMap.values()), 
        pontos: newPontos 
      }));
    };
    event.target.value = '';
  };

  const handleFileUpload = (pis: string, date: string, event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const base64 = e.target?.result as string;
      const newAnexo: AnexoPonto = {
        id: crypto.randomUUID(),
        nome: file.name,
        tipo: 'atestado',
        url: base64,
        dataEnvio: new Date().toISOString()
      };

      setData(prev => {
        const newPontos = { ...prev.pontos };
        if (!newPontos[pis]) newPontos[pis] = [];
        let dia = newPontos[pis].find(d => d.data === date);
        if (!dia) {
          dia = { data: date, batidas: [], isFalta: true };
          newPontos[pis].push(dia);
        }
        dia.anexos = [...(dia.anexos || []), newAnexo];
        dia.isFalta = true;
        return { ...prev, pontos: newPontos };
      });
    };
    reader.readAsDataURL(file);
  };

  const calculateDay = (batidas: RegistroBatida[], jornadaMinutos: number = 480) => {
    if (!batidas || batidas.length < 2) return { trabalhadas: 0, saldo: 0 };
    let total = 0;
    const sorted = [...batidas].sort((a, b) => a.hora.localeCompare(b.hora));
    for (let i = 0; i < sorted.length - 1; i += 2) {
      const [h1, m1] = sorted[i].hora.split(':').map(Number);
      const [h2, m2] = sorted[i+1].hora.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return { trabalhadas: total, saldo: total - jornadaMinutos };
  };

  const formatMins = (mins: number) => {
    const h = Math.floor(Math.abs(mins) / 60);
    const m = Math.abs(mins) % 60;
    return `${mins < 0 ? '-' : ''}${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  const handleExportPDF = () => {
    if (!activeEmployee) return;
    const doc = new jsPDF();
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();

    doc.setFontSize(20); doc.setFont("helvetica", "bold");
    doc.text("Espelho de Ponto Eletrônico", 14, 20);
    doc.setFontSize(8); doc.setFont("helvetica", "normal");
    doc.text(`Período: 01/${month}/${year} a ${lastDay}/${month}/${year}`, 14, 27);
    doc.line(14, 30, 196, 30);

    doc.setFontSize(9);
    doc.text(`Colaborador: ${activeEmployee.nome.toUpperCase()}`, 14, 38);
    doc.text(`PIS: ${activeEmployee.pis}`, 14, 43);
    doc.text(`Empresa: ABC DA CONSTRUÇÃO ITU`, 110, 38);

    const tableData = currentMonthDays.map(day => {
      const diaPonto = data.pontos[activeEmployee.pis]?.find(x => x.data === day);
      const b = diaPonto?.batidas || [];
      const calc = calculateDay(b, activeEmployee.jornadaDiariaMinutos);
      return [
        day.split('-').reverse().join('/'),
        b.map(x => x.hora).join('  '),
        b[0]?.hora || '', b[1]?.hora || '', b[2]?.hora || '', b[3]?.hora || '',
        calc.trabalhadas > 0 ? formatMins(calc.trabalhadas) : '',
        diaPonto?.anexos?.length ? 'SIM' : ''
      ];
    });

    (doc as any).autoTable({
      head: [['DATA', 'MARCAÇÕES', 'E1', 'S1', 'E2', 'S2', 'TOTAL', 'OBS']],
      body: tableData,
      startY: 50,
      theme: 'grid',
      styles: { fontSize: 7, cellPadding: 1.5 },
      headStyles: { fillColor: [227, 6, 19] }
    });

    // PÁGINA 2: JUSTIFICATIVAS E ANEXOS
    const anexosDia = currentMonthDays.filter(day => {
        const dia = data.pontos[activeEmployee.pis]?.find(x => x.data === day);
        return (dia?.anexos?.length || 0) > 0 || dia?.batidas.some(b => b.origem === 'AJUSTE');
    });

    if (anexosDia.length > 0) {
        doc.addPage();
        doc.setFontSize(16); doc.text("Justificativas e Ocorrências", 14, 20);
        doc.setFontSize(8);
        let y = 30;
        anexosDia.forEach(day => {
            const dia = data.pontos[activeEmployee.pis]?.find(x => x.data === day);
            doc.setFont("helvetica", "bold");
            doc.text(`DATA: ${day.split('-').reverse().join('/')}`, 14, y);
            doc.setFont("helvetica", "normal");
            y += 5;
            dia?.batidas.filter(b => b.origem === 'AJUSTE').forEach(b => {
                doc.text(`- Ajuste manual às ${b.hora}: ${b.obs || 'Sem justificativa'}`, 18, y);
                y += 5;
            });
            dia?.anexos?.forEach(anexo => {
                doc.text(`- Documento anexo: ${anexo.nome} (Submetido em ${new Date(anexo.dataEnvio).toLocaleDateString()})`, 18, y);
                y += 5;
            });
            y += 5;
            if (y > 270) { doc.addPage(); y = 20; }
        });
    }

    doc.save(`Ponto_ABC_ITU_${activeEmployee.nome}.pdf`);
  };

  const filteredFuncs = useMemo(() => {
    return data.funcionarios.filter(f => 
      f.nome.toLowerCase().includes(searchTerm.toLowerCase()) || f.pis.includes(searchTerm)
    ).sort((a, b) => a.nome.localeCompare(b.nome));
  }, [data.funcionarios, searchTerm]);

  const activeEmployee = useMemo(() => 
    data.funcionarios.find(f => f.pis === activePis), 
    [data.funcionarios, activePis]
  );

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: lastDay }, (_, i) => `${year}-${month}-${(i + 1).toString().padStart(2, '0')}`);
  }, [selectedMonth]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col lg:flex-row justify-between items-center gap-6 bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl">
        <div className="flex items-center gap-5">
           <div className="bg-[#E30613] p-4 rounded-3xl shadow-lg">
              <ShieldCheck className="w-8 h-8 text-white" />
           </div>
           <div>
              <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tighter leading-none">Ponto Unificado</h2>
              <p className="text-slate-400 font-bold text-[10px] uppercase tracking-widest mt-2">Filtro Numérico Estrito — ABC Itu</p>
           </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="bg-slate-50 rounded-2xl px-5 py-3 border border-slate-200 flex items-center gap-4">
            <Calendar className="w-5 h-5 text-[#E30613]" />
            <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="bg-transparent text-xs font-black uppercase outline-none cursor-pointer" />
          </div>
          <label className="flex items-center gap-3 px-8 py-4 bg-[#0A1121] text-white rounded-2xl cursor-pointer hover:bg-black transition-all font-black text-xs uppercase tracking-widest shadow-xl">
            <FileUp className="w-5 h-5 text-[#E30613]" /> LER AFD
            <input type="file" className="hidden" accept=".txt" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="lg:col-span-1">
          <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm sticky top-24">
            <div className="relative mb-6">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
              <input type="text" placeholder="Buscar PIS ou Nome..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl text-xs font-bold outline-none" />
            </div>
            <div className="space-y-2 max-h-[60vh] overflow-y-auto custom-scrollbar pr-2">
              {filteredFuncs.map(f => (
                <button 
                  key={f.pis}
                  onClick={() => setActivePis(f.pis)}
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePis === f.pis ? 'bg-[#E30613] text-white shadow-lg border-[#E30613]' : 'bg-slate-50 border-transparent text-slate-600 hover:bg-slate-100'}`}
                >
                  <p className="text-[10px] font-black uppercase truncate leading-tight">{f.nome}</p>
                  <p className={`text-[8px] font-bold ${activePis === f.pis ? 'text-white/60' : 'text-slate-400'}`}>PIS: {f.pis}</p>
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="lg:col-span-3 space-y-6">
           {activeEmployee ? (
             <>
               <div className="bg-white border border-slate-200 rounded-[2.5rem] shadow-xl overflow-hidden">
                  <div className="p-8 border-b border-slate-100 bg-slate-50/30 flex flex-col md:flex-row justify-between items-center gap-6">
                     <div className="flex items-center gap-6">
                        <div className="w-16 h-16 bg-white rounded-3xl shadow-sm flex items-center justify-center border border-slate-100">
                           <IdCard className="w-8 h-8 text-[#E30613]" />
                        </div>
                        <div>
                           <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter leading-none">{activeEmployee.nome}</h3>
                           <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-2">PIS: {activeEmployee.pis} | Matrícula: {activeEmployee.matricula || '---'}</p>
                        </div>
                     </div>
                     <button onClick={handleExportPDF} className="flex items-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-2xl text-xs font-black uppercase tracking-widest shadow-xl hover:bg-black transition-all">
                        <FileCheck className="w-5 h-5 text-[#E30613]" /> Gerar Espelho Completo
                     </button>
                  </div>
               </div>

               <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                  <div className="overflow-x-auto">
                     <table className="w-full text-left">
                        <thead>
                           <tr className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-widest">
                              <th className="px-8 py-6">Data</th>
                              <th className="px-8 py-6">Batidas</th>
                              <th className="px-4 py-6 text-center">E1</th>
                              <th className="px-4 py-6 text-center">S1</th>
                              <th className="px-4 py-6 text-center">E2</th>
                              <th className="px-4 py-6 text-center">S2</th>
                              <th className="px-8 py-6 text-right">Saldo</th>
                              <th className="px-8 py-6 text-center">Ações</th>
                           </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                           {currentMonthDays.map(day => {
                              const diaPonto = data.pontos[activePis!]?.find(x => x.data === day);
                              const b = diaPonto?.batidas || [];
                              const anexos = diaPonto?.anexos || [];
                              const calc = calculateDay(b, activeEmployee.jornadaDiariaMinutos);
                              const dt = new Date(day + 'T00:00:00');

                              return (
                                 <tr key={day} className="group hover:bg-slate-50 transition-all">
                                    <td className="px-8 py-5 border-r border-slate-50">
                                       <span className="text-sm font-black text-slate-900">{day.split('-').reverse().join('/')}</span>
                                       <span className="text-[9px] font-bold text-slate-400 uppercase block">{dt.toLocaleDateString('pt-BR', { weekday: 'short' }).toUpperCase()}</span>
                                    </td>
                                    <td className="px-8 py-5">
                                       <div className="flex flex-wrap gap-2">
                                          {b.map((bt, i) => (
                                            <span key={i} className={`text-[10px] font-black px-2 py-1 rounded-md border ${bt.origem === 'AJUSTE' ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-slate-50 border-slate-200 text-slate-700'}`}>{bt.hora}</span>
                                          ))}
                                          <button onClick={() => setModalAjuste({ pis: activePis!, date: day, hora: '08:00' })} className="p-1 text-slate-300 hover:text-emerald-600 transition-all">
                                            <Plus className="w-4 h-4" />
                                          </button>
                                       </div>
                                    </td>
                                    <td className="px-4 py-5 text-center text-[11px] font-black text-slate-400">{b[0]?.hora || '--:--'}</td>
                                    <td className="px-4 py-5 text-center text-[11px] font-black text-slate-400">{b[1]?.hora || '--:--'}</td>
                                    <td className="px-4 py-5 text-center text-[11px] font-black text-slate-400">{b[2]?.hora || '--:--'}</td>
                                    <td className="px-4 py-5 text-center text-[11px] font-black text-slate-400">{b[3]?.hora || '--:--'}</td>
                                    <td className={`px-8 py-5 text-right font-black text-[11px] ${calc.saldo < 0 ? 'text-[#E30613]' : 'text-emerald-600'}`}>
                                       {formatMins(calc.saldo)}
                                    </td>
                                    <td className="px-8 py-5 text-center">
                                       <div className="flex items-center justify-center gap-2">
                                          <label className="cursor-pointer p-2 hover:bg-slate-100 rounded-lg transition-all relative">
                                             <Paperclip className={`w-4 h-4 ${anexos.length > 0 ? 'text-emerald-600' : 'text-slate-300'}`} />
                                             <input type="file" className="hidden" onChange={(e) => handleFileUpload(activePis!, day, e)} />
                                             {anexos.length > 0 && <span className="absolute top-0 right-0 w-2 h-2 bg-[#E30613] rounded-full"></span>}
                                          </label>
                                       </div>
                                    </td>
                                 </tr>
                              )
                           })}
                        </tbody>
                     </table>
                  </div>
               </div>
             </>
           ) : (
             <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner">
               <Fingerprint className="w-20 h-20 opacity-10 mb-6 animate-pulse" />
               <p className="text-2xl font-black text-slate-400 uppercase tracking-tighter">RH — Auditoria de REP</p>
               <p className="text-[11px] font-bold text-slate-300 uppercase mt-2">Arraste o AFD para consolidar o espelho</p>
             </div>
           )}
        </div>
      </div>

      {modalAjuste && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-md">
           <div className="bg-white rounded-[3rem] shadow-2xl max-w-lg w-full p-12 space-y-8 animate-in zoom-in-95 duration-300">
              <div className="flex items-center gap-5 border-b border-slate-100 pb-8">
                 <div className="p-4 bg-red-50 rounded-3xl text-[#E30613] shadow-inner"><AlertOctagon /></div>
                 <div>
                    <h3 className="text-3xl font-black text-slate-900 tracking-tighter uppercase leading-none">Ajuste de Ponto</h3>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">Inclusão de Batida não Registrada</p>
                 </div>
              </div>
              <div className="space-y-6">
                 <div className="flex justify-between items-end gap-6">
                    <div className="flex-1 space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Horário</label>
                       <input type="time" value={modalAjuste.hora} onChange={(e) => setModalAjuste({...modalAjuste, hora: e.target.value})} className="w-full px-8 py-6 bg-slate-50 border border-slate-200 rounded-[2rem] font-black text-5xl text-slate-900 outline-none" />
                    </div>
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Justificativa</label>
                    <textarea placeholder="Ex: Problema no biométrico, viagem a serviço..." value={motivoAjuste} onChange={(e) => setMotivoAjuste(e.target.value)} className="w-full px-8 py-5 bg-slate-50 border border-slate-200 rounded-[2rem] font-bold text-slate-700 min-h-[140px] outline-none" />
                 </div>
                 <button onClick={() => {
                    if(!motivoAjuste) return alert("Justificativa obrigatória!");
                    const { pis, date, hora } = modalAjuste;
                    setData(prev => {
                      const newPontos = { ...prev.pontos };
                      if (!newPontos[pis]) newPontos[pis] = [];
                      let dia = newPontos[pis].find(d => d.data === date);
                      if (!dia) { dia = { data: date, batidas: [], isFalta: false }; newPontos[pis].push(dia); }
                      dia.batidas.push({ hora, origem: 'AJUSTE', obs: motivoAjuste });
                      dia.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
                      return { ...prev, pontos: newPontos };
                    });
                    setModalAjuste(null);
                    setMotivoAjuste('');
                 }} className="w-full py-7 bg-emerald-600 text-white rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl">SALVAR TRATATIVA</button>
                 <button onClick={() => setModalAjuste(null)} className="w-full py-2 text-slate-400 font-black text-[11px] uppercase">Fechar</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, Calendar, FileText, Search, ShieldCheck, Plus, 
  Fingerprint, IdCard, Paperclip, AlertOctagon, FileCheck, X
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, ControleHoras, RegistroBatida, AnexoPonto } from '../types';

export const HorasPage: React.FC = () => {
  const [data, setData] = useState<ControleHoras>(() => {
    const saved = localStorage.getItem('abc_rh_ponto_v11');
    return saved ? JSON.parse(saved) : { funcionarios: [], pontos: {}, logs: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePis, setActivePis] = useState<string | null>(null);
  const [modalAjuste, setModalAjuste] = useState<{pis: string, date: string, hora: string} | null>(null);
  const [motivoAjuste, setMotivoAjuste] = useState('');

  useEffect(() => {
    localStorage.setItem('abc_rh_ponto_v11', JSON.stringify(data));
  }, [data]);

  // Função que realmente identifica o PIS no arquivo iDClass
  const extractPis = (line: string): string | null => {
    const numbers = line.match(/\d{11,12}/g);
    if (!numbers) return null;
    // O PIS no AFD costuma ser o último número longo da linha ou ter 11-12 dígitos
    return numbers[numbers.length - 1].slice(-11); 
  };

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/);

      const funcsMap = new Map<string, Funcionario>();
      data.funcionarios.forEach(f => funcsMap.set(f.pis, f));

      const newPontos = { ...data.pontos };

      lines.forEach(line => {
        const trimmed = line.trim();
        if (trimmed.length < 20) return;

        // IDENTIFICAÇÃO DE BATIDA (Tipo 3 no padrão AFD)
        // Normalmente: NSR(10) + TIPO(1) + DATA(8) + HORA(4) + PIS(12)
        // Exemplo: 00000000013010120260909000065368359055
        const punchMatch = trimmed.match(/^(\d{10})3(\d{8})(\d{4})(\d{11,12})/);

        if (punchMatch) {
          const ddmmyyyy = punchMatch[2];
          const hhmm = punchMatch[3];
          const pis = punchMatch[4].slice(-11);

          const dateKey = `${ddmmyyyy.slice(4,8)}-${ddmmyyyy.slice(2,4)}-${ddmmyyyy.slice(0,2)}`;
          const time = `${hhmm.slice(0,2)}:${hhmm.slice(2,4)}`;

          if (!newPontos[pis]) newPontos[pis] = [];
          let diaPonto = newPontos[pis].find(p => p.data === dateKey);
          if (!diaPonto) {
            diaPonto = { data: dateKey, batidas: [], isFalta: false };
            newPontos[pis].push(diaPonto);
          }
          if (!diaPonto.batidas.find(b => b.hora === time)) {
            diaPonto.batidas.push({ hora: time, origem: 'AFD' });
            diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
          }

          if (!funcsMap.has(pis)) {
            funcsMap.set(pis, {
              pis, nome: `COLABORADOR ${pis}`, ativo: true, jornadaDiariaMinutos: 480,
              matricula: (funcsMap.size + 1).toString().padStart(4, '0')
            });
          }
        } else {
          // CADASTRO DE NOME (Tipo 5)
          const nameBlock = trimmed.match(/([A-ZÀ-Ü]{3,}(?:\s+[A-ZÀ-Ü]{2,})+)/);
          const pisInLine = extractPis(trimmed);

          if (nameBlock && pisInLine) {
            const name = nameBlock[1].trim();
            const existing = funcsMap.get(pisInLine);
            if (!existing) {
              funcsMap.set(pisInLine, {
                pis: pisInLine, nome: name, ativo: true, jornadaDiariaMinutos: 480,
                matricula: (funcsMap.size + 1).toString().padStart(4, '0')
              });
            } else if (existing.nome.includes("COLABORADOR") || existing.nome.length < name.length) {
              existing.nome = name;
            }
          }
        }
      });

      setData(prev => ({ 
        ...prev, 
        funcionarios: Array.from(funcsMap.values()), 
        pontos: newPontos 
      }));
    };
    event.target.value = '';
  };

  const handleFileUpload = (pis: string, date: string, event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const base64 = e.target?.result as string;
      const newAnexo: AnexoPonto = {
        id: crypto.randomUUID(),
        nome: file.name,
        tipo: 'atestado',
        url: base64,
        dataEnvio: new Date().toISOString()
      };

      setData(prev => {
        const newPontos = { ...prev.pontos };
        if (!newPontos[pis]) newPontos[pis] = [];
        let dia = newPontos[pis].find(d => d.data === date);
        if (!dia) { dia = { data: date, batidas: [], isFalta: true }; newPontos[pis].push(dia); }
        dia.anexos = [...(dia.anexos || []), newAnexo];
        dia.isFalta = true;
        return { ...prev, pontos: newPontos };
      });
    };
    reader.readAsDataURL(file);
  };

  const calculateDay = (batidas: RegistroBatida[], jornadaMinutos: number = 480) => {
    if (!batidas || batidas.length < 2) return { trabalhadas: 0, saldo: 0 };
    let total = 0;
    const sorted = [...batidas].sort((a, b) => a.hora.localeCompare(b.hora));
    for (let i = 0; i < sorted.length - 1; i += 2) {
      const [h1, m1] = sorted[i].hora.split(':').map(Number);
      const [h2, m2] = sorted[i+1].hora.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return { trabalhadas: total, saldo: total - jornadaMinutos };
  };

  const formatMins = (mins: number) => {
    const h = Math.floor(Math.abs(mins) / 60);
    const m = Math.abs(mins) % 60;
    return `${mins < 0 ? '-' : ''}${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  const handleExportPDF = () => {
    if (!activeEmployee) return;
    const doc = new jsPDF();
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();

    doc.setFontSize(18); doc.setFont("helvetica", "bold");
    doc.text("Espelho de Ponto - ABC Itu", 14, 20);
    doc.setFontSize(8); doc.setFont("helvetica", "normal");
    doc.text(`Período: 01/${month}/${year} a ${lastDay}/${month}/${year}`, 14, 27);

    doc.setFontSize(9);
    doc.text(`Colaborador: ${activeEmployee.nome.toUpperCase()}`, 14, 38);
    doc.text(`PIS: ${activeEmployee.pis}`, 14, 43);

    const tableData = currentMonthDays.map(day => {
      const diaPonto = data.pontos[activeEmployee.pis]?.find(x => x.data === day);
      const b = diaPonto?.batidas || [];
      const calc = calculateDay(b, activeEmployee.jornadaDiariaMinutos);
      return [
        day.split('-').reverse().join('/'),
        b.map(x => x.hora).join('  '),
        b[0]?.hora || '', b[1]?.hora || '', b[2]?.hora || '', b[3]?.hora || '',
        calc.trabalhadas > 0 ? formatMins(calc.trabalhadas) : '',
        diaPonto?.anexos?.length ? 'SIM' : ''
      ];
    });

    (doc as any).autoTable({
      head: [['DATA', 'BATIDAS', 'E1', 'S1', 'E2', 'S2', 'TOTAL', 'ANEXO']],
      body: tableData,
      startY: 50,
      theme: 'grid',
      styles: { fontSize: 7, cellPadding: 1.5 },
      headStyles: { fillColor: [10, 17, 33] }
    });

    doc.save(`Ponto_${activeEmployee.nome}.pdf`);
  };

  const filteredFuncs = useMemo(() => {
    return data.funcionarios.filter(f => 
      f.nome.toLowerCase().includes(searchTerm.toLowerCase()) || f.pis.includes(searchTerm)
    ).sort((a, b) => a.nome.localeCompare(b.nome));
  }, [data.funcionarios, searchTerm]);

  const activeEmployee = useMemo(() => 
    data.funcionarios.find(f => f.pis === activePis), 
    [data.funcionarios, activePis]
  );

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: lastDay }, (_, i) => `${year}-${month}-${(i + 1).toString().padStart(2, '0')}`);
  }, [selectedMonth]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col lg:flex-row justify-between items-center gap-6 bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl">
        <div className="flex items-center gap-5">
           <div className="bg-[#E30613] p-4 rounded-3xl shadow-lg">
              <ShieldCheck className="w-8 h-8 text-white" />
           </div>
           <div>
              <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tighter leading-none">Gestão de Horas</h2>
              <p className="text-slate-400 font-bold text-[10px] uppercase tracking-widest mt-2">Unificação por PIS — ABC Itu</p>
           </div>
        </div>

        <div className="flex items-center gap-3">
          <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="bg-slate-50 border border-slate-200 rounded-2xl px-5 py-3 text-xs font-black outline-none" />
          <label className="flex items-center gap-3 px-8 py-4 bg-[#0A1121] text-white rounded-2xl cursor-pointer hover:bg-black transition-all font-black text-xs uppercase shadow-xl">
            <FileUp className="w-5 h-5 text-[#E30613]" /> LER AFD
            <input type="file" className="hidden" accept=".txt" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="lg:col-span-1">
          <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm sticky top-24">
            <div className="relative mb-6">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
              <input type="text" placeholder="Buscar..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl text-xs font-bold outline-none" />
            </div>
            <div className="space-y-2 max-h-[60vh] overflow-y-auto custom-scrollbar pr-2">
              {filteredFuncs.map(f => (
                <button 
