                  onClick={() => setActivePis(f.pis)}
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePis === f.pis ? 'bg-[#E30613] text-white shadow-lg border-[#E30613]' : 'bg-slate-50 border-transparent text-slate-600 hover:bg-slate-100'}`}
                >
                  <p className="text-[10px] font-black uppercase truncate leading-tight">{f.nome}</p>
                  <p className={`text-[8px] font-bold ${activePis === f.pis ? 'text-white/60' : 'text-slate-400'}`}>PIS: {f.pis}</p>
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="lg:col-span-3 space-y-6">
           {activeEmployee ? (
             <>
               <div className="bg-white border border-slate-200 rounded-[2.5rem] shadow-xl overflow-hidden p-8 flex flex-col md:flex-row justify-between items-center gap-6">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-white rounded-3xl shadow-sm flex items-center justify-center border border-slate-100"><IdCard className="w-8 h-8 text-[#E30613]" /></div>
                     <div>
                        <h3 className="text-xl font-black text-slate-900 uppercase leading-none">{activeEmployee.nome}</h3>
                        <p className="text-[10px] font-bold text-slate-400 uppercase mt-2">PIS: {activeEmployee.pis}</p>
                     </div>
                  </div>
                  <button onClick={handleExportPDF} className="flex items-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-2xl text-xs font-black uppercase shadow-xl hover:bg-black">
                     <FileCheck className="w-5 h-5 text-[#E30613]" /> Exportar PDF
                  </button>
               </div>

               <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                  <table className="w-full text-left">
                     <thead>
                        <tr className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-widest">
                           <th className="px-8 py-6">Data</th>
                           <th className="px-8 py-6">Batidas</th>
                           <th className="px-4 py-6 text-center">E1/S1</th>
                           <th className="px-4 py-6 text-center">E2/S2</th>
                           <th className="px-8 py-6 text-right">Saldo</th>
                           <th className="px-8 py-6 text-center">Anexo</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-slate-100">
                        {currentMonthDays.map(day => {
                           const diaPonto = data.pontos[activePis!]?.find(x => x.data === day);
                           const b = diaPonto?.batidas || [];
                           const anexos = diaPonto?.anexos || [];
                           const calc = calculateDay(b, activeEmployee.jornadaDiariaMinutos);
                           const dt = new Date(day + 'T00:00:00');

                           return (
                              <tr key={day} className="group hover:bg-slate-50 transition-all">
                                 <td className="px-8 py-5">
                                    <span className="text-sm font-black text-slate-900">{day.split('-').reverse().join('/')}</span>
                                    <span className="text-[9px] font-bold text-slate-400 uppercase block">{dt.toLocaleDateString('pt-BR', { weekday: 'short' })}</span>
                                 </td>
                                 <td className="px-8 py-5">
                                    <div className="flex flex-wrap gap-2">
                                       {b.map((bt, i) => (
                                         <span key={i} className={`text-[10px] font-black px-2 py-1 rounded-md border ${bt.origem === 'AJUSTE' ? 'bg-amber-50 border-amber-200' : 'bg-slate-50 border-slate-200'}`}>{bt.hora}</span>
                                       ))}
                                       <button onClick={() => setModalAjuste({ pis: activePis!, date: day, hora: '08:00' })} className="p-1 text-slate-300 hover:text-emerald-600"><Plus className="w-4 h-4" /></button>
                                    </div>
                                 </td>
                                 <td className="px-4 py-5 text-center text-[11px] font-black text-slate-400">
                                    {b[0]?.hora || '--:--'} / {b[1]?.hora || '--:--'}
                                 </td>
                                 <td className="px-4 py-5 text-center text-[11px] font-black text-slate-400">
                                    {b[2]?.hora || '--:--'} / {b[3]?.hora || '--:--'}
                                 </td>
                                 <td className={`px-8 py-5 text-right font-black text-[11px] ${calc.saldo < 0 ? 'text-[#E30613]' : 'text-emerald-600'}`}>
                                    {formatMins(calc.saldo)}
                                 </td>
                                 <td className="px-8 py-5 text-center">
                                    <label className="cursor-pointer p-2 hover:bg-slate-100 rounded-lg transition-all relative inline-block">
                                       <Paperclip className={`w-4 h-4 ${anexos.length > 0 ? 'text-emerald-600' : 'text-slate-300'}`} />
                                       <input type="file" className="hidden" onChange={(e) => handleFileUpload(activePis!, day, e)} />
                                       {anexos.length > 0 && <span className="absolute top-0 right-0 w-2 h-2 bg-[#E30613] rounded-full"></span>}
                                    </label>
                                 </td>
                              </tr>
                           )
                        })}
                     </tbody>
                  </table>
               </div>
             </>
           ) : (
             <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner">
               <Fingerprint className="w-20 h-20 opacity-10 mb-6 animate-pulse" />
               <p className="text-2xl font-black text-slate-400 uppercase tracking-tighter">ABC RH — Auditar AFD</p>
             </div>
           )}
        </div>
      </div>

      {modalAjuste && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-md">
           <div className="bg-white rounded-[3rem] shadow-2xl max-w-lg w-full p-12 space-y-8 animate-in zoom-in-95 duration-300">
              <div className="flex items-center gap-5 border-b border-slate-100 pb-8">
                 <div className="p-4 bg-red-50 rounded-3xl text-[#E30613] shadow-inner"><AlertOctagon /></div>
                 <div>
                    <h3 className="text-3xl font-black text-slate-900 tracking-tighter uppercase leading-none">Ajuste Manual</h3>
                    <p className="text-[10px] font-black text-slate-400 uppercase mt-2">Corrigir batida esquecida</p>
                 </div>
              </div>
              <div className="space-y-6">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Horário</label>
                    <input type="time" value={modalAjuste.hora} onChange={(e) => setModalAjuste({...modalAjuste, hora: e.target.value})} className="w-full px-8 py-6 bg-slate-50 border border-slate-200 rounded-[2rem] font-black text-5xl text-slate-900 outline-none" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Justificativa</label>
                    <textarea placeholder="Motivo do ajuste..." value={motivoAjuste} onChange={(e) => setMotivoAjuste(e.target.value)} className="w-full px-8 py-5 bg-slate-50 border border-slate-200 rounded-[2rem] font-bold text-slate-700 min-h-[140px] outline-none" />
                 </div>
                 <button onClick={() => {
                    if(!motivoAjuste) return alert("Dê um motivo!");
                    const { pis, date, hora } = modalAjuste;
                    setData(prev => {
                      const newPontos = { ...prev.pontos };
                      if (!newPontos[pis]) newPontos[pis] = [];
                      let dia = newPontos[pis].find(d => d.data === date);
                      if (!dia) { dia = { data: date, batidas: [], isFalta: false }; newPontos[pis].push(dia); }
                      dia.batidas.push({ hora, origem: 'AJUSTE', obs: motivoAjuste });
                      dia.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
                      return { ...prev, pontos: newPontos };
                    });
                    setModalAjuste(null); setMotivoAjuste('');
                 }} className="w-full py-7 bg-emerald-600 text-white rounded-[2rem] font-black text-xs uppercase shadow-2xl">GRAVAR AJUSTE</button>
                 <button onClick={() => setModalAjuste(null)} className="w-full py-2 text-slate-400 font-black text-[11px] uppercase">Fechar</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, Calendar, FileText, Search, ShieldCheck, Plus, 
  Fingerprint, IdCard, Paperclip, AlertOctagon, FileCheck, X
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';
import { Funcionario, ControleHoras, RegistroBatida, AnexoPonto } from '../types';

export const HorasPage: React.FC = () => {
  const [data, setData] = useState<ControleHoras>(() => {
    const saved = localStorage.getItem('abc_rh_ponto_v12_final');
    return saved ? JSON.parse(saved) : { funcionarios: [], pontos: {}, logs: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePis, setActivePis] = useState<string | null>(null);
  const [modalAjuste, setModalAjuste] = useState<{pis: string, date: string, hora: string} | null>(null);
  const [motivoAjuste, setMotivoAjuste] = useState('');

  useEffect(() => {
    localStorage.setItem('abc_rh_ponto_v12_final', JSON.stringify(data));
  }, [data]);

  // MOTOR DE LEITURA AFD - VERSÃO CORRIGIDA
  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/);

      // Map para garantir que PIS duplicado não crie novo funcionário
      const funcsMap = new Map<string, Funcionario>();
      data.funcionarios.forEach(f => funcsMap.set(f.pis, f));

      const newPontos = { ...data.pontos };

      lines.forEach(line => {
        const trimmed = line.trim();
        if (trimmed.length < 20) return;

        // 1. IDENTIFICAÇÃO DE BATIDA (TIPO 3)
        // NSR(10) + TIPO(1) + DATA(8) + HORA(4) + PIS(12)
        const punchMatch = trimmed.match(/^(\d{10})3(\d{8})(\d{4})(\d{11,12})/);

        if (punchMatch) {
          const ddmmyyyy = punchMatch[2];
          const hhmm = punchMatch[3];
          const rawPis = punchMatch[4];
          const pis = rawPis.replace(/\D/g, '').slice(-11); // Limpa letras e padroniza 11 dígitos

          const dateKey = `${ddmmyyyy.slice(4,8)}-${ddmmyyyy.slice(2,4)}-${ddmmyyyy.slice(0,2)}`;
          const time = `${hhmm.slice(0,2)}:${hhmm.slice(2,4)}`;

          // Registra a batida no PIS unificado
          if (!newPontos[pis]) newPontos[pis] = [];
          let diaPonto = newPontos[pis].find(p => p.data === dateKey);
          if (!diaPonto) {
            diaPonto = { data: dateKey, batidas: [], isFalta: false };
            newPontos[pis].push(diaPonto);
          }
          if (!diaPonto.batidas.find(b => b.hora === time)) {
            diaPonto.batidas.push({ hora: time, origem: 'AFD' });
            diaPonto.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
          }

          // Cria o funcionário temporário se não existir
          if (!funcsMap.has(pis)) {
            funcsMap.set(pis, {
              pis, nome: `COLABORADOR ${pis}`, ativo: true, jornadaDiariaMinutos: 480,
              matricula: (funcsMap.size + 1).toString().padStart(4, '0')
            });
          }
        } 

        // 2. IDENTIFICAÇÃO DE CADASTRO/NOME (TIPO 5)
        // Se a linha contém um nome completo e um número longo (PIS)
        const nameMatch = trimmed.match(/([A-ZÀ-Ü]{3,}(?:\s+[A-ZÀ-Ü]{2,})+)/);
        const pisMatch = trimmed.match(/\d{11,12}/g);

        if (nameMatch && pisMatch) {
          const name = nameMatch[1].trim();
          const pis = pisMatch[pisMatch.length - 1].slice(-11);

          const existing = funcsMap.get(pis);
          if (!existing) {
            funcsMap.set(pis, {
              pis, nome: name, ativo: true, jornadaDiariaMinutos: 480,
              matricula: (funcsMap.size + 1).toString().padStart(4, '0')
            });
          } else {
            // Atualiza o nome se o atual for apenas o ID genérico
            if (existing.nome.startsWith("COLABORADOR") || existing.nome.length < 5) {
              existing.nome = name;
            }
          }
        }
      });

      setData(prev => ({ 
        ...prev, 
        funcionarios: Array.from(funcsMap.values()), 
        pontos: newPontos 
      }));
    };
    event.target.value = '';
  };

  const handleFileUpload = (pis: string, date: string, event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const base64 = e.target?.result as string;
      const newAnexo: AnexoPonto = {
        id: crypto.randomUUID(),
        nome: file.name,
        tipo: 'atestado',
        url: base64,
        dataEnvio: new Date().toISOString()
      };

      setData(prev => {
        const newPontos = { ...prev.pontos };
        if (!newPontos[pis]) newPontos[pis] = [];
        let dia = newPontos[pis].find(d => d.data === date);
        if (!dia) { dia = { data: date, batidas: [], isFalta: true }; newPontos[pis].push(dia); }
        dia.anexos = [...(dia.anexos || []), newAnexo];
        dia.isFalta = true;
        return { ...prev, pontos: newPontos };
      });
    };
    reader.readAsDataURL(file);
  };

  const calculateDay = (batidas: RegistroBatida[], jornadaMinutos: number = 480) => {
    if (!batidas || batidas.length < 2) return { trabalhadas: 0, saldo: 0 };
    let total = 0;
    const sorted = [...batidas].sort((a, b) => a.hora.localeCompare(b.hora));
    for (let i = 0; i < sorted.length - 1; i += 2) {
      const [h1, m1] = sorted[i].hora.split(':').map(Number);
      const [h2, m2] = sorted[i+1].hora.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return { trabalhadas: total, saldo: total - jornadaMinutos };
  };

  const formatMins = (mins: number) => {
    const h = Math.floor(Math.abs(mins) / 60);
    const m = Math.abs(mins) % 60;
    return `${mins < 0 ? '-' : ''}${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  const handleExportPDF = () => {
    if (!activeEmployee) return;
    const doc = new jsPDF();
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();

    doc.setFontSize(18); doc.setFont("helvetica", "bold");
    doc.text("Espelho de Ponto - ABC Itu", 14, 20);
    doc.setFontSize(8); doc.setFont("helvetica", "normal");
    doc.text(`Período: 01/${month}/${year} a ${lastDay}/${month}/${year}`, 14, 27);

    doc.setFontSize(9);
    doc.text(`Colaborador: ${activeEmployee.nome.toUpperCase()}`, 14, 38);
    doc.text(`PIS: ${activeEmployee.pis}`, 14, 43);

    const tableData = currentMonthDays.map(day => {
      const diaPonto = data.pontos[activeEmployee.pis]?.find(x => x.data === day);
      const b = diaPonto?.batidas || [];
      const calc = calculateDay(b, activeEmployee.jornadaDiariaMinutos);
      return [
        day.split('-').reverse().join('/'),
        b.map(x => x.hora).join('  '),
        b[0]?.hora || '', b[1]?.hora || '', b[2]?.hora || '', b[3]?.hora || '',
        calc.trabalhadas > 0 ? formatMins(calc.trabalhadas) : '',
        diaPonto?.anexos?.length ? 'SIM' : ''
      ];
    });

    (doc as any).autoTable({
      head: [['DATA', 'BATIDAS', 'E1', 'S1', 'E2', 'S2', 'TOTAL', 'ANEXO']],
      body: tableData,
      startY: 50,
      theme: 'grid',
      styles: { fontSize: 7, cellPadding: 1.5 },
      headStyles: { fillColor: [10, 17, 33] }
    });

    doc.save(`Ponto_${activeEmployee.nome}.pdf`);
  };

  const filteredFuncs = useMemo(() => {
    return data.funcionarios.filter(f => 
      f.nome.toLowerCase().includes(searchTerm.toLowerCase()) || f.pis.includes(searchTerm)
    ).sort((a, b) => a.nome.localeCompare(b.nome));
  }, [data.funcionarios, searchTerm]);

  const activeEmployee = useMemo(() => 
    data.funcionarios.find(f => f.pis === activePis), 
    [data.funcionarios, activePis]
  );

  const currentMonthDays = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
    return Array.from({ length: lastDay }, (_, i) => `${year}-${month}-${(i + 1).toString().padStart(2, '0')}`);
  }, [selectedMonth]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col lg:flex-row justify-between items-center gap-6 bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl">
        <div className="flex items-center gap-5">
           <div className="bg-[#E30613] p-4 rounded-3xl shadow-lg">
              <ShieldCheck className="w-8 h-8 text-white" />
           </div>
           <div>
              <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tighter leading-none">Gestão de Horas</h2>
              <p className="text-slate-400 font-bold text-[10px] uppercase tracking-widest mt-2">Unificação por PIS — ABC Itu</p>
           </div>
        </div>

        <div className="flex items-center gap-3">
          <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="bg-slate-50 border border-slate-200 rounded-2xl px-5 py-3 text-xs font-black outline-none" />
          <label className="flex items-center gap-3 px-8 py-4 bg-[#0A1121] text-white rounded-2xl cursor-pointer hover:bg-black transition-all font-black text-xs uppercase shadow-xl">
            <FileUp className="w-5 h-5 text-[#E30613]" /> LER AFD
            <input type="file" className="hidden" accept=".txt" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="lg:col-span-1">
          <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm sticky top-24">
            <div className="relative mb-6">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
              <input type="text" placeholder="Buscar..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl text-xs font-bold outline-none" />
            </div>
            <div className="space-y-2 max-h-[60vh] overflow-y-auto custom-scrollbar pr-2">
              {filteredFuncs.map(f => (
                <button 
                  key={f.pis}
                  onClick={() => setActivePis(f.pis)}
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePis === f.pis ? 'bg-[#E30613] text-white shadow-lg border-[#E30613]' : 'bg-slate-50 border-transparent text-slate-600 hover:bg-slate-100'}`}
                >
                  <p className="text-[10px] font-black uppercase truncate leading-tight">{f.nome}</p>
                  <p className={`text-[8px] font-bold ${activePis === f.pis ? 'text-white/60' : 'text-slate-400'}`}>PIS: {f.pis}</p>
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="lg:col-span-3 space-y-6">
           {activeEmployee ? (
             <>
               <div className="bg-white border border-slate-200 rounded-[2.5rem] shadow-xl overflow-hidden p-8 flex flex-col md:flex-row justify-between items-center gap-6">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-white rounded-3xl shadow-sm flex items-center justify-center border border-slate-100"><IdCard className="w-8 h-8 text-[#E30613]" /></div>
                     <div>
                        <h3 className="text-xl font-black text-slate-900 uppercase leading-none">{activeEmployee.nome}</h3>
                        <p className="text-[10px] font-bold text-slate-400 uppercase mt-2">PIS: {activeEmployee.pis}</p>
                     </div>
                  </div>
                  <button onClick={handleExportPDF} className="flex items-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-2xl text-xs font-black uppercase shadow-xl hover:bg-black">
                     <FileCheck className="w-5 h-5 text-[#E30613]" /> Exportar PDF
                  </button>
               </div>

               <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                  <table className="w-full text-left">
                     <thead>
                        <tr className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-widest">
                           <th className="px-8 py-6">Data</th>
                           <th className="px-8 py-6">Batidas</th>
                           <th className="px-4 py-6 text-center">E1/S1</th>
                           <th className="px-4 py-6 text-center">E2/S2</th>
                           <th className="px-8 py-6 text-right">Saldo</th>
                           <th className="px-8 py-6 text-center">Ações</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-slate-100">
                        {currentMonthDays.map(day => {
                           const diaPonto = data.pontos[activePis!]?.find(x => x.data === day);
                           const b = diaPonto?.batidas || [];
                           const anexos = diaPonto?.anexos || [];
                           const calc = calculateDay(b, activeEmployee.jornadaDiariaMinutos);
                           const dt = new Date(day + 'T00:00:00');

                           return (
                              <tr key={day} className="group hover:bg-slate-50 transition-all">
                                 <td className="px-8 py-5">
                                    <span className="text-sm font-black text-slate-900">{day.split('-').reverse().join('/')}</span>
                                    <span className="text-[9px] font-bold text-slate-400 uppercase block">{dt.toLocaleDateString('pt-BR', { weekday: 'short' })}</span>
                                 </td>
