                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Horário</label>
                    <input type="time" value={modalAjuste.hora} onChange={(e) => setModalAjuste({...modalAjuste, hora: e.target.value})} className="w-full px-8 py-6 bg-slate-50 border border-slate-200 rounded-[2rem] font-black text-5xl text-slate-900 outline-none" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Justificativa</label>
                    <textarea placeholder="Motivo do ajuste..." value={motivoAjuste} onChange={(e) => setMotivoAjuste(e.target.value)} className="w-full px-8 py-5 bg-slate-50 border border-slate-200 rounded-[2rem] font-bold text-slate-700 min-h-[140px] outline-none" />
                 </div>
                 <button onClick={() => {
                    if(!motivoAjuste) return alert("Dê um motivo!");
                    const { pis, date, hora } = modalAjuste;
                    setData(prev => {
                      const newPontos = { ...prev.pontos };
                      if (!newPontos[pis]) newPontos[pis] = [];
                      let dia = newPontos[pis].find(d => d.data === date);
                      if (!dia) { dia = { data: date, batidas: [], isFalta: false }; newPontos[pis].push(dia); }
                      dia.batidas.push({ hora, origem: 'AJUSTE', obs: motivoAjuste });
                      dia.batidas.sort((a, b) => a.hora.localeCompare(b.hora));
                      return { ...prev, pontos: newPontos };
                    });
                    setModalAjuste(null); setMotivoAjuste('');
                 }} className="w-full py-7 bg-emerald-600 text-white rounded-[2rem] font-black text-xs uppercase shadow-2xl">GRAVAR AJUSTE</button>
                 <button onClick={() => setModalAjuste(null)} className="w-full py-2 text-slate-400 font-black text-[11px] uppercase">Fechar</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

