lines.forEach(line => {
  const trimmed = line.trim();

  // Captura batidas de ponto (Tipo 3)
  const punchMatch = trimmed.match(/^(\d{10})3(\d{8})(\d{4})(\d{11,12})/);

  if (punchMatch) {
    const ddmmyyyy = punchMatch[2];
    const hhmm = punchMatch[3];
    const pis = punchMatch[4].replace(/\D/g, '').slice(-11); // UNIFICAÇÃO AQUI

    const dateKey = `${ddmmyyyy.slice(4,8)}-${ddmmyyyy.slice(2,4)}-${ddmmyyyy.slice(0,2)}`;
    const time = `${hhmm.slice(0,2)}:${hhmm.slice(2,4)}`;

