import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, Calendar, FileText, Search, ShieldCheck, Plus, 
  Fingerprint, IdCard, Paperclip, AlertOctagon, FileCheck, X,
  UserPlus, Database, Download, Trash2, Printer, History
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

// --- TYPES ---
type Punch = { id: string; dayISO: string; time: string; nsr: string; origin: 'AFD' | 'MANUAL' };
type Person = { name: string; ids: string[]; active: boolean; sector?: string };
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { file: string; atISO: string; stats: { lines: number; found: number; invalid: number } };
};

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_rh_ponto_v15');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonName, setActivePersonName] = useState<string | null>(null);
  const [showImportLog, setShowImportLog] = useState(false);

  useEffect(() => {
    localStorage.setItem('abc_rh_ponto_v15', JSON.stringify(store));
  }, [store]);

  // --- HELPERS & PARSER ---
  const normalizeId = (raw: string) => raw.replace(/\D/g, '').slice(-12);
  const normalizeName = (raw: string) => raw.trim().replace(/\s+/g, ' ').toUpperCase();

  const parseAFD = (text: string) => {
    const lines = text.split(/\r?\n/);
    const newPunches: Punch[] = [];
    const foundPeople = new Map<string, string[]>(); // Nome -> IDs[]

    let stats = { lines: 0, found: 0, invalid: 0 };

    lines.forEach(line => {
      stats.lines++;
      const trimmed = line.trim();
      if (trimmed.length < 20) return;

      // Regex Tipo B (Com '3' e prefixo A/I)
      const matchB = trimmed.match(/^(\d{10})3(\d{8})(\d{4})([AI]?)(\d{11,12})/);
      // Regex Tipo A (Grudado)
      const matchA = trimmed.match(/^(\d{10})(\d{8})(\d{4})(\d{12})/);

      const match = matchB || matchA;
      if (match) {
        const nsr = match[1];
        const ddmmyyyy = match[2];
        const hhmm = match[3];
        const rawId = match[5] || match[4]; // Ajuste dependendo de qual regex pegou

        const id = normalizeId(rawId);
        const dayISO = `${ddmmyyyy.slice(4,8)}-${ddmmyyyy.slice(2,4)}-${ddmmyyyy.slice(0,2)}`;
        const time = `${hhmm.slice(0,2)}:${hhmm.slice(2,4)}`;

        if (parseInt(hhmm.slice(0,2)) < 24 && parseInt(hhmm.slice(2,4)) < 60) {
          newPunches.push({ id, dayISO, time, nsr, origin: 'AFD' });
          stats.found++;
        } else {
          stats.invalid++;
        }
      }

      // Auto-captura de Nomes (Tipo 5 ou cadastros)
      const nameMatch = trimmed.match(/([A-ZÀ-Ü]{3,}(?:\s+[A-ZÀ-Ü]{2,})+)/);
      const idMatch = trimmed.match(/\d{11,12}/g);
      if (nameMatch && idMatch) {
        const name = normalizeName(nameMatch[1]);
        const id = normalizeId(idMatch[idMatch.length - 1]);
        const existing = foundPeople.get(name) || [];
        if (!existing.includes(id)) foundPeople.set(name, [...existing, id]);
      }
    });

    setStore(prev => {
      const updatedPeople = [...prev.people];

      // Upsert das pessoas encontradas no AFD
      foundPeople.forEach((ids, name) => {
        const pIdx = updatedPeople.findIndex(p => p.name === name);
        if (pIdx > -1) {
          ids.forEach(id => {
            if (!updatedPeople[pIdx].ids.includes(id)) updatedPeople[pIdx].ids.push(id);
          });
        } else {
          updatedPeople.push({ name, ids, active: true });
        }
      });

      // Garantir que pessoas sem nome mas com batidas existam como "COLABORADOR ID"
      newPunches.forEach(p => {
        const hasOwner = updatedPeople.some(pers => pers.ids.includes(p.id));
        if (!hasOwner) {
          updatedPeople.push({ name: `COLABORADOR ${p.id}`, ids: [p.id], active: true });
        }
      });

      // Evitar duplicatas de batidas (NSR único)
      const existingNsrs = new Set(prev.punches.map(p => p.nsr));
      const uniqueNewPunches = newPunches.filter(p => !existingNsrs.has(p.nsr));

      return {
        ...prev,
        people: updatedPeople,
        punches: [...prev.punches, ...uniqueNewPunches],
        lastImport: { file: 'AFD_IMPORT', atISO: new Date().toISOString(), stats }
      };
    });
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
