                    <td>${dayPunches.length === 4 ? '00008' : dayPunches.length > 0 ? '00007' : ''}</td>
                  </tr>
                `;
              }).join('')}
            </tbody>
          </table>
          <div class="footer">
            <div class="sign">ASSINATURA DO EMPREGADOR</div>
            <div class="sign">ASSINATURA DO EMPREGADO</div>
