import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, Calendar, FileText, Search, ShieldCheck, Plus, 
  Fingerprint, IdCard, Paperclip, AlertOctagon, FileCheck, X,
  UserPlus, Database, Download, Trash2, Printer, History, Edit3, Save
} from 'lucide-react';
import { Funcionario, RegistroBatida, AnexoPonto } from '../types';

// Tipos estritos para o novo motor
type Punch = { id: string; dayISO: string; time: string; nsr: string; origin: 'AFD' | 'AJUSTE' };
type Person = { 
  name: string; 
  ids: string[]; 
  active: boolean; 
  cargo?: string; 
  admissao?: string; 
  pis_oficial?: string;
  matricula?: string;
};
type StoreHoras = {
  people: Person[];
  punches: Punch[];
};

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<StoreHoras>(() => {
    const saved = localStorage.getItem('abc_rh_ponto_v20_final');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonName, setActivePersonName] = useState<string | null>(null);
  const [isEditingInfo, setIsEditingInfo] = useState(false);
  const [modalAjuste, setModalAjuste] = useState<{name: string, date: string} | null>(null);
  const [ajusteTime, setAjusteTime] = useState('08:00');

  useEffect(() => {
    localStorage.setItem('abc_rh_ponto_v20_final', JSON.stringify(store));
  }, [store]);

  // --- MOTOR DE PARSER HÍBRIDO (TIPO A + TIPO B) ---
  const normalizeId = (raw: string) => raw.replace(/\D/g, '').slice(-12).replace(/^0+/, '') || raw.replace(/\D/g, '');
  const normalizeName = (raw: string) => raw.trim().replace(/\s+/g, ' ').toUpperCase();

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/);

      const newPunches: Punch[] = [];
      const tempPeople = new Map<string, Set<string>>(); // Nome -> Set de IDs

      lines.forEach(line => {
        const trimmed = line.trim();
        if (trimmed.length < 20) return;

        // 1. CAPTURA DE BATIDA (Híbrida: Tipo 3 ou Grudada)
        const matchB = trimmed.match(/^(\d{10})3(\d{8})(\d{4})([AI]?)(\d{10,12})/);
        const matchA = trimmed.match(/^(\d{10})(\d{8})(\d{4})(\d{12})/);
        const m = matchB || matchA;

        if (m) {
          const ddmmyyyy = m[2];
          const hhmm = m[3];
          const rawId = m[5] || m[4];
          const id = normalizeId(rawId);
          const nsr = m[1];
          const dayISO = `${ddmmyyyy.slice(4,8)}-${ddmmyyyy.slice(2,4)}-${ddmmyyyy.slice(0,2)}`;
          const time = `${hhmm.slice(0,2)}:${hhmm.slice(2,4)}`;

          if (parseInt(hhmm.slice(0,2)) < 24 && parseInt(hhmm.slice(2,4)) < 60) {
            newPunches.push({ id, dayISO, time, nsr, origin: 'AFD' });
          }
        }

        // 2. CAPTURA DE NOMES E VÍNCULOS (Unificação)
        const nameMatch = trimmed.match(/([A-ZÀ-Ü]{3,}(?:\s+[A-ZÀ-Ü]{2,})+)/);
        const idMatch = trimmed.match(/\d{10,12}/g);
        if (nameMatch && idMatch) {
          const name = normalizeName(nameMatch[1]);
          const id = normalizeId(idMatch[idMatch.length - 1]);
          if (!tempPeople.has(name)) tempPeople.set(name, new Set());
          tempPeople.get(name)?.add(id);
        }
      });

      setStore(prev => {
        const updatedPeople = [...prev.people];

        // Atualiza ou Cria Pessoas com seus aliases
        tempPeople.forEach((ids, name) => {
          const idx = updatedPeople.findIndex(p => p.name === name);
          if (idx > -1) {
            ids.forEach(id => { if (!updatedPeople[idx].ids.includes(id)) updatedPeople[idx].ids.push(id) });
          } else {
            updatedPeople.push({ name, ids: Array.from(ids), active: true });
          }
        });

        // Garante que batidas sem nome tenham dono
        newPunches.forEach(p => {
          if (!updatedPeople.some(pers => pers.ids.includes(p.id))) {
            updatedPeople.push({ name: `COLABORADOR ${p.id}`, ids: [p.id], active: true });
          }
        });

        // Merge de batidas sem duplicar NSR
        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const filteredNew = newPunches.filter(p => !existingNsrs.has(p.nsr));

        return {
          people: updatedPeople,
          punches: [...prev.punches, ...filteredNew]
        };
      });
    };
    event.target.value = '';
  };

  const handlePrint = () => {
    if (!activePerson) return;
    const punches = getPunches(activePerson, selectedMonth);
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(Number(year), Number(month), 0).getDate();

