            </div>
          </div>
          <table>
            <thead>
              <tr>
                <th>DATA</th><th>MARCAÇÕES</th><th>TOTAL</th>
              </tr>
            </thead>
            <tbody>
              ${Array.from({length: lastDay}, (_, i) => {
                const day = (i+1).toString().padStart(2, '0');
                const iso = `${selectedMonth}-${day}`;
                const dayPunches = punches.filter(p => p.dayISO === iso).sort((a,b) => a.time.localeCompare(b.time));
                return `<tr>
                  <td>${day}/${month}</td>
                  <td>${dayPunches.map(p => p.time).join(' | ')}</td>
                  <td>${dayPunches.length >= 2 ? 'CALCULADO' : ''}</td>
                </tr>`;
              }).join('')}
            </tbody>
          </table>
          <div class="footer">
            <div class="sign">Assinatura do Empregador</div>
            <div class="sign">Assinatura do Empregado</div>
          </div>
          <script>window.print();</script>
        </body>
      </html>
    `);
    win.document.close();
  };

  const getPunches = (p: Person, month: string) => store.punches.filter(pun => p.ids.includes(pun.id) && pun.dayISO.startsWith(month));

  const filteredPeople = useMemo(() => store.people.filter(p => p.name.includes(searchTerm.toUpperCase()) || p.ids.some(id => id.includes(searchTerm))), [store, searchTerm]);
  const activePerson = store.people.find(p => p.name === activePersonName);

  return (
    <div className="space-y-6">
      {/* HEADER DINÂMICO */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl flex justify-between items-center">
        <div className="flex items-center gap-4">
          <div className="bg-[#E30613] p-4 rounded-2xl shadow-lg"><ShieldCheck className="text-white w-6 h-6" /></div>
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter">Gestão de Horas</h2>
            <p className="text-[10px] font-bold text-slate-400 uppercase">Unificação por Identidade Nominal</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <input type="month" value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)} className="bg-slate-50 border rounded-xl px-4 py-2 text-xs font-bold" />
          <label className="bg-[#0A1121] text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase cursor-pointer flex items-center gap-2">
            <FileUp className="w-4 h-4 text-[#E30613]" /> Ler AFD <input type="file" className="hidden" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* LISTA DE COLABORADORES */}
        <div className="bg-white border rounded-[2rem] p-6 shadow-sm">
          <div className="relative mb-4">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input type="text" placeholder="Buscar..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-slate-50 border rounded-xl text-xs font-bold" />
          </div>
          <div className="space-y-2 max-h-[60vh] overflow-y-auto pr-2">
            {filteredPeople.map(p => (
              <button key={p.name} onClick={() => { setActivePersonName(p.name); setIsEditingInfo(false); }} className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonName === p.name ? 'bg-[#E30613] text-white border-[#E30613] shadow-lg' : 'bg-slate-50 border-transparent hover:bg-slate-100'}`}>
                <p className="text-[10px] font-black uppercase truncate">{p.name}</p>
                <p className={`text-[8px] font-bold ${activePersonName === p.name ? 'text-white/60' : 'text-slate-400'}`}>IDs: {p.ids.join(', ')}</p>
              </button>
            ))}
          </div>
        </div>

        {/* DETALHES E ESPELHO */}
        <div className="lg:col-span-3 space-y-6">
          {activePerson ? (
            <>
              <div className="bg-white border rounded-[2.5rem] p-8 shadow-xl">
                <div className="flex justify-between items-start mb-8">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-slate-100 rounded-2xl flex items-center justify-center"><IdCard className="text-[#E30613]" /></div>
                    <div>
                      <h3 className="text-xl font-black uppercase tracking-tight">{activePerson.name}</h3>
                      <div className="flex gap-2 mt-1">
                        {activePerson.ids.map(id => <span key={id} className="text-[8px] bg-slate-100 px-2 py-0.5 rounded-md font-bold text-slate-400">ID: {id}</span>)}
                      </div>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => setIsEditingInfo(!isEditingInfo)} className="p-3 bg-slate-100 rounded-xl hover:bg-slate-200 transition-all"><Edit3 className="w-4 h-4 text-slate-600" /></button>
                    <button onClick={handlePrint} className="flex items-center gap-2 bg-[#0A1121] text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase shadow-lg"><Printer className="w-4 h-4 text-emerald-500" /> Gerar Espelho</button>
                  </div>
