                      <input type="text" value={activePerson.pis_oficial || ''} onChange={e => setStore(prev => ({...prev, people: prev.people.map(p => p.name === activePerson.name ? {...p, pis_oficial: e.target.value} : p)}))} className="w-full bg-white border rounded-lg px-3 py-2 text-xs font-bold" placeholder="000.00000.00-0" />
                    </div>
