                      <label className="text-[8px] font-black uppercase text-slate-400 ml-1">Matrícula</label>
                      <input type="text" value={activePerson.matricula || ''} onChange={e => setStore(prev => ({...prev, people: prev.people.map(p => p.name === activePerson.name ? {...p, matricula: e.target.value} : p)}))} className="w-full bg-white border rounded-lg px-3 py-2 text-xs font-bold" placeholder="0000" />
