  Database, UserPlus, History, Save, Edit3
} from 'lucide-react';

// --- TIPAGEM ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; 
  active: boolean; 
  cargo?: string; 
  admissao?: string; 
  pis_oficial?: string;
  matricula?: string;
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    atISO: string; 
    stats: { lines: number; punches: number; users: number; uniqueIds: number } 
  };
};

// --- CONSTANTES REGEX (CONFORME SOLICITADO) ---
const RX_PUNCH = /^(\d{10})3(\d{8})(\d{4})(\d{12})/;
const RX_USER = /^(\d{10})5(\d{8})(\d{4})([EIA])(\d{11,12})([A-ZÀ-Ü]{3,}(?:\s+[A-ZÀ-Ü]{2,})+)/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_rh_ponto_v25');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonName, setActivePersonName] = useState<string | null>(null);
  const [isEditingInfo, setIsEditingInfo] = useState(false);

  useEffect(() => {
    localStorage.setItem('abc_rh_ponto_v25', JSON.stringify(store));
  }, [store]);

  // --- NORMALIZAÇÃO ---
  const normId = (raw: string): string => {
    const d = raw.replace(/\D/g, '');
    return d.length >= 12 ? d.slice(-12) : d;
  };

  const normName = (raw: string): string => {
    return raw.trim().replace(/\s+/g, ' ').toUpperCase();
  };

  const isValidHHMM = (hh: string, mm: string) => {
    const h = parseInt(hh);
    const m = parseInt(mm);
    return h >= 0 && h <= 23 && m >= 0 && m <= 59;
  };

  // --- PARSER AFD ---
  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/);

      const newPunches: Punch[] = [];
      const extractedUsers = new Map<string, string>(); // ID -> Nome
      const stats = { lines: 0, punches: 0, users: 0 };

      lines.forEach(line => {
        stats.lines++;
        const trimmed = line.trim();

        // Tentar Match de Batida (Tipo 3)
        const punchMatch = trimmed.match(RX_PUNCH);
        if (punchMatch) {
          const [, nsr, ddmmyyyy, hhmm, idRaw] = punchMatch;
          if (isValidHHMM(hhmm.slice(0, 2), hhmm.slice(2, 4))) {
            newPunches.push({
              nsr,
              dayISO: `${ddmmyyyy.slice(4, 8)}-${ddmmyyyy.slice(2, 4)}-${ddmmyyyy.slice(0, 2)}`,
              time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
              id: normId(idRaw)
            });
            stats.punches++;
          }
        }

        // Tentar Match de Usuário (Tipo 5)
        const userMatch = trimmed.match(RX_USER);
        if (userMatch) {
          const [, , , , , idRaw, nameRaw] = userMatch;
          extractedUsers.set(normId(idRaw), normName(nameRaw));
          stats.users++;
        }
      });

      setStore(prev => {
        const updatedPeople = [...prev.people];

        // 1. Upsert de Pessoas pelos nomes encontrados
        extractedUsers.forEach((name, id) => {
          let person = updatedPeople.find(p => p.name === name);
          if (!person) {
            person = { name, ids: [id], active: true };
            updatedPeople.push(person);
          } else {
            if (!person.ids.includes(id)) {
              // Regra: ID não pode estar em 2 pessoas
              updatedPeople.forEach(other => {
                other.ids = other.ids.filter(oid => oid !== id);
              });
              person.ids.push(id);
            }
          }
        });

        // 2. Garantir que IDs órfãos nas batidas criem colaboradores genéricos
        newPunches.forEach(p => {
          const exists = updatedPeople.some(pers => pers.ids.includes(p.id));
          if (!exists) {
            updatedPeople.push({ name: `COLABORADOR ${p.id}`, ids: [p.id], active: true });
          }
        });

        // 3. Mesclar batidas (únicas por NSR)
        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const uniqueNew = newPunches.filter(p => !existingNsrs.has(p.nsr));

        return {
          people: updatedPeople.filter(p => p.ids.length > 0), // Remove fantasmas sem ID
          punches: [...prev.punches, ...uniqueNew],
          lastImport: {
            file: file.name,
            atISO: new Date().toISOString(),
            stats: { ...stats, uniqueIds: new Set(newPunches.map(p => p.id)).size }
          }
        };
      });
    };
    event.target.value = '';
  };

  // --- LÓGICA DE VISUALIZAÇÃO ---
  const filteredPeople = useMemo(() => {
    return store.people.filter(p => 
      p.name.includes(searchTerm.toUpperCase()) || p.ids.some(id => id.includes(searchTerm))
    ).sort((a, b) => a.name.localeCompare(b.name));
  }, [store.people, searchTerm]);

  const activePerson = useMemo(() => 
    store.people.find(p => p.name === activePersonName), 
    [store.people, activePersonName]
  );

  const getPersonPunches = (p: Person, month: string) => {
    return store.punches
      .filter(pun => p.ids.includes(pun.id) && pun.dayISO.startsWith(month))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));
  };

  const calculateDayMins = (punches: Punch[]) => {
    if (punches.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < punches.length - 1; i += 2) {
      const [h1, m1] = punches[i].time.split(':').map(Number);
      const [h2, m2] = punches[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  const formatMins = (mins: number) => {
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  const handlePrintMirror = () => {
    if (!activePerson) return;
    const punches = getPersonPunches(activePerson, selectedMonth);
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(Number(year), Number(month), 0).getDate();

    const win = window.open('', '_blank');
    if (!win) return;

    win.document.write(`
      <html>
        <head>
          <title>Espelho de Ponto - ${activePerson.name}</title>
          <style>
            @page { size: A4; margin: 15mm; }
            body { font-family: 'Courier New', monospace; font-size: 10px; line-height: 1.2; color: #000; }
            .header { text-align: center; border: 1px solid #000; padding: 10px; margin-bottom: 10px; }
            .info { display: grid; grid-template-columns: 1fr 1fr; border: 1px solid #000; padding: 10px; gap: 5px; margin-bottom: 10px; }
            table { width: 100%; border-collapse: collapse; }
            th, td { border: 1px solid #000; padding: 3px; font-size: 9px; text-align: center; }
            th { background: #eee; text-transform: uppercase; }
            .footer { margin-top: 30px; display: grid; grid-template-columns: 1fr 1fr; gap: 40px; text-align: center; }
            .sign { border-top: 1px solid #000; padding-top: 5px; }
          </style>
        </head>
        <body>
          <div class="header">
            <h2 style="margin:0">ESPELHO DE PONTO ELETRÔNICO</h2>
            <p style="margin:2px">PERÍODO: 01/${month}/${year} ATÉ ${lastDay}/${month}/${year}</p>
          </div>
          <div class="info">
            <div>
              <strong>EMPRESA:</strong> ABC DA CONSTRUÇÃO ITU<br>
              <strong>NOME:</strong> ${activePerson.name}<br>
              <strong>CARGO:</strong> ${activePerson.cargo || 'COLABORADOR'}
            </div>
            <div>
              <strong>PIS/ID:</strong> ${activePerson.pis_oficial || activePerson.ids[0]}<br>
              <strong>MATRÍCULA:</strong> ${activePerson.matricula || activePerson.ids.join(' / ')}<br>
              <strong>ADMISSÃO:</strong> ${activePerson.admissao || '--/--/----'}
            </div>
          </div>
          <table>
            <thead>
              <tr>
                <th width="15%">DIA</th>
                <th width="40%">MARCAÇÕES REGISTRADAS</th>
                <th>E1</th><th>S1</th><th>E2</th><th>S2</th>
                <th width="10%">TOTAL</th>
                <th width="5%">CH</th>
              </tr>
            </thead>
            <tbody>
              ${Array.from({ length: lastDay }, (_, i) => {
                const day = (i + 1).toString().padStart(2, '0');
                const iso = `${selectedMonth}-${day}`;
                const dayPunches = punches.filter(p => p.dayISO === iso);
                const mins = calculateDayMins(dayPunches);
                const wd = new Date(iso + 'T12:00:00').toLocaleDateString('pt-BR', { weekday: 'short' });
                return `
                  <tr>
                    <td>${day}/${month} ${wd.toUpperCase()}</td>
                    <td style="font-size: 8px">${dayPunches.map(p => p.time).join(' ')}</td>
                    <td>${dayPunches[0]?.time || ''}</td>
                    <td>${dayPunches[1]?.time || ''}</td>
                    <td>${dayPunches[2]?.time || ''}</td>
                    <td>${dayPunches[3]?.time || ''}</td>
                    <td>${mins > 0 ? formatMins(mins) : ''}</td>
                    <td>${dayPunches.length === 4 ? '00008' : dayPunches.length === 2 ? '00007' : ''}</td>
                  </tr>
                `;
              }).join('')}
            </tbody>
          </table>
          <p style="font-size: 8px; margin-top: 10px">Horários contratuais do empregado: Jornada flexível conforme escala.</p>
          <div class="footer">
            <div class="sign">ASSINATURA DO EMPREGADOR</div>
            <div class="sign">ASSINATURA DO EMPREGADO</div>
          </div>
          <script>window.print();</script>
        </body>
      </html>
    `);
    win.document.close();
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* HEADER PRINCIPAL */}
      <div className="flex flex-col lg:flex-row justify-between items-center gap-6 bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl">
        <div className="flex items-center gap-5">
           <div className="bg-[#E30613] p-4 rounded-3xl shadow-lg">
              <ShieldCheck className="w-8 h-8 text-white" />
           </div>
           <div>
              <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tighter leading-none">Gestão de Horas</h2>
              <p className="text-slate-400 font-bold text-[10px] uppercase tracking-widest mt-2">Unificação por Identidade Nominal (Aliases)</p>
           </div>
        </div>

        <div className="flex items-center gap-3">
          <input 
            type="month" 
            value={selectedMonth} 
            onChange={e => setSelectedMonth(e.target.value)} 
            className="bg-slate-50 border border-slate-200 rounded-2xl px-5 py-3 text-xs font-black outline-none focus:ring-2 focus:ring-[#E30613]" 
          />
          <label className="flex items-center gap-3 px-8 py-4 bg-[#0A1121] text-white rounded-2xl cursor-pointer hover:bg-black transition-all font-black text-xs uppercase shadow-xl group">
            <FileUp className="w-5 h-5 text-[#E30613] group-hover:scale-110 transition-transform" /> 
            <span>LER AFD</span>
            <input type="file" className="hidden" accept=".txt" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* SIDEBAR DE PESSOAS */}
        <div className="lg:col-span-1 space-y-4">
          <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm sticky top-24">
            <div className="relative mb-6">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
              <input 
                type="text" 
                placeholder="Buscar Nome ou ID..." 
                value={searchTerm} 
                onChange={e => setSearchTerm(e.target.value)} 
                className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl text-xs font-bold outline-none" 
              />
            </div>
            <div className="space-y-2 max-h-[55vh] overflow-y-auto custom-scrollbar pr-2">
              {filteredPeople.map(p => {
                const punches = getPersonPunches(p, selectedMonth);
                const workedDays = new Set(punches.map(pu => pu.dayISO)).size;
                return (
                  <button 
                    key={p.name}
                    onClick={() => { setActivePersonName(p.name); setIsEditingInfo(false); }}
                    className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonName === p.name ? 'bg-[#E30613] text-white shadow-lg border-[#E30613]' : 'bg-slate-50 border-transparent text-slate-600 hover:bg-slate-100'}`}
                  >
                    <div className="flex justify-between items-start">
                      <p className="text-[10px] font-black uppercase truncate leading-tight flex-1">{p.name}</p>
                      {workedDays > 0 && <span className={`text-[8px] font-black px-1.5 py-0.5 rounded ${activePersonName === p.name ? 'bg-white/20' : 'bg-emerald-100 text-emerald-600'}`}>{workedDays}D</span>}
                    </div>
                    <p className={`text-[8px] font-bold mt-1 ${activePersonName === p.name ? 'text-white/60' : 'text-slate-400'}`}>IDs: {p.ids.join(', ')}</p>
                  </button>
                );
              })}
            </div>

            <div className="mt-6 pt-6 border-t border-slate-100 grid grid-cols-2 gap-2">
               <button onClick={() => {
                 const blob = new Blob([JSON.stringify(store)], { type: 'application/json' });
                 const url = URL.createObjectURL(blob);
                 const a = document.createElement('a'); a.href = url; a.download = 'backup_ponto.json'; a.click();
               }} className="flex items-center justify-center gap-2 py-3 bg-slate-50 text-slate-400 rounded-xl text-[8px] font-black uppercase hover:bg-slate-100 transition-colors">
                  <Download className="w-3 h-3" /> Backup
               </button>
               <button onClick={() => {
                 if(confirm("Deseja zerar toda a base de ponto?")) setStore({ people: [], punches: [] });
               }} className="flex items-center justify-center gap-2 py-3 bg-red-50 text-red-400 rounded-xl text-[8px] font-black uppercase hover:bg-red-100 transition-colors">
                  <Trash2 className="w-3 h-3" /> Limpar
               </button>
            </div>
          </div>
        </div>

        {/* ÁREA DE CONTEÚDO */}
        <div className="lg:col-span-3">
          {activePerson ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
               {/* CARD DE IDENTIDADE */}
               <div className="bg-white border border-slate-200 rounded-[2.5rem] shadow-xl p-8 flex flex-col md:flex-row justify-between items-center gap-6">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-white rounded-3xl shadow-sm flex items-center justify-center border border-slate-100">
                        <IdCard className="w-8 h-8 text-[#E30613]" />
                     </div>
                     <div>
                        <h3 className="text-xl font-black text-slate-900 uppercase leading-none">{activePerson.name}</h3>
                        <p className="text-[10px] font-bold text-slate-400 uppercase mt-2">Vínculos AFD: {activePerson.ids.join(' • ')}</p>
                     </div>
                  </div>
                  <div className="flex gap-3">
                    <button onClick={() => setIsEditingInfo(!isEditingInfo)} className="p-4 bg-slate-100 text-slate-600 rounded-2xl hover:bg-slate-200 transition-all">
                       <Edit3 className="w-5 h-5" />
                    </button>
                    <button onClick={handlePrintMirror} className="flex items-center gap-3 px-8 py-4 bg-[#0A1121] text-white rounded-2xl text-xs font-black uppercase shadow-xl hover:bg-black transition-all">
                       <Printer className="w-5 h-5 text-emerald-500" /> Imprimir Espelho
                    </button>
                  </div>
               </div>

               {/* FORMULÁRIO DE EDIÇÃO */}
               {isEditingInfo && (
                  <div className="bg-slate-900 rounded-[2.5rem] p-10 text-white grid grid-cols-1 md:grid-cols-4 gap-6 animate-in zoom-in-95 duration-300 shadow-2xl">
                    <div className="space-y-2">
                       <label className="text-[9px] font-black uppercase text-slate-400 ml-1">Cargo</label>
                       <input type="text" value={activePerson.cargo || ''} onChange={e => setStore(prev => ({...prev, people: prev.people.map(p => p.name === activePerson.name ? {...p, cargo: e.target.value} : p)}))} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:border-[#E30613]" />
                    </div>
                    <div className="space-y-2">
                       <label className="text-[9px] font-black uppercase text-slate-400 ml-1">Matrícula</label>
                       <input type="text" value={activePerson.matricula || ''} onChange={e => setStore(prev => ({...prev, people: prev.people.map(p => p.name === activePerson.name ? {...p, matricula: e.target.value} : p)}))} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:border-[#E30613]" />
                    </div>
                    <div className="space-y-2">
                       <label className="text-[9px] font-black uppercase text-slate-400 ml-1">PIS Oficial</label>
                       <input type="text" value={activePerson.pis_oficial || ''} onChange={e => setStore(prev => ({...prev, people: prev.people.map(p => p.name === activePerson.name ? {...p, pis_oficial: e.target.value} : p)}))} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:border-[#E30613]" />
                    </div>
                    <div className="space-y-2">
                       <label className="text-[9px] font-black uppercase text-slate-400 ml-1">Admissão</label>
                       <input type="date" value={activePerson.admissao || ''} onChange={e => setStore(prev => ({...prev, people: prev.people.map(p => p.name === activePerson.name ? {...p, admissao: e.target.value} : p)}))} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:border-[#E30613]" />
                    </div>
                  </div>
               )}

               {/* TABELA DE REGISTROS */}
               <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                  <table className="w-full text-left">
                    <thead>
                      <tr className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-widest">
                        <th className="px-8 py-6">Data / Semana</th>
                        <th className="px-8 py-6">Marcações Registradas (AFD)</th>
                        <th className="px-4 py-6 text-center">Horas</th>
                        <th className="px-4 py-6 text-center">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {(() => {
                        const [year, month] = selectedMonth.split('-');
                        const days = new Date(Number(year), Number(month), 0).getDate();
                        const punches = getPersonPunches(activePerson, selectedMonth);

                        return Array.from({ length: days }, (_, i) => {
                          const day = (i + 1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dayPunches = punches.filter(p => p.dayISO === iso);
                          const dayMins = calculateDayMins(dayPunches);
                          const dt = new Date(iso + 'T12:00:00');

                          return (
                            <tr key={iso} className={`group hover:bg-slate-50 transition-all ${dayPunches.length === 0 ? 'opacity-30' : ''}`}>
                              <td className="px-8 py-5">
                                <span className="text-sm font-black text-slate-900">{day}/{month}</span>
                                <span className="text-[9px] font-bold text-slate-400 uppercase block leading-none">{dt.toLocaleDateString('pt-BR', { weekday: 'short' })}</span>
                              </td>
                              <td className="px-8 py-5">
                                <div className="flex flex-wrap gap-2">
                                  {dayPunches.length > 0 ? dayPunches.map((p, idx) => (
                                    <span key={idx} className="bg-slate-100 text-slate-700 text-[11px] font-black px-2.5 py-1.5 rounded-lg border border-slate-200">{p.time}</span>
                                  )) : <span className="text-slate-200 text-[10px] font-bold uppercase tracking-widest">—</span>}
                                  <button onClick={() => {
                                    const h = prompt("Digite a hora (HH:MM):", "08:00");
                                    if(h && h.includes(":")) {
                                      setStore(prev => ({
                                        ...prev,
                                        punches: [...prev.punches, { id: activePerson.ids[0], dayISO: iso, time: h, nsr: `MAN-${Date.now()}` }]
                                      }));
                                    }
                                  }} className="p-1.5 text-slate-200 hover:text-[#E30613] hover:bg-red-50 rounded-lg transition-all"><Plus className="w-4 h-4" /></button>
                                </div>
                              </td>
                              <td className="px-4 py-5 text-center">
                                <span className={`text-xs font-black ${dayMins > 0 ? 'text-emerald-600' : 'text-slate-200'}`}>
                                  {dayMins > 0 ? formatMins(dayMins) : '--:--'}
                                </span>
                              </td>
                              <td className="px-4 py-5 text-center">
                                 {dayPunches.length % 2 !== 0 && <AlertOctagon className="w-4 h-4 text-red-500 mx-auto" title="Batida ímpar" />}
                                 {dayPunches.length >= 2 && dayPunches.length % 2 === 0 && <span className="text-[9px] font-black text-emerald-500 uppercase">Ok</span>}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner">
               <Fingerprint className="w-24 h-24 opacity-10 mb-6 animate-pulse" />
               <p className="text-2xl font-black text-slate-400 uppercase tracking-tighter">Selecione um colaborador para conferir</p>
               {store.lastImport && (
                 <div className="mt-8 flex items-center gap-3 px-6 py-3 bg-emerald-50 rounded-2xl border border-emerald-100 text-emerald-600">
                    <History className="w-4 h-4" />
                    <span className="text-[10px] font-black uppercase tracking-widest">Último AFD: {store.lastImport.stats.punches} batidas / {store.lastImport.stats.uniqueIds} colaboradores</span>
                 </div>
               )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { PackageOpen, FileUp, CheckCircle2, TrendingDown, History, AlertOctagon, ArrowRight, Banknote, Trash2 } from 'lucide-react';
import * as XLSX from 'xlsx';
import { MesConferencia, Pedido } from '../types';

interface DevolvidosPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null) => void;
}

export const DevolvidosPage: React.FC<DevolvidosPageProps> = ({ data, onSetData }) => {
  const [loading, setLoading] = useState(false);
  const [processedLog, setProcessedLog] = useState<{mu: string, valor: number, margem: number, status: string}[]>(() => {
    const saved = localStorage.getItem('abc_devolvidos_log_v9');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('abc_devolvidos_log_v9', JSON.stringify(processedLog));
  }, [processedLog]);

  const formatCurrency = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const getActualKey = (firstRow: any, targets: string[]): string => {
    const keys = Object.keys(firstRow);
    for (const target of targets) {
      const normalizedTarget = target.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
      const found = keys.find(k => {
        const normalizedK = k.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
        return normalizedK === normalizedTarget || normalizedK.includes(normalizedTarget);
      });
      if (found) return found;
    }
    return targets[0];
  };

  const toNumber = (val: any): number => {
    if (val === null || val === undefined || val === '' || val === '-') return 0;
    if (typeof val === 'number') return val;
    let str = String(val).replace(/R\$/g, '').replace(/\s/g, '').trim();
    if (str.includes('.') && str.includes(',')) str = str.replace(/\./g, '').replace(',', '.');
    else if (str.includes(',')) str = str.replace(',', '.');
    return parseFloat(str) || 0;
  };

  const handleImportDevolvidos = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !data) return;
    setLoading(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const dataArray = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(dataArray, { type: 'array' });
        const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { defval: "" }) as any[];

        if (rows.length === 0) return;
        const firstRow = rows[0];

        // Mapeamento de colunas atualizado para priorizar "Margem Deduzir s/ frete"
        const keyMU = getActualKey(firstRow, ["Nº Pedido MU", "Pedido MU", "MU", "Pedido"]);
        const keyValor = getActualKey(firstRow, ["Preço total", "Valor Devolvido", "Total Devolvido"]);
        const keyMargem = getActualKey(firstRow, ["Margem Deduzir s/ frete", "Margem Deduzir", "Diferenca Margem", "Margem Deduzir c/ frete"]);

        const newPedidos = [...data.pedidos];
        const log: typeof processedLog = [];

        rows.forEach((row: any) => {
          const mu = String(row[keyMU] || "").trim();
          if (!mu || mu.toLowerCase().includes("total") || mu === "0") return;

          const valorDevolvido = toNumber(row[keyValor]);
          const margemDeduzir = toNumber(row[keyMargem]);

          const index = newPedidos.findIndex(p => p.id === mu);
          if (index !== -1) {
            newPedidos[index].isDevolvido = true;
            newPedidos[index].margemDeduzidaDevolucao = (newPedidos[index].margemDeduzidaDevolucao || 0) + margemDeduzir;
            newPedidos[index].total = Math.max(0, newPedidos[index].total - valorDevolvido);
            log.push({ mu, valor: valorDevolvido, margem: margemDeduzir, status: 'REVERSA_MES' });
          } else {
            const novoAjuste: Pedido = {
              id: mu, data: "Mês Anterior", canal: "AJUSTE REVERSA", vendedor: "SISTEMA (BACKLOG)",
              mkt: 0, cac: 0, total: 0, frete: 0, margemOriginal: 0, margemOriginalPct: 0, credito: 0, debito: 0,
              margemDeduzidaDevolucao: margemDeduzir, margemAjustada: margemDeduzir, confirmado: true, isDevolvido: true
            };
            newPedidos.push(novoAjuste);
            log.push({ mu, valor: valorDevolvido, margem: margemDeduzir, status: 'REVERSA_ANT' });
          }
        });

        onSetData({ ...data, pedidos: newPedidos });
        setProcessedLog(prev => [...prev, ...log]);
      } catch (err) { alert("Erro ao processar planilha."); } finally { setLoading(false); event.target.value = ""; }
    };
    reader.readAsArrayBuffer(file);
  };

  const conciliacao = useMemo(() => {
    if (!data) return [];
    const vinculos = data.pedidos.filter(p => p.isOcorrencia || p.idPedidoMestre);
    return vinculos.map(ocorr => {
      const muMestre = ocorr.idPedidoMestre || ocorr.id;
      const mestreOriginal = data.pedidos.find(p => p.id === muMestre);
      const reversa = processedLog.find(l => l.mu === muMestre);
      const valorEstornado = reversa ? Math.abs(reversa.margem) : 0;
      const margemNovaOcorrencia = ocorr.margemOriginal;
      const saldoABC = valorEstornado - margemNovaOcorrencia;
      return { ocorr, mestre: mestreOriginal, reversa, saldoABC };
    });
  }, [data, processedLog]);

  return (
    <div className="space-y-12 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="space-y-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Devoluções</h2>
          <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Conciliação e Auditoria de Logística</p>
        </div>
        <div className="flex gap-4">
          <button onClick={() => { if(confirm("Limpar log de importação?")) setProcessedLog([]) }} className="px-6 py-5 bg-slate-100 text-slate-400 rounded-2xl font-black text-xs uppercase hover:bg-red-50 hover:text-red-500 transition-all">LIMPAR LOG</button>
          <label className="flex items-center gap-4 px-10 py-5 bg-amber-600 text-white rounded-2xl cursor-pointer hover:bg-amber-700 transition-all shadow-xl font-black text-xs uppercase tracking-wider">
            <FileUp className="w-5 h-5" /> {loading ? 'PROCESSANDO...' : 'SUBIR PLANILHA DEVOLUÇÃO'}
            <input type="file" className="hidden" onChange={handleImportDevolvidos} accept=".xlsx, .xls" />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
         <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-[3rem] p-10">
            <h3 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-8 flex items-center gap-3"><History className="w-6 h-6 text-[#E30613]" /> Ciclo de Ocorrências (Saldo ABC)</h3>
            <div className="space-y-4">
               {conciliacao.length === 0 ? (
                 <p className="text-center py-20 text-slate-300 font-black uppercase text-xs">Aguardando vínculo de Pedidos Mestre...</p>
               ) : (
                 conciliacao.map((item, idx) => (
                   <div key={idx} className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 flex flex-col md:flex-row items-center gap-6">
                      <div className="flex-1 min-w-0">
                         <p className="text-[9px] font-black text-slate-400 uppercase">MU MESTRE: {item.mestre?.id || item.ocorr.idPedidoMestre}</p>
                         <h4 className="text-sm font-black text-slate-900 truncate">{item.ocorr.vendedor}</h4>
                         {/* FIX: Access 'id' through 'item.ocorr.id' instead of 'item.id' */}
                         <p className="text-[9px] font-bold text-amber-600 uppercase">Nova Ocorrência: {item.ocorr.id}</p>
                      </div>
                      <div className="flex items-center gap-4">
                         <div className="text-center">
                            <p className="text-[8px] font-black text-red-400 uppercase">Estorno (-)</p>
                            <p className="text-xs font-black">{item.reversa ? formatCurrency(Math.abs(item.reversa.margem)) : '---'}</p>
                         </div>
                         <ArrowRight className="w-4 h-4 text-slate-200" />
                         <div className="text-center">
                            <p className="text-[8px] font-black text-emerald-400 uppercase">Novo (+)</p>
                            <p className="text-xs font-black">{formatCurrency(item.ocorr.margemOriginal)}</p>
                         </div>
                         <div className={`p-3 rounded-xl min-w-[100px] text-center ${item.saldoABC > 0 ? 'bg-red-50 text-[#E30613]' : 'bg-emerald-50 text-emerald-600'}`}>
                            <p className="text-[8px] font-black uppercase mb-1">A Repor</p>
                            <p className="text-sm font-black">{formatCurrency(item.saldoABC)}</p>
                         </div>
                      </div>
                   </div>
                 ))
               )}
            </div>
         </div>

         <div className="bg-white border border-slate-200 rounded-[3rem] p-10 shadow-xl">
            <h3 className="text-sm font-black text-slate-950 uppercase tracking-widest mb-6">Logs de Importação de Devolvidos</h3>
            <div className="max-h-[500px] overflow-y-auto pr-2">
               <table className="w-full text-left">
                  <thead className="sticky top-0 bg-white">
                    <tr className="text-[9px] font-black uppercase text-slate-400 border-b border-slate-100">
                      <th className="py-4">Pedido MU</th>
                      <th className="py-4 text-right">Devolvido</th>
                      <th className="py-4 text-right">Margem Estornada</th>
                    </tr>
                  </thead>
                  <tbody>
                    {processedLog.map((l, i) => (
                      <tr key={i} className="border-b border-slate-50 hover:bg-slate-50">
                        <td className="py-4 font-black text-xs text-slate-900">{l.mu}</td>
                        <td className="py-4 text-right font-bold text-slate-400">{formatCurrency(l.valor)}</td>
                        <td className="py-4 text-right font-black text-[#E30613]">{formatCurrency(l.margem)}</td>
                      </tr>
                    ))}
                  </tbody>
               </table>
            </div>
         </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, Calendar, FileText, Search, ShieldCheck, Plus, 
  Fingerprint, IdCard, AlertOctagon, Printer, Trash2, Download, 
  Database, UserPlus, History, Save, Edit3
} from 'lucide-react';

// --- TIPAGEM ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; 
  active: boolean; 
  cargo?: string; 
  admissao?: string; 
  pis_oficial?: string;
  matricula?: string;
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    atISO: string; 
    stats: { lines: number; punches: number; users: number; uniqueIds: number } 
  };
};

// --- CONSTANTES REGEX (CONFORME SOLICITADO) ---
const RX_PUNCH = /^(\d{10})3(\d{8})(\d{4})(\d{12})/;
const RX_USER = /^(\d{10})5(\d{8})(\d{4})([EIA])(\d{11,12})([A-ZÀ-Ü]{3,}(?:\s+[A-ZÀ-Ü]{2,})+)/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_rh_ponto_v25');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonName, setActivePersonName] = useState<string | null>(null);
  const [isEditingInfo, setIsEditingInfo] = useState(false);

  useEffect(() => {
    localStorage.setItem('abc_rh_ponto_v25', JSON.stringify(store));
  }, [store]);

  // --- NORMALIZAÇÃO ---
  const normId = (raw: string): string => {
    const d = raw.replace(/\D/g, '');
    return d.length >= 12 ? d.slice(-12) : d;
  };

  const normName = (raw: string): string => {
    return raw.trim().replace(/\s+/g, ' ').toUpperCase();
  };

  const isValidHHMM = (hh: string, mm: string) => {
    const h = parseInt(hh);
    const m = parseInt(mm);
    return h >= 0 && h <= 23 && m >= 0 && m <= 59;
  };

  // --- PARSER AFD ---
  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/);

      const newPunches: Punch[] = [];
      const extractedUsers = new Map<string, string>(); // ID -> Nome
      const stats = { lines: 0, punches: 0, users: 0 };

      lines.forEach(line => {
        stats.lines++;
        const trimmed = line.trim();

        // Tentar Match de Batida (Tipo 3)
        const punchMatch = trimmed.match(RX_PUNCH);
        if (punchMatch) {
          const [, nsr, ddmmyyyy, hhmm, idRaw] = punchMatch;
          if (isValidHHMM(hhmm.slice(0, 2), hhmm.slice(2, 4))) {
            newPunches.push({
              nsr,
              dayISO: `${ddmmyyyy.slice(4, 8)}-${ddmmyyyy.slice(2, 4)}-${ddmmyyyy.slice(0, 2)}`,
              time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
              id: normId(idRaw)
            });
            stats.punches++;
          }
        }

        // Tentar Match de Usuário (Tipo 5)
        const userMatch = trimmed.match(RX_USER);
        if (userMatch) {
          const [, , , , , idRaw, nameRaw] = userMatch;
          extractedUsers.set(normId(idRaw), normName(nameRaw));
          stats.users++;
        }
      });

      setStore(prev => {
        const updatedPeople = [...prev.people];

        // 1. Upsert de Pessoas pelos nomes encontrados
        extractedUsers.forEach((name, id) => {
          let person = updatedPeople.find(p => p.name === name);
          if (!person) {
            person = { name, ids: [id], active: true };
            updatedPeople.push(person);
          } else {
            if (!person.ids.includes(id)) {
              // Regra: ID não pode estar em 2 pessoas
              updatedPeople.forEach(other => {
                other.ids = other.ids.filter(oid => oid !== id);
              });
              person.ids.push(id);
            }
          }
        });

        // 2. Garantir que IDs órfãos nas batidas criem colaboradores genéricos
        newPunches.forEach(p => {
          const exists = updatedPeople.some(pers => pers.ids.includes(p.id));
          if (!exists) {
            updatedPeople.push({ name: `COLABORADOR ${p.id}`, ids: [p.id], active: true });
          }
        });

        // 3. Mesclar batidas (únicas por NSR)
        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const uniqueNew = newPunches.filter(p => !existingNsrs.has(p.nsr));

        return {
          people: updatedPeople.filter(p => p.ids.length > 0), // Remove fantasmas sem ID
          punches: [...prev.punches, ...uniqueNew],
          lastImport: {
            file: file.name,
            atISO: new Date().toISOString(),
            stats: { ...stats, uniqueIds: new Set(newPunches.map(p => p.id)).size }
          }
        };
      });
    };
    event.target.value = '';
  };

  // --- LÓGICA DE VISUALIZAÇÃO ---
  const filteredPeople = useMemo(() => {
    return store.people.filter(p => 
      p.name.includes(searchTerm.toUpperCase()) || p.ids.some(id => id.includes(searchTerm))
    ).sort((a, b) => a.name.localeCompare(b.name));
  }, [store.people, searchTerm]);

  const activePerson = useMemo(() => 
    store.people.find(p => p.name === activePersonName), 
    [store.people, activePersonName]
  );

  const getPersonPunches = (p: Person, month: string) => {
    return store.punches
      .filter(pun => p.ids.includes(pun.id) && pun.dayISO.startsWith(month))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));
  };

  const calculateDayMins = (punches: Punch[]) => {
    if (punches.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < punches.length - 1; i += 2) {
      const [h1, m1] = punches[i].time.split(':').map(Number);
      const [h2, m2] = punches[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  const formatMins = (mins: number) => {
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  const handlePrintMirror = () => {
    if (!activePerson) return;
    const punches = getPersonPunches(activePerson, selectedMonth);
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(Number(year), Number(month), 0).getDate();

    const win = window.open('', '_blank');
    if (!win) return;

    win.document.write(`
      <html>
        <head>
          <title>Espelho de Ponto - ${activePerson.name}</title>
          <style>
            @page { size: A4; margin: 15mm; }
            body { font-family: 'Courier New', monospace; font-size: 10px; line-height: 1.2; color: #000; }
            .header { text-align: center; border: 1px solid #000; padding: 10px; margin-bottom: 10px; }
            .info { display: grid; grid-template-columns: 1fr 1fr; border: 1px solid #000; padding: 10px; gap: 5px; margin-bottom: 10px; }
            table { width: 100%; border-collapse: collapse; }
            th, td { border: 1px solid #000; padding: 3px; font-size: 9px; text-align: center; }
            th { background: #eee; text-transform: uppercase; }
            .footer { margin-top: 30px; display: grid; grid-template-columns: 1fr 1fr; gap: 40px; text-align: center; }
            .sign { border-top: 1px solid #000; padding-top: 5px; }
          </style>
        </head>
        <body>
          <div class="header">
            <h2 style="margin:0">ESPELHO DE PONTO ELETRÔNICO</h2>
            <p style="margin:2px">PERÍODO: 01/${month}/${year} ATÉ ${lastDay}/${month}/${year}</p>
          </div>
          <div class="info">
            <div>
              <strong>EMPRESA:</strong> ABC DA CONSTRUÇÃO ITU<br>
              <strong>NOME:</strong> ${activePerson.name}<br>
              <strong>CARGO:</strong> ${activePerson.cargo || 'COLABORADOR'}
            </div>
            <div>
              <strong>PIS/ID:</strong> ${activePerson.pis_oficial || activePerson.ids[0]}<br>
              <strong>MATRÍCULA:</strong> ${activePerson.matricula || activePerson.ids.join(' / ')}<br>
              <strong>ADMISSÃO:</strong> ${activePerson.admissao || '--/--/----'}
            </div>
          </div>
          <table>
            <thead>
              <tr>
                <th width="15%">DIA</th>
                <th width="40%">MARCAÇÕES REGISTRADAS</th>
                <th>E1</th><th>S1</th><th>E2</th><th>S2</th>
                <th width="10%">TOTAL</th>
                <th width="5%">CH</th>
              </tr>
            </thead>
            <tbody>
              ${Array.from({ length: lastDay }, (_, i) => {
                const day = (i + 1).toString().padStart(2, '0');
                const iso = `${selectedMonth}-${day}`;
                const dayPunches = punches.filter(p => p.dayISO === iso);
                const mins = calculateDayMins(dayPunches);
                const wd = new Date(iso + 'T12:00:00').toLocaleDateString('pt-BR', { weekday: 'short' });
                return `
                  <tr>
                    <td>${day}/${month} ${wd.toUpperCase()}</td>
                    <td style="font-size: 8px">${dayPunches.map(p => p.time).join(' ')}</td>
                    <td>${dayPunches[0]?.time || ''}</td>
                    <td>${dayPunches[1]?.time || ''}</td>
                    <td>${dayPunches[2]?.time || ''}</td>
                    <td>${dayPunches[3]?.time || ''}</td>
                    <td>${mins > 0 ? formatMins(mins) : ''}</td>
                    <td>${dayPunches.length === 4 ? '00008' : dayPunches.length === 2 ? '00007' : ''}</td>
                  </tr>
                `;
              }).join('')}
            </tbody>
          </table>
          <p style="font-size: 8px; margin-top: 10px">Horários contratuais do empregado: Jornada flexível conforme escala.</p>
          <div class="footer">
            <div class="sign">ASSINATURA DO EMPREGADOR</div>
            <div class="sign">ASSINATURA DO EMPREGADO</div>
          </div>
          <script>window.print();</script>
        </body>
      </html>
    `);
    win.document.close();
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* HEADER PRINCIPAL */}
      <div className="flex flex-col lg:flex-row justify-between items-center gap-6 bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl">
        <div className="flex items-center gap-5">
           <div className="bg-[#E30613] p-4 rounded-3xl shadow-lg">
              <ShieldCheck className="w-8 h-8 text-white" />
           </div>
           <div>
              <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tighter leading-none">Gestão de Horas</h2>
              <p className="text-slate-400 font-bold text-[10px] uppercase tracking-widest mt-2">Unificação por Identidade Nominal (Aliases)</p>
           </div>
        </div>

        <div className="flex items-center gap-3">
          <input 
            type="month" 
            value={selectedMonth} 
            onChange={e => setSelectedMonth(e.target.value)} 
            className="bg-slate-50 border border-slate-200 rounded-2xl px-5 py-3 text-xs font-black outline-none focus:ring-2 focus:ring-[#E30613]" 
          />
          <label className="flex items-center gap-3 px-8 py-4 bg-[#0A1121] text-white rounded-2xl cursor-pointer hover:bg-black transition-all font-black text-xs uppercase shadow-xl group">
            <FileUp className="w-5 h-5 text-[#E30613] group-hover:scale-110 transition-transform" /> 
            <span>LER AFD</span>
            <input type="file" className="hidden" accept=".txt" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* SIDEBAR DE PESSOAS */}
        <div className="lg:col-span-1 space-y-4">
          <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm sticky top-24">
            <div className="relative mb-6">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
              <input 
                type="text" 
                placeholder="Buscar Nome ou ID..." 
                value={searchTerm} 
                onChange={e => setSearchTerm(e.target.value)} 
                className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl text-xs font-bold outline-none" 
              />
            </div>
            <div className="space-y-2 max-h-[55vh] overflow-y-auto custom-scrollbar pr-2">
              {filteredPeople.map(p => {
                const punches = getPersonPunches(p, selectedMonth);
                const workedDays = new Set(punches.map(pu => pu.dayISO)).size;
                return (
                  <button 
                    key={p.name}
                    onClick={() => { setActivePersonName(p.name); setIsEditingInfo(false); }}
                    className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonName === p.name ? 'bg-[#E30613] text-white shadow-lg border-[#E30613]' : 'bg-slate-50 border-transparent text-slate-600 hover:bg-slate-100'}`}
                  >
                    <div className="flex justify-between items-start">
                      <p className="text-[10px] font-black uppercase truncate leading-tight flex-1">{p.name}</p>
                      {workedDays > 0 && <span className={`text-[8px] font-black px-1.5 py-0.5 rounded ${activePersonName === p.name ? 'bg-white/20' : 'bg-emerald-100 text-emerald-600'}`}>{workedDays}D</span>}
                    </div>
                    <p className={`text-[8px] font-bold mt-1 ${activePersonName === p.name ? 'text-white/60' : 'text-slate-400'}`}>IDs: {p.ids.join(', ')}</p>
                  </button>
                );
              })}
            </div>

            <div className="mt-6 pt-6 border-t border-slate-100 grid grid-cols-2 gap-2">
               <button onClick={() => {
                 const blob = new Blob([JSON.stringify(store)], { type: 'application/json' });
                 const url = URL.createObjectURL(blob);
