                    </div>
                    <div className="space-y-2">
                       <label className="text-[9px] font-black uppercase text-slate-400 ml-1">PIS Oficial</label>
                       <input type="text" value={activePerson.pis_oficial || ''} onChange={e => setStore(prev => ({...prev, people: prev.people.map(p => p.name === activePerson.name ? {...p, pis_oficial: e.target.value} : p)}))} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:border-[#E30613]" />
                    </div>
                    <div className="space-y-2">
                       <label className="text-[9px] font-black uppercase text-slate-400 ml-1">Admissão</label>
                       <input type="date" value={activePerson.admissao || ''} onChange={e => setStore(prev => ({...prev, people: prev.people.map(p => p.name === activePerson.name ? {...p, admissao: e.target.value} : p)}))} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:border-[#E30613]" />
                    </div>
                  </div>
               )}

               {/* TABELA DE REGISTROS */}
               <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                  <table className="w-full text-left">
                    <thead>
                      <tr className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-widest">
                        <th className="px-8 py-6">Data / Semana</th>
                        <th className="px-8 py-6">Marcações Registradas (AFD)</th>
                        <th className="px-4 py-6 text-center">Horas</th>
                        <th className="px-4 py-6 text-center">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {(() => {
                        const [year, month] = selectedMonth.split('-');
                        const days = new Date(Number(year), Number(month), 0).getDate();
                        const punches = getPersonPunches(activePerson, selectedMonth);

                        return Array.from({ length: days }, (_, i) => {
                          const day = (i + 1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dayPunches = punches.filter(p => p.dayISO === iso);
                          const dayMins = calculateDayMins(dayPunches);
                          const dt = new Date(iso + 'T12:00:00');

                          return (
                            <tr key={iso} className={`group hover:bg-slate-50 transition-all ${dayPunches.length === 0 ? 'opacity-30' : ''}`}>
                              <td className="px-8 py-5">
                                <span className="text-sm font-black text-slate-900">{day}/{month}</span>
                                <span className="text-[9px] font-bold text-slate-400 uppercase block leading-none">{dt.toLocaleDateString('pt-BR', { weekday: 'short' })}</span>
                              </td>
                              <td className="px-8 py-5">
                                <div className="flex flex-wrap gap-2">
                                  {dayPunches.length > 0 ? dayPunches.map((p, idx) => (
                                    <span key={idx} className="bg-slate-100 text-slate-700 text-[11px] font-black px-2.5 py-1.5 rounded-lg border border-slate-200">{p.time}</span>
                                  )) : <span className="text-slate-200 text-[10px] font-bold uppercase tracking-widest">—</span>}
                                  <button onClick={() => {
                                    const h = prompt("Digite a hora (HH:MM):", "08:00");
                                    if(h && h.includes(":")) {
                                      setStore(prev => ({
                                        ...prev,
                                        punches: [...prev.punches, { id: activePerson.ids[0], dayISO: iso, time: h, nsr: `MAN-${Date.now()}` }]
                                      }));
                                    }
                                  }} className="p-1.5 text-slate-200 hover:text-[#E30613] hover:bg-red-50 rounded-lg transition-all"><Plus className="w-4 h-4" /></button>
                                </div>
                              </td>
                              <td className="px-4 py-5 text-center">
                                <span className={`text-xs font-black ${dayMins > 0 ? 'text-emerald-600' : 'text-slate-200'}`}>
                                  {dayMins > 0 ? formatMins(dayMins) : '--:--'}
                                </span>
                              </td>
                              <td className="px-4 py-5 text-center">
                                 {/* FIX: Remove 'title' prop from Lucide component and wrap in a span with standard title attribute */}
                                 {dayPunches.length % 2 !== 0 && <span title="Batida ímpar"><AlertOctagon className="w-4 h-4 text-red-500 mx-auto" /></span>}
                                 {dayPunches.length >= 2 && dayPunches.length % 2 === 0 && <span className="text-[9px] font-black text-emerald-500 uppercase">Ok</span>}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner">
               <Fingerprint className="w-24 h-24 opacity-10 mb-6 animate-pulse" />
               <p className="text-2xl font-black text-slate-400 uppercase tracking-tighter">Selecione um colaborador para conferir</p>
               {store.lastImport && (
                 <div className="mt-8 flex items-center gap-3 px-6 py-3 bg-emerald-50 rounded-2xl border border-emerald-100 text-emerald-600">
                    <History className="w-4 h-4" />
                    <span className="text-[10px] font-black uppercase tracking-widest">Último AFD: {store.lastImport.stats.punches} batidas / {store.lastImport.stats.uniqueIds} colaboradores</span>
                 </div>
               )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Clock, FileUp, Calendar, FileText, Search, ShieldCheck, Plus, 
  Fingerprint, IdCard, AlertOctagon, Printer, Trash2, Download, 
  Database, UserPlus, History, Save, Edit3, X
} from 'lucide-react';

// --- TIPAGEM ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; 
  active: boolean; 
  cargo?: string; 
  admissao?: string; 
  pis_oficial?: string;
  matricula?: string;
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    atISO: string; 
    stats: { lines: number; punches: number; users: number; uniqueIds: number } 
  };
};

// --- CONSTANTES REGEX OBRIGATÓRIAS ---
const RX_PUNCH = /^(\d{10})3(\d{8})(\d{4})(\d{11,12})/; // Batida
const RX_USER = /^(\d{10})5(\d{8})(\d{4})([EIA])(\d{11,12})([A-ZÀ-Ü]{3,}(?:\s+[A-ZÀ-Ü]{2,})+)/; // Cadastro

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_rh_ponto_final_v3');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonName, setActivePersonName] = useState<string | null>(null);
  const [isEditingInfo, setIsEditingInfo] = useState(false);

  useEffect(() => {
    localStorage.setItem('abc_rh_ponto_final_v3', JSON.stringify(store));
  }, [store]);

  // Normalização: Remove zeros à esquerda para garantir que ID 0123 === 123
  const normId = (raw: string): string => raw.replace(/\D/g, '').replace(/^0+/, '');
  const normName = (raw: string): string => raw.trim().replace(/\s+/g, ' ').toUpperCase();

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1");

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/);

      const newPunches: Punch[] = [];
      const extractedUsers = new Map<string, string>(); // ID Normalizado -> Nome
      const stats = { lines: 0, punches: 0, users: 0 };

      // PASSADA 1: Identificar todos os nomes/cadastros no arquivo
      lines.forEach(line => {
        stats.lines++;
        const userMatch = line.match(RX_USER);
        if (userMatch) {
          const id = normId(userMatch[5]);
          const name = normName(userMatch[6]);
          extractedUsers.set(id, name);
          stats.users++;
        }
      });

      // PASSADA 2: Identificar todas as batidas
      lines.forEach(line => {
        const punchMatch = line.match(RX_PUNCH);
        if (punchMatch) {
          const [, nsr, ddmmyyyy, hhmm, idRaw] = punchMatch;
          newPunches.push({
            nsr,
            dayISO: `${ddmmyyyy.slice(4, 8)}-${ddmmyyyy.slice(2, 4)}-${ddmmyyyy.slice(0, 2)}`,
            time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
            id: normId(idRaw)
          });
          stats.punches++;
        }
      });

      setStore(prev => {
        const updatedPeople = [...prev.people];

        // 1. Vincular IDs aos Nomes
        extractedUsers.forEach((name, id) => {
          let person = updatedPeople.find(p => p.name === name);
          if (!person) {
            person = { name, ids: [id], active: true };
            updatedPeople.push(person);
          } else if (!person.ids.includes(id)) {
            person.ids.push(id);
          }
        });

        // 2. Criar colaboradores genéricos para batidas sem nome
        newPunches.forEach(p => {
          const owner = updatedPeople.find(pers => pers.ids.includes(p.id));
          if (!owner) {
            updatedPeople.push({ name: `COLABORADOR ${p.id}`, ids: [p.id], active: true });
          }
        });

        // 3. Mesclar batidas evitando duplicar NSR
        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const uniqueNew = newPunches.filter(p => !existingNsrs.has(p.nsr));

        return {
          people: updatedPeople,
          punches: [...prev.punches, ...uniqueNew],
          lastImport: {
            file: file.name,
            atISO: new Date().toISOString(),
            stats: { ...stats, uniqueIds: new Set(newPunches.map(p => p.id)).size }
          }
        };
      });
    };
    event.target.value = '';
  };

  const filteredPeople = useMemo(() => {
    return store.people.filter(p => 
      p.name.includes(searchTerm.toUpperCase()) || p.ids.some(id => id.includes(searchTerm))
    ).sort((a, b) => a.name.localeCompare(b.name));
  }, [store.people, searchTerm]);

  const activePerson = useMemo(() => 
    store.people.find(p => p.name === activePersonName), 
    [store.people, activePersonName]
  );

  const getPersonPunches = (p: Person, month: string) => {
    return store.punches
      .filter(pun => p.ids.includes(pun.id) && pun.dayISO.startsWith(month))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));
  };

  const calculateDayMins = (punches: Punch[]) => {
    if (punches.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < punches.length - 1; i += 2) {
      const [h1, m1] = punches[i].time.split(':').map(Number);
      const [h2, m2] = punches[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  const formatMins = (mins: number) => {
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  const handlePrintMirror = () => {
    if (!activePerson) return;
    const punches = getPersonPunches(activePerson, selectedMonth);
    const [year, month] = selectedMonth.split('-');
    const lastDay = new Date(Number(year), Number(month), 0).getDate();

    const win = window.open('', '_blank');
    if (!win) return;

    win.document.write(`
      <html>
        <head>
          <title>Espelho ${activePerson.name}</title>
          <style>
            body { font-family: monospace; font-size: 10px; padding: 20px; }
            table { width: 100%; border-collapse: collapse; margin-top: 10px; }
            th, td { border: 1px solid #000; padding: 4px; text-align: center; }
            .header { text-align: center; border: 1px solid #000; padding: 10px; margin-bottom: 5px; }
          </style>
        </head>
        <body>
          <div class="header">
            <h2>ESPELHO DE PONTO ELETRÔNICO</h2>
            <p>PERÍODO: 01/${month}/${year} A ${lastDay}/${month}/${year}</p>
            <p>NOME: ${activePerson.name} | PIS: ${activePerson.pis_oficial || activePerson.ids[0]}</p>
          </div>
          <table>
            <thead><tr><th>DATA</th><th>BATIDAS</th><th>TOTAL</th><th>CH</th></tr></thead>
            <tbody>
              ${Array.from({ length: lastDay }, (_, i) => {
                const day = (i + 1).toString().padStart(2, '0');
                const iso = `${selectedMonth}-${day}`;
                const dp = punches.filter(p => p.dayISO === iso);
                const m = calculateDayMins(dp);
                return `<tr>
                  <td>${day}/${month}</td>
                  <td>${dp.map(p => p.time).join(' ')}</td>
                  <td>${m > 0 ? formatMins(m) : ''}</td>
                  <td>${dp.length === 4 ? '00008' : dp.length === 2 ? '00007' : ''}</td>
                </tr>`;
              }).join('')}
            </tbody>
          </table>
          <script>window.print();</script>
        </body>
      </html>
    `);
    win.document.close();
  };

  return (
    <div className="space-y-6">
      {/* HEADER */}
      <div className="flex justify-between items-center bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl">
        <div className="flex items-center gap-5">
           <div className="bg-[#E30613] p-4 rounded-3xl shadow-lg"><ShieldCheck className="w-6 h-6 text-white" /></div>
           <div>
              <h2 className="text-2xl font-black uppercase tracking-tighter">Gestão de Horas</h2>
              <p className="text-[10px] font-bold text-slate-400 uppercase">Unificação Nominal v3</p>
           </div>
        </div>
        <div className="flex items-center gap-3">
          <input type="month" value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)} className="bg-slate-50 border rounded-xl px-4 py-2 text-xs font-bold" />
          <label className="bg-[#0A1121] text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase cursor-pointer flex items-center gap-2">
            <FileUp className="w-4 h-4 text-[#E30613]" /> LER AFD <input type="file" className="hidden" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* SIDEBAR */}
        <div className="bg-white border rounded-[2.5rem] p-6 shadow-sm">
          <div className="relative mb-4">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input type="text" placeholder="Buscar..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-slate-50 border rounded-xl text-xs font-bold" />
          </div>
          <div className="space-y-2 max-h-[60vh] overflow-y-auto pr-2">
            {filteredPeople.map(p => (
              <button key={p.name} onClick={() => { setActivePersonName(p.name); setIsEditingInfo(false); }} className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonName === p.name ? 'bg-[#E30613] text-white border-[#E30613]' : 'bg-slate-50 border-transparent hover:bg-slate-100'}`}>
                <p className="text-[10px] font-black uppercase truncate">{p.name}</p>
                <p className="text-[8px] opacity-60">IDs: {p.ids.join(', ')}</p>
              </button>
            ))}
          </div>
        </div>

        {/* CONTENT */}
        <div className="lg:col-span-3">
          {activePerson ? (
            <div className="space-y-6">
               <div className="bg-white border rounded-[2.5rem] p-8 shadow-xl flex justify-between items-center">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center border"><IdCard className="text-[#E30613]" /></div>
                     <div>
                        <h3 className="text-xl font-black uppercase">{activePerson.name}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase">IDs Vinculados: {activePerson.ids.join(' • ')}</p>
                     </div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => setIsEditingInfo(!isEditingInfo)} className="p-4 bg-slate-50 rounded-xl hover:bg-slate-100 transition-all"><Edit3 className="w-5 h-5 text-slate-400" /></button>
                    <button onClick={handlePrintMirror} className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2"><Printer className="w-4 h-4 text-emerald-500" /> Espelho</button>
                  </div>
               </div>

               {isEditingInfo && (
                  <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white grid grid-cols-1 md:grid-cols-4 gap-6 animate-in zoom-in-95">
                    <div className="space-y-1">
                      <label className="text-[9px] font-black text-slate-500 uppercase">Cargo</label>
                      <input type="text" value={activePerson.cargo || ''} onChange={e => setStore(prev => ({...prev, people: prev.people.map(p => p.name === activePerson.name ? {...p, cargo: e.target.value} : p)}))} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2 text-xs" />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-black text-slate-500 uppercase">Matrícula</label>
                      <input type="text" value={activePerson.matricula || ''} onChange={e => setStore(prev => ({...prev, people: prev.people.map(p => p.name === activePerson.name ? {...p, matricula: e.target.value} : p)}))} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2 text-xs" />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-black text-slate-500 uppercase">PIS Oficial</label>
                      <input type="text" value={activePerson.pis_oficial || ''} onChange={e => setStore(prev => ({...prev, people: prev.people.map(p => p.name === activePerson.name ? {...p, pis_oficial: e.target.value} : p)}))} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2 text-xs" />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-black text-slate-500 uppercase">Admissão</label>
                      <input type="date" value={activePerson.admissao || ''} onChange={e => setStore(prev => ({...prev, people: prev.people.map(p => p.name === activePerson.name ? {...p, admissao: e.target.value} : p)}))} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-2 text-xs" />
                    </div>
                  </div>
               )}

               <div className="bg-white border rounded-[3rem] shadow-2xl overflow-hidden">
                  <table className="w-full text-left">
                    <thead className="bg-slate-900 text-slate-400 text-[10px] font-black uppercase">
                      <tr><th className="px-8 py-5">Data</th><th className="px-8 py-5">Batidas AFD</th><th className="px-4 py-5 text-center">Horas</th><th className="px-4 py-5 text-center">Status</th></tr>
                    </thead>
                    <tbody className="divide-y">
                      {(() => {
                        const [y, m] = selectedMonth.split('-');
                        const days = new Date(Number(y), Number(m), 0).getDate();
                        const punches = getPersonPunches(activePerson, selectedMonth);
                        return Array.from({length: days}, (_, i) => {
                          const day = (i+1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dp = punches.filter(p => p.dayISO === iso);
                          const dm = calculateDayMins(dp);
                          return (
                            <tr key={iso} className={`hover:bg-slate-50 ${dp.length === 0 ? 'opacity-30' : ''}`}>
                              <td className="px-8 py-4"><span className="text-xs font-black">{day}/{m}</span></td>
                              <td className="px-8 py-4 flex flex-wrap gap-2">
