                              <button onClick={() => {
                                const t = prompt("Hora (HH:MM):", "08:00");
                                if(t) setStore(prev => ({...prev, punches: [...prev.punches, { id: activePerson.ids[0], dayISO: iso, time: t, nsr: 'MAN-'+Date.now() }]}));
                              }} className="text-slate-200 hover:text-[#E30613]"><Plus className="w-4 h-4" /></button>
                            </td>
                            <td className="px-4 py-4 text-center font-black text-xs">{mins > 0 ? formatMins(mins) : '--:--'}</td>
