              {store.lastImport && <div className="mt-4 p-4 bg-emerald-50 rounded-2xl text-[9px] font-black uppercase text-emerald-600">Último Arquivo: {store.lastImport.file} ({store.lastImport.stats.punches} batidas lidas)</div>}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  FileUp, Search, ShieldCheck, Plus, 
  IdCard, AlertOctagon, Printer, Trash2, Download, 
  Edit3, Fingerprint, History, X
} from 'lucide-react';

// --- MODELO DE DADOS ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; 
  active: boolean; 
  cargo?: string; 
  admissao?: string; 
  pis_oficial?: string;
  matricula?: string;
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    stats: { lines: number; punches: number; users: number } 
  };
};

// --- REGEX CIRÚRGICAS BASEADAS NO SEU ARQUIVO ---
// Tipo 3: NSR(10) + '3' + DATA(8) + HORA(4) + ID(12)
const RX_PUNCH = /^(\d{10})3(\d{8})(\d{4})(\d{11,12})/;

// Tipo 5: NSR(10) + '5' + DATA(8) + HORA(4) + TIPO(1) + ID(11-12) + NOME
// Nota: O nome começa logo após o ID. O ID no seu arquivo iDClass tem 12 dígitos.
const RX_USER = /^(\d{10})5(\d{8})(\d{4})[EIA](\d{12})([A-ZÀ-Ü\s]{3,})/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_rh_ponto_vFinal_v4');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonName, setActivePersonName] = useState<string | null>(null);
  const [isEditingInfo, setIsEditingInfo] = useState(false);

  useEffect(() => {
    localStorage.setItem('abc_rh_ponto_vFinal_v4', JSON.stringify(store));
  }, [store]);

  // NORMALIZAÇÃO CRÍTICA: Remove zeros à esquerda para unificar IDs variantes
  const normId = (raw: string): string => raw.trim().replace(/^0+/, '');
  const normName = (raw: string): string => raw.trim().replace(/\s+/g, ' ').toUpperCase();

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1"); // Para capturar acentos como JÚLIO ou JOCELI

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/);

      const newPunches: Punch[] = [];
      const extractedUsers = new Map<string, string>(); // ID Normalizado -> Nome Normalizado
      let totalLines = 0;

      // PASSADA 1: Mapear Cadastros (Tipo 5)
      lines.forEach(line => {
        if (!line.trim()) return;
        totalLines++;

        const userMatch = line.match(RX_USER);
        if (userMatch) {
          const id = normId(userMatch[4]);
          const name = normName(userMatch[5]);
          if (name.length > 3) {
            extractedUsers.set(id, name);
          }
        }
      });

      // PASSADA 2: Mapear Batidas (Tipo 3)
      lines.forEach(line => {
        const punchMatch = line.match(RX_PUNCH);
        if (punchMatch) {
          const [, nsr, ddmmyyyy, hhmm, idRaw] = punchMatch;
          newPunches.push({
            nsr,
            dayISO: `${ddmmyyyy.slice(4, 8)}-${ddmmyyyy.slice(2, 4)}-${ddmmyyyy.slice(0, 2)}`,
            time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
            id: normId(idRaw)
          });
        }
      });

      setStore(prev => {
        const currentPeople = [...prev.people];

        // 1. Atualizar ou Criar Pessoas baseadas no mapeamento de nomes
        extractedUsers.forEach((name, id) => {
          let person = currentPeople.find(p => p.name === name);
          if (!person) {
            // Se o ID já estava em outro colaborador genérico, removemos o ID de lá
            currentPeople.forEach(p => {
              p.ids = p.ids.filter(existingId => existingId !== id);
            });
            currentPeople.push({ name, ids: [id], active: true });
          } else {
            if (!person.ids.includes(id)) {
              // Garante que esse ID não pertença a mais ninguém
              currentPeople.forEach(p => { p.ids = p.ids.filter(x => x !== id); });
              person.ids.push(id);
            }
          }
        });

        // 2. Criar colaboradores temporários para IDs de batida que ainda não têm nome
        newPunches.forEach(p => {
          const owner = currentPeople.find(pers => pers.ids.includes(p.id));
          if (!owner) {
            currentPeople.push({ name: `COLABORADOR ${p.id}`, ids: [p.id], active: true });
          }
        });

        // 3. Mesclar batidas evitando duplicar o NSR (Número Sequencial de Registro)
        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const uniqueNewPunches = newPunches.filter(p => !existingNsrs.has(p.nsr));

        return {
          people: currentPeople.filter(p => p.ids.length > 0), // Remove quem ficou sem ID
          punches: [...prev.punches, ...uniqueNewPunches],
          lastImport: {
            file: file.name,
            stats: { lines: totalLines, punches: newPunches.length, users: extractedUsers.size }
          }
        };
      });
    };
    event.target.value = '';
  };

  // --- LÓGICA DE INTERFACE ---
  const filteredPeople = useMemo(() => {
    return store.people
      .filter(p => p.name.includes(searchTerm.toUpperCase()) || p.ids.some(id => id.includes(searchTerm)))
      .sort((a, b) => {
        // Coloca colaboradores sem nome no final da lista
        const aGen = a.name.startsWith('COLABORADOR');
        const bGen = b.name.startsWith('COLABORADOR');
        if (aGen && !bGen) return 1;
        if (!aGen && bGen) return -1;
        return a.name.localeCompare(b.name);
      });
  }, [store.people, searchTerm]);

  const activePerson = store.people.find(p => p.name === activePersonName);

  const getPunches = (p: Person, month: string) => 
    store.punches.filter(pun => p.ids.includes(pun.id) && pun.dayISO.startsWith(month))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));

  const calculateDayMins = (punches: Punch[]) => {
    if (punches.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < punches.length - 1; i += 2) {
      const [h1, m1] = punches[i].time.split(':').map(Number);
      const [h2, m2] = punches[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  const formatMins = (mins: number) => {
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
