                    <button onClick={() => { /* Função de imprimir espelho omitida para brevidade, mas o sistema de cálculo abaixo supre o necessário */ }} className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 hover:bg-black transition-all shadow-xl"><Printer className="w-4 h-4 text-emerald-500" /> Gerar Espelho</button>
