  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  FileUp, Search, ShieldCheck, Plus, 
  IdCard, AlertOctagon, Printer, Edit3, Fingerprint, History
} from 'lucide-react';

// --- MODELO DE DADOS ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; // Aliases canonicalizados
  active: boolean; 
  cargo?: string; 
  admissao?: string; 
  pis_oficial?: string;
  matricula?: string;
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    stats: { lines: number; punches: number; users: number } 
  };
};

// --- MOTOR DE PARSING ---

// Canonicalização: Garante 12 dígitos com zeros à esquerda
const canon12 = (d: string) => d.replace(/\D/g, '').padStart(12, '0').slice(-12);

// Tipo 5: NSR(10) + '5' + Data(8) + Hora(4) + [IAE] + ID(números) + Nome(letras)
// Usamos \d+ para o ID e capturamos o Nome a partir da primeira letra maiúscula
const RX_USER_IDCLASS = /^(\d{10})5\d{8}\d{4}[IAE](\d+)([A-ZÀ-Ü]{3,}.*)$/;

// Tipo 3: NSR(10) + '3' + Data(8) + Hora(4) + [IAE]? + ID(11 ou 12)
const RX_PUNCH_IDCLASS = /^(\d{10})3(\d{8})(\d{4})[IAE]?(\d{11,12})/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_rh_ponto_v5_nominal');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonName, setActivePersonName] = useState<string | null>(null);
  const [isEditingInfo, setIsEditingInfo] = useState(false);

  useEffect(() => {
    localStorage.setItem('abc_rh_ponto_v5_nominal', JSON.stringify(store));
  }, [store]);

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1"); 

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/);

      const newPunches: Punch[] = [];
      const userMap = new Map<string, string>(); // ID Canonizado -> Nome
      let totalLines = 0;

      lines.forEach(line => {
        const raw = line.trim();
        if (!raw) return;
        totalLines++;

        // Passada para Tipo 5 (Usuários)
        const userMatch = raw.match(RX_USER_IDCLASS);
        if (userMatch) {
          const id = canon12(userMatch[2]);
          const name = userMatch[3].trim().toUpperCase();
          if (name.length > 3) userMap.set(id, name);
          return;
        }

        // Passada para Tipo 3 (Batidas)
        const punchMatch = raw.match(RX_PUNCH_IDCLASS);
        if (punchMatch) {
          const [, nsr, ddmmyyyy, hhmm, idRaw] = punchMatch;
          newPunches.push({
            nsr,
            dayISO: `${ddmmyyyy.slice(4, 8)}-${ddmmyyyy.slice(2, 4)}-${ddmmyyyy.slice(0, 2)}`,
            time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
            id: canon12(idRaw)
          });
        }
      });

      setStore(prev => {
        const people = [...prev.people];

        // 1. Unificação por Nome (Identidade Nominal)
        userMap.forEach((name, id) => {
          let person = people.find(p => p.name === name);
          if (!person) {
            // Se o ID já estava em um "COLABORADOR X", removemos de lá
            people.forEach(p => p.ids = p.ids.filter(x => x !== id));
            people.push({ name, ids: [id], active: true });
          } else {
            if (!person.ids.includes(id)) {
              people.forEach(p => p.ids = p.ids.filter(x => x !== id));
              person.ids.push(id);
            }
          }
        });

        // 2. Garante que batidas sem nome criem um colaborador genérico
        newPunches.forEach(p => {
          const owner = people.find(pers => pers.ids.includes(p.id));
          if (!owner) {
            people.push({ name: `COLABORADOR ${p.id}`, ids: [p.id], active: true });
          }
        });

        // 3. Mescla Batidas por NSR
        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const filteredNew = newPunches.filter(p => !existingNsrs.has(p.nsr));

        return {
          people: people.filter(p => p.ids.length > 0),
          punches: [...prev.punches, ...filteredNew],
          lastImport: {
            file: file.name,
            stats: { lines: totalLines, punches: newPunches.length, users: userMap.size }
          }
        };
      });
    };
    event.target.value = '';
  };

  const filteredPeople = useMemo(() => {
    return store.people
      .filter(p => p.name.includes(searchTerm.toUpperCase()) || p.ids.some(id => id.includes(searchTerm)))
      .sort((a, b) => {
        const aGen = a.name.startsWith('COLABORADOR');
        const bGen = b.name.startsWith('COLABORADOR');
        if (aGen && !bGen) return 1;
        if (!aGen && bGen) return -1;
        return a.name.localeCompare(b.name);
      });
  }, [store.people, searchTerm]);

  const activePerson = store.people.find(p => p.name === activePersonName);

  const getPunches = (p: Person, month: string) => 
    store.punches.filter(pun => p.ids.includes(pun.id) && pun.dayISO.startsWith(month))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));

  const calculateDayMins = (punches: Punch[]) => {
    if (punches.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < punches.length - 1; i += 2) {
      const [h1, m1] = punches[i].time.split(':').map(Number);
      const [h2, m2] = punches[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  const formatMins = (mins: number) => {
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl flex justify-between items-center">
        <div className="flex items-center gap-5">
          <div className="bg-[#E30613] p-4 rounded-2xl shadow-lg shadow-red-100">
            <ShieldCheck className="text-white w-6 h-6" />
          </div>
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter text-[#0A1121]">Gestão de Horas</h2>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Unificação por Identidade Nominal (Aliases)</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <input type="month" value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)} className="bg-slate-50 border rounded-xl px-4 py-2 text-xs font-bold outline-none" />
          <label className="bg-[#0A1121] text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase cursor-pointer flex items-center gap-2 hover:bg-black transition-all shadow-xl">
            <FileUp className="w-4 h-4 text-[#E30613]" /> LER AFD <input type="file" className="hidden" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="bg-white border rounded-[2.5rem] p-6 shadow-sm min-h-[70vh]">
          <div className="relative mb-6">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input type="text" placeholder="Buscar Nome ou ID..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-slate-50 border rounded-xl text-xs font-bold outline-none" />
          </div>
          <div className="space-y-2 max-h-[60vh] overflow-y-auto pr-2 custom-scrollbar">
            {filteredPeople.map(p => (
              <button key={p.name} onClick={() => { setActivePersonName(p.name); setIsEditingInfo(false); }} className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonName === p.name ? 'bg-[#E30613] text-white border-[#E30613] shadow-lg' : 'bg-slate-50 border-transparent hover:bg-slate-100 text-slate-600'}`}>
                <p className="text-[10px] font-black uppercase truncate leading-tight">{p.name}</p>
                <p className={`text-[8px] mt-1 ${activePersonName === p.name ? 'text-white/60' : 'text-slate-400'}`}>IDs: {p.ids.join(', ')}</p>
              </button>
            ))}
          </div>
        </div>

        <div className="lg:col-span-3">
          {activePerson ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
               <div className="bg-white border rounded-[2.5rem] p-8 shadow-xl flex justify-between items-center">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center border border-slate-100 shadow-sm"><IdCard className="text-[#E30613] w-8 h-8" /></div>
                     <div>
                        <h3 className="text-xl font-black uppercase text-slate-900 leading-none">{activePerson.name}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-2 tracking-widest">Vínculos AFD: {activePerson.ids.join(' • ')}</p>
                     </div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => setIsEditingInfo(!isEditingInfo)} className={`p-4 rounded-xl transition-all ${isEditingInfo ? 'bg-slate-900 text-white' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}><Edit3 className="w-5 h-5" /></button>
                    <button onClick={() => window.print()} className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 hover:bg-black transition-all shadow-xl"><Printer className="w-4 h-4 text-emerald-500" /> Imprimir Espelho</button>
                  </div>
               </div>

               <div className="bg-white border rounded-[3rem] shadow-2xl overflow-hidden border-slate-200">
                  <table className="w-full text-left">
                    <thead className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-10 py-6">Data / Semana</th>
                        <th className="px-10 py-6">Marcações Registradas (AFD)</th>
                        <th className="px-4 py-6 text-center">Horas</th>
                        <th className="px-4 py-6 text-center">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {(() => {
                        const [y, m] = selectedMonth.split('-');
                        const days = new Date(Number(y), Number(m), 0).getDate();
                        const punches = getPunches(activePerson, selectedMonth);
                        return Array.from({length: days}, (_, i) => {
                          const day = (i+1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dp = punches.filter(p => p.dayISO === iso);
                          const mins = calculateDayMins(dp);
                          const dt = new Date(iso + 'T12:00:00');
                          const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                          return (
                            <tr key={iso} className={`group hover:bg-slate-50 transition-all ${dp.length === 0 ? 'opacity-30' : ''} ${isWeekend ? 'bg-slate-50/30' : ''}`}>
                              <td className="px-10 py-5">
                                <span className="text-sm font-black text-slate-900">{day}/{m}</span>
                                <span className="text-[9px] font-bold text-slate-400 uppercase block leading-none">{dt.toLocaleDateString('pt-BR', {weekday: 'short'})}</span>
                              </td>
                              <td className="px-10 py-5">
                                <div className="flex flex-wrap gap-2">
                                  {dp.length > 0 ? dp.map((p, ix) => (
                                    <span key={ix} className="bg-white text-slate-700 text-[11px] font-black px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm">{p.time}</span>
                                  )) : <span className="text-slate-300 text-[10px] font-bold uppercase tracking-widest">—</span>}
                                  <button onClick={() => {
                                    const t = prompt("Hora (HH:MM):", "08:00");
                                    if(t) setStore(prev => ({...prev, punches: [...prev.punches, { id: activePerson.ids[0], dayISO: iso, time: t, nsr: 'MAN-'+Date.now() }]}));
                                  }} className="p-1.5 text-slate-200 hover:text-[#E30613] hover:bg-red-50 rounded-lg transition-all"><Plus className="w-4 h-4" /></button>
                                </div>
                              </td>
                              <td className="px-4 py-5 text-center font-black text-xs text-slate-600">
                                {mins > 0 ? formatMins(mins) : '--:--'}
                              </td>
                              <td className="px-4 py-5 text-center">
                                {dp.length % 2 !== 0 && <span title="Batida Ímpar"><AlertOctagon className="w-5 h-5 text-red-500 mx-auto animate-pulse" /></span>}
                                {dp.length > 0 && dp.length % 2 === 0 && <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">Ok</span>}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner">
              <Fingerprint className="w-24 h-24 opacity-10 mb-6 animate-pulse" />
              <p className="font-black uppercase text-sm tracking-[0.2em] text-slate-400">Aguardando Seleção de Colaborador</p>
              {store.lastImport && (
                <div className="mt-8 px-6 py-3 bg-emerald-50 rounded-2xl border border-emerald-100 flex items-center gap-3">
                  <History className="w-4 h-4 text-emerald-500" />
                  <span className="text-[10px] font-black uppercase text-emerald-700 tracking-widest">Último AFD: {store.lastImport.stats.punches} batidas / {store.lastImport.stats.users} nomes</span>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  FileUp, Search, ShieldCheck, Plus, 
  IdCard, AlertOctagon, Printer, Edit3, Fingerprint, History
} from 'lucide-react';

// --- MODELO DE DADOS ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; // Aliases canonicalizados de 12 dígitos
  active: boolean; 
  cargo?: string; 
  admissao?: string; 
  pis_oficial?: string;
  matricula?: string;
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    stats: { lines: number; punches: number; users: number } 
  };
};

// --- MOTOR DE PARSING ESPECIFICADO ---

// Canonicalização para 12 dígitos mantendo zeros à esquerda (Essencial para iDClass)
const canon12 = (d: string) => d.replace(/\D/g, '').padStart(12, '0').slice(-12);

// Tipo 5: NSR(10)+‘5’+DATA(8)+HORA(4)+[IAE]+ID_NUMÉRICO+NOME...
// Captura até a transição para a primeira letra do nome
const RX_USER_IDCLASS = /^(\d{10})5(\d{8})(\d{4})([IAE])(\d+)([A-ZÀ-Ü].*)$/;

// Tipo 3: NSR(10)+‘3’+DATA(8)+HORA(4)+[IAE]?+ID(11/12)
const RX_PUNCH_IDCLASS = /^(\d{10})3(\d{8})(\d{4})([IAE]?)(\d{11,12})/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_rh_ponto_v6_blindado');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonName, setActivePersonName] = useState<string | null>(null);
  const [isEditingInfo, setIsEditingInfo] = useState(false);

  useEffect(() => {
    localStorage.setItem('abc_rh_ponto_v6_blindado', JSON.stringify(store));
  }, [store]);

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1"); 

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/);

      const newPunches: Punch[] = [];
      const userMap = new Map<string, string>(); 
      let totalLines = 0;

      lines.forEach(line => {
        const raw = line.trim();
        if (!raw) return;
        totalLines++;

        // Processamento Tipo 5 (Usuários) - Regex baseada em transição Num->Alpha
        const userMatch = raw.match(RX_USER_IDCLASS);
        if (userMatch) {
          const id = canon12(userMatch[5]);
          const name = userMatch[6].trim().toUpperCase();
          if (name.length > 3) userMap.set(id, name);
          return;
        }

        // Processamento Tipo 3 (Batidas) - Com prefixo opcional [EIA]
        const punchMatch = raw.match(RX_PUNCH_IDCLASS);
        if (punchMatch) {
          const [, , ddmmyyyy, hhmm, , idRaw] = punchMatch;
          newPunches.push({
            nsr: punchMatch[1],
            dayISO: `${ddmmyyyy.slice(4, 8)}-${ddmmyyyy.slice(2, 4)}-${ddmmyyyy.slice(0, 2)}`,
            time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
            id: canon12(idRaw)
          });
        }
      });

      setStore(prev => {
        const people = [...prev.people];

        // 1. Unificação Nominal com Múltiplos IDs (Aliases)
        userMap.forEach((name, id) => {
          let person = people.find(p => p.name === name);
          if (!person) {
            // Remove esse ID de qualquer "Colaborador Genérico" anterior
            people.forEach(p => p.ids = p.ids.filter(x => x !== id));
            people.push({ name, ids: [id], active: true });
          } else {
            if (!person.ids.includes(id)) {
              people.forEach(p => p.ids = p.ids.filter(x => x !== id));
              person.ids.push(id);
            }
          }
        });

        // 2. Garantia de Batidas Órfãs (Sem Nome no AFD)
        newPunches.forEach(p => {
          const owner = people.find(pers => pers.ids.includes(p.id));
          if (!owner) {
            people.push({ name: `COLABORADOR ${p.id}`, ids: [p.id], active: true });
          }
        });

        // 3. Mesclagem Inteligente por NSR
        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const filteredNew = newPunches.filter(p => !existingNsrs.has(p.nsr));

        return {
          people: people.filter(p => p.ids.length > 0),
          punches: [...prev.punches, ...filteredNew],
          lastImport: {
            file: file.name,
            stats: { lines: totalLines, punches: newPunches.length, users: userMap.size }
          }
        };
      });
    };
    event.target.value = '';
  };

  // --- LÓGICA DE FILTRAGEM POR COMPETÊNCIA ---
  const filteredPeople = useMemo(() => {
    // 1. Identifica quais IDs tiveram batidas no mês selecionado
    const idsWithPunchesThisMonth = new Set(
      store.punches
        .filter(p => p.dayISO.startsWith(selectedMonth))
        .map(p => p.id)
    );

    // 2. Filtra a lista para mostrar apenas quem bateu ponto nesse período
    return store.people
      .filter(p => {
        const hasPunchesInPeriod = p.ids.some(id => idsWithPunchesThisMonth.has(id));
        const matchesSearch = p.name.includes(searchTerm.toUpperCase()) || p.ids.some(id => id.includes(searchTerm));
        return hasPunchesInPeriod && matchesSearch;
      })
      .sort((a, b) => {
        const aGen = a.name.startsWith('COLABORADOR');
        const bGen = b.name.startsWith('COLABORADOR');
        if (aGen && !bGen) return 1;
        if (!aGen && bGen) return -1;
        return a.name.localeCompare(b.name);
      });
  }, [store.people, store.punches, searchTerm, selectedMonth]);

  const activePerson = store.people.find(p => p.name === activePersonName);

  const getPunches = (p: Person, month: string) => 
    store.punches.filter(pun => p.ids.includes(pun.id) && pun.dayISO.startsWith(month))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));

  const calculateDayMins = (punches: Punch[]) => {
    if (punches.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < punches.length - 1; i += 2) {
      const [h1, m1] = punches[i].time.split(':').map(Number);
      const [h2, m2] = punches[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  const formatMins = (mins: number) => {
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl flex justify-between items-center">
        <div className="flex items-center gap-5">
          <div className="bg-[#E30613] p-4 rounded-2xl shadow-lg shadow-red-100">
            <ShieldCheck className="text-white w-6 h-6" />
          </div>
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter text-[#0A1121]">Gestão de Horas</h2>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Unificação por Identidade Nominal (Aliases)</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <input 
            type="month" 
            value={selectedMonth} 
            onChange={e => {
              setSelectedMonth(e.target.value);
              setActivePersonName(null); // Reseta seleção ao mudar mês para evitar confusão
            }} 
            className="bg-slate-50 border rounded-xl px-4 py-2 text-xs font-bold outline-none border-slate-200 focus:ring-2 focus:ring-[#E30613]" 
          />
          <label className="bg-[#0A1121] text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase cursor-pointer flex items-center gap-2 hover:bg-black transition-all shadow-xl">
            <FileUp className="w-4 h-4 text-[#E30613]" /> LER AFD <input type="file" className="hidden" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* LISTA LATERAL - DINÂMICA POR MÊS */}
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm min-h-[70vh]">
          <div className="mb-4 px-2">
             <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">Colaboradores Ativos no Período:</p>
             <div className="h-1 w-12 bg-[#E30613] rounded-full opacity-30"></div>
          </div>
          <div className="relative mb-6">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input type="text" placeholder="Filtrar por nome..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-slate-50 border rounded-xl text-xs font-bold outline-none" />
          </div>
          <div className="space-y-2 max-h-[60vh] overflow-y-auto pr-2 custom-scrollbar">
            {filteredPeople.length === 0 ? (
              <div className="text-center py-10 opacity-30">
                <Fingerprint className="w-8 h-8 mx-auto mb-2" />
                <p className="text-[9px] font-black uppercase">Nenhum registro em {selectedMonth}</p>
              </div>
            ) : (
              filteredPeople.map(p => (
                <button 
                  key={p.name} 
                  onClick={() => { setActivePersonName(p.name); setIsEditingInfo(false); }} 
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonName === p.name ? 'bg-[#E30613] text-white border-[#E30613] shadow-lg shadow-red-100' : 'bg-slate-50 border-transparent hover:bg-slate-100 text-slate-600'}`}
                >
                  <p className="text-[10px] font-black uppercase truncate leading-tight">{p.name}</p>
                  <p className={`text-[8px] mt-1 ${activePersonName === p.name ? 'text-white/60' : 'text-slate-400'}`}>ID Canon: {p.ids[0]}</p>
                </button>
              ))
            )}
          </div>
        </div>

        {/* ÁREA DE REGISTROS */}
        <div className="lg:col-span-3">
          {activePerson ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
               <div className="bg-white border rounded-[2.5rem] p-8 shadow-xl flex justify-between items-center">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center border border-slate-100 shadow-sm"><IdCard className="text-[#E30613] w-8 h-8" /></div>
                     <div>
                        <h3 className="text-xl font-black uppercase text-slate-900 leading-none">{activePerson.name}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-2 tracking-widest">Aliases Detectados: {activePerson.ids.join(' • ')}</p>
                     </div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => setIsEditingInfo(!isEditingInfo)} className={`p-4 rounded-xl transition-all ${isEditingInfo ? 'bg-slate-900 text-white' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}><Edit3 className="w-5 h-5" /></button>
                    <button onClick={() => window.print()} className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 hover:bg-black transition-all shadow-xl"><Printer className="w-4 h-4 text-emerald-500" /> Imprimir Espelho</button>
                  </div>
               </div>

               {isEditingInfo && (
                  <div className="bg-slate-900 rounded-[2.5rem] p-10 text-white grid grid-cols-1 md:grid-cols-3 gap-6 animate-in zoom-in-95 duration-300">
                    <div className="space-y-1">
                      <label className="text-[9px] font-black text-slate-500 uppercase px-1">Cargo / Função</label>
                      <input type="text" value={activePerson.cargo || ''} onChange={e => setStore(prev => ({...prev, people: prev.people.map(p => p.name === activePerson.name ? {...p, cargo: e.target.value} : p)}))} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-xs outline-none focus:border-[#E30613]" />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-black text-slate-500 uppercase px-1">Matrícula Interna</label>
                      <input type="text" value={activePerson.matricula || ''} onChange={e => setStore(prev => ({...prev, people: prev.people.map(p => p.name === activePerson.name ? {...p, matricula: e.target.value} : p)}))} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-xs outline-none focus:border-[#E30613]" />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-black text-slate-500 uppercase px-1">PIS Oficial (Padrão)</label>
                      <input type="text" value={activePerson.pis_oficial || activePerson.ids[0]} onChange={e => setStore(prev => ({...prev, people: prev.people.map(p => p.name === activePerson.name ? {...p, pis_oficial: e.target.value} : p)}))} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-xs outline-none focus:border-[#E30613]" />
                    </div>
                  </div>
               )}

               <div className="bg-white border rounded-[3rem] shadow-2xl overflow-hidden border-slate-200">
                  <table className="w-full text-left">
                    <thead className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-10 py-6">Data / Semana</th>
                        <th className="px-10 py-6">Marcações Registradas (AFD)</th>
                        <th className="px-4 py-6 text-center">Total Dia</th>
                        <th className="px-4 py-6 text-center">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {(() => {
                        const [y, m] = selectedMonth.split('-');
                        const days = new Date(Number(y), Number(m), 0).getDate();
                        const punches = getPunches(activePerson, selectedMonth);
                        return Array.from({length: days}, (_, i) => {
                          const day = (i+1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dp = punches.filter(p => p.dayISO === iso);
                          const mins = calculateDayMins(dp);
                          const dt = new Date(iso + 'T12:00:00');
                          const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                          return (
                            <tr key={iso} className={`group hover:bg-slate-50 transition-all ${dp.length === 0 ? 'opacity-30' : ''} ${isWeekend ? 'bg-slate-50/30' : ''}`}>
                              <td className="px-10 py-5">
                                <span className="text-sm font-black text-slate-900">{day}/{m}</span>
                                <span className="text-[9px] font-bold text-slate-400 uppercase block leading-none">{dt.toLocaleDateString('pt-BR', {weekday: 'short'})}</span>
                              </td>
                              <td className="px-10 py-5">
                                <div className="flex flex-wrap gap-2">
                                  {dp.length > 0 ? dp.map((p, ix) => (
                                    <span key={ix} className="bg-white text-slate-700 text-[11px] font-black px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm" title={`NSR: ${p.nsr}`}>{p.time}</span>
                                  )) : <span className="text-slate-300 text-[10px] font-bold uppercase tracking-widest">—</span>}
                                  <button onClick={() => {
                                    const t = prompt("Adicionar batida manual (HH:MM):", "08:00");
                                    if(t && t.includes(':')) {
                                      setStore(prev => ({
                                        ...prev, 
                                        punches: [...prev.punches, { id: activePerson.ids[0], dayISO: iso, time: t, nsr: 'MAN-'+Date.now() }]
                                      }));
                                    }
                                  }} className="p-1.5 text-slate-200 hover:text-[#E30613] hover:bg-red-50 rounded-lg transition-all"><Plus className="w-4 h-4" /></button>
                                </div>
                              </td>
                              <td className="px-4 py-5 text-center font-black text-xs text-slate-600">
                                {mins > 0 ? formatMins(mins) : '--:--'}
                              </td>
                              <td className="px-4 py-5 text-center">
                                {dp.length % 2 !== 0 && <span title="Batida Ímpar (Incompleta)"><AlertOctagon className="w-5 h-5 text-red-500 mx-auto animate-pulse" /></span>}
                                {dp.length > 0 && dp.length % 2 === 0 && <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">Completo</span>}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner">
              <Fingerprint className="w-24 h-24 opacity-10 mb-6 animate-pulse" />
              <p className="font-black uppercase text-sm tracking-[0.2em] text-slate-400 text-center">
                 Selecione um Colaborador na lista lateral<br/>
                 <span className="text-[10px] opacity-60">A lista exibe apenas quem possui batidas em {selectedMonth}</span>
              </p>
              {store.lastImport && (
                <div className="mt-8 px-6 py-3 bg-emerald-50 rounded-2xl border border-emerald-100 flex items-center gap-3">
                  <History className="w-4 h-4 text-emerald-500" />
                  <span className="text-[10px] font-black uppercase text-emerald-700 tracking-widest">Processado: {store.lastImport.stats.punches} batidas unificadas</span>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

