                        <th className="px-10 py-6">Data / Dia</th>
                        <th className="px-10 py-6">Marcações Registradas</th>
                        <th className="px-4 py-6 text-center">Total Dia</th>
                        <th className="px-4 py-6 text-center">Auditoria</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {(() => {
                        const [y, m] = selectedMonth.split('-');
                        const days = new Date(Number(y), Number(m), 0).getDate();
                        return Array.from({length: days}, (_, i) => {
                          const day = (i+1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dp = punchesAtivos.filter(p => p.dayISO === iso);
                          const mins = calculateDayMins(dp);
                          const dt = new Date(iso + 'T12:00:00');
                          const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                          return (
                            <tr key={iso} className={`group hover:bg-slate-50 transition-all ${dp.length === 0 ? 'opacity-30' : ''} ${isWeekend ? 'bg-slate-50/30' : ''}`}>
                              <td className="px-10 py-5">
                                <span className="text-sm font-black text-slate-900">{day}/{m}</span>
                                <span className="text-[9px] font-bold text-slate-400 uppercase block leading-none">{dt.toLocaleDateString('pt-BR', {weekday: 'short'})}</span>
                              </td>
                              <td className="px-10 py-5">
                                <div className="flex flex-wrap gap-2">
                                  {dp.map((p, ix) => (
                                    <span key={ix} className="bg-white text-slate-700 text-[11px] font-black px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm" title={`NSR: ${p.nsr}`}>{p.time}</span>
                                  ))}
                                  <button onClick={() => {
                                    const t = prompt("Hora manual (HH:MM):", "08:00");
                                    if(t) setStore(prev => ({...prev, punches: [...prev.punches, { id: activePerson.ids[0], dayISO: iso, time: t, nsr: 'MAN-'+Date.now() }]}));
                                  }} className="p-1.5 text-slate-200 hover:text-[#E30613] hover:bg-red-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"><Plus className="w-4 h-4" /></button>
                                </div>
                              </td>
                              <td className="px-4 py-5 text-center font-black text-xs text-slate-600">
                                {mins > 0 ? formatMins(mins) : '--:--'}
                              </td>
                              <td className="px-4 py-5 text-center">
                                {dp.length % 2 !== 0 && <span title="Batida Ímpar (Incompleta)"><AlertOctagon className="w-5 h-5 text-red-500 mx-auto animate-pulse" /></span>}
                                {dp.length > 0 && dp.length % 2 === 0 && <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">OK</span>}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner text-center px-10">
              <Fingerprint className="w-24 h-24 opacity-10 mb-6 animate-pulse" />
              <p className="font-black uppercase text-sm tracking-[0.2em] text-slate-400">Selecione um colaborador ativo na lista lateral</p>
              <p className="text-[10px] mt-2 font-bold text-slate-300 uppercase">A lista filtra apenas quem tem batidas em {selectedMonth}</p>
              {store.lastImport && (
                <div className="mt-8 px-6 py-3 bg-emerald-50 rounded-2xl border border-emerald-100 flex items-center gap-3">
                  <History className="w-4 h-4 text-emerald-500" />
                  <span className="text-[10px] font-black uppercase text-emerald-700 tracking-widest">Processado: {store.lastImport.stats.punches} registros unificados</span>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  FileUp, Search, ShieldCheck, Plus, 
  IdCard, AlertOctagon, Printer, Edit3, Fingerprint, History
} from 'lucide-react';

// --- MODELO DE DADOS ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; // Aliases canonicalizados (sempre 12 dígitos)
  active: boolean; 
  cargo?: string; 
  matricula?: string;
  pis_oficial?: string;
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    stats: { punches: number; users: number } 
  };
};

// --- MOTOR DE PARSING DEFINITIVO ---

// Canonicalização: Garante 12 dígitos com zeros à esquerda
const canon12 = (d: string) => d.replace(/\D/g, '').padStart(12, '0').slice(-12);

/** 
 * TIPO 5 (Cadastro): NSR(10) + '5' + Data(8) + Hora(4) + [IAE]? (opcional) + ID + Nome 
 * O segredo está no (\d+?) seguido do lookahead (?=[A-ZÀ-Ü]) para não invadir o nome.
 */
const RX_USER_IDCLASS = /^(\d{10})5\d{8}\d{4}[IAE]?(\d+?)(?=[A-ZÀ-Ü\s])([A-ZÀ-Ü\s]+)/;

/** 
 * TIPO 3 (Batida): NSR(10) + '3' + Data(8) + Hora(4) + [IAE]? (opcional) + ID 
 */
const RX_PUNCH_IDCLASS = /^(\d{10})3(\d{8})(\d{4})[IAE]?(\d{10,12})/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_ponto_v9_blindado');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonName, setActivePersonName] = useState<string | null>(null);
  const [isEditingInfo, setIsEditingInfo] = useState(false);

  useEffect(() => {
    localStorage.setItem('abc_ponto_v9_blindado', JSON.stringify(store));
  }, [store]);

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1"); 

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/).filter(l => l.trim().length > 30); // Filtra linhas curtas ou vazias

      const newPunches: Punch[] = [];
      const userMap = new Map<string, string>(); 

      lines.forEach(line => {
        const raw = line.trim();

        // Tenta Tipo 5 primeiro (Cadastro de Usuário)
        const userMatch = raw.match(RX_USER_IDCLASS);
        if (userMatch) {
          const id = canon12(userMatch[2]);
          const name = userMatch[3].trim().toUpperCase();
          if (name.length > 2) userMap.set(id, name);
          return;
        }

        // Tenta Tipo 3 (Batida de Ponto)
        const punchMatch = raw.match(RX_PUNCH_IDCLASS);
        if (punchMatch) {
          const [, nsr, ddmmyyyy, hhmm, idRaw] = punchMatch;
          newPunches.push({
            nsr,
            dayISO: `${ddmmyyyy.slice(4, 8)}-${ddmmyyyy.slice(2, 4)}-${ddmmyyyy.slice(0, 2)}`,
            time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
            id: canon12(idRaw)
          });
        }
      });

      setStore(prev => {
        const people = [...prev.people];

        // Vincula nomes aos IDs canonicalizados
        userMap.forEach((name, id) => {
          let person = people.find(p => p.name === name);
          if (!person) {
            people.forEach(p => p.ids = p.ids.filter(x => x !== id));
            people.push({ name, ids: [id], active: true });
          } else if (!person.ids.includes(id)) {
            people.forEach(p => p.ids = p.ids.filter(x => x !== id));
            person.ids.push(id);
          }
        });

        // Adiciona batidas órfãs (IDs sem Tipo 5 no arquivo)
        newPunches.forEach(p => {
          if (!people.find(pers => pers.ids.includes(p.id))) {
            people.push({ name: `COLABORADOR ${p.id}`, ids: [p.id], active: true });
          }
        });

        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const filteredNew = newPunches.filter(p => !existingNsrs.has(p.nsr));

        return {
          people,
          punches: [...prev.punches, ...filteredNew],
          lastImport: { 
            file: file.name, 
            stats: { punches: newPunches.length, users: userMap.size } 
          }
        };
      });
    };
    event.target.value = '';
  };

  // FILTRO: Apenas quem trabalhou no mês selecionado
  const filteredPeople = useMemo(() => {
    const activeIdsThisMonth = new Set(
      store.punches
        .filter(p => p.dayISO.startsWith(selectedMonth))
        .map(p => p.id)
    );

    return store.people
      .filter(p => {
        const hasPunches = p.ids.some(id => activeIdsThisMonth.has(id));
        const matchesSearch = p.name.includes(searchTerm.toUpperCase()) || p.ids.some(id => id.includes(searchTerm));
        return hasPunches && matchesSearch;
      })
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [store.people, store.punches, searchTerm, selectedMonth]);

  const activePerson = store.people.find(p => p.name === activePersonName);
  const punchesAtivos = useMemo(() => {
    if (!activePerson) return [];
    return store.punches
      .filter(pun => activePerson.ids.includes(pun.id) && pun.dayISO.startsWith(selectedMonth))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));
  }, [activePerson, store.punches, selectedMonth]);

  const calculateDayMins = (p: Punch[]) => {
    if (p.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < p.length - 1; i += 2) {
      const [h1, m1] = p[i].time.split(':').map(Number);
      const [h2, m2] = p[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl flex justify-between items-center">
        <div className="flex items-center gap-5">
          <div className="bg-[#E30613] p-4 rounded-2xl">
            <ShieldCheck className="text-white w-6 h-6" />
          </div>
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter text-[#0A1121]">Folha de Ponto</h2>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Processamento iDClass • Canonicalização 12D</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <input 
            type="month" 
            value={selectedMonth} 
            onChange={e => { setSelectedMonth(e.target.value); setActivePersonName(null); }} 
            className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold outline-none" 
          />
          <label className="bg-[#0A1121] text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase cursor-pointer flex items-center gap-2 hover:bg-black transition-all shadow-xl">
            <FileUp className="w-4 h-4 text-[#E30613]" /> LER AFD <input type="file" className="hidden" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm min-h-[60vh]">
          <div className="relative mb-6">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input type="text" placeholder="Filtrar por nome..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-slate-50 border rounded-xl text-xs font-bold outline-none" />
          </div>
          <div className="space-y-2 max-h-[55vh] overflow-y-auto pr-2 custom-scrollbar text-center">
            {filteredPeople.length === 0 ? (
              <div className="py-20 opacity-30">
                <Fingerprint className="w-8 h-8 mx-auto mb-2" />
                <p className="text-[9px] font-black uppercase">Ninguém em {selectedMonth}</p>
              </div>
            ) : (
              filteredPeople.map(p => (
                <button 
                  key={p.name} 
                  onClick={() => { setActivePersonName(p.name); setIsEditingInfo(false); }} 
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonName === p.name ? 'bg-[#E30613] text-white border-[#E30613] shadow-lg shadow-red-100' : 'bg-slate-50 border-transparent hover:bg-slate-100 text-slate-600'}`}
                >
                  <p className="text-[10px] font-black uppercase truncate">{p.name}</p>
                  <p className={`text-[8px] mt-1 ${activePersonName === p.name ? 'text-white/60' : 'text-slate-400'}`}>ID: {p.ids[0]}</p>
                </button>
              ))
            )}
          </div>
        </div>

        <div className="lg:col-span-3">
          {activePerson ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
               <div className="bg-white border rounded-[2.5rem] p-8 shadow-xl flex justify-between items-center">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center border border-slate-100 shadow-sm"><IdCard className="text-[#E30613] w-8 h-8" /></div>
                     <div>
                        <h3 className="text-xl font-black uppercase text-slate-900 leading-none">{activePerson.name}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-2 tracking-widest">Aliases: {activePerson.ids.join(' • ')}</p>
                     </div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => setIsEditingInfo(!isEditingInfo)} className={`p-4 rounded-xl transition-all ${isEditingInfo ? 'bg-slate-900 text-white' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}><Edit3 className="w-5 h-5" /></button>
                    <button onClick={() => window.print()} className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 hover:bg-black transition-all shadow-xl"><Printer className="w-4 h-4 text-emerald-500" /> Imprimir</button>
                  </div>
               </div>

               <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                  <table className="w-full text-left">
                    <thead className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-10 py-6">Data</th>
                        <th className="px-10 py-6">Marcações (AFD)</th>
                        <th className="px-4 py-6 text-center">Total</th>
                        <th className="px-4 py-6 text-center">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {(() => {
                        const [y, m] = selectedMonth.split('-');
                        const days = new Date(Number(y), Number(m), 0).getDate();
                        return Array.from({length: days}, (_, i) => {
                          const day = (i+1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dp = punchesAtivos.filter(p => p.dayISO === iso);
                          const mins = calculateDayMins(dp);
                          const dt = new Date(iso + 'T12:00:00');

                          return (
                            <tr key={iso} className={`group hover:bg-slate-50 transition-all ${dp.length === 0 ? 'opacity-30' : ''}`}>
                              <td className="px-10 py-5">
                                <span className="text-sm font-black text-slate-900">{day}/{m}</span>
                                <span className="text-[9px] font-bold text-slate-400 uppercase block leading-none">{dt.toLocaleDateString('pt-BR', {weekday: 'short'})}</span>
                              </td>
                              <td className="px-10 py-5">
                                <div className="flex flex-wrap gap-2">
                                  {dp.map((p, ix) => (
                                    <span key={ix} className="bg-white text-slate-700 text-[11px] font-black px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm">{p.time}</span>
                                  ))}
                                </div>
                              </td>
                              <td className="px-4 py-5 text-center font-black text-xs text-slate-600">
                                {mins > 0 ? `${Math.floor(mins/60)}h${(mins%60).toString().padStart(2,'0')}` : '--:--'}
                              </td>
                              <td className="px-4 py-5 text-center">
                                {dp.length % 2 !== 0 && <span title="Ímpar"><AlertOctagon className="w-5 h-5 text-red-500 mx-auto" /></span>}
                                {dp.length > 0 && dp.length % 2 === 0 && <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">OK</span>}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner text-center px-10">
              <Fingerprint className="w-24 h-24 opacity-10 mb-6 animate-pulse" />
              <p className="font-black uppercase text-sm tracking-[0.2em] text-slate-400">Selecione um colaborador na lista lateral</p>
              <p className="text-[10px] mt-2 font-bold text-slate-300 uppercase">Apenas quem teve batidas em {selectedMonth} aparecerá aqui.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  FileUp, Search, ShieldCheck, Plus, 
  IdCard, AlertOctagon, Printer, Edit3, Fingerprint, History
} from 'lucide-react';

// --- MODELO DE DADOS ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; // Aliases canonicalizados (sempre 12 dígitos)
  active: boolean; 
  cargo?: string; 
  matricula?: string;
  pis_oficial?: string;
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    stats: { punches: number; users: number } 
  };
};

// --- MOTOR DE PARSING DEFINITIVO ---

// Canonicalização: Garante 12 dígitos com zeros à esquerda
const canon12 = (d: string) => d.replace(/\D/g, '').padStart(12, '0').slice(-12);

/** 
 * TIPO 5 (Cadastro): NSR(10) + '5' + Data(8) + Hora(4) + [IAE]? (opcional) + ID + Nome 
 * A Regex para no primeiro caractere alfabético A-Z ou acentuado.
 */
const RX_USER_IDCLASS = /^(\d{10})5\d{8}\d{4}[IAE]?(\d+?)(?=[A-ZÀ-Ü])([A-ZÀ-Ü\s\-\']+)/;

/** 
 * TIPO 3 (Batida): NSR(10) + '3' + Data(8) + Hora(4) + [IAE]? (opcional) + ID 
 */
const RX_PUNCH_IDCLASS = /^(\d{10})3(\d{8})(\d{4})[IAE]?(\d+)/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_ponto_v10_final');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonName, setActivePersonName] = useState<string | null>(null);
  const [isEditingInfo, setIsEditingInfo] = useState(false);

  useEffect(() => {
    localStorage.setItem('abc_ponto_v10_final', JSON.stringify(store));
  }, [store]);

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    // ISO-8859-1 é fundamental para AFDs brasileiros
    reader.readAsText(file, "ISO-8859-1"); 

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/).filter(l => l.trim().length > 0);

      const newPunches: Punch[] = [];
      const userMap = new Map<string, string>(); 

      lines.forEach(line => {
        const raw = line.trim();

        // Tenta Tipo 5 primeiro (Cadastro)
        const userMatch = raw.match(RX_USER_IDCLASS);
        if (userMatch) {
          const id = canon12(userMatch[2]);
          const name = userMatch[3].trim().toUpperCase();
          if (name.length > 1) userMap.set(id, name);
          return;
        }

        // Tenta Tipo 3 (Batida)
        const punchMatch = raw.match(RX_PUNCH_IDCLASS);
        if (punchMatch) {
          const [, nsr, ddmmyyyy, hhmm, idRaw] = punchMatch;
          // Captura apenas os últimos 12 dígitos do campo de ID da batida
          newPunches.push({
            nsr,
            dayISO: `${ddmmyyyy.slice(4, 8)}-${ddmmyyyy.slice(2, 4)}-${ddmmyyyy.slice(0, 2)}`,
            time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
            id: canon12(idRaw)
          });
        }
      });

      if (userMap.size === 0 && newPunches.length > 0) {
        console.warn("AFD detectou batidas mas nenhum cadastro de usuário. Verifique o formato do Tipo 5.");
      }

      setStore(prev => {
        const people = [...prev.people];

        // Atualiza ou Cria Pessoas baseada no Mapa de Nomes
        userMap.forEach((name, id) => {
          let person = people.find(p => p.name === name);
          if (!person) {
            // Se o ID já pertencia a um "COLABORADOR X", removemos o vínculo antigo
            people.forEach(p => p.ids = p.ids.filter(v => v !== id));
            people.push({ name, ids: [id], active: true });
          } else if (!person.ids.includes(id)) {
            people.forEach(p => p.ids = p.ids.filter(v => v !== id));
            person.ids.push(id);
          }
        });

        // Garante que IDs que bateram ponto mas não tem Tipo 5 apareçam
        newPunches.forEach(p => {
          if (!people.find(pers => pers.ids.includes(p.id))) {
            people.push({ name: `COLABORADOR ${p.id}`, ids: [p.id], active: true });
          }
        });

        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const filteredNew = newPunches.filter(p => !existingNsrs.has(p.nsr));

        return {
          people: people.filter(p => p.ids.length > 0),
          punches: [...prev.punches, ...filteredNew],
          lastImport: { 
            file: file.name, 
            stats: { punches: newPunches.length, users: userMap.size } 
          }
        };
      });
    };
    event.target.value = '';
  };

  const filteredPeople = useMemo(() => {
    const activeIdsThisMonth = new Set(
      store.punches
        .filter(p => p.dayISO.startsWith(selectedMonth))
        .map(p => p.id)
    );

    return store.people
      .filter(p => {
        const hasPunches = p.ids.some(id => activeIdsThisMonth.has(id));
        const matchesSearch = p.name.includes(searchTerm.toUpperCase()) || p.ids.some(id => id.includes(searchTerm));
        return hasPunches && matchesSearch;
      })
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [store.people, store.punches, searchTerm, selectedMonth]);

  const activePerson = store.people.find(p => p.name === activePersonName);
  const punchesAtivos = useMemo(() => {
    if (!activePerson) return [];
    return store.punches
      .filter(pun => activePerson.ids.includes(pun.id) && pun.dayISO.startsWith(selectedMonth))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));
  }, [activePerson, store.punches, selectedMonth]);

  const calculateDayMins = (p: Punch[]) => {
    if (p.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < p.length - 1; i += 2) {
      const [h1, m1] = p[i].time.split(':').map(Number);
      const [h2, m2] = p[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

