                <p className="text-[9px] font-black uppercase text-slate-400">Nenhum registro ativo</p>
              </div>
            ) : (
              filteredPeople.map(p => (
                <button 
                  key={p.name} 
                  onClick={() => { setActivePersonName(p.name); setIsEditingInfo(false); }} 
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonName === p.name ? 'bg-[#E30613] text-white border-[#E30613] shadow-lg shadow-red-100' : 'bg-slate-50 border-transparent hover:bg-slate-100 text-slate-600'}`}
                >
                  <p className="text-[10px] font-black uppercase truncate leading-tight">{p.name}</p>
                  <p className={`text-[8px] mt-1 ${activePersonName === p.name ? 'text-white/60' : 'text-slate-400'}`}>ID: {p.ids[0]}</p>
                </button>
              ))
            )}
          </div>
        </div>

        <div className="lg:col-span-3">
          {activePerson ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
               <div className="bg-white border rounded-[2.5rem] p-8 shadow-xl flex justify-between items-center">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center border border-slate-100 shadow-sm"><IdCard className="text-[#E30613] w-8 h-8" /></div>
                     <div>
                        <h3 className="text-xl font-black uppercase text-slate-900 leading-none">{activePerson.name}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-2 tracking-widest">IDs Associados: {activePerson.ids.join(' • ')}</p>
                     </div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => window.print()} className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 hover:bg-black transition-all shadow-xl"><Printer className="w-4 h-4 text-emerald-500" /> Imprimir</button>
                  </div>
               </div>

               <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                  <table className="w-full text-left">
                    <thead className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-10 py-6">Data</th>
                        <th className="px-10 py-6">Marcações (AFD)</th>
                        <th className="px-4 py-6 text-center">Horas</th>
                        <th className="px-4 py-6 text-center">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {(() => {
                        const [y, m] = selectedMonth.split('-');
                        const days = new Date(Number(y), Number(m), 0).getDate();
                        return Array.from({length: days}, (_, i) => {
                          const day = (i+1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dp = punchesAtivos.filter(p => p.dayISO === iso);
                          const mins = calculateDayMins(dp);
                          const dt = new Date(iso + 'T12:00:00');
                          const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                          return (
                            <tr key={iso} className={`group hover:bg-slate-50 transition-all ${dp.length === 0 ? 'opacity-30' : ''} ${isWeekend ? 'bg-slate-50/20' : ''}`}>
                              <td className="px-10 py-5">
                                <span className="text-sm font-black text-slate-900">{day}/{m}</span>
                                <span className="text-[9px] font-bold text-slate-400 uppercase block leading-none">{dt.toLocaleDateString('pt-BR', {weekday: 'short'})}</span>
                              </td>
                              <td className="px-10 py-5">
                                <div className="flex flex-wrap gap-2">
                                  {dp.map((p, ix) => (
                                    <span key={ix} className="bg-white text-slate-700 text-[11px] font-black px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm">{p.time}</span>
                                  ))}
                                </div>
                              </td>
                              <td className="px-4 py-5 text-center font-black text-xs text-slate-600">
                                {mins > 0 ? `${Math.floor(mins/60)}h${(mins%60).toString().padStart(2,'0')}` : '--:--'}
                              </td>
                              <td className="px-4 py-5 text-center">
                                {dp.length % 2 !== 0 && <span title="Marcação Incompleta"><AlertOctagon className="w-5 h-5 text-red-500 mx-auto animate-pulse" /></span>}
                                {dp.length > 0 && dp.length % 2 === 0 && <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">OK</span>}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner text-center px-10">
              <Fingerprint className="w-24 h-24 opacity-10 mb-6 animate-pulse" />
              <p className="font-black uppercase text-sm tracking-[0.2em] text-slate-400">Selecione um colaborador na lista lateral</p>
              <p className="text-[10px] mt-2 font-bold text-slate-300 uppercase">Se a lista estiver vazia, mude o mês no topo ou importe um arquivo AFD.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  FileUp, Search, ShieldCheck, Plus, 
  IdCard, AlertOctagon, Printer, Edit3, Fingerprint, History, Terminal
} from 'lucide-react';

// --- MODELO DE DADOS ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; // Aliases canonicalizados (sempre 12 dígitos)
  active: boolean; 
  cargo?: string; 
  matricula?: string;
  pis_oficial?: string;
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    stats: { punches: number; users: number } 
  };
};

// --- MOTOR DE PARSING ROBUSTO ---

/** 
 * Canonicalização 12D: Resolve a inconsistência de IDs com/sem zeros.
 */
const canon12 = (d: string) => d.replace(/\D/g, '').padStart(12, '0').slice(-12);

/** 
 * REGEX TIPO 5 (CADASTRO) - A PROVA DE FALHAS
 * 1. Pula NSR(10) + Tipo(1) + Data(8) + Hora(4) = 23 caracteres iniciais.
 * 2. Consome opcionalmente [IAE].
 * 3. Captura dígitos (\d+?) até a "parede" de letras (?=[A-ZÀ-Ü]).
 * 4. Captura o Nome incluindo acentos, espaços e hífens.
 */
const RX_USER_IDCLASS = /^.{23}[IAE]?(\d+?)(?=[A-ZÀ-Ü])([A-ZÀ-Ü\s\-\']+)/;

/** 
 * REGEX TIPO 3 (BATIDA)
 * Captura NSR, Data, Hora e o ID (limpando o marcador IAE se existir).
 */
const RX_PUNCH_IDCLASS = /^(\d{10})3(\d{8})(\d{4})[IAE]?(\d+)/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_ponto_v11_robust');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonName, setActivePersonName] = useState<string | null>(null);
  const [importError, setImportError] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('abc_ponto_v11_robust', JSON.stringify(store));
  }, [store]);

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    setImportError(null);

    // ISO-8859-1 previne corrupção de nomes acentuados que quebram a Regex
    reader.readAsText(file, "ISO-8859-1"); 

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 20);

      const newPunches: Punch[] = [];
      const userMap = new Map<string, string>(); 
      let samples: string[] = [];

      lines.forEach(raw => {
        // Diagnóstico: Pega as primeiras linhas do tipo 5 para log se falhar
        if (raw.substring(10, 11) === '5' && samples.length < 3) samples.push(raw);

        // 1. Tentar ler Cadastro (Tipo 5)
        const userMatch = raw.match(RX_USER_IDCLASS);
        if (userMatch) {
          const id = canon12(userMatch[1]);
          const name = userMatch[2].trim().toUpperCase();
          if (name.length > 1) userMap.set(id, name);
          return;
        }

        // 2. Tentar ler Batida (Tipo 3)
        const punchMatch = raw.match(RX_PUNCH_IDCLASS);
        if (punchMatch) {
          const [, nsr, ddmmyyyy, hhmm, idRaw] = punchMatch;
          newPunches.push({
            nsr,
            dayISO: `${ddmmyyyy.slice(4, 8)}-${ddmmyyyy.slice(2, 4)}-${ddmmyyyy.slice(0, 2)}`,
            time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
            id: canon12(idRaw)
          });
        }
      });

      // Se houver batidas mas nenhum usuário, a Regex do Tipo 5 falhou
      if (userMap.size === 0 && newPunches.length > 0) {
        const msg = `ERRO: Batidas lidas (${newPunches.length}), mas nenhum nome encontrado. Amostra Tipo 5: ${samples[0] || 'N/A'}`;
        setImportError(msg);
        console.error(msg, samples);
      }

      setStore(prev => {
        const people = [...prev.people];

        // Processa Cadastros e resolve Aliases
        userMap.forEach((name, id) => {
          let person = people.find(p => p.name === name);
          if (!person) {
            people.forEach(p => p.ids = p.ids.filter(v => v !== id));
            people.push({ name, ids: [id], active: true });
          } else if (!person.ids.includes(id)) {
            people.forEach(p => p.ids = p.ids.filter(v => v !== id));
            person.ids.push(id);
          }
        });

        // Adiciona IDs que bateram ponto mas não tinham Tipo 5 no arquivo
        newPunches.forEach(p => {
          if (!people.find(pers => pers.ids.includes(p.id))) {
            people.push({ name: `COLABORADOR ${p.id}`, ids: [p.id], active: true });
          }
        });

        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const filteredNew = newPunches.filter(p => !existingNsrs.has(p.nsr));

        return {
          people: people.filter(p => p.ids.length > 0),
          punches: [...prev.punches, ...filteredNew],
          lastImport: { 
            file: file.name, 
            stats: { punches: newPunches.length, users: userMap.size } 
          }
        };
      });
    };
    event.target.value = '';
  };

  const filteredPeople = useMemo(() => {
    const activeIdsThisMonth = new Set(
      store.punches
        .filter(p => p.dayISO.startsWith(selectedMonth))
        .map(p => p.id)
    );

    return store.people
      .filter(p => {
        const hasPunches = p.ids.some(id => activeIdsThisMonth.has(id));
        const matchesSearch = p.name.includes(searchTerm.toUpperCase()) || p.ids.some(id => id.includes(searchTerm));
        return hasPunches && matchesSearch;
      })
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [store.people, store.punches, searchTerm, selectedMonth]);

  const activePerson = store.people.find(p => p.name === activePersonName);
  const punchesAtivos = useMemo(() => {
    if (!activePerson) return [];
    return store.punches
      .filter(pun => activePerson.ids.includes(pun.id) && pun.dayISO.startsWith(selectedMonth))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));
  }, [activePerson, store.punches, selectedMonth]);

  const calculateDayMins = (p: Punch[]) => {
    if (p.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < p.length - 1; i += 2) {
      const [h1, m1] = p[i].time.split(':').map(Number);
      const [h2, m2] = p[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  return (
    <div className="space-y-6">
      {/* HEADER DE IMPORTAÇÃO */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-5">
          <div className="bg-[#E30613] p-4 rounded-2xl shadow-lg shadow-red-100">
            <ShieldCheck className="text-white w-6 h-6" />
          </div>
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter text-[#0A1121]">Folha de Ponto</h2>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
               {store.lastImport ? `Lido: ${store.lastImport.file}` : 'Aguardando Arquivo AFD'}
            </p>
          </div>
        </div>

        {importError && (
          <div className="bg-red-50 border border-red-100 px-4 py-2 rounded-xl flex items-center gap-3 text-red-600 animate-pulse">
            <Terminal className="w-4 h-4" />
            <span className="text-[9px] font-black uppercase">Falha de Mapeamento de Nomes</span>
          </div>
        )}

        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end mr-2">
             <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">Competência</span>
             <input 
               type="month" 
               value={selectedMonth} 
               onChange={e => { setSelectedMonth(e.target.value); setActivePersonName(null); }} 
               className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-1.5 text-xs font-bold outline-none cursor-pointer" 
             />
          </div>
          <label className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase cursor-pointer flex items-center gap-2 hover:bg-black transition-all shadow-xl active:scale-95">
            <FileUp className="w-4 h-4 text-[#E30613]" /> LER ARQUIVO AFD <input type="file" className="hidden" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* LISTA LATERAL */}
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm min-h-[60vh]">
          <div className="relative mb-6">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input type="text" placeholder="Buscar por Nome ou ID..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-slate-50 border rounded-xl text-xs font-bold outline-none" />
          </div>

          <div className="space-y-2 max-h-[55vh] overflow-y-auto pr-2 custom-scrollbar">
            {filteredPeople.length === 0 ? (
              <div className="py-24 text-center">
                <Fingerprint className="w-10 h-10 mx-auto mb-3 text-slate-100" />
                <p className="text-[10px] font-black uppercase text-slate-300 tracking-widest">Nenhum registro ativo</p>
                <p className="text-[8px] text-slate-200 mt-1 uppercase">Mude o mês ou importe dados</p>
              </div>
            ) : (
              filteredPeople.map(p => (
                <button 
                  key={p.name} 
                  onClick={() => { setActivePersonName(p.name); }} 
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonName === p.name ? 'bg-[#E30613] text-white border-[#E30613] shadow-lg shadow-red-100' : 'bg-slate-50 border-transparent hover:bg-slate-100 text-slate-600'}`}
                >
                  <p className="text-[10px] font-black uppercase truncate leading-tight">{p.name}</p>
                  <p className={`text-[8px] mt-1 ${activePersonName === p.name ? 'text-white/60' : 'text-slate-400'}`}>ID: {p.ids[0]}</p>
                </button>
              ))
            )}
          </div>
        </div>

        {/* ESPELHO DE PONTO */}
        <div className="lg:col-span-3">
          {activePerson ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
               <div className="bg-white border rounded-[2.5rem] p-8 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center border border-slate-100 shadow-sm"><IdCard className="text-[#E30613] w-8 h-8" /></div>
                     <div>
                        <h3 className="text-xl font-black uppercase text-slate-900 leading-none">{activePerson.name}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-2 tracking-widest">IDs: {activePerson.ids.join(' • ')}</p>
                     </div>
                  </div>
                  <button onClick={() => window.print()} className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 hover:bg-black transition-all shadow-xl"><Printer className="w-4 h-4 text-emerald-500" /> Imprimir Espelho</button>
               </div>

               <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                  <table className="w-full text-left border-collapse">
                    <thead className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-10 py-6">Data / Dia</th>
                        <th className="px-10 py-6">Marcações (AFD)</th>
                        <th className="px-4 py-6 text-center">Total Dia</th>
                        <th className="px-4 py-6 text-center">Auditoria</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {(() => {
                        const [y, m] = selectedMonth.split('-');
                        const days = new Date(Number(y), Number(m), 0).getDate();
                        return Array.from({length: days}, (_, i) => {
                          const day = (i+1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dp = punchesAtivos.filter(p => p.dayISO === iso);
                          const mins = calculateDayMins(dp);
                          const dt = new Date(iso + 'T12:00:00');
                          const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                          return (
                            <tr key={iso} className={`group hover:bg-slate-50 transition-all ${dp.length === 0 ? 'opacity-30' : ''} ${isWeekend ? 'bg-slate-50/20' : ''}`}>
                              <td className="px-10 py-5">
                                <span className="text-sm font-black text-slate-900">{day}/{m}</span>
                                <span className="text-[9px] font-bold text-slate-400 uppercase block leading-none">{dt.toLocaleDateString('pt-BR', {weekday: 'short'})}</span>
                              </td>
                              <td className="px-10 py-5">
                                <div className="flex flex-wrap gap-2">
                                  {dp.map((p, ix) => (
                                    <span key={ix} className="bg-white text-slate-700 text-[11px] font-black px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm" title={`NSR: ${p.nsr}`}>{p.time}</span>
                                  ))}
                                </div>
                              </td>
                              <td className="px-4 py-5 text-center font-black text-xs text-slate-600">
                                {mins > 0 ? `${Math.floor(mins/60)}h${(mins%60).toString().padStart(2,'0')}` : '--:--'}
                              </td>
                              <td className="px-4 py-5 text-center">
                                {dp.length % 2 !== 0 && <span title="Marcação Incompleta"><AlertOctagon className="w-5 h-5 text-red-500 mx-auto animate-pulse" /></span>}
                                {dp.length > 0 && dp.length % 2 === 0 && <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">OK</span>}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner text-center px-10">
              <Fingerprint className="w-24 h-24 opacity-10 mb-6 animate-pulse" />
              <p className="font-black uppercase text-sm tracking-[0.2em] text-slate-400">Selecione um colaborador na lista lateral</p>
              <p className="text-[10px] mt-2 font-bold text-slate-300 uppercase">Se a lista estiver vazia, certifique-se de importar o arquivo AFD correto.</p>
              {store.lastImport && (
                <div className="mt-8 px-6 py-3 bg-emerald-50 rounded-2xl border border-emerald-100 flex items-center gap-3">
                  <History className="w-4 h-4 text-emerald-500" />
                  <span className="text-[10px] font-black uppercase text-emerald-700 tracking-widest">Base Ativa: {store.punches.length} registros processados</span>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  FileUp, Search, ShieldCheck, 
  IdCard, AlertOctagon, Printer, Fingerprint, History, Terminal, AlertTriangle
} from 'lucide-react';

// --- MODELO DE DADOS ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; // Aliases canonicalizados (sempre 12 dígitos)
  active: boolean; 
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    stats: { punches: number; users: number } 
  };
};

// --- MOTOR DE PARSING BLINDADO ---

/** 
 * Canonicalização 12D: Resolve inconsistências de zeros à esquerda.
 */
const canon12 = (d: string) => d.replace(/\D/g, '').padStart(12, '0').slice(-12);

/** 
 * REGEX TIPO 5 (CADASTRO) - PAREDE DÍGITO-LETRA
 * Estrutura: NSR(10) + '5' + DATA(8) + HORA(4) + [IAE]? + ID + NOME
 * O segredo: (\d+?) consome dígitos até o lookahead (?=[A-ZÀ-Ü]) encontrar a primeira letra do nome.
 */
const RX_USER_IDCLASS = /^\d{10}5\d{8}\d{4}[IAE]?(\d+?)(?=[A-ZÀ-Ü])([A-ZÀ-Ü\s\-\']+)/;

/** 
 * REGEX TIPO 3 (BATIDA)
 */
const RX_PUNCH_IDCLASS = /^(\d{10})3(\d{8})(\d{4})[IAE]?(\d+)/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_ponto_v12_final');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonName, setActivePersonName] = useState<string | null>(null);
  const [debugInfo, setDebugInfo] = useState<{msg: string, samples: string[]} | null>(null);

  useEffect(() => {
    localStorage.setItem('abc_ponto_v12_final', JSON.stringify(store));
  }, [store]);

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    setDebugInfo(null);

    reader.readAsText(file, "ISO-8859-1"); 

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);

      const newPunches: Punch[] = [];
      const userMap = new Map<string, string>(); 
      let type5Samples: string[] = [];

      lines.forEach(raw => {
        // Coleta amostras de linhas de cadastro (Tipo 5) para diagnóstico em caso de erro
        if (raw.length > 11 && raw.substring(10, 11) === '5') {
          if (type5Samples.length < 5) type5Samples.push(raw);
        }

        // 1. Tentar ler Cadastro (Tipo 5)
        const userMatch = raw.match(RX_USER_IDCLASS);
        if (userMatch) {
          const id = canon12(userMatch[1]);
          const name = userMatch[2].trim().toUpperCase();
          if (name.length > 1) userMap.set(id, name);
          return;
        }

        // 2. Tentar ler Batida (Tipo 3)
        const punchMatch = raw.match(RX_PUNCH_IDCLASS);
        if (punchMatch) {
          const [, nsr, ddmmyyyy, hhmm, idRaw] = punchMatch;
          newPunches.push({
            nsr,
            dayISO: `${ddmmyyyy.slice(4, 8)}-${ddmmyyyy.slice(2, 4)}-${ddmmyyyy.slice(0, 2)}`,
            time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
            id: canon12(idRaw)
          });
        }
      });

      // Diagnóstico de falha: Batidas lidas mas 0 usuários
      if (userMap.size === 0 && newPunches.length > 0) {
        setDebugInfo({
          msg: "AVISO: Batidas encontradas, mas nenhum nome identificado. Verifique o formato do Tipo 5 no console.",
          samples: type5Samples
        });
        console.warn("DEBUG AFD - Linhas Tipo 5 detectadas mas não casaram com a Regex:", type5Samples);
      }

      setStore(prev => {
        const people = [...prev.people];

        // Mapeia nomes aos IDs (Aliases)
        userMap.forEach((name, id) => {
          let person = people.find(p => p.name === name);
          if (!person) {
            // Remove ID de qualquer outra pessoa se existir (limpeza de alias órfão)
            people.forEach(p => p.ids = p.ids.filter(v => v !== id));
            people.push({ name, ids: [id], active: true });
          } else if (!person.ids.includes(id)) {
            people.forEach(p => p.ids = p.ids.filter(v => v !== id));
            person.ids.push(id);
          }
        });

        // Garante que IDs sem Tipo 5 apareçam como "COLABORADOR ID"
        newPunches.forEach(p => {
          if (!people.find(pers => pers.ids.includes(p.id))) {
            people.push({ name: `COLABORADOR ${p.id}`, ids: [p.id], active: true });
          }
        });

        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const filteredNew = newPunches.filter(p => !existingNsrs.has(p.nsr));

        return {
          people: people.filter(p => p.ids.length > 0),
          punches: [...prev.punches, ...filteredNew],
          lastImport: { 
            file: file.name, 
            stats: { punches: newPunches.length, users: userMap.size } 
          }
        };
      });
    };
    event.target.value = '';
  };

  const filteredPeople = useMemo(() => {
    const activeIdsThisMonth = new Set(
      store.punches
        .filter(p => p.dayISO.startsWith(selectedMonth))
        .map(p => p.id)
    );

    return store.people
      .filter(p => {
        const hasPunches = p.ids.some(id => activeIdsThisMonth.has(id));
        const matchesSearch = p.name.includes(searchTerm.toUpperCase()) || p.ids.some(id => id.includes(searchTerm));
        return hasPunches && matchesSearch;
      })
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [store.people, store.punches, searchTerm, selectedMonth]);

  const activePerson = store.people.find(p => p.name === activePersonName);
  const punchesAtivos = useMemo(() => {
    if (!activePerson) return [];
    return store.punches
      .filter(pun => activePerson.ids.includes(pun.id) && pun.dayISO.startsWith(selectedMonth))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));
  }, [activePerson, store.punches, selectedMonth]);

  const calculateDayMins = (p: Punch[]) => {
    if (p.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < p.length - 1; i += 2) {
      const [h1, m1] = p[i].time.split(':').map(Number);
      const [h2, m2] = p[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  return (
    <div className="space-y-6">
      {/* HEADER DE IMPORTAÇÃO */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-5">
          <div className="bg-[#E30613] p-4 rounded-2xl shadow-lg shadow-red-100">
            <ShieldCheck className="text-white w-6 h-6" />
          </div>
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter text-[#0A1121]">Folha de Ponto</h2>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
               {store.lastImport ? `Lido: ${store.lastImport.file}` : 'Aguardando Importação AFD'}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end mr-2">
             <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">Mês Base</span>
             <input 
               type="month" 
               value={selectedMonth} 
               onChange={e => { setSelectedMonth(e.target.value); setActivePersonName(null); }} 
               className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-1.5 text-xs font-bold outline-none cursor-pointer" 
             />
          </div>
          <label className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase cursor-pointer flex items-center gap-2 hover:bg-black transition-all shadow-xl active:scale-95">
            <FileUp className="w-4 h-4 text-[#E30613]" /> LER ARQUIVO AFD <input type="file" className="hidden" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      {/* DIAGNÓSTICO DE ERRO */}
      {debugInfo && (
        <div className="bg-red-50 border border-red-100 p-6 rounded-3xl flex flex-col gap-4 animate-in fade-in slide-in-from-top-4">
          <div className="flex items-center gap-3 text-red-600">
            <AlertTriangle className="w-5 h-5" />
            <span className="text-xs font-black uppercase tracking-widest">{debugInfo.msg}</span>
          </div>
          <div className="bg-slate-900/5 p-4 rounded-xl space-y-2">
             <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-200 pb-2 mb-2">Amostras de Linhas Tipo 5 no Arquivo:</p>
             {debugInfo.samples.map((s, i) => (
               <code key={i} className="block text-[10px] font-mono text-slate-600 break-all">{s}</code>
             ))}
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* LISTA LATERAL */}
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm min-h-[60vh]">
          <div className="relative mb-6">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input type="text" placeholder="Nome ou ID..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-slate-50 border rounded-xl text-xs font-bold outline-none" />
          </div>

          <div className="space-y-2 max-h-[55vh] overflow-y-auto pr-2 custom-scrollbar">
            {filteredPeople.length === 0 ? (
              <div className="py-24 text-center">
                <Fingerprint className="w-10 h-10 mx-auto mb-3 text-slate-100" />
                <p className="text-[10px] font-black uppercase text-slate-300 tracking-widest">Nenhum registro ativo</p>
                <p className="text-[8px] text-slate-200 mt-1 uppercase">Apenas quem bateu ponto em {selectedMonth} aparece aqui.</p>
              </div>
            ) : (
              filteredPeople.map(p => (
                <button 
                  key={p.name} 
                  onClick={() => { setActivePersonName(p.name); }} 
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonName === p.name ? 'bg-[#E30613] text-white border-[#E30613] shadow-lg shadow-red-100' : 'bg-slate-50 border-transparent hover:bg-slate-100 text-slate-600'}`}
                >
                  <p className="text-[10px] font-black uppercase truncate leading-tight">{p.name}</p>
                  <p className={`text-[8px] mt-1 ${activePersonName === p.name ? 'text-white/60' : 'text-slate-400'}`}>ID: {p.ids[0]}</p>
                </button>
              ))
            )}
          </div>
        </div>

        {/* ESPELHO DE PONTO */}
        <div className="lg:col-span-3">
          {activePerson ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
               <div className="bg-white border rounded-[2.5rem] p-8 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center border border-slate-100 shadow-sm"><IdCard className="text-[#E30613] w-8 h-8" /></div>
                     <div>
                        <h3 className="text-xl font-black uppercase text-slate-900 leading-none">{activePerson.name}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-2 tracking-widest">IDs 12D: {activePerson.ids.join(' • ')}</p>
                     </div>
                  </div>
                  <button onClick={() => window.print()} className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 hover:bg-black transition-all shadow-xl"><Printer className="w-4 h-4 text-emerald-500" /> Imprimir Espelho</button>
               </div>

               <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                  <table className="w-full text-left border-collapse">
                    <thead className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-10 py-6">Data / Dia</th>
                        <th className="px-10 py-6">Marcações (AFD)</th>
                        <th className="px-4 py-6 text-center">Total Dia</th>
                        <th className="px-4 py-6 text-center">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {(() => {
                        const [y, m] = selectedMonth.split('-');
                        const days = new Date(Number(y), Number(m), 0).getDate();
                        return Array.from({length: days}, (_, i) => {
                          const day = (i+1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dp = punchesAtivos.filter(p => p.dayISO === iso);
                          const mins = calculateDayMins(dp);
                          const dt = new Date(iso + 'T12:00:00');
                          const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                          return (
                            <tr key={iso} className={`group hover:bg-slate-50 transition-all ${dp.length === 0 ? 'opacity-30' : ''} ${isWeekend ? 'bg-slate-50/20' : ''}`}>
                              <td className="px-10 py-5">
                                <span className="text-sm font-black text-slate-900">{day}/{m}</span>
                                <span className="text-[9px] font-bold text-slate-400 uppercase block leading-none">{dt.toLocaleDateString('pt-BR', {weekday: 'short'})}</span>
                              </td>
                              <td className="px-10 py-5">
                                <div className="flex flex-wrap gap-2">
                                  {dp.map((p, ix) => (
                                    <span key={ix} className="bg-white text-slate-700 text-[11px] font-black px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm" title={`NSR: ${p.nsr}`}>{p.time}</span>
                                  ))}
                                </div>
                              </td>
                              <td className="px-4 py-5 text-center font-black text-xs text-slate-600">
                                {mins > 0 ? `${Math.floor(mins/60)}h${(mins%60).toString().padStart(2,'0')}` : '--:--'}
                              </td>
                              <td className="px-4 py-5 text-center">
                                {dp.length % 2 !== 0 && <span title="Marcação Incompleta"><AlertOctagon className="w-5 h-5 text-red-500 mx-auto animate-pulse" /></span>}
                                {dp.length > 0 && dp.length % 2 === 0 && <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">OK</span>}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner text-center px-10">
              <Fingerprint className="w-24 h-24 opacity-10 mb-6 animate-pulse" />
              <p className="font-black uppercase text-sm tracking-[0.2em] text-slate-400">Selecione um colaborador na lista lateral</p>
              <p className="text-[10px] mt-2 font-bold text-slate-300 uppercase">Se a lista estiver vazia, certifique-se de importar o arquivo AFD correto.</p>
              {store.lastImport && (
                <div className="mt-8 px-6 py-3 bg-emerald-50 rounded-2xl border border-emerald-100 flex items-center gap-3">
                  <History className="w-4 h-4 text-emerald-500" />
                  <span className="text-[10px] font-black uppercase text-emerald-700 tracking-widest">Base Ativa: {store.punches.length} registros no sistema</span>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  FileUp, Search, ShieldCheck, 
  IdCard, AlertOctagon, Printer, Fingerprint, History, Terminal, AlertTriangle
} from 'lucide-react';

// --- MODELO DE DADOS ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; // Aliases canonicalizados (sempre 12 dígitos)
  active: boolean; 
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    stats: { punches: number; users: number } 
  };
};

// --- MOTOR DE PARSING ROBUSTO ---

/** 
 * Canonicalização 12D: Resolve inconsistências de zeros à esquerda.
 */
const canon12 = (d: string) => d.replace(/\D/g, '').padStart(12, '0').slice(-12);

/** 
 * REGEX TIPO 5 (CADASTRO) - ANCORAGEM POR PADRÃO AFD
 * 1. \d{10}5\d{8}\d{4} : Ancoragem dinâmica por NSR(10) + Tipo(5) + Data(8) + Hora(4).
 * 2. [IAE]? : Marcador opcional.
 * 3. (\d+?) : ID capturado de forma lazy até a parede.
 * 4. (?=[A-ZÀ-Ü]) : Lookahead para a primeira letra (Parede Dígito->Letra).
 * 5. ([A-ZÀ-Ü\s\-\']+) : Nome incluindo acentos e hífens.
 */
const RX_USER_IDCLASS = /\d{10}5\d{8}\d{4}[IAE]?(\d+?)(?=[A-ZÀ-Ü])([A-ZÀ-Ü\s\-\']+)/;

/** 
 * REGEX TIPO 3 (BATIDA)
 * Ancoragem dinâmica similar para garantir captura independente de ruído inicial.
 */
const RX_PUNCH_IDCLASS = /(\d{10})3(\d{8})(\d{4})[IAE]?(\d+)/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_ponto_v13_final');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonName, setActivePersonName] = useState<string | null>(null);
  const [debugInfo, setDebugInfo] = useState<{msg: string, samples: string[]} | null>(null);

  useEffect(() => {
    localStorage.setItem('abc_ponto_v13_final', JSON.stringify(store));
  }, [store]);

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    setDebugInfo(null);

    // ISO-8859-1 preserva acentos para a Regex não falhar na parede de letras
    reader.readAsText(file, "ISO-8859-1"); 

    reader.onload = (e) => {
      const content = e.target?.result as string;
      // NUNCA filtrar por tamanho, apenas remover linhas vazias
      const lines = content.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);

      const newPunches: Punch[] = [];
      const userMap = new Map<string, string>(); 
      let type5LinesFound: string[] = [];

      lines.forEach(raw => {
        // Coleta amostras de qualquer linha que pareça ser Tipo 5 para diagnóstico
        if (raw.length > 11 && raw.substring(10, 11) === '5') {
          type5LinesFound.push(raw);
        }

        // 1. Tentar ler Cadastro (Tipo 5) com Parede Dígito->Letra
        const userMatch = raw.match(RX_USER_IDCLASS);
        if (userMatch) {
          const id = canon12(userMatch[1]);
          const name = userMatch[2].trim().toUpperCase();
          if (name.length > 1) userMap.set(id, name);
          return;
        }

        // 2. Tentar ler Batida (Tipo 3)
        const punchMatch = raw.match(RX_PUNCH_IDCLASS);
        if (punchMatch) {
          const [, nsr, ddmmyyyy, hhmm, idRaw] = punchMatch;
          newPunches.push({
            nsr,
            dayISO: `${ddmmyyyy.slice(4, 8)}-${ddmmyyyy.slice(2, 4)}-${ddmmyyyy.slice(0, 2)}`,
            time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
            id: canon12(idRaw)
          });
        }
      });

      // Diagnóstico: Se encontrou linhas '5' mas a Regex não extraiu nomes
      if (userMap.size === 0 && type5LinesFound.length > 0) {
        setDebugInfo({
          msg: `ERRO DE MAPEAMENTO: ${type5LinesFound.length} linhas de cadastro detectadas, mas 0 nomes extraídos. Verifique a "Parede" abaixo.`,
          samples: type5LinesFound.slice(0, 5)
        });
      }

      setStore(prev => {
        const people = [...prev.people];

        // Atualiza base de pessoas com novos Aliases
        userMap.forEach((name, id) => {
          let person = people.find(p => p.name === name);
          if (!person) {
            people.forEach(p => p.ids = p.ids.filter(v => v !== id));
            people.push({ name, ids: [id], active: true });
          } else if (!person.ids.includes(id)) {
            people.forEach(p => p.ids = p.ids.filter(v => v !== id));
            person.ids.push(id);
          }
        });

        // Garante exibição de IDs que bateram mas não estão no Tipo 5
        newPunches.forEach(p => {
          if (!people.find(pers => pers.ids.includes(p.id))) {
            people.push({ name: `COLABORADOR ${p.id}`, ids: [p.id], active: true });
          }
        });

        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const filteredNew = newPunches.filter(p => !existingNsrs.has(p.nsr));

        return {
          people: people.filter(p => p.ids.length > 0),
          punches: [...prev.punches, ...filteredNew],
          lastImport: { 
            file: file.name, 
            stats: { punches: newPunches.length, users: userMap.size } 
          }
        };
      });
    };
    event.target.value = '';
  };

  const filteredPeople = useMemo(() => {
    const activeIdsThisMonth = new Set(
      store.punches
        .filter(p => p.dayISO.startsWith(selectedMonth))
        .map(p => p.id)
    );

    return store.people
      .filter(p => {
        const hasPunches = p.ids.some(id => activeIdsThisMonth.has(id));
        const matchesSearch = p.name.includes(searchTerm.toUpperCase()) || p.ids.some(id => id.includes(searchTerm));
        return hasPunches && matchesSearch;
      })
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [store.people, store.punches, searchTerm, selectedMonth]);

  const activePerson = store.people.find(p => p.name === activePersonName);
  const punchesAtivos = useMemo(() => {
    if (!activePerson) return [];
    return store.punches
      .filter(pun => activePerson.ids.includes(pun.id) && pun.dayISO.startsWith(selectedMonth))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));
  }, [activePerson, store.punches, selectedMonth]);

  const calculateDayMins = (p: Punch[]) => {
    if (p.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < p.length - 1; i += 2) {
      const [h1, m1] = p[i].time.split(':').map(Number);
      const [h2, m2] = p[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-5">
          <div className="bg-[#E30613] p-4 rounded-2xl shadow-lg">
            <ShieldCheck className="text-white w-6 h-6" />
          </div>
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter text-[#0A1121]">Folha de Ponto</h2>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
               {store.lastImport ? `Último: ${store.lastImport.file}` : 'Aguardando Arquivo AFD'}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end mr-2">
             <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">Período</span>
             <input 
               type="month" 
               value={selectedMonth} 
               onChange={e => { setSelectedMonth(e.target.value); setActivePersonName(null); }} 
