             />
          </div>
          <label className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase cursor-pointer flex items-center gap-2 hover:bg-black transition-all shadow-xl active:scale-95">
            <FileUp className="w-4 h-4 text-[#E30613]" /> LER ARQUIVO AFD <input type="file" className="hidden" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      {debugInfo && (
        <div className="bg-red-50 border border-red-200 p-8 rounded-[2rem] space-y-4 animate-in slide-in-from-top-4">
          <div className="flex items-center gap-3 text-red-600">
            <AlertTriangle className="w-5 h-5" />
            <span className="text-xs font-black uppercase tracking-widest">{debugInfo.msg}</span>
          </div>
          <div className="bg-slate-900 p-6 rounded-2xl space-y-3">
             <p className="text-[9px] font-black text-slate-400 uppercase border-b border-white/10 pb-2">Linhas brutas detectadas (Tipo 5):</p>
             {debugInfo.samples.map((s, i) => (
               <code key={i} className="block text-[10px] font-mono text-emerald-400 break-all leading-relaxed opacity-80">{s}</code>
             ))}
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm min-h-[60vh]">
          <div className="relative mb-6">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input type="text" placeholder="Nome ou ID..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-slate-50 border rounded-xl text-xs font-bold outline-none" />
          </div>

          <div className="space-y-2 max-h-[55vh] overflow-y-auto pr-2 custom-scrollbar">
            {filteredPeople.length === 0 ? (
              <div className="py-24 text-center">
                <Fingerprint className="w-10 h-10 mx-auto mb-3 text-slate-100" />
                <p className="text-[10px] font-black uppercase text-slate-300 tracking-widest">Nenhum registro ativo</p>
              </div>
            ) : (
              filteredPeople.map(p => (
                <button 
                  key={p.name} 
                  onClick={() => { setActivePersonName(p.name); }} 
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonName === p.name ? 'bg-[#E30613] text-white border-[#E30613] shadow-lg shadow-red-100' : 'bg-slate-50 border-transparent hover:bg-slate-100 text-slate-600'}`}
                >
                  <p className="text-[10px] font-black uppercase truncate leading-tight">{p.name}</p>
                  <p className={`text-[8px] mt-1 ${activePersonName === p.name ? 'text-white/60' : 'text-slate-400'}`}>ID: {p.ids[0]}</p>
                </button>
              ))
            )}
          </div>
        </div>

        <div className="lg:col-span-3">
          {activePerson ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
               <div className="bg-white border rounded-[2.5rem] p-8 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center border border-slate-100 shadow-sm"><IdCard className="text-[#E30613] w-8 h-8" /></div>
                     <div>
                        <h3 className="text-xl font-black uppercase text-slate-900 leading-none">{activePerson.name}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-2 tracking-widest">IDs: {activePerson.ids.join(' • ')}</p>
                     </div>
                  </div>
                  <button onClick={() => window.print()} className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 hover:bg-black transition-all shadow-xl"><Printer className="w-4 h-4 text-emerald-500" /> Imprimir</button>
               </div>

               <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                  <table className="w-full text-left border-collapse">
                    <thead className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-10 py-6">Data</th>
                        <th className="px-10 py-6">Marcações</th>
                        <th className="px-4 py-6 text-center">Horas</th>
                        <th className="px-4 py-6 text-center">Auditoria</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {(() => {
                        const [y, m] = selectedMonth.split('-');
                        const days = new Date(Number(y), Number(m), 0).getDate();
                        return Array.from({length: days}, (_, i) => {
                          const day = (i+1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dp = punchesAtivos.filter(p => p.dayISO === iso);
                          const mins = calculateDayMins(dp);
                          const dt = new Date(iso + 'T12:00:00');
                          const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                          return (
                            <tr key={iso} className={`group hover:bg-slate-50 transition-all ${dp.length === 0 ? 'opacity-30' : ''} ${isWeekend ? 'bg-slate-50/20' : ''}`}>
                              <td className="px-10 py-5">
                                <span className="text-sm font-black text-slate-900">{day}/{m}</span>
                                <span className="text-[9px] font-bold text-slate-400 uppercase block leading-none">{dt.toLocaleDateString('pt-BR', {weekday: 'short'})}</span>
                              </td>
                              <td className="px-10 py-5">
                                <div className="flex flex-wrap gap-2">
                                  {dp.map((p, ix) => (
                                    <span key={ix} className="bg-white text-slate-700 text-[11px] font-black px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm" title={`NSR: ${p.nsr}`}>{p.time}</span>
                                  ))}
                                </div>
                              </td>
                              <td className="px-4 py-5 text-center font-black text-xs text-slate-600">
                                {mins > 0 ? `${Math.floor(mins/60)}h${(mins%60).toString().padStart(2,'0')}` : '--:--'}
                              </td>
                              <td className="px-4 py-5 text-center">
                                {dp.length % 2 !== 0 && <span title="Marcação Incompleta"><AlertOctagon className="w-5 h-5 text-red-500 mx-auto animate-pulse" /></span>}
                                {dp.length > 0 && dp.length % 2 === 0 && <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">OK</span>}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner text-center px-10">
              <Fingerprint className="w-24 h-24 opacity-10 mb-6 animate-pulse" />
              <p className="font-black uppercase text-sm tracking-[0.2em] text-slate-400">Selecione um colaborador na lista lateral</p>
              <p className="text-[10px] mt-2 font-bold text-slate-300 uppercase">Se a lista estiver vazia, certifique-se de importar o arquivo AFD correto.</p>
              {store.lastImport && (
                <div className="mt-8 px-6 py-3 bg-emerald-50 rounded-2xl border border-emerald-100 flex items-center gap-3">
                  <History className="w-4 h-4 text-emerald-500" />
                  <span className="text-[10px] font-black uppercase text-emerald-700 tracking-widest">Base Ativa: {store.punches.length} registros no sistema</span>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  FileUp, Search, ShieldCheck, 
  IdCard, AlertOctagon, Printer, Fingerprint, History, Terminal, AlertTriangle
} from 'lucide-react';

// --- MODELO DE DADOS ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; // Aliases canonicalizados (sempre 12 dígitos)
  active: boolean; 
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    stats: { punches: number; users: number } 
  };
};

// --- MOTOR DE PARSING ROBUSTO (SINAL IMUTÁVEL) ---

/** 
 * Canonicalização 12D: Chave única de 12 dígitos para IDs.
 */
const canon12 = (d: string) => d.replace(/\D/g, '').padStart(12, '0').slice(-12);

/** 
 * REGEX TIPO 3 (BATIDA) - RESILIENTE
 * Busca o padrão: Data(8) + Hora(4) + ID (Dígitos)
 * Ignora o que vem antes (NSR/Tipo).
 */
const RX_PUNCH = /\d{8}\d{4}[IAE]?(\d+)/;

/** 
 * REGEX TIPO 5 (CADASTRO) - A "PAREDE" DEFINITIVA
 * Identifica a linha pela transição: Dígitos -> Letras Maiúsculas/Acentuadas.
 * 1. (\d+) : Captura o ID (sequência de números).
 * 2. (?=[A-ZÀ-Ü]) : Lookahead para a parede de letras (Nome).
 * 3. ([A-ZÀ-Ü\s\-\']+) : Captura o Nome.
 */
const RX_USER_WALL = /(\d+)(?=[A-ZÀ-Ü])([A-ZÀ-Ü\s\-\']+)/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_ponto_v14_robust');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonName, setActivePersonName] = useState<string | null>(null);
  const [debugLines, setDebugLines] = useState<string[]>([]);

  useEffect(() => {
    localStorage.setItem('abc_ponto_v14_robust', JSON.stringify(store));
  }, [store]);

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    setDebugLines([]);

    // ISO-8859-1 é vital para não corromper acentos que definem a "Parede" de letras
    reader.readAsText(file, "ISO-8859-1"); 

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 5);

      const newPunches: Punch[] = [];
      const userMap = new Map<string, string>(); 
      let rawLinesSample: string[] = [];

      lines.forEach(raw => {
        if (rawLinesSample.length < 10) rawLinesSample.push(raw);

        // REGRA 1: É uma Batida? (Padrão de Data/Hora)
        // O AFD padrão Tipo 3 tem: NSR(10) + '3' + DATA(8) + HORA(4)
        if (raw.length >= 23 && raw.includes('3', 10)) {
          const match = raw.match(RX_PUNCH);
          if (match) {
            const datePart = raw.substring(11, 19);
            const timePart = raw.substring(19, 23);
            const idRaw = match[1];

            newPunches.push({
              nsr: raw.substring(0, 10),
              dayISO: `${datePart.slice(4, 8)}-${datePart.slice(2, 4)}-${datePart.slice(0, 2)}`,
              time: `${timePart.slice(0, 2)}:${timePart.slice(2, 4)}`,
              id: canon12(idRaw)
            });
            return;
          }
        }

        // REGRA 2: É um Cadastro? (Transição Dígito -> Letra)
        const userMatch = raw.match(RX_USER_WALL);
        if (userMatch) {
          const id = canon12(userMatch[1]);
          const name = userMatch[2].trim().toUpperCase();
          if (name.length > 2) {
            userMap.set(id, name);
          }
        }
      });

      // Diagnóstico: Se leu batidas mas não mapeou nomes
      if (userMap.size === 0 && newPunches.length > 0) {
        setDebugLines(rawLinesSample);
        console.warn("AFD Parser: Batidas detectadas, mas a Parede Dígito->Letra não encontrou nomes.", rawLinesSample);
      }

      setStore(prev => {
        const people = [...prev.people];

        // Vincula nomes aos IDs
        userMap.forEach((name, id) => {
          let person = people.find(p => p.name === name);
          if (!person) {
            people.forEach(p => p.ids = p.ids.filter(v => v !== id));
            people.push({ name, ids: [id], active: true });
          } else if (!person.ids.includes(id)) {
            people.forEach(p => p.ids = p.ids.filter(v => v !== id));
            person.ids.push(id);
          }
        });

        // Adiciona IDs sem nome como "COLABORADOR ID"
        newPunches.forEach(p => {
          if (!people.find(pers => pers.ids.includes(p.id))) {
            people.push({ name: `COLABORADOR ${p.id}`, ids: [p.id], active: true });
          }
        });

        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const filteredNew = newPunches.filter(p => !existingNsrs.has(p.nsr));

        return {
          people: people.filter(p => p.ids.length > 0),
          punches: [...prev.punches, ...filteredNew],
          lastImport: { 
            file: file.name, 
            stats: { punches: newPunches.length, users: userMap.size } 
          }
        };
      });
    };
    event.target.value = '';
  };

  const filteredPeople = useMemo(() => {
    const activeIdsThisMonth = new Set(
      store.punches
        .filter(p => p.dayISO.startsWith(selectedMonth))
        .map(p => p.id)
    );

    return store.people
      .filter(p => {
        const hasPunches = p.ids.some(id => activeIdsThisMonth.has(id));
        const matchesSearch = p.name.includes(searchTerm.toUpperCase()) || p.ids.some(id => id.includes(searchTerm));
        return hasPunches && matchesSearch;
      })
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [store.people, store.punches, searchTerm, selectedMonth]);

  const activePerson = store.people.find(p => p.name === activePersonName);
  const punchesAtivos = useMemo(() => {
    if (!activePerson) return [];
    return store.punches
      .filter(pun => activePerson.ids.includes(pun.id) && pun.dayISO.startsWith(selectedMonth))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));
  }, [activePerson, store.punches, selectedMonth]);

  const calculateDayMins = (p: Punch[]) => {
    if (p.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < p.length - 1; i += 2) {
      const [h1, m1] = p[i].time.split(':').map(Number);
      const [h2, m2] = p[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  return (
    <div className="space-y-6">
      {/* HEADER */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-5">
          <div className="bg-[#E30613] p-4 rounded-2xl shadow-lg">
            <ShieldCheck className="text-white w-6 h-6" />
          </div>
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter text-[#0A1121]">Folha de Ponto</h2>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
               {store.lastImport ? `Lido: ${store.lastImport.file}` : 'Aguardando Arquivo AFD'}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end mr-2">
             <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">Mês Base</span>
             <input 
               type="month" 
               value={selectedMonth} 
               onChange={e => { setSelectedMonth(e.target.value); setActivePersonName(null); }} 
               className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-1.5 text-xs font-bold outline-none cursor-pointer" 
             />
          </div>
          <label className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase cursor-pointer flex items-center gap-2 hover:bg-black transition-all shadow-xl active:scale-95">
            <FileUp className="w-4 h-4 text-[#E30613]" /> LER ARQUIVO AFD <input type="file" className="hidden" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      {/* ALERTA DE DIAGNÓSTICO */}
      {debugLines.length > 0 && store.people.length < 5 && (
        <div className="bg-red-50 border border-red-200 p-8 rounded-[2rem] space-y-4">
          <div className="flex items-center gap-3 text-red-600">
            <AlertTriangle className="w-5 h-5" />
            <span className="text-xs font-black uppercase tracking-widest">Aviso de Mapeamento: Batidas lidas, mas nomes não identificados.</span>
          </div>
          <div className="bg-slate-900 p-6 rounded-2xl space-y-2">
            <p className="text-[8px] font-black text-slate-500 uppercase tracking-[0.2em] mb-2">Análise das Linhas Brutas (Primeiras 10):</p>
            {debugLines.map((line, i) => (
              <code key={i} className="block text-[10px] font-mono text-emerald-400 opacity-70 break-all">{line}</code>
            ))}
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* LISTA DE COLABORADORES */}
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm min-h-[60vh]">
          <div className="relative mb-6">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input type="text" placeholder="Filtrar..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-slate-50 border rounded-xl text-xs font-bold outline-none" />
          </div>

          <div className="space-y-2 max-h-[55vh] overflow-y-auto pr-2 custom-scrollbar">
            {filteredPeople.length === 0 ? (
              <div className="py-24 text-center">
                <Fingerprint className="w-10 h-10 mx-auto mb-3 text-slate-100" />
                <p className="text-[10px] font-black uppercase text-slate-300 tracking-widest">Nenhum registro ativo</p>
              </div>
            ) : (
              filteredPeople.map(p => (
                <button 
                  key={p.name} 
                  onClick={() => { setActivePersonName(p.name); }} 
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonName === p.name ? 'bg-[#E30613] text-white border-[#E30613] shadow-lg shadow-red-100' : 'bg-slate-50 border-transparent hover:bg-slate-100 text-slate-600'}`}
                >
                  <p className="text-[10px] font-black uppercase truncate leading-tight">{p.name}</p>
                  <p className={`text-[8px] mt-1 ${activePersonName === p.name ? 'text-white/60' : 'text-slate-400'}`}>ID: {p.ids[0]}</p>
                </button>
              ))
            )}
          </div>
        </div>

        {/* ESPELHO DE PONTO */}
        <div className="lg:col-span-3">
          {activePerson ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
               <div className="bg-white border rounded-[2.5rem] p-8 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center border border-slate-100 shadow-sm"><IdCard className="text-[#E30613] w-8 h-8" /></div>
                     <div>
                        <h3 className="text-xl font-black uppercase text-slate-900 leading-none">{activePerson.name}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-2 tracking-widest">Aliases Ativos: {activePerson.ids.join(' • ')}</p>
                     </div>
                  </div>
                  <button onClick={() => window.print()} className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 hover:bg-black transition-all shadow-xl"><Printer className="w-4 h-4 text-emerald-500" /> Imprimir Espelho</button>
               </div>

               <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                  <table className="w-full text-left border-collapse">
                    <thead className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-10 py-6">Data / Dia</th>
                        <th className="px-10 py-6">Marcações</th>
                        <th className="px-4 py-6 text-center">Tempo Total</th>
                        <th className="px-4 py-6 text-center">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {(() => {
                        const [y, m] = selectedMonth.split('-');
                        const days = new Date(Number(y), Number(m), 0).getDate();
                        return Array.from({length: days}, (_, i) => {
                          const day = (i+1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dp = punchesAtivos.filter(p => p.dayISO === iso);
                          const mins = calculateDayMins(dp);
                          const dt = new Date(iso + 'T12:00:00');
                          const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                          return (
                            <tr key={iso} className={`group hover:bg-slate-50 transition-all ${dp.length === 0 ? 'opacity-30' : ''} ${isWeekend ? 'bg-slate-50/20' : ''}`}>
                              <td className="px-10 py-5">
                                <span className="text-sm font-black text-slate-900">{day}/{m}</span>
                                <span className="text-[9px] font-bold text-slate-400 uppercase block leading-none">{dt.toLocaleDateString('pt-BR', {weekday: 'short'})}</span>
                              </td>
                              <td className="px-10 py-5">
                                <div className="flex flex-wrap gap-2">
                                  {dp.map((p, ix) => (
                                    <span key={ix} className="bg-white text-slate-700 text-[11px] font-black px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm">{p.time}</span>
                                  ))}
                                </div>
                              </td>
                              <td className="px-4 py-5 text-center font-black text-xs text-slate-600">
                                {mins > 0 ? `${Math.floor(mins/60)}h${(mins%60).toString().padStart(2,'0')}` : '--:--'}
                              </td>
                              <td className="px-4 py-5 text-center">
                                {dp.length % 2 !== 0 && <span title="Marcação Incompleta"><AlertOctagon className="w-5 h-5 text-red-500 mx-auto animate-pulse" /></span>}
                                {dp.length > 0 && dp.length % 2 === 0 && <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">OK</span>}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner text-center px-10">
              <Fingerprint className="w-24 h-24 opacity-10 mb-6 animate-pulse" />
              <p className="font-black uppercase text-sm tracking-[0.2em] text-slate-400">Selecione um colaborador na lista lateral</p>
              <p className="text-[10px] mt-2 font-bold text-slate-300 uppercase">Se a lista estiver vazia, certifique-se de importar o arquivo AFD correto.</p>
              {store.lastImport && (
                <div className="mt-8 px-6 py-3 bg-emerald-50 rounded-2xl border border-emerald-100 flex items-center gap-3">
                  <History className="w-4 h-4 text-emerald-500" />
                  <span className="text-[10px] font-black uppercase text-emerald-700 tracking-widest">Base Ativa: {store.punches.length} registros processados</span>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  FileUp, Search, ShieldCheck, 
  IdCard, AlertOctagon, Printer, Fingerprint, History, AlertTriangle
} from 'lucide-react';

// --- MODELO DE DADOS ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; // Aliases canonicalizados (sempre 12 dígitos)
  active: boolean; 
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    stats: { punches: number; users: number } 
  };
};

// --- MOTOR DE PARSING ULTRA-ROBUSTO (SINAL SEMÂNTICO) ---

/** 
 * Canonicalização 12D: Resolve variações de zeros à esquerda (ex: 575 e 000000000575)
 */
const canon12 = (d: string) => d.replace(/\D/g, '').padStart(12, '0').slice(-12);

/**
 * REGEX DE CADASTRO (TIPO 5) - PAREDE DÍGITO->LETRA
 * Busca: Data(8) + Hora(4) + [IAE]? + ID(\d+?) + Nome(?=[A-ZÀ-Ü])
 * O sinal imutável é a transição de número para letra humana.
 */
const RX_CADASTRO_WALL = /(\d{8})(\d{4})[IAE]?(\d+?)(?=[A-ZÀ-Ü])([A-ZÀ-Ü\s\-\']+)/;

/**
 * REGEX DE BATIDA (TIPO 3)
 * Busca: Data(8) + Hora(4) + [IAE]? + ID(\d+)
 * Nota: Como a batida termina em número (ID), não precisa de lookahead.
 */
const RX_BATIDA = /(\d{8})(\d{4})[IAE]?(\d+)$/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_ponto_v15_final');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonName, setActivePersonName] = useState<string | null>(null);
  const [debugLines, setDebugLines] = useState<string[]>([]);

  useEffect(() => {
    localStorage.setItem('abc_ponto_v15_final', JSON.stringify(store));
  }, [store]);

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    setDebugLines([]);

    // ISO-8859-1 preserva acentos, essencial para a "Parede de Letras" (?=[A-ZÀ-Ü])
    reader.readAsText(file, "ISO-8859-1"); 

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 10);

      const newPunches: Punch[] = [];
      const userMap = new Map<string, string>(); 
      let ignoredLines: string[] = [];

      lines.forEach((raw, idx) => {
        // Tentar identificar como Cadastro primeiro (mais específico pela parede de letras)
        const userMatch = raw.match(RX_CADASTRO_WALL);
        if (userMatch) {
          const id = canon12(userMatch[3]);
          const name = userMatch[4].trim().toUpperCase();
          if (name.length > 2) userMap.set(id, name);
          return;
        }

        // Tentar identificar como Batida
        const punchMatch = raw.match(RX_BATIDA);
        if (punchMatch) {
          const [, ddmmyyyy, hhmm, idRaw] = punchMatch;
          // O NSR em AFD padrão são os 10 primeiros dígitos da linha, se existirem
          const nsr = raw.substring(0, 10).replace(/\D/g, '').padStart(10, '0');

          newPunches.push({
            nsr: nsr + idx, // Sal para garantir unicidade em layouts viciados
            dayISO: `${ddmmyyyy.slice(4, 8)}-${ddmmyyyy.slice(2, 4)}-${ddmmyyyy.slice(0, 2)}`,
            time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
            id: canon12(idRaw)
          });
          return;
        }

        // Se não casou com nenhum, logar para debug se tiver potencial de ser Tipo 5
        if (raw.includes('5', 10) || raw.match(/[A-Z]/)) {
          if (ignoredLines.length < 10) ignoredLines.push(raw);
        }
      });

      // Diagnóstico Crítico: Se temos batidas mas nenhum nome foi extraído
      if (userMap.size === 0 && newPunches.length > 0) {
        setDebugLines(ignoredLines.length > 0 ? ignoredLines : lines.slice(0, 10));
        console.error("FALHA DE PARSING: Batidas lidas, mas o ID e Nome estão colados ou em formato não reconhecido pela parede dígito-letra.");
      }

      setStore(prev => {
        const people = [...prev.people];

        // Mapear Nomes -> IDs (Aliases)
        userMap.forEach((name, id) => {
          let person = people.find(p => p.name === name);
          if (!person) {
            // Remove esse ID de qualquer outra pessoa para evitar duplicidade
            people.forEach(p => p.ids = p.ids.filter(v => v !== id));
            people.push({ name, ids: [id], active: true });
          } else if (!person.ids.includes(id)) {
            people.forEach(p => p.ids = p.ids.filter(v => v !== id));
            person.ids.push(id);
          }
        });

        // Garantir que batidas órfãs apareçam como "COLABORADOR [ID]"
        newPunches.forEach(p => {
          if (!people.find(pers => pers.ids.includes(p.id))) {
            people.push({ name: `COLABORADOR ${p.id}`, ids: [p.id], active: true });
          }
        });

        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const filteredNew = newPunches.filter(p => !existingNsrs.has(p.nsr));

        return {
          people: people.filter(p => p.ids.length > 0),
          punches: [...prev.punches, ...filteredNew],
          lastImport: { 
            file: file.name, 
            stats: { punches: newPunches.length, users: userMap.size } 
          }
        };
      });
    };
    event.target.value = '';
  };

  const filteredPeople = useMemo(() => {
    const activeIdsThisMonth = new Set(
      store.punches
        .filter(p => p.dayISO.startsWith(selectedMonth))
        .map(p => p.id)
    );

    return store.people
      .filter(p => {
        const hasPunches = p.ids.some(id => activeIdsThisMonth.has(id));
        const matchesSearch = p.name.includes(searchTerm.toUpperCase()) || p.ids.some(id => id.includes(searchTerm));
        return hasPunches && matchesSearch;
      })
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [store.people, store.punches, searchTerm, selectedMonth]);

  const activePerson = store.people.find(p => p.name === activePersonName);
  const punchesAtivos = useMemo(() => {
    if (!activePerson) return [];
    return store.punches
      .filter(pun => activePerson.ids.includes(pun.id) && pun.dayISO.startsWith(selectedMonth))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));
  }, [activePerson, store.punches, selectedMonth]);

  const calculateDayMins = (p: Punch[]) => {
    if (p.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < p.length - 1; i += 2) {
      const [h1, m1] = p[i].time.split(':').map(Number);
      const [h2, m2] = p[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-5">
          <div className="bg-[#E30613] p-4 rounded-2xl shadow-lg">
            <ShieldCheck className="text-white w-6 h-6" />
          </div>
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter text-[#0A1121]">Folha de Ponto</h2>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
               {store.lastImport ? `Lido: ${store.lastImport.file}` : 'Aguardando Importação'}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end mr-2">
             <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">Mês Base</span>
             <input 
               type="month" 
               value={selectedMonth} 
               onChange={e => { setSelectedMonth(e.target.value); setActivePersonName(null); }} 
               className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-1.5 text-xs font-bold outline-none cursor-pointer" 
             />
          </div>
          <label className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase cursor-pointer flex items-center gap-2 hover:bg-black transition-all shadow-xl active:scale-95">
            <FileUp className="w-4 h-4 text-[#E30613]" /> LER ARQUIVO AFD <input type="file" className="hidden" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      {debugLines.length > 0 && store.people.length < 2 && (
        <div className="bg-red-50 border border-red-200 p-8 rounded-[2rem] space-y-4">
          <div className="flex items-center gap-3 text-red-600">
            <AlertTriangle className="w-5 h-5" />
            <span className="text-xs font-black uppercase tracking-widest">Aviso de Compatibilidade iDClass</span>
          </div>
          <div className="bg-slate-900 p-6 rounded-2xl space-y-2">
            <p className="text-[8px] font-black text-slate-500 uppercase tracking-[0.2em] mb-2">Análise de Conteúdo (Transição Dígito-Letra falhou):</p>
            {debugLines.map((line, i) => (
              <code key={i} className="block text-[10px] font-mono text-emerald-400 opacity-70 break-all leading-relaxed">{line}</code>
            ))}
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm min-h-[60vh]">
          <div className="relative mb-6">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input type="text" placeholder="Buscar Colaborador..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-slate-50 border rounded-xl text-xs font-bold outline-none" />
          </div>

          <div className="space-y-2 max-h-[55vh] overflow-y-auto pr-2 custom-scrollbar">
            {filteredPeople.length === 0 ? (
              <div className="py-24 text-center">
                <Fingerprint className="w-10 h-10 mx-auto mb-3 text-slate-100" />
                <p className="text-[10px] font-black uppercase text-slate-300 tracking-widest">Nenhum registro ativo</p>
              </div>
            ) : (
              filteredPeople.map(p => (
                <button 
                  key={p.name} 
                  onClick={() => { setActivePersonName(p.name); }} 
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonName === p.name ? 'bg-[#E30613] text-white border-[#E30613] shadow-lg shadow-red-100' : 'bg-slate-50 border-transparent hover:bg-slate-100 text-slate-600'}`}
                >
                  <p className="text-[10px] font-black uppercase truncate leading-tight">{p.name}</p>
                  <p className={`text-[8px] mt-1 ${activePersonName === p.name ? 'text-white/60' : 'text-slate-400'}`}>ID: {p.ids[0]}</p>
                </button>
              ))
            )}
          </div>
        </div>

        <div className="lg:col-span-3">
          {activePerson ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
               <div className="bg-white border rounded-[2.5rem] p-8 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center border border-slate-100 shadow-sm"><IdCard className="text-[#E30613] w-8 h-8" /></div>
                     <div>
                        <h3 className="text-xl font-black uppercase text-slate-900 leading-none">{activePerson.name}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-2 tracking-widest">Aliases Canônicos: {activePerson.ids.join(' • ')}</p>
                     </div>
                  </div>
                  <button onClick={() => window.print()} className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 hover:bg-black transition-all shadow-xl"><Printer className="w-4 h-4 text-emerald-500" /> Imprimir Ponto</button>
               </div>

               <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                  <table className="w-full text-left border-collapse">
                    <thead className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-10 py-6">Data</th>
                        <th className="px-10 py-6">Marcações AFD</th>
                        <th className="px-4 py-6 text-center">Horas</th>
                        <th className="px-4 py-6 text-center">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {(() => {
                        const [y, m] = selectedMonth.split('-');
                        const days = new Date(Number(y), Number(m), 0).getDate();
                        return Array.from({length: days}, (_, i) => {
                          const day = (i+1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dp = punchesAtivos.filter(p => p.dayISO === iso);
                          const mins = calculateDayMins(dp);
                          const dt = new Date(iso + 'T12:00:00');
                          const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                          return (
                            <tr key={iso} className={`group hover:bg-slate-50 transition-all ${dp.length === 0 ? 'opacity-30' : ''} ${isWeekend ? 'bg-slate-50/20' : ''}`}>
                              <td className="px-10 py-5">
                                <span className="text-sm font-black text-slate-900">{day}/{m}</span>
                                <span className="text-[9px] font-bold text-slate-400 uppercase block leading-none">{dt.toLocaleDateString('pt-BR', {weekday: 'short'})}</span>
                              </td>
                              <td className="px-10 py-5">
                                <div className="flex flex-wrap gap-2">
                                  {dp.map((p, ix) => (
                                    <span key={ix} className="bg-white text-slate-700 text-[11px] font-black px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm">{p.time}</span>
                                  ))}
                                </div>
                              </td>
                              <td className="px-4 py-5 text-center font-black text-xs text-slate-600">
                                {mins > 0 ? `${Math.floor(mins/60)}h${(mins%60).toString().padStart(2,'0')}` : '--:--'}
                              </td>
                              <td className="px-4 py-5 text-center">
                                {dp.length % 2 !== 0 && <span title="Marcação Incompleta"><AlertOctagon className="w-5 h-5 text-red-500 mx-auto animate-pulse" /></span>}
                                {dp.length > 0 && dp.length % 2 === 0 && <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">OK</span>}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner text-center px-10">
              <Fingerprint className="w-24 h-24 opacity-10 mb-6 animate-pulse" />
              <p className="font-black uppercase text-sm tracking-[0.2em] text-slate-400">Selecione um colaborador</p>
              <p className="text-[10px] mt-2 font-bold text-slate-300 uppercase">A identificação agora é feita por transição de dígitos para letras (Parede AFD).</p>
              {store.lastImport && (
                <div className="mt-8 px-6 py-3 bg-emerald-50 rounded-2xl border border-emerald-100 flex items-center gap-3">
                  <History className="w-4 h-4 text-emerald-500" />
                  <span className="text-[10px] font-black uppercase text-emerald-700 tracking-widest">Registros Processados: {store.punches.length}</span>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  FileUp, Search, ShieldCheck, 
  IdCard, AlertOctagon, Printer, Fingerprint, History, AlertTriangle, Users
} from 'lucide-react';

// --- MODELO DE DADOS ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; // Aliases canonicalizados (sempre 12 dígitos)
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    stats: { punches: number; users: number } 
  };
};

// --- MOTOR DE PARSING SEMÂNTICO ---

const canon12 = (d: string) => d.replace(/\D/g, '').padStart(12, '0').slice(-12);

/**
 * REGEX DE CADASTRO IDCLASS (Sinal Semântico)
 * Padrão: NSR(10) + Data(8) + Hora(4) + [IAE]? + ID(\d+?) + Parede(?=[A-ZÀ-Ü]) + Nome
 */
const RX_CADASTRO_SEMANTICO = /\d{10}\d{8}\d{4}[IAE]?(\d+?)(?=[A-ZÀ-Ü])([A-ZÀ-Ü\s\-\']+)/;

/**
 * REGEX DE BATIDA (TIPO 3)
 * Padrão: NSR(10) + '3' + Data(8) + Hora(4) + [IAE]? + ID
 */
const RX_BATIDA_PADRAO = /(\d{10})3(\d{8})(\d{4})[IAE]?(\d+)/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_ponto_v16_semantico');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonId, setActivePersonId] = useState<string | null>(null);
  const [debugLines, setDebugLines] = useState<string[]>([]);

  useEffect(() => {
    localStorage.setItem('abc_ponto_v16_semantico', JSON.stringify(store));
  }, [store]);

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    setDebugLines([]);
    reader.readAsText(file, "ISO-8859-1"); 

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 20);

      const newPunches: Punch[] = [];
      const userMap = new Map<string, string>(); 
      let sampleLines: string[] = [];

      lines.forEach((raw) => {
        // 1. Tentar capturar Cadastro (Parede Dígito->Letra)
        const userMatch = raw.match(RX_CADASTRO_SEMANTICO);
        if (userMatch) {
          const id = canon12(userMatch[1]);
          const name = userMatch[2].trim().toUpperCase();
          if (name.length > 2) userMap.set(id, name);
          return;
        }

        // 2. Tentar capturar Batida
        const punchMatch = raw.match(RX_BATIDA_PADRAO);
        if (punchMatch) {
          const [, nsr, ddmmyyyy, hhmm, idRaw] = punchMatch;
          newPunches.push({
            nsr,
            dayISO: `${ddmmyyyy.slice(4, 8)}-${ddmmyyyy.slice(2, 4)}-${ddmmyyyy.slice(0, 2)}`,
            time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
            id: canon12(idRaw)
          });
        } else if (sampleLines.length < 5) {
          sampleLines.push(raw);
        }
      });

      setStore(prev => {
        const people = [...prev.people];

        // Atualiza/Cria pessoas no cadastro global
        userMap.forEach((name, id) => {
          let person = people.find(p => p.name === name);
          if (!person) {
            people.push({ name, ids: [id] });
          } else if (!person.ids.includes(id)) {
            person.ids.push(id);
          }
        });

        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const filteredNew = newPunches.filter(p => !existingNsrs.has(p.nsr));

        return {
          people,
          punches: [...prev.punches, ...filteredNew],
          lastImport: { 
            file: file.name, 
            stats: { punches: newPunches.length, users: userMap.size } 
          }
        };
      });

      if (userMap.size === 0 && newPunches.length > 0) setDebugLines(sampleLines);
    };
    event.target.value = '';
  };

  // --- LÓGICA DE FILTRAGEM DINÂMICA (PONTO-CENTRISTA) ---
  const activeEmployeesInMonth = useMemo(() => {
    // 1. Pega todos os IDs que tiveram batidas no mês selecionado
    const monthPunches = store.punches.filter(p => p.dayISO.startsWith(selectedMonth));
    const uniqueIds = Array.from(new Set(monthPunches.map(p => p.id)));

    // 2. Mapeia esses IDs para Nomes Resolvidos ou Rótulos de "Colaborador ID"
    const employees = uniqueIds.map(id => {
      const resolvedPerson = store.people.find(p => p.ids.includes(id));
      return {
        id,
        name: resolvedPerson ? resolvedPerson.name : `COLABORADOR ${id.slice(-6)}`,
        isResolved: !!resolvedPerson
      };
    });

    // 3. Aplica o filtro de busca
    return employees
      .filter(e => 
        e.name.includes(searchTerm.toUpperCase()) || 
        e.id.includes(searchTerm)
      )
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [store.punches, store.people, selectedMonth, searchTerm]);

  const activeEmployee = activeEmployeesInMonth.find(e => e.id === activePersonId);

  const punchesForDisplay = useMemo(() => {
    if (!activePersonId) return [];
    return store.punches
      .filter(p => p.id === activePersonId && p.dayISO.startsWith(selectedMonth))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));
  }, [activePersonId, store.punches, selectedMonth]);

  const statsCount = useMemo(() => ({
    total: activeEmployeesInMonth.length,
    resolved: activeEmployeesInMonth.filter(e => e.isResolved).length
  }), [activeEmployeesInMonth]);

  const calculateDayMins = (p: Punch[]) => {
    if (p.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < p.length - 1; i += 2) {
      const [h1, m1] = p[i].time.split(':').map(Number);
      const [h2, m2] = p[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  return (
    <div className="space-y-6">
      {/* HEADER DINÂMICO */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-5">
          <div className="bg-[#E30613] p-4 rounded-2xl shadow-lg">
            <ShieldCheck className="text-white w-6 h-6" />
          </div>
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter text-[#0A1121]">Folha de Ponto</h2>
            <div className="flex items-center gap-3 mt-1">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                {selectedMonth} • {statsCount.total} Ativos • {statsCount.resolved} Identificados
              </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end mr-2">
             <input 
               type="month" 
               value={selectedMonth} 
               onChange={e => { setSelectedMonth(e.target.value); setActivePersonId(null); }} 
               className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-black outline-none cursor-pointer hover:bg-white transition-all shadow-sm" 
             />
          </div>
          <label className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase cursor-pointer flex items-center gap-2 hover:bg-black transition-all shadow-xl active:scale-95">
            <FileUp className="w-4 h-4 text-[#E30613]" /> LER AFD <input type="file" className="hidden" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      {debugLines.length > 0 && (
        <div className="bg-red-50 border border-red-200 p-6 rounded-[2rem] flex items-center gap-4">
          <AlertTriangle className="w-6 h-6 text-red-500 animate-pulse" />
          <div className="flex-1">
            <p className="text-[10px] font-black text-red-900 uppercase">Atenção: Nomes não resolvidos no arquivo iDClass.</p>
            <p className="text-[9px] text-red-600 font-bold uppercase opacity-70">Verifique se as linhas de cadastro contêm a transição dígito -> letra.</p>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* LISTA LATERAL: RECONSTRUÍDA POR MÊS */}
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm min-h-[60vh] flex flex-col">
          <div className="relative mb-6">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input 
              type="text" 
              placeholder="Nome ou ID..." 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)} 
              className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-transparent focus:border-[#E30613] focus:bg-white rounded-xl text-xs font-bold outline-none transition-all" 
            />
          </div>

          <div className="flex-1 space-y-2 overflow-y-auto pr-2 custom-scrollbar">
            {activeEmployeesInMonth.length === 0 ? (
              <div className="py-24 text-center">
                <Fingerprint className="w-10 h-10 mx-auto mb-3 text-slate-100" />
                <p className="text-[10px] font-black uppercase text-slate-300 tracking-widest">Sem batidas no período</p>
              </div>
            ) : (
              activeEmployeesInMonth.map(e => (
                <button 
                  key={e.id} 
                  onClick={() => setActivePersonId(e.id)} 
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonId === e.id ? 'bg-[#0A1121] text-white border-[#0A1121] shadow-lg' : 'bg-slate-50 border-transparent hover:bg-slate-100 text-slate-600'}`}
                >
                  <div className="flex justify-between items-start">
                    <p className="text-[10px] font-black uppercase truncate leading-tight flex-1">{e.name}</p>
                    {!e.isResolved && <AlertOctagon className="w-3 h-3 text-red-500 ml-2" />}
                  </div>
                  <p className={`text-[8px] mt-1 font-bold ${activePersonId === e.id ? 'text-slate-400' : 'text-slate-400'}`}>ID: {e.id}</p>
                </button>
              ))
            )}
          </div>
        </div>

        {/* ESPELHO DE PONTO */}
        <div className="lg:col-span-3">
          {activeEmployee ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
               <div className="bg-white border rounded-[2.5rem] p-8 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center border border-slate-100 shadow-sm">
                       <IdCard className={`${activeEmployee.isResolved ? 'text-emerald-500' : 'text-[#E30613]'} w-8 h-8`} />
                     </div>
                     <div>
                        <h3 className="text-xl font-black uppercase text-slate-900 leading-none">{activeEmployee.name}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-2 tracking-widest">Canônico: {activeEmployee.id}</p>
                     </div>
                  </div>
                  <button onClick={() => window.print()} className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 hover:bg-black transition-all shadow-xl active:scale-95">
                    <Printer className="w-4 h-4 text-[#E30613]" /> Imprimir Espelho
                  </button>
               </div>

               <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                  <table className="w-full text-left border-collapse">
                    <thead className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-10 py-6">Data / Dia</th>
                        <th className="px-10 py-6">Marcações AFD</th>
                        <th className="px-4 py-6 text-center">Horas</th>
                        <th className="px-4 py-6 text-center">Auditoria</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {(() => {
                        const [y, m] = selectedMonth.split('-');
                        const days = new Date(Number(y), Number(m), 0).getDate();
                        return Array.from({length: days}, (_, i) => {
                          const day = (i+1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dp = punchesForDisplay.filter(p => p.dayISO === iso);
                          const mins = calculateDayMins(dp);
                          const dt = new Date(iso + 'T12:00:00');
                          const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                          return (
                            <tr key={iso} className={`group hover:bg-slate-50 transition-all ${dp.length === 0 ? 'opacity-30' : ''} ${isWeekend ? 'bg-slate-50/20' : ''}`}>
                              <td className="px-10 py-5">
                                <span className="text-sm font-black text-slate-900">{day}/{m}</span>
                                <span className="text-[9px] font-bold text-slate-400 uppercase block leading-none">{dt.toLocaleDateString('pt-BR', {weekday: 'short'})}</span>
                              </td>
                              <td className="px-10 py-5">
                                <div className="flex flex-wrap gap-2">
                                  {dp.map((p, ix) => (
                                    <span key={ix} className="bg-white text-slate-700 text-[11px] font-black px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm" title={`NSR: ${p.nsr}`}>{p.time}</span>
                                  ))}
                                </div>
                              </td>
                              <td className="px-4 py-5 text-center font-black text-xs text-slate-600">
                                {mins > 0 ? `${Math.floor(mins/60)}h${(mins%60).toString().padStart(2,'0')}` : '--:--'}
                              </td>
                              <td className="px-4 py-5 text-center">
                                {dp.length % 2 !== 0 && dp.length > 0 && <span title="Ponto Impar"><AlertOctagon className="w-5 h-5 text-red-500 mx-auto animate-pulse" /></span>}
                                {dp.length > 0 && dp.length % 2 === 0 && <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">OK</span>}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner text-center px-10">
              <Users className="w-24 h-24 opacity-10 mb-6" />
              <p className="font-black uppercase text-sm tracking-[0.2em] text-slate-400">Auditoria Mensal: {selectedMonth}</p>
              <p className="text-[10px] mt-2 font-bold text-slate-300 uppercase">Selecione um colaborador à esquerda para abrir o espelho.</p>
              {store.lastImport && (
                <div className="mt-8 px-6 py-3 bg-slate-900 rounded-2xl flex items-center gap-3">
                  <History className="w-4 h-4 text-[#E30613]" />
                  <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Base: {store.punches.length} registros no sistema</span>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  FileUp, Search, ShieldCheck, 
  IdCard, AlertOctagon, Printer, Fingerprint, History, AlertTriangle, Users, Database
} from 'lucide-react';

// --- MODELO DE DADOS ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; // Aliases canonicalizados (sempre 12 dígitos)
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    stats: { punches: number; users: number } 
  };
};

// --- MOTOR DE PARSING SEMÂNTICO (iDClass Robust) ---

const canon12 = (d: string) => d.replace(/\D/g, '').padStart(12, '0').slice(-12);

// Regex foca na estrutura de dados, ignorando posições fixas de tipo
// Padrão iDClass: NSR(10) + Data(8) + Hora(4) + [IAE] + ID + Nome (Parede Letra)
const RX_CADASTRO = /\d{10}(\d{8})(\d{4})[IAE]?(\d+?)(?=[A-ZÀ-Ü])([A-ZÀ-Ü\s\-\']+)/;

// Padrão iDClass Batida: NSR(10) + '3' + Data(8) + Hora(4) + ID
const RX_BATIDA = /(\d{10})3(\d{8})(\d{4})[IAE]?(\d+)/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_ponto_v17_fix');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [activePersonId, setActivePersonId] = useState<string | null>(null);
  const [debugLines, setDebugLines] = useState<string[]>([]);

  useEffect(() => {
    localStorage.setItem('abc_ponto_v17_fix', JSON.stringify(store));
  }, [store]);

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    setDebugLines([]);
    reader.readAsText(file, "ISO-8859-1"); 

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 20);

      const newPunches: Punch[] = [];
      const userMap = new Map<string, string>(); 
      let sampleLines: string[] = [];

      lines.forEach((raw) => {
        // 1. Tentar Cadastro
        const userMatch = raw.match(RX_CADASTRO);
        if (userMatch) {
          const id = canon12(userMatch[3]);
          const name = userMatch[4].trim().toUpperCase();
          if (name.length > 2) userMap.set(id, name);
          return;
        }

        // 2. Tentar Batida
        const punchMatch = raw.match(RX_BATIDA);
        if (punchMatch) {
          const [, nsr, ddmmyyyy, hhmm, idRaw] = punchMatch;

          // CORREÇÃO CRÍTICA: DDMMYYYY -> YYYY-MM-DD
          const day = ddmmyyyy.slice(0, 2);
          const month = ddmmyyyy.slice(2, 4);
          const year = ddmmyyyy.slice(4, 8);
          const dayISO = `${year}-${month}-${day}`;

          newPunches.push({
            nsr,
            dayISO,
            time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
            id: canon12(idRaw)
          });
        } else if (sampleLines.length < 5 && raw.length > 30) {
          sampleLines.push(raw);
        }
      });

      // LOG DE DIAGNÓSTICO OBRIGATÓRIO
      if (newPunches.length > 0) {
        const first = newPunches[0];
        console.log("--- DIAGNÓSTICO AFD ---");
        console.log("Amostra dayISO:", first.dayISO);
        console.log("Mês Selecionado:", selectedMonth);
        console.log("Match Mês?:", first.dayISO.startsWith(selectedMonth));
        console.log("Total Lidos:", newPunches.length);
      }

      setStore(prev => {
        const people = [...prev.people];
        userMap.forEach((name, id) => {
          let person = people.find(p => p.name === name);
          if (!person) {
            people.push({ name, ids: [id] });
          } else if (!person.ids.includes(id)) {
            person.ids.push(id);
          }
        });

        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const filteredNew = newPunches.filter(p => !existingNsrs.has(p.nsr));

        return {
          people,
          punches: [...prev.punches, ...filteredNew],
          lastImport: { 
            file: file.name, 
            stats: { punches: newPunches.length, users: userMap.size } 
          }
        };
      });

      if (userMap.size === 0 && newPunches.length > 0) setDebugLines(sampleLines);
    };
    event.target.value = '';
  };

  // --- LÓGICA DE FILTRAGEM DINÂMICA (PONTO-CENTRISTA) ---
  const auditData = useMemo(() => {
    // 1. Filtrar batidas do mês selecionado
    const punchesInMonth = store.punches.filter(p => p.dayISO.startsWith(selectedMonth));
    const uniqueIdsInMonth = Array.from(new Set(punchesInMonth.map(p => p.id)));

    // 2. Construir lista de funcionários ativos NESTE mês
    const employees = uniqueIdsInMonth.map(id => {
      const person = store.people.find(p => p.ids.includes(id));
      return {
        id,
        name: person ? person.name : `COLABORADOR ${id.slice(-6)}`,
        isResolved: !!person
      };
    });

    // 3. Filtrar por termo de busca
    const filtered = employees
      .filter(e => e.name.includes(searchTerm.toUpperCase()) || e.id.includes(searchTerm))
      .sort((a, b) => a.name.localeCompare(b.name));

    return {
      employees: filtered,
      stats: {
        totalGlobal: store.punches.length,
        idsGlobal: new Set(store.punches.map(p => p.id)).size,
        punchesInMonth: punchesInMonth.length,
        idsInMonth: uniqueIdsInMonth.length,
        resolvedInMonth: filtered.filter(e => e.isResolved).length
      }
    };
  }, [store, selectedMonth, searchTerm]);

  const activeEmployee = auditData.employees.find(e => e.id === activePersonId);

  const punchesForDisplay = useMemo(() => {
    if (!activePersonId) return [];
    return store.punches
      .filter(p => p.id === activePersonId && p.dayISO.startsWith(selectedMonth))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));
  }, [activePersonId, store.punches, selectedMonth]);

  const calculateDayMins = (p: Punch[]) => {
    if (p.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < p.length - 1; i += 2) {
      const [h1, m1] = p[i].time.split(':').map(Number);
      const [h2, m2] = p[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  return (
    <div className="space-y-6">
      {/* HEADER DE DIAGNÓSTICO */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-5">
          <div className="bg-[#E30613] p-4 rounded-2xl shadow-lg">
            <ShieldCheck className="text-white w-6 h-6" />
          </div>
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter text-[#0A1121]">Folha de Ponto</h2>
            <div className="flex items-center gap-3 mt-1">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-50 px-3 py-1 rounded-full border border-slate-100">
                {selectedMonth} • {auditData.stats.idsInMonth} Ativos no Mês • {auditData.stats.punchesInMonth} Batidas
              </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end mr-2">
             <input 
               type="month" 
               value={selectedMonth} 
               onChange={e => { setSelectedMonth(e.target.value); setActivePersonId(null); }} 
               className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-black outline-none cursor-pointer hover:bg-white transition-all shadow-sm" 
             />
          </div>
          <label className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase cursor-pointer flex items-center gap-2 hover:bg-black transition-all shadow-xl active:scale-95">
            <FileUp className="w-4 h-4 text-[#E30613]" /> LER AFD <input type="file" className="hidden" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      {/* PAINEL DE INTEGRIDADE DE DADOS */}
      {store.punches.length > 0 && auditData.stats.punchesInMonth === 0 && (
        <div className="bg-amber-50 border border-amber-200 p-8 rounded-[2.5rem] flex items-center gap-6 animate-pulse">
           <AlertTriangle className="w-10 h-10 text-amber-500 shrink-0" />
           <div>
              <p className="text-xs font-black text-amber-900 uppercase tracking-widest">Inconsistência de Filtro Detectada</p>
              <p className="text-[10px] font-bold text-amber-700 uppercase mt-1 leading-relaxed">
                O banco contém {auditData.stats.totalGlobal} batidas globais, mas ZERO no mês {selectedMonth}. 
                Isso indica que o formato de data do arquivo não condiz com o filtro selecionado.
              </p>
           </div>
           <div className="ml-auto bg-white p-4 rounded-2xl border border-amber-100 text-[10px] font-mono text-amber-800">
              Amostra no Banco: {store.punches[0].dayISO}
           </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* LISTA LATERAL DINÂMICA */}
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm min-h-[60vh] flex flex-col">
          <div className="relative mb-6">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input 
              type="text" 
              placeholder="Filtrar Nome/ID..." 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)} 
              className="w-full pl-10 pr-4 py-3 bg-slate-50 border rounded-xl text-xs font-bold outline-none" 
            />
          </div>

          <div className="flex-1 space-y-2 overflow-y-auto pr-2 custom-scrollbar">
            {auditData.employees.length === 0 ? (
              <div className="py-24 text-center">
                <Fingerprint className="w-10 h-10 mx-auto mb-3 text-slate-100" />
                <p className="text-[10px] font-black uppercase text-slate-300 tracking-widest italic">Nenhum ponto batido neste mês</p>
              </div>
            ) : (
              auditData.employees.map(e => (
                <button 
                  key={e.id} 
                  onClick={() => setActivePersonId(e.id)} 
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonId === e.id ? 'bg-[#0A1121] text-white border-[#0A1121] shadow-lg' : 'bg-slate-50 border-transparent hover:bg-slate-100 text-slate-600'}`}
                >
                  <div className="flex justify-between items-start">
                    <p className="text-[10px] font-black uppercase truncate leading-tight flex-1">{e.name}</p>
                    {!e.isResolved && <AlertOctagon className="w-3 h-3 text-red-500 ml-2" />}
                  </div>
                  <p className={`text-[8px] mt-1 font-bold ${activePersonId === e.id ? 'text-slate-400' : 'text-slate-400'}`}>ID: {e.id}</p>
                </button>
              ))
            )}
          </div>

          <div className="mt-4 pt-4 border-t border-slate-100 flex items-center justify-between text-[8px] font-black text-slate-400 uppercase tracking-widest">
             <div className="flex items-center gap-1"><Database className="w-3 h-3" /> {auditData.stats.totalGlobal} Global</div>
             <div className="flex items-center gap-1"><Users className="w-3 h-3" /> {auditData.stats.idsInMonth} Ativos</div>
          </div>
        </div>

        {/* ESPELHO DE PONTO */}
        <div className="lg:col-span-3">
          {activeEmployee ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
