import React, { useState, useMemo, useEffect } from 'react';
import { 
  FileUp, Search, ShieldCheck, 
  IdCard, AlertOctagon, Printer, Fingerprint, History, AlertTriangle, Users, Database, CalendarRange
} from 'lucide-react';

// --- MODELO DE DADOS ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; // Aliases canonicalizados (sempre 12 dígitos)
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    stats: { punches: number; users: number; range: string } 
  };
};

// --- MOTOR DE PARSING SEMÂNTICO ---

const canon12 = (d: string) => d.replace(/\D/g, '').padStart(12, '0').slice(-12);

// iDClass: NSR(10) + Data(8) + Hora(4) + [IAE] + ID + Nome (Parede Letra)
const RX_CADASTRO = /\d{10}(\d{8})(\d{4})[IAE]?(\d+?)(?=[A-ZÀ-Ü])([A-ZÀ-Ü\s\-\']+)/;

// iDClass Batida: NSR(10) + '3' + Data(8) + Hora(4) + ID
const RX_BATIDA = /(\d{10})3(\d{8})(\d{4})[IAE]?(\d+)/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_ponto_v18_ux');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
  const [activePersonId, setActivePersonId] = useState<string | null>(null);
  const [debugLines, setDebugLines] = useState<string[]>([]);

  useEffect(() => {
    localStorage.setItem('abc_ponto_v18_ux', JSON.stringify(store));
  }, [store]);

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    setDebugLines([]);
    reader.readAsText(file, "ISO-8859-1"); 

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 20);

      const newPunches: Punch[] = [];
      const userMap = new Map<string, string>(); 
      const foundMonths = new Set<string>();

      lines.forEach((raw) => {
        const userMatch = raw.match(RX_CADASTRO);
        if (userMatch) {
          const id = canon12(userMatch[3]);
          const name = userMatch[4].trim().toUpperCase();
          if (name.length > 2) userMap.set(id, name);
          return;
        }

        const punchMatch = raw.match(RX_BATIDA);
        if (punchMatch) {
          const [, nsr, ddmmyyyy, hhmm, idRaw] = punchMatch;
          const day = ddmmyyyy.slice(0, 2);
          const month = ddmmyyyy.slice(2, 4);
          const year = ddmmyyyy.slice(4, 8);
          const dayISO = `${year}-${month}-${day}`;

          foundMonths.add(`${year}-${month}`);
          newPunches.push({
            nsr,
            dayISO,
            time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
            id: canon12(idRaw)
          });
        }
      });

      // AUTO-AJUSTE DE MÊS: Se o mês atual está vazio mas o arquivo tem dados, pula para o mês mais recente do arquivo
      if (newPunches.length > 0) {
        const sortedMonths = Array.from(foundMonths).sort();
        const latestMonthInFile = sortedMonths[sortedMonths.length - 1];

        // Verifica se no mês selecionado atual haverá batidas após o merge
        const willHaveData = newPunches.some(p => p.dayISO.startsWith(selectedMonth)) || 
                             store.punches.some(p => p.dayISO.startsWith(selectedMonth));

        if (!willHaveData) {
          setSelectedMonth(latestMonthInFile);
          console.log(`Auto-ajuste: Mudando filtro para ${latestMonthInFile} pois o arquivo não contém dados para ${selectedMonth}`);
        }
      }

      setStore(prev => {
        const people = [...prev.people];
        userMap.forEach((name, id) => {
          let person = people.find(p => p.name === name);
          if (!person) {
            people.push({ name, ids: [id] });
          } else if (!person.ids.includes(id)) {
            person.ids.push(id);
          }
        });

        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const filteredNew = newPunches.filter(p => !existingNsrs.has(p.nsr));
        const allPunches = [...prev.punches, ...filteredNew];

        // Calcular range total do banco
        const allDays = allPunches.map(p => p.dayISO).sort();
        const range = allDays.length > 0 ? 
          `${allDays[0].slice(5,7)}/${allDays[0].slice(0,4)} até ${allDays[allDays.length-1].slice(5,7)}/${allDays[allDays.length-1].slice(0,4)}` : 
          "N/A";

        return {
          people,
          punches: allPunches,
          lastImport: { 
            file: file.name, 
            stats: { punches: newPunches.length, users: userMap.size, range } 
          }
        };
      });
    };
    event.target.value = '';
  };

  const auditData = useMemo(() => {
    const punchesInMonth = store.punches.filter(p => p.dayISO.startsWith(selectedMonth));
    const uniqueIdsInMonth = Array.from(new Set(punchesInMonth.map(p => p.id)));

    const employees = uniqueIdsInMonth.map(id => {
      const person = store.people.find(p => p.ids.includes(id));
      return {
        id,
        name: person ? person.name : `COLABORADOR ${id.slice(-6)}`,
        isResolved: !!person
      };
    });

    const filtered = employees
      .filter(e => e.name.includes(searchTerm.toUpperCase()) || e.id.includes(searchTerm))
      .sort((a, b) => a.name.localeCompare(b.name));

    return {
      employees: filtered,
      stats: {
        totalGlobal: store.punches.length,
        punchesInMonth: punchesInMonth.length,
        idsInMonth: uniqueIdsInMonth.length,
      }
    };
  }, [store, selectedMonth, searchTerm]);

  const activeEmployee = auditData.employees.find(e => e.id === activePersonId);
  const punchesForDisplay = useMemo(() => {
    if (!activePersonId) return [];
    return store.punches
      .filter(p => p.id === activePersonId && p.dayISO.startsWith(selectedMonth))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));
  }, [activePersonId, store.punches, selectedMonth]);

  const calculateDayMins = (p: Punch[]) => {
    if (p.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < p.length - 1; i += 2) {
      const [h1, m1] = p[i].time.split(':').map(Number);
      const [h2, m2] = p[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  return (
    <div className="space-y-6">
      {/* HEADER DE DIAGNÓSTICO */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-5">
          <div className="bg-[#E30613] p-4 rounded-2xl shadow-lg">
            <ShieldCheck className="text-white w-6 h-6" />
          </div>
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter text-[#0A1121]">Folha de Ponto</h2>
            <div className="flex items-center gap-3 mt-1">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-50 px-3 py-1 rounded-full border border-slate-100">
                {selectedMonth} • {auditData.stats.idsInMonth} Ativos no Mês
              </span>
              {store.lastImport && (
                <span className="text-[9px] font-black text-emerald-600 uppercase tracking-widest flex items-center gap-1">
                   <CalendarRange className="w-3 h-3" /> Janela: {store.lastImport.stats.range}
                </span>
              )}
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <input 
            type="month" 
            value={selectedMonth} 
            onChange={e => { setSelectedMonth(e.target.value); setActivePersonId(null); }} 
            className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-black outline-none cursor-pointer hover:bg-white transition-all shadow-sm" 
          />
          <label className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase cursor-pointer flex items-center gap-2 hover:bg-black transition-all shadow-xl active:scale-95">
            <FileUp className="w-4 h-4 text-[#E30613]" /> LER AFD <input type="file" className="hidden" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      {/* AVISO DE CONTEXTO TEMPORAL */}
      {store.punches.length > 0 && auditData.stats.punchesInMonth === 0 && (
        <div className="bg-amber-50 border border-amber-200 p-8 rounded-[2.5rem] flex items-center gap-6">
           <AlertTriangle className="w-10 h-10 text-amber-500 shrink-0" />
           <div className="flex-1">
              <p className="text-xs font-black text-amber-900 uppercase tracking-widest leading-none">Mês sem marcações</p>
              <p className="text-[10px] font-bold text-amber-700 uppercase mt-2 leading-relaxed">
                Você está filtrando o mês <span className="underline">{selectedMonth}</span>, mas seu arquivo contém registros de <span className="font-black text-amber-900">{store.lastImport?.stats.range}</span>. 
                Selecione um mês válido acima para visualizar os colaboradores.
              </p>
           </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* LISTA LATERAL */}
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm min-h-[60vh] flex flex-col">
          <div className="relative mb-6">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input 
              type="text" 
              placeholder="Buscar por Nome ou ID..." 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)} 
              className="w-full pl-10 pr-4 py-3 bg-slate-50 border rounded-xl text-xs font-bold outline-none" 
            />
          </div>

          <div className="flex-1 space-y-2 overflow-y-auto pr-2 custom-scrollbar">
            {auditData.employees.length === 0 ? (
              <div className="py-24 text-center opacity-40">
                <Fingerprint className="w-10 h-10 mx-auto mb-3 text-slate-200" />
                <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Nada para {selectedMonth}</p>
              </div>
            ) : (
              auditData.employees.map(e => (
                <button 
                  key={e.id} 
                  onClick={() => setActivePersonId(e.id)} 
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonId === e.id ? 'bg-[#0A1121] text-white border-[#0A1121] shadow-lg' : 'bg-slate-50 border-transparent hover:bg-slate-100 text-slate-600'}`}
                >
                  <div className="flex justify-between items-start">
                    <p className="text-[10px] font-black uppercase truncate leading-tight flex-1">{e.name}</p>
                    {!e.isResolved && <AlertOctagon className="w-3 h-3 text-red-500 ml-2" />}
                  </div>
                  <p className={`text-[8px] mt-1 font-bold ${activePersonId === e.id ? 'text-slate-400' : 'text-slate-400'}`}>ID: {e.id}</p>
                </button>
              ))
            )}
          </div>

          <div className="mt-4 pt-4 border-t border-slate-100 flex items-center justify-between text-[8px] font-black text-slate-400 uppercase tracking-widest">
             <div className="flex items-center gap-1"><Database className="w-3 h-3" /> {auditData.stats.totalGlobal} Batidas</div>
             <div className="flex items-center gap-1"><Users className="w-3 h-3" /> {auditData.stats.idsInMonth} no Filtro</div>
          </div>
        </div>

        {/* ESPELHO DE PONTO */}
        <div className="lg:col-span-3">
          {activeEmployee ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
               <div className="bg-white border rounded-[2.5rem] p-8 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center border border-slate-100 shadow-sm">
                       <IdCard className={`${activeEmployee.isResolved ? 'text-emerald-500' : 'text-[#E30613]'} w-8 h-8`} />
                     </div>
                     <div>
                        <h3 className="text-xl font-black uppercase text-slate-900 leading-none">{activeEmployee.name}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-2 tracking-widest">Identificação: {activeEmployee.id}</p>
                     </div>
                  </div>
                  <button onClick={() => window.print()} className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 hover:bg-black transition-all shadow-xl active:scale-95">
