      lines.forEach((raw) => {
        // 1. Tentar Cadastro (Extrair Nomes)
        const userMatch = raw.match(RX_CADASTRO);
        if (userMatch) {
          const id = canon12(userMatch[3]);
          const name = userMatch[4].trim().toUpperCase();
          if (name.length > 2) userMap.set(id, name);
          return;
        }

        // 2. Tentar Batida (Tipo 3)
        const punchMatch = raw.match(RX_BATIDA);
        if (punchMatch) {
          const [, nsr, ddmmyyyy, hhmm, idRaw] = punchMatch;

          // REGRA DE OURO: Fatiamento explícito DD-MM-YYYY -> YYYY-MM-DD
          const day = ddmmyyyy.slice(0, 2);
          const month = ddmmyyyy.slice(2, 4);
          const year = ddmmyyyy.slice(4, 8);
          const dayISO = `${year}-${month}-${day}`;

          foundMonths.add(`${year}-${month}`);
          newPunches.push({
            nsr,
            dayISO,
            time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
            id: canon12(idRaw)
          });
        }
      });

      // LOG DE DIAGNÓSTICO OBRIGATÓRIO (Amostragem de 3 batidas)
      if (newPunches.length > 0) {
        console.group("DIAGNÓSTICO AFD iDClass");
        newPunches.slice(0, 3).forEach((p, idx) => {
          console.log(`Amostra ${idx+1}: dayISO=${p.dayISO} | monthFilter=${selectedMonth} | MATCH=${p.dayISO.startsWith(selectedMonth)}`);
        });
        console.groupEnd();
      }

      // AUTO-AJUSTE: Se o filtro atual não tem dados, mas o arquivo tem, muda para o mês mais recente do arquivo
      let targetMonth = selectedMonth;
      if (newPunches.length > 0) {
        const sortedFound = Array.from(foundMonths).sort();
        const latestInFile = sortedFound[sortedFound.length - 1];
        const currentHasData = newPunches.some(p => p.dayISO.startsWith(selectedMonth));

        if (!currentHasData) {
          targetMonth = latestInFile;
          setSelectedMonth(latestInFile);
        }
      }

      setStore(prev => {
        const people = [...prev.people];

        // Atualiza Cadastro de Nomes
        userMap.forEach((name, id) => {
          let person = people.find(p => p.name === name);
          if (!person) {
            people.push({ name, ids: [id] });
          } else if (!person.ids.includes(id)) {
            person.ids.push(id);
          }
        });

        // Mescla Batidas (Evita duplicados pelo NSR)
        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const filteredNew = newPunches.filter(p => !existingNsrs.has(p.nsr));
        const allPunches = [...prev.punches, ...filteredNew];

        // Calcula a Janela Temporal Real do Banco
        const allDates = allPunches.map(p => p.dayISO).sort();
        const range = allDates.length > 0 ? 
          `${allDates[0].split('-').reverse().slice(0,2).join('/')} a ${allDates[allDates.length-1].split('-').reverse().slice(0,2).join('/')}` : 
          "N/A";

        return {
          people,
          punches: allPunches,
          lastImport: { 
            file: file.name, 
            stats: { punches: newPunches.length, users: userMap.size, range } 
          }
        };
      });
    };
    event.target.value = '';
  };

  /**
   * RECONSTRUÇÃO DA LISTA LATERAL (Ponto-Centrista)
   * A lista agora depende das BATIDAS do mês, não do cadastro global.
   */
  const auditData = useMemo(() => {
    // 1. Filtra as batidas do mês selecionado
    const punchesInSelectedMonth = store.punches.filter(p => p.dayISO.startsWith(selectedMonth));

    // 2. Extrai IDs únicos que realmente bateram ponto
    const uniqueIdsThisMonth = Array.from(new Set(punchesInSelectedMonth.map(p => p.id)));

    // 3. Resolve nomes ou cria placeholders
    const employees = uniqueIdsThisMonth.map(id => {
      const person = store.people.find(p => p.ids.includes(id));
      return {
        id,
        name: person ? person.name : `COLABORADOR ${id.slice(-6)}`,
        isResolved: !!person
      };
    });

    // 4. Aplica busca e ordena
    const filtered = employees
      .filter(e => e.name.includes(searchTerm.toUpperCase()) || e.id.includes(searchTerm))
      .sort((a, b) => a.name.localeCompare(b.name));

    return {
      employees: filtered,
      stats: {
        totalGlobal: store.punches.length,
        uniqueIdsTotal: new Set(store.punches.map(p => p.id)).size,
        punchesInMonth: punchesInSelectedMonth.length,
        uniqueIdsInMonth: uniqueIdsThisMonth.length,
        resolvedInMonth: filtered.filter(e => e.isResolved).length
      }
    };
  }, [store, selectedMonth, searchTerm]);

  const activeEmployee = auditData.employees.find(e => e.id === activePersonId);
  const punchesForDisplay = useMemo(() => {
    if (!activePersonId) return [];
    return store.punches
      .filter(p => p.id === activePersonId && p.dayISO.startsWith(selectedMonth))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));
  }, [activePersonId, store.punches, selectedMonth]);

  const calculateDayMins = (p: Punch[]) => {
    if (p.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < p.length - 1; i += 2) {
      const [h1, m1] = p[i].time.split(':').map(Number);
      const [h2, m2] = p[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  return (
    <div className="space-y-6">
      {/* HEADER DE COMANDO */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-5">
          <div className="bg-[#E30613] p-4 rounded-2xl shadow-lg">
            <ShieldCheck className="text-white w-6 h-6" />
          </div>
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter text-[#0A1121]">Folha de Ponto</h2>
            <div className="flex flex-wrap items-center gap-3 mt-1">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-50 px-3 py-1 rounded-full border border-slate-100">
                {selectedMonth} • {auditData.stats.uniqueIdsInMonth} Colaboradores Ativos
              </span>
              {store.lastImport && (
                <span className="text-[9px] font-black text-emerald-600 uppercase tracking-widest flex items-center gap-1">
                   <CalendarRange className="w-3 h-3" /> Intervalo: {store.lastImport.stats.range}
                </span>
              )}
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <input 
            type="month" 
            value={selectedMonth} 
            onChange={e => { setSelectedMonth(e.target.value); setActivePersonId(null); }} 
            className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-black outline-none cursor-pointer hover:bg-white transition-all shadow-sm" 
          />
          <label className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase cursor-pointer flex items-center gap-2 hover:bg-black transition-all shadow-xl active:scale-95">
            <FileUp className="w-4 h-4 text-[#E30613]" /> LER AFD <input type="file" className="hidden" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      {/* PAINEL DE DIAGNÓSTICO (Aparece em caso de inconsistência) */}
      {store.punches.length > 0 && auditData.stats.punchesInMonth === 0 && (
        <div className="bg-amber-50 border border-amber-200 p-8 rounded-[2.5rem] flex flex-col md:flex-row items-center gap-6 animate-in fade-in zoom-in duration-300">
           <AlertTriangle className="w-12 h-12 text-amber-500 shrink-0" />
           <div className="flex-1 text-center md:text-left">
              <p className="text-sm font-black text-amber-950 uppercase tracking-tighter">Filtro Temporal Vazio</p>
              <p className="text-[11px] font-medium text-amber-800 uppercase mt-1">
                A base global tem <span className="font-black underline">{auditData.stats.totalGlobal}</span> batidas, mas no mês <span className="font-black text-amber-950 underline">{selectedMonth}</span> não há registros.
                Tente selecionar meses dentro do intervalo: <span className="bg-white px-2 py-0.5 rounded border border-amber-200 font-black">{store.lastImport?.stats.range}</span>.
              </p>
           </div>
           <div className="flex flex-col items-center gap-2 bg-white px-6 py-4 rounded-2xl border border-amber-100 shadow-sm">
              <Database className="w-5 h-5 text-slate-300" />
              <div className="text-center">
                 <p className="text-[8px] font-black text-slate-400 uppercase">Batidas Totais</p>
                 <p className="text-xs font-black text-slate-900">{auditData.stats.totalGlobal}</p>
              </div>
           </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* LISTA LATERAL (IDs ÚNICOS DO MÊS) */}
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm min-h-[60vh] flex flex-col">
          <div className="relative mb-6">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input 
              type="text" 
              placeholder="Nome ou ID no mês..." 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)} 
              className="w-full pl-10 pr-4 py-3 bg-slate-50 border rounded-xl text-xs font-bold outline-none" 
            />
          </div>

          <div className="flex-1 space-y-2 overflow-y-auto pr-2 custom-scrollbar">
            {auditData.employees.length === 0 ? (
              <div className="py-24 text-center opacity-40">
                <Fingerprint className="w-10 h-10 mx-auto mb-3 text-slate-200" />
                <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Sem ativos em {selectedMonth}</p>
              </div>
            ) : (
              auditData.employees.map(e => (
                <button 
                  key={e.id} 
                  onClick={() => setActivePersonId(e.id)} 
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonId === e.id ? 'bg-[#0A1121] text-white border-[#0A1121] shadow-lg scale-[1.02]' : 'bg-slate-50 border-transparent hover:bg-slate-100 text-slate-600'}`}
                >
                  <div className="flex justify-between items-start">
                    <p className="text-[10px] font-black uppercase truncate leading-tight flex-1">{e.name}</p>
                    {!e.isResolved && <AlertOctagon className="w-3 h-3 text-red-500 ml-2 animate-pulse" />}
                  </div>
                  <p className={`text-[8px] mt-1 font-bold ${activePersonId === e.id ? 'text-slate-400' : 'text-slate-400'}`}>ID: {e.id}</p>
                </button>
              ))
            )}
          </div>

          <div className="mt-4 pt-4 border-t border-slate-100 space-y-2">
             <div className="flex items-center justify-between text-[8px] font-black text-slate-400 uppercase tracking-widest">
                <span>IDs Resolvidas</span>
                <span>{auditData.stats.resolvedInMonth} / {auditData.stats.uniqueIdsInMonth}</span>
             </div>
             <div className="w-full h-1 bg-slate-50 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-emerald-500 transition-all duration-700" 
                  style={{ width: `${(auditData.stats.resolvedInMonth / auditData.stats.uniqueIdsInMonth) * 100}%` }}
                />
             </div>
          </div>
        </div>

        {/* ESPELHO DE PONTO */}
        <div className="lg:col-span-3">
          {activeEmployee ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
               <div className="bg-white border rounded-[2.5rem] p-8 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center border border-slate-100 shadow-sm">
                       <IdCard className={`${activeEmployee.isResolved ? 'text-emerald-500' : 'text-[#E30613]'} w-8 h-8`} />
                     </div>
                     <div>
                        <h3 className="text-xl font-black uppercase text-slate-900 leading-none">{activeEmployee.name}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-2 tracking-widest">Ponto ID: {activeEmployee.id}</p>
                     </div>
                  </div>
                  <button onClick={() => window.print()} className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 hover:bg-black transition-all shadow-xl active:scale-95">
                    <Printer className="w-4 h-4 text-[#E30613]" /> Imprimir Espelho
                  </button>
               </div>

               <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                  <table className="w-full text-left border-collapse">
                    <thead className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-10 py-6 border-r border-slate-800/50">Data / Dia</th>
                        <th className="px-10 py-6">Marcações (AFD)</th>
                        <th className="px-4 py-6 text-center">Horas</th>
                        <th className="px-4 py-6 text-center">Auditoria</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {(() => {
                        const [y, m] = selectedMonth.split('-');
                        const days = new Date(Number(y), Number(m), 0).getDate();
                        return Array.from({length: days}, (_, i) => {
                          const day = (i+1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dp = punchesForDisplay.filter(p => p.dayISO === iso);
                          const mins = calculateDayMins(dp);
                          const dt = new Date(iso + 'T12:00:00');
                          const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                          return (
                            <tr key={iso} className={`group hover:bg-slate-50 transition-all ${dp.length === 0 ? 'opacity-30' : ''} ${isWeekend ? 'bg-slate-50/20' : ''}`}>
                              <td className="px-10 py-5 border-r border-slate-50">
                                <span className="text-sm font-black text-slate-900">{day}/{m}</span>
                                <span className="text-[9px] font-bold text-slate-400 uppercase block leading-none">{dt.toLocaleDateString('pt-BR', {weekday: 'short'})}</span>
                              </td>
                              <td className="px-10 py-5">
                                <div className="flex flex-wrap gap-2">
                                  {dp.map((p, ix) => (
                                    <span key={ix} className="bg-white text-slate-700 text-[11px] font-black px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm" title={`NSR: ${p.nsr}`}>{p.time}</span>
                                  ))}
                                </div>
                              </td>
                              <td className="px-4 py-5 text-center font-black text-xs text-slate-600">
                                {mins > 0 ? `${Math.floor(mins/60)}h${(mins%60).toString().padStart(2,'0')}` : '--:--'}
                              </td>
                              <td className="px-4 py-5 text-center">
                                {dp.length % 2 !== 0 && dp.length > 0 && <span title="Ponto Ímpar"><AlertOctagon className="w-5 h-5 text-red-500 mx-auto animate-pulse" /></span>}
                                {dp.length > 0 && dp.length % 2 === 0 && <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">OK</span>}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner text-center px-10">
              <Users className="w-24 h-24 opacity-10 mb-6" />
              <p className="font-black uppercase text-sm tracking-[0.2em] text-slate-400">Auditoria Mensal: {selectedMonth}</p>
              <p className="text-[10px] mt-2 font-bold text-slate-300 uppercase">Selecione um colaborador na lista ao lado para carregar os registros.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  FileUp, Search, ShieldCheck, 
  IdCard, AlertOctagon, Printer, Fingerprint, History, AlertTriangle, Users, Database, CalendarRange, Info
} from 'lucide-react';

// --- MODELO DE DADOS ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; // Aliases canonicalizados (12 dígitos)
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    stats: { punches: number; users: number; range: string } 
  };
};

// --- MOTOR DE PARSING ---

const canon12 = (d: string) => d.replace(/\D/g, '').padStart(12, '0').slice(-12);

// iDClass: NSR(10) + Data(8) + Hora(4) + [IAE] + ID + Nome (Parede Letra)
const RX_CADASTRO = /\d{10}(\d{8})(\d{4})[IAE]?(\d+?)(?=[A-ZÀ-Ü])([A-ZÀ-Ü\s\-\']+)/;

// iDClass Batida: NSR(10) + '3' + Data(8) + Hora(4) + ID
const RX_BATIDA = /(\d{10})3(\d{8})(\d{4})[IAE]?(\d+)/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_ponto_v21_final');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); 
  const [activePersonId, setActivePersonId] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('abc_ponto_v21_final', JSON.stringify(store));
  }, [store]);

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1"); 

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 20);

      const newPunches: Punch[] = [];
      const userMap = new Map<string, string>(); 
      const foundMonths = new Set<string>();

      lines.forEach((raw) => {
        // 1. Tentar Cadastro (Tipo 5)
        const userMatch = raw.match(RX_CADASTRO);
        if (userMatch) {
          const id = canon12(userMatch[3]);
          const name = userMatch[4].trim().toUpperCase();
          if (name.length > 2) userMap.set(id, name);
          return;
        }

        // 2. Tentar Batida (Tipo 3)
        const punchMatch = raw.match(RX_BATIDA);
        if (punchMatch) {
          const [, nsr, ddmmyyyy, hhmm, idRaw] = punchMatch;

          const day = ddmmyyyy.slice(0, 2);
          const month = ddmmyyyy.slice(2, 4);
          const year = ddmmyyyy.slice(4, 8);
          const dayISO = `${year}-${month}-${day}`;

          foundMonths.add(`${year}-${month}`);
          newPunches.push({
            nsr,
            dayISO,
            time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
            id: canon12(idRaw)
          });
        }
      });

      // DIAGNÓSTICO E AUTO-AJUSTE
      if (newPunches.length > 0) {
        const sortedMonths = Array.from(foundMonths).sort();
        const latestMonthInFile = sortedMonths[sortedMonths.length - 1];

        console.group("Relatório de Importação AFD");
        console.log("Total Batidas:", newPunches.length);
        console.log("Meses Encontrados:", sortedMonths);
        console.log("Mês mais recente no arquivo:", latestMonthInFile);
        console.groupEnd();

        // Se o mês selecionado não tem dados, mas o arquivo tem, ajustamos para o mais recente do arquivo
        const hasDataInCurrentFilter = newPunches.some(p => p.dayISO.startsWith(selectedMonth));
        if (!hasDataInCurrentFilter) {
          setSelectedMonth(latestMonthInFile);
          setActivePersonId(null);
        }
      }

      setStore(prev => {
        const people = [...prev.people];
        userMap.forEach((name, id) => {
          let person = people.find(p => p.name === name);
          if (!person) {
            people.push({ name, ids: [id] });
          } else if (!person.ids.includes(id)) {
            person.ids.push(id);
          }
        });

        const existingNsrs = new Set(prev.punches.map(p => p.nsr));
        const filteredNew = newPunches.filter(p => !existingNsrs.has(p.nsr));
        const allPunches = [...prev.punches, ...filteredNew];

        const allDates = allPunches.map(p => p.dayISO).sort();
        const range = allDates.length > 0 ? 
          `${allDates[0].split('-').reverse().join('/')} até ${allDates[allDates.length-1].split('-').reverse().join('/')}` : 
          "N/A";

        return {
          people,
          punches: allPunches,
          lastImport: { 
            file: file.name, 
            stats: { punches: newPunches.length, users: userMap.size, range } 
          }
        };
      });
    };
    event.target.value = '';
  };

  /**
   * LÓGICA DE AUDITORIA: Lista lateral baseada em quem bateu ponto no mês.
   */
  const auditData = useMemo(() => {
    const punchesInMonth = store.punches.filter(p => p.dayISO.startsWith(selectedMonth));
    const uniqueIdsInMonth = Array.from(new Set(punchesInMonth.map(p => p.id)));

    const employees = uniqueIdsInMonth.map(id => {
      const person = store.people.find(p => p.ids.includes(id));
      return {
        id,
        name: person ? person.name : `COLABORADOR ${id.slice(-6)}`,
        isResolved: !!person
      };
    });

    const filtered = employees
      .filter(e => e.name.includes(searchTerm.toUpperCase()) || e.id.includes(searchTerm))
      .sort((a, b) => a.name.localeCompare(b.name));

    return {
      employees: filtered,
      stats: {
        totalGlobal: store.punches.length,
        idsGlobal: new Set(store.punches.map(p => p.id)).size,
        punchesInMonth: punchesInMonth.length,
        idsInMonth: uniqueIdsInMonth.length,
        resolvedInMonth: filtered.filter(e => e.isResolved).length
      }
    };
  }, [store, selectedMonth, searchTerm]);

  const activeEmployee = auditData.employees.find(e => e.id === activePersonId);
  const punchesForDisplay = useMemo(() => {
    if (!activePersonId) return [];
    return store.punches
      .filter(p => p.id === activePersonId && p.dayISO.startsWith(selectedMonth))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));
  }, [activePersonId, store.punches, selectedMonth]);

  const calculateDayMins = (p: Punch[]) => {
    if (p.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < p.length - 1; i += 2) {
      const [h1, m1] = p[i].time.split(':').map(Number);
      const [h2, m2] = p[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  return (
    <div className="space-y-6">
      {/* HEADER DE COMANDO */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-5">
          <div className="bg-[#E30613] p-4 rounded-2xl shadow-lg">
            <ShieldCheck className="text-white w-6 h-6" />
          </div>
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter text-[#0A1121]">Folha de Ponto</h2>
            <div className="flex flex-wrap items-center gap-3 mt-1">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-50 px-3 py-1 rounded-full border border-slate-100">
                Competência: {selectedMonth.split('-').reverse().join('/')} • {auditData.stats.idsInMonth} Ativos
              </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <input 
            type="month" 
            value={selectedMonth} 
            onChange={e => { setSelectedMonth(e.target.value); setActivePersonId(null); }} 
            className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-black outline-none cursor-pointer hover:bg-white transition-all shadow-sm" 
          />
          <label className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase cursor-pointer flex items-center gap-2 hover:bg-black transition-all shadow-xl active:scale-95">
            <FileUp className="w-4 h-4 text-[#E30613]" /> LER AFD <input type="file" className="hidden" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      {/* PAINEL DE CONTEXTO TEMPORAL */}
      {store.punches.length > 0 && auditData.stats.punchesInMonth === 0 && (
        <div className="bg-amber-50 border border-amber-200 p-8 rounded-[2.5rem] flex flex-col md:flex-row items-center gap-6 animate-in slide-in-from-top-4 duration-500">
           <AlertTriangle className="w-12 h-12 text-amber-500 shrink-0" />
           <div className="flex-1 text-center md:text-left">
              <p className="text-xs font-black text-amber-950 uppercase tracking-widest">Atenção: Filtro Incompatível com os Dados</p>
              <p className="text-[11px] font-bold text-amber-800 uppercase mt-2 leading-relaxed">
                Você está filtrando o mês {selectedMonth}, mas o arquivo importado contém batidas no intervalo: <span className="font-black text-amber-950">{store.lastImport?.stats.range}</span>. 
                <br/>Altere o seletor de data acima para visualizar os colaboradores.
              </p>
           </div>
           <div className="bg-white/50 px-6 py-4 rounded-2xl border border-amber-100 flex flex-col items-center">
              <Database className="w-4 h-4 text-amber-300 mb-1" />
              <p className="text-[10px] font-black text-amber-900">{auditData.stats.totalGlobal} Batidas no Banco</p>
           </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* LISTA LATERAL DINÂMICA */}
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm min-h-[60vh] flex flex-col">
          <div className="relative mb-6">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input 
              type="text" 
              placeholder="Buscar por Nome ou ID..." 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)} 
              className="w-full pl-10 pr-4 py-3 bg-slate-50 border rounded-xl text-xs font-bold outline-none" 
            />
          </div>

          <div className="flex-1 space-y-2 overflow-y-auto pr-2 custom-scrollbar">
            {auditData.employees.length === 0 ? (
              <div className="py-24 text-center opacity-30">
                <Fingerprint className="w-10 h-10 mx-auto mb-3 text-slate-200" />
                <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Ninguém bateu ponto em {selectedMonth}</p>
              </div>
            ) : (
              auditData.employees.map(e => (
                <button 
                  key={e.id} 
                  onClick={() => setActivePersonId(e.id)} 
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonId === e.id ? 'bg-[#0A1121] text-white border-[#0A1121] shadow-lg' : 'bg-slate-50 border-transparent hover:bg-slate-100 text-slate-600'}`}
                >
                  <div className="flex justify-between items-start">
                    <p className="text-[10px] font-black uppercase truncate leading-tight flex-1">{e.name}</p>
                    {!e.isResolved && <AlertOctagon className="w-3 h-3 text-red-500 ml-2" />}
                  </div>
                  <p className={`text-[8px] mt-1 font-bold ${activePersonId === e.id ? 'text-slate-400' : 'text-slate-400'}`}>ID: {e.id}</p>
                </button>
              ))
            )}
          </div>

          <div className="mt-4 pt-4 border-t border-slate-100 flex items-center justify-between text-[8px] font-black text-slate-400 uppercase tracking-widest">
             <div className="flex items-center gap-1"><Database className="w-3 h-3" /> {auditData.stats.totalGlobal} Batidas</div>
             <div className="flex items-center gap-1"><Users className="w-3 h-3" /> {auditData.stats.idsInMonth} Ativos</div>
          </div>
        </div>

        {/* ESPELHO DE PONTO */}
        <div className="lg:col-span-3">
          {activeEmployee ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
               <div className="bg-white border rounded-[2.5rem] p-8 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center border border-slate-100 shadow-sm">
                       <IdCard className={`${activeEmployee.isResolved ? 'text-emerald-500' : 'text-[#E30613]'} w-8 h-8`} />
                     </div>
                     <div>
                        <h3 className="text-xl font-black uppercase text-slate-900 leading-none">{activeEmployee.name}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-2 tracking-widest">Registro: {activeEmployee.id}</p>
                     </div>
                  </div>
                  <button onClick={() => window.print()} className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 hover:bg-black transition-all shadow-xl active:scale-95">
                    <Printer className="w-4 h-4 text-[#E30613]" /> Imprimir Espelho
                  </button>
               </div>

               <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                  <table className="w-full text-left border-collapse">
                    <thead className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-10 py-6 border-r border-slate-800/50">Data / Dia</th>
                        <th className="px-10 py-6">Marcações (AFD)</th>
                        <th className="px-4 py-6 text-center">Horas</th>
                        <th className="px-4 py-6 text-center">Auditoria</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {(() => {
                        const [y, m] = selectedMonth.split('-');
                        const days = new Date(Number(y), Number(m), 0).getDate();
                        return Array.from({length: days}, (_, i) => {
                          const day = (i+1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dp = punchesForDisplay.filter(p => p.dayISO === iso);
                          const mins = calculateDayMins(dp);
                          const dt = new Date(iso + 'T12:00:00');
                          const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                          return (
                            <tr key={iso} className={`group hover:bg-slate-50 transition-all ${dp.length === 0 ? 'opacity-30' : ''} ${isWeekend ? 'bg-slate-50/20' : ''}`}>
                              <td className="px-10 py-5 border-r border-slate-50">
                                <span className="text-sm font-black text-slate-900">{day}/{m}</span>
                                <span className="text-[9px] font-bold text-slate-400 uppercase block leading-none">{dt.toLocaleDateString('pt-BR', {weekday: 'short'})}</span>
                              </td>
                              <td className="px-10 py-5">
                                <div className="flex flex-wrap gap-2">
                                  {dp.map((p, ix) => (
                                    <span key={ix} className="bg-white text-slate-700 text-[11px] font-black px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm" title={`NSR: ${p.nsr}`}>{p.time}</span>
                                  ))}
                                </div>
                              </td>
                              <td className="px-4 py-5 text-center font-black text-xs text-slate-600">
                                {mins > 0 ? `${Math.floor(mins/60)}h${(mins%60).toString().padStart(2,'0')}` : '--:--'}
                              </td>
                              <td className="px-4 py-5 text-center">
                                {dp.length % 2 !== 0 && dp.length > 0 && <span title="Ponto Ímpar"><AlertOctagon className="w-5 h-5 text-red-500 mx-auto animate-pulse" /></span>}
                                {dp.length > 0 && dp.length % 2 === 0 && <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">OK</span>}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner text-center px-10">
              <Users className="w-24 h-24 opacity-10 mb-6" />
              <p className="font-black uppercase text-sm tracking-[0.2em] text-slate-400">Auditoria Mensal: {selectedMonth}</p>
              <p className="text-[10px] mt-2 font-bold text-slate-300 uppercase italic">Selecione um colaborador à esquerda para carregar as batidas.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Pedido, SortConfig, SortDirection } from '../types';
import { ChevronUp, ChevronDown, Check, Trash2, AlertTriangle, FileX, History, Share2, AlertOctagon, User, X, Link, Target } from 'lucide-react';

interface OrderTableProps {
  data: Pedido[];
  onUpdatePedido?: (id: string, updates: Partial<Pedido>) => void;
  onDeletePedido?: (id: string) => void;
  readOnly?: boolean;
}

export const OrderTable: React.FC<OrderTableProps> = ({ data, onUpdatePedido, onDeletePedido, readOnly = false }) => {
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'id', direction: 'asc' });
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [editingVendedor, setEditingVendedor] = useState<{id: string, nome: string} | null>(null);

  const listaVendedores = useMemo(() => {
    const nomes = new Set(data.map(p => p.vendedor).filter(v => v && v !== "." && v !== "SISTEMA"));
    return Array.from(nomes).sort();
  }, [data]);

  const handleSort = (key: keyof Pedido) => {
    let direction: SortDirection = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const sortedData = useMemo(() => {
    const sortableItems = [...data];
    if (sortConfig.direction !== null) {
      sortableItems.sort((a, b) => {
        const valA = a[sortConfig.key];
        const valB = b[sortConfig.key];
        if (valA === undefined || valA === null) return 1;
        if (valB === undefined || valB === null) return -1;
        if (typeof valA === 'string' && typeof valB === 'string') {
          return sortConfig.direction === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
        }
        if (typeof valA === 'number' && typeof valB === 'number') {
          return sortConfig.direction === 'asc' ? valA - valB : valB - valA;
        }
        return 0;
      });
    }
    return sortableItems;
  }, [data, sortConfig]);

  const totals = useMemo(() => {
    return data.reduce(
      (acc, curr) => {
        const valorFaturamento = curr.isOcorrencia ? 0 : (curr.total || 0);
        return {
          total: acc.total + valorFaturamento,
          margemOriginal: acc.margemOriginal + (curr.margemOriginal || 0),
          margemAjustada: acc.margemAjustada + (curr.margemAjustada || 0),
        };
      },
      { total: 0, margemOriginal: 0, margemAjustada: 0 }
    );
  }, [data]);

  const formatCurrency = (value: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  const formatPercent = (value: number) => new Intl.NumberFormat('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(value) + '%';

  const getMargemColor = (pct: number) => {
    if (pct <= 8.00) return 'text-[#E30613]';
    if (pct <= 10.00) return 'text-amber-500';
    return 'text-emerald-600';
  };

  const SortIcon = ({ column }: { column: keyof Pedido }) => {
    if (sortConfig.key !== column) return <ChevronDown className="w-3 h-3 text-slate-300 opacity-30" />;
    return sortConfig.direction === 'asc' ? <ChevronUp className="w-3 h-3 text-[#E30613]" /> : <ChevronDown className="w-3 h-3 text-[#E30613]" />;
  };

  return (
    <>
      {confirmDeleteId && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-950/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white rounded-[2.5rem] shadow-2xl max-w-md w-full p-10 space-y-8 border border-slate-200">
            <div className="flex flex-col items-center text-center space-y-4">
              <AlertTriangle className="w-10 h-10 text-[#E30613]" />
              <h3 className="text-2xl font-black text-slate-900 uppercase">Excluir Registro?</h3>
              <p className="text-slate-500 text-sm">Remover permanentemente <span className="font-black">MU {confirmDeleteId}</span>?</p>
            </div>
            <div className="flex flex-col gap-3">
              <button onClick={() => { onDeletePedido?.(confirmDeleteId); setConfirmDeleteId(null); }} className="w-full py-4 bg-[#E30613] text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl">Sim, Excluir</button>
              <button onClick={() => setConfirmDeleteId(null)} className="w-full py-4 bg-slate-100 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest">Cancelar</button>
            </div>
          </div>
        </div>
      )}

      <div className="bg-white rounded-[1.5rem] shadow-2xl border border-slate-200 overflow-hidden w-full">
        <div className="overflow-x-auto scrollbar-hide">
          <table className="w-full text-left text-[10px] border-collapse">
            <thead>
              <tr className="bg-[#0A1121] border-b border-slate-800">
                <th className="w-[45px] px-2 py-4 font-black text-slate-400 uppercase tracking-tighter text-center">Ocorr.</th>
                <th onClick={() => handleSort('id')} className="w-[100px] px-3 py-4 font-black text-slate-400 cursor-pointer hover:bg-slate-900 transition-colors uppercase tracking-tighter">
                   <div className="flex items-center justify-between">MU <SortIcon column="id" /></div>
                </th>
                <th className="w-[90px] px-2 py-4 font-black text-slate-400 uppercase tracking-tighter text-center">MU MESTRE</th>
                <th onClick={() => handleSort('data')} className="w-[85px] px-2 py-4 font-black text-slate-400 cursor-pointer hover:bg-slate-900 transition-colors uppercase tracking-tighter text-center">
                   <div className="flex items-center justify-center gap-1">DATA <SortIcon column="data" /></div>
                </th>
                <th onClick={() => handleSort('canal')} className="w-[110px] px-2 py-4 font-black text-slate-400 cursor-pointer hover:bg-slate-900 transition-colors uppercase tracking-tighter">
                   <div className="flex items-center justify-between">CANAL <SortIcon column="canal" /></div>
                </th>
                <th onClick={() => handleSort('vendedor')} className="px-3 py-4 font-black text-slate-400 cursor-pointer hover:bg-slate-900 transition-colors uppercase tracking-tighter min-w-[180px]">
                   <div className="flex items-center justify-between">VENDEDOR <SortIcon column="vendedor" /></div>
                </th>
                <th onClick={() => handleSort('total')} className="w-[100px] px-2 py-4 font-black text-slate-400 cursor-pointer hover:bg-slate-900 transition-colors uppercase tracking-tighter text-right">
                   <div className="flex items-center justify-end gap-1">TOTAL <SortIcon column="total" /></div>
                </th>
                <th onClick={() => handleSort('margemOriginal')} className="w-[100px] px-2 py-4 font-black text-slate-400 cursor-pointer hover:bg-slate-900 transition-colors uppercase tracking-tighter text-right">
                   <div className="flex items-center justify-end gap-1">MARGEM <SortIcon column="margemOriginal" /></div>
                </th>
                <th onClick={() => handleSort('margemOriginalPct')} className="w-[70px] px-2 py-4 font-black text-slate-400 cursor-pointer hover:bg-slate-900 transition-colors uppercase tracking-tighter text-right">
                   <div className="flex items-center justify-end gap-1">% <SortIcon column="margemOriginalPct" /></div>
                </th>
                <th className="w-[75px] px-2 py-4 font-black text-slate-400 uppercase tracking-tighter text-center">CRÉD.</th>
                <th className="w-[75px] px-2 py-4 font-black text-slate-400 uppercase tracking-tighter text-center">DÉB.</th>
                <th onClick={() => handleSort('margemAjustada')} className="w-[115px] px-3 py-4 font-black text-slate-700 uppercase tracking-tighter bg-slate-50 text-right cursor-pointer hover:bg-slate-100 transition-colors">
                   <div className="flex items-center justify-end gap-1">AJUSTADA <SortIcon column="margemAjustada" /></div>
                </th>
                <th className="w-[80px] px-3 py-4 font-black text-slate-700 text-right uppercase tracking-tighter bg-slate-100/50">FINAL %</th>
                <th className="w-[50px] px-2 py-4 font-black text-slate-400 text-center uppercase tracking-tighter">AÇÕES</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {sortedData.map((p) => {
                const isRetroativo = p.data.includes("Anterior") || p.vendedor.includes("SISTEMA");
                const margemAjustadaPct = p.total > 0 ? (p.margemAjustada / p.total) * 100 : 0;

                return (
                  <tr key={p.id} className={`${p.isOcorrencia ? 'bg-amber-50/60' : isRetroativo ? 'bg-emerald-50/20' : p.isCancelado ? 'bg-red-50/30' : 'bg-white'} hover:bg-slate-50/80 transition-all`}>
                    <td className="px-2 py-2.5 text-center">
                       <button onClick={() => !readOnly && onUpdatePedido?.(p.id, { isOcorrencia: !p.isOcorrencia })} className={`p-1.5 rounded-lg transition-all ${p.isOcorrencia ? 'bg-amber-500 text-white shadow-lg scale-110' : 'bg-slate-100 text-slate-300 hover:text-amber-500 hover:bg-amber-50'}`}>
                          <AlertOctagon className="w-3.5 h-3.5" />
                       </button>
                    </td>
                    <td className="px-3 py-2.5 text-slate-900 font-black">
                       <div className="flex items-center gap-1">
                          {p.id}
                          {isRetroativo && <History className="w-2.5 h-2.5 text-emerald-600 shrink-0" />}
                          {p.isCancelado && <FileX className="w-2.5 h-2.5 text-[#E30613] shrink-0" />}
                       </div>
                    </td>
                    <td className="px-2 py-2.5 text-center">
                       <div className="relative">
                          <input 
                            type="text" 
                            placeholder="Mestre..."
                            value={p.idPedidoMestre || ''}
                            onChange={(e) => onUpdatePedido?.(p.id, { idPedidoMestre: e.target.value })}
                            className="w-full bg-transparent border-b border-slate-200 text-center font-black text-[9px] focus:border-[#E30613] outline-none placeholder:opacity-30"
                          />
                       </div>
                    </td>
                    <td className={`px-2 py-2.5 font-black text-center ${isRetroativo ? 'text-emerald-600' : 'text-slate-500'}`}>{p.data}</td>
                    <td className="px-2 py-2.5">
                       <div className="flex items-center gap-1">
                          <Share2 className="w-2.5 h-2.5 text-slate-300 shrink-0" />
                          <span className="text-slate-700 uppercase font-black tracking-tighter truncate leading-none">{p.canal || "---"}</span>
                       </div>
                    </td>
                    <td className="px-3 py-2.5 text-slate-600 uppercase font-bold group/vend">
                       <div className="flex items-center gap-2">
                          {editingVendedor?.id === p.id ? (
                            <div className="flex items-center gap-1 w-full animate-in zoom-in-95 duration-200">
                               <select 
                                 value={editingVendedor.nome} 
                                 onChange={(e) => setEditingVendedor({...editingVendedor, nome: e.target.value})}
                                 className="w-full bg-white border-2 border-[#E30613] rounded-lg px-2 py-1 text-[10px] font-black outline-none shadow-inner"
                                 autoFocus
                               >
                                  <option value="">SELECIONE VENDEDOR</option>
                                  {listaVendedores.map(nome => <option key={nome} value={nome}>{nome}</option>)}
                               </select>
                               <button onClick={() => { onUpdatePedido?.(p.id, { vendedor: editingVendedor.nome }); setEditingVendedor(null); }} className="p-1.5 bg-emerald-500 text-white rounded-lg shadow-md hover:bg-emerald-600 transition-colors">
                                 <Check className="w-3 h-3" />
                               </button>
                               <button onClick={() => setEditingVendedor(null)} className="p-1.5 bg-slate-200 text-slate-500 rounded-lg"><X className="w-3 h-3"/></button>
                            </div>
                          ) : (
                            <>
                              <span className="flex-1 leading-tight">{p.vendedor || "."}</span>
                              {!readOnly && (
                                <button onClick={() => setEditingVendedor({id: p.id, nome: p.vendedor})} className="p-1.5 text-slate-300 hover:text-[#E30613] hover:bg-white rounded-lg transition-all opacity-0 group-hover/vend:opacity-100 shadow-sm border border-transparent hover:border-slate-100">
                                  <User className="w-3 h-3" />
                                </button>
                              )}
                            </>
                          )}
                       </div>
                    </td>
                    <td className={`px-2 py-2.5 font-black text-right ${p.isOcorrencia ? 'text-slate-400 line-through opacity-50' : 'text-slate-900'}`}>{formatCurrency(p.total || 0)}</td>
                    <td className="px-2 py-2.5 text-slate-400 italic text-right">{formatCurrency(p.margemOriginal || 0)}</td>
                    <td className="px-2 py-2.5 text-slate-400 italic text-right">{formatPercent(p.margemOriginalPct || 0)}</td>

                    <td className="px-2 py-2.5 text-center">
                        <input 
                          type="number" step="0.01" value={p.credito || ''} 
                          onChange={(e) => onUpdatePedido?.(p.id, { credito: parseFloat(e.target.value) || 0 })} 
                          className={`w-14 px-1 py-0.5 border rounded-lg text-right font-black outline-none text-[9px] transition-all ${p.credito > 0 ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-white border-slate-200'}`} 
                        />
                    </td>
                    <td className="px-2 py-2.5 text-center">
                        <input 
                          type="number" step="0.01" value={p.debito || ''} 
                          onChange={(e) => onUpdatePedido?.(p.id, { debito: parseFloat(e.target.value) || 0 })} 
                          className={`w-14 px-1 py-0.5 border rounded-lg text-right font-black outline-none text-[9px] transition-all ${p.debito > 0 ? 'bg-red-50 border-red-200 text-red-700' : 'bg-white border-slate-200'}`} 
                        />
                    </td>

                    <td className="px-3 py-2.5 font-black text-slate-900 bg-slate-50/50 text-right">{formatCurrency(p.margemAjustada)}</td>
                    <td className={`px-3 py-2.5 font-black text-right bg-slate-100/20 ${getMargemColor(margemAjustadaPct)}`}>
                      {isRetroativo ? '---' : formatPercent(margemAjustadaPct)}
                    </td>

                    <td className="px-2 py-2.5 text-center">
                      {!readOnly && <button onClick={() => setConfirmDeleteId(p.id)} className="p-1.5 text-slate-300 hover:text-[#E30613] hover:bg-red-50 rounded-lg transition-all"><Trash2 className="w-3.5 h-3.5" /></button>}
                    </td>
                  </tr>
                );
              })}
            </tbody>
            <tfoot className="bg-[#0A1121] text-white sticky bottom-0 z-30 shadow-[0_-4px_10px_rgba(0,0,0,0.2)]">
              <tr className="border-t border-slate-800">
                <td colSpan={6} className="px-4 py-4 text-right font-black text-[9px] uppercase tracking-[0.2em] text-slate-400">RESUMO AUDITORIA:</td>
                <td className="px-2 py-4 font-black text-right text-sm">{formatCurrency(totals.total)}</td>
                <td className="px-2 py-4 font-bold text-slate-500 italic text-right text-xs opacity-60">{formatCurrency(totals.margemOriginal)}</td>
                <td className="px-2 py-4 font-bold text-slate-500 italic text-right text-xs opacity-60">
                   {(totals.total > 0 ? (totals.margemOriginal / totals.total) * 100 : 0).toFixed(2)}%
                </td>
                <td colSpan={2}></td>
                <td className="px-3 py-4 font-black text-right bg-slate-800/80 text-lg border-l border-slate-700">{formatCurrency(totals.margemAjustada)}</td>
                <td className={`px-3 py-4 font-black text-right text-lg bg-slate-900 ${getMargemColor(totals.total > 0 ? (totals.margemAjustada / totals.total) * 100 : 0)}`}>
                  {formatPercent(totals.total > 0 ? (totals.margemAjustada / totals.total) * 100 : 0)}
                </td>
                <td className="bg-slate-900"></td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
    </>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  FileUp, Search, ShieldCheck, 
  IdCard, AlertOctagon, Printer, Fingerprint, History, AlertTriangle, Users, Database, CalendarRange, Info
} from 'lucide-react';

// --- MODELO DE DADOS ---
type Punch = { id: string; dayISO: string; time: string; nsr: string };
type Person = { 
  name: string; 
  ids: string[]; // Aliases canonicalizados (12 dígitos)
};
type Store = {
  people: Person[];
  punches: Punch[];
  lastImport?: { 
    file: string; 
    stats: { punches: number; users: number; range: string } 
  };
};

// --- MOTOR DE PARSING ---

const canon12 = (d: string) => d.replace(/\D/g, '').padStart(12, '0').slice(-12);

// iDClass: NSR(10) + Data(8) + Hora(4) + [IAE] + ID + Nome (Parede Letra)
const RX_CADASTRO = /\d{10}(\d{8})(\d{4})[IAE]?(\d+?)(?=[A-ZÀ-Ü])([A-ZÀ-Ü\s\-\']+)/;

// iDClass Batida: NSR(10) + '3' + Data(8) + Hora(4) + ID
const RX_BATIDA = /(\d{10})3(\d{8})(\d{4})[IAE]?(\d+)/;

export const HorasPage: React.FC = () => {
  const [store, setStore] = useState<Store>(() => {
    const saved = localStorage.getItem('abc_ponto_v21_final');
    return saved ? JSON.parse(saved) : { people: [], punches: [] };
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); 
  const [activePersonId, setActivePersonId] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('abc_ponto_v21_final', JSON.stringify(store));
  }, [store]);

  const handleImportAFD = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.readAsText(file, "ISO-8859-1"); 

    reader.onload = (e) => {
      const content = e.target?.result as string;
      const lines = content.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 20);

      const newPunches: Punch[] = [];
      const userMap = new Map<string, string>(); 
      const foundMonths = new Set<string>();

      lines.forEach((raw) => {
        // 1. Tentar Cadastro (Tipo 5)
        const userMatch = raw.match(RX_CADASTRO);
        if (userMatch) {
          const id = canon12(userMatch[3]);
          const name = userMatch[4].trim().toUpperCase();
          if (name.length > 2) userMap.set(id, name);
          return;
        }

        // 2. Tentar Batida (Tipo 3)
        const punchMatch = raw.match(RX_BATIDA);
        if (punchMatch) {
          const [, nsr, ddmmyyyy, hhmm, idRaw] = punchMatch;

          const day = ddmmyyyy.slice(0, 2);
          const month = ddmmyyyy.slice(2, 4);
          const year = ddmmyyyy.slice(4, 8);
          const dayISO = `${year}-${month}-${day}`;

          foundMonths.add(`${year}-${month}`);
          newPunches.push({
            nsr,
            dayISO,
            time: `${hhmm.slice(0, 2)}:${hhmm.slice(2, 4)}`,
            id: canon12(idRaw)
          });
        }
      });

      // DIAGNÓSTICO E AUTO-AJUSTE
      if (newPunches.length > 0) {
        const sortedMonths = Array.from(foundMonths).sort();
        const latestMonthInFile = sortedMonths[sortedMonths.length - 1];

        console.group("Relatório de Importação AFD");
        console.log("Total Batidas:", newPunches.length);
        console.log("Meses Encontrados:", sortedMonths);
        console.log("Mês mais recente no arquivo:", latestMonthInFile);
        console.groupEnd();

        // Se o mês selecionado não tem dados, mas o arquivo tem, ajustamos para o mais recente do arquivo
        const hasDataInCurrentFilter = newPunches.some(p => p.dayISO.startsWith(selectedMonth));
        if (!hasDataInCurrentFilter) {
          setSelectedMonth(latestMonthInFile);
          setActivePersonId(null);
        }
      }

      setStore(prev => {
        const people = [...prev.people];
        // Adicionando tipos explícitos para resolver erros de inferência 'unknown'
        userMap.forEach((name: string, id: string) => {
          let person = people.find((p: Person) => p.name === name);
          if (!person) {
            people.push({ name, ids: [id] });
          } else if (!person.ids.includes(id)) {
            person.ids.push(id);
          }
        });

        const existingNsrs = new Set(prev.punches.map((p: Punch) => p.nsr));
        const filteredNew = newPunches.filter((p: Punch) => !existingNsrs.has(p.nsr));
        const allPunches = [...prev.punches, ...filteredNew];

        const allDates = allPunches.map((p: Punch) => p.dayISO).sort();
        const range = allDates.length > 0 ? 
          `${allDates[0].split('-').reverse().join('/')} até ${allDates[allDates.length-1].split('-').reverse().join('/')}` : 
          "N/A";

        return {
          people,
          punches: allPunches,
          lastImport: { 
            file: file.name, 
            stats: { punches: newPunches.length, users: userMap.size, range } 
          }
        };
      });
    };
    event.target.value = '';
  };

  /**
   * LÓGICA DE AUDITORIA: Lista lateral baseada em quem bateu ponto no mês.
   */
  const auditData = useMemo(() => {
    // Explicitando tipos nos callbacks para garantir que os métodos de string (slice, includes) funcionem
    const punchesInMonth = store.punches.filter((p: Punch) => p.dayISO.startsWith(selectedMonth));
    const uniqueIdsInMonth = Array.from(new Set<string>(punchesInMonth.map((p: Punch) => p.id)));

    const employees = uniqueIdsInMonth.map((id: string) => {
      // Fix: Tipagem explícita de Person e garantindo que id é tratado como string
      const person = store.people.find((p: Person) => p.ids.includes(id));
      return {
        id,
        name: person ? person.name : `COLABORADOR ${id.slice(-6)}`,
        isResolved: !!person
      };
    });

    const filtered = employees
      .filter(e => e.name.includes(searchTerm.toUpperCase()) || e.id.includes(searchTerm))
      .sort((a, b) => a.name.localeCompare(b.name));

    return {
      employees: filtered,
      stats: {
        totalGlobal: store.punches.length,
        idsGlobal: new Set(store.punches.map((p: Punch) => p.id)).size,
        punchesInMonth: punchesInMonth.length,
        idsInMonth: uniqueIdsInMonth.length,
        resolvedInMonth: filtered.filter(e => e.isResolved).length
      }
    };
  }, [store, selectedMonth, searchTerm]);

  const activeEmployee = auditData.employees.find(e => e.id === activePersonId);
  const punchesForDisplay = useMemo(() => {
    if (!activePersonId) return [];
    return store.punches
      .filter((p: Punch) => p.id === activePersonId && p.dayISO.startsWith(selectedMonth))
      .sort((a, b) => a.dayISO.localeCompare(b.dayISO) || a.time.localeCompare(b.time));
  }, [activePersonId, store.punches, selectedMonth]);

  const calculateDayMins = (p: Punch[]) => {
    if (p.length < 2) return 0;
    let total = 0;
    for (let i = 0; i < p.length - 1; i += 2) {
      const [h1, m1] = p[i].time.split(':').map(Number);
      const [h2, m2] = p[i+1].time.split(':').map(Number);
      total += (h2 * 60 + m2) - (h1 * 60 + m1);
    }
    return total;
  };

  return (
    <div className="space-y-6">
      {/* HEADER DE COMANDO */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="flex items-center gap-5">
          <div className="bg-[#E30613] p-4 rounded-2xl shadow-lg">
            <ShieldCheck className="text-white w-6 h-6" />
          </div>
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter text-[#0A1121]">Folha de Ponto</h2>
            <div className="flex flex-wrap items-center gap-3 mt-1">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-50 px-3 py-1 rounded-full border border-slate-100">
                Competência: {selectedMonth.split('-').reverse().join('/')} • {auditData.stats.idsInMonth} Ativos
              </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <input 
            type="month" 
            value={selectedMonth} 
            onChange={e => { setSelectedMonth(e.target.value); setActivePersonId(null); }} 
            className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-black outline-none cursor-pointer hover:bg-white transition-all shadow-sm" 
          />
          <label className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase cursor-pointer flex items-center gap-2 hover:bg-black transition-all shadow-xl active:scale-95">
            <FileUp className="w-4 h-4 text-[#E30613]" /> LER AFD <input type="file" className="hidden" onChange={handleImportAFD} />
          </label>
        </div>
      </div>

      {/* PAINEL DE CONTEXTO TEMPORAL */}
      {store.punches.length > 0 && auditData.stats.punchesInMonth === 0 && (
        <div className="bg-amber-50 border border-amber-200 p-8 rounded-[2.5rem] flex flex-col md:flex-row items-center gap-6 animate-in slide-in-from-top-4 duration-500">
           <AlertTriangle className="w-12 h-12 text-amber-500 shrink-0" />
           <div className="flex-1 text-center md:text-left">
              <p className="text-xs font-black text-amber-950 uppercase tracking-widest">Atenção: Filtro Incompatível com os Dados</p>
              <p className="text-[11px] font-bold text-amber-800 uppercase mt-2 leading-relaxed">
                Você está filtrando o mês {selectedMonth}, mas o arquivo importado contém batidas no intervalo: <span className="font-black text-amber-950">{store.lastImport?.stats.range}</span>. 
                <br/>Altere o seletor de data acima para visualizar os colaboradores.
              </p>
           </div>
           <div className="bg-white/50 px-6 py-4 rounded-2xl border border-amber-100 flex flex-col items-center">
              <Database className="w-4 h-4 text-amber-300 mb-1" />
              <p className="text-[10px] font-black text-amber-900">{auditData.stats.totalGlobal} Batidas no Banco</p>
           </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* LISTA LATERAL DINÂMICA */}
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-sm min-h-[60vh] flex flex-col">
          <div className="relative mb-6">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input 
              type="text" 
              placeholder="Buscar por Nome ou ID..." 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)} 
              className="w-full pl-10 pr-4 py-3 bg-slate-50 border rounded-xl text-xs font-bold outline-none" 
            />
          </div>

          <div className="flex-1 space-y-2 overflow-y-auto pr-2 custom-scrollbar">
            {auditData.employees.length === 0 ? (
              <div className="py-24 text-center opacity-30">
                <Fingerprint className="w-10 h-10 mx-auto mb-3 text-slate-200" />
                <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Ninguém bateu ponto em {selectedMonth}</p>
              </div>
            ) : (
              auditData.employees.map(e => (
                <button 
                  key={e.id} 
                  onClick={() => setActivePersonId(e.id)} 
                  className={`w-full text-left p-4 rounded-2xl transition-all border ${activePersonId === e.id ? 'bg-[#0A1121] text-white border-[#0A1121] shadow-lg' : 'bg-slate-50 border-transparent hover:bg-slate-100 text-slate-600'}`}
                >
                  <div className="flex justify-between items-start">
                    <p className="text-[10px] font-black uppercase truncate leading-tight flex-1">{e.name}</p>
                    {!e.isResolved && <AlertOctagon className="w-3 h-3 text-red-500 ml-2" />}
                  </div>
                  <p className={`text-[8px] mt-1 font-bold ${activePersonId === e.id ? 'text-slate-400' : 'text-slate-400'}`}>ID: {e.id}</p>
                </button>
              ))
            )}
          </div>

          <div className="mt-4 pt-4 border-t border-slate-100 flex items-center justify-between text-[8px] font-black text-slate-400 uppercase tracking-widest">
             <div className="flex items-center gap-1"><Database className="w-3 h-3" /> {auditData.stats.totalGlobal} Batidas</div>
             <div className="flex items-center gap-1"><Users className="w-3 h-3" /> {auditData.stats.idsInMonth} Ativos</div>
          </div>
        </div>

        {/* ESPELHO DE PONTO */}
        <div className="lg:col-span-3">
          {activeEmployee ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
               <div className="bg-white border rounded-[2.5rem] p-8 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
                  <div className="flex items-center gap-6">
                     <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center border border-slate-100 shadow-sm">
                       <IdCard className={`${activeEmployee.isResolved ? 'text-emerald-500' : 'text-[#E30613]'} w-8 h-8`} />
                     </div>
                     <div>
                        <h3 className="text-xl font-black uppercase text-slate-900 leading-none">{activeEmployee.name}</h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase mt-2 tracking-widest">Registro: {activeEmployee.id}</p>
                     </div>
                  </div>
                  <button onClick={() => window.print()} className="bg-[#0A1121] text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 hover:bg-black transition-all shadow-xl active:scale-95">
                    <Printer className="w-4 h-4 text-[#E30613]" /> Imprimir Espelho
                  </button>
               </div>

               <div className="bg-white border border-slate-200 rounded-[3rem] shadow-2xl overflow-hidden">
                  <table className="w-full text-left border-collapse">
                    <thead className="bg-[#0A1121] text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                      <tr>
                        <th className="px-10 py-6 border-r border-slate-800/50">Data / Dia</th>
                        <th className="px-10 py-6">Marcações (AFD)</th>
                        <th className="px-4 py-6 text-center">Horas</th>
                        <th className="px-4 py-6 text-center">Auditoria</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {(() => {
                        const [y, m] = selectedMonth.split('-');
                        const days = new Date(Number(y), Number(m), 0).getDate();
                        return Array.from({length: days}, (_, i) => {
                          const day = (i+1).toString().padStart(2, '0');
                          const iso = `${selectedMonth}-${day}`;
                          const dp = punchesForDisplay.filter(p => p.dayISO === iso);
                          const mins = calculateDayMins(dp);
                          const dt = new Date(iso + 'T12:00:00');
                          const isWeekend = dt.getDay() === 0 || dt.getDay() === 6;

                          return (
                            <tr key={iso} className={`group hover:bg-slate-50 transition-all ${dp.length === 0 ? 'opacity-30' : ''} ${isWeekend ? 'bg-slate-50/20' : ''}`}>
                              <td className="px-10 py-5 border-r border-slate-50">
                                <span className="text-sm font-black text-slate-900">{day}/{m}</span>
                                <span className="text-[9px] font-bold text-slate-400 uppercase block leading-none">{dt.toLocaleDateString('pt-BR', {weekday: 'short'})}</span>
                              </td>
                              <td className="px-10 py-5">
                                <div className="flex flex-wrap gap-2">
                                  {dp.map((p, ix) => (
                                    <span key={ix} className="bg-white text-slate-700 text-[11px] font-black px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm" title={`NSR: ${p.nsr}`}>{p.time}</span>
                                  ))}
                                </div>
                              </td>
                              <td className="px-4 py-5 text-center font-black text-xs text-slate-600">
                                {mins > 0 ? `${Math.floor(mins/60)}h${(mins%60).toString().padStart(2,'0')}` : '--:--'}
                              </td>
                              <td className="px-4 py-5 text-center">
                                {dp.length % 2 !== 0 && dp.length > 0 && <span title="Ponto Ímpar"><AlertOctagon className="w-5 h-5 text-red-500 mx-auto animate-pulse" /></span>}
                                {dp.length > 0 && dp.length % 2 === 0 && <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">OK</span>}
                              </td>
                            </tr>
                          );
                        });
                      })()}
                    </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-64 flex flex-col items-center justify-center text-slate-300 shadow-inner text-center px-10">
              <Users className="w-24 h-24 opacity-10 mb-6" />
              <p className="font-black uppercase text-sm tracking-[0.2em] text-slate-400">Auditoria Mensal: {selectedMonth}</p>
              <p className="text-[10px] mt-2 font-bold text-slate-300 uppercase italic">Selecione um colaborador à esquerda para carregar as batidas.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

