import React, { useState, useMemo } from 'react';
import { MesConferencia, Pedido } from '../types';
import { 
  Calendar, 
  ChevronLeft, 
  ChevronRight, 
  Filter, 
  Maximize2, 
  MoreHorizontal, 
  FileUp, 
  CheckCircle2, 
  AlertTriangle,
  ArrowRight
} from 'lucide-react';
import * as XLSX from 'xlsx';

interface OcorrenciasPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null) => void;
}

export const OcorrenciasPage: React.FC<OcorrenciasPageProps> = ({ data, onSetData }) => {
  const [selectedYear, setSelectedYear] = useState('2025');
  const [selectedMonth, setSelectedMonth] = useState('agosto');
  const [selectedDay, setSelectedDay] = useState<number | null>(null);
  const [selectedFilial, setSelectedFilial] = useState('Todas');
  const [loading, setLoading] = useState(false);

  const months = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
  const years = ['2025', '2026'];

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const handleImportOcorrencias = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !data) return;

    setLoading(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { defval: "" }) as any[];

        const newPedidos = [...data.pedidos];

        rows.forEach((r: any) => {
          const muNovo = String(r["Novo pedido"] || r["Pedido"] || "").trim();
          const muOriginal = String(r["Pedido original"] || r["MU Mestre"] || "").trim();

          if (!muNovo) return;

          const index = newPedidos.findIndex(p => p.id === muNovo);
          if (index !== -1) {
            newPedidos[index].idPedidoMestre = muOriginal;
            newPedidos[index].filial = r["Filial"] || "F - ITU";
            newPedidos[index].statusOcorrencia = r["Status"] || "Finalizado Reposição";
            newPedidos[index].tipoOcorrencia = r["Status tipo"] || "Reposição - Entrega ao Cliente";
            newPedidos[index].dataOcorrencia = r["Data ocorrência"];
          }
        });

        onSetData({ ...data, pedidos: newPedidos });
      } catch (err) {
        alert("Erro ao processar planilha de ocorrências.");
      } finally {
        setLoading(false);
        event.target.value = "";
      }
    };
    reader.readAsBinaryString(file);
  };

  const auditData = useMemo(() => {
    if (!data) return [];

    // Filtramos apenas pedidos que são reposição/ocorrência (têm idPedidoMestre)
    return data.pedidos
      .filter(p => p.idPedidoMestre && p.idPedidoMestre !== p.id)
      .map(p => {
        const mestre = data.pedidos.find(m => m.id === p.idPedidoMestre);
        const valorDevolvido = p.valorDevolvido || (mestre?.isDevolvido ? mestre.total : 0);
        const margemDescontada = mestre?.margemDeduzidaDevolucao || 0;
        const difPedido = p.total - valorDevolvido;
        const margemLiquida = p.margemAjustada;

        return {
          dataOcorr: p.dataOcorrencia || p.data,
          dataAjustada: p.data,
          filial: p.filial || 'F - ITU',
          status: p.statusOcorrencia || 'Finalizado Reposição',
          tipo: p.tipoOcorrencia || 'Reposição - Entrega ao Cliente',
          pedidoOriginal: p.idPedidoMestre,
          valorDevolvido,
          margemDescontada,
          novoPedido: p.id,
          valorPedido: p.total,
          difPedido,
          margemLiquida,
          dif: margemLiquida - (mestre?.margemOriginal || 0)
        };
      });
  }, [data]);

  const totals = useMemo(() => {
    return auditData.reduce((acc, curr) => ({
      devolvido: acc.devolvido + curr.valorDevolvido,
      descontada: acc.descontada + curr.margemDescontada,
      novo: acc.novo + curr.valorPedido,
      dif: acc.dif + curr.difPedido,
      margem: acc.margem + curr.margemLiquida
    }), { devolvido: 0, descontada: 0, novo: 0, dif: 0, margem: 0 });
  }, [auditData]);

  return (
    <div className="space-y-6">
      {/* HEADER DE TÍTULO */}
      <div className="flex justify-between items-center mb-4">
         <h2 className="text-4xl font-black text-[#E30613] tracking-tight">Ajustes de Margem em Pedidos com Ocorrência</h2>
         <div className="text-right">
            <p className="text-[10px] font-black text-slate-400 uppercase">Atualizado em:</p>
            <p className="text-[11px] font-black text-red-500">{new Date().toLocaleString('pt-BR')}</p>
         </div>
      </div>

      {/* FILTROS DE CALENDÁRIO (ESTILO PRINT) */}
      <div className="bg-white p-6 rounded-[2.5rem] shadow-xl border border-slate-100 space-y-4">
        <div className="flex gap-1">
          <span className="text-[10px] font-black text-slate-400 uppercase w-24 pt-2">Data ajustada</span>
          <div className="flex-1 flex gap-px bg-slate-200 p-px rounded-lg overflow-hidden h-10">
            {years.map(y => (
              <button 
                key={y} 
                onClick={() => setSelectedYear(y)}
                className={`flex-1 text-xs font-black uppercase transition-all ${selectedYear === y ? 'bg-slate-800 text-white' : 'bg-red-600 text-white hover:bg-red-700'}`}
              >
                {y}
              </button>
            ))}
          </div>
          <div className="flex gap-2 ml-4">
            <button className="p-2 text-slate-400 hover:text-slate-900"><Filter className="w-5 h-5" /></button>
            <button className="p-2 text-slate-400 hover:text-slate-900"><Maximize2 className="w-5 h-5" /></button>
            <button className="p-2 text-slate-400 hover:text-slate-900"><MoreHorizontal className="w-5 h-5" /></button>
          </div>
        </div>

        <div className="flex gap-px bg-red-600 p-px rounded-lg overflow-hidden h-10">
          {months.map(m => (
            <button 
              key={m} 
              onClick={() => setSelectedMonth(m)}
              className={`flex-1 text-[10px] font-black uppercase transition-all border-r border-white/20 last:border-0 ${selectedMonth === m ? 'bg-slate-800 text-white' : 'text-white hover:bg-red-700'}`}
            >
              {m}
            </button>
          ))}
        </div>

        <div className="relative group">
           <div className="flex gap-px bg-red-600 p-px rounded-lg overflow-x-auto scrollbar-hide h-10">
             {Array.from({length: 31}, (_, i) => i + 1).map(d => (
               <button 
                 key={d} 
                 onClick={() => setSelectedDay(selectedDay === d ? null : d)}
                 className={`min-w-[40px] text-[10px] font-black uppercase transition-all border-r border-white/20 last:border-0 ${selectedDay === d ? 'bg-slate-800 text-white' : 'text-white hover:bg-red-700'}`}
               >
                 {d}
               </button>
             ))}
           </div>
           <div className="absolute right-0 top-0 h-full w-12 bg-gradient-to-l from-white to-transparent pointer-events-none flex items-center justify-end pr-2">
              <ChevronRight className="w-5 h-5 text-slate-400" />
           </div>
        </div>
      </div>

      {/* FILTRO DE FILIAL */}
      <div className="bg-white p-6 rounded-[2rem] shadow-lg border border-slate-100 max-w-xs">
