  const months = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
  const years = ['2025', '2026'];

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const handleUpdateMestre = (muId: string, mestreId: string) => {
    if (!data) return;
    const newPedidos = data.pedidos.map(p => {
      if (p.id === muId) return { ...p, idPedidoMestre: mestreId };
      return p;
    });
    onSetData({ ...data, pedidos: newPedidos });
  };

  const auditData = useMemo(() => {
    if (!data) return [];

    // Filtramos pedidos que são ocorrências ou têm vínculo mestre
    // E aplicamos os filtros de calendário/busca
    return data.pedidos
      .filter(p => {
        const matchesSearch = p.id.includes(searchTerm) || (p.idPedidoMestre && p.idPedidoMestre.includes(searchTerm));
        const isOccurrence = p.isOcorrencia || (p.idPedidoMestre && p.idPedidoMestre !== p.id);
        return isOccurrence && matchesSearch;
      })
      .map(p => {
        // Busca o pedido mestre para comparação
        const mestre = data.pedidos.find(m => m.id === p.idPedidoMestre);

        const valorDevolvido = mestre?.total || 0;
        const margemDescontada = mestre?.margemOriginal || 0;
        const valorPedidoNovo = p.total;
        const difPedido = valorPedidoNovo - valorDevolvido;
        const margemLiquida = p.margemAjustada;

        return {
          id: p.id,
          dataOcorr: p.dataOcorrencia || p.data,
          dataAjustada: p.data,
          filial: p.filial || 'F - ITU',
          status: p.statusOcorrencia || 'Finalizado Reposição',
          tipo: p.tipoOcorrencia || 'Reposição - Entrega ao Cliente',
          pedidoOriginal: p.idPedidoMestre || '',
          valorDevolvido,
          margemDescontada,
          novoPedido: p.id,
          valorPedido: valorPedidoNovo,
          difPedido,
          margemLiquida,
          // Se a margem líquida do novo for menor que o que foi perdido no original, é um problema
          isSaudavel: margemLiquida >= margemDescontada
        };
      });
  }, [data, searchTerm]);

  const totals = useMemo(() => {
    return auditData.reduce((acc, curr) => ({
      devolvido: acc.devolvido + curr.valorDevolvido,
      descontada: acc.descontada + curr.margemDescontada,
      novo: acc.novo + curr.valorPedido,
      dif: acc.dif + curr.difPedido,
      margem: acc.margem + curr.margemLiquida
    }), { devolvido: 0, descontada: 0, novo: 0, dif: 0, margem: 0 });
  }, [auditData]);

  return (
    <div className="space-y-6">
      {/* HEADER DINÂMICO */}
      <div className="flex justify-between items-start mb-2">
         <div>
            <h2 className="text-4xl font-black text-[#E30613] tracking-tighter uppercase italic">Ajustes de Margem em Pedidos com Ocorrência</h2>
