               <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
               <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Módulo de Auditoria de Reposição e Saldo ABC</p>
            </div>
         </div>
         <div className="text-right">
            <p className="text-[10px] font-black text-slate-400 uppercase">Atualizado em:</p>
            <p className="text-xs font-black text-slate-900">{new Date().toLocaleString('pt-BR')}</p>
         </div>
      </div>

      {/* INTERFACE DE CALENDÁRIO (CONFORME PRINT) */}
      <div className="bg-white p-6 rounded-[2.5rem] shadow-2xl border border-slate-100 space-y-4">
        {/* FAIXA ANOS */}
        <div className="flex items-center gap-4">
          <span className="text-[10px] font-black text-slate-400 uppercase w-28">Data ajustada</span>
          <div className="flex-1 flex gap-px bg-slate-200 p-px rounded-xl overflow-hidden h-10 shadow-inner">
            {years.map(y => (
              <button 
