import React, { useState, useMemo, useEffect } from 'react';
import { MesConferencia, Pedido } from '../types';
import { 
  FileUp, 
  CheckCircle2, 
  RotateCcw, 
  Calendar, 
  AlertCircle, 
  ShieldCheck, 
  TrendingDown, 
  TrendingUp,
  Link2,
  RefreshCw
} from 'lucide-react';
import * as XLSX from 'xlsx';

interface OcorrenciasPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null) => void;
}

export const OcorrenciasPage: React.FC<OcorrenciasPageProps> = ({ data, onSetData }) => {
  const [loading, setLoading] = useState(false);
  const [selectedMonth, setSelectedMonth] = useState(data?.mesReferencia || new Date().toISOString().slice(0, 7));

  useEffect(() => {
    if (data?.mesReferencia) {
      setSelectedMonth(data.mesReferencia);
    }
  }, [data?.mesReferencia]);

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const handleUpdateMestre = (muId: string, mestreId: string) => {
    if (!data) return;
    const newPedidos = data.pedidos.map(p => {
      if (p.id === muId) return { ...p, idPedidoMestre: mestreId };
      return p;
    });
    onSetData({ ...data, pedidos: newPedidos });
  };

  const handleImportOcorrencias = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !data) return;

    setLoading(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { defval: "" }) as any[];

        const newPedidos = [...data.pedidos];

        rows.forEach((r: any) => {
          const muNovo = String(r["Novo pedido"] || r["Pedido"] || r["MU"] || "").trim();
          const muOriginal = String(r["Pedido original"] || r["MU Mestre"] || r["Pedido Mestre"] || "").trim();

          if (!muNovo) return;

          const index = newPedidos.findIndex(p => p.id === muNovo);
          if (index !== -1) {
            newPedidos[index].idPedidoMestre = muOriginal;
            newPedidos[index].filial = r["Filial"] || "F - ITU";
            newPedidos[index].statusOcorrencia = r["Status"] || "Finalizado Reposição";
            newPedidos[index].tipoOcorrencia = r["Status tipo"] || "Reposição - Entrega ao Cliente";
          }
        });

        onSetData({ ...data, pedidos: newPedidos });
      } catch (err) {
        alert("Erro ao processar planilha de ocorrências.");
      } finally {
        setLoading(false);
        event.target.value = "";
      }
    };
    reader.readAsBinaryString(file);
  };

  const auditData = useMemo(() => {
    if (!data) return [];

    return data.pedidos
      .filter(p => p.isOcorrencia || (p.idPedidoMestre && p.idPedidoMestre !== p.id))
      .map(p => {
        const mestre = data.pedidos.find(m => m.id === p.idPedidoMestre);
        const valorEstornoMargem = mestre?.margemOriginal || 0;
        const margemNova = p.margemAjustada;
        const saldoABC = margemNova - valorEstornoMargem;

        return {
          id: p.id,
          data: p.data,
          filial: p.filial || 'F - ITU',
          status: p.statusOcorrencia || 'Finalizado Reposição',
          tipo: p.tipoOcorrencia || 'Reposição',
          pedidoOriginal: p.idPedidoMestre || '',
          valorPedidoOriginal: mestre?.total || 0,
          margemEstornada: valorEstornoMargem,
          valorPedidoNovo: p.total,
          margemNova,
          saldoABC,
          isSaudavel: saldoABC >= 0
        };
      });
  }, [data]);

  const summary = useMemo(() => {
    return auditData.reduce((acc, curr) => ({
      totalReposicao: acc.totalReposicao + curr.valorPedidoNovo,
      margemNova: acc.margemNova + curr.margemNova,
      saldoABC: acc.saldoABC + curr.saldoABC,
      count: acc.count + 1,
      pendentes: acc.pendentes + (curr.pedidoOriginal === '' ? 1 : 0)
    }), { totalReposicao: 0, margemNova: 0, saldoABC: 0, count: 0, pendentes: 0 });
  }, [auditData]);

  return (
    <div className="space-y-12">
      {/* HEADER ALINHADO COM VENDAS BASE */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="flex flex-col gap-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Ocorrências</h2>
          <div className="flex flex-wrap items-center gap-3">
            <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Auditoria e Saldo ABC:</p>
            <div className="flex items-center gap-2 bg-white border border-slate-200 rounded-xl px-4 py-2 shadow-sm group">
               <Calendar className="w-4 h-4 text-[#E30613]" />
               <input 
                 type="month" 
                 value={selectedMonth} 
                 onChange={(e) => setSelectedMonth(e.target.value)} 
                 className="bg-transparent text-xs font-black uppercase text-slate-700 outline-none cursor-pointer" 
               />
            </div>
          </div>
        </div>
        <div className="flex flex-wrap items-center gap-4">
          <label className="flex items-center gap-4 px-10 py-5 bg-[#E30613] hover:bg-red-700 text-white rounded-2xl cursor-pointer shadow-2xl active:scale-95 font-black text-sm uppercase tracking-wider transition-all">
            <FileUp className="w-5 h-5" />
            <span>IMPORTAR VÍNCULOS</span>
            <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleImportOcorrencias} />
          </label>
        </div>
      </div>

      {/* CARDS DE RESUMO ESTILO VENDAS BASE */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 animate-in fade-in slide-in-from-top-4 duration-500">
        <div className="bg-[#0A1121] rounded-[2.5rem] p-8 text-white shadow-2xl">
          <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">Total Reposições</span>
          <p className="text-3xl font-black tracking-tighter">{formatCurrency(summary.totalReposicao)}</p>
        </div>
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100">
          <span className="text-[9px] font-black uppercase tracking-widest text-slate-500">Margem Nova Acumulada</span>
          <p className="text-3xl font-black tracking-tighter text-slate-900">{formatCurrency(summary.margemNova)}</p>
        </div>
        {summary.saldoABC < 0 ? (
          <div className="bg-red-50 border border-red-100 rounded-[2.5rem] p-8 shadow-xl">
            <span className="text-[9px] font-black uppercase tracking-widest text-red-400">Saldo ABC (Déficit)</span>
            <div className="flex items-center gap-2">
               <TrendingDown className="w-6 h-6 text-red-500" />
               <p className="text-3xl font-black tracking-tighter text-[#E30613]">{formatCurrency(summary.saldoABC)}</p>
            </div>
          </div>
        ) : (
          <div className="bg-emerald-50 border border-emerald-100 rounded-[2.5rem] p-8 shadow-xl">
            <span className="text-[9px] font-black uppercase tracking-widest text-emerald-400">Saldo ABC (Positivo)</span>
            <div className="flex items-center gap-2">
               <TrendingUp className="w-6 h-6 text-emerald-500" />
               <p className="text-3xl font-black tracking-tighter text-emerald-600">{formatCurrency(summary.saldoABC)}</p>
            </div>
          </div>
        )}
        <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 flex flex-col justify-center">
          <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">Integridade de Vínculos</span>
          {summary.pendentes > 0 ? (
             <p className="text-xl font-black text-amber-600 flex items-center gap-2 mt-1">
                <AlertCircle className="w-5 h-5" /> {summary.pendentes} Pendentes
             </p>
          ) : (
             <p className="text-xl font-black text-emerald-600 flex items-center gap-2 mt-1">
                <ShieldCheck className="w-5 h-5" /> 100% Vinculado
             </p>
          )}
          <p className="text-[10px] font-bold text-slate-300 uppercase mt-1">Base: {summary.count} Pedidos</p>
        </div>
      </div>

      {/* TABELA DE AUDITORIA */}
      <div className="bg-white border border-slate-200 rounded-[2.5rem] shadow-2xl overflow-hidden">
        <div className="overflow-x-auto scrollbar-hide">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-[#0A1121] text-[10px] font-black text-slate-400 uppercase tracking-tighter border-b border-slate-800">
                <th className="px-5 py-5 border-r border-slate-800/50">Data</th>
                <th className="px-5 py-5 border-r border-slate-800/50">Filial</th>
                <th className="px-5 py-5 border-r border-slate-800/50">Status / Tipo</th>
                <th className="px-5 py-5 border-r border-slate-800/50 text-center bg-red-900/10">MU Mestre (Original)</th>
                <th className="px-5 py-5 border-r border-slate-800/50 text-right">Margem Estornada</th>
                <th className="px-5 py-5 border-r border-slate-800/50 text-center bg-emerald-900/10 text-emerald-400">Nova MU (Reposição)</th>
                <th className="px-5 py-5 border-r border-slate-800/50 text-right">Nova Margem</th>
                <th className="px-5 py-5 text-right bg-slate-800/50">Saldo ABC</th>
                <th className="px-5 py-5 text-center">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {loading ? (
                <tr>
                   <td colSpan={9} className="py-32 text-center">
                      <RefreshCw className="w-10 h-10 animate-spin text-red-500 mx-auto mb-4" />
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Processando base de ocorrências...</p>
                   </td>
                </tr>
              ) : auditData.length === 0 ? (
                <tr>
                   <td colSpan={9} className="py-32 text-center">
                      <RotateCcw className="w-12 h-12 mb-4 text-slate-200 mx-auto" />
                      <p className="text-[11px] font-black text-slate-300 uppercase tracking-[0.3em]">Nenhuma ocorrência identificada no mês</p>
                   </td>
                </tr>
              ) : (
                auditData.map((item) => (
                  <tr key={item.id} className={`${!item.isSaudavel ? 'bg-red-50/30' : 'bg-white'} hover:bg-slate-50 transition-all text-[11px] font-bold text-slate-700`}>
                    <td className="px-5 py-4 border-r border-slate-100">{item.data}</td>
                    <td className="px-5 py-4 border-r border-slate-100 uppercase">{item.filial}</td>
                    <td className="px-5 py-4 border-r border-slate-100">
                       <div className="flex flex-col">
                          <span className="text-[9px] font-black uppercase text-slate-900 leading-none">{item.status}</span>
                          <span className="text-[8px] font-bold text-slate-400 uppercase mt-1">{item.tipo}</span>
                       </div>
                    </td>

                    {/* VÍNCULO MESTRE */}
                    <td className="px-5 py-4 border-r border-slate-100 text-center bg-red-50/10">
                       <div className="relative group">
                          <input 
                            type="text" 
                            value={item.pedidoOriginal}
                            placeholder="VINCULAR..."
                            onChange={(e) => handleUpdateMestre(item.id, e.target.value)}
                            className="w-full bg-transparent text-center font-black text-[11px] text-[#E30613] outline-none placeholder:text-red-200"
                          />
                          <Link2 className="absolute -left-1 top-1/2 -translate-y-1/2 w-3 h-3 text-red-300 opacity-0 group-hover:opacity-100" />
                       </div>
                    </td>

                    <td className="px-5 py-4 border-r border-slate-100 text-right text-slate-400 italic">{formatCurrency(item.margemEstornada)}</td>

                    <td className="px-5 py-4 border-r border-slate-100 text-center font-black bg-emerald-50/10 text-emerald-700">{item.id}</td>

