import React, { useState, useMemo, useEffect } from 'react';
import * as XLSX from 'xlsx';
import { Pedido, MesConferencia } from '../types';
import { OrderTable } from '../components/OrderTable';
import { FileUp, CheckCircle2, DatabaseBackup, Calendar, AlertCircle, FileSearch, ShieldCheck, RotateCcw } from 'lucide-react';

interface ConferenciaPageProps {
  data: MesConferencia | null;
  onSetData: (newData: MesConferencia | null, multiMonthData?: Record<string, Pedido[]>) => void;
  onUpdatePedido: (id: string, updates: Partial<Pedido>) => void;
  onDeletePedido: (id: string) => void;
  onNavigateToAjustes: () => void;
  onNavigateToOcorrencias: () => void;
}

export const ConferenciaPage: React.FC<ConferenciaPageProps> = ({ 
  data, 
  onSetData, 
  onUpdatePedido, 
  onDeletePedido,
  onNavigateToAjustes,
  onNavigateToOcorrencias
}) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedMonth, setSelectedMonth] = useState(data?.mesReferencia || new Date().toISOString().slice(0, 7));

  useEffect(() => {
    if (data?.mesReferencia) {
      setSelectedMonth(data.mesReferencia);
    }
  }, [data?.mesReferencia]);

  const toNumber = (val: any): number => {
    if (val === null || val === undefined || val === '' || val === '-') return 0;
    if (typeof val === 'number') return val;
    const cleaned = String(val).replace(/R\$/g, '').replace(/\./g, '').replace(',', '.').replace(/\s/g, '').trim();
    const n = parseFloat(cleaned);
    return isNaN(n) ? 0 : n;
  };

  const toPercent = (val: any): number => {
    let n = toNumber(val);
    if (Math.abs(n) > 0 && Math.abs(n) < 1) return n * 100;
    return n;
  };

  const excelDateToBR = (serial: any): string => {
    if (!serial) return '';
    if (typeof serial === 'string') return serial;
    try {
      const date = new Date(Math.round((serial - 25569) * 86400 * 1000));
      if (isNaN(date.getTime())) return String(serial);
      return date.toLocaleDateString('pt-BR');
    } catch {
      return String(serial);
    }
  };

  const extractYearMonth = (dateStr: string): string | null => {
    const parts = dateStr.split('/');
    if (parts.length === 3) {
      return `${parts[2]}-${parts[1]}`; 
    }
    return null;
  };

  const getActualKey = (firstRow: any, targets: string[]): string => {
    const keys = Object.keys(firstRow);
    for (const target of targets) {
      const normalizedTarget = target.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
      const found = keys.find(k => {
        const normalizedK = k.toLowerCase().normalize("NFD").replace(/[\u0300 scalp \u036f]/g, "").trim();
        return normalizedK === normalizedTarget || normalizedK.includes(normalizedTarget);
      });
      if (found) return found;
    }
    return targets[0];
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { defval: "" }) as any[];

        if (rows.length === 0) throw new Error("Planilha vazia");

        const firstRow = rows[0];
        const K = {
          MU: getActualKey(firstRow, ["Nº Pedido MU", "Pedido MU", "MU", "Pedido"]),
          DATA: getActualKey(firstRow, ["Data Faturamento", "Data", "Data Pedido"]),
          VENDEDOR: getActualKey(firstRow, ["Vendedor", "Nome Vendedor"]),
          TOTAL: getActualKey(firstRow, ["Total Pedido (R$)", "Total Pedido", "Valor Total", "Preco Total"]),
          CANAL: getActualKey(firstRow, ["Canal Venda", "Canal", "Tipo Venda", "Tipo de Pedido", "Origem"]),
          MARGEM_RS: getActualKey(firstRow, ["Margem líq. c/ frete", "Margem Liq", "Margem R$", "Margem Contribuicao"]),
          MARGEM_PCT: getActualKey(firstRow, ["Margem produto c/frete (%)", "Margem %", "Rentabilidade"]),
          MKT: getActualKey(firstRow, ["Mkt"]),
          CAC: getActualKey(firstRow, ["CAC"]),
          FRETE: getActualKey(firstRow, ["Frete", "Valor Frete"])
        };

        const multiMonthData: Record<string, Record<string, Pedido>> = {};

        for (let i = 0; i < rows.length; i++) {
          const r = rows[i];
          const rawMU = String(r[K.MU] || "").trim();

          if (rawMU && !rawMU.toUpperCase().includes("TOTAL")) {
            const currentMU = rawMU;
            const dateStr = excelDateToBR(r[K.DATA]);
            const monthKey = extractYearMonth(dateStr) || selectedMonth;
            let canalFinal = String(r[K.CANAL] || "").trim();

            if (!canalFinal && i + 1 < rows.length) {
              canalFinal = String(rows[i + 1][K.CANAL] || "").trim();
            }

            if (!multiMonthData[monthKey]) multiMonthData[monthKey] = {};

            multiMonthData[monthKey][currentMU] = {
              id: currentMU,
              data: dateStr,
              canal: canalFinal,
              vendedor: String(r[K.VENDEDOR] || "").trim(),
              mkt: toNumber(r[K.MKT]),
              cac: toNumber(r[K.CAC]),
              total: toNumber(r[K.TOTAL]),
              frete: toNumber(r[K.FRETE]),
              margemOriginal: toNumber(r[K.MARGEM_RS]),
              margemOriginalPct: toPercent(r[K.MARGEM_PCT]),
              credito: 0,
              debito: 0,
              isOcorrencia: false,
              margemDeduzidaCancelamento: 0,
              margemDeduzidaDevolucao: 0,
              margemAjustada: toNumber(r[K.MARGEM_RS]),
              confirmado: false,
              isDivergente: false
            };

            let j = i + 1;
            while (j < rows.length && !String(rows[j][K.MU] || "").trim()) {
              multiMonthData[monthKey][currentMU].mkt += toNumber(rows[j][K.MKT]);
              multiMonthData[monthKey][currentMU].cac += toNumber(rows[j][K.CAC]);
              j++;
            }
            i = j - 1;
          }
        }

        const monthsFound = Object.keys(multiMonthData);
        if (monthsFound.length === 0) throw new Error("Nenhum dado válido encontrado.");

        const formattedMultiMonth: Record<string, Pedido[]> = {};
        monthsFound.forEach(m => {
          formattedMultiMonth[m] = Object.values(multiMonthData[m]);
        });

        const firstMonth = monthsFound[0];
        onSetData({ 
          mesReferencia: firstMonth, 
          pedidos: formattedMultiMonth[firstMonth],
          ajustesExtras: []
        }, formattedMultiMonth);

        setSelectedMonth(firstMonth);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Erro ao processar arquivo.");
      } finally {
        setLoading(false);
        if (event.target) event.target.value = "";
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleComparisonUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !data) return;

    setLoading(true);
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const bstr = e.target?.result;
        const workbook = XLSX.read(bstr, { type: 'binary' });
        const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { defval: "" }) as any[];

        if (rows.length === 0) return;

        const firstRow = rows[0];
        const keyMU = getActualKey(firstRow, ["Nº Pedido MU", "Pedido MU", "MU", "Pedido"]);
        const keyTotal = getActualKey(firstRow, ["Total Pedido (R$)", "Total Pedido", "Valor Total", "Preco Total"]);

        const updatedPedidos = [...data.pedidos];
        let discrepancies = 0;

        rows.forEach(r => {
          const mu = String(r[keyMU] || "").trim();
          if (!mu) return;
          const valorApoio = toNumber(r[keyTotal]);

          const index = updatedPedidos.findIndex(p => p.id === mu);
          if (index !== -1) {
            const originalTotal = updatedPedidos[index].total;
            if (Math.abs(originalTotal - valorApoio) > 0.05) {
              updatedPedidos[index].isDivergente = true;
              updatedPedidos[index].valorApoio = valorApoio;
              discrepancies++;
            } else {
              updatedPedidos[index].isDivergente = false;
            }
          }
        });

        onSetData({ ...data, pedidos: updatedPedidos });
        alert(`Conferência Finalizada: ${discrepancies} divergências encontradas.`);
      } catch (err) {
        alert("Erro ao cruzar planilhas.");
      } finally {
        setLoading(false);
        if (event.target) event.target.value = "";
      }
    };
    reader.readAsBinaryString(file);
  };

  const summary = useMemo(() => {
    if (!data || data.pedidos.length === 0) return { total: 0, margem: 0, pct: 0, divergentes: 0 };
    const total = data.pedidos.reduce((acc, curr) => acc + (curr.isOcorrencia ? 0 : curr.total), 0);
    const margem = data.pedidos.reduce((acc, curr) => acc + curr.margemAjustada, 0);
    const pct = total > 0 ? (margem / total) * 100 : 0;
    const divergentes = data.pedidos.filter(p => p.isDivergente).length;
    return { total, margem, pct, divergentes };
  }, [data]);

  const formatCurrency = (value: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);

  return (
    <div className="space-y-12">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-slate-100">
        <div className="flex flex-col gap-2">
          <h2 className="text-5xl font-black text-slate-950 tracking-tighter">Vendas Base</h2>
          <div className="flex flex-wrap items-center gap-3">
            <p className="text-[#E30613] font-bold uppercase text-[11px] tracking-[0.3em]">Auditoria e Conciliação:</p>
            <div className="flex items-center gap-2 bg-white border border-slate-200 rounded-xl px-4 py-2 shadow-sm group">
               <Calendar className="w-4 h-4 text-[#E30613]" />
               <input 
                 type="month" 
                 value={selectedMonth} 
                 onChange={(e) => setSelectedMonth(e.target.value)} 
                 className="bg-transparent text-xs font-black uppercase text-slate-700 outline-none cursor-pointer" 
               />
            </div>
          </div>
        </div>
        <div className="flex flex-wrap items-center gap-4">
          {data && (
            <>
              <button onClick={onNavigateToOcorrencias} className="flex items-center gap-4 px-8 py-5 bg-white border-2 border-slate-200 hover:border-[#E30613] text-slate-600 rounded-2xl shadow-xl transition-all font-black text-sm uppercase tracking-wider">
                <RotateCcw className="w-5 h-5 text-red-500" /> OCORRÊNCIAS
              </button>
              <label className="flex items-center gap-4 px-8 py-5 bg-slate-50 border-2 border-slate-200 hover:bg-slate-100 text-slate-600 rounded-2xl cursor-pointer shadow-lg transition-all font-black text-[11px] uppercase tracking-wider">
                <FileSearch className="w-5 h-5 text-blue-600" />
                <span>2. CONFERIR (APOIO)</span>
                <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleComparisonUpload} />
              </label>
              <button onClick={onNavigateToAjustes} className="flex items-center gap-4 px-10 py-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl shadow-xl transition-all active:scale-95 font-black text-sm uppercase tracking-wider">
                <CheckCircle2 className="w-5 h-5" /> VALIDAR MÊS
              </button>
            </>
          )}
          <label className="flex items-center gap-4 px-10 py-5 bg-[#E30613] hover:bg-red-700 text-white rounded-2xl cursor-pointer shadow-2xl active:scale-95 font-black text-sm uppercase tracking-wider">
            <FileUp className="w-5 h-5" />
            <span>1. PLANILHA OFICIAL</span>
            <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
          </label>
        </div>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-100 p-4 rounded-2xl flex items-center gap-3 text-red-600 text-xs font-black uppercase tracking-widest">
          <AlertCircle className="w-5 h-5" /> {error}
        </div>
      )}

      {data && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 animate-in fade-in slide-in-from-top-4 duration-500">
          <div className="bg-[#0A1121] rounded-[2.5rem] p-8 text-white shadow-2xl">
            <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">Faturamento Líquido</span>
            <p className="text-3xl font-black tracking-tighter">{formatCurrency(summary.total)}</p>
          </div>
          <div className="bg-white border border-slate-200 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100">
            <span className="text-[9px] font-black uppercase tracking-widest text-slate-500">Margem R$ Auditada</span>
            <p className="text-3xl font-black tracking-tighter text-slate-900">{formatCurrency(summary.margem)}</p>
          </div>
          {summary.divergentes > 0 ? (
            <div className="bg-red-50 border border-red-100 rounded-[2.5rem] p-8 shadow-xl">
              <span className="text-[9px] font-black uppercase tracking-widest text-red-400">Pedidos Divergentes</span>
              <p className="text-3xl font-black tracking-tighter text-[#E30613]">{summary.divergentes}</p>
            </div>
          ) : (
            <div className="bg-emerald-50 border border-emerald-100 rounded-[2.5rem] p-8 shadow-xl">
              <span className="text-[9px] font-black uppercase tracking-widest text-emerald-400">Integridade de Dados</span>
              <p className="text-3xl font-black tracking-tighter text-emerald-600 flex items-center gap-2">
                 <ShieldCheck className="w-8 h-8" /> 100% OK
              </p>
            </div>
          )}
          <div className="bg-slate-50 border border-slate-200 rounded-[2.5rem] p-8 flex flex-col justify-center items-center text-center">
             <DatabaseBackup className="w-8 h-8 text-slate-300 mb-2" />
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Base Ativa</p>
             <p className="text-lg font-black text-slate-600">{data.pedidos.length} Registros</p>
          </div>
        </div>
      )}

      {loading ? (
        <div className="flex flex-col items-center py-64">
          <div className="w-12 h-12 border-4 border-slate-100 border-t-[#E30613] rounded-full animate-spin mb-8"></div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest animate-pulse">Cruzando bases de dados...</p>
        </div>
      ) : !data ? (
        <div className="bg-white border-2 border-dashed border-slate-200 rounded-[4rem] py-64 flex flex-col items-center justify-center text-slate-300">
          <FileSearch className="w-24 h-24 mb-10 opacity-20" />
          <p className="text-3xl font-black text-slate-800 tracking-tight text-center">Auditoria Comparativa</p>
          <p className="text-slate-400 font-medium mt-2">Suba a Planilha Oficial e a Planilha de Apoio para identificar erros.</p>
        </div>
      ) : (
        <div className="animate-in fade-in slide-in-from-bottom-6 duration-700">
          <OrderTable data={data.pedidos} onUpdatePedido={onUpdatePedido} onDeletePedido={onDeletePedido} />
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Sidebar } from './components/Sidebar';
import { ConferenciaPage } from './pages/ConferenciaPage';
import { CanceladosPage } from './pages/CanceladosPage';
import { DevolvidosPage } from './pages/DevolvidosPage';
import { OcorrenciasPage } from './pages/OcorrenciasPage';
import { AjustesVariosPage } from './pages/AjustesVariosPage';
import { AjustesFinaisPage } from './pages/AjustesFinaisPage';
import { DashboardPage } from './pages/DashboardPage';
import { AnaliseVendedorPage } from './pages/AnaliseVendedorPage';
import { ConfiguracaoPage } from './pages/ConfiguracaoPage';
import { ContasPagarPage } from './pages/ContasPagarPage';
import { FluxoCaixaPage } from './pages/FluxoCaixaPage';
import { DREPage } from './pages/DREPage';
import { ComissaoPage } from './pages/ComissaoPage';
import { FretePage } from './pages/FretePage';
import { HorasPage } from './pages/HorasPage';
import { PageId, MesConferencia, Pedido, HistoricoConsolidado } from './types';
import { Sparkles } from 'lucide-react';
import { storageService } from './services/storageService';

const App: React.FC = () => {
  const [activePage, setActivePage] = useState<PageId>('dashboard');
  const [data, setData] = useState<MesConferencia | null>(storageService.getData());
  const [history, setHistory] = useState<HistoricoConsolidado>(storageService.getHistory());
  const [showToast, setShowToast] = useState<{show: boolean, msg: string, type: 'success' | 'danger'}>({show: false, msg: '', type: 'success'});

  // LÓGICA DE CÁLCULO CENTRALIZADA - UNICA FONTE DE VERDADE
  const calculateMargemFinal = (p: Pedido): number => {
    const cred = parseFloat(String(p.credito || 0));
    const deb = parseFloat(String(p.debito || 0));
    const canc = Math.abs(parseFloat(String(p.margemDeduzidaCancelamento || 0)));
    const dev = Math.abs(parseFloat(String(p.margemDeduzidaDevolucao || 0)));

    return p.margemOriginal + cred - deb - canc - dev;
  };

  const handleUpdatePedido = useCallback((id: string, updates: Partial<Pedido>) => {
    setData(current => {
      if (!current) return null;
      const newPedidos = current.pedidos.map((p) => {
        if (p.id === id) {
          const updated = { ...p, ...updates };
          updated.margemAjustada = calculateMargemFinal(updated);
          return updated;
        }
        return p;
      });
      const updatedData = { ...current, pedidos: newPedidos };
      storageService.saveData(updatedData);
      return updatedData;
    });
  }, []);

  const handleSetData = (newData: MesConferencia | null, multiMonthData?: Record<string, Pedido[]>) => {
    if (multiMonthData) {
      Object.keys(multiMonthData).forEach(mesRef => {
        const pedidosMes = multiMonthData[mesRef].map(p => ({
          ...p,
          margemAjustada: calculateMargemFinal(p)
        }));
        storageService.saveToHistory({ mesReferencia: mesRef, pedidos: pedidosMes, ajustesExtras: [] });
      });
      setHistory(storageService.getHistory());
      setShowToast({show: true, msg: 'Dados processados com sucesso!', type: 'success'});
      setTimeout(() => setShowToast({show: false, msg: '', type: 'success'}), 4000);
      if (newData) { 
        newData.pedidos = newData.pedidos.map(p => ({ ...p, margemAjustada: calculateMargemFinal(p) }));
        setData(newData); 
        storageService.saveData(newData); 
      }
    } else if (newData) {
      newData.pedidos = newData.pedidos.map(p => ({ ...p, margemAjustada: calculateMargemFinal(p) }));
      storageService.saveData(newData);
      setData(newData);
    } else {
      storageService.clearData();
      setData(null);
    }
  };

  const handleCloseMonth = (consolidated: MesConferencia) => {
    storageService.saveToHistory(consolidated);
    storageService.clearData();
    localStorage.removeItem('abc_cancelados_log_v9');
    localStorage.removeItem('abc_devolvidos_log_v9');
    setData(null);
    setHistory(storageService.getHistory());
    setActivePage('dashboard');
    setShowToast({show: true, msg: 'Auditoria consolidada!', type: 'success'});
    setTimeout(() => setShowToast({show: false, msg: '', type: 'success'}), 4000);
  };

  const handleDeletePedido = (id: string) => {
    setData(current => {
      if (!current) return null;
      const newPedidos = current.pedidos.filter(p => p.id !== id);
      const updatedData = { ...current, pedidos: newPedidos };
      storageService.saveData(updatedData);
      return updatedData;
    });
  };

  const handleClearDatabase = () => {
    storageService.clearAll();
    localStorage.removeItem('abc_cancelados_log_v9');
    localStorage.removeItem('abc_devolvidos_log_v9');
    setData(null);
    setHistory({ meses: [] });
    setActivePage('dashboard');
    setShowToast({show: true, msg: 'Sistema resetado!', type: 'danger'});
    setTimeout(() => setShowToast({show: false, msg: '', type: 'success'}), 4000);
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex selection:bg-red-100 selection:text-red-900 antialiased">
      <Sidebar activePage={activePage} setActivePage={setActivePage} />
      <main className="flex-grow flex flex-col min-w-0">
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-40 flex items-center justify-between px-12">
          <div className="flex items-center gap-3">
            <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">ABC ITU — Gestão Comercial</p>
          </div>
          <div className="flex items-center gap-2 px-4 py-2 bg-slate-50 rounded-full border border-slate-100">
            <span className="text-[10px] font-black text-slate-500 uppercase">{history.meses.length} Meses na Base</span>
          </div>
        </header>

        {showToast.show && (
          <div className="fixed top-24 right-12 z-[250] animate-in slide-in-from-right-8 fade-in duration-500">
            <div className={`${showToast.type === 'success' ? 'bg-emerald-600' : 'bg-[#E30613]'} text-white px-8 py-5 rounded-3xl shadow-2xl flex items-center gap-4`}>
               <Sparkles className="w-5 h-5" />
               <p className="text-[10px] font-black uppercase">{showToast.msg}</p>
            </div>
          </div>
        )}

        <div className="p-8 lg:p-12">
          <div className="bg-white p-10 rounded-[4rem] shadow-xl border border-slate-200/50 min-h-[75vh]">
            {activePage === 'dashboard' && <DashboardPage history={history} />}
            {activePage === 'conferencia' && (
              <ConferenciaPage 
                data={data} 
                onSetData={handleSetData} 
                onUpdatePedido={handleUpdatePedido} 
                onDeletePedido={handleDeletePedido} 
                onNavigateToAjustes={() => setActivePage('ajustes')} 
                onNavigateToOcorrencias={() => setActivePage('ocorrencias')}
              />
            )}
            {activePage === 'cancelados' && <CanceladosPage data={data} onSetData={handleSetData} />}
            {activePage === 'devolvidos' && <DevolvidosPage data={data} onSetData={handleSetData} />}
            {activePage === 'ocorrencias' && <OcorrenciasPage data={data} onSetData={handleSetData} />}
            {activePage === 'ajustes-varios' && <AjustesVariosPage data={data} onSetData={handleSetData} />}
            {activePage === 'ajustes' && <AjustesFinaisPage data={data} onUpdatePedido={handleUpdatePedido} onDeletePedido={handleDeletePedido} onCloseMonth={handleCloseMonth} />}
            {activePage === 'analise-vendedor' && <AnaliseVendedorPage history={history} />}
            {activePage === 'contas-pagar' && <ContasPagarPage />}
            {activePage === 'fluxo-caixa' && <FluxoCaixaPage />}
            {activePage === 'dre' && <DREPage />}
            {activePage === 'comissao' && <ComissaoPage history={history} />}
            {activePage === 'frete' && <FretePage />}
            {activePage === 'horas' && <HorasPage />}
            {activePage === 'configuracao' && <ConfiguracaoPage onClearDatabase={handleClearDatabase} />}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Pedido, SortConfig, SortDirection } from '../types';
import { ChevronUp, ChevronDown, Check, Trash2, AlertTriangle, FileX, History, Share2, AlertOctagon, User, X, CheckCircle2, ShieldAlert } from 'lucide-react';

interface OrderTableProps {
  data: Pedido[];
  onUpdatePedido?: (id: string, updates: Partial<Pedido>) => void;
  onDeletePedido?: (id: string) => void;
  readOnly?: boolean;
}

export const OrderTable: React.FC<OrderTableProps> = ({ data, onUpdatePedido, onDeletePedido, readOnly = false }) => {
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'id', direction: 'asc' });
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [editingVendedor, setEditingVendedor] = useState<{id: string, nome: string} | null>(null);

  const listaVendedores = useMemo(() => {
    const nomes = new Set(data.map(p => p.vendedor).filter(v => v && v !== "." && v !== "SISTEMA"));
    return Array.from(nomes).sort();
  }, [data]);

  const handleSort = (key: keyof Pedido) => {
    let direction: SortDirection = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const sortedData = useMemo(() => {
    const sortableItems = [...data];
    if (sortConfig.direction !== null) {
      sortableItems.sort((a, b) => {
        const valA = a[sortConfig.key];
        const valB = b[sortConfig.key];
        if (valA === undefined || valA === null) return 1;
        if (valB === undefined || valB === null) return -1;
        if (typeof valA === 'string' && typeof valB === 'string') {
          return sortConfig.direction === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
        }
        if (typeof valA === 'number' && typeof valB === 'number') {
          return sortConfig.direction === 'asc' ? valA - valB : valB - valA;
        }
        return 0;
      });
    }
    return sortableItems;
  }, [data, sortConfig]);

  const totals = useMemo(() => {
    return data.reduce(
      (acc, curr) => {
        // Pedidos de ocorrência NÃO entram no faturamento bruto
        const valorFaturamento = curr.isOcorrencia ? 0 : (curr.total || 0);
        return {
          total: acc.total + valorFaturamento,
          margemOriginal: acc.margemOriginal + (curr.margemOriginal || 0),
          margemAjustada: acc.margemAjustada + (curr.margemAjustada || 0),
        };
      },
      { total: 0, margemOriginal: 0, margemAjustada: 0 }
    );
  }, [data]);

  const formatCurrency = (value: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  const formatPercent = (value: number) => new Intl.NumberFormat('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(value) + '%';

  const getMargemColor = (pct: number) => {
    if (pct <= 8.00) return 'text-[#E30613]';
    if (pct <= 10.00) return 'text-amber-500';
    return 'text-emerald-600';
  };

  const SortIcon = ({ column }: { column: keyof Pedido }) => {
    if (sortConfig.key !== column) return <ChevronDown className="w-3 h-3 text-slate-300 opacity-30" />;
    return sortConfig.direction === 'asc' ? <ChevronUp className="w-3 h-3 text-[#E30613]" /> : <ChevronDown className="w-3 h-3 text-[#E30613]" />;
  };

  return (
    <>
      {confirmDeleteId && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-950/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white rounded-[2.5rem] shadow-2xl max-w-md w-full p-10 space-y-8 border border-slate-200">
            <div className="flex flex-col items-center text-center space-y-4">
              <AlertTriangle className="w-10 h-10 text-[#E30613]" />
              <h3 className="text-2xl font-black text-slate-900 uppercase">Excluir Registro?</h3>
              <p className="text-slate-500 text-sm">Remover permanentemente <span className="font-black">MU {confirmDeleteId}</span>?</p>
            </div>
            <div className="flex flex-col gap-3">
              <button onClick={() => { onDeletePedido?.(confirmDeleteId); setConfirmDeleteId(null); }} className="w-full py-4 bg-[#E30613] text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl">Sim, Excluir</button>
              <button onClick={() => setConfirmDeleteId(null)} className="w-full py-4 bg-slate-100 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest">Cancelar</button>
            </div>
          </div>
        </div>
      )}

      <div className="bg-white rounded-[1.5rem] shadow-2xl border border-slate-200 overflow-hidden w-full">
        <div className="overflow-x-auto scrollbar-hide">
          <table className="w-full text-left text-[10px] border-collapse">
            <thead>
              <tr className="bg-[#0A1121] border-b border-slate-800">
                <th className="w-[45px] px-2 py-4 font-black text-slate-400 uppercase tracking-tighter text-center">Status</th>
                <th onClick={() => handleSort('id')} className="w-[100px] px-3 py-4 font-black text-slate-400 cursor-pointer hover:bg-slate-900 transition-colors uppercase tracking-tighter">
                   <div className="flex items-center justify-between">MU <SortIcon column="id" /></div>
                </th>
                <th className="w-[90px] px-2 py-4 font-black text-slate-400 uppercase tracking-tighter text-center">MU MESTRE</th>
                <th onClick={() => handleSort('data')} className="w-[85px] px-2 py-4 font-black text-slate-400 cursor-pointer hover:bg-slate-900 transition-colors uppercase tracking-tighter text-center">
                   <div className="flex items-center justify-center gap-1">DATA <SortIcon column="data" /></div>
                </th>
                <th onClick={() => handleSort('vendedor')} className="px-3 py-4 font-black text-slate-400 cursor-pointer hover:bg-slate-900 transition-colors uppercase tracking-tighter min-w-[180px]">
                   <div className="flex items-center justify-between">VENDEDOR <SortIcon column="vendedor" /></div>
                </th>
                <th onClick={() => handleSort('total')} className="w-[100px] px-2 py-4 font-black text-slate-400 cursor-pointer hover:bg-slate-900 transition-colors uppercase tracking-tighter text-right">
                   <div className="flex items-center justify-end gap-1">TOTAL <SortIcon column="total" /></div>
                </th>
                <th onClick={() => handleSort('margemOriginal')} className="w-[100px] px-2 py-4 font-black text-slate-400 cursor-pointer hover:bg-slate-900 transition-colors uppercase tracking-tighter text-right">
                   <div className="flex items-center justify-end gap-1">MARGEM <SortIcon column="margemOriginal" /></div>
                </th>
                <th onClick={() => handleSort('margemOriginalPct')} className="w-[70px] px-2 py-4 font-black text-slate-400 cursor-pointer hover:bg-slate-900 transition-colors uppercase tracking-tighter text-right">
                   <div className="flex items-center justify-end gap-1">% <SortIcon column="margemOriginalPct" /></div>
                </th>
                <th className="w-[60px] px-2 py-4 font-black text-slate-400 uppercase tracking-tighter text-center">CONF.</th>
                <th className="w-[75px] px-2 py-4 font-black text-slate-400 uppercase tracking-tighter text-center">CRÉD.</th>
                <th className="w-[75px] px-2 py-4 font-black text-slate-400 uppercase tracking-tighter text-center">DÉB.</th>
                <th onClick={() => handleSort('margemAjustada')} className="w-[115px] px-3 py-4 font-black text-slate-700 uppercase tracking-tighter bg-slate-50 text-right cursor-pointer hover:bg-slate-100 transition-colors">
                   <div className="flex items-center justify-end gap-1">AJUSTADA <SortIcon column="margemAjustada" /></div>
                </th>
                <th className="w-[80px] px-3 py-4 font-black text-slate-700 text-right uppercase tracking-tighter bg-slate-100/50">FINAL %</th>
                <th className="w-[50px] px-2 py-4 font-black text-slate-400 text-center uppercase tracking-tighter">AÇÕES</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {sortedData.map((p) => {
                const isRetroativo = p.data.includes("Anterior") || p.vendedor.includes("SISTEMA");
                const margemAjustadaPct = p.total > 0 ? (p.margemAjustada / p.total) * 100 : 0;

                return (
                  <tr key={p.id} className={`${p.isDivergente ? 'bg-red-50/50' : p.isOcorrencia ? 'bg-amber-50/60' : isRetroativo ? 'bg-emerald-50/20' : p.isCancelado ? 'bg-red-50/30' : 'bg-white'} hover:bg-slate-50/80 transition-all`}>
                    <td className="px-2 py-2.5 text-center">
                       {p.isDivergente ? (
                         <div title={`Divergência: Planilha apoio diz ${formatCurrency(p.valorApoio || 0)}`} className="inline-flex items-center justify-center p-1.5 bg-red-100 text-red-600 rounded-lg animate-pulse">
                            <ShieldAlert className="w-3.5 h-3.5" />
                         </div>
                       ) : (
                         <button 
                           title={p.isOcorrencia ? "Pedido de Reposição (Não conta no faturamento)" : "Venda Normal (Clique para marcar como Ocorrência)"}
                           onClick={() => !readOnly && onUpdatePedido?.(p.id, { isOcorrencia: !p.isOcorrencia })}
                           className={`p-1.5 rounded-lg transition-all active:scale-90 ${p.isOcorrencia ? 'bg-amber-500 text-white shadow-lg' : 'bg-slate-100 text-slate-300 hover:bg-amber-100 hover:text-amber-500'}`}
                         >
                            {p.isOcorrencia ? <AlertOctagon className="w-3.5 h-3.5" /> : <CheckCircle2 className="w-3.5 h-3.5 opacity-30" />}
                         </button>
                       )}
                    </td>
                    <td className="px-3 py-2.5 text-slate-900 font-black">
                       <div className="flex items-center gap-1">
                          {p.id}
                          {isRetroativo && <History className="w-2.5 h-2.5 text-emerald-600 shrink-0" />}
                          {p.isCancelado && <FileX className="w-2.5 h-2.5 text-[#E30613] shrink-0" />}
                       </div>
                    </td>
                    <td className="px-2 py-2.5 text-center">
                       <div className="relative">
                          <input 
                            type="text" 
                            placeholder="Mestre..."
                            value={p.idPedidoMestre || ''}
                            onChange={(e) => onUpdatePedido?.(p.id, { idPedidoMestre: e.target.value })}
                            className="w-full bg-transparent border-b border-slate-200 text-center font-black text-[9px] focus:border-[#E30613] outline-none placeholder:opacity-30"
                          />
                       </div>
                    </td>
                    <td className={`px-2 py-2.5 font-black text-center ${isRetroativo ? 'text-emerald-600' : 'text-slate-500'}`}>{p.data}</td>
                    <td className="px-3 py-2.5 text-slate-600 uppercase font-bold group/vend">
                       <div className="flex items-center gap-2">
                          {editingVendedor?.id === p.id ? (
                            <div className="flex items-center gap-1 w-full animate-in zoom-in-95 duration-200">
                               <select 
                                 value={editingVendedor.nome} 
                                 onChange={(e) => setEditingVendedor({...editingVendedor, nome: e.target.value})}
                                 className="w-full bg-white border-2 border-[#E30613] rounded-lg px-2 py-1 text-[10px] font-black outline-none shadow-inner"
                                 autoFocus
                               >
                                  <option value="">SELECIONE VENDEDOR</option>
                                  {listaVendedores.map(nome => <option key={nome} value={nome}>{nome}</option>)}
                               </select>
                               <button onClick={() => { onUpdatePedido?.(p.id, { vendedor: editingVendedor.nome }); setEditingVendedor(null); }} className="p-1.5 bg-emerald-500 text-white rounded-lg shadow-md hover:bg-emerald-600 transition-colors">
                                 <Check className="w-3 h-3" />
                               </button>
                               <button onClick={() => setEditingVendedor(null)} className="p-1.5 bg-slate-200 text-slate-500 rounded-lg"><X className="w-3 h-3"/></button>
                            </div>
                          ) : (
                            <>
                              <span className="flex-1 leading-tight">{p.vendedor || "."}</span>
                              {!readOnly && (
                                <button onClick={() => setEditingVendedor({id: p.id, nome: p.vendedor})} className="p-1.5 text-slate-300 hover:text-[#E30613] hover:bg-white rounded-lg transition-all opacity-0 group-hover/vend:opacity-100 shadow-sm border border-transparent hover:border-slate-100">
                                  <User className="w-3 h-3" />
                                </button>
                              )}
                            </>
                          )}
                       </div>
                    </td>
                    <td className={`px-2 py-2.5 font-black text-right ${p.isOcorrencia ? 'text-slate-400 line-through opacity-50' : 'text-slate-900'}`}>{formatCurrency(p.total || 0)}</td>
                    <td className="px-2 py-2.5 text-slate-400 italic text-right">{formatCurrency(p.margemOriginal || 0)}</td>
                    <td className="px-2 py-2.5 text-slate-400 italic text-right">{formatPercent(p.margemOriginalPct || 0)}</td>

                    <td className="px-2 py-2.5 text-center">
                       <button onClick={() => onUpdatePedido?.(p.id, { confirmado: !p.confirmado })} className={`p-1.5 rounded-full border transition-all ${p.confirmado ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-white border-slate-200 text-slate-200 hover:text-emerald-500'}`}>
                          <Check className="w-3 h-3" />
                       </button>
                    </td>

                    <td className="px-2 py-2.5 text-center">
                        <input 
                          type="number" step="0.01" value={p.credito || ''} 
                          onChange={(e) => onUpdatePedido?.(p.id, { credito: parseFloat(e.target.value) || 0 })} 
                          className={`w-14 px-1 py-0.5 border rounded-lg text-right font-black outline-none text-[9px] transition-all ${p.credito > 0 ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-white border-slate-200'}`} 
                        />
                    </td>
                    <td className="px-2 py-2.5 text-center">
                        <input 
                          type="number" step="0.01" value={p.debito || ''} 
                          onChange={(e) => onUpdatePedido?.(p.id, { debito: parseFloat(e.target.value) || 0 })} 
                          className={`w-14 px-1 py-0.5 border rounded-lg text-right font-black outline-none text-[9px] transition-all ${p.debito > 0 ? 'bg-red-50 border-red-200 text-red-700' : 'bg-white border-slate-200'}`} 
                        />
                    </td>

                    <td className="px-3 py-2.5 font-black text-slate-900 bg-slate-50/50 text-right">{formatCurrency(p.margemAjustada)}</td>
                    <td className={`px-3 py-2.5 font-black text-right bg-slate-100/20 ${getMargemColor(margemAjustadaPct)}`}>
                      {isRetroativo ? '---' : formatPercent(margemAjustadaPct)}
                    </td>

                    <td className="px-2 py-2.5 text-center">
                      {!readOnly && <button onClick={() => setConfirmDeleteId(p.id)} className="p-1.5 text-slate-300 hover:text-[#E30613] hover:bg-red-50 rounded-lg transition-all"><Trash2 className="w-3.5 h-3.5" /></button>}
                    </td>
                  </tr>
                );
              })}
            </tbody>
            <tfoot className="bg-[#0A1121] text-white sticky bottom-0 z-30 shadow-[0_-4px_10px_rgba(0,0,0,0.2)]">
              <tr className="border-t border-slate-800">
                <td colSpan={5} className="px-4 py-4 text-right font-black text-[9px] uppercase tracking-[0.2em] text-slate-400">RESUMO AUDITORIA:</td>
                <td className="px-2 py-4 font-black text-right text-sm">{formatCurrency(totals.total)}</td>
                <td className="px-2 py-4 font-bold text-slate-500 italic text-right text-xs opacity-60">{formatCurrency(totals.margemOriginal)}</td>
                <td className="px-2 py-4 font-bold text-slate-500 italic text-right text-xs opacity-60">
                   {(totals.total > 0 ? (totals.margemOriginal / totals.total) * 100 : 0).toFixed(2)}%
                </td>
                <td colSpan={3}></td>
                <td className="px-3 py-4 font-black text-right bg-slate-800/80 text-lg border-l border-slate-700">{formatCurrency(totals.margemAjustada)}</td>
                <td className={`px-3 py-4 font-black text-right text-lg bg-slate-900 ${getMargemColor(totals.total > 0 ? (totals.margemAjustada / totals.total) * 100 : 0)}`}>
                  {formatPercent(totals.total > 0 ? (totals.margemAjustada / totals.total) * 100 : 0)}
                </td>
                <td className="bg-slate-900"></td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
    </>
  );
};
